    driver: *evaluator.Driver,
};

fn same(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}
fn operation(comptime T: type, a: std.mem.Allocator, value: T) !state.Digest {
    const bytes = try contracts.encodeOwned(T, a, value);
    defer a.free(bytes);
    var hash = std.crypto.hash.sha2.Sha256.init(.{});
    hash.update("agent.native.operation.v1\x00");
    hash.update(bytes);
    var result: state.Digest = undefined;
    hash.final(&result);
    return result;
}
fn name(bytes: []const u8) !state.Name {
    if (bytes.len == 0 or bytes.len > 128 or !std.unicode.utf8ValidateSlice(
        bytes,
    )) return error.InvalidParams;
    return .{ .bytes = bytes };
}
fn answerDigest(
    a: std.mem.Allocator,
    task_id: state.TaskId,
    question_id: state.Digest,
    revision: u64,
    request_digest: state.Digest,
    schema_id: []const u8,
    answer: []const u8,
) !state.Digest {
    const Request = struct {
        method: state.Method,
        task: state.TaskId,
        question: state.Digest,
        revision: u64,
        request: state.Digest,
        schema: state.Name,
        answer: contracts.Bytes(null),
    };
    return operation(
        Request,
        a,
        .{
            .method = .respond,
            .task = task_id,
            .question = question_id,
            .revision = revision,
            .request = request_digest,
            .schema = try name(schema_id),
            .answer = .{ .bytes = answer },
        },
    );
}

fn cancelDigest(a: std.mem.Allocator, task_id: state.TaskId, reason: state.Reason) !state.Digest {
    const Request = struct { method: state.Method, task: state.TaskId, reason: state.Reason };
    return operation(Request, a, .{ .method = .cancel, .task = task_id, .reason = reason });
}

fn reconcileDigest(
    a: std.mem.Allocator,
    task_id: state.TaskId,
    expected: u64,
    occurrence_id: state.Digest,
    attempt_id: state.Digest,
    recovery: state.RecoveryRequest,
) !state.Digest {
    const Request = struct {
        method: state.Method,
        task: state.TaskId,
        revision: u64,
        occurrence: state.Digest,
        attempt: state.Digest,
        recovery: state.RecoveryRequest,
    };
    return operation(Request, a, .{
        .method = .reconcile,
        .task = task_id,
        .revision = expected,
        .occurrence = occurrence_id,
        .attempt = attempt_id,
        .recovery = recovery,
    });
}

