pub fn Service(comptime Types: type) type {
    return struct {
        const Self = @This();
        allocator: std.mem.Allocator,
        io: std.Io,
        namespace: *Namespace,
        assets: discovery.Assets,
        application: *const discovery.Application,
        handlers: registry.Registry,
        profile: Profile,
        program: *evaluator.Program,
        active: ?Active = null,
        /// Only this process's explicit admissions/resumes are runnable. Merely
        /// opening a namespace never resumes a persisted task.
        runnable: std.ArrayList(workspace.Subject) = .empty,
        /// Logical queue order is items[cursor..] followed by items[0..cursor].
        /// Advancing a turn must not move every remaining ID.
        runnable_cursor: usize = 0,
        /// Unsettled cleanup retains ownership, but never runnable work.
        owned: std.ArrayList(state.TaskId) = .empty,
        cleanup_cursor: usize = 0,
        shutdown_cancel_requested: bool = false,
        remote_stopped_parent: ?state.TaskId = null,
        owner_epoch: state.Digest = undefined,
        work: ?Work = null,
        placement_pending: std.ArrayList(PlacementPending) = .empty,
        placement_job: ?PlacementJob = null,
        checked_workspace_programs: std.AutoHashMapUnmanaged(state.Digest, u64) = .empty,
        checked_workspace_runtimes: std.AutoHashMapUnmanaged(CompilerFact, u64) = .empty,
        runtime_cache: ?RuntimeCache = null,
        compiler_facts: ?*CompilerFacts = null,
        // Import may use ordinary mutation projections only through an existing
        // matching receipt. Missing receipts must never execute a new mutation.
        workspace_replay: ?struct {
            replayed: bool,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        } = null,
        pub const CompilerFacts = compilerFactsType();
        fn compilerFactsType() type {
            return struct {
                allocator: std.mem.Allocator,
                entries: std.AutoHashMapUnmanaged(CompilerFact, void) = .empty,
                sources: std.AutoHashMapUnmanaged(state.Digest, []u8) = .empty,
                values: std.AutoHashMapUnmanaged(state.Digest, construction.SemanticValue) = .empty,

                pub fn deinit(facts: *@This()) void {
                    var sources = facts.sources.valueIterator();
                    while (sources.next()) |bytes| facts.allocator.free(bytes.*);
                    facts.sources.deinit(facts.allocator);
                    var semantic_values = facts.values.valueIterator();
                    while (semantic_values.next()) |value| {
                        facts.allocator.free(value.schema);
                        facts.allocator.free(value.value);
                    }
                    facts.values.deinit(facts.allocator);
                    facts.entries.deinit(facts.allocator);
                }
            };
        }
        fn semanticRenderingKey(
            a: std.mem.Allocator,
            runtime: *const kosmos.RuntimeArtifact,
            selection: SemanticRendering,
        ) !state.Digest {
            const runtime_bytes = try runtime.encode(a);
            defer a.free(runtime_bytes);
            const Key = struct { runtime: state.Reference, selection: SemanticRendering };
            const bytes = try contracts.encodeOwned(Key, a, .{
                .runtime = compilerReference(runtime_bytes),
                .selection = selection,
            });
            defer a.free(bytes);
            return storage.digest(bytes);
        }
        fn renderSemanticSource(
            self: *Self,
            a: std.mem.Allocator,
            runtime: *const kosmos.RuntimeArtifact,
            guest: state.Reference,
            section: wc.SemanticSection,
            page: wc.Page,
        ) !json.Value {
            const key = try semanticRenderingKey(a, runtime, .{ .source = .{
                .guest = guest,
                .section = section,
                .page = page,
            } });
            if (self.compiler_facts) |facts| if (facts.sources.get(key)) |bytes| {
                return std.json.parseFromSliceLeaky(json.Value, a, bytes, .{
                    .allocate = .alloc_always,
                    .parse_numbers = false,
                });
            };
            if (self.store().transaction) return error.CompilerPreparationRequired;
            const result = try construction.semanticSource(a, runtime, guest, section, page);
            if (self.compiler_facts) |facts| {
                const bytes = try json.canonical(facts.allocator, result);
                errdefer facts.allocator.free(bytes);
                try facts.sources.put(facts.allocator, key, bytes);
            }
            return result;
        }
        fn renderConsumer(
            self: *Self,
            a: std.mem.Allocator,
            bytes: []const u8,
            derived: bool,
            site: @import("horos").source.consumer.Site,
            page: wc.Page,
        ) !json.Value {
            const Key = struct {
                contract: contracts.Utf8,
                source: state.Reference,
                derived: bool,
                site: @import("horos").source.consumer.Site,
                page: wc.Page,
            };
            const key_bytes = try contracts.encodeOwned(Key, a, .{
                .contract = .{ .bytes = "protean-consumer-inspection/1" },
                .source = compilerReference(bytes),
                .derived = derived,
                .site = site,
                .page = page,
            });
            defer a.free(key_bytes);
            const key = storage.digest(key_bytes);
            if (self.compiler_facts) |facts| if (facts.sources.get(key)) |cached|
                return std.json.parseFromSliceLeaky(json.Value, a, cached, .{
                    .allocate = .alloc_always,
                    .parse_numbers = false,
                });
            if (self.store().transaction) return error.CompilerPreparationRequired;
            const result = try construction.inspectConsumer(a, bytes, derived, site, page);
            if (self.compiler_facts) |facts| {
                const rendered = try json.canonical(facts.allocator, result);
                errdefer facts.allocator.free(rendered);
                try facts.sources.put(facts.allocator, key, rendered);
            }
            return result;
        }
        fn renderSemanticValue(
            self: *Self,
            a: std.mem.Allocator,
            runtime: *const kosmos.RuntimeArtifact,
            module: wc.SemanticModule,
            references: bool,
        ) !construction.SemanticValue {
            const key = try semanticRenderingKey(a, runtime, .{ .value = .{
                .module = module,
                .references = references,
            } });
            if (self.compiler_facts) |facts| if (facts.values.get(key)) |value| {
                const schema = try a.dupe(u8, value.schema);
                errdefer a.free(schema);
                return .{ .schema = schema, .value = try a.dupe(u8, value.value) };
            };
            if (self.store().transaction) return error.CompilerPreparationRequired;
            const result = try construction.semanticModuleValue(a, runtime, module, references);
            errdefer {
                a.free(result.schema);
                a.free(result.value);
            }
            if (self.compiler_facts) |facts| {
                const schema = try facts.allocator.dupe(u8, result.schema);
                errdefer facts.allocator.free(schema);
                const value = try facts.allocator.dupe(u8, result.value);
                errdefer facts.allocator.free(value);
                try facts.values.put(facts.allocator, key, .{ .schema = schema, .value = value });
            }
            return result;
        }
        fn compilerFact(self: *Self, fact: CompilerFact) !bool {
            if (self.compiler_facts) |facts| if (facts.entries.contains(fact)) return true;
            if (self.store().transaction) return error.CompilerPreparationRequired;
            return false;
        }
        fn retainCompilerFact(self: *Self, fact: CompilerFact) !void {
            if (self.compiler_facts) |facts| try facts.entries.put(facts.allocator, fact, {});
        }
        fn compilerReference(bytes: []const u8) state.Reference {
            return .{ .digest = storage.digest(bytes), .bytes = bytes.len };
        }
        fn prepareSemanticRead(
            self: *Self,
            a: std.mem.Allocator,
            manifest: state.Archive,
            source: anytype,
            parent: state.Task,
            selection: @FieldType(wc.InspectionTarget, "semantic_source"),
            page: wc.Page,
            basis: workspace.ReadObservation,
        ) !void {
            const subject = switch (selection.subject) {
                .runtime => |selected| try semanticRuntimeSubject(
                    a,
                    manifest,
                    source,
                    parent,
                    selected,
                ),
                .work => try semanticWorkSubject(a, manifest, source, parent, basis),
                .controller => try semanticControllerSubject(a, manifest, source, parent, basis),
            };
            var admitted = if (subject.runtime) |ref|
                try kosmos.RuntimeArtifact.init(a, try source.object(a, ref, null), ref.digest)
            else
                try self.program.retainRuntime();
            defer admitted.deinit();
            _ = try self.renderSemanticSource(a, &admitted, subject.guest, selection.section, page);
        }
        fn semanticRuntimeSubject(
            a: std.mem.Allocator,
            manifest: state.Archive,
            source: anytype,
            parent: state.Task,
            selected: anytype,
        ) !SemanticReadSubject {
            var runtime: ?state.Reference = null;
            var guest: state.Reference = undefined;

            const key = try workspace.custodyId(
                a,
                parent.id,
                try wp.identity(selected, .runtime),
            );
            const ref = archive_api.record(
                manifest,
                .workspace_runtime,
                key,
            ) orelse return error.InvalidArchive;
            var saved = try contracts.decodeOwned(
                workspace.Runtime,
                a,
                try source.object(a, ref, null),
            );
            defer saved.deinit();
            runtime = saved.value.artifact;
            const program_key = try workspace.custodyId(a, parent.id, saved.value.program);
            const program_ref = archive_api.record(
                manifest,
                .workspace_program,
                program_key,
            ) orelse return error.InvalidArchive;
            var program = try contracts.decodeOwned(
                workspace.Program,
                a,
                try source.object(a, program_ref, null),
            );
            defer program.deinit();
            guest = program.value.description.image;

            return .{ .runtime = runtime, .guest = guest };
        }
        fn semanticWorkSubject(
            a: std.mem.Allocator,
            manifest: state.Archive,
            source: anytype,
            parent: state.Task,
            basis: workspace.ReadObservation,
        ) !SemanticReadSubject {
            var runtime: ?state.Reference = null;
            var guest: state.Reference = undefined;

            if (basis != .works or
                basis.works.works.items.len == 0)
                return error.InvalidArchive;
            const observed = basis.works.works.items[0] orelse return error.InvalidArchive;
            runtime = observed.work.runtime;
            const key = try workspace.custodyId(a, parent.id, observed.work.program);
            const ref = archive_api.record(
                manifest,
                .workspace_program,
                key,
            ) orelse return error.InvalidArchive;
            var program = try contracts.decodeOwned(
                workspace.Program,
                a,
                try source.object(a, ref, null),
            );
            defer program.deinit();
            guest = program.value.description.image;

            return .{ .runtime = runtime, .guest = guest };
        }
        fn semanticControllerSubject(
            a: std.mem.Allocator,
            manifest: state.Archive,
            source: anytype,
            parent: state.Task,
            basis: workspace.ReadObservation,
        ) !SemanticReadSubject {
            var runtime: ?state.Reference = null;
            var guest: state.Reference = undefined;

            if (basis != .controller) return error.InvalidArchive;
            runtime = basis.controller.runtime;
            guest = parent.image;
            if (basis.controller.binding) |id| {
                const ref = archive_api.record(
                    manifest,
                    .controller_binding,
                    id,
                ) orelse return error.InvalidArchive;
                var binding = try contracts.decodeOwned(
                    state.ControllerBinding,
                    a,
                    try source.object(a, ref, null),
                );
                defer binding.deinit();
                guest = binding.value.image;
            }

            return .{ .runtime = runtime, .guest = guest };
        }
        fn prepareSemanticRenderings(self: *Self, manifest: state.Archive, source: anytype) !void {
            for (manifest.records.items) |row| {
                try self.prepareSemanticRenderingRow(manifest, source, row);
            }
        }
        fn prepareSemanticRenderingRow(
            self: *Self,
            manifest: state.Archive,
            source: anytype,
            row: state.ArchiveRecord,
        ) !void {
            if (row.kind != .workspace_value and row.kind != .workspace_reply) return;
            var arena = std.heap.ArenaAllocator.init(self.allocator);
            defer arena.deinit();
            const a = arena.allocator();
            const bytes = try source.object(a, row.body, null);
            if (row.kind == .workspace_value) {
                return self.prepareSemanticValueRendering(a, source, bytes);
            }

            try self.prepareSemanticReplyRendering(a, manifest, source, bytes);
        }
        fn prepareSemanticValueRendering(
            self: *Self,
            a: std.mem.Allocator,
            source: anytype,
            bytes: []const u8,
        ) !void {
            var saved = try contracts.decodeOwned(workspace.Value, a, bytes);
            defer saved.deinit();
            const origin = saved.value.derivation.semantic_source orelse return;
            var admitted = try kosmos.RuntimeArtifact.init(
                a,
                try source.object(a, origin.runtime, null),
                origin.runtime.digest,
            );
            defer admitted.deinit();
            const rendered = try self.renderSemanticValue(
                a,
                &admitted,
                origin.selection.module,
                origin.selection.references,
            );
            a.free(rendered.schema);
            a.free(rendered.value);
            return;
        }
        fn prepareSemanticReplyRendering(
            self: *Self,
            a: std.mem.Allocator,
            manifest: state.Archive,
            source: anytype,
            bytes: []const u8,
        ) !void {
            var saved = try contracts.decodeOwned(workspace.ReplyObservation, a, bytes);
            defer saved.deinit();
            if (saved.value.evidence != .read) return;
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                try source.object(a, saved.value.request, null),
            );
            defer request.deinit();
            const entry = try self.handlers.resolve(
                request.value,
                request.value.binding.program_identity,
            );
            const authorize = entry.declaration.workspace orelse return error.InvalidArchive;
            var parent = try contracts.decodeOwned(
                state.Task,
                a,
                try source.object(a, manifest.task, null),
            );
            defer parent.deinit();
            const read = struct {
                fn object(
                    context: *anyopaque,
                    allocator: std.mem.Allocator,
                    ref: state.Reference,
                    limit: usize,
                ) ![]u8 {
                    const selected: @TypeOf(source) = @ptrCast(@alignCast(context));
                    return selected.object(allocator, ref, limit);
                }
            }.object;
            const authorized_bytes = try authorize(.{
                .allocator = a,
                .task = parent.value.id,
                .tenant = parent.value.tenant.bytes,
                .profile = self.profile.bytes,
                .application = self.application.image_identity,
                .resources = parent.value.resources.items,
                .objects = .validating(source, read),
            }, request.value.binding.payload);
            var authorized = try contracts.decodeOwned(
                workspace.Authorized,
                a,
                authorized_bytes,
            );
            defer authorized.deinit();
            const command = authorized.value.command;
            if (command != .program or command.program != .inspect) return;
            const inspected = command.program.inspect;
            if (inspected.target == .semantic_source) {
                try self.prepareSemanticRead(
                    a,
                    manifest,
                    source,
                    parent.value,
                    inspected.target.semantic_source,
                    inspected.page,
                    saved.value.evidence.read,
                );
            } else if (inspected.target == .consumer) {
                try self.prepareConsumerRendering(a, manifest, source, parent.value, inspected);
            }
        }
        fn prepareConsumerRendering(
            self: *Self,
            a: std.mem.Allocator,
            manifest: state.Archive,
            source: anytype,
            parent: state.Task,
            inspected: @FieldType(wc.Program, "inspect"),
        ) !void {
            const selected = inspected.target.consumer;
            const key = try workspace.custodyId(
                a,
                parent.id,
                try wp.identity(selected.program, .program),
            );
            const ref = archive_api.record(
                manifest,
                .workspace_program,
                key,
            ) orelse return error.InvalidArchive;
            var program = try contracts.decodeOwned(
                workspace.Program,
                a,
                try source.object(a, ref, null),
            );
            defer program.deinit();
            const artifact = program.value.description;
            if (artifact.source_kind != .source_records and
                artifact.source_kind != .source_derivation)
                return error.UnsupportedSource;
            _ = try self.renderConsumer(a, try source.object(
                a,
                artifact.source,
                null,
            ), artifact.source_kind == .source_derivation, .{
                .function = selected.function,
                .binding = selected.binding,
            }, inspected.page);
        }
        fn prepareCompilerFacts(self: *Self, manifest: state.Archive, source: anytype) !void {
            if (self.store().transaction or self.compiler_facts == null) return error.InvalidState;
            try self.validateArchiveRuntimePolicies(manifest, source);
            try self.prepareArchiveCompilerEvents(manifest, source);
            try self.prepareArchiveCompilerCaptures(manifest, source);
            try self.prepareArchiveCompilerRecords(manifest, source);
            try self.prepareSemanticRenderings(manifest, source);
        }
        fn validateArchiveRuntimePolicies(
            self: *Self,
            manifest: state.Archive,
            source: anytype,
        ) !void {
            for (manifest.records.items) |row| {
                if (row.kind != .workspace_runtime) continue;
                var arena = std.heap.ArenaAllocator.init(self.allocator);
                defer arena.deinit();
                const a = arena.allocator();
                var saved = try contracts.decodeOwned(
                    workspace.Runtime,
                    a,
                    try source.object(a, row.body, null),
                );
                defer saved.deinit();
                if (saved.value.validation) |validation| try self.requireSemanticPolicy(
                    validation.root,
                    validation.checker.bytes,
                );
            }
        }
        fn prepareArchiveCompilerEvents(
            self: *Self,
            manifest: state.Archive,
            source: anytype,
        ) !void {
            for (manifest.events.items) |row| {
                var arena = std.heap.ArenaAllocator.init(self.allocator);
                defer arena.deinit();
                const a = arena.allocator();
                var event_value = try contracts.decodeOwned(
                    state.Event,
                    a,
                    try source.object(a, row.body, null),
                );
                defer event_value.deinit();
                const reference = event_value.value.workspace_command orelse continue;
                var command = try contracts.decodeOwned(
                    workspace.PublicationCommand,
                    a,
                    try source.object(a, reference, null),
                );
                defer command.deinit();
                if (command.value != .semantic) continue;
                const selected = command.value.semantic;
                try self.validateCompilerOutput(
                    event_value.value.task,
                    try source.object(a, selected.input, null),
                    try source.object(a, selected.output, null),
                );
            }
        }
        fn prepareArchiveCompilerCaptures(
            self: *Self,
            manifest: state.Archive,
            source: anytype,
        ) !void {
            for (manifest.records.items) |row| {
                if (row.kind != .capture) continue;
                var arena = std.heap.ArenaAllocator.init(self.allocator);
                defer arena.deinit();
                const a = arena.allocator();
                var captured = try contracts.decodeOwned(
                    state.Capture,
                    a,
                    try source.object(a, row.body, null),
                );
                defer captured.deinit();
                const output = captured.value.response orelse continue;
                const attempt_ref = archive_api.record(
                    manifest,
                    .attempt,
                    row.id,
                ) orelse return error.InvalidArchive;
                var attempt = try contracts.decodeOwned(
                    state.Attempt,
                    a,
                    try source.object(a, attempt_ref, null),
                );
                defer attempt.deinit();
                if (attempt.value.operation != .workspace_build) continue;
                try self.validateCompilerOutput(
                    attempt.value.task,
                    try source.object(a, captured.value.request, null),
                    try source.object(a, output, null),
                );
            }
        }
        fn prepareArchiveCompilerRecords(
            self: *Self,
            manifest: state.Archive,
            source: anytype,
        ) !void {
            for (manifest.records.items) |row| {
                if (row.kind != .workspace_program and
                    row.kind != .workspace_candidate and
                    row.kind != .workspace_runtime)
                    continue;
                var arena = std.heap.ArenaAllocator.init(self.allocator);
                defer arena.deinit();
                const a = arena.allocator();
                const bytes = try source.object(a, row.body, null);
                switch (row.kind) {
                    .workspace_program => {
                        var saved = try contracts.decodeOwned(workspace.Program, a, bytes);
                        defer saved.deinit();
                        if (comptime @TypeOf(source) == *storage.Store) {
                            if (self.checked_workspace_programs.get(
                                saved.value.artifact.digest,
                            ) == self.store().integrity_epoch) continue;
                        }
                        try self.validateProgramCompiler(a, saved.value, source);
                    },
                    .workspace_candidate => {
                        var saved = try contracts.decodeOwned(workspace.Candidate, a, bytes);
                        defer saved.deinit();
                        try self.validateCandidateCompiler(a, saved.value, source);
                    },
                    .workspace_runtime => {
                        var saved = try contracts.decodeOwned(workspace.Runtime, a, bytes);
                        defer saved.deinit();
                        if (comptime @TypeOf(source) == *storage.Store) {
                            if (self.checked_workspace_runtimes.get(
                                try runtimeCompilerFact(
                                    a,
                                    saved.value.artifact,
                                    saved.value.validation,
                                ),
                            ) == self.store().integrity_epoch) continue;
                        }
                        const code = try source.object(a, saved.value.artifact, null);
                        var admitted = try kosmos.RuntimeArtifact.init(
                            a,
                            code,
                            saved.value.artifact.digest,
                        );
                        defer admitted.deinit();
                        try self.validateRuntimeCompiler(
                            a,
                            saved.value.artifact,
                            saved.value.validation,
                            &admitted,
                            source,
                        );
                    },
                    else => unreachable,
                }
            }
        }
        pub fn init(
            a: std.mem.Allocator,
            io: std.Io,
            namespace: *Namespace,
            assets: discovery.Assets,
            application: *const discovery.Application,
            handlers: registry.Registry,
            profile: Profile,
        ) !Self {
            try profile.validate();
            var self: Self = .{
                .allocator = a,
                .io = io,
                .namespace = namespace,
                .assets = assets,
                .application = application,
                .handlers = handlers,
                .profile = profile,
                .program = try evaluator.Program.open(a, assets.image),
            };
            errdefer self.program.close() catch |err| {
                std.log.err("unpublished program cleanup failed: {s}", .{@errorName(err)});
            };
            try io.randomSecure(&self.owner_epoch);
            _ = try self.store().auditRetention(handlers, application.image_identity);
            try self.recover(a, null);
            try self.recoverWorkspace(a);
            try self.recoverControllerResiduals(a, null);
            try self.recoverPlacementFiles(a);
            return self;
        }
        fn store(self: *Self) *storage.Store {
            return &self.namespace.store;
        }
        fn allowed(self: *Self) !void {
            if (self.profile.authority.revoked or
                !self.profile.authority.disclosure)
                return error.Denied;
            if (self.store().fenced) return error.StorageUnavailable;
        }
        fn placementSite(self: *Self) !@import("placement.zig").Site {
            const configured = self.profile.placement orelse return error.UnsupportedCapability;
            return .{
                .key = configured.signing_key.public_key.toBytes(),
                .namespace = self.namespace.identity,
            };
        }
        fn requireCustody(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: ?state.Digest,
        ) !void {
            // Historical validation may project an existing receipt, but its
            // replay guard forbids executing a missing operation.
            if (self.workspace_replay != null) return;
            if (try @import("placement_journal.zig").custody(
                self.store(),
                a,
                .{ .task = task_id, .work = work_id },
            )) |saved| {
                var current = saved;
                defer current.deinit();
                if (self.profile.placement == null) return error.CustodyNotLocal;
                try current.value.requireLocal(try self.placementSite());
            } else if (!try self.store().locallyAdmitted(task_id)) {
                return error.CustodyNotLocal;
            }
        }
        fn hasLocalCustody(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: ?state.Digest,
        ) !bool {
            self.requireCustody(a, task_id, work_id) catch |err| {
                if (err == error.CustodyNotLocal) return false;
                return err;
            };
            return true;
        }
        fn hasFrozenCustody(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: ?state.Digest,
        ) !bool {
            if (self.profile.placement == null) return false;
            var saved = try @import("placement_journal.zig").custody(self.store(), a, .{
                .task = task_id,
                .work = work_id,
            }) orelse return false;
            defer saved.deinit();
            return saved.value.phase == .frozen and std.meta.eql(
                saved.value.owner,
                try self.placementSite(),
            );
        }
        fn createCustody(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: ?state.Digest,
        ) !void {
            if (self.profile.placement == null) return;
            const custody = try self.initialCustody(
                a,
                .{ .task = task_id, .work = work_id },
                try self.placementSite(),
            );
            try @import("placement_journal.zig").putCustody(self.store(), a, custody);
        }
        fn initialCustody(
            self: *Self,
            a: std.mem.Allocator,
            subject: @import("placement.zig").Subject,
            site: @import("placement.zig").Site,
        ) !@import("placement.zig").Custody {
            const p = @import("placement.zig");
            var custody = p.Custody.initial(subject, site);
            if (subject.work == null) {
                var parent = try self.task(a, subject.task);
                defer parent.deinit();
                custody.epoch = parent.value.controller_epoch;
            }
            return custody;
        }
        pub fn task(
            self: *Self,
            a: std.mem.Allocator,
            id: state.TaskId,
        ) !contracts.Decoded(state.Task) {
            try self.allowed();
            const bytes = try self.store().taskBytes(a, id);
            defer a.free(bytes);
            var decoded = try contracts.decodeOwned(state.Task, a, bytes);
            errdefer decoded.deinit();
            if (!same(
                decoded.value.principal.bytes,
                self.profile.authority.principal,
            ) or !same(
                decoded.value.tenant.bytes,
                self.profile.authority.tenant,
            )) return error.Denied;
            if (!same(&decoded.value.id, &id)) return error.CorruptState;
            return decoded;
        }
        pub fn schemaArtifact(self: *Self, id: state.Digest) !discovery.Artifact {
            try self.allowed();
            return self.application.schemaArtifact(id);
        }
        pub fn projectedArtifact(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !state.Reference {
            var value = try self.task(a, task_id);
            defer value.deinit();
            try self.compatibleApplication(value.value);
            if (!same(
                &value.value.runtime_identity,
                &self.profile.runtime_identity,
            )) return error.ArtifactUnavailable;
            const owners = try self.store().projectionOwners(a, task_id, id);
            defer a.free(owners);
            for (owners) |owner| {
                var attempt = try self.record(state.Attempt, a, "attempt", owner.attempt, task_id);
                defer attempt.deinit();
                if (!std.meta.eql(
                    attempt.value.profile,
                    value.value.profile,
                )) return error.CorruptState;
                const bytes = try self.store().object(a, attempt.value.request, null);
                defer a.free(bytes);
                var request = try data.invocation.decode(data.invocation.Request, a, bytes);
                defer request.deinit();
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    attempt.value.occurrence,
                    task_id,
                );
                defer pending.deinit();
                const entry = try self.handlers.resolve(
                    request.value,
                    try self.occurrenceImage(a, value.value, pending.value),
                );
                if (entry.declaration.public_outputs) return owner.object;
            }
            return error.ArtifactUnavailable;
        }
        pub fn frozenInputs(self: *Self, a: std.mem.Allocator, id: state.TaskId) !FrozenInputs {
            // Rebuild adapter state from owned immutable data, never from the
            // original filesystem paths. This read does not resume or grant work.
            var decoded = try self.task(a, id);
            defer decoded.deinit();
            return readFrozenInputs(a, decoded.value, self.store());
        }
        pub fn frozenArchiveInputs(
            self: *Self,
            a: std.mem.Allocator,
            path: []const u8,
        ) !FrozenInputs {
            // Supply only the owned launch data needed to configure an import.
            // This preview admits no task, grant, resident or external operation.
            try self.allowed();
            var reader = try archive_api.Reader.open(a, path);
            defer reader.deinit();
            const bytes = try reader.object(a, reader.manifest.value.task, null);
            defer a.free(bytes);
            var decoded = try contracts.decodeOwned(state.Task, a, bytes);
            defer decoded.deinit();
            if (!same(
                decoded.value.principal.bytes,
                self.profile.authority.principal,
            ) or !same(
                decoded.value.tenant.bytes,
                self.profile.authority.tenant,
            )) return error.Denied;
            return readFrozenInputs(a, decoded.value, &reader);
        }
        pub fn pendingQuestion(
            self: *Self,
            a: std.mem.Allocator,
            id: state.TaskId,
        ) !?contracts.Decoded(state.Question) {
            var value = try self.task(a, id);
            defer value.deinit();
            const current = value.value.current_occurrence orelse return null;
            var saved = try self.record(occurrence.Occurrence, a, "occurrence", current, id);
            defer saved.deinit();
            const question_id = switch (saved.value.state) {
                .awaiting => |waiting| waiting.question,
                else => return null,
            };
            return try self.record(state.Question, a, "question", question_id, id);
        }
        pub fn status(self: *Self, a: std.mem.Allocator, value: state.Task) !Status {
            switch (value.outcome_kind) {
                .completed => return .completed,
                .failed => return .failed,
                .cancelled => return .cancelled,
                else => {},
            }
            if (value.current_occurrence) |id| {
                var saved = try self.record(occurrence.Occurrence, a, "occurrence", id, value.id);
                defer saved.deinit();
                if (saved.value.state == .unknown or
                    (saved.value.state == .dispatching and
                        (self.work == null or
                            !same(&self.work.?.occurrence, &id)))) return .unknown;
                if (saved.value.state == .awaiting and
                    (value.cancellation == null or
                        value.cancellation_applied))
                    return .waiting_input;
            }
            if (value.blocker != null) return .blocked;
            if (value.cancellation != null) return .cancelling;
            // Worker-owned execution is active while ineligible for another turn.
            if (self.work) |work| if (same(&work.task, &value.id)) return .running;
            for (self.runnable.items) |subject| if (subject.work == null and same(
                &subject.task,
                &value.id,
            )) return if (value.schedule == .queued) .queued else .running;
            return .parked;
        }
        pub fn taskCleanupComplete(self: *Self, a: std.mem.Allocator, value: state.Task) !bool {
            if (!value.terminal()) return false;
            const bytes = try self.store().object(a, value.outcome, null);
            defer a.free(bytes);
            var outcome = try data.invocation.decode(data.invocation.Outcome, a, bytes);
            defer outcome.deinit();
            return cleanupComplete(outcome.value) and try self.associatedWorkDisposed(a, value.id);
        }
        pub fn associatedWorkDisposed(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
        ) !bool {
            return try self.controllerResidualsSettled(
                a,
                task_id,
            ) and try self.workspaceSettled(a, task_id, true, true, false);
        }
        fn workspaceSettled(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            require_disposal: bool,
            include_remote: bool,
            require_park: bool,
        ) !bool {
            var query = try self.store().database.prepare(
                "SELECT id FROM records WHERE task=? AND kind='workspace_work' ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            var arena = std.heap.ArenaAllocator.init(a);
            defer arena.deinit();
            while (try query.step() == .row) {
                const bytes = try query.bytes(0);
                if (bytes.len != 32) return error.CorruptState;
                const id = bytes[0..32].*;
                _ = arena.reset(.retain_capacity);
                const temporary = arena.allocator();
                if (!try self.hasLocalCustody(temporary, task_id, id)) {
                    if (try self.hasFrozenCustody(temporary, task_id, id)) {
                        var frozen = try self.retainedWorkspaceWork(temporary, task_id, id);
                        defer frozen.deinit();
                        if (require_disposal or
                            require_park or
                            frozen.value.cancellation != null)
                            return false;
                    }
                    if (!include_remote) continue;
                    var remote = try self.remoteWorkState(temporary, task_id, id);
                    defer remote.deinit();
                    if (remote.pending) return false;
                    if (try self.retainedWorkspaceDisposed(temporary, task_id, id)) continue;
                    if (require_disposal) {
                        const observed =
                            if (remote.latest) |saved|
                                saved.value.report.?.value.work_state.?
                            else
                                return false;
                        if (!remoteDisposed(observed)) return false;
                    } else if (require_park) {
                        const observed =
                            if (remote.latest) |saved|
                                saved.value.report.?.value.work_state.?
                            else
                                return false;
                        if (!remoteDisposed(observed) and !observed.parkSettled()) return false;
                    }
                    continue;
                }
                var child = try self.retainedWorkspaceWork(temporary, task_id, id);
                defer child.deinit();
                if (!try self.workspaceWorkSettled(
                    temporary,
                    child.value,
                    require_disposal,
                    require_park,
                )) return false;
            }
            return true;
        }
        fn workspaceWorkSettled(
            self: *Self,
            a: std.mem.Allocator,
            child: workspace.Work,
            require_disposal: bool,
            require_park: bool,
        ) !bool {
            if (require_disposal and child.observer != null and !child.observer.?.stopped and
                child.observer.?.successor == null) return false;
            if (child.terminal()) {
                const outcome_bytes = try self.store().object(a, child.outcome, null);
                defer a.free(outcome_bytes);
                var outcome = try data.invocation.decode(data.invocation.Outcome, a, outcome_bytes);
                defer outcome.deinit();
                return cleanupComplete(outcome.value);
            }
            if (require_disposal or
                child.cancellation != null or
                (require_park and
                    child.schedule != .parked))
                return false;
            if (child.current_occurrence) |current| {
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    current,
                    child.task,
                );
                defer pending.deinit();
                switch (pending.value.state) {
                    .dispatching, .unknown, .captured, .settled_reply => return false,
                    else => {},
                }
            }
            return true;
        }
        fn retainedWorkspaceDisposed(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
        ) !bool {
            var child = try self.retainedWorkspaceWork(a, task_id, work_id);
            defer child.deinit();
            return child.value.terminal() and try self.workspaceWorkSettled(
                a,
                child.value,
                true,
                false,
            );
        }
        pub fn shutdownIncomplete(self: *Self, a: std.mem.Allocator) !bool {
            for (self.owned.items) |id| {
                var decoded = try self.task(a, id);
                defer decoded.deinit();
                const value = decoded.value;
                const controller = try self.hasLocalCustody(
                    a,
                    id,
                    null,
                ) or try self.hasFrozenCustody(a, id, null);
                if (controller) {
                    if (value.terminal()) {
                        const bytes = try self.store().object(a, value.outcome, null);
                        defer a.free(bytes);
                        var outcome = try data.invocation.decode(data.invocation.Outcome, a, bytes);
                        defer outcome.deinit();
                        if (!cleanupComplete(outcome.value)) return true;
                    } else if (self.shutdown_cancel_requested or try self.status(
                        a,
                        value,
                    ) == .unknown or value.cancellation != null) return true;
                }
                if (controller and !try self.controllerResidualsSettled(a, id)) return true;
                if (!try self.workspaceSettled(
                    a,
                    id,
                    self.shutdown_cancel_requested or (controller and value.cancellation != null),
                    controller,
                    controller and value.terminal(),
                )) return true;
            }
            return false;
        }
        pub fn cancelOwned(
            self: *Self,
            a: std.mem.Allocator,
            instance: []const u8,
            reason: []const u8,
        ) !void {
            // Launch ownership names recovery tasks. Actual cancellation authority
            // is the local controller or the independently held local work subjects.
            self.shutdown_cancel_requested = true;
            const owned = try a.dupe(state.TaskId, self.owned.items);
            defer a.free(owned);
            for (owned) |id| {
                if (try self.hasLocalCustody(a, id, null)) {
                    const operation_id = try std.fmt.allocPrint(a, "shutdown-{s}-{s}", .{
                        instance,
                        std.fmt.bytesToHex(id, .lower),
                    });
                    defer a.free(operation_id);
                    _ = try self.requestCancel(a, operation_id, id, reason);
                    continue;
                }
                const children = try self.workspaceIds(a, id);
                defer a.free(children);
                for (children) |work_id| {
                    if (!try self.hasLocalCustody(a, id, work_id)) continue;
                    var child = try self.workspaceWork(a, id, work_id);
                    defer child.deinit();
                    if (try self.stopLocalWorkspaceObserver(a, child.value)) {
                        const updated = try self.workspaceWork(a, id, work_id);
                        child.deinit();
                        child = updated;
                    }
                    if (child.value.terminal()) continue;
                    const Identity = struct {
                        instance: contracts.Bytes(null),
                        task: state.TaskId,
                        work: state.Digest,
                    };
                    const identity = try operation(Identity, a, .{
                        .instance = .{ .bytes = instance },
                        .task = id,
                        .work = work_id,
                    });
                    const operation_id = try std.fmt.allocPrint(a, "shutdown-work-{s}", .{
                        std.fmt.bytesToHex(identity, .lower),
                    });
                    defer a.free(operation_id);
                    _ = try self.workspaceControl(
                        a,
                        operation_id,
                        id,
                        work_id,
                        child.value.execution_revision,
                        child.value.control_revision,
                        .{ .cancel = .{ .bytes = reason } },
                    );
                }
            }
        }
        pub fn placementActive(self: *const Self) bool {
            return self.placement_job != null or self.placement_pending.items.len != 0;
        }
        fn workspaceIds(self: *Self, a: std.mem.Allocator, task_id: state.TaskId) ![]state.Digest {
            var query = try self.store().database.prepare(
                "SELECT id FROM records WHERE task=? AND kind='workspace_work' ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            var ids: std.ArrayList(state.Digest) = .empty;
            errdefer ids.deinit(a);
            while (try query.step() == .row) {
                const bytes = try query.bytes(0);
                if (bytes.len != 32) return error.CorruptState;
                try ids.append(a, bytes[0..32].*);
            }
            return ids.toOwnedSlice(a);
        }
        fn controllerResidualIds(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
        ) ![]state.Digest {
            var query = try self.store().database.prepare(
                "SELECT id FROM records WHERE task=? AND kind='controller_residual' ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            var ids: std.ArrayList(state.Digest) = .empty;
            errdefer ids.deinit(a);
            while (try query.step() == .row) {
                const bytes = try query.bytes(0);
                if (bytes.len != 32) return error.CorruptState;
                try ids.append(a, bytes[0..32].*);
            }
            return ids.toOwnedSlice(a);
        }
        fn controllerResidualsSettled(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
        ) !bool {
            const ids = try self.controllerResidualIds(a, task_id);
            defer a.free(ids);
            for (ids) |id| {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    task_id,
                );
                defer residual.deinit();
                const bytes = try self.store().object(a, residual.value.outcome, null);
                defer a.free(bytes);
                var outcome = try data.invocation.decode(data.invocation.Outcome, a, bytes);
                defer outcome.deinit();
                if (!cleanupComplete(outcome.value)) return false;
            }
            return true;
        }
        fn appendControllerResiduals(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            subjects: *std.ArrayList(workspace.Subject),
        ) !void {
            const ids = try self.controllerResidualIds(a, task_id);
            defer a.free(ids);
            for (ids) |id| {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    task_id,
                );
                defer residual.deinit();
                if (residual.value.schedule != .parked) try subjects.append(a, .{
                    .task = task_id,
                    .residual = id,
                });
            }
        }
        fn recoverControllerResiduals(
            self: *Self,
            a: std.mem.Allocator,
            selected: ?state.TaskId,
        ) !void {
            const tasks = try self.store().taskIds(a, false);
            defer a.free(tasks);
            for (tasks) |task_id| {
                if (selected) |id| if (!std.meta.eql(id, task_id)) continue;
                var authorized = self.task(a, task_id) catch |err| switch (err) {
                    error.Denied => continue,
                    else => return err,
                };
                defer authorized.deinit();
                const ids = try self.controllerResidualIds(a, task_id);
                defer a.free(ids);
                for (ids) |id| {
                    try self.recoverControllerResidual(a, task_id, id);
                }
            }
        }
        fn recoverControllerResidual(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !void {
            var residual = try self.record(
                state.ControllerResidual,
                a,
                "controller_residual",
                id,
                task_id,
            );
            defer residual.deinit();
            const current = residual.value.current_occurrence orelse return;
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                current,
                task_id,
            );
            defer pending.deinit();
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if (pending.value.state == .dispatching) {
                try self.recoverDispatchedResidual(
                    a,
                    task_id,
                    id,
                    current,
                    parent.value,
                    pending.value,
                );
            } else if (pending.value.state == .unknown) {
                const recovery_id = (try self.pendingRecovery(
                    a,
                    task_id,
                    current,
                    pending.value.state.unknown.id,
                )) orelse return;
                var recovery = try self.record(
                    state.Reconciliation,
                    a,
                    "reconciliation",
                    recovery_id,
                    task_id,
                );
                defer recovery.deinit();
                try self.finishRecovery(
                    a,
                    parent.value,
                    pending.value,
                    recovery.value,
                    null,
                    .interrupted,
                );
            }
        }
        fn recoverDispatchedResidual(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
            current: state.Digest,
            parent: state.Task,
            pending: occurrence.Occurrence,
        ) !void {
            const lost = try occurrence.unknown(
                pending,
                .{
                    .id = current,
                    .task = task_id,
                    .residual = id,
                    .request = pending.request,
                },
                pending.state.dispatching.id,
            );
            var value = parent;
            value.revision = try std.math.add(u64, value.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                current,
                task_id,
                lost,
            );
            try self.effectSchedule(a, &value, pending, .parked, .unavailable_environment);
            try self.persist(
                a,
                value,
                parent.revision,
                "controller.recover-cleanup",
                .preserve,
            );
        }
        fn recoverWorkspace(self: *Self, a: std.mem.Allocator) !void {
            const tasks = try self.store().taskIds(a, false);
            defer a.free(tasks);
            for (tasks) |task_id| {
                const ids = try self.workspaceIds(a, task_id);
                defer a.free(ids);
                for (ids) |id| {
                    var parent = self.task(a, task_id) catch |err| switch (err) {
                        error.Denied => continue,
                        else => return err,
                    };
                    defer parent.deinit();
                    // Reopening classifies lost delivery before the launch
                    // profile is selected. This transition uses retained task
                    // custody, and grants no new execution authority.
                    var child = try self.retainedWorkspaceWork(a, task_id, id);
                    defer child.deinit();
                    const current = child.value.current_occurrence orelse continue;
                    var pending = try self.record(
                        occurrence.Occurrence,
                        a,
                        "occurrence",
                        current,
                        task_id,
                    );
                    defer pending.deinit();
                    if (pending.value.state != .dispatching) continue;
                    const lost = try occurrence.unknown(
                        pending.value,
                        .{
                            .id = current,
                            .task = task_id,
                            .work = id,
                            .request = pending.value.request,
                        },
                        pending.value.state.dispatching.id,
                    );
                    var value = parent.value;
                    value.revision = try std.math.add(u64, value.revision, 1);
                    try self.store().begin();
                    defer self.store().rollback();
                    try self.store().putRecord(
                        occurrence.Occurrence,
                        "occurrence",
                        current,
                        task_id,
                        lost,
                    );
                    try self.effectSchedule(
                        a,
                        &value,
                        pending.value,
                        .parked,
                        .unavailable_environment,
                    );
                    try self.persist(
                        a,
                        value,
                        parent.value.revision,
                        "work.recover-unknown",
                        .preserve,
                    );
                }
            }
        }
        fn remoteDisposed(value: @import("placement.zig").WorkState) bool {
            return !value.observer_active and (value.outcome == .completed or
                value.outcome == .failed or value.outcome == .cancelled) and value.cleanup_complete;
        }
        fn stopRemoteObserverOne(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
        ) !bool {
            var child = try self.retainedWorkspaceWork(a, task_id, work_id);
            defer child.deinit();
            if (!self.activeObserver(child.value)) return false;
            var remote = try self.remoteWorkState(a, task_id, work_id);
            defer remote.deinit();
            if (remote.latest) |saved| if (!saved.value.report.?.value.work_state.?.observer_active)
                return false;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            return self.settleRemoteWork(a, parent.value, work_id);
        }
        fn remoteWorkState(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
        ) !RemoteWorkState {
            var result: RemoteWorkState = .{};
            errdefer result.deinit();
            var custody = try @import("placement_journal.zig").custody(self.store(), a, .{
                .task = task_id,
                .work = work_id,
            }) orelse return result;
            defer custody.deinit();
            if (custody.value.phase != .away) return result;
            var controller_custody = try @import(
                "placement_journal.zig",
            ).custody(self.store(), a, .{ .task = task_id }) orelse return result;
            defer controller_custody.deinit();
            var query = try self.store().database.prepare(
                "SELECT id FROM records WHERE task=? AND kind='placement_control' ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            while (try query.step() == .row) {
                const bytes = try query.bytes(0);
                if (bytes.len != 32) return error.CorruptState;
                try self.observeRemoteControl(
                    a,
                    task_id,
                    work_id,
                    bytes[0..32].*,
                    custody.value,
                    controller_custody.value,
                    &result,
                );
            }
            return result;
        }
        fn observeRemoteControl(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
            id: state.Digest,
            custody: @import("placement.zig").Custody,
            controller_custody: @import("placement.zig").Custody,
            result: *RemoteWorkState,
        ) !void {
            const p = @import("placement.zig");
            var saved = try self.record(
                p.ControlRecord,
                a,
                "placement_control",
                id,
                task_id,
            );
            errdefer saved.deinit();
            const control = saved.value.control.value;
            if (!std.meta.eql(control.subject.work, work_id) or !std.meta.eql(
                control.controller,
                controller_custody.owner,
            ) or control.controller_epoch != controller_custody.epoch) {
                saved.deinit();
                return;
            }
            if (saved.value.report) |report| {
                if (!std.meta.eql(
                    report.value.executor,
                    custody.owner,
                ) or report.value.custody_epoch != custody.epoch) {
                    saved.deinit();
                    return;
                }
                if (report.value.work_state) |observed| {
                    try p.matchReport(a, control, saved.value.route.items, report);
                    if (!std.meta.eql(
                        report.value.control,
                        try p.digest(p.Control, a, control),
                    ) or report.value.custody_epoch != custody.epoch) {
                        return error.InvalidRemoteCommand;
                    }
                    if (result.latest == null or
                        observed.observed_at >=
                            result.latest.?.value.report.?.value.work_state.?.observed_at)
                    {
                        if (result.latest) |*old| old.deinit();
                        result.latest = saved;
                        return;
                    }
                }
            } else {
                result.pending = true;
                if (saved.value.last_error == null) result.retry_pending = saved.value.id;
            }
            saved.deinit();
        }
        fn settleRemoteWork(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work_id: state.Digest,
        ) !bool {
            const cancellation_revision: ?u64 =
                if (parent.cancellation !=
                null) try self.parentCancellationRevision(a, parent.id) else null;
            var observed = try self.remoteWorkState(a, parent.id, work_id);
            defer observed.deinit();
            if (observed.pending) {
                if (observed.retry_pending) |id| {
                    try self.placement_pending.ensureUnusedCapacity(self.allocator, 1);
                    self.placementQueue(parent.id, id, .control);
                }
                return false;
            }
            if (try self.retainedWorkspaceDisposed(a, parent.id, work_id)) return false;
            const reference = try wp.reference(a, .work, work_id);
            var command: wc.Work = .{ .inspect = .{ .work = reference } };
            var predecessor: state.Digest = @splat(0);
            command = try self.remoteSettlementCommand(
                a,
                parent,
                work_id,
                reference,
                cancellation_revision,
                observed,
                &predecessor,
            ) orelse return false;
            return self.publishRemoteSettlement(
                a,
                parent,
                work_id,
                cancellation_revision,
                predecessor,
                command,
            );
        }
        fn remoteSettlementCommand(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work_id: state.Digest,
            reference: anytype,
            cancellation_revision: ?u64,
            observed: RemoteWorkState,
            predecessor: *state.Digest,
        ) !?wc.Work {
            const p = @import("placement.zig");
            var command: wc.Work = .{ .inspect = .{ .work = reference } };
            if (observed.latest) |saved| {
                const report = saved.value.report.?;
                const current = report.value.work_state.?;
                if (remoteDisposed(current)) return null;
                predecessor.* = try p.digest(p.Report, a, report.value);
                const expected: wc.Expected = .{
                    .work = reference,
                    .execution_revision = current.execution_revision,
                    .control_revision = current.control_revision,
                };
                // A signed rejection at unchanged revisions needs operator
                // reconciliation; do not generate an unbounded retry stream.
                if (report.value.reply.disposition == .rejected and
                    saved.value.control.value.cleanup_request == cancellation_revision)
                {
                    const prior = switch (saved.value.control.value.command) {
                        .cancel => |v| v.expected,
                        .pump => |v| v.expected,
                        .park, .stop_observing => |v| v,
                        else => null,
                    };
                    if (prior == null) return null;
                    if (prior) |revision|
                        if (revision.execution_revision ==
                            expected.execution_revision and
                            revision.control_revision == expected.control_revision)
                            return null;
                }
                if (current.observer_active) {
                    command = .{ .stop_observing = expected };
                } else if (cancellation_revision) |revision| {
                    const acknowledged = try self.remoteCancellationAcknowledged(
                        a,
                        parent.id,
                        work_id,
                        revision,
                    );
                    if (acknowledged and current.explicitly_parked) return null;
                    command = if (current.cancellation == null or !acknowledged) .{ .cancel = .{
                        .expected = expected,
                        .reason = parent.cancellation.?,
                    } } else .{ .pump = .{ .expected = expected, .base_quantum = 65536 } };
                } else {
                    if (current.explicitly_parked) {
                        if (current.parkSettled()) return null;
                    } else command = if (current.cancellation == null) .{
                        .park = expected,
                    } else .{ .pump = .{ .expected = expected, .base_quantum = 65536 } };
                }
            }
            return command;
        }
        fn publishRemoteSettlement(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work_id: state.Digest,
            cancellation_revision: ?u64,
            predecessor: state.Digest,
            command: wc.Work,
        ) !bool {
            const p = @import("placement.zig");
            const identity = if (cancellation_revision) |revision|
                try operation(struct {
                    work: state.Digest,
                    cancellation: state.Reason,
                    request_revision: u64,
                    predecessor: state.Digest,
                }, a, .{
                    .work = work_id,
                    .cancellation = parent.cancellation.?,
                    .request_revision = revision,
                    .predecessor = predecessor,
                })
            else
                try operation(struct {
                    work: state.Digest,
                    completion_revision: u64,
                    predecessor: state.Digest,
                }, a, .{
                    .work = work_id,
                    .completion_revision = parent.execution_revision,
                    .predecessor = predecessor,
                });
            const operation_name = try std.fmt.allocPrint(a, "{s}-{s}", .{
                if (cancellation_revision != null) "cleanup" else "close",
                std.fmt.bytesToHex(identity, .lower),
            });
            defer a.free(operation_name);
            try self.placement_pending.ensureUnusedCapacity(self.allocator, 1);
            const bytes = self.placementControlExpanded(
                a,
                operation_name,
                parent.id,
                command,
                null,
                true,
                cancellation_revision,
            ) catch |err| switch (err) {
                error.CustodyNotRemote, error.UnsupportedCapability, error.Denied => return false,
                else => return err,
            };
            defer a.free(bytes);
            var signed = try contracts.decodeOwned(p.Signed(p.Control), a, bytes);
            defer signed.deinit();
            const id = p.controlId(signed.value.value);
            var saved = try self.record(p.ControlRecord, a, "placement_control", id, parent.id);
            defer saved.deinit();
            if (saved.value.report != null) return false;
            self.placementQueue(parent.id, id, .control);
            return true;
        }
        fn parentCancellationRevision(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
        ) !u64 {
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? ORDER BY e.seq DESC",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var event_value = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer event_value.deinit();
                if (event_value.value.kind == .cancellation_requested)
                    return event_value.value.revision;
            }
            return error.CorruptState;
        }
        fn remoteCancellationAcknowledged(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
            revision: u64,
        ) !bool {
            const p = @import("placement.zig");
            var events = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.revision>? ORDER BY e.seq DESC",
                &.{ .{ .blob = &task_id }, .{ .integer = @intCast(revision) } },
            );
            defer events.deinit();
            while (try events.step() == .row) {
                var event_value = try contracts.decodeOwned(state.Event, a, try events.bytes(0));
                defer event_value.deinit();
                const concerns_child = for (event_value.value.workspace_publications.items) |item| {
                    if (std.meta.eql(item.work, work_id)) break true;
                } else false;
                if (!concerns_child) continue;
                const reference = event_value.value.workspace_command orelse continue;
                const bytes = try self.store().object(a, reference, null);
                defer a.free(bytes);
                var command = try contracts.decodeOwned(workspace.PublicationCommand, a, bytes);
                defer command.deinit();
                if (command.value == .control and
                    command.value.control.command == .cancel)
                    return true;
            }
            var query = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='placement_control'",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(p.ControlRecord, a, try query.bytes(0));
                defer saved.deinit();
                const control = saved.value.control.value;
                if (control.command != .cancel or
                    control.cleanup_request != revision or
                    !std.meta.eql(control.subject.work, work_id)) continue;
                if (saved.value.report) |report| {
                    try p.matchReport(a, control, saved.value.route.items, report);
                    if (report.value.reply.disposition == .observed and try self.retainsController(
                        a,
                        control,
                    )) return true;
                }
            }
            return false;
        }
        fn retainsController(
            self: *Self,
            a: std.mem.Allocator,
            control: @import("placement.zig").Control,
        ) !bool {
            const p = @import("placement.zig");
            const journal = @import("placement_journal.zig");
            var current = try journal.custody(self.store(), a, .{
                .task = control.subject.task,
            }) orelse return error.InvalidTransfer;
            defer current.deinit();
            var site = current.value.owner;
            var epoch = current.value.epoch;
            if (std.meta.eql(
                control.controller,
                site,
            ) and control.controller_epoch == epoch) return true;
            const lineage = try journal.controllerLineage(self.store(), a, control.subject.task);
            defer a.free(lineage);
            var index = lineage.len;
            while (index > 0) {
                index -= 1;
                const transition = lineage[index];
                if (transition == .behavior) {
                    const prior = transition.behavior;
                    if (prior.value.epoch != epoch or !std.meta.eql(
                        prior.value.owner,
                        site,
                    )) continue;
                    try p.verify(p.Behavior, a, prior, site);
                    if (!std.meta.eql(
                        prior.value.task,
                        control.subject.task,
                    ) or prior.value.epoch != try std.math.add(
                        u64,
                        prior.value.previous_epoch,
                        1,
                    )) return error.InvalidTransfer;
                    epoch = prior.value.previous_epoch;
                    if (std.meta.eql(
                        control.controller,
                        site,
                    ) and control.controller_epoch == epoch) return true;
                    continue;
                }
                const prior = transition.move;
                const intent = prior.offer.value.intent;
                if (prior.decision.value.epoch != epoch or !std.meta.eql(
                    prior.decision.value.destination,
                    site,
                )) continue;
                try p.verify(p.Offer, a, prior.offer, intent.source);
                try p.matchDecision(a, prior.offer.value, prior.decision);
                if (prior.decision.value.verdict != .accepted or !std.meta.eql(
                    prior.decision.value.destination,
                    intent.destination,
                ) or !std.meta.eql(
                    intent.subject.task,
                    control.subject.task,
                ) or intent.subject.work != null) return error.InvalidTransfer;
                site = intent.source;
                epoch = intent.epoch;
                if (std.meta.eql(
                    control.controller,
                    site,
                ) and control.controller_epoch == epoch) return true;
            }
            return false;
