                    (parent.cancellation != null or
                        parent.terminal()) and
                    try self.settleRemoteWork(a, parent, id)) return true;
                return false;
            }
            var child = try self.workspaceWork(a, parent.id, id);
            defer child.deinit();
            if (self.shutdown_cancel_requested and
                try self.stopLocalWorkspaceObserver(a, child.value)) return true;
            if (child.value.terminal()) return false;
            if (!controller or parent.cancellation == null) {
                if (child.value.cancellation != null and
                    child.value.schedule != .parked) try self.subjectAdd(
                    .{ .task = parent.id, .work = id },
