                var child = try self.workspaceWork(a, task_id, id);
                defer child.deinit();
                if (try self.stopLocalWorkspaceObserver(a, child.value)) return true;
            }
            return false;
        }
        fn stopLocalWorkspaceObserver(
            self: *Self,
            a: std.mem.Allocator,
            child: workspace.Work,
