        fn recover(self: *Self, a: std.mem.Allocator, selected: ?state.TaskId) !void {
            const ids = try self.store().taskIds(a, true);
            defer a.free(ids);
            for (ids) |id| {
                if (selected) |task_id| if (!std.meta.eql(id, task_id)) continue;
                try self.recoverDispatchedTask(a, id);
            }
            for (ids) |id| {
                if (selected) |task_id| if (!std.meta.eql(id, task_id)) continue;
                try self.recoverUnknownTask(a, id);
            }
        }
        fn recoverUnknownTask(self: *Self, a: std.mem.Allocator, id: state.TaskId) !void {
            var decoded = self.task(a, id) catch |err| switch (err) {
                error.Denied => return,
                else => return err,
            };
            defer decoded.deinit();
            const current = decoded.value.current_occurrence orelse return;
            var saved = try self.record(occurrence.Occurrence, a, "occurrence", current, id);
            defer saved.deinit();
            if (saved.value.state != .unknown) return;
            const pending = try self.pendingRecovery(
                a,
                id,
                current,
                saved.value.state.unknown.id,
            ) orelse return;
            var item = try self.record(state.Reconciliation, a, "reconciliation", pending, id);
            defer item.deinit();
            try self.finishRecovery(
                a,
                decoded.value,
                saved.value,
                item.value,
                null,
                .interrupted,
            );
