        fn event(self: *Self, value: *state.Task, kind: state.EventType, bytes: []const u8) !void {
            return self.publicationEvent(value, kind, bytes, &.{}, null);
        }
        fn publicationEvent(
            self: *Self,
            value: *state.Task,
            kind: state.EventType,
            bytes: []const u8,
            publications: []const state.WorkPublication,
            command: ?state.Reference,
