                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq",
                &.{ .{ .blob = &parent.id }, .{
                    .integer = std.math.cast(i64, watermark) orelse return error.InvalidArchive,
                } },
            );
            defer rows.deinit();
            while (try rows.step() == .row) {
                var event_value = try contracts.decodeOwned(state.Event, a, try rows.bytes(0));
                defer event_value.deinit();
                const saved_event = event_value.value;
                if (saved_event.kind != .controller and saved_event.kind != .imported) continue;
                var parsed = try json.parse(a, saved_event.data.bytes, .{});
                defer parsed.deinit();
                if (saved_event.kind == .controller) {
                    const next = try json.decimal(
                        u64,
                        json.get(parsed.value, "epoch") orelse return error.InvalidArchive,
                    );
                    if (next != (std.math.add(
                        u64,
                        epoch,
                        1,
                    ) catch return error.InvalidArchive)) return error.InvalidArchive;
                    epoch = next;
                } else {
                    epoch = try self.importedControllerEpoch(a, parent.id, parsed.value, epoch);
                }
            }
            return epoch;
        }
        fn importedControllerEpoch(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            event_data: json.Value,
            epoch: u64,
        ) !u64 {
            var id: state.Digest = undefined;
            _ = std.fmt.hexToBytes(
                &id,
                try json.text(
                    json.get(
                        event_data,
                        "archive_sha256",
                    ) orelse return error.InvalidArchive,
                ),
            ) catch return error.InvalidArchive;
            var origin = try self.record(state.Origin, a, "origin", id, task_id);
            defer origin.deinit();
            if (origin.value.transfer) |transfer| {
                const p = @import("placement.zig");
                var succession = try self.record(
                    p.Succession,
                    a,
                    "placement_succession",
                    transfer,
                    task_id,
                );
                defer succession.deinit();
                const intent = succession.value.offer.value.intent;
                try p.matchDecision(
                    a,
                    succession.value.offer.value,
                    succession.value.decision,
                );
                if (succession.value.decision.value.verdict != .accepted or !std.meta.eql(
                    intent.subject.task,
                    task_id,
                )) return error.InvalidArchive;
                if (intent.subject.work == null) {
                    if (intent.epoch != epoch) return error.InvalidArchive;
                    return succession.value.decision.value.epoch;
                }
            }

            return epoch;
        }
        fn rootRouteImage(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            route: workspace.ExecutionRoute,
        ) !state.Reference {
            if (route.work != null) return error.CorruptState;
            if (route.controller) |id| {
                var cursor = value.controller;
                var last_epoch: ?u64 = null;
                while (cursor) |current| {
                    const binding = try self.controllerBinding(a, value, current);
                    if (last_epoch) |epoch| if (binding.epoch >= epoch) return error.CorruptState;
                    if (std.meta.eql(current, id)) {
                        if (!std.meta.eql(
                            binding.program_identity,
                            route.program_identity,
                        )) return error.CorruptState;
                        return binding.image;
                    }
                    last_epoch = binding.epoch;
                    cursor = binding.predecessor;
                }
                return error.CorruptState;
            }
            if (!std.meta.eql(
                route.program_identity,
                self.application.image_identity,
            )) return error.CorruptState;
            return value.image;
        }
        fn rootDriver(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            instance: data.invocation.Instance,
        ) !*evaluator.Driver {
            const reference = try self.rootImage(a, value);
            if (value.controller_runtime == null and std.meta.eql(reference, value.image))
                return evaluator.Driver.start(self.allocator, self.program, instance);
            const image = try self.store().object(a, reference, null);
            defer a.free(image);
            var runtime = try self.controllerRuntime(
                a,
                value.id,
                reference,
                value.controller_runtime,
            );
            defer runtime.deinit();
            return evaluator.Driver.openSelected(self.allocator, image, instance, &runtime);
        }
        fn controllerRuntime(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            image: state.Reference,
            reference: ?state.Reference,
        ) !kosmos.RuntimeArtifact {
            const ref = reference orelse return self.program.retainRuntime();
            var selected = try self.workspaceRuntime(a, task_id, ref.digest, null);
            defer selected.record.deinit();
            errdefer selected.admitted.deinit();
            var program = try self.workspaceProgram(a, task_id, selected.record.value.program);
            defer program.deinit();
            if (!std.meta.eql(ref, selected.record.value.artifact) or
                !std.meta.eql(image, program.value.description.image)) return error.InvalidRuntime;
            return selected.admitted;
        }
        fn rootIdentity(id: state.TaskId) state.Digest {
            return state.controllerExecutionIdentity(id);
        }
        fn rootProvenance(value: state.Task) kosmos.RuntimeCapsule.Provenance {
            return .{
                .execution = rootIdentity(value.id),
                .custody = storage.digest(&value.id),
                .publication = .{
                    .digest = value.checkpoint.digest,
                    .bytes = value.checkpoint.bytes,
                },
            };
        }
        fn rootOperation(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
        ) !?contracts.Decoded(state.RootOperation) {
            const bytes = try self.store().recordBytes(
                a,
                "root_operation",
                rootIdentity(value.id),
                value.id,
            ) orelse return null;
            defer a.free(bytes);
            var decoded = try contracts.decodeOwned(state.RootOperation, a, bytes);
            errdefer decoded.deinit();
            if (!std.meta.eql(decoded.value.id, rootIdentity(value.id)) or !std.meta.eql(
                decoded.value.task,
                value.id,
            ) or
                decoded.value.execution_revision != value.execution_revision)
                return error.InvalidArchive;
            return decoded;
        }
        fn putRootOperation(self: *Self, a: std.mem.Allocator, value: state.RootOperation) !void {
            if (try self.store().recordBytes(a, "root_operation", value.id, value.task)) |bytes| {
                a.free(bytes);
                try self.store().putRecord(
                    state.RootOperation,
                    "root_operation",
                    value.id,
                    value.task,
                    value,
                );
            } else try self.store().createRecord(
                state.RootOperation,
                "root_operation",
                value.id,
                value.task,
                value,
            );
        }
        fn rootConsumed(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            control: data.invocation.Control,
        ) !?occurrence.Occurrence {
            if (control != .reply and control != .cancel) return null;
            const id = value.current_occurrence orelse return null;
            var pending = try self.record(occurrence.Occurrence, a, "occurrence", id, value.id);
            defer pending.deinit();
            return try occurrence.consumed(
                pending.value,
                .{ .id = id, .task = value.id, .request = pending.value.request },
                if (control == .cancel) .cancel else .{ .reply = storage.digest(control.reply) },
                value.cancellation != null,
            );
        }
        fn retainRootOperation(self: *Self, a: std.mem.Allocator) !void {
            const active = self.active orelse return;
            if (active.subject == .residual) return self.retainResidualOperation(a, active);
            if (active.subject != .root or active.root_control == null) return;
            var saved = try self.task(a, active.task);
            defer saved.deinit();
            if (saved.value.execution_revision != active.execution_revision)
                return error.CorruptState;
            const capsule = try active.driver.retainCapsule(rootProvenance(saved.value));
            const dependencies = try capsuleDependencies(a, capsule);
            defer a.free(dependencies);
            const code = try active.driver.runtimeBytes(a);
            defer a.free(code);
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(code);
            const pending: state.OuterOperation = .{
                .capsule = try self.store().putObject(capsule),
                .dependencies = .{ .items = dependencies },
                .control = try self.store().putObject(active.root_control.?),
                .guest_quantum = active.root_quantum,
            };
            try self.putRootOperation(a, .{
                .id = rootIdentity(active.task),
                .task = active.task,
                .execution_revision = active.execution_revision,
                .pending = pending,
            });
            try self.namespace.commit("controller.outer-suspend");
            self.active.?.outer_operation = pending.capsule;
        }
        fn validateRootOperation(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            saved: state.RootOperation,
        ) !bool {
            if (!std.meta.eql(saved.id, rootIdentity(value.id)) or !std.meta.eql(
                saved.task,
                value.id,
            ) or saved.execution_revision != value.execution_revision) return error.InvalidArchive;
            const pending = saved.pending orelse return false;
            return self.validateControllerOperation(a, value, pending, null, false);
        }
        fn validateControllerOperation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: state.OuterOperation,
            residual: ?state.ControllerResidual,
            historical: bool,
        ) !bool {
            const value = controllerOperationTask(parent, residual);
            if (value.terminal() or pending.guest_quantum > 256) return error.InvalidArchive;
            const bytes = try self.store().object(a, pending.capsule, null);
            defer a.free(bytes);
            var envelope = try kosmos.RuntimeCapsule.read(a, bytes);
            defer envelope.deinit();
            const record_value = envelope.value.record;
            const effective_image = try self.validateControllerCapsule(
                a,
                parent,
                value,
                pending,
                residual,
                record_value,
            );
            const image = try self.store().object(a, effective_image, null);
            defer a.free(image);
            var runtime = try self.controllerRuntime(
                a,
                parent.id,
                effective_image,
                if (residual) |retired| retired.runtime else value.controller_runtime,
            );
            defer runtime.deinit();
            var prepared = try kosmos.Prepared.initWithRuntime(a, image, &runtime);
            defer prepared.deinit();
            if (!std.meta.eql(record_value.artifact.digest, prepared.runtime.identity) or
                record_value.artifact.bytes != prepared.runtime.core.?.encoded_length)
                return error.InvalidArchive;
            const code = try self.store().object(
                a,
                .{ .digest = record_value.artifact.digest, .bytes = record_value.artifact.bytes },
                null,
            );
            defer a.free(code);
            try self.validateControllerCommand(
                a,
                value,
                pending,
                envelope.value.command,
                residual,
                historical,
            );
            const Inspect = struct {
                fn claim(
                    _: *anyopaque,
                    _: kosmos.RuntimeCapsule.Reference,
                    _: kosmos.RuntimeCapsule.Record,
                    _: kosmos.RuntimeCapsule.Reference,
                ) !void {}
            };
            var context: u8 = 0;
            var candidate = try kosmos.RuntimeCapsule.restore(
                a,
                &prepared.guest,
                &prepared.runtime,
                bytes,
                .{ .context = &context, .claim = Inspect.claim },
            );
            defer candidate.deinit();
            return record_value.operation == null;
        }
        fn controllerOperationTask(
            parent: state.Task,
            residual: ?state.ControllerResidual,
        ) state.Task {
            var value = parent;
            if (residual) |retired| {
                value.checkpoint = retired.checkpoint;
                value.outcome = retired.outcome;
                value.outcome_kind = retired.outcome_kind;
                value.current_occurrence = retired.current_occurrence;
                value.cancellation = .{ .bytes = "Controller superseded" };
                value.cancellation_applied = retired.cancellation_applied;
            }
            return value;
        }
        fn validateControllerCapsule(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: state.Task,
            pending: state.OuterOperation,
            residual: ?state.ControllerResidual,
            record_value: kosmos.RuntimeCapsule.Record,
        ) !state.Reference {
            const effective_image = if (residual) |retired| (try self.controllerBinding(
                a,
                parent,
                retired.controller,
            )).image else try self.rootImage(a, value);
            const provenance = if (residual) |retired| residualProvenance(
                retired,
            ) else rootProvenance(value);
            if (!std.meta.eql(record_value.provenance, provenance) or
                record_value.kind != .outer_execution or
                (record_value.operation != .advance and
                    record_value.operation != null) or
                !std.meta.eql(record_value.guest.image.digest, effective_image.digest) or
                record_value.guest.image.bytes != effective_image.bytes)
                return error.InvalidArchive;
            if (pending.dependencies.items.len != record_value.dependencies.len)
                return error.InvalidArchive;
            for (pending.dependencies.items, record_value.dependencies) |ref, expected|
                if (!std.meta.eql(
                    ref.digest,
                    expected.digest,
                ) or ref.bytes != expected.bytes) return error.InvalidArchive;

            return effective_image;
        }
        fn validateControllerCommand(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: state.OuterOperation,
            command_bytes: []const u8,
            residual: ?state.ControllerResidual,
            historical: bool,
        ) !void {
            // Check the exact accepted control against the original guest cut
            // and the acquired occurrence, independently of the outer machine.
            const control_bytes = try self.store().object(a, pending.control, null);
            defer a.free(control_bytes);
            var accepted = try contracts.decodeOwned(data.invocation.Control, a, control_bytes);
            defer accepted.deinit();
            var command = try kosmos.RuntimeCapsule.readCommand(a, command_bytes);
            defer command.deinit();
            if (command.value != .advance or
                command.value.advance.quantum != pending.guest_quantum or
                (pending.guest_quantum == 0 and
                    accepted.value != .reply))
                return error.InvalidArchive;
            const actual = command.value.advance.control;
            switch (accepted.value) {
                .none => if (actual != .none or
                    value.outcome_kind != .progressed or
                    value.current_occurrence != null)
                    return error.InvalidArchive,
                .resume_yield => if (actual != .resume_yield or
                    value.outcome_kind != .yielded or
                    value.current_occurrence != null)
                    return error.InvalidArchive,
                .cancel => try self.validateControllerCancellation(
                    a,
                    value,
                    accepted.value,
                    actual,
                    residual,
                    historical,
                ),
                .reply => try self.validateControllerAnswer(
                    a,
                    value,
                    accepted.value,
                    actual,
                    residual,
                    historical,
                ),
            }
        }
        fn validateControllerCancellation(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            accepted: data.invocation.Control,
            actual: anytype,
            residual: ?state.ControllerResidual,
            historical: bool,
        ) !void {
            const reason = accepted.cancel;

            const cancellation = value.cancellation orelse return error.InvalidArchive;
            if (value.cancellation_applied or reason != .text or !same(
                reason.text,
                cancellation.bytes,
            ) or actual != .cancel or !data.record.equal(
                data.invocation.Reason,
                reason,
                actual.cancel,
            )) return error.InvalidArchive;
            if (residual) |retired| {
                if (value.current_occurrence) |id| {
                    var current = try self.record(
                        occurrence.Occurrence,
                        a,
                        "occurrence",
                        id,
                        value.id,
                    );
                    defer current.deinit();
                    if (current.value.work != null or
                        (retired.cancellation_applied and
                            !std.meta.eql(
                                current.value.residual,
                                retired.id,
                            ))) return error.InvalidArchive;
                    if (historical and current.value.state == .admitted) {
                        if (current.value.state.admitted != .cancelled)
                            return error.InvalidArchive;
                    } else _ = try occurrence.consumed(
                        current.value,
                        .{
                            .id = id,
                            .task = value.id,
                            .work = null,
                            .residual = current.value.residual,
                            .request = current.value.request,
                        },
                        .cancel,
                        true,
                    );
                }
            } else _ = try self.rootConsumed(a, value, accepted);
        }
        fn validateControllerAnswer(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            accepted: data.invocation.Control,
            actual: anytype,
            residual: ?state.ControllerResidual,
            historical: bool,
        ) !void {
            const reply = accepted.reply;

            if (actual != .answer or
                value.outcome_kind != .requested or
                value.current_occurrence == null)
                return error.InvalidArchive;
            var response = try data.invocation.decode(data.invocation.Result, a, reply);
            defer response.deinit();
            var occurrence_value = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                value.current_occurrence.?,
                value.id,
            );
            defer occurrence_value.deinit();
            const prior = occurrence_value.value;
            const acquired = switch (prior.state) {
                .settled_reply => |saved| saved,
                .admitted => |saved| if (historical and
                    saved == .reply) saved.reply else return error.InvalidArchive,
                else => return error.InvalidArchive,
            };
            if (prior.work != null or !std.meta.eql(
                acquired.reply,
                storage.digest(reply),
            ) or !std.meta.eql(prior.request, response.value.request_identity) or
                !same(actual.answer, response.value.value)) return error.InvalidArchive;
            if (residual) |retired| {
                if (!retired.cancellation_applied or !std.meta.eql(
                    prior.residual,
                    retired.id,
                )) return error.InvalidArchive;
                if (!historical or prior.state != .admitted) _ = try occurrence.consumed(
                    prior,
                    .{
                        .id = prior.id,
                        .task = value.id,
                        .work = null,
                        .residual = retired.id,
                        .request = prior.request,
                    },
                    .{ .reply = storage.digest(reply) },
                    true,
                );
            } else _ = try self.rootConsumed(a, value, accepted);
        }
        fn retire(self: *Self, a: std.mem.Allocator) !void {
            try self.retainRootOperation(a);
            if (self.active) |active| {
                try active.driver.retire();
                try active.driver.destroy();
                if (active.root_control) |bytes| self.allocator.free(bytes);
                self.active = null;
            }
        }
        fn resident(self: *Self, a: std.mem.Allocator, value: state.Task) !*evaluator.Driver {
            try self.compatible(value);
            if (self.active) |active| {
                if (active.subject == .root and same(&active.task, &value.id) and
                    active.execution_revision == value.execution_revision and
                    active.realization_revision == value.realization_revision)
                    return active.driver;
                try self.retire(a);
            }
            var pending = try self.rootOperation(a, value);
            defer if (pending) |*saved| saved.deinit();
            const root_control = if (pending != null and
                pending.?.value.pending != null) try self.store().object(
                self.allocator,
                pending.?.value.pending.?.control,
                null,
            ) else null;
            errdefer if (root_control) |bytes| self.allocator.free(bytes);
            var root_cut_ready = false;
            const driver = if (pending != null and pending.?.value.pending != null) restored: {
                const operation_value = pending.?.value.pending.?;
                root_cut_ready = try self.validateRootOperation(a, value, pending.?.value);
                const bytes = try self.store().object(a, operation_value.capsule, null);
                defer a.free(bytes);
                const Owner = struct {
                    task: state.Task,
                    reference: state.Reference,
                    fn claim(
                        context: *anyopaque,
                        ref: kosmos.RuntimeCapsule.Reference,
                        record_value: kosmos.RuntimeCapsule.Record,
                        _: kosmos.RuntimeCapsule.Reference,
                    ) !void {
                        const owner: *@This() = @ptrCast(@alignCast(context));
                        if (!std.meta.eql(
                            ref.digest,
                            owner.reference.digest,
                        ) or ref.bytes != owner.reference.bytes or
                            !std.meta.eql(
                                record_value.provenance,
                                rootProvenance(owner.task),
                            )) return error.InvalidArchive;
                    }
                };
                var owner: Owner = .{ .task = value, .reference = operation_value.capsule };
                var runtime = try self.controllerRuntime(
                    a,
                    value.id,
                    try self.rootImage(a, value),
                    value.controller_runtime,
                );
                defer runtime.deinit();
                const image = try self.store().object(a, try self.rootImage(a, value), null);
                defer a.free(image);
                break :restored try evaluator.Driver.openCapsule(
                    self.allocator,
                    image,
                    &runtime,
                    bytes,
                    .{ .context = &owner, .claim = Owner.claim },
                );
            } else restored: {
                const checkpoint = try self.store().object(a, value.checkpoint, null);
                defer a.free(checkpoint);
                break :restored try self.rootDriver(a, value, .{ .state = checkpoint });
            };
            self.active = .{
                .task = value.id,
                .execution_revision = value.execution_revision,
                .realization_revision = value.realization_revision,
                .driver = driver,
                .root_control = root_control,
                .root_cut_ready = root_cut_ready,
            };
            if (pending) |saved| if (saved.value.pending) |operation_value| {
                self.active.?.root_quantum = operation_value.guest_quantum;
                self.active.?.outer_operation = operation_value.capsule;
            };
            return driver;
        }
        fn submitDigest(
            a: std.mem.Allocator,
            profile_digest: state.Digest,
            input: Types.Input,
        ) !state.Digest {
            const Request = struct {
                method: state.Method,
                application: state.Name,
                profile_digest: state.Digest,
                input: Types.Input,
            };
            return operation(Request, a, .{
                .method = .submit,
                .application = try name(Types.application_id),
                .profile_digest = profile_digest,
                .input = input,
            });
        }
        pub fn submit(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            input: Types.Input,
        ) !Admission {
            try self.allowed();
            const profile_digest = try self.submissionProfileDigest(a, id);
            const request = try submitDigest(a, profile_digest, input);
            if (try self.replay(a, id, request)) |prior| return prior;
            try self.ensureOwnershipCapacity(null);
            // Reserve scheduling capacity before making acceptance durable.
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            try self.retire(a);
            var task_id: state.TaskId = undefined;
            try self.io.randomSecure(&task_id);
            const input_bytes = try contracts.encodeOwned(Types.Input, a, input);
            defer a.free(input_bytes);
            const controller_id: ?state.Digest = if (self.application.controller != null) blk: {
                var identity: state.Digest = undefined;
                try self.io.randomSecure(&identity);
                break :blk identity;
            } else null;
            const execution_input = try self.submissionExecutionInput(
                a,
                task_id,
                input,
                input_bytes,
            );
            defer a.free(execution_input);
            const driver = try evaluator.Driver.start(self.allocator, self.program, .{
                .initial_args = execution_input,
            });
            self.active = .{ .task = task_id, .execution_revision = 0, .driver = driver };
            errdefer if (!self.store().fenced) {
                self.retire(a) catch {
                    self.store().fence();
                };
            };
            const publication = try driver.drive(a, .none, 0);
            // Retain the new receipt if durable admission fails after publish.
            errdefer self.store().fence();
            const outcome = publication.outcome;
            defer a.free(outcome);
            const checkpoint = publication.checkpoint;
            const resources = try a.alloc(state.Reference, self.profile.resources.len);
            defer a.free(resources);
            try self.store().begin();
            defer self.store().rollback();
            return self.persistSubmittedTask(
                a,
                id,
                request,
                task_id,
                controller_id,
                resources,
                input_bytes,
                checkpoint,
                outcome,
            );
        }
        fn submissionProfileDigest(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
        ) !state.Digest {
            var profile_digest = storage.digest(self.profile.bytes);
            const key = try self.operationKey(a, id);
            if (try self.store().savedReceipt(a, &key)) |bytes| {
                defer a.free(bytes);
                var saved = try contracts.decodeOwned(state.Receipt, a, bytes);
                defer saved.deinit();
                if (saved.value.method == .submit) {
                    var original = try self.task(a, saved.value.task);
                    defer original.deinit();
                    // The original alias is resolved only on first admission.
                    // Retrying it after a launch configuration change recovers
                    // the original receipt and cannot rebind the existing task.
                    if (same(
                        original.value.profile_id.bytes,
                        self.profile.id,
                    )) profile_digest = original.value.profile.digest;
                }
            }

            return profile_digest;
        }
        fn submissionExecutionInput(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            input: Types.Input,
            input_bytes: []const u8,
        ) ![]u8 {
            return if (self.application.controller != null) blk: {
                if (comptime @hasDecl(
                    Types,
                    "ControllerInput",
                )) break :blk try contracts.encodeOwned(Types.ControllerInput, a, .{ .anchor = .{
                    .task = task_id,
                }, .private = .{ .initial = input } });
                return error.IncompatibleProfile;
            } else try a.dupe(u8, input_bytes);
        }
        fn submittedTask(
            self: *Self,
            task_id: state.TaskId,
            controller_id: ?state.Digest,
            resources: []const state.Reference,
            input_bytes: []const u8,
            checkpoint: []const u8,
            outcome: []const u8,
        ) !state.Task {
            return .{
                .id = task_id,
                .application_id = try name(Types.application_id),
                .input_schema_id = try name(Types.input_schema_id),
                .output_schema_id = try name(Types.output_schema_id),
                .failure_schema_id = try name(Types.failure_schema_id),
                .message_schema_id = try name(Types.message_schema_id),
                .principal = try name(self.profile.authority.principal),
                .tenant = try name(self.profile.authority.tenant),
                .profile_id = try name(self.profile.id),
                .profile = try self.store().putObject(self.profile.bytes),
                .resources = .{ .items = resources },
                .image = try self.store().putObject(self.assets.image),
                .controller = controller_id,
                .runtime_identity = self.profile.runtime_identity,
                .input = try self.store().putObject(input_bytes),
                .checkpoint = try self.store().putObject(checkpoint),
                .outcome = try self.store().putObject(outcome),
                .outcome_kind = .progressed,
                .current_occurrence = null,
                .revision = 1,
                .execution_revision = 0,
                .schedule = .queued,
                .cancellation = null,
                .cancellation_applied = false,
                .blocker = null,
                .result = null,
                .client_result = null,
                .result_artifact = null,
                .event_floor = 1,
                .event_high = 1,
                .next_message = 1,
                .messages = .{ .items = &.{} },
                .inference_attempts = 0,
                .inference_request_bytes = 0,
                .inference_output_tokens = 0,
                .evidence_bytes = 0,
            };
        }
        fn seedSubmittedController(
            self: *Self,
            _: std.mem.Allocator,
            task_id: state.TaskId,
            controller_id: state.Digest,
            image_ref: state.Reference,
            seed: discovery.SeedController,
        ) !void {
            var seed_arena = std.heap.ArenaAllocator.init(self.allocator);
            defer seed_arena.deinit();
            const seed_allocator = seed_arena.allocator();
            var descriptor = try contracts.decodeOwned(
                contracts.controller.Descriptor,
                seed_allocator,
                seed.descriptor,
            );
            defer descriptor.deinit();
            var image = try data.program_image.decode(seed_allocator, self.assets.image);
            defer image.deinit();
            const interface = try construction.interfaceOf(seed_allocator, image.program);
            defer {
                seed_allocator.free(interface.input.bytes);
                seed_allocator.free(interface.output.bytes);
                seed_allocator.free(interface.failure.bytes);
            }
            const artifact = try self.workspaceStoreProgram(
                seed_allocator,
                task_id,
                seed.source,
                .source_records,
                null,
                &.{},
                .{
                    .image = .{ .bytes = self.assets.image },
                    .interface = interface,
                    .ports = .{ .items = &.{} },
                    .controller = descriptor.value,
                },
            );
            try self.store().createRecord(
                state.ControllerBinding,
                "controller_binding",
                controller_id,
                task_id,
                .{
                    .id = controller_id,
                    .task = task_id,
                    .epoch = 0,
                    .program = artifact.digest,
                    .image = image_ref,
                    .program_identity = self.application.image_identity,
                    .predecessor = null,
                },
            );
            try self.checked_workspace_programs.put(
                self.allocator,
                artifact.digest,
                self.store().integrity_epoch,
            );
        }
        fn persistSubmittedTask(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            request: state.Digest,
            task_id: state.TaskId,
            controller_id: ?state.Digest,
            resources: []state.Reference,
            input_bytes: []const u8,
            checkpoint: []const u8,
            outcome: []const u8,
        ) !Admission {
            for (self.profile.resources, resources) |bytes, *reference|
                reference.* =
                    try self.store().putObject(bytes);
            const value = try self.submittedTask(
                task_id,
                controller_id,
                resources,
                input_bytes,
                checkpoint,
                outcome,
            );
            // Establish the referenced task before its foreign-keyed events.
            try self.store().putTask(value, null);
            if (self.application.controller) |seed| {
                try self.seedSubmittedController(a, task_id, controller_id.?, value.image, seed);
            }
            try self.createCustody(a, task_id, null);
            try self.store().putEvent(
                .{ .task = task_id, .seq = 1, .revision = 1, .kind = .accepted, .data = .{
                    .bytes = "{}",
                } },
            );
            const admitted = try self.receipt(
                a,
                .submit,
                id,
                request,
                value,
                .accepted,
                null,
                null,
            );
            try self.namespace.commit("task.submit");
            self.runnableAppendAssumeCapacity(task_id);
            self.claim(task_id);
            return admitted;
        }
        pub fn requestCancel(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            task_id: state.TaskId,
            reason: []const u8,
        ) !Admission {
            if (reason.len > 256 or !std.unicode.utf8ValidateSlice(
                reason,
            )) return error.InvalidParams;
            const request = try cancelDigest(a, task_id, .{ .bytes = reason });
            if (try self.replay(a, id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            var decoded = try self.task(a, task_id);
            defer decoded.deinit();
            var value = decoded.value;
            const previous = value.revision;
            const needs_cancellation = !value.terminal() or !try self.associatedWorkDisposed(
                a,
                task_id,
            );
            const queue_root = self.work == null or
                self.work.?.subject_work != null or
                self.work.?.subject_residual != null or
                !same(&self.work.?.task, &task_id);
            const executable = compatible: {
                self.compatible(value) catch |err| switch (err) {
                    error.IncompatibleProfile => break :compatible false,
                };
                break :compatible true;
            };
            var cleanup: std.ArrayList(workspace.Subject) = .empty;
            defer cleanup.deinit(a);
            if (needs_cancellation) {
                try self.ensureOwnershipCapacity(task_id);
            }
            if (needs_cancellation and executable) try self.cancellationCleanup(
                a,
                task_id,
                queue_root,
                &cleanup,
            );
            try applyCancellation(&value, reason, needs_cancellation, executable, queue_root);
            try self.store().begin();
            defer self.store().rollback();
            try self.event(&value, .cancellation_requested, "{}");
            const admitted = try self.receipt(
                a,
                .cancel,
                id,
                request,
                value,
                .cancellation_requested,
                null,
                null,
            );
            try self.persistScheduled(a, value, previous, "task.cancel", .preserve, cleanup.items);
            return self.applyPublishedCancellation(
                a,
                task_id,
                needs_cancellation,
                executable,
                admitted,
            );
        }
        fn applyPublishedCancellation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            needs_cancellation: bool,
            executable: bool,
            admitted: Admission,
        ) !Admission {
            // The receipt now survives retries. If applying its cancellation
            // fails, only restart recovery may resume this owner's work.
            errdefer self.store().fence();
            // Cancellation intent survives a different launch configuration,
            // but it grants no authority to run the root or retained cleanup.
            if (needs_cancellation and !executable) {
                self.claim(task_id);
                return admitted;
            }
            if (self.work) |*work| if (same(&work.task, &task_id)) {
                work.cancel_requested = true;
            };
            // A new cancellation can also interrupt admitted recovery before
            // it acquires the worker. Prior cancellation intent does not abort
            // a later explicit recovery needed to settle unknown delivery.
            try self.interruptQueuedRecoveries(a, task_id);
            if (needs_cancellation) {
                self.claim(task_id);
            }
            return admitted;
        }
        fn cancellationCleanup(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            queue_root: bool,
            cleanup: *std.ArrayList(workspace.Subject),
        ) !void {
            {
                const children = try self.workspaceIds(a, task_id);
                defer a.free(children);
                for (children) |child_id| {
                    if (!try self.hasLocalCustody(a, task_id, child_id)) continue;
                    var child = try self.retainedWorkspaceWork(a, task_id, child_id);
                    defer child.deinit();
                    // Reopening requires explicit ownership. A new cancel
                    // can continue already admitted cleanup even when the root
                    // has a result and ordinary task resume is unavailable.
                    if (!child.value.terminal() and
                        child.value.cancellation != null and
                        child.value.schedule != .parked)
                        try cleanup.append(a, .{ .task = task_id, .work = child_id });
                }
            }
            try self.appendControllerResiduals(a, task_id, cleanup);
            if (queue_root) try cleanup.append(a, .{ .task = task_id });
        }
        fn applyCancellation(
            value: *state.Task,
            reason: []const u8,
            needs_cancellation: bool,
            executable: bool,
            queue_root: bool,
        ) !void {
            value.*.revision = try std.math.add(u64, value.revision, 1);
            if (needs_cancellation and value.*.cancellation == null) value.*.cancellation = .{
                .bytes = reason,
            };
            if (needs_cancellation and !executable) {
                value.*.blocker = .incompatible_profile;
                value.*.schedule = .parked;
            } else if (executable) {
                if (value.*.blocker == .incompatible_profile) value.*.blocker = null;
                if (!value.*.terminal() and queue_root) value.*.schedule = .queued;
            }
        }
        fn interruptQueuedRecoveries(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
        ) !void {
            var query = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='reconciliation'",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            var pending_ids: std.ArrayList(state.Digest) = .empty;
            defer pending_ids.deinit(a);
            while (try query.step() == .row) {
                var item = try contracts.decodeOwned(state.Reconciliation, a, try query.bytes(0));
                defer item.deinit();
                if (item.value.outcome != .pending) continue;
                if (self.work) |work| if (std.meta.eql(
                    work.task,
                    task_id,
                )) if (work.recovery) |recovery| if (std.meta.eql(
                    recovery.id,
                    item.value.id,
                )) continue;
                try pending_ids.append(a, item.value.id);
            }
            for (pending_ids.items) |id| {
                var item = try self.record(state.Reconciliation, a, "reconciliation", id, task_id);
                defer item.deinit();
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    item.value.occurrence,
                    task_id,
                );
                defer pending.deinit();
                var parent = try self.task(a, task_id);
                defer parent.deinit();
                try self.finishRecovery(
                    a,
                    parent.value,
                    pending.value,
                    item.value,
                    null,
                    .unavailable,
                );
            }
        }
        pub fn resumeTask(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            task_id: state.TaskId,
            expected: u64,
        ) !Admission {
            const Request = struct { method: state.Method, task: state.TaskId, revision: u64 };
            const request = try operation(Request, a, .{
                .method = .@"resume",
                .task = task_id,
                .revision = expected,
            });
            if (try self.replay(a, id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            var decoded = try self.task(a, task_id);
            defer decoded.deinit();
            var value = decoded.value;
            try self.compatible(value);
            if (value.revision != expected) return error.StaleRevision;
            if (value.terminal()) return error.TerminalTask;
            try self.ensureOwnershipCapacity(task_id);
            const rearmed = try self.resumedOccurrence(a, value);
            const children = try self.workspaceIds(a, task_id);
            defer a.free(children);
            var eligible: std.ArrayList(workspace.Subject) = .empty;
            defer eligible.deinit(a);
            try eligible.append(a, .{ .task = task_id });
            for (children) |child_id| {
                var child = try self.workspaceWork(a, task_id, child_id);
                defer child.deinit();
                if (try self.workspaceRunnable(
                    a,
                    value,
                    child.value,
                )) try eligible.append(a, .{ .task = task_id, .work = child_id });
            }
            try self.appendControllerResiduals(a, task_id, &eligible);
            value.revision = try std.math.add(u64, value.revision, 1);
            value.schedule = .queued;
            value.blocker = null;
            try self.store().begin();
            defer self.store().rollback();
            if (rearmed) |pending| try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                task_id,
                pending,
            );
            try self.event(&value, .resumed, "{}");
            const admitted = try self.receipt(
                a,
                .@"resume",
                id,
                request,
                value,
                .resumed,
                null,
                null,
            );
            try self.persistScheduled(a, value, expected, "task.resume", .preserve, eligible.items);
            self.claim(task_id);
            return admitted;
        }
        fn resumedOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
        ) !?occurrence.Occurrence {
            var rearmed: ?occurrence.Occurrence = null;
            if (value.current_occurrence) |current| {
                var saved = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    current,
                    value.id,
                );
                defer saved.deinit();
                if (saved.value.state == .unknown or
                    saved.value.state == .dispatching)
                    return error.UnsettledOccurrence;
                if (saved.value.state == .not_sent) rearmed = try occurrence.rearm(saved.value, .{
                    .id = current,
                    .task = value.id,
                    .request = saved.value.request,
                });
            }
            return rearmed;
        }
        pub fn recoveryAvailability(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
        ) !?RecoveryAvailability {
            // Public recovery hints contain original IDs and compiled mechanisms,
            // never prepared bytes or an authority to provide replacement replies.
            return self.subjectRecoveryAvailability(a, task_id, null);
        }
        pub fn subjectRecoveryAvailability(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            residual_id: ?state.Digest,
        ) !?RecoveryAvailability {
            var decoded = try self.task(a, task_id);
            defer decoded.deinit();
            const value = decoded.value;
            const id = if (residual_id) |residual| blk: {
                var saved = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    residual,
                    task_id,
                );
                defer saved.deinit();
                break :blk saved.value.current_occurrence orelse return null;
            } else value.current_occurrence orelse return null;
            var pending = try self.record(occurrence.Occurrence, a, "occurrence", id, task_id);
            defer pending.deinit();
            if (pending.value.state != .unknown) return null;
            var result: RecoveryAvailability = .{
                .occurrence = id,
                .attempt = pending.value.state.unknown.id,
                .mechanisms = &.{},
            };
            self.compatible(
                value,
            ) catch |err| return if (err == error.IncompatibleProfile) result else err;
            const bytes = try self.store().object(a, pending.value.request_object, null);
            defer a.free(bytes);
            var request = try data.invocation.decode(data.invocation.Request, a, bytes);
            defer request.deinit();
            const entry = self.handlers.resolve(
                request.value,
                try self.occurrenceImage(a, value, pending.value),
            ) catch |err| switch (err) {
                error.MissingCapability,
                error.CapabilitySchemaMismatch,
                error.Denied,
                => return result,
                else => return err,
            };
            if (entry.declaration.recovery) |adapter| {
                const can_lookup = adapter.lookup != null and blk: {
                    _ = self.handlers.admit(
                        request.value,
                        self.profile.authority,
                        try self.occurrenceImage(a, value, pending.value),
                        registry.resourceIdentity(
                            self.application.image_identity,
                            value.profile.digest,
                            value.resources.items,
                        ),
                    ) catch break :blk false;
                    break :blk true;
                };
                result.mechanisms = if (adapter.rederive != null) (if (can_lookup) &.{
                    .rederive,
                    .lookup,
                } else &.{.rederive}) else if (can_lookup) &.{.lookup} else &.{};
            }
            return result;
        }
        pub fn reconciliation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !contracts.Decoded(state.Reconciliation) {
            var authorized = try self.task(a, task_id);
            defer authorized.deinit();
            return self.record(state.Reconciliation, a, "reconciliation", id, task_id);
        }
        pub fn reconcile(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            task_id: state.TaskId,
            expected: u64,
            occurrence_id: state.Digest,
            attempt_id: state.Digest,
            recovery: state.RecoveryRequest,
        ) !Admission {
            // Admit explicit recovery. Receipt lookup precedes revision/state
            // checks; pure computation completes locally, while asynchronous
            // lookup gets a sealed pending record before the worker may start.
            const request_digest = try reconcileDigest(
                a,
                task_id,
                expected,
                occurrence_id,
                attempt_id,
                recovery,
            );
            if (try self.replay(a, id, request_digest)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            var decoded = try self.task(a, task_id);
            defer decoded.deinit();
            const value = decoded.value;
            try self.compatible(value);
            if (value.revision != expected) return error.StaleRevision;
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                occurrence_id,
                task_id,
            );
            defer pending.deinit();
            try self.validateReconciliation(a, value, pending.value, occurrence_id, attempt_id);
            var attempt = try self.record(state.Attempt, a, "attempt", attempt_id, task_id);
            defer attempt.deinit();
            var original_request = try self.recoveryRequest(a, attempt.value);
            defer original_request.deinit();
            const entry = try self.handlers.resolve(
                original_request.value,
                try self.occurrenceImage(a, value, pending.value),
            );
            const asynchronous = try self.admitRecoveryMechanism(
                a,
                value,
                pending.value,
                attempt.value,
                original_request.value,
                entry,
                recovery,
                occurrence_id,
                attempt_id,
            );
            return self.publishReconciliation(
                a,
                id,
                value,
                pending.value,
                attempt.value,
                request_digest,
                recovery,
                entry,
                asynchronous,
                occurrence_id,
                attempt_id,
            );
        }
        fn recoveryRequest(
            self: *Self,
            a: std.mem.Allocator,
            attempt: state.Attempt,
        ) !data.invocation.Owned(data.invocation.Request) {
            const request_bytes = try self.store().object(a, attempt.request, null);
            defer a.free(request_bytes);
            return try data.invocation.decode(data.invocation.Request, a, request_bytes);
        }
        fn validateReconciliation(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            occurrence_id: state.Digest,
            attempt_id: state.Digest,
        ) !void {
            if (pending.work != null) return error.StaleOccurrence;
            _ = try self.occurrenceSubject(a, value, pending);
            if (pending.state != .unknown) return error.UnsettledOccurrence;
            if (!same(&pending.state.unknown.id, &attempt_id)) return error.StaleOccurrence;
            if (try self.pendingRecovery(
                a,
                value.id,
                occurrence_id,
                attempt_id,
            ) != null) return error.UnsettledOccurrence;
        }
        fn validateLookupRecovery(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            attempt: state.Attempt,
            request: data.invocation.Request,
            entry: anytype,
        ) !void {
            _ = try self.handlers.admit(
                request,
                self.profile.authority,
                try self.occurrenceImage(a, value, pending),
                registry.resourceIdentity(
                    self.application.image_identity,
                    value.profile.digest,
                    value.resources.items,
                ),
            );
            if (entry.declaration.capture) |adapter| {
                const prepared = try self.store().object(
                    a,
                    attempt.prepared orelse return error.CorruptState,
                    null,
                );
                defer a.free(prepared);
                const expected_prepared = try self.prepareProjection(
                    a,
                    value,
                    pending,
                    adapter,
                    try entry.payload(a, request.binding.payload),
                );
                defer a.free(expected_prepared);
                if (!same(prepared, expected_prepared)) return error.CorruptState;
            }
        }
        fn admitRecoveryMechanism(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            attempt: state.Attempt,
            request: data.invocation.Request,
            entry: anytype,
            recovery: state.RecoveryRequest,
            occurrence_id: state.Digest,
            attempt_id: state.Digest,
        ) !bool {
            const lookup = recovery == .lookup and
                if (entry.declaration.recovery) |adapter| adapter.lookup != null else false;
            if (lookup) try self.validateLookupRecovery(a, value, pending, attempt, request, entry);
            const rederive = recovery == .rederive and
                if (entry.declaration.recovery) |adapter| adapter.rederive != null else false;
            if (rederive) try self.validateRederivation(a, value.id, occurrence_id, attempt_id);
            const asynchronous = lookup or rederive;
            if (asynchronous) {
                try self.ensureOwnershipCapacity(value.id);
                try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            }
            return asynchronous;
        }
        fn reconciliationRecord(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            value: state.Task,
            _: occurrence.Occurrence,
            attempt: state.Attempt,
            request_digest: state.Digest,
            recovery: state.RecoveryRequest,
            entry: anytype,
            asynchronous: bool,
            reconciliation_id: state.Digest,
            occurrence_id: state.Digest,
            attempt_id: state.Digest,
        ) !state.Reconciliation {
            const task_id = value.id;
            return .{
                .id = reconciliation_id,
                .task = task_id,
                .client_operation_id = try name(id),
                .request_digest = request_digest,
                .admission_revision = value.revision,
                .occurrence = occurrence_id,
                .attempt = attempt_id,
                .original_occurrence = try self.snapshotRecord(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    occurrence_id,
                    task_id,
                ),
                .original_attempt = try self.snapshotRecord(
                    state.Attempt,
                    a,
                    "attempt",
                    attempt_id,
                    task_id,
                ),
                .request = attempt.request,
                .prepared = attempt.prepared,
                .profile = value.profile,
                .resources = value.resources,
                .capability = attempt.capability,
                .mechanism = try name(
                    if (entry.declaration.recovery) |adapter| adapter.identity else "unavailable",
                ),
                .mechanism_version = if (entry.declaration.recovery) |adapter|
                    adapter.version
                else
                    0,
                .provenance = .none,
                .outcome = .{ .unresolved = .unsupported },
                .selection = recovery,
                .owner_epoch = if (asynchronous) self.owner_epoch else null,
            };
        }
        fn publishReconciliation(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt: state.Attempt,
            request_digest: state.Digest,
            recovery: state.RecoveryRequest,
            entry: anytype,
            asynchronous: bool,
            occurrence_id: state.Digest,
            attempt_id: state.Digest,
        ) !Admission {
            var value = initial;
            const expected = initial.revision;
            const task_id = initial.id;
            var reconciliation_id: state.Digest = undefined;
            try self.io.randomSecure(&reconciliation_id);
            value.revision = try std.math.add(u64, expected, 1);
            try self.store().begin();
            defer self.store().rollback();
            var result = try self.reconciliationRecord(
                a,
                id,
                value,
                pending,
                attempt,
                request_digest,
                recovery,
                entry,
                asynchronous,
                reconciliation_id,
                occurrence_id,
                attempt_id,
            );
            if (asynchronous) try self.queueReconciliation(a, &value, &result, attempt_id);
            if (pending.residual != null) {
                if (asynchronous) try self.effectSchedule(a, &value, pending, .queued, null);
                value.schedule = initial.schedule;
                value.blocker = initial.blocker;
            }
            try self.store().createRecord(
                state.Reconciliation,
                "reconciliation",
                reconciliation_id,
                task_id,
                result,
            );
            const admitted = try self.reconciliationAdmission(
                a,
                id,
                request_digest,
                &value,
                reconciliation_id,
            );
            try self.persistOccurrence(
                a,
                value,
                expected,
                "task.reconcile",
                pending,
                asynchronous,
            );
            if (asynchronous) {
                self.claim(task_id);
            }
            return admitted;
        }
        fn queueReconciliation(
            self: *Self,
            a: std.mem.Allocator,
            value: *state.Task,
            result: *state.Reconciliation,
            attempt_id: state.Digest,
        ) !void {
            result.outcome = .pending;
            value.schedule = .queued;
            value.blocker = null;
            if (try self.store().recordBytes(a, "capture", attempt_id, value.id)) |prior| {
                defer a.free(prior);
                result.original_capture = try self.store().putObject(prior);
            }
        }
        fn reconciliationAdmission(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            request_digest: state.Digest,
            value: *state.Task,
            reconciliation_id: state.Digest,
        ) !Admission {
            const event_data = try std.fmt.allocPrint(a, "{{\"reconciliation_id\":\"{s}\"}}", .{
                std.fmt.bytesToHex(reconciliation_id, .lower),
            });
            defer a.free(event_data);
            try self.event(value, .reconciled, event_data);
            const admitted = try self.recoveryReceipt(
                a,
                .reconcile,
                id,
                request_digest,
                value.*,
                .reconciled,
                null,
                null,
                reconciliation_id,
            );
            return admitted;
        }
        fn pendingRecovery(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            occurrence_id: state.Digest,
            attempt_id: state.Digest,
        ) !?state.Digest {
            var rows = try self.store().database.prepare(
                "SELECT id FROM records WHERE kind='reconciliation' AND task=?",
                &.{.{ .blob = &task_id }},
            );
            defer rows.deinit();
            var result: ?state.Digest = null;
            while (try rows.step() == .row) {
                const bytes = try rows.bytes(0);
                if (bytes.len != 32) return error.CorruptState;
                var item = try self.record(
                    state.Reconciliation,
                    a,
                    "reconciliation",
                    bytes[0..32].*,
                    task_id,
                );
                defer item.deinit();
                if (item.value.outcome != .pending) continue;
                if (!same(&item.value.occurrence, &occurrence_id) or
                    !same(&item.value.attempt, &attempt_id))
                    continue;
                if (result != null) return error.CorruptState;
                result = item.value.id;
            }
            return result;
        }
        fn recoveryWork(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            id: state.Digest,
        ) !Step {
            if (self.work != null) return .idle;
            var saved = try self.record(state.Reconciliation, a, "reconciliation", id, value.id);
            defer saved.deinit();
            const item = saved.value;
            if (item.outcome != .pending or item.owner_epoch == null or !same(
                &item.owner_epoch.?,
                &self.owner_epoch,
            )) return error.CorruptState;
            const request = try self.store().object(self.allocator, item.request, null);
            errdefer self.allocator.free(request);
            var decoded = try data.invocation.decode(data.invocation.Request, a, request);
            defer decoded.deinit();
            const entry = if (item.selection == .rederive) try self.handlers.resolve(
                decoded.value,
                try self.occurrenceImage(a, value, pending),
            ) else self.handlers.admit(
                decoded.value,
                self.profile.authority,
                try self.occurrenceImage(a, value, pending),
                registry.resourceIdentity(
                    self.application.image_identity,
                    value.profile.digest,
                    value.resources.items,
                ),
            ) catch {
                try self.finishRecovery(a, value, pending, item, null, .unavailable);
                self.allocator.free(request);
                return .progressed;
            };
            const prepared = if (item.prepared) |ref| try self.store().object(
                self.allocator,
                ref,
                null,
            ) else null;
            errdefer if (prepared) |bytes| self.allocator.free(bytes);
            const profile = try self.store().object(self.allocator, value.profile, null);
            errdefer self.allocator.free(profile);
            const body = try contracts.encodeOwned(state.Reconciliation, self.allocator, item);
            self.work = .{
                .owner_epoch = self.owner_epoch,
                .task = value.id,
                .subject_work = pending.work,
                .subject_residual = pending.residual,
                .occurrence = pending.id,
                .attempt = item.attempt,
                .request = request,
                .prepared = prepared,
                .profile = profile,
                .entry = entry,
                .cleanup = pending.residual != null,
                .recovery = .{ .id = id, .body = body },
            };
            return .{ .work = self.work.? };
        }
        fn recoveryFinding(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            original: state.Reconciliation,
            identity: state.Digest,
            completion: RecoveryCompletion,
        ) !Recovered {
            const request_bytes = try self.store().object(a, original.request, null);
            defer a.free(request_bytes);
            var request = try data.invocation.decode(data.invocation.Request, a, request_bytes);
            defer request.deinit();
            if (!same(&request.value.request_identity, &identity)) return error.InvalidRecovery;
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                original.occurrence,
                initial.id,
            );
            defer pending.deinit();
            const entry = try self.handlers.resolve(
                request.value,
                try self.occurrenceImage(a, initial, pending.value),
            );
            if (completion == .rederived) return rederivedFinding(a, original, completion, entry);
            if (original.selection != .lookup) return error.InvalidRecovery;
            const finding = try self.store().project(
                registry.RecoveryFinding,
                a,
                self.handlers,
                try self.occurrenceProjectionBinding(a, initial, pending.value),
                struct {
                    handlers: registry.Registry,
                    input: registry.RecoveryInput,
                    evidence: []const u8,
                    pub fn run(
                        this: @This(),
                        ctx: registry.ProjectionContext,
                    ) !registry.RecoveryFinding {
                        return this.handlers.verifyRecovery(ctx, this.input, this.evidence);
                    }
                }{ .handlers = self.handlers, .input = registry.RecoveryInput.fromReconciliation(
                    original,
                    identity,
                    entry.declaration.inference,
                ), .evidence = completion.evidence },
            );
            return switch (finding) {
                .capture => |bytes| .{ .capture = bytes },
                .not_sent => .not_sent,
                .inconclusive => .inconclusive,
                .unavailable => .unavailable,
                .rejected => .rejected,
            };
        }
        fn rederivedFinding(
            a: std.mem.Allocator,
            original: state.Reconciliation,
            completion: RecoveryCompletion,
            entry: anytype,
        ) !Recovered {
            if (original.selection != .rederive or
                entry.declaration.recovery == null or
                entry.declaration.recovery.?.rederive == null)
                return error.InvalidRecovery;
            return switch (completion.rederived) {
                .unsupported => .unsupported,
                .unavailable => .unavailable,
                .inconclusive => .inconclusive,
                .rejected => .rejected,
                .result => |bytes| blk: {
                    if (entry.declaration.capture != null) break :blk .{ .capture = bytes };
                    var schema = try data.schema.decode(a, entry.resume_schema);
                    defer schema.deinit();
                    data.schema.validateValue(
                        a,
                        schema.descriptor,
                        bytes,
                    ) catch |err| switch (err) {
                        error.OutOfMemory, error.Capacity => return err,
                        else => return .rejected,
                    };
                    break :blk .{ .reply = bytes };
                },
            };
        }
        fn finishRecovery(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            original: state.Reconciliation,
            completion: ?RecoveryCompletion,
            failure: @FieldType(@FieldType(state.Reconciliation, "outcome"), "unresolved"),
        ) !void {
            try self.validateRecoveryCompletion(a, initial, pending, original);
            if (completion != null) _ = try self.occurrenceSubject(a, initial, pending);
            var arena = std.heap.ArenaAllocator.init(a);
            defer arena.deinit();
            const verified: ?Recovered = if (completion) |result| try self.recoveryFinding(
                arena.allocator(),
                initial,
                original,
                pending.request,
                result,
            ) else null;
            const advancing = if (verified) |finding| finding == .capture or
                finding == .reply or
                (finding == .not_sent and
                    pending.residual == null) else false;
            if (advancing) try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            value.schedule = .parked;
            value.blocker = .unavailable_environment;
            try self.store().begin();
            defer self.store().rollback();
            var result = try self.recoveryCompletionRecord(
                a,
                value.id,
                original,
                completion,
                failure,
            );
            try self.applyRecoveryFinding(a, &value, pending, original, &result, verified);
            if (pending.residual != null) {
                try self.effectSchedule(
                    a,
                    &value,
                    pending,
                    if (advancing) .queued else .parked,
                    if (advancing) null else .unavailable_environment,
                );
                value.schedule = initial.schedule;
                value.blocker = initial.blocker;
            }
            try self.store().putRecord(
                state.Reconciliation,
                "reconciliation",
                result.id,
                value.id,
                result,
            );
            try self.persistOccurrence(
                a,
                value,
                initial.revision,
                "recovery.complete",
                pending,
                if (pending.residual != null) advancing else value.schedule == .queued,
            );
            if (pending.residual == null and value.schedule != .queued) self.runnableRemove(
                value.id,
            );
        }
        fn recoveryCompletionRecord(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            original: state.Reconciliation,
            completion: ?RecoveryCompletion,
            failure: @FieldType(@FieldType(state.Reconciliation, "outcome"), "unresolved"),
        ) !state.Reconciliation {
            var result = original;
            result.previous = try self.snapshotRecord(
                state.Reconciliation,
                a,
                "reconciliation",
                original.id,
                task_id,
            );
            result.evidence = if (completion != null and
                completion.? == .evidence) try self.store().putObject(
                completion.?.evidence,
            ) else null;
            result.outcome = .{ .unresolved = failure };
            return result;
        }
        fn validateRecoveryCompletion(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            original: state.Reconciliation,
        ) !void {
            if (original.outcome != .pending or pending.state != .unknown or !same(
                &pending.state.unknown.id,
                &original.attempt,
            )) return error.StaleOccurrence;
            if (!std.meta.eql(original.task, initial.id) or
                !std.meta.eql(pending.task, initial.id) or
                !std.meta.eql(
                    original.occurrence,
                    pending.id,
                ) or pending.work != null) return error.StaleOccurrence;
            if (pending.residual) |id| {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    initial.id,
                );
                defer residual.deinit();
                if (!residual.value.cancellation_applied or !std.meta.eql(
                    residual.value.current_occurrence,
                    pending.id,
                )) return error.StaleOccurrence;
            } else if (!std.meta.eql(
                initial.current_occurrence,
                pending.id,
            )) return error.StaleOccurrence;
        }
        fn completeRecoveryCapture(
            self: *Self,
            a: std.mem.Allocator,
            value: *state.Task,
            pending: occurrence.Occurrence,
            original: state.Reconciliation,
            result: *state.Reconciliation,
            raw: []const u8,
        ) !void {
            const capture_value: state.Capture = .{
                .task = value.id,
                .occurrence = pending.id,
                .attempt = original.attempt,
                .request = original.prepared orelse return error.CorruptState,
                .response = try self.store().putObject(raw),
                .disposition = .complete,
                .reconciliation = original.id,
            };
            if (try self.store().recordBytes(
                a,
                "capture",
                original.attempt,
                value.id,
            )) |prior| {
                defer a.free(prior);
                if (original.original_capture == null) return error.CorruptState;
                try self.store().putRecord(
                    state.Capture,
                    "capture",
                    original.attempt,
                    value.id,
                    capture_value,
                );
            } else try self.store().createRecord(
                state.Capture,
                "capture",
                original.attempt,
                value.id,
                capture_value,
            );
            result.provenance =
                if (original.selection ==
                .rederive) .rederived else .authentic;
            result.outcome = .{ .capture_admitted = capture_value.response.? };
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                value.id,
                try occurrence.recoveredCapture(
                    pending,
                    .{
                        .id = pending.id,
                        .task = value.id,
                        .work = pending.work,
                        .residual = pending.residual,
                        .request = pending.request,
                    },
                    original.attempt,
                ),
            );
            value.schedule = .queued;
            value.blocker = null;
        }
        fn completeRecoveryReply(
            self: *Self,
            a: std.mem.Allocator,
            value: *state.Task,
            pending: occurrence.Occurrence,
            original: state.Reconciliation,
            result: *state.Reconciliation,
            bytes: []const u8,
        ) !void {
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = bytes,
            });
            defer a.free(bound);
            const ref = try self.store().putObject(bound);
            result.provenance = .rederived;
            result.outcome = .{ .reply_settled = ref };
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                value.id,
                try occurrence.acquired(
                    pending,
                    .{
                        .id = pending.id,
                        .task = value.id,
                        .work = pending.work,
                        .residual = pending.residual,
                        .request = pending.request,
                    },
                    original.attempt,
                    ref.digest,
                ),
            );
            value.schedule = .queued;
            value.blocker = null;
        }
        fn completeRecoveryNotSent(
            self: *Self,
            _: std.mem.Allocator,
            value: *state.Task,
            pending: occurrence.Occurrence,
            original: state.Reconciliation,
            result: *state.Reconciliation,
        ) !void {
            result.provenance = .authoritative;
            result.outcome = .{ .not_sent = result.evidence.? };
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                value.id,
                try occurrence.recoveredNotSent(
                    pending,
                    .{
                        .id = pending.id,
                        .task = value.id,
                        .work = pending.work,
                        .residual = pending.residual,
                        .request = pending.request,
                    },
                    original.attempt,
                ),
            );
            if (value.cancellation != null) {
                value.schedule = .queued;
                value.blocker = null;
            }
        }
        fn applyRecoveryFinding(
            self: *Self,
            a: std.mem.Allocator,
            value: *state.Task,
            pending: occurrence.Occurrence,
            original: state.Reconciliation,
            result: *state.Reconciliation,
            verified: ?Recovered,
        ) !void {
            if (verified) |finding| switch (finding) {
                .unsupported => result.outcome = .{ .unresolved = .unsupported },
                .inconclusive => result.outcome = .{ .unresolved = .inconclusive },
                .unavailable => result.outcome = .{ .unresolved = .unavailable },
                .rejected => result.outcome = .{ .unresolved = .rejected },
                .capture => |raw| try self.completeRecoveryCapture(
                    a,
                    value,
                    pending,
                    original,
                    result,
                    raw,
                ),
                .reply => |bytes| try self.completeRecoveryReply(
                    a,
                    value,
                    pending,
                    original,
                    result,
                    bytes,
                ),
                .not_sent => try self.completeRecoveryNotSent(a, value, pending, original, result),
            };
        }
        fn snapshotRecord(
            self: *Self,
            comptime T: type,
            a: std.mem.Allocator,
            comptime kind: []const u8,
            id: state.Digest,
            task_id: state.TaskId,
        ) !state.Reference {
            if (T != storage.Record(kind)) @compileError("native record type/kind mismatch");
            const bytes = (try self.store().recordBytes(
                a,
                kind,
                id,
                task_id,
            )) orelse return error.CorruptState;
            defer a.free(bytes);
            return self.store().putObject(bytes);
        }
        fn validateRederivation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            occurrence_id: state.Digest,
            attempt_id: state.Digest,
        ) !void {
            // Check the original immutable inputs before sealing recovery admission.
            // No computation or borrowed projection view escapes this call.
            var decoded = try self.task(a, task_id);
            defer decoded.deinit();
            const value = decoded.value;
            try self.compatible(value);
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                occurrence_id,
                task_id,
            );
            defer pending.deinit();
            if (pending.value.work != null) return error.StaleOccurrence;
            _ = try self.occurrenceSubject(a, value, pending.value);
            if (pending.value.state != .unknown) return error.UnsettledOccurrence;
            if (!same(&pending.value.state.unknown.id, &attempt_id)) return error.StaleOccurrence;
            var attempt = try self.record(state.Attempt, a, "attempt", attempt_id, task_id);
            defer attempt.deinit();
            const original = attempt.value;
            if (!same(&original.id, &attempt_id) or
                !same(&original.task, &task_id) or
                !same(&original.occurrence, &occurrence_id) or
                !std.meta.eql(original.profile, value.profile) or !std.meta.eql(
                original.request,
                pending.value.request_object,
            )) return error.CorruptState;
            const input: registry.RecoveryInput = .{
                .task = task_id,
                .occurrence = occurrence_id,
                .attempt = attempt_id,
                .request_identity = pending.value.request,
                .request = original.request,
                .prepared = original.prepared,
                .profile = original.profile,
                .resources = value.resources.items,
                .capability = original.capability.bytes,
                .inference = original.inference,
            };
            return self.store().project(
                void,
                a,
                self.handlers,
                try self.occurrenceProjectionBinding(a, value, pending.value),
                struct {
                    handlers: registry.Registry,
                    input: registry.RecoveryInput,
                    pub fn run(this: @This(), ctx: registry.ProjectionContext) !void {
                        return this.handlers.validateRederivation(ctx, this.input);
                    }
                }{ .handlers = self.handlers, .input = input },
            );
        }
        fn messageDigest(
            a: std.mem.Allocator,
            task_id: state.TaskId,
            input: Types.Message,
        ) !state.Digest {
            const Request = struct {
                method: state.Method,
                task: state.TaskId,
                schema: state.Name,
                value: Types.Message,
            };
            return operation(Request, a, .{
                .method = .message,
                .task = task_id,
                .schema = try name(Types.message_schema_id),
                .value = input,
            });
        }
        pub fn message(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            task_id: state.TaskId,
            input: Types.Message,
        ) !Admission {
            const request = try messageDigest(a, task_id, input);
            if (try self.replay(a, id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            var decoded = try self.task(a, task_id);
            defer decoded.deinit();
            var value = decoded.value;
            if (value.terminal() or value.cancellation != null) return error.TerminalTask;
            // Input belongs to the saved application's contract, independently
            // of which launch profile will eventually resume its execution.
            try self.compatibleApplication(value);
            if (!same(
                value.message_schema_id.bytes,
                Types.message_schema_id,
            )) return error.IncompatibleProfile;
            if (!self.acceptsMessages()) return error.UnsupportedCapability;
            const bytes = try contracts.encodeOwned(Types.Message, a, input);
            defer a.free(bytes);
            var identity: state.Digest = undefined;
            try self.io.randomSecure(&identity);
            const previous = value.revision;
            value.revision = try std.math.add(u64, previous, 1);
            const ordinal = value.next_message;
            value.next_message = try std.math.add(u64, ordinal, 1);
            const queue = try a.alloc(state.Digest, value.messages.items.len + 1);
            defer a.free(queue);
            @memcpy(queue[0..value.messages.items.len], value.messages.items);
            queue[queue.len - 1] = identity;
            value.messages = .{ .items = queue };
            try self.store().begin();
            defer self.store().rollback();
            const saved: state.Message = .{
                .id = identity,
                .task = task_id,
                .ordinal = ordinal,
                .schema_id = try name(Types.message_schema_id),
                .value = try self.store().putObject(bytes),
                .disposition = .queued,
                .occurrence = null,
            };
            try self.store().createRecord(state.Message, "message", identity, task_id, saved);
            try self.messageEvent(a, &value, .message_queued, saved);
            const admitted = try self.receipt(
                a,
                .message,
                id,
                request,
                value,
                .queued,
                identity,
                null,
            );
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            try self.persist(a, value, previous, "task.message", .preserve);
            return admitted;
        }
        pub fn respond(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            task_id: state.TaskId,
            question_id: state.Digest,
            revision: u64,
            request_digest: state.Digest,
            schema_id: []const u8,
            answer_json: json.Value,
        ) !Admission {
            var decoded = try self.task(a, task_id);
            defer decoded.deinit();
            const value = decoded.value;
            // Client-selected identities may be absent without corrupting the
            // store. Missing references from durable state still use record().
            const question_bytes = (try self.store().recordBytes(
                a,
                "question",
                question_id,
                task_id,
            )) orelse {
                // Missing durable current-question references remain storage
                // corruption even when discovered during a client lookup.
                var current = try self.pendingQuestion(a, task_id);
                if (current) |*question| question.deinit();
                return error.StaleInteraction;
            };
            defer a.free(question_bytes);
            var question_decoded = try contracts.decodeOwned(state.Question, a, question_bytes);
            defer question_decoded.deinit();
            const question = question_decoded.value;
            if (question.revision != revision or !same(
                &question.request_digest,
                &request_digest,
            ) or !same(
                question.answer_schema_id.bytes,
                schema_id,
            )) return error.StaleInteraction;
            const answer = try self.encodeAnswer(a, schema_id, question, answer_json);
            defer a.free(answer);
            const request = try answerDigest(
                a,
                task_id,
                question_id,
                revision,
                request_digest,
                schema_id,
                answer,
            );
            if (try self.replay(a, id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            if (question.answer != null) return self.replayAnswer(a, id, request, question, answer);
            return self.admitAnswer(a, id, request, value, question, question_id, answer);
        }
        fn encodeAnswer(
            self: *Self,
            a: std.mem.Allocator,
            schema_id: []const u8,
            question: state.Question,
            answer_json: json.Value,
        ) ![]u8 {
            var answer_bytes: ?[]u8 = null;
            for (self.handlers.entries) |entry| {
                if (entry.declaration.kind == .question and same(
                    entry.declaration.answer_schema_id.?,
                    schema_id,
                ) and same(
                    &storage.digest(entry.resume_schema),
                    &question.answer_schema_digest,
                )) {
                    answer_bytes = try entry.declaration.answer.?(a, answer_json);
                    break;
                }
            }
            return answer_bytes orelse error.IncompatibleProfile;
        }
        fn replayAnswer(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            request: state.Digest,
            question: state.Question,
            answer: []const u8,
        ) !Admission {
            const saved_answer = question.answer.?;

            if (!same(
                &saved_answer.digest,
                &storage.digest(answer),
            )) return error.AnswerConflict;
            const original = question.receipt orelse return error.CorruptState;
            const bytes = try contracts.encodeOwned(state.Receipt, a, original);
            defer a.free(bytes);
            const key = try self.operationKey(a, id);
            try self.store().begin();
            defer self.store().rollback();
            try self.store().putReceipt(&key, request, bytes);
            try self.namespace.commit("task.respond.replay");
            var retained = original;
            retained.client_operation_id = .{
                .bytes = try a.dupe(u8, original.client_operation_id.bytes),
            };
            return .{ .receipt = retained, .replayed = true };
        }
        fn admitAnswer(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            request: state.Digest,
            value: state.Task,
            question: state.Question,
            question_id: state.Digest,
            answer: []const u8,
        ) !Admission {
            const task_id = value.id;
            if (question.retired or
                value.terminal() or
                (value.cancellation != null and
                    !value.cancellation_applied) or
                value.current_occurrence == null or
                !same(
                    &value.current_occurrence.?,
                    &question.occurrence,
                )) return error.StaleInteraction;
            try self.admitQuestionRequest(a, value, question);
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                question.occurrence,
                task_id,
            );
            defer pending.deinit();
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = question.request_digest,
                .value = answer,
            });
            defer a.free(bound);
            const binding: occurrence.Binding = .{
                .id = pending.value.id,
                .task = task_id,
                .request = pending.value.request,
            };
            const acquired = try occurrence.answered(
                pending.value,
                binding,
                question_id,
                question.pending_digest,
                storage.digest(answer),
                storage.digest(bound),
                false,
            );
            try self.ensureOwnershipCapacity(task_id);
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            return self.publishAnswer(
                a,
                id,
                request,
                value,
                question,
                question_id,
                answer,
                bound,
                acquired,
            );
        }
        fn admitQuestionRequest(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            question: state.Question,
        ) !void {
            const original_request = try self.store().object(a, question.request, null);
            defer a.free(original_request);
            var admitted_request = try data.invocation.decode(
                data.invocation.Request,
                a,
                original_request,
            );
            defer admitted_request.deinit();
            _ = try self.handlers.admit(
                admitted_request.value,
                self.profile.authority,
                try self.rootProgramIdentity(a, value),
                registry.resourceIdentity(
                    self.application.image_identity,
                    value.profile.digest,
                    value.resources.items,
                ),
            );
        }
        fn publishAnswer(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            request: state.Digest,
            initial: state.Task,
            original_question: state.Question,
            question_id: state.Digest,
            answer: []const u8,
            bound: []const u8,
            acquired: occurrence.Occurrence,
        ) !Admission {
            var value = initial;
            var question = original_question;
            const task_id = value.id;
            const previous = value.revision;
            value.revision = try std.math.add(u64, previous, 1);
            value.schedule = .queued;
            try self.store().begin();
            defer self.store().rollback();
            question.answer = try self.store().putObject(answer);
            _ = try self.store().putObject(bound);
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                acquired.id,
                task_id,
                acquired,
            );
            try self.event(&value, .input_accepted, "{}");
            const admitted = try self.receipt(
                a,
                .respond,
                id,
                request,
                value,
                .answer_acquired,
                null,
                question_id,
            );
            question.receipt = admitted.receipt;
            try self.store().putRecord(state.Question, "question", question_id, task_id, question);
            try self.persistScheduled(a, value, previous, "task.respond", .preserve, &.{.{
                .task = task_id,
            }});
            self.claim(task_id);
            return admitted;
        }
        fn blocked(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            blocker: state.Blocker,
        ) !Step {
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            value.blocker = blocker;
            value.schedule = .parked;
            try self.store().begin();
            defer self.store().rollback();
            try self.event(&value, .blocked, "{}");
            try self.persist(a, value, initial.revision, "task.blocked", .preserve);
            self.runnableRemove(value.id);
            try self.retire(a);
            return .waiting;
        }
        pub fn pump(self: *Self, a: std.mem.Allocator) !Step {
            // At most one bounded Kosmos quantum or one durable environmental
            // transition. The caller services its control channel between calls.
            try self.allowed();
            if (try self.pumpPlacement(a)) return .progressed;
            const cleanup_count = self.owned.items.len;
            if (try self.pumpOwnedCleanup(a, @min(cleanup_count, 1))) return .progressed;
            const step = try self.pumpRunnable(a);
            if (step != .idle or cleanup_count <= 1) return step;
            if (try self.pumpOwnedCleanup(a, cleanup_count - 1)) return .progressed;
            return self.pumpRunnable(a);
        }
        fn pumpRunnable(self: *Self, a: std.mem.Allocator) !Step {
            // Scan one round, without charging or preparing blocked leaves.
            // Each actual transition yields back to the host control channel.
            const count = self.runnable.items.len;
            for (0..count) |_| {
                if (self.runnable.items.len == 0) break;
                const id = self.runnable.items[self.runnable_cursor];
                self.runnable_cursor += 1;
                if (self.runnable_cursor == self.runnable.items.len) self.runnable_cursor = 0;
                const step = (if (id.residual) |residual_id|
                    self.pumpControllerResidual(a, id.task, residual_id)
                else if (id.work) |work_id|
                    self.pumpWorkspace(a, id.task, work_id)
                else
                    self.pumpTask(a, id.task)) catch |err| switch (err) {
                    error.ObservationBlocked,
                    error.SemanticPolicyDenied,
                    error.GuardPolicyDenied,
                    => .idle,
                    else => return err,
                };
                if (step != .idle) return step;
            }
            return .idle;
        }
        fn pumpOwnedCleanup(self: *Self, a: std.mem.Allocator, count: usize) !bool {
            // Cancellation is a retained obligation, independent of root runnable
            // membership. Custody changes need no producer-specific wake-up.
            for (0..count) |_| {
                if (self.owned.items.len == 0) break;
                const id = self.owned.items[self.cleanup_cursor];
                self.cleanup_cursor = (self.cleanup_cursor + 1) % self.owned.items.len;
                const controller = try self.hasLocalCustody(a, id, null);
                var parent = try self.task(a, id);
                defer parent.deinit();
                self.compatible(parent.value) catch continue;
                if (try self.settleWorkspaceOne(a, parent.value, controller)) return true;
                if (!controller) continue;
                if (try self.settleControllerResiduals(a, parent.value)) return true;
                if (try self.rootCleanupRunnable(a, parent.value)) try self.runnableAdd(id);
                if (parent.value.terminal() and try self.taskCleanupComplete(
                    a,
                    parent.value,
                )) self.unclaim(id);
            }
            return false;
        }
        fn settleControllerResiduals(self: *Self, a: std.mem.Allocator, parent: state.Task) !bool {
            const ids = try self.controllerResidualIds(a, parent.id);
            defer a.free(ids);
            for (ids) |id| {
                var saved = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    parent.id,
                );
                defer saved.deinit();
                const residual = saved.value;
                if (residual.outcome_kind == .completed or
                    residual.outcome_kind == .failed or
                    residual.outcome_kind == .cancelled)
                    continue;
                if (residual.schedule != .parked) {
                    try self.subjectAdd(.{ .task = parent.id, .residual = id });
                } else if (parent.cancellation != null and try self.residualCancellationPending(
                    a,
                    parent.id,
                    id,
                )) {
                    const operation_id = try std.fmt.allocPrint(a, "residual-cancel-{s}-{d}", .{
                        std.fmt.bytesToHex(id, .lower),
                        residual.control_revision,
                    });
                    defer a.free(operation_id);
                    _ = self.controllerResidualControl(
                        a,
                        operation_id,
                        parent.id,
                        id,
                        residual.execution_revision,
                        residual.control_revision,
                        .{ .cancel = parent.cancellation.? },
                    ) catch |err| switch (err) {
                        error.UnsettledOccurrence => continue,
                        else => return err,
                    };
                    return true;
                }
            }
            return false;
        }
        fn residualCancellationPending(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !bool {
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? ORDER BY e.seq DESC",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            const expected = std.fmt.bytesToHex(id, .lower);
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer saved.deinit();
                if (saved.value.kind == .cancellation_requested) return true;
                if (saved.value.kind == .reconciled) {
                    var data_value = try json.parse(a, saved.value.data.bytes, .{});
                    defer data_value.deinit();
                    const text = try json.text(
                        json.get(
                            data_value.value,
                            "reconciliation_id",
                        ) orelse return error.CorruptState,
                    );
                    var recovery_id: state.Digest = undefined;
                    if (text.len != 64) return error.CorruptState;
                    _ = try std.fmt.hexToBytes(&recovery_id, text);
                    var recovery = try self.record(
                        state.Reconciliation,
                        a,
                        "reconciliation",
                        recovery_id,
                        task_id,
                    );
                    defer recovery.deinit();
                    var pending = try self.record(
                        occurrence.Occurrence,
                        a,
                        "occurrence",
                        recovery.value.occurrence,
                        task_id,
                    );
                    defer pending.deinit();
                    if (std.meta.eql(pending.value.residual, id)) return false;
                }
                const ref = saved.value.workspace_command orelse continue;
                const bytes = try self.store().object(a, ref, null);
                defer a.free(bytes);
                var command = try contracts.decodeOwned(workspace.PublicationCommand, a, bytes);
                defer command.deinit();
                if (command.value != .residual or
                    (command.value.residual.command != .park and
                        command.value.residual.command != .cancel))
                    continue;
                var event_data = try json.parse(a, saved.value.data.bytes, .{});
                defer event_data.deinit();
                const identity = json.get(
                    event_data.value,
                    "workspace_id",
                ) orelse return error.CorruptState;
                if (identity == .string and same(identity.string, &expected)) return false;
            }
            return false;
        }
        fn rootCleanupRunnable(self: *Self, a: std.mem.Allocator, value: state.Task) !bool {
            if (value.cancellation == null or
                value.terminal() or
                value.schedule == .parked)
                return false;
            if (!value.cancellation_applied) return true;
            const id = value.current_occurrence orelse return true;
            var pending = try self.record(occurrence.Occurrence, a, "occurrence", id, value.id);
            defer pending.deinit();
            return pending.value.state != .awaiting and pending.value.state != .not_sent;
        }
        fn pumpTask(self: *Self, a: std.mem.Allocator, id: state.TaskId) !Step {
            self.requireCustody(a, id, null) catch |err| {
                if (err != error.CustodyNotLocal) return err;
                self.runnableRemove(id);
                return .idle;
            };
            var decoded = try self.task(a, id);
            defer decoded.deinit();
            const value = decoded.value;
            if (value.terminal()) {
                self.runnableRemove(id);
                if (try self.taskCleanupComplete(a, value)) self.unclaim(id);
                return .progressed;
            }
            self.compatible(value) catch return self.blocked(a, value, .incompatible_profile);
            if (value.controller_succession) |succession| return self.pumpControllerSuccession(
                a,
                value,
                succession,
            );
            if (self.active) |active| {
                if (active.subject == .root and std.meta.eql(
                    active.task,
                    id,
                ) and active.root_control != null) return self.pumpRoot(a, value);
            }
            var saved_operation = try self.rootOperation(a, value);
            defer if (saved_operation) |*saved| saved.deinit();
            if (saved_operation != null and
                saved_operation.?.value.pending != null)
                return self.pumpRoot(a, value);
            return self.pumpTaskOccurrence(a, value);
        }
        fn pumpTaskOccurrence(self: *Self, a: std.mem.Allocator, value: state.Task) !Step {
            const id = value.id;
            var current: ?contracts.Decoded(occurrence.Occurrence) = null;
            defer if (current) |*item| item.deinit();
            if (value.current_occurrence) |identity| current = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                identity,
                id,
            );
            var control: data.invocation.Control = .none;
            if (current) |item| {
                return self.pumpPendingOccurrence(a, value, item.value);
            } else if (value.cancellation != null and !value.cancellation_applied) {
                control = .{ .cancel = .{ .text = value.cancellation.?.bytes } };
            } else if (value.outcome_kind == .yielded) {
                control = .resume_yield;
            }
            return self.advance(a, value, control, null);
        }
        fn pumpPendingOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
        ) !Step {
            const id = value.id;
            var control: data.invocation.Control = .none;
            var consumed: ?occurrence.Occurrence = null;
            var reply: ?[]u8 = null;
            defer if (reply) |bytes| a.free(bytes);

            const binding: occurrence.Binding = .{
                .id = pending.id,
                .task = id,
                .request = pending.request,
            };
            switch (pending.state) {
                .captured => return self.interpretCapture(a, value, pending),
                .unknown => |attempt| return self.pumpUnknownOccurrence(a, value, pending, attempt),
                .dispatching => |attempt| {
                    // This worker still owns the attempt even when another
                    // task now owns the sole physical Kosmos resident.
                    if (self.work) |work| if (same(&work.task, &id) and
                        same(&work.occurrence, &pending.id) and
                        same(&work.attempt, &attempt.id))
                        return .idle;
                    return self.blocked(a, value, .unavailable_environment);
                },
                .settled_reply => |acquired| {
                    reply = try self.store().acquiredObject(a, acquired.reply, null);
                    consumed = try occurrence.consumed(
                        pending,
                        binding,
                        .{ .reply = acquired.reply },
                        value.cancellation != null,
                    );
                    control = .{ .reply = reply.? };
                },
                .ready, .awaiting, .not_sent => {
                    if (value.cancellation != null and !value.cancellation_applied) {
                        consumed = try occurrence.consumed(pending, binding, .cancel, true);
                        control = .{ .cancel = .{ .text = value.cancellation.?.bytes } };
                    } else if (pending.state == .awaiting or pending.state == .not_sent) {
                        self.runnableRemove(id);
                        try self.retire(a);
                        return .waiting;
                    } else return self.dispatch(a, value, pending);
                },
                .admitted => return error.CorruptState,
            }
            return self.advance(a, value, control, consumed);
        }
        fn pumpUnknownOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            attempt: anytype,
        ) !Step {
            if (self.work) |work| if (work.recovery != null and same(
                &work.task,
                &value.id,
            ) and
                same(&work.occurrence, &pending.id) and
                same(&work.attempt, &attempt.id))
                return .idle;
            if (try self.pendingRecovery(
                a,
                value.id,
                pending.id,
                attempt.id,
            )) |recovery_id| return self.recoveryWork(a, value, pending, recovery_id);
            return self.blocked(a, value, .unavailable_environment);
        }
        fn advance(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            control: data.invocation.Control,
            consumed: ?occurrence.Occurrence,
        ) !Step {
            if (initial.cancellation == null) try self.requireRuntimePolicy(
                a,
                initial.id,
                initial.controller_runtime,
            );
            try self.requireCustody(a, initial.id, null);
            const driver = try self.resident(a, initial);
            const quantum: u64 = if (control == .reply and
                initial.cancellation != null and
                !initial.cancellation_applied) 0 else 256;
            _ = consumed;
            const encoded_control = try contracts.encodeOwned(
                data.invocation.Control,
                self.allocator,
                control,
            );
            driver.beginAdvance(control, quantum) catch |err| {
                self.allocator.free(encoded_control);
                return err;
            };
            self.active.?.root_control = encoded_control;
            self.active.?.root_quantum = quantum;
            return self.pumpRoot(a, initial);
        }
        fn pumpRoot(self: *Self, a: std.mem.Allocator, initial: state.Task) anyerror!Step {
            if (initial.cancellation == null) try self.requireRuntimePolicy(
                a,
                initial.id,
                initial.controller_runtime,
            );
            const driver = try self.resident(a, initial);
            var decoded = try contracts.decodeOwned(
                data.invocation.Control,
                a,
                self.active.?.root_control orelse return error.CorruptState,
            );
            defer decoded.deinit();
            const control = decoded.value;
            const consumed = try self.rootConsumed(a, initial, control);
            if (!try self.rootCutReady(driver)) return .progressed;
            // Publication is transactional too. Keep the completed-cut phase
            // on failure so retry cannot apply the accepted command twice.
            const publication = try driver.drive(a, .none, 0);
            self.allocator.free(self.active.?.root_control.?);
            self.active.?.root_control = null;
            self.active.?.root_cut_ready = false;
            const encoded = publication.outcome;
            defer a.free(encoded);
            // Kosmos may now be ahead of storage. Any failure below fences all
            // further effects; restart uses the old checkpoint and saved reply.
            errdefer self.store().fence();
            var outcome = try data.invocation.decode(data.invocation.Outcome, a, encoded);
            defer outcome.deinit();
            if (outcome.value == .needs_capacity) return error.Capacity;
            var checked_output: ?contracts.Decoded(Types.Output) = null;
            defer if (checked_output) |*checked| checked.deinit();
            var checked_failure: ?contracts.Decoded(Types.Failure) = null;
            defer if (checked_failure) |*checked| checked.deinit();
            if (outcome.value == .completed) {
                checked_output = self.decodeRootResult(
                    Types.Output,
                    a,
                    initial,
                    outcome.value.completed,
                ) catch |err| {
                    if (err != error.InvalidResultReference) return err;
                    return self.rejectResult(a, initial, driver);
                };
            } else if (outcome.value == .failed) {
                checked_failure = self.decodeRootResult(
                    Types.Failure,
                    a,
                    initial,
                    outcome.value.failed.value,
                ) catch |err| {
                    if (err != error.InvalidResultReference) return err;
                    return self.rejectResult(a, initial, driver);
                };
            }
            return self.publishRootCut(
                a,
                initial,
                driver,
                control,
                consumed,
                publication.checkpoint,
                encoded,
                outcome.value,
                checked_output,
                checked_failure,
            );
        }
        fn rootCutReady(self: *Self, driver: *evaluator.Driver) !bool {
            // Physical pumping is transactional. An allocation failure leaves
            // the accepted operation live and retryable without fencing storage.
            if (!self.active.?.root_cut_ready) {
                var progress = try driver.pump(65536);
                defer progress.deinit();
                if (progress == .suspended) return false;
                if (progress != .event or
                    progress.event.value != .cut)
                    return error.InvalidRuntimeProgress;
                self.active.?.root_cut_ready = true;
            }
            return true;
        }
        fn decodeRootResult(
            self: *Self,
            comptime T: type,
            a: std.mem.Allocator,
            initial: state.Task,
            bytes: []const u8,
        ) !contracts.Decoded(T) {
            var decoded = try contracts.decodeOwned(T, a, bytes);
            errdefer decoded.deinit();
            try self.validateResult(T, a, initial, decoded.value);
            return decoded;
        }
        fn consumeRootOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            value: *state.Task,
            prior: occurrence.Occurrence,
        ) !void {
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                prior.id,
                value.id,
                prior,
            );
            const question_id: ?state.Digest = switch (prior.state.admitted) {
                .reply => |acquired| if (acquired.answer) |answer| answer.question else null,
                .cancelled => |waiting| if (waiting) |question| question.question else null,
            };
            if (question_id) |id| {
                var saved = try self.record(state.Question, a, "question", id, value.id);
                defer saved.deinit();
                saved.value.retired = true;
                try self.store().putRecord(
                    state.Question,
                    "question",
                    id,
                    value.id,
                    saved.value,
                );
            }
            if (value.messages.items.len != 0) {
                const message_id = value.messages.items[0];
                var saved = try self.record(state.Message, a, "message", message_id, value.id);
                defer saved.deinit();
                if (saved.value.disposition == .acquired and
                    saved.value.occurrence != null and
                    same(&saved.value.occurrence.?, &prior.id))
                {
                    saved.value.disposition = .consumed;
                    try self.store().putRecord(
                        state.Message,
                        "message",
                        message_id,
                        value.id,
                        saved.value,
                    );
                    value.messages.items = value.messages.items[1..];
                    try self.messageEvent(a, value, .message_consumed, saved.value);
                }
            }
        }
        fn publishRootRequest(
            self: *Self,
            a: std.mem.Allocator,
            value: *state.Task,
            pending: anytype,
        ) !void {
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                pending.request,
            );
            defer request.deinit();
            var id: state.Digest = undefined;
            try self.io.randomSecure(&id);
            const next: occurrence.Occurrence = .{
                .id = id,
                .task = value.id,
                .request = request.value.request_identity,
                .request_object = try self.store().putObject(pending.request),
            };
            try self.store().createRecord(
                occurrence.Occurrence,
                "occurrence",
                id,
                value.id,
                next,
            );
            const interaction = try self.controllerRequest(a, value.*, id, request.value);
            try self.store().createRecord(
                workspace.ExecutionRoute,
                "execution_route",
                id,
                value.id,
                .{
                    .id = id,
                    .task = value.id,
                    .work = null,
                    .image = try self.rootImage(a, value.*),
                    .program_identity = request.value.binding.program_identity,
                    .controller = value.controller,
                    .controller_epoch = value.controller_epoch,
                    .interaction = interaction,
                },
            );
            value.current_occurrence = id;
            value.outcome_kind = .requested;
        }
        fn publishRootOutcome(
            self: *Self,
            a: std.mem.Allocator,
            value: *state.Task,
            outcome: data.invocation.Outcome,
            checked_output: ?contracts.Decoded(Types.Output),
            checked_failure: ?contracts.Decoded(Types.Failure),
        ) !void {
            switch (outcome) {
                .progressed => value.outcome_kind = .progressed,
                .yielded => value.outcome_kind = .yielded,
                .requested => |pending| try self.publishRootRequest(a, value, pending),
                .completed => |bytes| {
                    value.outcome_kind = .completed;
                    value.result = try self.store().putObject(bytes);
                    try self.clientResult(
                        Types.Output,
                        a,
                        value,
                        Types.output_schema_id,
                        checked_output.?.value,
                    );
                    try self.event(value, .completed, "{}");
                },
                .failed => {
                    value.outcome_kind = .failed;
                    value.result = value.outcome;
                    try self.clientResult(
                        Types.Failure,
                        a,
                        value,
                        Types.failure_schema_id,
                        checked_failure.?.value,
                    );
                    try self.event(value, .failed, "{}");
                },
                .cancelled => {
                    value.outcome_kind = .cancelled;
                    value.result = value.outcome;
                    try self.event(value, .cancelled, "{}");
                },
                .needs_capacity => unreachable,
            }
        }
        fn retireRootMessages(self: *Self, a: std.mem.Allocator, value: *state.Task) !void {
            value.schedule = .parked;
            for (value.messages.items) |id| {
                var saved = try self.record(state.Message, a, "message", id, value.id);
                defer saved.deinit();
                saved.value.disposition = .not_consumed;
                try self.store().putRecord(state.Message, "message", id, value.id, saved.value);
                try self.messageEvent(a, value, .message_not_consumed, saved.value);
            }
            value.messages.items = &.{};
        }
        fn settleTerminalRoot(self: *Self, a: std.mem.Allocator, value: state.Task) !void {
            self.runnableRemove(value.id);
            const children = try self.workspaceIds(a, value.id);
            defer a.free(children);
            for (children) |child_id| {
                if (!try self.hasLocalCustody(a, value.id, child_id)) continue;
                var child = try self.workspaceWork(a, value.id, child_id);
                defer child.deinit();
                if (child.value.cancellation == null and !child.value.terminal()) {
                    try self.parkWorkspaceOnClose(a, value.id, child_id);
                    self.subjectRemove(.{ .task = value.id, .work = child_id });
                }
            }
            if (try self.taskCleanupComplete(a, value)) self.unclaim(value.id);
        }
        fn publishRootCut(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            driver: *evaluator.Driver,
            control: data.invocation.Control,
            consumed: ?occurrence.Occurrence,
            checkpoint: []const u8,
            encoded: []const u8,
            outcome: data.invocation.Outcome,
            checked_output: ?contracts.Decoded(Types.Output),
            checked_failure: ?contracts.Decoded(Types.Failure),
        ) !Step {
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            value.execution_revision = try std.math.add(u64, value.execution_revision, 1);
            value.current_occurrence = null;
            value.schedule = .active;
            value.blocker = null;
            if (control == .cancel) value.cancellation_applied = true;
            try self.store().begin();
            defer self.store().rollback();
            value.checkpoint = try self.store().putObject(checkpoint);
            value.outcome = try self.store().putObject(encoded);
            try self.subjectPublicationEvent(&value, .execution, "{}", &.{}, &.{}, null, null, .{
                .before = .from(initial),
                .after = .from(value),
            });
            // Terminal state has no remaining guest cleanup. Its checkpoint
            // and outcome are now owned by the transaction, so release the
            // physical evaluator before materializing potentially much larger
            // client JSON. Failure below still fences the uncommitted owner;
            // restart uses the prior durable cut and acquired reply.
            if (outcome == .completed or
                outcome == .failed or
                outcome == .cancelled)
            {
                try driver.close();
                try driver.destroy();
                self.active = null;
            }
            if (consumed) |prior| try self.consumeRootOccurrence(a, &value, prior);
            try self.publishRootOutcome(a, &value, outcome, checked_output, checked_failure);
            if (value.terminal()) try self.retireRootMessages(a, &value);
            try self.putRootOperation(a, .{
                .id = rootIdentity(value.id),
                .task = value.id,
                .execution_revision = value.execution_revision,
                .pending = null,
            });
            try self.persist(a, value, initial.revision, "world.advance", .preserve);
            if (self.active) |*active| {
                active.outer_operation = null;
                active.execution_revision = value.execution_revision;
            }
            if (value.terminal()) try self.settleTerminalRoot(a, value);
            return .progressed;
        }
        fn rejectResult(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            driver: *evaluator.Driver,
        ) !Step {
            try driver.close();
            try driver.destroy();
            self.active = null;
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            value.blocker = .denied;
            value.schedule = .parked;
            try self.store().begin();
            defer self.store().rollback();
            try self.putRootOperation(a, .{
                .id = rootIdentity(value.id),
                .task = value.id,
                .execution_revision = value.execution_revision,
                .pending = null,
            });
            try self.event(&value, .blocked, "{\"reason\":\"InvalidResultReference\"}");
            try self.persist(a, value, initial.revision, "task.blocked", .preserve);
            self.runnableRemove(value.id);
            return .waiting;
        }
        fn clientResult(
            self: *Self,
            comptime T: type,
            a: std.mem.Allocator,
            value: *state.Task,
            schema_id: []const u8,
            result: T,
        ) !void {
            const bytes = try json.canonicalBounded(
                self.allocator,
                try values.toJson(T, a, result),
                try self.store().database.blobLimit(),
            );
            defer self.allocator.free(bytes);
            value.client_result = try self.store().putObject(bytes);
            if (bytes.len > 60 * 1024) {
                var id: state.Digest = undefined;
                try self.io.randomSecure(&id);
                const artifact: state.Artifact = .{
                    .id = id,
                    .task = value.id,
                    .value = value.client_result.?,
                    .media_type = .{ .bytes = "application/json" },
                    .schema_id = try name(schema_id),
                };
                try self.store().createRecord(state.Artifact, "artifact", id, value.id, artifact);
                value.result_artifact = id;
            }
        }
        const ResultAdmission = resultAdmissionType();
        fn resultAdmissionType() type {
            return struct {
                service: *Self,
                allocator: std.mem.Allocator,
                task: state.TaskId,
                profile: state.Digest,

                pub fn projected(this: @This(), reference: anytype, identity: []const u8) ![]u8 {
                    const host = this.service;
                    const a = this.allocator;
                    const owners = try host.store().projectionOwners(
                        a,
                        this.task,
                        reference.digest,
                    );
                    defer a.free(owners);
                    var parent = try host.task(a, this.task);
                    defer parent.deinit();
                    for (owners) |owner| {
                        if (owner.object.bytes != reference.bytes) continue;
                        var attempt = try host.record(
                            state.Attempt,
                            a,
                            "attempt",
                            owner.attempt,
                            this.task,
                        );
                        defer attempt.deinit();
                        if (!std.meta.eql(
                            attempt.value.profile,
                            parent.value.profile,
                        )) return error.CorruptState;
                        const bytes = try host.store().object(a, attempt.value.request, null);
                        defer a.free(bytes);
                        var request = try data.invocation.decode(data.invocation.Request, a, bytes);
                        defer request.deinit();
                        var pending = try host.record(
                            occurrence.Occurrence,
                            a,
                            "occurrence",
                            attempt.value.occurrence,
                            this.task,
                        );
                        defer pending.deinit();
                        const entry = try host.handlers.resolve(
                            request.value,
                            try host.occurrenceImage(a, parent.value, pending.value),
                        );
                        if (same(
                            entry.declaration.identity,
                            identity,
                        )) return host.store().object(a, owner.object, null);
                    }
                    return error.InvalidResultReference;
                }
                pub fn workspaceReference(
                    this: @This(),
                    ref: wc.Ref,
                    kind: @FieldType(wc.Ref, "kind"),
                ) !void {
                    const id = wp.identity(ref, kind) catch return error.InvalidResultReference;
                    const custody_id = try workspaceContentCustody(this.allocator, this.task, id);
                    switch (kind) {
                        .program => {
                            const bytes = (try this.service.store().recordBytes(
                                this.allocator,
                                "workspace_program",
                                custody_id,
                                this.task,
                            )) orelse return error.InvalidResultReference;
                            this.allocator.free(bytes);
                            var program = try this.service.workspaceProgram(
                                this.allocator,
                                this.task,
                                id,
                            );
                            defer program.deinit();
                        },
                        .value => {
                            const bytes = (try this.service.store().recordBytes(
                                this.allocator,
                                "workspace_value",
                                custody_id,
                                this.task,
                            )) orelse return error.InvalidResultReference;
                            this.allocator.free(bytes);
                            _ = try this.service.workspaceValueReference(
                                this.allocator,
                                this.task,
                                ref,
                            );
                        },
                        else => return error.InvalidResultReference,
                    }
                }
            };
        }
        fn validateResult(
            self: *Self,
            comptime T: type,
            a: std.mem.Allocator,
            value: state.Task,
            result: T,
        ) !void {
            if (comptime T == Types.Output and @hasDecl(Types, "validateOutput")) {
                try Types.validateOutput(
                    ResultAdmission{
                        .service = self,
                        .allocator = a,
                        .task = value.id,
                        .profile = value.profile.digest,
                    },
                    result,
                );
            }
        }
        fn occurrenceImage(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
        ) !state.Digest {
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                pending.id,
                parent.id,
            );
            defer route.deinit();
            if (!std.meta.eql(route.value.work, pending.work) or
                !std.meta.eql(route.value.residual, pending.residual) or
                !std.meta.eql(route.value.task, parent.id) or
                !std.meta.eql(route.value.id, pending.id))
                return error.CorruptState;
            if (pending.work) |id| {
                var work = try self.workspaceWork(a, parent.id, id);
                defer work.deinit();
                var program = try self.workspaceProgram(a, parent.id, work.value.program);
                defer program.deinit();
                if (!std.meta.eql(
                    program.value.description.image,
                    route.value.image,
                ) or !std.meta.eql(
                    work.value.delegation,
                    route.value.delegation,
                )) return error.CorruptState;
            } else if (!std.meta.eql(
                try self.rootRouteImage(a, parent, route.value),
                route.value.image,
            )) return error.CorruptState;
            return route.value.program_identity;
        }
        fn occurrenceSubject(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
        ) !OccurrenceSubject {
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                pending.id,
                parent.id,
            );
            defer route.deinit();
            if (!std.meta.eql(route.value.work, pending.work) or
                !std.meta.eql(route.value.residual, pending.residual) or
                !std.meta.eql(route.value.task, parent.id) or
                !std.meta.eql(route.value.id, pending.id))
                return error.CorruptState;
            if (pending.work != null) return self.workspaceOccurrenceSubject(
                a,
                parent,
                pending,
                route.value,
            );
            if (pending.residual) |id| {
                if (pending.work != null) return error.CorruptState;
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    parent.id,
                );
                defer residual.deinit();
                if (!residual.value.cancellation_applied or !std.meta.eql(
                    residual.value.current_occurrence,
                    pending.id,
                ) or !std.meta.eql(
                    route.value.controller,
                    residual.value.controller,
                ) or !std.meta.eql(
                    try self.rootRouteImage(a, parent, route.value),
                    route.value.image,
                )) return error.StaleOccurrence;
                return .{
                    .image = route.value.program_identity,
                    .cancelling = true,
                    .cleanup = true,
                };
            }
            if (!std.meta.eql(parent.current_occurrence, pending.id) or !std.meta.eql(
                parent.controller,
                route.value.controller,
            )) return error.StaleOccurrence;
            if (!std.meta.eql(
                try self.rootImage(a, parent),
                route.value.image,
            ) or !std.meta.eql(
                route.value.program_identity,
                try self.rootProgramIdentity(a, parent),
            )) return error.CorruptState;
            return .{
                .image = route.value.program_identity,
                .cancelling = parent.cancellation != null,
                .cleanup = parent.cancellation_applied,
            };
        }
        fn workspaceOccurrenceSubject(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            route: workspace.ExecutionRoute,
        ) !OccurrenceSubject {
            const id = pending.work.?;

            var work = try self.workspaceWork(a, parent.id, id);
            defer work.deinit();
            if (!std.meta.eql(
                work.value.current_occurrence,
                pending.id,
            )) return error.StaleOccurrence;
            var program = try self.workspaceProgram(a, parent.id, work.value.program);
            defer program.deinit();
            if (!std.meta.eql(
                program.value.description.image,
                route.image,
            )) return error.CorruptState;
            return .{
                .image = route.program_identity,
                .cancelling = work.value.cancellation != null,
                .cleanup = work.value.cancellation_applied,
            };
        }
        fn effectSchedule(
            self: *Self,
            a: std.mem.Allocator,
            parent: *state.Task,
            pending: occurrence.Occurrence,
            schedule: state.Schedule,
            blocker: ?state.Blocker,
        ) !void {
            // Inside the same transaction as its occurrence. Child accounting is
            // visible in the task journal without changing the root continuation.
            if (pending.residual) |id| {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    parent.id,
                );
                defer residual.deinit();
                if (!std.meta.eql(
                    residual.value.current_occurrence,
                    pending.id,
                )) return error.StaleOccurrence;
                residual.value.schedule = schedule;
                residual.value.blocker = blocker;
                try self.store().putRecord(
                    state.ControllerResidual,
                    "controller_residual",
                    id,
                    parent.id,
                    residual.value,
                );
                try self.residualProgressEvent(a, parent, residual.value);
                return;
            }
            const id = pending.work orelse return;
            var work = try self.retainedWorkspaceWork(a, parent.id, id);
            defer work.deinit();
            if (!std.meta.eql(
                work.value.current_occurrence,
                pending.id,
            )) return error.StaleOccurrence;
            // Completion makes work eligible; it does not revoke a later park.
            if (schedule != .queued or
                work.value.schedule != .parked) work.value.schedule = schedule;
            work.value.blocker = blocker;
            work.value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            try self.writeWorkspaceWork(&work.value, .replace);
            const event_data = try std.fmt.allocPrint(a, "{{\"workspace_id\":\"{s}\"}}", .{
                std.fmt.bytesToHex(id, .lower),
            });
            defer a.free(event_data);
            const observed = try self.freezeWorkspaceWork(
                a,
                parent.id,
                try wp.reference(a, .work, id),
                true,
            );
            const snapshot = try contracts.encodeOwned(workspace.WorkObservation, a, observed);
            defer a.free(snapshot);
            _ = try self.store().putObject(snapshot);
            try self.publicationEvent(
                parent,
                .workspace_progress,
                event_data,
                &.{try workPublication(a, observed)},
                null,
            );
        }
        fn persistOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            previous: u64,
            transition: []const u8,
            pending: occurrence.Occurrence,
            wake: bool,
        ) !void {
            var subject: ?workspace.Subject = null;
            if (wake) if (pending.residual) |id| {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    parent.id,
                );
                defer residual.deinit();
                if (residual.value.schedule != .parked) subject = .{
                    .task = parent.id,
                    .residual = id,
                };
            } else if (pending.work) |id| {
                var work = try self.workspaceWork(a, parent.id, id);
                defer work.deinit();
                if (work.value.schedule != .parked) subject = .{ .task = parent.id, .work = id };
            } else {
                subject = .{ .task = parent.id };
            };
            try self.persistScheduled(
                a,
                parent,
                previous,
                transition,
                .preserve,
                if (subject) |value| &.{value} else &.{},
            );
        }
        fn blockedOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            reason: state.Blocker,
        ) !Step {
            if (pending.work == null and pending.residual == null) return self.blocked(
                a,
                initial,
                reason,
            );
            var parent = initial;
            parent.revision = try std.math.add(u64, parent.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.effectSchedule(a, &parent, pending, .parked, reason);
            try self.persist(a, parent, initial.revision, "effect.blocked", .preserve);
            self.subjectRemove(.{
                .task = parent.id,
                .work = pending.work,
                .residual = pending.residual,
            });
            return .waiting;
        }
        fn controllerInternal(identity: []const u8) bool {
            const c = contracts.controller;
            return same(identity, c.boot_identity) or
                same(identity, c.offer_identity) or
                same(identity, c.handoff_identity);
        }
        fn controllerOverlay(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
            binding_id: state.Digest,
            handoff: state.Digest,
            event_cut: u64,
            next_message: u64,
            epoch: u64,
        ) ![]u8 {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            const binding = try self.controllerBinding(a, parent, binding_id);
            const user = try self.controllerOverlayUser(a, parent, next_message, event_cut);
            const control = try self.controllerOverlayControl(
                a,
                parent,
                binding_id,
                binding.program,
                handoff,
                event_cut,
                epoch,
            );
            var overlay = json.object();
            try json.put(a, &overlay, "user", user);
            try json.put(a, &overlay, "control", control);
            return json.canonical(allocator, overlay);
        }
        fn controllerOverlayUser(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            next_message: u64,
            event_cut: u64,
        ) !json.Value {
            var input = try contracts.decodeOwned(
                Types.Input,
                a,
                try self.store().object(a, parent.input, null),
            );
            defer input.deinit();
            var user = json.object();
            try json.put(a, &user, "task", try values.toJson(Types.Input, a, input.value));
            try json.put(
                a,
                &user,
                "amendments_in_admission_order",
                try self.controllerOverlayAmendments(a, parent.id, next_message),
            );
            try json.put(
                a,
                &user,
                "admitted_human_answers",
                try self.controllerOverlayAnswers(a, parent.id, event_cut),
            );
            return user;
        }
        fn controllerOverlayAmendments(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            next_message: u64,
        ) !json.Value {
            const Amendment = struct { ordinal: u64, value: json.Value };
            var amendments: std.ArrayList(Amendment) = .empty;
            var rows = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='message'",
                &.{.{ .blob = &task_id }},
            );
            defer rows.deinit();
            while (try rows.step() == .row) {
                var saved = try contracts.decodeOwned(state.Message, a, try rows.bytes(0));
                defer saved.deinit();
                if (saved.value.ordinal >= next_message) continue;
                var amendment = try contracts.decodeOwned(
                    Types.Message,
                    a,
                    try self.store().object(a, saved.value.value, null),
                );
                defer amendment.deinit();
                try amendments.append(a, .{
                    .ordinal = saved.value.ordinal,
                    .value = try values.toJson(Types.Message, a, amendment.value),
                });
            }
            std.mem.sort(Amendment, amendments.items, {}, struct {
                fn less(_: void, left: Amendment, right: Amendment) bool {
                    return left.ordinal < right.ordinal;
                }
            }.less);
            if (next_message == 0 or
                amendments.items.len != next_message - 1)
                return error.CorruptState;
            var messages: json.Value = .{ .array = .init(a) };
            for (amendments.items, 1..) |item, ordinal| {
                if (item.ordinal != ordinal) return error.CorruptState;
                try messages.array.append(item.value);
            }
            return messages;
        }
        fn controllerOverlayAnswers(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            event_cut: u64,
        ) !json.Value {
            var answers: json.Value = .{ .array = .init(a) };
            var questions = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='question' ORDER BY r.id",
                &.{.{ .blob = &task_id }},
            );
            defer questions.deinit();
            while (try questions.step() == .row) {
                var question = try contracts.decodeOwned(state.Question, a, try questions.bytes(0));
                defer question.deinit();
                const answer = question.value.answer orelse continue;
                const answer_receipt = question.value.receipt orelse return error.CorruptState;
                var admitted = try self.store().database.prepare(
                    "SELECT 1 FROM events WHERE task=? AND revision=? AND seq<=?",
                    &.{ .{ .blob = &task_id }, .{
                        .integer = std.math.cast(
                            i64,
                            answer_receipt.revision,
                        ) orelse return error.CorruptState,
                    }, .{
                        .integer = std.math.cast(i64, event_cut) orelse return error.CorruptState,
                    } },
                );
                defer admitted.deinit();
                if (try admitted.step() != .row) continue;
                const Answer = if (@hasDecl(Types, "Answer")) Types.Answer else void;
                var decoded = try contracts.decodeOwned(
                    Answer,
                    a,
                    try self.store().object(a, answer, null),
                );
                defer decoded.deinit();
                var observed = json.object();
                try json.put(
                    a,
                    &observed,
                    "question",
                    json.string(try a.dupe(u8, &std.fmt.bytesToHex(question.value.id, .lower))),
                );
                try json.put(
                    a,
                    &observed,
                    "prompt",
                    json.string(try self.store().object(a, question.value.prompt, null)),
                );
                try json.put(a, &observed, "answer", try values.toJson(Answer, a, decoded.value));
                try answers.array.append(observed);
            }
            return answers;
        }
        fn controllerOverlayControl(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            binding_id: state.Digest,
            program_id: state.Digest,
            handoff: state.Digest,
            event_cut: u64,
            epoch: u64,
        ) !json.Value {
            var control = json.object();
            try json.put(
                a,
                &control,
                "task",
                json.string(try a.dupe(u8, &std.fmt.bytesToHex(parent.id, .lower))),
            );
            try json.put(a, &control, "controller_epoch", try json.number(a, epoch));
            try json.put(
                a,
                &control,
                "expected_handoff_identity",
                json.string(try a.dupe(u8, &std.fmt.bytesToHex(handoff, .lower))),
            );
            try json.put(
                a,
                &control,
                "realization_target",
                try self.controllerRealizationTarget(
                    a,
                    parent,
                    binding_id,
                    handoff,
                    event_cut,
                    epoch,
                ),
            );

            try json.put(
                a,
                &control,
                "program",
                try values.toJson(wc.Ref, a, try wp.reference(a, .program, program_id)),
            );
            try json.put(a, &control, "event_cut", try json.number(a, event_cut));
            try json.put(
                a,
                &control,
                "policy_identity",
                json.string(try a.dupe(u8, &std.fmt.bytesToHex(parent.profile.digest, .lower))),
            );
            try json.put(
                a,
                &control,
                "inspection",
                json.string(
                    "program.describe current_controller exposes exact source, carry " ++
                        "and contracts. context and work operations expose retained task " ++
                        "evidence. Program construction and adoption require their existi" ++
                        "ng task permissions.",
                ),
            );
            return control;
        }
        fn controllerRealizationTarget(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            binding_id: state.Digest,
            handoff: state.Digest,
            event_cut: u64,
            epoch: u64,
        ) !json.Value {
            const runtime_cut: ControllerRuntimeCut = if (event_cut == parent.event_high and
                epoch == parent.controller_epoch and
                std.meta.eql(parent.controller, @as(?state.Digest, binding_id)))
                .{
                    .runtime = parent.controller_runtime,
                    .realization_revision = parent.realization_revision,
                }
            else if (parent.realization_revision != 0 or
                !std.meta.eql(parent.controller, @as(?state.Digest, binding_id)))
                try self.controllerRuntimeAt(a, parent, event_cut)
            else
                ControllerRuntimeCut{};
            return values.toJson(wc.ControllerRealizationTarget, a, .{ .action = .{
                .interaction = .{
                    .bytes = try a.dupe(u8, &std.fmt.bytesToHex(handoff, .lower)),
                },
                .epoch = epoch,
                .realization_revision = runtime_cut.realization_revision,
            } });
        }
        fn controllerRequest(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            request: data.invocation.Request,
        ) !?state.Digest {
            if (parent.controller == null) return null;
            const c = contracts.controller;
            if (same(request.binding.semantic_identity, c.offer_identity)) return id;
            const model = same(request.binding.semantic_identity, c.effect_prefix ++ "deliberate");
            const handoff = same(request.binding.semantic_identity, c.handoff_identity);
            if (!model and !handoff) return null;
            var saved = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                parent.controller_interaction orelse return error.InvalidControllerBinding,
                parent.id,
            );
            defer saved.deinit();
            if (!std.meta.eql(
                saved.value.controller,
                parent.controller.?,
            ) or saved.value.handoff != null) return error.InvalidControllerBinding;
            const offered = try self.store().object(a, saved.value.offered, null);
            defer a.free(offered);
            if (model) {
                if (saved.value.model != null or !same(
                    offered,
                    request.binding.payload,
                )) return error.InvalidControllerBinding;
                saved.value.model = id;
            } else {
                try self.validateControllerHandoffRequest(a, parent, saved.value, request, offered);
                saved.value.handoff = id;
            }
            try self.store().putRecord(
                state.ControllerInteraction,
                "controller_interaction",
                saved.value.id,
                parent.id,
                saved.value,
            );
            return saved.value.id;
        }
        fn validateControllerHandoffRequest(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            interaction: state.ControllerInteraction,
            request: data.invocation.Request,
            offered: []const u8,
        ) !void {
            var prior = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                interaction.model orelse return error.InvalidControllerBinding,
                parent.id,
            );
            defer prior.deinit();
            if (prior.value.state != .admitted or
                prior.value.state.admitted != .reply)
                return error.InvalidControllerBinding;
            const encoded = try self.store().object(
                a,
                try self.store().objectReference(prior.value.state.admitted.reply.reply, null),
                null,
            );
            defer a.free(encoded);
            var reply = try data.invocation.decode(data.invocation.Result, a, encoded);
            defer reply.deinit();
            if (request.binding.payload.len != offered.len + reply.value.value.len or !same(
                request.binding.payload[0..offered.len],
                offered,
            ) or !same(
                request.binding.payload[offered.len..],
                reply.value.value,
            )) return error.InvalidControllerBinding;
        }
        fn controllerReply(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            request: data.invocation.Request,
        ) ![]u8 {
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                pending.id,
                parent.id,
            );
            defer route.deinit();
            if (pending.work != null or route.value.controller == null or !std.meta.eql(
                try self.rootRouteImage(a, parent, route.value),
                route.value.image,
            )) return error.InvalidControllerBinding;
            const binding = try self.controllerBinding(a, parent, route.value.controller.?);
            if (!std.meta.eql(
                request.binding.program_identity,
                binding.program_identity,
            )) return error.InvalidControllerBinding;
            var program = try self.workspaceProgram(a, parent.id, binding.program);
            defer program.deinit();
            const descriptor = program.value.description.controller.?;
            const model = for (descriptor.imports.items) |item| {
                if (item.import == .deliberate) break item;
            } else return error.InvalidControllerBinding;
            const c = contracts.controller;
            const boot = same(request.binding.semantic_identity, c.boot_identity);
            const offer = same(request.binding.semantic_identity, c.offer_identity);
            if (!boot and !offer and !same(
                request.binding.semantic_identity,
                c.handoff_identity,
            )) return error.InvalidControllerBinding;
            try self.validateControllerReplySchema(
                a,
                request,
                program.value.description.input_schema,
                descriptor,
                model,
                boot,
                offer,
            );
            if (boot) {
                if (request.binding.payload.len < parent.id.len or !same(
                    request.binding.payload[0..parent.id.len],
                    &parent.id,
                )) return error.InvalidControllerBinding;
                return a.dupe(u8, &.{});
            }
            if (offer) return self.controllerOffer(
                a,
                self.projectionBinding(parent),
                request.binding.payload,
            );
            return controllerHandoffReply(a, request, model.payload.bytes);
        }
        fn controllerHandoffReply(
            a: std.mem.Allocator,
            request: data.invocation.Request,
            payload_schema: []const u8,
        ) ![]u8 {
            var model_schema = try data.schema.decode(a, payload_schema);
            defer model_schema.deinit();
            var arena = std.heap.ArenaAllocator.init(a);
            defer arena.deinit();
            const scratch = arena.allocator();
            const facts = try data.admission.schemas(scratch, model_schema.descriptor.types);
            var reader: data.wire.Reader = .{ .input = request.binding.payload };
            _ = try data.admission.readValue(
                scratch,
                model_schema.descriptor.types,
                facts,
                model_schema.descriptor.root,
                &reader,
            );
            return std.mem.concat(a, u8, &.{ request.binding.payload[reader.position..], &.{0} });
        }
        fn validateControllerReplySchema(
            self: *Self,
            a: std.mem.Allocator,
            request: data.invocation.Request,
            input_schema: state.Reference,
            descriptor: anytype,
            model: anytype,
            boot: bool,
            offer: bool,
        ) !void {
            const boot_schema = if (boot) try self.store().object(
                a,
                input_schema,
                null,
            ) else null;
            defer if (boot_schema) |bytes| a.free(bytes);
            const unit = if (boot) try values.schemaBytes(void, a) else null;
            defer if (unit) |bytes| a.free(bytes);
            const payload_schema =
                if (boot)
                    boot_schema.?
                else if (offer)
                    model.payload.bytes
                else
                    descriptor.handoff_payload.bytes;
            const result_schema =
                if (boot)
                    unit.?
                else if (offer)
                    model.payload.bytes
                else
                    (model.public_result orelse
                        return error.InvalidControllerBinding).bytes;
            if (!same(request.binding.payload_schema, payload_schema) or !same(
                request.binding.resume_schema,
                result_schema,
            )) return error.CapabilitySchemaMismatch;
            var shape = try data.schema.decode(a, payload_schema);
            defer shape.deinit();
            try data.schema.validateValue(a, shape.descriptor, request.binding.payload);
        }
        fn controllerOffer(
            self: *Self,
            a: std.mem.Allocator,
            binding: registry.ProjectionBinding,
            payload: []const u8,
        ) ![]u8 {
            var entry = for (self.handlers.entries) |item| {
                if (item.declaration.controller_import == .deliberate) break item;
            } else return error.MissingCapability;
            entry.controller_envelope = true;
            const proposal = try entry.payload(a, payload);
            const callback = entry.declaration.controller_offer orelse return a.dupe(u8, payload);
            const normalized = try self.store().project([]u8, a, self.handlers, binding, struct {
                callback: @TypeOf(callback),
                proposal: []const u8,
                pub fn run(this: @This(), context: registry.ProjectionContext) ![]u8 {
                    return this.callback(context, this.proposal);
                }
            }{ .callback = callback, .proposal = proposal });
            defer a.free(normalized);
            return std.mem.concat(a, u8, &.{ normalized, payload[proposal.len..] });
        }
        fn controllerStoredReply(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            request: data.invocation.Request,
        ) ![]u8 {
            const ordinary = try self.controllerReply(a, parent, pending, request);
            errdefer a.free(ordinary);
            if (!same(
                request.binding.semantic_identity,
                contracts.controller.handoff_identity,
            )) return ordinary;
            const selected = (try self.controllerSelection(
                a,
                parent,
                ordinary[0 .. ordinary.len - 1],
            )) orelse return ordinary;
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                pending.id,
                parent.id,
            );
            defer route.deinit();
            const id = route.value.interaction orelse return error.InvalidArchive;
            const bytes = (try self.store().recordBytes(
                a,
                "controller_succession",
                id,
                parent.id,
            )) orelse return ordinary;
            defer a.free(bytes);
            var succession = try contracts.decodeOwned(state.ControllerSuccession, a, bytes);
            defer succession.deinit();
            const command = try contracts.encodeOwned(wc.Adoption, a, selected);
            defer a.free(command);
            if (!std.meta.eql(succession.value.command, state.Reference{
                .digest = storage.digest(command),
                .bytes = command.len,
            })) return error.InvalidArchive;
            if (succession.value.phase == .activated) return error.InvalidArchive;
            const diagnostic = succession.value.diagnostic orelse return error.InvalidArchive;
            const encoded = try contracts.encodeOwned(
                ?contracts.controller.Diagnostic,
                a,
                diagnostic,
            );
            defer a.free(encoded);
            const result = try std.mem.concat(a, u8, &.{
                ordinary[0 .. ordinary.len - 1],
                encoded,
            });
            a.free(ordinary);
            return result;
        }
        fn validateControllerInteraction(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            records: []const state.ArchiveRecord,
        ) !void {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var saved = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                id,
                parent.id,
            );
            defer saved.deinit();
            const interaction = saved.value;
            try self.validateControllerInteractionIdentity(a, parent, id, interaction);
            const offered = try self.controllerInteractionOffered(
                a,
                parent,
                id,
                interaction,
                records,
            );
            try self.validateControllerInteractionCarry(a, parent, id, interaction, offered);
            var model_reply: ?[]const u8 = null;
            inline for (.{ "model", "handoff" }) |field|
                if (@field(interaction, field)) |occurrence_id| {
                    try self.validateControllerInteractionOccurrence(
                        a,
                        parent,
                        id,
                        interaction,
                        records,
                        offered,
                        field,
                        occurrence_id,
                        &model_reply,
                    );
                };
        }
        fn validateControllerInteractionOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            interaction: state.ControllerInteraction,
            records: []const state.ArchiveRecord,
            offered: []const u8,
            comptime field: []const u8,
            occurrence_id: state.Digest,
            model_reply: *?[]const u8,
        ) !void {
            try self.validateControllerInteractionRoute(
                a,
                parent,
                id,
                interaction,
                records,
                occurrence_id,
            );
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                occurrence_id,
                parent.id,
            );
            defer pending.deinit();
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                try self.store().object(a, pending.value.request_object, null),
            );
            defer request.deinit();
            const is_model = comptime same(field, "model");
            if (!same(
                request.value.binding.semantic_identity,
                if (is_model)
                    contracts.controller.effect_prefix ++ "deliberate"
                else
                    contracts.controller.handoff_identity,
            )) return error.InvalidArchive;
            try self.validateControllerInteractionPayload(
                a,
                interaction,
                pending.value,
                request.value,
                offered,
                is_model,
                model_reply,
            );
        }
        fn validateControllerInteractionPayload(
            self: *Self,
            a: std.mem.Allocator,
            interaction: state.ControllerInteraction,
            pending: occurrence.Occurrence,
            request: data.invocation.Request,
            offered: []const u8,
            comptime is_model: bool,
            model_reply: *?[]const u8,
        ) !void {
            if (is_model) {
                if (!same(request.binding.payload, offered)) return error.InvalidArchive;
                if (interaction.handoff != null) {
                    const result = switch (pending.state) {
                        .admitted => |outcome| if (outcome ==
                            .reply) outcome.reply else return error.InvalidArchive,
                        else => return error.InvalidArchive,
                    };
                    var decoded = try data.invocation.decode(
                        data.invocation.Result,
                        a,
                        try self.store().object(
                            a,
                            try self.store().objectReference(result.reply, null),
                            null,
                        ),
                    );
                    defer decoded.deinit();
                    model_reply.* = try a.dupe(u8, decoded.value.value);
                }
            } else {
                const result = model_reply.* orelse return error.InvalidArchive;
                const payload = request.binding.payload;
                if (payload.len != offered.len + result.len or !same(
                    payload[0..offered.len],
                    offered,
                ) or !same(payload[offered.len..], result)) return error.InvalidArchive;
            }
        }
        fn validateControllerInteractionRoute(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            interaction: state.ControllerInteraction,
            records: []const state.ArchiveRecord,
            occurrence_id: state.Digest,
        ) !void {
            try requireArchiveRecord(records, .occurrence, occurrence_id);
            try requireArchiveRecord(records, .execution_route, occurrence_id);
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                occurrence_id,
                parent.id,
            );
            defer route.deinit();
            if (route.value.work != null or !std.meta.eql(
                route.value.controller,
                interaction.controller,
            ) or !std.meta.eql(
                route.value.interaction,
                id,
            )) return error.InvalidArchive;
        }
        fn validateControllerInteractionCarry(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            interaction: state.ControllerInteraction,
            offered: []const u8,
        ) !void {
            var entry = for (self.handlers.entries) |item| {
                if (item.declaration.controller_import == .deliberate) break item;
            } else return error.InvalidArchive;
            entry.controller_envelope = true;
            const proposed = try entry.payload(a, offered);
            const carry = try self.store().object(a, interaction.carry, null);
            if (!same(carry, offered[proposed.len..])) return error.InvalidArchive;
            const overlay = try self.controllerOverlay(
                a,
                parent,
                interaction.controller,
                id,
                interaction.event_cut,
                interaction.next_message,
                interaction.epoch,
            );
            if (!same(
                overlay,
                try self.store().object(a, interaction.overlay, null),
            )) return error.InvalidArchive;
        }
        fn controllerInteractionOffered(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            interaction: state.ControllerInteraction,
            records: []const state.ArchiveRecord,
        ) ![]const u8 {
            try requireArchiveRecord(records, .occurrence, id);
            var offer = try self.record(occurrence.Occurrence, a, "occurrence", id, parent.id);
            defer offer.deinit();
            try requireArchiveRecord(records, .execution_route, id);
            var offer_route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                id,
                parent.id,
            );
            defer offer_route.deinit();
            if (offer_route.value.work != null or !std.meta.eql(
                offer_route.value.controller,
                interaction.controller,
            ) or !std.meta.eql(
                offer_route.value.interaction,
                id,
            )) return error.InvalidArchive;
            var offer_request = try data.invocation.decode(
                data.invocation.Request,
                a,
                try self.store().object(a, offer.value.request_object, null),
            );
            defer offer_request.deinit();
            if (!same(
                offer_request.value.binding.semantic_identity,
                contracts.controller.offer_identity,
            )) return error.InvalidArchive;
            const accepted = switch (offer.value.state) {
                .settled_reply => |reply| reply,
                .admitted => |outcome| if (outcome ==
                    .reply) outcome.reply else return error.InvalidArchive,
                else => return error.InvalidArchive,
            };
            const reply_bytes = try self.store().object(
                a,
                try self.store().objectReference(accepted.reply, null),
                null,
            );
            var reply = try data.invocation.decode(data.invocation.Result, a, reply_bytes);
            defer reply.deinit();
            const offered = try self.store().object(a, interaction.offered, null);
            if (!same(offered, reply.value.value)) return error.InvalidArchive;
            return offered;
        }
        fn validateControllerInteractionIdentity(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            interaction: state.ControllerInteraction,
        ) !void {
            if (!std.meta.eql(interaction.id, id) or
                !std.meta.eql(interaction.task, parent.id) or
                !std.meta.eql(
                    interaction.policy,
                    parent.profile,
                ) or interaction.next_message > parent.next_message or !std.meta.eql(
                @as(?state.Digest, interaction.controller),
                try self.controllerAt(a, parent, interaction.event_cut),
            ) or interaction.epoch != try self.controllerEpochAt(
                a,
                parent,
                interaction.event_cut,
            )) return error.InvalidArchive;
            const binding = try self.controllerBinding(a, parent, interaction.controller);
            var program = try self.workspaceProgram(a, parent.id, binding.program);
            defer program.deinit();
            const schema = program.value.description.controller.?.carry.bytes;
            if (!std.meta.eql(
                interaction.carry_schema.digest,
                storage.digest(schema),
            ) or interaction.carry_schema.bytes != schema.len) return error.InvalidArchive;
        }
        fn validateControllerSuccession(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var saved = try self.record(
                state.ControllerSuccession,
                a,
                "controller_succession",
                id,
                parent.id,
            );
            defer saved.deinit();
            const operation_value = saved.value;
            if (!std.meta.eql(operation_value.id, id) or !std.meta.eql(
                operation_value.task,
                parent.id,
            )) return error.InvalidArchive;
            try self.validateSuccessionRecord(a, parent, operation_value, records, checked);
        }
        fn validateSuccessionAdmissionEvent(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            admission: anytype,
        ) !void {
            const events = try self.store().eventsAfter(a, parent.id, admission.event - 1, 1);
            if (events.len != 1) return error.InvalidArchive;
            var event_value = try contracts.decodeOwned(state.Event, a, events[0]);
            defer event_value.deinit();
            if (event_value.value.kind != .controller_requested or
                event_value.value.seq != admission.event or
                event_value.value.revision != admission.revision)
                return error.InvalidArchive;
            const event_data = (try json.parse(a, event_value.value.data.bytes, .{})).value;
            const operation_id = json.get(
                event_data,
                "operation",
            ) orelse return error.InvalidArchive;
            if (operation_id != .string or !same(
                operation_id.string,
                &std.fmt.bytesToHex(id, .lower),
            )) return error.InvalidArchive;
        }
        fn validateSuccessionAdmission(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            interaction: state.ControllerInteraction,
            pending: occurrence.Occurrence,
            admission: anytype,
        ) !void {
            const id = operation_value.id;
            if (admission.revision <= 1 or
                admission.event != operation_value.event_cut + 1 or
                (!std.meta.eql(
                    interaction.model,
                    operation_value.handoff,
                ) and !std.meta.eql(
                    interaction.handoff,
                    operation_value.handoff,
                ))) return error.InvalidArchive;
            if (admission.occurrence.state != .ready and
                admission.occurrence.state != .not_sent)
                return error.InvalidArchive;
            if (!std.meta.eql(
                admission.occurrence.id,
                pending.id,
            ) or !std.meta.eql(admission.occurrence.task, parent.id) or
                admission.occurrence.work != null or
                admission.occurrence.residual != null or
                !std.meta.eql(
                    admission.occurrence.request,
                    pending.request,
                ) or !std.meta.eql(
                admission.occurrence.request_object,
                pending.request_object,
            )) return error.InvalidArchive;
            if (admission.occurrence.state == .not_sent) {
                var attempt = try self.record(
                    state.Attempt,
                    a,
                    "attempt",
                    admission.occurrence.state.not_sent.id,
                    parent.id,
                );
                defer attempt.deinit();
                if (!std.meta.eql(
                    attempt.value.occurrence,
                    pending.id,
                )) return error.InvalidArchive;
            }

            try self.validateSuccessionAdmissionEvent(a, parent, id, admission);
        }
        fn successionSelection(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            interaction: state.ControllerInteraction,
            pending: occurrence.Occurrence,
            request: data.invocation.Request,
        ) !wc.Adoption {
            const id = operation_value.id;
            const selected = if (operation_value.operator_admission) |admission| blk: {
                try self.validateSuccessionAdmission(
                    a,
                    parent,
                    operation_value,
                    interaction,
                    pending,
                    admission,
                );
                var command_value = try contracts.decodeOwned(
                    wc.Adoption,
                    a,
                    try self.store().object(a, operation_value.command, null),
                );
                defer command_value.deinit();
                break :blk try values.fromJson(
                    wc.Adoption,
                    a,
                    try values.toJson(wc.Adoption, a, command_value.value),
                );
            } else blk: {
                if (!std.meta.eql(id, interaction.id) or !std.meta.eql(
                    interaction.handoff,
                    operation_value.handoff,
                )) return error.InvalidArchive;
                if (operation_value.event_cut < interaction.event_cut or
                    operation_value.next_message < interaction.next_message)
                    return error.InvalidArchive;
                const reply = try self.controllerReply(a, parent, pending, request);
                break :blk (try self.controllerSelection(
                    a,
                    parent,
                    reply[0 .. reply.len - 1],
                )) orelse return error.InvalidArchive;
            };

            return selected;
        }
        fn validateSuccessionActivation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            selected: wc.Adoption,
            predecessor: state.ControllerBinding,
            records: []const state.ArchiveRecord,
        ) !void {
            if (operation_value.phase == .activated) {
                const at = operation_value.activation_event orelse return error.InvalidArchive;
                const epoch = operation_value.activated_epoch orelse return error.InvalidArchive;
                const binding_id = (try self.controllerAt(
                    a,
                    parent,
                    at,
                )) orelse return error.InvalidArchive;
                const binding = try self.controllerBinding(a, parent, binding_id);
                if (epoch != (std.math.add(
                    u64,
                    selected.expected_controller_epoch,
                    1,
                ) catch return error.InvalidArchive) or
                    epoch <= predecessor.epoch or
                    binding.epoch != epoch or
                    binding.activated_at != at or
                    !std.meta.eql(binding.predecessor, predecessor.id) or !std.meta.eql(
                    binding.program,
                    operation_value.successor.?,
                ) or at <= operation_value.event_cut) return error.InvalidArchive;
                try requireArchiveRecord(
                    records,
                    .controller_residual,
                    operation_value.residual orelse return error.InvalidArchive,
                );
            } else if (operation_value.activation_event != null or
                operation_value.activated_epoch != null or
                operation_value.residual != null)
                return error.InvalidArchive;
        }
        fn validateSuccessionSelection(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            interaction: state.ControllerInteraction,
            selected: wc.Adoption,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const id = operation_value.id;
            const command = try contracts.encodeOwned(wc.Adoption, a, selected);
            if (!std.meta.eql(operation_value.command, state.Reference{
                .digest = storage.digest(command),
                .bytes = command.len,
            })) return error.InvalidArchive;
            const preparing = operation_value.phase == .preparing or
                operation_value.phase == .ready;
            if (preparing != std.meta.eql(
                parent.controller_succession,
                @as(?state.Digest, id),
            )) return error.InvalidArchive;
            if (preparing and (!std.meta.eql(
                parent.controller,
                operation_value.predecessor,
            ) or !std.meta.eql(
                parent.checkpoint,
                operation_value.checkpoint,
            ) or !std.meta.eql(parent.outcome, operation_value.outcome) or !std.meta.eql(
                parent.current_occurrence,
                operation_value.handoff,
            ))) return error.InvalidArchive;
            const successful = preparing or operation_value.phase == .activated;
            if (successful == (operation_value.diagnostic != null)) return error.InvalidArchive;
            if (operation_value.phase == .rejected) {
                if (operation_value.successor != null or
                    operation_value.converter != null or
                    operation_value.conversion_input != null or
                    operation_value.conversion_work != null or
                    operation_value.converted != null or
                    operation_value.boot != null)
                    return error.InvalidArchive;
            } else {
                try self.validateSuccessionPrograms(
                    a,
                    parent,
                    operation_value,
                    interaction,
                    selected,
                    records,
                    checked,
                );
            }
        }
        fn validateSuccessionBoot(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            successor: workspace.Program,
        ) !void {
            if (operation_value.boot) |boot| {
                const converted = try self.store().object(
                    a,
                    operation_value.converted orelse return error.InvalidArchive,
                    null,
                );
                const anchor = try contracts.encodeOwned(contracts.controller.TaskAnchor, a, .{
                    .task = parent.id,
                });
                const initial = try std.mem.concat(a, u8, &.{ anchor, converted });
                const image = try self.store().object(a, successor.description.image, null);
                var runtime = try self.program.retainRuntime();
                defer runtime.deinit();
                const driver = try evaluator.Driver.openSelected(
                    self.allocator,
                    image,
                    .{ .initial_args = initial },
                    &runtime,
                );
                defer {
                    driver.retire() catch self.store().fence();
                    driver.destroy() catch self.store().fence();
                }
                const actual = try driver.drive(a, .none, 256);
                if (!std.meta.eql(boot.checkpoint, state.Reference{
                    .digest = storage.digest(actual.checkpoint),
                    .bytes = actual.checkpoint.len,
                }) or !std.meta.eql(boot.outcome, state.Reference{
                    .digest = storage.digest(actual.outcome),
                    .bytes = actual.outcome.len,
                })) return error.InvalidArchive;
                var outcome = try data.invocation.decode(
                    data.invocation.Outcome,
                    a,
                    actual.outcome,
                );
                defer outcome.deinit();
                if (outcome.value != .requested) return error.InvalidArchive;
                var boot_request = try data.invocation.decode(
                    data.invocation.Request,
                    a,
                    outcome.value.requested.request,
                );
                defer boot_request.deinit();
                if (!same(
                    boot_request.value.binding.semantic_identity,
                    contracts.controller.boot_identity,
                ) or !same(
                    boot_request.value.binding.payload,
                    initial,
                )) return error.InvalidArchive;
            } else if (operation_value.phase == .ready or
                operation_value.phase == .activated)
                return error.InvalidArchive;
        }
        fn validateSuccessionConversion(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            interaction: state.ControllerInteraction,
            converter_id: state.Digest,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const conversion_input = operation_value.conversion_input orelse
                return error.InvalidArchive;
            const input = try self.store().object(a, conversion_input, null);
            const carry = try self.store().object(a, interaction.carry, null);
            if (input.len < carry.len or !same(
                input[0..carry.len],
                carry,
            )) return error.InvalidArchive;
            var view = try contracts.decodeOwned(
                contracts.controller.OwnerView,
                a,
                input[carry.len..],
            );
            defer view.deinit();
            if (!std.meta.eql(view.value.task, parent.id) or
                view.value.event_cut != operation_value.event_cut or
                view.value.next_message != operation_value.next_message or
                !std.meta.eql(view.value.policy, operation_value.policy.digest) or !same(
                view.value.input.bytes,
                try self.store().object(a, parent.input, null),
            )) return error.InvalidArchive;
            try self.validateControllerViewIn(
                a,
                parent,
                view.value,
                operation_value.view_works.items,
                records,
                checked,
            );
            if (operation_value.conversion_work) |work_id| {
                try requireArchiveRecord(records, .workspace_work, work_id);
                var work = try self.workspaceWork(a, parent.id, work_id);
                defer work.deinit();
                if (work.value.trial != null or !std.meta.eql(
                    work.value.program,
                    converter_id,
                ) or !std.meta.eql(
                    work.value.input,
                    conversion_input,
                )) return error.InvalidArchive;
                if (operation_value.converted) |converted|
                    if (work.value.outcome_kind !=
                        .completed or
                        !std.meta.eql(
                            work.value.result,
                            converted,
                        )) return error.InvalidArchive;
            } else if (operation_value.converted != null or
                operation_value.boot != null)
                return error.InvalidArchive;
        }
        fn validateSuccessionPrograms(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            interaction: state.ControllerInteraction,
            selected: wc.Adoption,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const successor_id = operation_value.successor orelse return error.InvalidArchive;
            const converter_id = operation_value.converter orelse return error.InvalidArchive;
            if (!std.meta.eql(
                successor_id,
                try wp.identity(selected.successor, .program),
            ) or !std.meta.eql(
                converter_id,
                try wp.identity(selected.converter, .program),
            ) or selected.expected_controller_epoch != try self.controllerEpochAt(
                a,
                parent,
                operation_value.event_cut,
            ) or !same(
                selected.expected_handoff_identity.bytes,
                &std.fmt.bytesToHex(interaction.id, .lower),
            )) return error.InvalidArchive;
            var successor = try self.workspaceProgram(a, parent.id, successor_id);
            defer successor.deinit();
            const descriptor = successor.value.description.controller orelse
                return error.InvalidArchive;
            var converter = try self.workspaceProgram(a, parent.id, converter_id);
            defer converter.deinit();
            const expected = try @import("controller_construction.zig").conversionSchema(
                a,
                try self.store().object(a, interaction.carry_schema, null),
            );
            if (converter.value.description.controller != null or
                converter.value.description.ports.items.len != 0 or
                !std.meta.eql(
                    converter.value.description.input_schema.digest,
                    storage.digest(expected),
                ) or !std.meta.eql(
                converter.value.description.result_schema.digest,
                storage.digest(descriptor.private_input.bytes),
            )) return error.InvalidArchive;
            try self.validateSuccessionConversion(
                a,
                parent,
                operation_value,
                interaction,
                converter_id,
                records,
                checked,
            );
            try self.validateSuccessionBoot(a, parent, operation_value, successor.value);
        }
        fn validateSuccessionRecord(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                operation_value.handoff,
                parent.id,
            );
            defer route.deinit();
            var interaction = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                route.value.interaction orelse return error.InvalidArchive,
                parent.id,
            );
            defer interaction.deinit();
            if (!std.meta.eql(
                operation_value.predecessor,
                interaction.value.controller,
            ) or !std.meta.eql(
                operation_value.policy,
                interaction.value.policy,
            ) or !std.meta.eql(
                @as(?state.Digest, operation_value.predecessor),
                try self.controllerAt(a, parent, operation_value.event_cut),
            )) return error.InvalidArchive;
            try self.validateControllerMessageCut(
                a,
                parent,
                operation_value.event_cut,
                operation_value.next_message,
            );
            try self.validateSuccessionHandoff(
                a,
                parent,
                operation_value,
                interaction.value,
                records,
                checked,
            );
        }
        fn validateSuccessionHandoff(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            interaction: state.ControllerInteraction,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const predecessor = try self.controllerBinding(a, parent, operation_value.predecessor);
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                operation_value.handoff,
                parent.id,
            );
            defer pending.deinit();
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                try self.store().object(a, pending.value.request_object, null),
            );
            defer request.deinit();
            const selected = try self.successionSelection(
                a,
                parent,
                operation_value,
                interaction,
                pending.value,
                request.value,
            );
            try self.validateSuccessionSelection(
                a,
                parent,
                operation_value,
                interaction,
                selected,
                records,
                checked,
            );
            try self.validateSuccessionActivation(
                a,
                parent,
                operation_value,
                selected,
                predecessor,
                records,
            );
        }
        fn validateControllerResidual(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            records: []const state.ArchiveRecord,
        ) !void {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var saved = try self.record(
                state.ControllerResidual,
                a,
                "controller_residual",
                id,
                parent.id,
            );
            defer saved.deinit();
            try requireArchiveRecord(records, .controller_succession, saved.value.succession);
            if (saved.value.current_occurrence) |current| try requireArchiveRecord(
                records,
                .occurrence,
                current,
            );
            return self.validateControllerResidualValue(allocator, parent, saved.value, false);
        }
        fn validateControllerResidualValue(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
            residual: state.ControllerResidual,
            historical: bool,
        ) !void {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            const id = residual.id;
            try self.validateResidualWait(a, parent, residual);
            var operation_value = try self.record(
                state.ControllerSuccession,
                a,
                "controller_succession",
                residual.succession,
                parent.id,
            );
            defer operation_value.deinit();
            const runtime_cut = try self.controllerRuntimeAt(
                a,
                parent,
                (operation_value.value.activation_event orelse return error.InvalidArchive) -| 1,
            );
            if (!std.meta.eql(residual.runtime, runtime_cut.runtime)) return error.InvalidArchive;
            if (operation_value.value.phase != .activated or !std.meta.eql(
                operation_value.value.residual,
                id,
            ) or !std.meta.eql(
                operation_value.value.predecessor,
                residual.controller,
            ) or !std.meta.eql(
                operation_value.value.checkpoint,
                residual.initial_checkpoint,
            )) return error.InvalidArchive;
            try self.validateResidualCheckpoint(
                a,
                parent,
                residual,
                operation_value.value,
                historical,
            );
        }
        fn validateResidualWait(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            residual: state.ControllerResidual,
        ) !void {
            if (residual.blocker == .waiting_workspace) {
                if (!residual.cancellation_applied or
                    residual.schedule != .parked)
                    return error.InvalidArchive;
                const current = residual.current_occurrence orelse return error.InvalidArchive;
                var waiting = try self.record(
                    workspace.Wait,
                    a,
                    "workspace_wait",
                    current,
                    parent.id,
                );
                defer waiting.deinit();
                if (!std.meta.eql(waiting.value.id, current) or !std.meta.eql(
                    waiting.value.task,
                    parent.id,
                )) return error.InvalidArchive;
            }
        }
        fn validateResidualCheckpoint(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            residual: state.ControllerResidual,
            operation_value: state.ControllerSuccession,
            historical: bool,
        ) !void {
            const binding = try self.controllerBinding(a, parent, residual.controller);
            const image = try self.store().object(a, binding.image, null);
            var prepared = try self.program.prepare(self.allocator, image);
            defer prepared.deinit();
            const checkpoint = try self.store().object(a, residual.checkpoint, null);
            var candidate = try kosmos.Session.restore(self.allocator, &prepared, checkpoint);
            defer candidate.deinit();
            var actual = try kosmos.invocation.finishPublication(a, &candidate, .receipt, null);
            defer actual.outcome.deinit();
            defer self.allocator.free(actual.checkpoint.?);
            try self.validateResidualOutcome(
                a,
                parent,
                residual,
                operation_value,
                historical,
                checkpoint,
                actual,
            );
        }
        fn validateResidualOutcome(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            residual: state.ControllerResidual,
            operation_value: state.ControllerSuccession,
            historical: bool,
            checkpoint: []const u8,
            actual: anytype,
        ) !void {
            const id = residual.id;
            const outcome = try data.invocation.encodeOwned(
                data.invocation.Outcome,
                a,
                actual.outcome.record,
            );
            if (!std.meta.eql(residual.outcome, state.Reference{
                .digest = storage.digest(outcome),
                .bytes = outcome.len,
            }) or !same(checkpoint, actual.checkpoint.?) or !same(
                @tagName(residual.outcome_kind),
                @tagName(actual.outcome.record),
            )) return error.InvalidArchive;
            try validateCancellation(
                a,
                .{
                    .cancellation_applied = residual.cancellation_applied,
                    .cancellation = @as(?state.Reason, .{ .bytes = "Controller superseded" }),
                },
                actual.outcome.record,
                checkpoint,
            );
            if (!residual.cancellation_applied and (!std.meta.eql(
                residual.checkpoint,
                residual.initial_checkpoint,
            ) or !std.meta.eql(
                residual.current_occurrence,
                operation_value.handoff,
            ))) return error.InvalidArchive;
            if (actual.outcome.record == .requested) {
                const occurrence_id = residual.current_occurrence orelse
                    return error.InvalidArchive;
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    occurrence_id,
                    parent.id,
                );
                defer pending.deinit();
                const bytes = actual.outcome.record.requested.request;
                if (!std.meta.eql(pending.value.request_object, state.Reference{
                    .digest = storage.digest(bytes),
                    .bytes = bytes.len,
                }) or
                    pending.value.work != null or
                    (residual.cancellation_applied and
                        !std.meta.eql(
                            pending.value.residual,
                            id,
                        ))) return error.InvalidArchive;
            } else if (residual.current_occurrence != null) return error.InvalidArchive;
            if (residual.outer_operation) |pending| _ = try self.validateControllerOperation(
                a,
                parent,
                pending,
                residual,
                historical,
            );
        }
        fn validateResidualObservation(
            self: *Self,
            a: std.mem.Allocator,
            observed: state.ControllerResidualObservation,
        ) !void {
            var current = try self.record(
                state.ControllerResidual,
                a,
                "controller_residual",
                observed.id,
                observed.task,
            );
            defer current.deinit();
            inline for (.{
                "controller",
                "succession",
                "initial_checkpoint",
                "runtime",
            }) |field| if (!std.meta.eql(
                @field(observed, field),
                @field(current.value, field),
            )) return error.InvalidArchive;
            if (observed.execution_revision > current.value.execution_revision or
                observed.control_revision > current.value.control_revision or
                observed.control_revision == 0)
                return error.InvalidArchive;
            if (observed.execution_revision == current.value.execution_revision) inline for (.{
                "checkpoint",
                "outcome",
                "outcome_kind",
                "current_occurrence",
                "cancellation_applied",
            }) |field| {
                if (!std.meta.eql(
                    @field(observed, field),
                    @field(current.value, field),
                )) return error.InvalidArchive;
            };
            var parent = try self.task(a, observed.task);
            defer parent.deinit();
            try self.validateControllerResidualValue(
                self.allocator,
                parent.value,
