        fn controllerResidualControl(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            id: state.Digest,
            execution: u64,
            control: u64,
            command: workspace.Command,
        ) !Admission {
            const request = try operation(workspace.ResidualControlRequest, a, .{
                .task = task_id,
                .residual = id,
                .execution = execution,
                .control = control,
                .command = command,
            });
