            defer parent.deinit();
            try self.compatible(parent.value);
            var saved = try self.record(
                state.ControllerResidual,
                a,
                "controller_residual",
                id,
                task_id,
            );
            defer saved.deinit();
            const value = saved.value;
            if (execution != value.execution_revision or
                control != value.control_revision)
                return error.StaleRevision;
            if (value.outcome_kind == .completed or
                value.outcome_kind == .failed or
                value.outcome_kind == .cancelled)
                return error.TerminalTask;
            const rearmed = try self.rearmControllerResidual(a, task_id, value, command);
            return self.commitResidualControl(
                a,
                parent.value,
                operation_id,
                request,
                value,
                command,
                rearmed,
