        fn rearmControllerResidual(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            value: state.ControllerResidual,
            command: workspace.Command,
        ) !?occurrence.Occurrence {
            var rearmed: ?occurrence.Occurrence = null;
            if (value.current_occurrence) |current| {
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    current,
                    task_id,
                );
                defer pending.deinit();
                if (pending.value.state == .unknown or
                    pending.value.state == .dispatching)
                    return error.UnsettledOccurrence;
                if (command != .park and
                    pending.value.state == .not_sent) rearmed = try occurrence.rearm(
                    pending.value,
                    .{
                        .id = current,
                        .task = task_id,
                        .residual = pending.value.residual,
                        .request = pending.value.request,
                    },
                );
            }

            return rearmed;
        }
        fn commitResidualControl(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_id: []const u8,
            request: state.Digest,
            initial: state.ControllerResidual,
            command: workspace.Command,
            rearmed: ?occurrence.Occurrence,
        ) !Admission {
            var value = initial;
            const task_id = parent.id;
            const id = value.id;
            const execution = value.execution_revision;
            const control = value.control_revision;
            try self.ensureOwnershipCapacity(task_id);
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            value.control_revision = try std.math.add(u64, value.control_revision, 1);
            value.schedule = if (command == .park) .parked else .queued;
            value.blocker = null;
            try self.store().begin();
            defer self.store().rollback();
            if (rearmed) |pending| try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                task_id,
                pending,
            );
            try self.store().putRecord(
                state.ControllerResidual,
                "controller_residual",
                id,
                task_id,
                value,
            );
            const admitted = try self.workspaceCommit(
                a,
                parent,
                operation_id,
                request,
                id,
                .residual,
                try self.snapshotRecord(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    task_id,
                ),
                .{ .residual = .{
                    .execution = execution,
                    .control = control,
                    .command = command,
                } },
            );
            const subject: workspace.Subject = .{ .task = task_id, .residual = id };
            if (command == .park) self.subjectRemove(subject) else {
                self.claim(task_id);
            }
            return admitted;
        }
        fn activateController(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: state.ControllerSuccession,
        ) !Step {
            try self.controllerCutCurrent(a, parent, initial);
            const boot = initial.boot orelse return error.CorruptState;
            var program = try self.workspaceProgram(
                a,
                parent.id,
                initial.successor orelse return error.CorruptState,
            );
            defer program.deinit();
            const old = try self.controllerBinding(a, parent, initial.predecessor);
            const epoch = try std.math.add(u64, parent.controller_epoch, 1);
            const bytes = try self.store().object(a, boot.outcome, null);
            defer a.free(bytes);
            var outcome = try data.invocation.decode(data.invocation.Outcome, a, bytes);
            defer outcome.deinit();
            if (outcome.value != .requested) return error.InvalidControllerBoot;
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                outcome.value.requested.request,
            );
            defer request.deinit();
            if (!same(
                request.value.binding.semantic_identity,
                contracts.controller.boot_identity,
            )) return error.InvalidControllerBoot;
            return self.activateDecodedController(
                a,
                parent,
                initial,
                program.value,
                old,
                epoch,
                outcome.value.requested.request,
                request.value,
            );
        }
        const ControllerActivationPlacement = controllerActivationPlacementType();
        fn controllerActivationPlacementType() type {
            return struct {
                behavior: ?@import("placement.zig").Signed(@import("placement.zig").Behavior),
                custody: ?@import("placement.zig").Custody,
            };
        }
        fn controllerActivationPlacement(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: state.ControllerSuccession,
            old: state.ControllerBinding,
            epoch: u64,
            binding_id: state.Digest,
        ) !ControllerActivationPlacement {
            const p = @import("placement.zig");
            const journal = @import("placement_journal.zig");
            var custody = if (self.profile.placement != null) try journal.custody(
                self.store(),
                a,
                .{ .task = parent.id },
            ) else null;
            defer if (custody) |*saved| saved.deinit();
            var next_custody: ?p.Custody = null;
            const behavior: ?p.Signed(p.Behavior) = if (self.profile.placement) |placement| blk: {
                const site = try self.placementSite();
                var current = if (custody) |saved| saved.value else try self.initialCustody(
                    a,
                    .{ .task = parent.id },
                    site,
                );
                try current.requireLocal(site);
                if (current.epoch != parent.controller_epoch) return error.StaleController;
                current.epoch = epoch;
                next_custody = current;
                break :blk try p.sign(p.Behavior, a, placement.signing_key, .{
                    .operation = initial.id,
                    .task = parent.id,
                    .owner = site,
                    .previous_epoch = parent.controller_epoch,
                    .epoch = epoch,
                    .predecessor = old.id,
                    .successor = binding_id,
                    .event_cut = parent.event_high,
                });
            } else null;

            return .{ .behavior = behavior, .custody = next_custody };
        }
        fn activatedControllerTask(
            parent: state.Task,
            boot: anytype,
            binding_id: state.Digest,
            occurrence_id: state.Digest,
            epoch: u64,
        ) !state.Task {
            var value = parent;
            value.revision = try std.math.add(u64, value.revision, 1);
            value.execution_revision = try std.math.add(u64, value.execution_revision, 1);
            value.controller = binding_id;
            value.controller_epoch = epoch;
            value.controller_interaction = null;
            value.controller_succession = null;
            value.controller_runtime = null;
            value.realization_revision = 0;
            value.checkpoint = boot.checkpoint;
            value.outcome = boot.outcome;
            value.outcome_kind = .requested;
            value.current_occurrence = occurrence_id;
            value.schedule = .queued;
            value.blocker = null;

            return value;
        }
        const ControllerActivationRecords = controllerActivationRecordsType();
        fn controllerActivationRecordsType() type {
            return struct {
                binding: state.ControllerBinding,
                residual: state.ControllerResidual,
            };
        }
        fn controllerActivationRecords(
            parent: state.Task,
            initial: state.ControllerSuccession,
            program: workspace.Program,
            old: state.ControllerBinding,
            request: data.invocation.Request,
            binding_id: state.Digest,
            residual_id: state.Digest,
            epoch: u64,
            activation_event: u64,
        ) ControllerActivationRecords {
            const binding: state.ControllerBinding = .{
                .id = binding_id,
                .task = parent.id,
                .epoch = epoch,
                .activated_at = activation_event,
                .program = initial.successor.?,
                .image = program.description.image,
                .program_identity = request.binding.program_identity,
                .predecessor = old.id,
            };
            const residual: state.ControllerResidual = .{
                .id = residual_id,
                .task = parent.id,
                .controller = old.id,
                .succession = initial.id,
                .runtime = parent.controller_runtime,
                .initial_checkpoint = parent.checkpoint,
                .checkpoint = parent.checkpoint,
                .outcome = parent.outcome,
                .outcome_kind = parent.outcome_kind,
                .current_occurrence = parent.current_occurrence,
                .execution_revision = parent.execution_revision,
            };

            return .{ .binding = binding, .residual = residual };
        }
        fn writeControllerActivation(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            initial: state.ControllerSuccession,
            operation_value: state.ControllerSuccession,
            records: ControllerActivationRecords,
            placement: ControllerActivationPlacement,
            occurrence_id: state.Digest,
            request: data.invocation.Request,
            request_bytes: []const u8,
        ) !void {
            const p = @import("placement.zig");
            const journal = @import("placement_journal.zig");
            if (placement.behavior) |decision| {
                try self.store().createRecord(
                    p.BehaviorRecord,
                    "placement_behavior",
                    initial.id,
                    value.id,
                    .{ .id = initial.id, .task = value.id, .decision = decision },
                );
                try journal.putCustody(self.store(), a, placement.custody.?);
            }
            try self.store().createRecord(
                state.ControllerBinding,
                "controller_binding",
                records.binding.id,
                value.id,
                records.binding,
            );
            try self.store().createRecord(
                state.ControllerResidual,
                "controller_residual",
                records.residual.id,
                value.id,
                records.residual,
            );
            try self.store().putRecord(
                state.ControllerSuccession,
                "controller_succession",
                initial.id,
                value.id,
                operation_value,
            );
            try self.writeActivationOccurrence(
                value,
                records.binding,
                occurrence_id,
                request,
                request_bytes,
            );
        }
        fn writeActivationOccurrence(
            self: *Self,
            value: state.Task,
            binding: state.ControllerBinding,
            occurrence_id: state.Digest,
            request: data.invocation.Request,
            request_bytes: []const u8,
        ) !void {
            try self.store().createRecord(
                occurrence.Occurrence,
                "occurrence",
                occurrence_id,
                value.id,
                .{
                    .id = occurrence_id,
                    .task = value.id,
                    .request = request.request_identity,
                    .request_object = try self.store().putObject(request_bytes),
                },
            );
            try self.store().createRecord(
                workspace.ExecutionRoute,
                "execution_route",
                occurrence_id,
                value.id,
                .{
                    .id = occurrence_id,
                    .task = value.id,
                    .work = null,
                    .image = binding.image,
                    .program_identity = binding.program_identity,
                    .controller = binding.id,
                    .controller_epoch = binding.epoch,
                },
            );
        }
        fn commitControllerActivation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: *state.Task,
            initial: state.ControllerSuccession,
            operation_value: state.ControllerSuccession,
            records: ControllerActivationRecords,
            placement: ControllerActivationPlacement,
            occurrence_id: state.Digest,
            request: data.invocation.Request,
            request_bytes: []const u8,
            event_data: []const u8,
        ) !Step {
            try self.store().begin();
            defer self.store().rollback();
            try self.writeControllerActivation(
                a,
                value.*,
                initial,
                operation_value,
                records,
                placement,
                occurrence_id,
                request,
                request_bytes,
            );
            try self.putRootOperation(a, .{
                .id = rootIdentity(value.id),
                .task = value.id,
                .execution_revision = value.execution_revision,
                .pending = null,
            });
            try self.subjectPublicationEvent(value, .controller, event_data, &.{}, &.{
                try self.residualPublication(a, records.residual),
            }, null, null, .{ .before = .from(parent), .after = .from(value.*) });
            try self.persistScheduled(
                a,
                value.*,
                parent.revision,
                "controller.activate",
                .preserve,
                &.{ .{ .task = value.id, .residual = records.residual.id }, .{ .task = value.id } },
            );
            return .progressed;
        }
        fn activateDecodedController(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: state.ControllerSuccession,
            program: workspace.Program,
            old: state.ControllerBinding,
            epoch: u64,
            request_bytes: []const u8,
            request: data.invocation.Request,
        ) !Step {
            var binding_id: state.Digest = undefined;
            var residual_id: state.Digest = undefined;
            var occurrence_id: state.Digest = undefined;
            try self.io.randomSecure(&binding_id);
            try self.io.randomSecure(&residual_id);
            try self.io.randomSecure(&occurrence_id);
            const placement = try self.controllerActivationPlacement(
                a,
                parent,
                initial,
                old,
                epoch,
                binding_id,
            );
            const event_data = try std.fmt.allocPrint(
                a,
                "{{\"operation\":\"{s}\",\"phase\":\"activated\",\"epoch\":\"{d}\"}}",
                .{ std.fmt.bytesToHex(initial.id, .lower), epoch },
            );
            defer a.free(event_data);
            try self.runnable.ensureUnusedCapacity(self.allocator, 2);
            try self.retire(a);
            var value = try activatedControllerTask(
                parent,
                initial.boot.?,
                binding_id,
                occurrence_id,
                epoch,
            );
            var operation_value = initial;
            operation_value.phase = .activated;
            operation_value.activated_epoch = epoch;
            operation_value.activation_event = try std.math.add(u64, value.event_high, 1);
            operation_value.residual = residual_id;
            const records = controllerActivationRecords(
                parent,
                initial,
                program,
                old,
                request,
                binding_id,
                residual_id,
                epoch,
                operation_value.activation_event.?,
            );
            return self.commitControllerActivation(
                a,
                parent,
                &value,
                initial,
                operation_value,
                records,
                placement,
                occurrence_id,
                request,
                request_bytes,
                event_data,
            );
        }
        fn residualProvenance(value: state.ControllerResidual) kosmos.RuntimeCapsule.Provenance {
            return .{ .execution = value.id, .custody = value.controller, .publication = .{
                .digest = value.checkpoint.digest,
                .bytes = value.checkpoint.bytes,
            } };
        }
        fn retainResidualOperation(self: *Self, a: std.mem.Allocator, active: Active) !void {
            if (active.root_control == null) return;
            var saved = try self.record(
                state.ControllerResidual,
                a,
                "controller_residual",
                active.subject.residual,
                active.task,
            );
            defer saved.deinit();
            if (saved.value.execution_revision != active.execution_revision)
                return error.CorruptState;
            const capsule = try active.driver.retainCapsule(residualProvenance(saved.value));
            const dependencies = try capsuleDependencies(a, capsule);
            defer a.free(dependencies);
            const code = try active.driver.runtimeBytes(a);
            defer a.free(code);
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(code);
            saved.value.outer_operation = .{
                .capsule = try self.store().putObject(capsule),
                .dependencies = .{ .items = dependencies },
                .control = try self.store().putObject(active.root_control.?),
                .guest_quantum = active.root_quantum,
            };
            try self.store().putRecord(
                state.ControllerResidual,
                "controller_residual",
                saved.value.id,
                active.task,
                saved.value,
            );
            try self.namespace.commit("controller.residual-suspend");
            self.active.?.outer_operation = saved.value.outer_operation.?.capsule;
        }
        fn residualResident(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: state.ControllerResidual,
        ) !*evaluator.Driver {
            if (self.active) |active| {
                if (std.meta.eql(
                    active.task,
                    parent.id,
                ) and active.subject == .residual and std.meta.eql(
                    active.subject.residual,
                    value.id,
                ) and active.execution_revision == value.execution_revision) return active.driver;
                try self.retire(a);
            }
            const binding = try self.controllerBinding(a, parent, value.controller);
            const image = try self.store().object(a, binding.image, null);
            defer a.free(image);
            var runtime = try self.controllerRuntime(a, parent.id, binding.image, value.runtime);
            defer runtime.deinit();
            var root_control: ?[]u8 = null;
            errdefer if (root_control) |bytes| self.allocator.free(bytes);
            var ready = false;
            const driver = if (value.outer_operation) |pending| blk: {
                root_control = try self.store().object(self.allocator, pending.control, null);
                const capsule = try self.store().object(a, pending.capsule, null);
                defer a.free(capsule);
                ready = try self.validateControllerOperation(a, parent, pending, value, false);
                const Owner = struct {
                    value: state.ControllerResidual,
                    fn claim(
                        context: *anyopaque,
                        ref: kosmos.RuntimeCapsule.Reference,
                        record_value: kosmos.RuntimeCapsule.Record,
                        _: kosmos.RuntimeCapsule.Reference,
                    ) !void {
                        const owner: *@This() = @ptrCast(@alignCast(context));
                        if (!std.meta.eql(
                            ref.digest,
                            owner.value.outer_operation.?.capsule.digest,
                        ) or !std.meta.eql(
                            record_value.provenance,
                            residualProvenance(owner.value),
                        )) return error.InvalidArchive;
                    }
                };
                var owner: Owner = .{ .value = value };
                break :blk try evaluator.Driver.openCapsule(
                    self.allocator,
                    image,
                    &runtime,
                    capsule,
                    .{ .context = &owner, .claim = Owner.claim },
                );
            } else blk: {
                const checkpoint = try self.store().object(a, value.checkpoint, null);
                defer a.free(checkpoint);
                break :blk try evaluator.Driver.openSelected(
                    self.allocator,
                    image,
                    .{ .state = checkpoint },
                    &runtime,
                );
            };
            self.active = .{
                .task = parent.id,
                .subject = .{ .residual = value.id },
                .execution_revision = value.execution_revision,
                .driver = driver,
                .root_control = root_control,
                .root_cut_ready = ready,
                .root_quantum = if (value.outer_operation) |pending| pending.guest_quantum else 0,
            };
            return driver;
        }
        fn pumpControllerResidual(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !Step {
            self.requireCustody(a, task_id, null) catch |err| {
                if (err != error.CustodyNotLocal) return err;
                self.subjectRemove(.{ .task = task_id, .residual = id });
                return .idle;
            };
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            var saved = try self.record(
                state.ControllerResidual,
                a,
                "controller_residual",
                id,
                task_id,
            );
            defer saved.deinit();
            const residual = saved.value;
            if (residual.outcome_kind == .completed or
                residual.outcome_kind == .failed or
                residual.outcome_kind == .cancelled)
            {
                self.subjectRemove(.{ .task = task_id, .residual = id });
                if (try self.taskCleanupComplete(a, parent.value)) self.unclaim(task_id);
                return .idle;
            }
            if (residual.schedule == .parked) {
                self.subjectRemove(.{ .task = task_id, .residual = id });
                return .idle;
            }
            return self.pumpResidentResidual(a, parent.value, residual);
        }
        fn prepareResidualControl(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            residual: state.ControllerResidual,
            driver: *evaluator.Driver,
            current: ?contracts.Decoded(occurrence.Occurrence),
        ) !?Step {
            const task_id = parent.id;

            var control: data.invocation.Control = .none;
            if (!residual.cancellation_applied) {
                control = .{ .cancel = .{ .text = "Controller superseded" } };
            } else if (current) |item| switch (item.value.state) {
                .ready => return try self.dispatch(a, parent, item.value),
                .captured => return try self.interpretCapture(a, parent, item.value),
                .settled_reply => |reply| control = .{
                    .reply = try self.store().acquiredObject(a, reply.reply, null),
                },
                .unknown => |attempt| {
                    if (try self.pendingRecovery(
                        a,
                        task_id,
                        item.value.id,
                        attempt.id,
                    )) |recovery_id| return try self.recoveryWork(
                        a,
                        parent,
                        item.value,
                        recovery_id,
                    );
                    return .idle;
                },
                .dispatching, .not_sent => return .idle,
                else => return error.CorruptState,
            } else if (residual.outcome_kind == .yielded) control = .resume_yield;
            const encoded = try contracts.encodeOwned(
                data.invocation.Control,
                self.allocator,
                control,
            );
            errdefer self.allocator.free(encoded);
            try driver.beginAdvance(control, 256);
            self.active.?.root_control = encoded;
            self.active.?.root_quantum = 256;

            return null;
        }
        fn consumeResidualOccurrence(
            task_id: state.TaskId,
            control: data.invocation.Control,
            current: ?contracts.Decoded(occurrence.Occurrence),
        ) !?occurrence.Occurrence {
            var consumed: ?occurrence.Occurrence = null;
            if (current) |item| {
                if (control == .reply or control == .cancel) consumed = try occurrence.consumed(
                    item.value,
                    .{
                        .id = item.value.id,
                        .task = task_id,
                        .work = item.value.work,
                        .residual = item.value.residual,
                        .request = item.value.request,
                    },
                    if (control == .cancel) .cancel else .{
                        .reply = storage.digest(control.reply),
                    },
                    true,
                );
            }

            return consumed;
        }
        fn pumpResidentResidual(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            residual: state.ControllerResidual,
        ) !Step {
            const task_id = parent.id;
            const driver = try self.residualResident(a, parent, residual);
            var current: ?contracts.Decoded(occurrence.Occurrence) = null;
            defer if (current) |*item| item.deinit();
            if (residual.current_occurrence) |occurrence_id| current = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                occurrence_id,
                task_id,
            );
            if (self.active.?.root_control == null) {
                if (try self.prepareResidualControl(
                    a,
                    parent,
                    residual,
                    driver,
                    current,
                )) |step| return step;
            }
            var decoded = try contracts.decodeOwned(
                data.invocation.Control,
                a,
                self.active.?.root_control.?,
            );
            defer decoded.deinit();
            const control = decoded.value;
            const consumed = try consumeResidualOccurrence(task_id, control, current);
            return self.advanceResidualController(a, parent, residual, driver, control, consumed);
        }
        fn storeResidualRequest(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            residual: *state.ControllerResidual,
            request_bytes: []const u8,
        ) !void {
            const task_id = value.id;
            const id = residual.id;

            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                request_bytes,
            );
            defer request.deinit();
            const binding = try self.controllerBinding(a, value, residual.controller);
            if (!std.meta.eql(
                request.value.binding.program_identity,
                binding.program_identity,
            )) return error.InvalidControllerBinding;
            var occurrence_id: state.Digest = undefined;
            try self.io.randomSecure(&occurrence_id);
            try self.store().createRecord(
                occurrence.Occurrence,
                "occurrence",
                occurrence_id,
                task_id,
                .{
                    .id = occurrence_id,
                    .task = task_id,
                    .residual = id,
                    .request = request.value.request_identity,
                    .request_object = try self.store().putObject(request_bytes),
                },
            );
            try self.store().createRecord(
                workspace.ExecutionRoute,
                "execution_route",
                occurrence_id,
                task_id,
                .{
                    .id = occurrence_id,
                    .task = task_id,
                    .work = null,
                    .residual = id,
                    .image = binding.image,
                    .program_identity = binding.program_identity,
                    .controller = binding.id,
                    .controller_epoch = binding.epoch,
                },
            );
            residual.current_occurrence = occurrence_id;
            residual.outcome_kind = .requested;
        }
        fn storeResidualOutcome(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            residual: *state.ControllerResidual,
            outcome: data.invocation.Outcome,
        ) !void {
            switch (outcome) {
                .progressed => residual.outcome_kind = .progressed,
                .yielded => residual.outcome_kind = .yielded,
                .completed => residual.outcome_kind = .completed,
                .failed => residual.outcome_kind = .failed,
                .cancelled => residual.outcome_kind = .cancelled,
                .requested => |requested| try self.storeResidualRequest(
                    a,
                    value,
                    residual,
                    requested.request,
                ),
                .needs_capacity => unreachable,
            }
        }
        fn publishResidualAdvance(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: state.ControllerResidual,
            driver: *evaluator.Driver,
            control: data.invocation.Control,
            consumed: ?occurrence.Occurrence,
            publication: anytype,
            outcome: data.invocation.Outcome,
        ) !Step {
            var residual = initial;
            const task_id = parent.id;
            const id = residual.id;
            residual.cancellation_applied = residual.cancellation_applied or control == .cancel;
            residual.execution_revision = try std.math.add(u64, residual.execution_revision, 1);
            residual.current_occurrence = null;
            residual.outer_operation = null;
            residual.schedule = .queued;
            var value = parent;
            value.revision = try std.math.add(u64, value.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            residual.checkpoint = try self.store().putObject(publication.checkpoint);
            residual.outcome = try self.store().putObject(publication.outcome);
            if (consumed) |item| try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                item.id,
                task_id,
                item,
            );
            try self.storeResidualOutcome(a, value, &residual, outcome);

            const terminal = residual.outcome_kind == .completed or
                residual.outcome_kind == .failed or
                residual.outcome_kind == .cancelled;
            if (terminal) residual.schedule = .parked;
            try self.store().putRecord(
                state.ControllerResidual,
                "controller_residual",
                id,
                task_id,
                residual,
            );
            try self.residualProgressEvent(a, &value, residual);
            try self.persist(a, value, parent.revision, "controller.residual", .preserve);
            self.active.?.execution_revision = residual.execution_revision;
            if (terminal) {
                self.subjectRemove(.{ .task = task_id, .residual = id });
                try driver.close();
                try driver.destroy();
                self.active = null;
            }
            return .progressed;
        }
        fn advanceResidualController(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            residual: state.ControllerResidual,
            driver: *evaluator.Driver,
            control: data.invocation.Control,
            consumed: ?occurrence.Occurrence,
        ) !Step {
            if (!self.active.?.root_cut_ready) {
                var progress = try driver.pump(65536);
                defer progress.deinit();
                if (progress == .suspended) return .progressed;
                if (progress != .event or
                    progress.event.value != .cut)
                    return error.InvalidRuntimeProgress;
                self.active.?.root_cut_ready = true;
            }
            const publication = try driver.drive(a, .none, 0);
            defer a.free(publication.outcome);
            errdefer self.store().fence();
            self.allocator.free(self.active.?.root_control.?);
            self.active.?.root_control = null;
            self.active.?.root_cut_ready = false;
            var outcome = try data.invocation.decode(
                data.invocation.Outcome,
                a,
                publication.outcome,
            );
            defer outcome.deinit();
            if (outcome.value == .needs_capacity) return error.Capacity;
            return self.publishResidualAdvance(
                a,
                parent,
                residual,
                driver,
                control,
                consumed,
                publication,
                outcome.value,
            );
        }
        fn saveControllerSuccession(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
        ) !Step {
            var value = parent;
            value.revision = try std.math.add(u64, value.revision, 1);
            if (operation_value.diagnostic != null) value.controller_succession = null;
            const parked = operation_value.diagnostic != null and
                operation_value.operator_admission != null and
                parent.cancellation == null;
            if (parked) value.schedule = .parked;
            try self.store().begin();
            defer self.store().rollback();
            try self.store().putRecord(
                state.ControllerSuccession,
                "controller_succession",
                operation_value.id,
                value.id,
                operation_value,
            );
            try self.persist(a, value, parent.revision, "controller.preparation", .preserve);
            if (parked) self.runnableRemove(value.id);
            return .progressed;
        }
        fn controllerPreparationFailure(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            err: anyerror,
        ) !Step {
            if (err == error.OutOfMemory or
                err == error.StorageUnavailable or
                err == error.CorruptState or
                err == error.CorruptObject)
                return err;
            var next = operation_value;
            next.phase = if (err == error.Canceled or
                err == error.StaleInstructions or
                err == error.StaleController) .aborted else .failed;
            next.diagnostic = .{ .operation = next.id, .code = .{
                .bytes = @errorName(err),
            }, .observation = .{ .bytes = @errorName(err) } };
            if (next.conversion_work) |id| {
                var work = try self.workspaceWork(a, parent.id, id);
                defer work.deinit();
                if (!work.value.terminal() and work.value.cancellation == null) {
                    const operation_id = try std.fmt.allocPrint(a, "controller:{s}:abort", .{
                        std.fmt.bytesToHex(next.id, .lower),
                    });
                    defer a.free(operation_id);
                    _ = try self.workspaceControl(
                        a,
                        operation_id,
                        parent.id,
                        id,
                        work.value.execution_revision,
                        work.value.control_revision,
                        .{ .cancel = .{ .bytes = "Controller preparation invalidated" } },
                    );
                }
            }
            var current = try self.task(a, parent.id);
            defer current.deinit();
            return self.saveControllerSuccession(a, current.value, next);
        }
        fn controllerCutCurrent(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
        ) !void {
            if (!std.meta.eql(
                parent.controller,
                operation_value.predecessor,
            ) or !std.meta.eql(
                parent.current_occurrence,
                operation_value.handoff,
            ) or !std.meta.eql(
                parent.checkpoint,
                operation_value.checkpoint,
            )) return error.StaleController;
            if (parent.next_message != operation_value.next_message or !std.meta.eql(
                parent.profile,
                operation_value.policy,
            )) return error.StaleInstructions;
            if (parent.cancellation != null) return error.Canceled;
            if (!try self.controllerPermission(a, parent)) return error.Unauthorized;
            try self.requireCustody(a, parent.id, null);
            if (self.profile.placement != null) {
                const p = @import("placement.zig");
                const journal = @import("placement_journal.zig");
                const site = try self.placementSite();
                try journal.requireSettled(self.store(), a, .{ .task = parent.id }, site);
                var moves = try self.store().database.prepare(
                    "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                        "HERE r.kind='placement_move' AND r.task=?",
                    &.{.{ .blob = &parent.id }},
                );
                defer moves.deinit();
                while (try moves.step() == .row) {
                    var moving = try contracts.decodeOwned(p.Move, a, try moves.bytes(0));
                    defer moving.deinit();
                    if (std.meta.eql(moving.value.owner, site) and
                        moving.value.decision == null and
                        !moving.value.cancelled)
                        return error.UnsettledRemoteControl;
                }
            }
        }
        fn pumpControllerSuccession(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
        ) !Step {
            var saved = try self.record(
                state.ControllerSuccession,
                a,
                "controller_succession",
                id,
                parent.id,
            );
            defer saved.deinit();
            const operation_value = saved.value;
            if (operation_value.phase != .preparing and
                operation_value.phase != .ready)
                return error.CorruptState;
            self.controllerCutCurrent(
                a,
                parent,
                operation_value,
            ) catch |err| return self.controllerPreparationFailure(
                a,
                parent,
                operation_value,
                err,
            );
            if (operation_value.phase == .ready) return self.activateController(
                a,
                parent,
                operation_value,
            );
            if (operation_value.conversion_work == null) {
                return self.startControllerConversion(a, parent, operation_value);
            }

            return self.pumpControllerConversion(a, parent, operation_value);
        }
        fn startControllerConversion(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
        ) !Step {
            const id = operation_value.id;

            const operation_id = try std.fmt.allocPrint(a, "controller:{s}:convert", .{
                std.fmt.bytesToHex(id, .lower),
            });
            defer a.free(operation_id);
            const input = try self.store().object(
                a,
                operation_value.conversion_input orelse return error.CorruptState,
                null,
            );
            defer a.free(input);
            _ = self.workspaceStartAdmitted(
                a,
                operation_id,
                parent.id,
                operation_value.converter orelse return error.CorruptState,
                input,
                .{ .stop = .terminal, .continuation = .owner_scheduled },
                null,
                null,
                null,
                .{ .none = .{} },
                operation_value,
                null,
            ) catch |err| return self.controllerPreparationFailure(
                a,
                parent,
                operation_value,
                err,
            );
            return .progressed;
        }
        fn pumpControllerConversion(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
        ) !Step {
            var conversion = try self.workspaceWork(
                a,
                parent.id,
                operation_value.conversion_work.?,
            );
            defer conversion.deinit();
            if (!conversion.value.terminal()) {
                if (conversion.value.blocker != null or
                    conversion.value.current_occurrence != null)
                    return self.controllerPreparationFailure(
                        a,
                        parent,
                        operation_value,
                        error.ControllerConversionBlocked,
                    );
                return .idle;
            }
            if (conversion.value.outcome_kind != .completed)
                return self.controllerPreparationFailure(
                    a,
                    parent,
                    operation_value,
                    if (conversion.value.outcome_kind ==
                        .cancelled)
                        error.ControllerConversionCanceled
                    else
                        error.ControllerConversionFailed,
                );
            return self.prepareControllerBoot(a, parent, operation_value, conversion.value);
        }
        fn prepareControllerBoot(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            conversion: workspace.Work,
        ) !Step {
            const private_ref = conversion.result orelse return error.CorruptState;
            const private = try self.store().object(a, private_ref, null);
            defer a.free(private);
            var successor = try self.workspaceProgram(
                a,
                parent.id,
                operation_value.successor orelse return error.CorruptState,
            );
            defer successor.deinit();
            const descriptor = successor.value.description.controller orelse
                return error.CorruptState;
            var schema = try data.schema.decode(a, descriptor.private_input.bytes);
            defer schema.deinit();
            try data.schema.validateValue(a, schema.descriptor, private);
            const anchor = try contracts.encodeOwned(contracts.controller.TaskAnchor, a, .{
                .task = parent.id,
            });
            defer a.free(anchor);
            const input = try std.mem.concat(a, u8, &.{ anchor, private });
            defer a.free(input);
            const image = try self.store().object(a, successor.value.description.image, null);
            defer a.free(image);
            return self.driveControllerBoot(a, parent, operation_value, private_ref, input, image);
        }
        fn commitControllerBoot(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: state.ControllerSuccession,
            private_ref: state.Reference,
            publication: anytype,
        ) !Step {
            var operation_value = initial;
            const id = operation_value.id;
            operation_value.converted = private_ref;
            operation_value.phase = .ready;
            var value = parent;
            value.revision = try std.math.add(u64, value.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            operation_value.boot = .{
                .checkpoint = try self.store().putObject(publication.checkpoint),
                .outcome = try self.store().putObject(publication.outcome),
            };
            try self.store().putRecord(
                state.ControllerSuccession,
                "controller_succession",
                id,
                parent.id,
                operation_value,
            );
            try self.persist(a, value, parent.revision, "controller.boot-ready", .preserve);
            try self.retire(a);
            return .progressed;
        }
        fn driveControllerBoot(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_value: state.ControllerSuccession,
            private_ref: state.Reference,
            input: []const u8,
            image: []const u8,
        ) !Step {
            const id = operation_value.id;
            try self.retire(a);
            var runtime = try self.program.retainRuntime();
            defer runtime.deinit();
            const driver = evaluator.Driver.openSelected(
                self.allocator,
                image,
                .{ .initial_args = input },
                &runtime,
            ) catch |err| return self.controllerPreparationFailure(
                a,
                parent,
                operation_value,
                err,
            );
            self.active = .{
                .task = parent.id,
                .subject = .{ .preparation = id },
                .execution_revision = 0,
                .driver = driver,
            };
            const publication = driver.drive(a, .none, 256) catch |err| {
                try self.retire(a);
                return self.controllerPreparationFailure(a, parent, operation_value, err);
            };
            defer a.free(publication.outcome);
            var outcome = try data.invocation.decode(
                data.invocation.Outcome,
                a,
                publication.outcome,
            );
            defer outcome.deinit();
            if (outcome.value != .requested) {
                try self.retire(a);
                return self.controllerPreparationFailure(
                    a,
                    parent,
                    operation_value,
                    error.InvalidControllerBoot,
                );
            }
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                outcome.value.requested.request,
            );
            defer request.deinit();
            if (!same(
                request.value.binding.semantic_identity,
                contracts.controller.boot_identity,
            ) or !same(
                request.value.binding.payload,
                input,
            )) return error.InvalidControllerBoot;
            return self.commitControllerBoot(a, parent, operation_value, private_ref, publication);
        }
        fn controllerSelection(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            response: []const u8,
        ) !?wc.Adoption {
            const entry = for (self.handlers.entries) |item| {
                if (item.declaration.controller_import == .deliberate) break item;
            } else return null;
            const callback = entry.declaration.controller_choice orelse return null;
            return self.store().project(?wc.Adoption, a, self.handlers, self.projectionBinding(
                parent,
            ), struct {
                callback: @TypeOf(callback),
                response: []const u8,
                pub fn run(this: @This(), context: registry.ProjectionContext) !?wc.Adoption {
                    return this.callback(context, this.response);
                }
            }{ .callback = callback, .response = response });
        }
        fn controllerPermission(self: *Self, a: std.mem.Allocator, parent: state.Task) !bool {
            const entry = for (self.handlers.entries) |item| {
                if (item.declaration.controller_import == .deliberate) break item;
            } else return false;
            const callback = entry.declaration.controller_permission orelse return false;
            return self.store().project(bool, a, self.handlers, self.projectionBinding(
                parent,
            ), struct {
                callback: @TypeOf(callback),
                pub fn run(this: @This(), context: registry.ProjectionContext) !bool {
                    return this.callback(context) catch |err| switch (err) {
                        error.ToolConstructionNotAdmitted => false,
                        else => return err,
                    };
                }
            }{ .callback = callback });
        }
        fn freeControllerViewWorks(
            a: std.mem.Allocator,
            snapshots: []const workspace.WorkObservation,
        ) void {
            for (snapshots) |snapshot| freeControllerViewWork(a, snapshot);
            a.free(snapshots);
        }
        fn freeControllerViewWork(a: std.mem.Allocator, snapshot: workspace.WorkObservation) void {
            const work = snapshot.work;
            a.free(work.inputs.items);
            a.free(work.runtime_dependencies.items);
            if (work.runtime_trace) |trace| a.free(trace.dependencies.items);
            if (work.outer_operation) |pending| a.free(pending.dependencies.items);
            if (work.guard) |guard| {
                if (guard.reference_operation) |pending| a.free(pending.dependencies.items);
                if (guard.failure) |failure| a.free(failure.bytes);
            }
            if (work.cancellation) |reason| a.free(reason.bytes);
            if (work.observer) |observer|
                @import("workspace_observers.zig").freeObserver(a, observer);
        }
        fn controllerView(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
        ) !struct {
            bytes: []u8,
            works: []workspace.WorkObservation,
        } {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            const messages = try self.controllerViewMessages(a, parent);
            const ids = try self.workspaceIds(a, parent.id);
            const works = try a.alloc(contracts.controller.WorkFact, ids.len);
            const snapshots = try allocator.alloc(workspace.WorkObservation, ids.len);
            var initialized: usize = 0;
            errdefer {
                for (snapshots[0..initialized]) |snapshot| freeControllerViewWork(
                    allocator,
                    snapshot,
                );
                allocator.free(snapshots);
            }
            var observers = CurrentObservers.init(a, parent.id, parent.event_high);
            defer observers.deinit();
            for (ids, works, snapshots) |id, *out, *snapshot| {
                snapshot.* = try self.freezeWorkspaceWork(
                    allocator,
                    parent.id,
                    try wp.reference(a, .work, id),
                    true,
                );
                initialized += 1;
                out.* = try self.controllerWorkFact(a, parent, id, snapshot.*, &observers);
            }
            return .{
                .works = snapshots,
                .bytes = try contracts.encodeOwned(
                    contracts.controller.OwnerView,
                    allocator,
                    .{
                        .task = parent.id,
                        .event_cut = parent.event_high,
                        .next_message = parent.next_message,
                        .policy = parent.profile.digest,
                        .input_schema = .{ .bytes = try values.schemaBytes(Types.Input, a) },
                        .input = .{ .bytes = try self.store().object(a, parent.input, null) },
                        .messages = .{ .items = messages },
                        .works = .{ .items = works },
                    },
                ),
            };
        }
        fn controllerWorkFact(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            snapshot: workspace.WorkObservation,
            observers: *CurrentObservers,
        ) !contracts.controller.WorkFact {
            const child = snapshot.work;
            return .{
                .work = try wp.reference(a, .work, id),
                .execution_revision = child.execution_revision,
                .control_revision = child.control_revision,
                .event_watermark = child.event_watermark,
                .observation = .{
                    .bytes = try json.canonical(
                        a,
                        try self.renderWorkspaceWorkObservationIn(
                            a,
                            child,
                            snapshot.occurrence,
                            parent.event_high,
                            .{ .current = observers },
                        ),
                    ),
                },
            };
        }
        fn controllerViewMessages(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
        ) ![]contracts.Bytes(null) {
            const messages = try a.alloc(contracts.Bytes(null), @intCast(parent.next_message - 1));
            const found = try a.alloc(bool, messages.len);
            @memset(found, false);
            var rows = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='message'",
                &.{.{ .blob = &parent.id }},
            );
            defer rows.deinit();
            while (try rows.step() == .row) {
                var saved = try contracts.decodeOwned(state.Message, a, try rows.bytes(0));
                defer saved.deinit();
                if (saved.value.ordinal == 0 or
                    saved.value.ordinal >= parent.next_message)
                    return error.CorruptState;
                const i: usize = @intCast(saved.value.ordinal - 1);
                if (found[i]) return error.CorruptState;
                found[i] = true;
                messages[i] = .{ .bytes = try self.store().object(a, saved.value.value, null) };
            }
            for (found) |present| if (!present) return error.CorruptState;
            return messages;
        }
        fn validateControllerViewIn(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            view: contracts.controller.OwnerView,
            snapshots: []const workspace.WorkObservation,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) anyerror!void {
            if (!std.meta.eql(view.task, parent.id) or
                view.event_cut > parent.event_high or
                view.next_message == 0 or
                view.next_message > parent.next_message or
                !std.meta.eql(view.policy, parent.profile.digest) or !same(
                view.input.bytes,
                try self.store().object(a, parent.input, null),
            ) or !same(
                view.input_schema.bytes,
                try values.schemaBytes(Types.Input, a),
            )) return error.InvalidArchive;
            try self.validateControllerViewMessages(a, parent, view);
            try self.validateControllerMessageCut(a, parent, view.event_cut, view.next_message);
            const ids = try self.workspaceScopeAt(a, parent.id, view.event_cut);
            if (ids.len != view.works.items.len or
                ids.len != snapshots.len)
                return error.InvalidArchive;
            for (ids, view.works.items, snapshots) |id, fact, snapshot| {
                const child = snapshot.work;
                if (!std.meta.eql(id, try wp.identity(fact.work, .work)) or !std.meta.eql(
                    id,
                    child.id,
                ) or
                    fact.execution_revision != child.execution_revision or
                    fact.control_revision != child.control_revision or
                    fact.event_watermark != child.event_watermark or
                    child.event_watermark != try self.workspacePublicationAt(
                        a,
                        parent.id,
                        id,
                        view.event_cut,
                    )) return error.InvalidArchive;
                try self.validateWorkspaceWorkSnapshotIn(parent, snapshot, records, checked);
                try self.validateHistoricalOccurrence(a, snapshot);
                if (!same(
                    fact.observation.bytes,
                    try json.canonical(
                        a,
                        try self.renderWorkspaceWorkObservationIn(
                            a,
                            child,
                            snapshot.occurrence,
                            view.event_cut,
                            .{
                                .historical = try checked.observer_successors.histories.get(
                                    parent.id,
                                    view.event_cut,
                                ),
                            },
                        ),
                    ),
                )) return error.InvalidArchive;
            }
        }
        fn validateControllerViewMessages(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            view: contracts.controller.OwnerView,
        ) !void {
            if (view.messages.items.len != view.next_message - 1) return error.InvalidArchive;
            const found = try a.alloc(bool, view.messages.items.len);
            @memset(found, false);
            var rows = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='message'",
                &.{.{ .blob = &parent.id }},
            );
            defer rows.deinit();
            while (try rows.step() == .row) {
                var saved_message = try contracts.decodeOwned(state.Message, a, try rows.bytes(0));
                defer saved_message.deinit();
                if (saved_message.value.ordinal >= view.next_message) continue;
                if (saved_message.value.ordinal == 0) return error.InvalidArchive;
                const i: usize = @intCast(saved_message.value.ordinal - 1);
                if (found[i] or !same(
                    view.messages.items[i].bytes,
                    try self.store().object(a, saved_message.value.value, null),
                )) return error.InvalidArchive;
                found[i] = true;
            }
            for (found) |present| if (!present) return error.InvalidArchive;
        }
        fn validateControllerMessageCut(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            event_cut: u64,
            expected_next_message: u64,
        ) !void {
            if (event_cut == 0 or
                event_cut > parent.event_high or
                expected_next_message == 0 or
                expected_next_message > parent.next_message)
                return error.InvalidArchive;
            var next_message: u64 = 1;
            var events = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=?",
                &.{ .{ .blob = &parent.id }, .{
                    .integer = std.math.cast(i64, event_cut) orelse return error.InvalidArchive,
                } },
            );
            defer events.deinit();
            while (try events.step() == .row) {
                var saved = try contracts.decodeOwned(state.Event, a, try events.bytes(0));
                defer saved.deinit();
                if (saved.value.kind == .message_queued) next_message = try std.math.add(
                    u64,
                    next_message,
                    1,
                );
            }
            if (next_message != expected_next_message) return error.InvalidArchive;
        }
        fn admitControllerSuccession(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            interaction: state.ControllerInteraction,
            command: wc.Adoption,
            operator: bool,
        ) !ControllerSuccessionAdmission {
            try self.validateControllerSuccessionAdmission(
                a,
                parent,
                interaction,
                command,
                operator,
            );
            const successor_id = try wp.identity(command.successor, .program);
            const converter_id = try wp.identity(command.converter, .program);
            var successor = try self.workspaceProgram(a, parent.id, successor_id);
            defer successor.deinit();
            _ = successor.value.description.controller orelse
                return error.InvalidControllerBinding;
            try self.validateControllerSelectedTrial(a, parent, command, successor_id);
            try self.validateControllerConversion(
                a,
                parent,
                interaction,
                successor.value,
                converter_id,
            );
            const carry = try self.store().object(a, interaction.carry, null);
            defer a.free(carry);
            const view = try self.controllerView(a, parent);
            defer a.free(view.bytes);
            errdefer freeControllerViewWorks(a, view.works);
            return .{
                .successor = successor_id,
                .converter = converter_id,
                .input = try std.mem.concat(a, u8, &.{ carry, view.bytes }),
                .works = view.works,
            };
        }
        fn validateControllerConversion(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            interaction: state.ControllerInteraction,
            successor: workspace.Program,
            converter_id: state.Digest,
        ) !void {
            var converter = try self.workspaceProgram(a, parent.id, converter_id);
            defer converter.deinit();
            const conversion = converter.value.description;
            if (conversion.controller != null or conversion.ports.items.len != 0 or
                (conversion.source_kind != .source_records and
                    conversion.source_kind != .component_recipe and
                    conversion.source_kind != .source_derivation))
                return error.ImpureControllerConversion;
            const carry_schema = try self.store().object(a, interaction.carry_schema, null);
            defer a.free(carry_schema);
            const expected_input = try @import(
                "controller_construction.zig",
            ).conversionSchema(
                a,
                carry_schema,
            );
            defer a.free(expected_input);
            if (!std.meta.eql(
                conversion.input_schema.digest,
                storage.digest(expected_input),
            ) or !std.meta.eql(
                conversion.result_schema.digest,
                storage.digest(successor.description.controller.?.private_input.bytes),
            )) return error.ControllerConversionSchemaMismatch;
            const result = try values.schemaBytes(Types.Output, a);
            defer a.free(result);
            const failure = try values.schemaBytes(Types.Failure, a);
            defer a.free(failure);
            if (!std.meta.eql(
                successor.description.result_schema.digest,
                storage.digest(result),
            ) or !std.meta.eql(
                successor.description.failure_schema.digest,
                storage.digest(failure),
            )) return error.ControllerResultSchemaMismatch;
        }
        fn validateControllerSelectedTrial(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            command: wc.Adoption,
            successor_id: state.Digest,
        ) !void {
            if (command.trial == .selected) {
                var work = try self.workspaceWork(
                    a,
                    parent.id,
                    try wp.identity(command.trial.selected, .work),
                );
                defer work.deinit();
                if (work.value.trial == null or
                    work.value.outcome_kind != .completed or
                    !std.meta.eql(
                        work.value.program,
                        successor_id,
                    )) return error.IncompatibleControllerTrial;
                var trial = try self.record(
                    workspace.Trial,
                    a,
                    "workspace_trial",
                    work.value.trial.?,
                    parent.id,
                );
                defer trial.deinit();
                if (!std.meta.eql(
                    trial.value.policy,
                    parent.profile,
                )) return error.IncompatibleControllerTrial;
            }
        }
        fn validateControllerSuccessionAdmission(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            interaction: state.ControllerInteraction,
            command: wc.Adoption,
            operator: bool,
        ) !void {
            if (!try self.controllerPermission(a, parent)) return error.Unauthorized;
            _ = try self.controllerBinding(a, parent, interaction.controller);
            if (command.expected_controller_epoch != parent.controller_epoch or
                (!operator and
                    interaction.epoch != parent.controller_epoch) or
                !same(
                    command.expected_handoff_identity.bytes,
                    &std.fmt.bytesToHex(interaction.id, .lower),
                ) or !std.meta.eql(
                parent.controller,
                interaction.controller,
            )) return error.StaleController;
            if ((!operator and parent.next_message != interaction.next_message) or !std.meta.eql(
                parent.profile,
                interaction.policy,
            )) return error.StaleInstructions;
            if (parent.cancellation != null) return error.Canceled;
            try self.requireCustody(a, parent.id, null);
        }
        fn controllerHandoff(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            response: []const u8,
        ) !ControllerHandoff {
            const command = (try self.controllerSelection(
                a,
                initial,
                response,
            )) orelse return .ordinary;
            const canonical = try contracts.encodeOwned(wc.Adoption, a, command);
            defer a.free(canonical);
            const id = initial.controller_interaction orelse return error.InvalidControllerBinding;
            if (try self.controllerHandoffReplay(a, initial, id, canonical)) |prior| return prior;
            var interaction = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                id,
                initial.id,
            );
            defer interaction.deinit();
            if (!std.meta.eql(
                interaction.value.handoff,
                pending.id,
            )) return error.InvalidControllerBinding;
            var operation_value: state.ControllerSuccession = .{
                .id = id,
                .task = initial.id,
                .command = undefined,
                .predecessor = interaction.value.controller,
                .handoff = pending.id,
                .checkpoint = initial.checkpoint,
                .outcome = initial.outcome,
                .event_cut = initial.event_high,
                .next_message = initial.next_message,
                .policy = initial.profile,
                .phase = .preparing,
            };
            defer freeControllerViewWorks(a, operation_value.view_works.items);
            var input: ?[]u8 = null;
            defer if (input) |bytes| a.free(bytes);
            if (self.admitControllerSuccession(
                a,
                initial,
                interaction.value,
                command,
                false,
            )) |admitted| {
                operation_value.successor = admitted.successor;
                operation_value.converter = admitted.converter;
                input = admitted.input;
                operation_value.view_works = .{ .items = admitted.works };
            } else |err| {
                if (err == error.OutOfMemory or
                    err == error.StorageUnavailable or
                    err == error.CorruptState or
                    err == error.CorruptObject)
                    return err;
                operation_value.phase = .rejected;
                operation_value.diagnostic = .{ .operation = id, .code = .{
                    .bytes = @errorName(err),
                }, .observation = .{ .bytes = @errorName(err) } };
            }
            return self.saveControllerHandoff(a, initial, &operation_value, canonical, input);
        }
        fn saveControllerHandoff(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            operation_value: *state.ControllerSuccession,
            canonical: []const u8,
            input: ?[]const u8,
        ) !ControllerHandoff {
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            if (operation_value.phase == .preparing) {
                value.controller_succession = operation_value.id;
            }
            try self.store().begin();
            defer self.store().rollback();
            operation_value.command = try self.store().putObject(canonical);
            if (input) |bytes| operation_value.conversion_input = try self.store().putObject(bytes);
            try self.store().createRecord(
                state.ControllerSuccession,
                "controller_succession",
                operation_value.id,
                initial.id,
                operation_value.*,
            );
            try self.persist(a, value, initial.revision, "controller.prepare", .preserve);
            return .progressed;
        }
        fn controllerHandoffReplay(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            id: state.Digest,
            canonical: []const u8,
        ) !?ControllerHandoff {
            if (try self.store().recordBytes(a, "controller_succession", id, initial.id)) |bytes| {
                defer a.free(bytes);
                var prior = try contracts.decodeOwned(state.ControllerSuccession, a, bytes);
                defer prior.deinit();
                if (!std.meta.eql(
                    prior.value.command.digest,
                    storage.digest(canonical),
                )) return error.OperationConflict;
                if (prior.value.diagnostic) |diagnostic| return .{
                    .diagnostic = .{ .operation = diagnostic.operation, .code = .{
                        .bytes = try a.dupe(u8, diagnostic.code.bytes),
                    }, .observation = .{
                        .bytes = try a.dupe(u8, diagnostic.observation.bytes),
                    } },
                };
                return .progressed;
            }
            return null;
        }
        fn controllerRecoveryCut(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
        ) !state.ControllerInteraction {
            if (parent.terminal() or
                parent.controller_succession != null or
                parent.cancellation != null)
                return error.ControllerRecoveryUnavailable;
            if (self.active) |active| if (std.meta.eql(active.task, parent.id) and
                active.subject == .root and
                active.root_control != null)
                return error.ControllerRecoveryUnavailable;
            var outer = try self.rootOperation(a, parent);
            defer if (outer) |*saved| saved.deinit();
            if (outer != null and
                outer.?.value.pending != null)
                return error.ControllerRecoveryUnavailable;
            const current = parent.current_occurrence orelse
                return error.ControllerRecoveryUnavailable;
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                current,
                parent.id,
            );
            defer pending.deinit();
            if (pending.value.state != .ready and
                pending.value.state != .not_sent)
                return error.UnsettledOccurrence;
            _ = try self.occurrenceSubject(a, parent, pending.value);
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                current,
                parent.id,
            );
            defer route.deinit();
            const id = parent.controller_interaction orelse
                return error.ControllerRecoveryUnavailable;
            if (!std.meta.eql(
                route.value.interaction,
                id,
            )) return error.ControllerRecoveryUnavailable;
            var saved = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                id,
                parent.id,
            );
            defer saved.deinit();
            if (!std.meta.eql(saved.value.model, current) and !std.meta.eql(
                saved.value.handoff,
                current,
            )) return error.ControllerRecoveryUnavailable;
            if (std.meta.eql(
                saved.value.model,
                current,
            ) and saved.value.handoff != null) return error.ControllerRecoveryUnavailable;
            return saved.value;
        }
        pub fn adoptController(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            expected_revision: u64,
            command: wc.Adoption,
        ) !Admission {
            const request = try operation(state.ControllerAdoptionRequest, a, .{
                .task = task_id,
                .revision = expected_revision,
                .command = command,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            try self.requireCustody(a, task_id, null);
            if (parent.value.revision != expected_revision) return error.StaleRevision;
            const interaction = try self.controllerRecoveryCut(a, parent.value);
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                parent.value.current_occurrence.?,
                task_id,
            );
            defer pending.deinit();
            const admitted = try self.admitControllerSuccession(
                a,
                parent.value,
                interaction,
                command,
                true,
            );
            defer a.free(admitted.input);
            defer freeControllerViewWorks(a, admitted.works);
            const encoded = try contracts.encodeOwned(wc.Adoption, a, command);
            defer a.free(encoded);
            var succession_id: state.Digest = undefined;
            try self.io.randomSecure(&succession_id);
            return self.publishControllerAdoption(a, .{
                .operation_id = operation_id,
                .task_id = task_id,
                .expected_revision = expected_revision,
                .request = request,
                .parent = parent.value,
                .interaction = interaction,
                .pending = pending.value,
                .admitted = admitted,
                .encoded = encoded,
                .succession_id = succession_id,
            });
        }
        fn publishControllerAdoption(
            self: *Self,
            a: std.mem.Allocator,
            cut: ControllerAdoption,
        ) !Admission {
            const event_data = try std.fmt.allocPrint(a, "{{\"operation\":\"{s}\"}}", .{
                std.fmt.bytesToHex(cut.succession_id, .lower),
            });
            defer a.free(event_data);
            try self.ensureOwnershipCapacity(cut.task_id);
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            try self.retire(a);
            var value = cut.parent;
            value.revision = try std.math.add(u64, value.revision, 1);
            value.controller_succession = cut.succession_id;
            value.schedule = .queued;
            value.blocker = null;
            try self.store().begin();
            defer self.store().rollback();
            try self.storeControllerAdoption(cut, value);
            try self.event(&value, .controller_requested, event_data);
            const receipt_value = try self.receipt(
                a,
                .adopt,
                cut.operation_id,
                cut.request,
                value,
                .accepted,
                null,
                null,
            );
            try self.persistScheduled(
                a,
                value,
                cut.expected_revision,
                "controller.operator-prepare",
                .acquire,
                &.{.{ .task = cut.task_id }},
            );
            return receipt_value;
        }
        fn storeControllerAdoption(
            self: *Self,
            cut: ControllerAdoption,
            value: state.Task,
        ) !void {
            try self.store().createRecord(
                state.ControllerSuccession,
                "controller_succession",
                cut.succession_id,
                cut.task_id,
                .{
                    .id = cut.succession_id,
                    .task = cut.task_id,
                    .command = try self.store().putObject(cut.encoded),
                    .predecessor = cut.interaction.controller,
                    .handoff = cut.parent.current_occurrence.?,
                    .checkpoint = cut.parent.checkpoint,
                    .outcome = cut.parent.outcome,
                    .event_cut = cut.parent.event_high,
                    .next_message = cut.parent.next_message,
                    .policy = cut.parent.profile,
                    .successor = cut.admitted.successor,
                    .converter = cut.admitted.converter,
                    .conversion_input = try self.store().putObject(cut.admitted.input),
                    .view_works = .{ .items = cut.admitted.works },
                    .phase = .preparing,
                    .operator_admission = .{
                        .revision = value.revision,
                        .event = try std.math.add(u64, value.event_high, 1),
                        .occurrence = cut.pending,
                    },
                },
            );
        }
        fn dispatchController(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            request: data.invocation.Request,
            subject: OccurrenceSubject,
        ) !Step {
            var payload = self.controllerReply(
                a,
                initial,
                pending,
                request,
            ) catch |err| return self.blockControllerRequest(a, initial, pending, err);
            defer a.free(payload);
            if (same(request.binding.semantic_identity, contracts.controller.handoff_identity)) {
                switch (self.controllerHandoff(
                    a,
                    initial,
                    pending,
                    payload[0 .. payload.len - 1],
                ) catch |err| return self.blockControllerRequest(
                    a,
                    initial,
                    pending,
                    err,
                )) {
                    .ordinary => {},
                    .progressed => return .progressed,
                    .diagnostic => |diagnostic| {
                        const encoded = try contracts.encodeOwned(
                            ?contracts.controller.Diagnostic,
                            a,
                            diagnostic,
                        );
                        defer a.free(encoded);
                        const replacement = try std.mem.concat(a, u8, &.{
                            payload[0 .. payload.len - 1],
                            encoded,
                        });
                        a.free(payload);
                        payload = replacement;
                    },
                }
            }
            return self.publishControllerReply(a, initial, pending, request, subject, payload);
        }
        fn publishControllerReply(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            request: data.invocation.Request,
            subject: OccurrenceSubject,
            payload: []const u8,
        ) !Step {
            const reply = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = payload,
            });
            defer a.free(reply);
            var attempt: state.Digest = undefined;
            try self.io.randomSecure(&attempt);
            const binding: occurrence.Binding = .{
                .id = pending.id,
                .task = pending.task,
                .request = pending.request,
            };
            const dispatched = try occurrence.dispatch(
                pending,
                binding,
                attempt,
                subject.cancelling,
                subject.cleanup,
            );
            const acquired = try occurrence.acquired(
                dispatched,
                binding,
                attempt,
                storage.digest(reply),
            );
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            value.schedule = .active;
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(reply);
            try self.storeControllerOffer(a, initial, pending, request, payload, &value);
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                value.id,
                acquired,
            );
            try self.persist(a, value, initial.revision, "controller.acquire", .preserve);
            return .progressed;
        }
        fn storeControllerOffer(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            request: data.invocation.Request,
            payload: []const u8,
            value: *state.Task,
        ) !void {
            if (same(request.binding.semantic_identity, contracts.controller.offer_identity)) {
                const controller = initial.controller orelse return error.InvalidControllerBinding;
                const binding_value = try self.controllerBinding(a, initial, controller);
                var program = try self.workspaceProgram(a, initial.id, binding_value.program);
                defer program.deinit();
                var entry = for (self.handlers.entries) |item| {
                    if (item.declaration.controller_import == .deliberate) break item;
                } else return error.MissingCapability;
                entry.controller_envelope = true;
                const proposal = try entry.payload(a, payload);
                const overlay = try self.controllerOverlay(
                    a,
                    initial,
                    controller,
                    pending.id,
                    initial.event_high,
                    initial.next_message,
                    initial.controller_epoch,
                );
                defer a.free(overlay);
                try self.store().createRecord(
                    state.ControllerInteraction,
                    "controller_interaction",
                    pending.id,
                    initial.id,
                    .{
                        .id = pending.id,
                        .task = initial.id,
                        .controller = controller,
                        .epoch = initial.controller_epoch,
                        .offered = try self.store().putObject(payload),
                        .carry = try self.store().putObject(payload[proposal.len..]),
                        .carry_schema = try self.store().putObject(
                            program.value.description.controller.?.carry.bytes,
                        ),
                        .overlay = try self.store().putObject(overlay),
                        .event_cut = initial.event_high,
                        .next_message = initial.next_message,
                        .policy = initial.profile,
