        fn blockControllerRequest(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            err: anyerror,
        ) !Step {
            return switch (err) {
                error.CorruptState, error.CorruptObject, error.StorageUnavailable => err,
                error.OutOfMemory, error.Capacity => self.blockedOccurrence(
                    a,
                    parent,
                    pending,
                    .capacity,
                ),
                error.Denied => self.blockedOccurrence(a, parent, pending, .denied),
                else => self.blockedOccurrence(a, parent, pending, .incompatible_profile),
            };
        }
        fn controllerOverlayCurrent(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            interaction: state.ControllerInteraction,
        ) !bool {
            if (interaction.next_message != parent.next_message or
                interaction.epoch != parent.controller_epoch) return false;
            const bytes = try self.store().object(a, interaction.overlay, null);
            defer a.free(bytes);
            var overlay = try json.parseAsset(a, bytes, bytes.len);
            defer overlay.deinit();
            const control = json.get(overlay.value, "control") orelse
                return error.InvalidControllerBinding;
            const target = try values.fromJson(
                wc.ControllerTarget,
                a,
                json.get(
                    control,
                    "realization_target",
                ) orelse return error.InvalidControllerBinding,
            );
            if (target != .action) return error.InvalidControllerBinding;
            return target.action.realization_revision == parent.realization_revision;
        }
        fn refreshControllerOverlay(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
        ) !bool {
            if (pending.work != null or pending.residual != null) return false;
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                pending.id,
                parent.id,
            );
            defer route.deinit();
            const id = route.value.interaction orelse return false;
            var saved = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                id,
                parent.id,
            );
            defer saved.deinit();
            if (!std.meta.eql(saved.value.model, pending.id) or !std.meta.eql(
                saved.value.controller,
                parent.controller orelse return error.InvalidControllerBinding,
            )) return error.InvalidControllerBinding;
            if (try self.controllerOverlayCurrent(a, parent, saved.value)) return false;
            if (pending.state != .ready) return error.UnsettledOccurrence;
            const overlay = try self.controllerOverlay(
                a,
                parent,
                saved.value.controller,
                id,
                parent.event_high,
                parent.next_message,
                parent.controller_epoch,
            );
            defer a.free(overlay);
            var value = parent;
            value.revision = try std.math.add(u64, parent.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            saved.value.overlay = try self.store().putObject(overlay);
            saved.value.next_message = parent.next_message;
            saved.value.event_cut = parent.event_high;
            saved.value.epoch = parent.controller_epoch;
            try self.store().putRecord(
                state.ControllerInteraction,
                "controller_interaction",
                id,
                parent.id,
                saved.value,
            );
            try self.persist(a, value, parent.revision, "controller.overlay", .preserve);
            return true;
        }
        fn dispatch(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
        ) !Step {
            const request_bytes = try self.store().object(a, pending.request_object, null);
            defer a.free(request_bytes);
            var request = try data.invocation.decode(data.invocation.Request, a, request_bytes);
            defer request.deinit();
            const subject = try self.occurrenceSubject(a, initial, pending);
            if (!same(&request.value.request_identity, &pending.request)) return error.CorruptState;
            if (pending.residual != null and controllerInternal(
                request.value.binding.semantic_identity,
            )) return self.blockedOccurrence(a, initial, pending, .denied);
            if (controllerInternal(
                request.value.binding.semantic_identity,
            )) return self.dispatchController(a, initial, pending, request.value, subject);
            const entry = self.handlers.admit(
                request.value,
                self.profile.authority,
                subject.image,
                registry.resourceIdentity(
                    self.application.image_identity,
                    initial.profile.digest,
                    initial.resources.items,
                ),
            ) catch |err|
                return self.blockedOccurrence(
                    a,
                    initial,
                    pending,
                    if (err == error.Denied) .denied else .missing_capability,
                );
            if (entry.declaration.kind != .leaf and
                (pending.work != null or
                    (pending.residual != null and
                        entry.declaration.kind != .workspace)))
                return self.blockedOccurrence(a, initial, pending, .missing_capability);
            if (pending.residual != null and
                entry.declaration.inference)
                return self.blockedOccurrence(a, initial, pending, .denied);
            if (entry.declaration.kind == .leaf and self.work != null) return .idle;
            return self.dispatchAdmitted(
                a,
                initial,
                pending,
                request.value,
                request_bytes,
                subject,
                entry,
