                a,
                initial,
                value,
                pending,
                entry,
                request,
                request_bytes,
                prompt,
                question_id,
                waiting,
            );
        }
        fn publishQuestion(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            value: *state.Task,
            pending: occurrence.Occurrence,
            entry: registry.Entry,
            request: data.invocation.Request,
            request_bytes: []const u8,
            prompt: []const u8,
            question_id: state.Digest,
            waiting: occurrence.Occurrence,
        ) !Step {
            try self.store().begin();
            defer self.store().rollback();
            const question: state.Question = .{
                .id = question_id,
                .task = value.id,
                .occurrence = pending.id,
                .revision = 1,
                .request_digest = pending.request,
                .pending_digest = request.binding.pending_state_digest,
                .answer_schema_id = try name(entry.declaration.answer_schema_id.?),
                .answer_schema_digest = storage.digest(entry.resume_schema),
                .request = try self.store().putObject(request_bytes),
                .prompt = try self.store().putObject(prompt),
                .answer = null,
                .receipt = null,
                .retired = false,
            };
            try self.store().createRecord(
                state.Question,
                "question",
                question_id,
                value.id,
                question,
            );
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                value.id,
                waiting,
            );
            const event_data = try state.questionData(a, question, prompt);
            const event_bytes = try json.canonical(a, event_data);
            defer a.free(event_bytes);
            try self.event(value, .input_required, event_bytes);
            try self.persist(a, value.*, initial.revision, "question.awaiting", .preserve);
            self.runnableRemove(value.id);
