        fn publishInbox(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            value: state.Task,
            pending: occurrence.Occurrence,
            binding: occurrence.Binding,
            attempt: state.Digest,
            dispatched: occurrence.Occurrence,
            input: contracts.InboxReply(Types.Message),
            message_decoded: ?contracts.Decoded(state.Message),
        ) !Step {
            const payload = try contracts.encodeOwned(
                contracts.InboxReply(Types.Message),
                a,
                input,
            );
            defer a.free(payload);
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = payload,
            });
            defer a.free(bound);
            const acquired = try occurrence.acquired(
                dispatched,
                binding,
                attempt,
                storage.digest(bound),
            );
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(bound);
            if (message_decoded) |saved| try self.store().putRecord(
                state.Message,
                "message",
                saved.value.id,
                value.id,
                saved.value,
            );
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                value.id,
                acquired,
            );
