                pending.residual != null) and
                context != null)
                return error.InvalidControllerBinding;
            if (pending.work) |id| {
                var child = try self.workspaceWork(a, value.id, id);
                defer child.deinit();
                if (child.value.trial) |trial_id| {
                    var trial = try self.record(
                        workspace.Trial,
                        a,
                        "workspace_trial",
                        trial_id,
                        value.id,
                    );
                    defer trial.deinit();
                    binding.trial = .{ .work = id, .view = trial.value.view };
                }
                return binding;
            }
            if (pending.residual != null) return binding;
            var route = try self.record(
                workspace.ExecutionRoute,
                a,
                "execution_route",
                pending.id,
                value.id,
            );
            defer route.deinit();
            if (route.value.interaction) |id| {
                binding.controller = try self.controllerProjectionAt(
                    a,
                    value,
                    pending,
                    context,
                    id,
                    route.value.controller,
                );
            } else if (context != null) return error.InvalidControllerBinding;
            return binding;
        }
        fn controllerProjectionAt(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            context: ?state.ControllerContext,
            id: state.Digest,
            controller_id: ?state.Digest,
        ) !@FieldType(registry.ProjectionBinding, "controller") {
            var interaction = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                id,
                value.id,
            );
            defer interaction.deinit();
            if (!std.meta.eql(
                controller_id,
                interaction.value.controller,
            ) or !std.meta.eql(
                interaction.value.model,
                pending.id,
            )) return error.InvalidControllerBinding;
            const controller = try self.controllerBinding(
                a,
                value,
                interaction.value.controller,
            );
            const captured = context orelse return error.InvalidControllerBinding;
            if (captured.next_message > value.next_message or !std.meta.eql(
                @as(?state.Digest, controller.id),
                try self.controllerAt(a, value, captured.event_cut),
            ) or captured.epoch != try self.controllerEpochAt(
                a,
                value,
                captured.event_cut,
            )) return error.InvalidControllerBinding;
            const expected = try self.controllerOverlay(
                a,
                value,
                controller.id,
                id,
                captured.event_cut,
                captured.next_message,
                captured.epoch,
            );
            defer a.free(expected);
            if (!std.meta.eql(captured.overlay, state.Reference{
                .digest = storage.digest(expected),
                .bytes = expected.len,
            })) return error.InvalidControllerBinding;
            return .{
                .binding = controller.id,
                .epoch = captured.epoch,
                .program = controller.program_identity,
                .overlay = captured.overlay,
            };
        }
        fn prepareProjection(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            adapter: registry.CaptureAdapter,
            payload: []const u8,
        ) ![]u8 {
            return self.store().project(
                []u8,
                a,
                self.handlers,
                try self.occurrenceProjectionBinding(a, value, pending),
                struct {
                    adapter: registry.CaptureAdapter,
                    payload: []const u8,
                    pub fn run(this: @This(), context: registry.ProjectionContext) ![]u8 {
                        return this.adapter.prepare(context, this.payload);
                    }
                }{ .adapter = adapter, .payload = payload },
            );
        }
        fn interpretProjection(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            pending: occurrence.Occurrence,
            adapter: registry.CaptureAdapter,
            payload: []const u8,
            prepared: []const u8,
            response: []const u8,
        ) !registry.Projection {
            return self.store().project(
                registry.Projection,
                a,
                self.handlers,
                try self.occurrenceProjectionBinding(a, value, pending),
                struct {
                    adapter: registry.CaptureAdapter,
                    payload: []const u8,
                    prepared: []const u8,
                    response: []const u8,
                    pub fn run(
                        this: @This(),
                        context: registry.ProjectionContext,
                    ) !registry.Projection {
                        return this.adapter.interpret(
                            context,
                            this.payload,
                            this.prepared,
                            this.response,
                        );
                    }
                }{
                    .adapter = adapter,
                    .payload = payload,
                    .prepared = prepared,
                    .response = response,
                },
            );
        }
        fn capture(self: *Self, a: std.mem.Allocator, work: Work, raw: []const u8) !void {
            defer self.releaseWork();
            errdefer self.store().fence();
            // Publication failure fences this owner. The durable dispatched
            // occurrence then recovers as unknown, never as permission to retry.
            if (work.prepared == null) return error.InvalidPreparedRequest;
            var decoded = try self.task(a, work.task);
            defer decoded.deinit();
            var value = decoded.value;
            var saved = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                work.occurrence,
                work.task,
            );
            defer saved.deinit();
            const next = try occurrence.captured(
                saved.value,
                .{
                    .id = work.occurrence,
                    .task = work.task,
                    .work = work.subject_work,
                    .residual = work.subject_residual,
                    .request = saved.value.request,
                },
                work.attempt,
            );
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            const previous = value.revision;
            value.revision = try std.math.add(u64, previous, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.store().createRecord(state.Capture, "capture", work.attempt, work.task, .{
                .task = work.task,
                .occurrence = work.occurrence,
                .attempt = work.attempt,
                .request = try self.store().putObject(work.prepared.?),
                .response = try self.store().putObject(raw),
                .disposition = .complete,
            });
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                work.occurrence,
                work.task,
                next,
            );
            try self.effectSchedule(a, &value, saved.value, .queued, null);
            try self.persistOccurrence(a, value, previous, "effect.capture", saved.value, true);
        }
        fn interpretCapture(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
        ) !Step {
            try self.requireCustody(a, initial.id, pending.work);
            const attempt_id = pending.state.captured.id;
            var attempt = try self.record(state.Attempt, a, "attempt", attempt_id, initial.id);
            defer attempt.deinit();
            var raw = try self.record(state.Capture, a, "capture", attempt_id, initial.id);
            defer raw.deinit();
            try validateCapturedAttempt(initial, pending, attempt.value, raw.value);
            const encoded = try self.store().object(a, attempt.value.request, null);
            defer a.free(encoded);
            var request = try data.invocation.decode(data.invocation.Request, a, encoded);
            defer request.deinit();
            if (!same(&request.value.request_identity, &pending.request)) return error.CorruptState;
            // Resolve the original schemas without acquiring another I/O grant.
            const entry = try self.handlers.resolve(
                request.value,
                (try self.occurrenceSubject(a, initial, pending)).image,
            );
            if (attempt.value.operation == .workspace_build) return self.interpretWorkspaceBuild(
                a,
                initial,
                pending,
                attempt.value,
                raw.value,
            );
            const adapter = entry.declaration.capture orelse return error.IncompatibleProfile;
            const rendered = try self.store().object(a, raw.value.request, null);
            defer a.free(rendered);
            const response = try self.store().object(a, raw.value.response.?, null);
            defer a.free(response);
            var projection_arena = std.heap.ArenaAllocator.init(a);
            defer projection_arena.deinit();
            const result = self.interpretProjection(
                projection_arena.allocator(),
                initial,
                pending,
                adapter,
                try entry.payload(projection_arena.allocator(), request.value.binding.payload),
                rendered,
                response,
            ) catch
                return self.blockedOccurrence(a, initial, pending, .unavailable_environment);
            var schema = try data.schema.decode(a, entry.resume_schema);
            defer schema.deinit();
            data.schema.validateValue(
                a,
                schema.descriptor,
                result.reply,
            ) catch return self.blockedOccurrence(
                a,
                initial,
                pending,
                .unavailable_environment,
            );
            return self.publishInterpretedCapture(
                a,
                initial,
                pending,
                attempt_id,
                raw.value,
                entry,
                adapter,
                result,
            );
        }
        fn validateCapturedAttempt(
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt: state.Attempt,
            raw: state.Capture,
        ) !void {
            if (raw.disposition != .complete or
                raw.response == null or
                raw.projection != null or
                attempt.prepared == null or
                !same(&attempt.occurrence, &pending.id) or
                !same(&raw.occurrence, &pending.id) or
                !same(&attempt.profile.digest, &initial.profile.digest) or
                !std.meta.eql(attempt.prepared.?, raw.request)) return error.CorruptState;
        }
        fn settleCaptureReconciliation(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt_id: state.Digest,
            raw: state.Capture,
            reply: state.Reference,
            id: state.Digest,
        ) !void {
            var prior = try self.record(
                state.Reconciliation,
                a,
                "reconciliation",
                id,
                initial.id,
            );
            defer prior.deinit();
            var recovery = prior.value;
            if (recovery.outcome != .capture_admitted or !same(
                &recovery.attempt,
                &attempt_id,
            ) or !same(&recovery.occurrence, &pending.id) or !std.meta.eql(
                recovery.outcome.capture_admitted,
                raw.response.?,
            )) return error.CorruptState;
            recovery.previous = try self.snapshotRecord(
                state.Reconciliation,
                a,
                "reconciliation",
                id,
                initial.id,
            );
            recovery.outcome = .{ .reply_settled = reply };
            try self.store().putRecord(
                state.Reconciliation,
                "reconciliation",
                id,
                initial.id,
                recovery,
            );
        }
        fn retainCaptureProjection(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            attempt_id: state.Digest,
            raw: state.Capture,
            adapter: registry.CaptureAdapter,
            result: registry.Projection,
            bound: []const u8,
        ) !state.Reference {
            const reply = try self.store().putObject(bound);
            const objects = try a.alloc(state.Reference, result.objects.len);
            defer a.free(objects);
            for (result.objects, objects) |object, *reference|
                reference.* =
                    try self.store().putObject(object);
            try self.store().retainProjection(adapter.dependencies, result.objects);
            var projected = raw;
            projected.projection = .{
                .reply = reply,
                .objects = .{ .items = objects },
                .output_tokens = result.output_tokens,
            };
            try self.store().putRecord(state.Capture, "capture", attempt_id, initial.id, projected);
            return reply;
        }
        fn publishInterpretedCapture(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt_id: state.Digest,
            raw: state.Capture,
            entry: registry.Entry,
            adapter: registry.CaptureAdapter,
            result: registry.Projection,
        ) !Step {
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = result.reply,
            });
            defer a.free(bound);
            const next = try capturedOccurrence(initial, pending, attempt_id, bound);
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            if (entry.declaration.inference) if (result.output_tokens) |tokens| {
                value.inference_output_tokens = std.math.add(
                    u64,
                    value.inference_output_tokens,
                    tokens,
                ) catch return self.blockedOccurrence(a, initial, pending, .capacity);
            };
            try self.store().begin();
            defer self.store().rollback();
            const reply = try self.retainCaptureProjection(
                a,
                initial,
                attempt_id,
                raw,
                adapter,
                result,
                bound,
            );
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                initial.id,
                next,
            );
            if (raw.reconciliation) |id| try self.settleCaptureReconciliation(
                a,
                initial,
                pending,
                attempt_id,
                raw,
                reply,
                id,
            );
            try self.effectSchedule(a, &value, pending, .queued, null);
            try self.persistOccurrence(
                a,
                value,
                initial.revision,
                "effect.interpret",
                pending,
                true,
            );
            return .progressed;
        }
        fn capturedOccurrence(
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt_id: state.Digest,
            bound: []const u8,
        ) !occurrence.Occurrence {
            return try occurrence.acquired(
                pending,
                .{
                    .id = pending.id,
                    .task = initial.id,
                    .work = pending.work,
                    .residual = pending.residual,
                    .request = pending.request,
                },
                attempt_id,
                storage.digest(bound),
            );
        }
        fn currentWork(self: *Self, work: Work) !void {
            const current = self.work orelse return error.StaleOccurrence;
            if (!same(&self.owner_epoch, &work.owner_epoch) or
                !same(&current.owner_epoch, &work.owner_epoch) or
                !same(&current.task, &work.task) or !std.meta.eql(
                current.subject_work,
                work.subject_work,
            ) or !std.meta.eql(
                current.subject_residual,
                work.subject_residual,
            ) or current.operation != work.operation or !same(
                &current.occurrence,
                &work.occurrence,
            ) or !same(&current.attempt, &work.attempt)) return error.StaleOccurrence;
            if ((current.recovery != null) != (work.recovery != null)) return error.StaleOccurrence;
            if (current.recovery) |item| if (!same(
                &item.id,
                &work.recovery.?.id,
            )) return error.StaleOccurrence;
        }
        fn releaseWork(self: *Self) void {
            self.allocator.free(self.work.?.request);
            if (self.work.?.prepared) |body| self.allocator.free(body);
            self.allocator.free(self.work.?.profile);
            if (self.work.?.recovery) |item| self.allocator.free(item.body);
            self.work = null;
        }
        pub fn shouldCancelWork(self: *Self, work: Work) !bool {
            try self.currentWork(work);
            return (work.recovery != null or !work.cleanup) and self.work.?.cancel_requested;
        }
        pub fn completeWork(
            self: *Self,
            a: std.mem.Allocator,
            work: Work,
            result: WorkResult,
        ) !void {
            // All front ends publish a joined worker through this same owner.
            try self.currentWork(work);
            try self.requireCustody(a, work.task, work.subject_work);
            switch (result) {
                .acquired => |bytes| return self.acquire(a, work, bytes),
                .not_sent => return self.notSent(a, work),
                .unknown => return self.unknown(a, work),
                .rederived => |finding| {
                    try self.currentWork(work);
                    if (work.recovery == null) return error.InvalidRecovery;
                    return self.completeRecoveryWork(a, work, .{ .rederived = finding });
                },
                .failure => |err| {
                    try self.currentWork(work);
                    self.releaseWork();
                    self.store().fence();
                    return err;
                },
            }
        }
        fn completeRecoveryWork(
            self: *Self,
            a: std.mem.Allocator,
            work: Work,
            completion: ?RecoveryCompletion,
        ) !void {
            try self.currentWork(work);
            defer self.releaseWork();
            errdefer self.store().fence();
            var value = try self.task(a, work.task);
            defer value.deinit();
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                work.occurrence,
                work.task,
            );
            defer pending.deinit();
            var item = try self.record(
                state.Reconciliation,
                a,
                "reconciliation",
                work.recovery.?.id,
                work.task,
            );
            defer item.deinit();
            if (item.value.owner_epoch == null or !same(
                &item.value.owner_epoch.?,
                &work.owner_epoch,
            ) or !same(&item.value.attempt, &work.attempt) or !same(
                &item.value.occurrence,
                &work.occurrence,
            )) return error.StaleOccurrence;
            try self.finishRecovery(
                a,
                value.value,
                pending.value,
                item.value,
                completion,
                .unavailable,
            );
        }
        pub fn acquire(self: *Self, a: std.mem.Allocator, work: Work, reply: []const u8) !void {
            // A worker has returned and will no longer access this work item.
            // Acquisition is published before any subsequent Kosmos consumption.
            try self.currentWork(work);
            try self.requireCustody(a, work.task, work.subject_work);
            if (work.recovery != null) return self.completeRecoveryWork(a, work, .{
                .evidence = reply,
            });
            if (work.operation == .workspace_build or
                work.entry.declaration.capture != null)
                return self.capture(a, work, reply);
            defer self.releaseWork();
            errdefer self.store().fence();
            var schema = try data.schema.decode(a, work.entry.resume_schema);
            defer schema.deinit();
            try data.schema.validateValue(a, schema.descriptor, reply);
            var decoded = try self.task(a, work.task);
            defer decoded.deinit();
            var value = decoded.value;
            var saved = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                work.occurrence,
                work.task,
            );
            defer saved.deinit();
            const binding: occurrence.Binding = .{
                .id = work.occurrence,
                .task = work.task,
                .work = work.subject_work,
                .residual = work.subject_residual,
                .request = saved.value.request,
            };
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = saved.value.request,
                .value = reply,
            });
            defer a.free(bound);
            const acquired = try occurrence.acquired(
                saved.value,
                binding,
                work.attempt,
                storage.digest(bound),
            );
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            const previous = value.revision;
            value.revision = try std.math.add(u64, previous, 1);
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(bound);
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                work.occurrence,
                work.task,
                acquired,
            );
            try self.effectSchedule(a, &value, saved.value, .queued, null);
            try self.persistOccurrence(a, value, previous, "effect.acquire", saved.value, true);
        }
        pub fn unknown(self: *Self, a: std.mem.Allocator, work: Work) !void {
            try self.currentWork(work);
            try self.requireCustody(a, work.task, work.subject_work);
            if (work.recovery != null) return self.completeRecoveryWork(a, work, null);
            defer self.releaseWork();
            errdefer self.store().fence();
            var decoded = try self.task(a, work.task);
            defer decoded.deinit();
            var value = decoded.value;
            var saved = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                work.occurrence,
                work.task,
            );
            defer saved.deinit();
            const binding: occurrence.Binding = .{
                .id = work.occurrence,
                .task = work.task,
                .work = work.subject_work,
                .residual = work.subject_residual,
                .request = saved.value.request,
            };
            const lost = try occurrence.unknown(saved.value, binding, work.attempt);
            const previous = value.revision;
            value.revision = try std.math.add(u64, previous, 1);
            if (work.subject_work == null and work.subject_residual == null) {
                value.schedule = .parked;
                value.blocker = .unavailable_environment;
            }
            try self.store().begin();
            defer self.store().rollback();
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                work.occurrence,
                work.task,
                lost,
            );
            if (work.subject_work == null and work.subject_residual == null) try self.event(
                &value,
                .delivery_unknown,
                "{}",
            );
            try self.effectSchedule(a, &value, saved.value, .parked, .unavailable_environment);
            try self.persist(a, value, previous, "effect.unknown", .preserve);
            self.subjectRemove(.{
                .task = work.task,
                .work = work.subject_work,
                .residual = work.subject_residual,
            });
            try self.retire(a);
        }
        pub fn notSent(self: *Self, a: std.mem.Allocator, work: Work) !void {
            try self.currentWork(work);
            try self.requireCustody(a, work.task, work.subject_work);
            if (work.recovery != null) return self.completeRecoveryWork(a, work, null);
            defer self.releaseWork();
            errdefer self.store().fence();
            var decoded = try self.task(a, work.task);
            defer decoded.deinit();
            var value = decoded.value;
            var saved = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                work.occurrence,
                work.task,
            );
            defer saved.deinit();
            const next = try occurrence.notSent(
                saved.value,
                .{
                    .id = work.occurrence,
                    .task = work.task,
                    .work = work.subject_work,
                    .residual = work.subject_residual,
                    .request = saved.value.request,
                },
                work.attempt,
            );
            const previous = value.revision;
            value.revision = try std.math.add(u64, previous, 1);
            const subject = try self.occurrenceSubject(a, value, saved.value);
            const cancelling = subject.cancelling and !subject.cleanup;
            if (cancelling) try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            if (work.subject_work == null and work.subject_residual == null) {
                value.blocker = if (cancelling) null else .unavailable_environment;
                value.schedule = if (cancelling) .queued else .parked;
            }
            try self.store().begin();
            defer self.store().rollback();
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                work.occurrence,
                work.task,
                next,
            );
            if (work.subject_work == null and work.subject_residual == null) try self.event(
                &value,
                .blocked,
                "{\"delivery\":\"definitely_not_sent\"}",
            );
            try self.effectSchedule(
                a,
                &value,
                saved.value,
                if (cancelling) .queued else .parked,
                if (cancelling) null else .unavailable_environment,
            );
            try self.persistOccurrence(
                a,
                value,
                previous,
                "effect.not-sent",
                saved.value,
                cancelling,
            );
        }
        fn archiveAccess(self: *Self) !void {
            try self.allowed();
            if (self.work != null) return error.UnsettledOccurrence;
        }
        fn requireArchiveRecord(
            records: []const state.ArchiveRecord,
            kind: state.RecordKind,
            id: state.Digest,
        ) !void {
            for (records) |row| if (row.kind == kind and same(&row.id, &id)) return;
            return error.InvalidArchive;
        }
        fn validateInboxReply(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            saved: occurrence.Occurrence,
            bytes: []const u8,
        ) !?state.Digest {
            // Both directions of the inbox/message relationship are checked. An
            // empty reply has no message; a nonempty reply names exactly the saved
            // payload and its acquired/consumed boundary.
            var decoded = try contracts.decodeOwned(contracts.InboxReply(Types.Message), a, bytes);
            defer decoded.deinit();
            if (decoded.value == .empty) return null;
            const input = decoded.value.message;
            var id: state.Digest = undefined;
            if (input.id.bytes.len != 64) return error.InvalidArchive;
            _ = std.fmt.hexToBytes(&id, input.id.bytes) catch return error.InvalidArchive;
            var message_value = try self.record(state.Message, a, "message", id, task_id);
            defer message_value.deinit();
            const item = message_value.value;
            const expected: state.MessageDisposition = switch (saved.state) {
                .settled_reply => .acquired,
                .admitted => |admitted| if (admitted ==
                    .reply) .consumed else return error.InvalidArchive,
                else => return error.InvalidArchive,
            };
            if (item.disposition != expected or item.occurrence == null or !same(
                &item.occurrence.?,
                &saved.id,
            )) return error.InvalidArchive;
            const encoded = try contracts.encodeOwned(Types.Message, a, input.value);
            defer a.free(encoded);
            if (item.value.bytes != encoded.len or !same(
                &item.value.digest,
                &storage.digest(encoded),
            )) return error.InvalidArchive;
            return id;
        }
        fn validateArchiveAdmissions(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            index: state.Archive,
        ) !void {
            // The operation index preserves original identity even when a repeated
            // answer also has aliases. Messages, receipts and inbox history are one
            // admitted relationship, not independently trustworthy rows.
            var admission: ArchiveAdmissions = .{
                .service = self,
                .a = a,
                .value = value,
                .index = index,
                .receipts = .init(a),
                .ordinals = .init(a),
            };
            defer admission.receipts.deinit();
            defer admission.ordinals.deinit();
            for (index.operations.items) |row| try admission.operation(row);
            if (!admission.submitted) return error.InvalidArchive;
            if (value.cancellation) |reason| if (admission.first_cancel) |admitted| {
                const expected = try cancelDigest(a, value.id, reason);
                if (!same(&admitted.request, &expected)) return error.InvalidArchive;
            };
            for (index.records.items) |row| try admission.message(row);
            if (value.next_message != admission.count + 1 or
                admission.receipts.count() != admission.count) return error.InvalidArchive;
        }
        const ArchiveAdmissions = archiveAdmissionsType();
        fn archiveAdmissionsType() type {
            return struct {
                service: *Self,
                a: std.mem.Allocator,
                value: state.Task,
                index: state.Archive,
                receipts: std.AutoHashMap(state.Digest, state.Digest),
                ordinals: std.AutoHashMap(u64, void),
                submitted: bool = false,
                first_cancel: ?struct { revision: u64, request: state.Digest } = null,
                count: u64 = 0,
                fn operation(admission: *@This(), row: state.ArchiveOperation) !void {
                    var arena = std.heap.ArenaAllocator.init(admission.service.allocator);
                    defer arena.deinit();
                    const temporary = arena.allocator();
                    const bytes = try admission.service.store().object(temporary, row.body, null);
                    var decoded = try contracts.decodeOwned(state.Receipt, temporary, bytes);
                    defer decoded.deinit();
                    const receipt_value = decoded.value;
                    if (receipt_value.method == .cancel and
                        (admission.first_cancel == null or
                            receipt_value.revision < admission.first_cancel.?.revision))
                    {
                        admission.first_cancel = .{
                            .revision = receipt_value.revision,
                            .request = receipt_value.request_digest,
                        };
                    }
                    try admission.receiptIdentity(temporary, row, bytes, receipt_value);
                    if (receipt_value.method == .submit) {
                        if (admission.submitted or
                            receipt_value.revision != 1) return error.InvalidArchive;
                        admission.submitted = true;
                        const input_bytes = try admission.service.store().object(
                            temporary,
                            admission.value.input,
                            null,
                        );
                        var input = try contracts.decodeOwned(Types.Input, temporary, input_bytes);
                        defer input.deinit();
                        const expected_digest = try submitDigest(
                            temporary,
                            admission.value.profile.digest,
                            input.value,
                        );
                        if (!same(
                            &expected_digest,
                            &receipt_value.request_digest,
                        )) return error.InvalidArchive;
                    }
                    if (receipt_value.method == .message) {
                        const id = receipt_value.message.?;
                        const found = try admission.receipts.getOrPut(id);
                        if (found.found_existing) return error.InvalidArchive;
                        found.value_ptr.* = receipt_value.request_digest;
                    }
                    if (receipt_value.method == .reconcile)
                        try admission.reconcile(temporary, receipt_value);
                }
                fn receiptIdentity(
                    admission: *@This(),
                    temporary: std.mem.Allocator,
                    row: state.ArchiveOperation,
                    bytes: []const u8,
                    receipt_value: state.Receipt,
                ) !void {
                    const primary = try admission.service.operationKey(
                        temporary,
                        receipt_value.client_operation_id.bytes,
                    );
                    const original = (try admission.service.store().savedReceipt(
                        temporary,
                        &primary,
                    )) orelse return error.InvalidArchive;
                    if (!same(bytes, original) or (!same(
                        row.key.bytes,
                        &primary,
                    ) and receipt_value.method != .respond)) return error.InvalidArchive;
                    const expected: state.Disposition = switch (receipt_value.method) {
                        .submit => .accepted,
                        .message => .queued,
                        .respond => .answer_acquired,
                        .cancel => .cancellation_requested,
                        .@"resume" => .resumed,
                        .import_checkpoint => .imported,
                        .reconcile => .reconciled,
                        .workspace => .accepted,
                        .adopt => .accepted,
                    };
                    if (receipt_value.disposition != expected or
                        (receipt_value.message != null) != (receipt_value.method == .message) or
                        (receipt_value.question != null) != (receipt_value.method == .respond))
                        return error.InvalidArchive;
                }
                fn reconcile(
                    admission: *@This(),
                    temporary: std.mem.Allocator,
                    receipt_value: state.Receipt,
                ) !void {
                    const id = receipt_value.reconciliation orelse return error.InvalidArchive;
                    try requireArchiveRecord(admission.index.records.items, .reconciliation, id);
                    var recovery = try admission.service.record(
                        state.Reconciliation,
                        temporary,
                        "reconciliation",
                        id,
                        admission.value.id,
                    );
                    defer recovery.deinit();
                    if (recovery.value.admission_revision == 0) return error.InvalidArchive;
                    const expected_digest = try reconcileDigest(
                        temporary,
                        admission.value.id,
                        recovery.value.admission_revision - 1,
                        recovery.value.occurrence,
                        recovery.value.attempt,
                        recovery.value.selection,
                    );
                    if (!same(
                        &expected_digest,
                        &receipt_value.request_digest,
                    )) return error.InvalidArchive;
                }
                fn message(admission: *@This(), row: state.ArchiveRecord) !void {
                    if (row.kind != .message) return;
                    var arena = std.heap.ArenaAllocator.init(admission.service.allocator);
                    defer arena.deinit();
                    const temporary = arena.allocator();
                    var decoded = try admission.service.record(
                        state.Message,
                        temporary,
                        "message",
                        row.id,
                        admission.value.id,
                    );
                    defer decoded.deinit();
                    const item = decoded.value;
                    if (!same(item.schema_id.bytes, Types.message_schema_id) or
                        item.ordinal == 0 or
                        item.ordinal >= admission.value.next_message)
                        return error.InvalidArchive;
                    const ordinal = try admission.ordinals.getOrPut(item.ordinal);
                    if (ordinal.found_existing) return error.InvalidArchive;
                    admission.count += 1;
                    const bytes = try admission.service.store().object(temporary, item.value, null);
                    var payload = contracts.decodeOwned(
                        Types.Message,
                        temporary,
                        bytes,
                    ) catch |err| {
                        return if (err == error.OutOfMemory) err else error.InvalidArchive;
                    };
                    defer payload.deinit();
                    const receipt_digest = admission.receipts.get(
                        item.id,
                    ) orelse return error.InvalidArchive;
                    if (!same(
                        &receipt_digest,
                        &try messageDigest(temporary, admission.value.id, payload.value),
                    )) return error.InvalidArchive;
                    try admission.disposition(temporary, item);
                }
                fn disposition(
                    admission: *@This(),
                    temporary: std.mem.Allocator,
                    item: state.Message,
                ) !void {
                    switch (item.disposition) {
                        .queued, .not_consumed => {
                            if (item.occurrence != null or
                                (item.disposition == .not_consumed and
                                    !admission.value.terminal()))
                                return error.InvalidArchive;
                        },
                        .acquired, .consumed => {
                            try admission.validateAcquired(temporary, item);
                        },
                    }
                }
                fn validateAcquired(
                    admission: *@This(),
                    temporary: std.mem.Allocator,
                    item: state.Message,
                ) !void {
                    const occurrence_id = item.occurrence orelse return error.InvalidArchive;
                    try requireArchiveRecord(
                        admission.index.records.items,
                        .occurrence,
                        occurrence_id,
                    );
                    var saved = try admission.service.record(
                        occurrence.Occurrence,
                        temporary,
                        "occurrence",
                        occurrence_id,
                        admission.value.id,
                    );
                    defer saved.deinit();
                    const acquired = switch (saved.value.state) {
                        .settled_reply => |reply| reply,
                        .admitted => |admitted| if (admitted ==
                            .reply) admitted.reply else return error.InvalidArchive,
                        else => return error.InvalidArchive,
                    };
                    const request_bytes = try admission.service.store().object(
                        temporary,
                        saved.value.request_object,
                        null,
                    );
                    var request = try data.invocation.decode(
                        data.invocation.Request,
                        temporary,
                        request_bytes,
                    );
                    defer request.deinit();
                    const entry = try admission.service.handlers.resolve(
                        request.value,
                        try admission.service.occurrenceImage(
                            temporary,
                            admission.value,
                            saved.value,
                        ),
                    );
                    if (entry.declaration.kind != .inbox) return error.InvalidArchive;
                    const bound = try admission.service.store().acquiredObject(
                        temporary,
                        acquired.reply,
                        null,
                    );
                    var reply = try data.invocation.decode(
                        data.invocation.Result,
                        temporary,
                        bound,
                    );
                    defer reply.deinit();
                    const input_id = (try admission.service.validateInboxReply(
                        temporary,
                        admission.value.id,
                        saved.value,
                        reply.value.value,
                    )) orelse return error.InvalidArchive;
                    if (!same(&input_id, &item.id)) return error.InvalidArchive;
                }
            };
        }
        fn validateWorkspacePortOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            pending: occurrence.Occurrence,
            reference: state.Reference,
            request: data.invocation.Request,
            records: []const state.ArchiveRecord,
        ) !void {
            // The retained request determines which acquisition evidence must
            // exist. Validating only supplied attempts/questions misses omissions.
            var validation: PortOccurrenceValidation = .{
                .service = self,
                .a = a,
                .task_id = task_id,
                .pending = pending,
                .reference = reference,
                .request = request,
                .records = records,
            };
            try validation.run();
        }
        const PortOccurrenceValidation = portOccurrenceValidationType();
        fn portOccurrenceValidationType() type {
            return struct {
                service: *Self,
                a: std.mem.Allocator,
                task_id: state.TaskId,
                pending: occurrence.Occurrence,
                reference: state.Reference,
                request: data.invocation.Request,
                records: []const state.ArchiveRecord,
                fn run(validation: *@This()) !void {
                    const bytes = try validation.service.store().object(
                        validation.a,
                        validation.reference,
                        null,
                    );
                    var decoded = try contracts.decodeOwned(workspace.Port, validation.a, bytes);
                    defer decoded.deinit();
                    const port = decoded.value;
                    try validation.record(port);
                    var work = try validation.service.workspaceWork(
                        validation.a,
                        validation.task_id,
                        port.work,
                    );
                    defer work.deinit();
                    try validation.validateProgram(port, work.value);
                    var payload_schema = try data.schema.decode(
                        validation.a,
                        validation.request.binding.payload_schema,
                    );
                    defer payload_schema.deinit();
                    try data.schema.validateValue(
                        validation.a,
                        payload_schema.descriptor,
                        validation.request.binding.payload,
                    );
                    const acquired: ?occurrence.Acquired = switch (validation.pending.state) {
                        .ready => null,
                        .settled_reply => |reply| reply,
                        .admitted => |admitted| if (admitted ==
                            .reply) admitted.reply else if (admitted.cancelled ==
                            null) null else return error.InvalidArchive,
                        else => return error.InvalidArchive,
                    };
                    if (acquired) |reply| try validation.validateReply(port, work.value, reply);
                }
                fn record(validation: *@This(), port: workspace.Port) !void {
                    try requireArchiveRecord(validation.records, .workspace_port, port.id);
                    const record_bytes = (try validation.service.store().recordBytes(
                        validation.a,
                        "workspace_port",
                        port.id,
                        validation.task_id,
                    )) orelse return error.InvalidArchive;
                    const canonical: state.Reference = .{
                        .digest = storage.digest(record_bytes),
                        .bytes = record_bytes.len,
                    };
                    if (!std.meta.eql(
                        canonical,
                        validation.reference,
                    ) or !std.meta.eql(
                        port.task,
                        validation.task_id,
                    ) or
                        !std.meta.eql(@as(?state.Digest, port.work), validation.pending.work) or
                        !std.meta.eql(port.occurrence, validation.pending.id) or
                        !std.meta.eql(
                            port.request_identity,
                            validation.pending.request,
                        ) or !std.meta.eql(
                        port.request,
                        validation.pending.request_object,
                    ) or port.generation == 0) return error.InvalidArchive;
                }
                fn validateProgram(
                    validation: *@This(),
                    port: workspace.Port,
                    work: workspace.Work,
                ) !void {
                    var program = try validation.service.workspaceProgram(
                        validation.a,
                        validation.task_id,
                        work.program,
                    );
                    defer program.deinit();
                    if (!std.meta.eql(
                        port.program,
                        program.value.artifact,
                    ) or port.generation > work.port_generation) return error.InvalidArchive;
                    var matched = false;
                    for (program.value.description.ports.items) |candidate| {
                        if (!same(
                            candidate.identity.bytes,
                            port.interface.identity.bytes,
                        )) continue;
                        if (candidate.class != port.interface.class) return error.InvalidArchive;
                        inline for (.{
                            "argument",
                            "observation",
                            "payload",
                            "command",
                        }) |field| if (!std.meta.eql(
                            @field(candidate, field),
                            @field(port.interface, field),
                        )) return error.InvalidArchive;
                        matched = true;
                    }
                    if (!matched or !same(
                        port.interface.identity.bytes,
                        validation.request.binding.semantic_identity,
                    ) or
                        !std.meta.eql(port.interface.payload, state.Reference{
                            .digest = storage.digest(validation.request.binding.payload_schema),
                            .bytes = validation.request.binding.payload_schema.len,
                        }) or
                        !std.meta.eql(port.interface.command, state.Reference{
                            .digest = storage.digest(validation.request.binding.resume_schema),
                            .bytes = validation.request.binding.resume_schema.len,
                        }) or
                        !std.meta.eql(port.payload, state.Reference{
                            .digest = storage.digest(validation.request.binding.payload),
                            .bytes = validation.request.binding.payload.len,
                        })) return error.InvalidArchive;
                }
                fn validateReply(
                    validation: *@This(),
                    port: workspace.Port,
                    work: workspace.Work,
                    reply: occurrence.Acquired,
                ) !void {
                    if (reply.answer != null) return error.InvalidArchive;
                    try requireArchiveRecord(
                        validation.records,
                        .workspace_port_reply,
                        reply.attempt,
                    );
                    var answer = try validation.service.record(
                        workspace.PortReply,
                        validation.a,
                        "workspace_port_reply",
                        reply.attempt,
                        validation.task_id,
                    );
                    defer answer.deinit();
                    if (!std.meta.eql(answer.value.task, validation.task_id) or
                        !std.meta.eql(answer.value.id, reply.attempt) or
                        !std.meta.eql(answer.value.port, validation.reference) or !std.meta.eql(
                        answer.value.reply.digest,
                        reply.reply,
                    )) return error.InvalidArchive;
                    var result = try data.invocation.decode(
                        data.invocation.Result,
                        validation.a,
                        try validation.service.store().object(
                            validation.a,
                            answer.value.reply,
                            null,
                        ),
                    );
                    defer result.deinit();
                    if (!std.meta.eql(
                        result.value.request_identity,
                        validation.pending.request,
                    )) return error.InvalidArchive;
                    try validation.validateCommand(port, work, answer.value, result.value);
                }
                fn validateCommand(
                    validation: *@This(),
                    port: workspace.Port,
                    work: workspace.Work,
                    answer: workspace.PortReply,
                    result: data.invocation.Result,
                ) !void {
                    const protocol: @import("workspace_driver.zig").Protocol = .{
                        .class = port.interface.class,
                        .command_schema = validation.request.binding.resume_schema,
                        .payload_schema = validation.request.binding.payload_schema,
                        .payload = validation.request.binding.payload,
                    };
                    const command = try protocol.decode(validation.a, result.value);
                    if (answer.command == .finish) {
                        if (command != .finish or
                            answer.input != null)
                            return error.InvalidArchive;
                    } else {
                        if (command != .resume_value) return error.InvalidArchive;
                        const input = answer.input orelse return error.InvalidArchive;
                        const origin = try validation.service.workspaceValueReference(
                            validation.a,
                            validation.task_id,
                            try wp.reference(validation.a, .value, input.digest),
                        );
                        if (!std.meta.eql(origin.artifact, input) or !std.meta.eql(
                            origin.schema,
                            port.interface.argument,
                        )) return error.InvalidArchive;
                        const input_bytes = command.resume_value;
                        if (!std.meta.eql(origin.value, state.Reference{
                            .digest = storage.digest(input_bytes),
                            .bytes = input_bytes.len,
                        })) return error.InvalidArchive;
                        var found = false;
                        for (work.inputs.items) |source| found = found or std.meta.eql(
                            source,
                            input,
                        );
                        if (!found) return error.InvalidArchive;
                    }
                }
            };
        }
        fn validateOccurrenceProvenance(
            self: *Self,
            a: std.mem.Allocator,
            value: state.Task,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            var proof: OccurrenceProof = .{
                .service = self,
                .a = a,
                .value = value,
                .records = records,
                .checked = checked,
                .residual_occurrences = .init(a),
                .images = .init(a),
            };
            defer proof.residual_occurrences.deinit();
            defer proof.images.deinit();
            try proof.residuals();
            for (records) |row| try proof.occurrenceRow(row);
            try proof.questions();
        }
        const OccurrenceProof = occurrenceProofType();
        fn occurrenceProofType() type {
            return struct {
                service: *Self,
                a: std.mem.Allocator,
                value: state.Task,
                records: []const state.ArchiveRecord,
                checked: *SnapshotValidation,
                residual_occurrences: std.AutoHashMap(state.Digest, state.Digest),
                images: std.AutoHashMap(state.Reference, state.Digest),
                fn residuals(proof: *@This()) !void {
                    for (proof.records) |row| if (row.kind == .controller_residual) {
                        var residual = try proof.service.record(
                            state.ControllerResidual,
                            proof.a,
                            "controller_residual",
                            row.id,
                            proof.value.id,
                        );
                        defer residual.deinit();
                        if (residual.value.current_occurrence) |id| {
                            if (std.meta.eql(
                                proof.value.current_occurrence,
                                id,
                            ) or proof.residual_occurrences.contains(
                                id,
                            )) return error.InvalidArchive;
                            try proof.residual_occurrences.put(id, row.id);
                        }
