                    if (saved.work) |work_id| {
                        try requireArchiveRecord(proof.records, .workspace_work, work_id);
                        var work = try proof.service.workspaceWork(
                            temporary,
                            proof.value.id,
                            work_id,
                        );
                        defer work.deinit();
                        var program = try proof.service.workspaceProgram(
                            temporary,
                            proof.value.id,
                            work.value.program,
                        );
                        defer program.deinit();
                        expected_image = program.value.description.image;
                        current_id = work.value.current_occurrence;
