        fn workspaceInterpretationEvidence(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            pending: ?occurrence.Occurrence,
            observed_at: u64,
        ) !json.Value {
            var program = try self.workspaceProgram(a, work.task, work.program);
            defer program.deinit();
            const input = work.input_value orelse return error.CorruptState;
            const bytes = try self.store().object(a, input, null);
            defer a.free(bytes);
            var artifact = try contracts.decodeOwned(workspace.ValueArtifact, a, bytes);
            defer artifact.deinit();
            var result = json.object();
            try json.put(a, &result, "evidence_class", json.string("experimental"));
            try json.put(a, &result, "analysis_checker", .null);
            try json.put(a, &result, "program", try values.toJson(
                wc.Ref,
                a,
                try wp.reference(a, .program, work.program),
            ));
            try json.put(a, &result, "executable", try values.toJson(
                state.Reference,
                a,
                program.value.description.image,
            ));
            try json.put(a, &result, "work", try values.toJson(
                wc.Ref,
                a,
                try wp.reference(a, .work, work.id),
            ));
            try json.put(a, &result, "input", try values.toJson(
                wc.Ref,
                a,
                try wp.reference(a, .value, input.digest),
            ));
            try json.put(a, &result, "input_provenance", try values.toJson(
                wc.Ref,
                a,
                try wp.reference(a, .provenance, artifact.value.provenance.digest),
            ));
            try json.put(a, &result, "result", if (work.result_value) |ref|
                try values.toJson(wc.Ref, a, try wp.reference(a, .value, ref.digest))
            else
                .null);
            try json.put(a, &result, "observed_control_trace", try workspaceInterpretationTrace(
                a,
                work,
                pending,
                observed_at,
            ));
            try appendInterpretationClaims(a, &result, work);
            return result;
        }
        fn appendInterpretationClaims(
            a: std.mem.Allocator,
            result: *json.Value,
            work: workspace.Work,
        ) !void {
            try json.put(a, result, "scope", json.string("actual_program_execution"));
            try json.put(
                a,
                result,
                "interpretation_claims",
                json.string("not_independently_checked"),
            );
            try json.put(a, result, "coverage", json.string("committed_publications_only"));
            try json.put(a, result, "reference_semantics", json.string(
                "input_provenance_does_not_certify_use",
            ));
            try json.put(
                a,
                result,
                "stopping_disposition",
                json.string(@tagName(work.outcome_kind)),
            );
        }
        fn workspaceInterpretationTrace(
            a: std.mem.Allocator,
            work: workspace.Work,
            pending: ?occurrence.Occurrence,
            observed_at: u64,
        ) !json.Value {
            return values.toJson(
                struct {
                    task: state.TaskId,
                    through_event: u64,
                    execution_revision: u64,
                    control_revision: u64,
                    checkpoint: state.Reference,
                    control: workspace.ControlObservation,
                },
                a,
                .{
                    .task = work.task,
                    .through_event = observed_at,
                    .execution_revision = work.execution_revision,
                    .control_revision = work.control_revision,
                    .checkpoint = work.checkpoint,
                    .control = workspace.ControlObservation.from(.{
                        .work = work,
                        .occurrence = pending,
                    }),
                },
            );
        }
        fn workspacePortObservation(
            self: *Self,
            a: std.mem.Allocator,
            port: workspace.Port,
        ) !json.Value {
            var result = json.object();
            try json.put(
                a,
                &result,
                "reference",
                try values.toJson(wc.Ref, a, try wp.reference(a, .port, port.id)),
            );
            try json.put(a, &result, "generation", try json.number(a, port.generation));
            try json.put(a, &result, "class", json.string(@tagName(port.interface.class)));
            try json.put(
                a,
                &result,
                "identity",
                json.string(try a.dupe(u8, port.interface.identity.bytes)),
            );
            inline for (.{ "argument", "observation", "payload", "command" }) |field| {
                const ref = @field(port.interface, field);
                const bytes = try self.store().object(a, ref, null);
                defer a.free(bytes);
                try json.put(
                    a,
                    &result,
                    field ++ "_schema",
                    try values.toJson(wc.Ref, a, try wp.reference(a, .schema, ref.digest)),
                );
                try json.put(a, &result, field ++ "_descriptor", try wp.schema(a, bytes));
            }
            const payload = try self.store().object(a, port.payload, null);
            defer a.free(payload);
            try json.put(
                a,
                &result,
                "preview",
                try self.workspacePayloadPreview(a, port.interface.payload, payload),
            );
            return result;
        }
        fn workspacePayloadPreview(
            self: *Self,
            a: std.mem.Allocator,
            schema_ref: state.Reference,
            payload: []const u8,
        ) !json.Value {
            const schema = try self.store().object(a, schema_ref, null);
            defer a.free(schema);
            return @import("dynamic_values.zig").preview(a, schema, payload);
        }
        fn workspacePayloadPage(
            self: *Self,
            a: std.mem.Allocator,
            schema_ref: state.Reference,
            payload_ref: state.Reference,
            page: wc.Page,
        ) !json.Value {
            const payload = try self.store().object(a, payload_ref, null);
            defer a.free(payload);
            return self.workspacePayloadBytesPage(a, schema_ref, payload, page);
        }
        fn workspacePayloadBytesPage(
            self: *Self,
            a: std.mem.Allocator,
            schema_ref: state.Reference,
            payload: []const u8,
            page: wc.Page,
        ) !json.Value {
            const schema = try self.store().object(a, schema_ref, null);
            defer a.free(schema);
            return @import("dynamic_values.zig").page(a, schema, payload, page);
        }
        pub fn workspaceInteract(
            self: *Self,
            allocator: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            interaction: @FieldType(wc.Work, "interact"),
        ) !Admission {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            const request = try operation(workspace.InteractionRequest, a, .{
                .task = task_id,
                .interaction = interaction,
            });
            if (try self.replay(allocator, operation_id, request)) |prior| return prior;
            const work_id = try wp.identity(interaction.expected.work, .work);
            try self.requireCustody(allocator, task_id, work_id);
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            var saved = try self.workspaceWork(a, task_id, work_id);
            defer saved.deinit();
            const value = saved.value;
            if (value.execution_revision != interaction.expected.execution_revision or
                value.control_revision != interaction.expected.control_revision)
                return error.StaleRevision;
            if (!workspaceInteractionAllowed(self.workspaceParentStopped(parent.value), value))
                return error.InvalidState;
            var port = try self.workspaceInteractionPort(a, task_id, value, interaction);
            defer port.deinit();
            const binding = workspaceInteractionBinding(task_id, value.id, port.value);
            var pending = try self.workspaceInteractionPending(a, task_id, binding);
            defer pending.deinit();
            var encoded = try self.encodeWorkspaceInteraction(a, task_id, port.value, interaction);
            defer encoded.deinit(a);
            return self.commitWorkspaceInteraction(a, .{
                .operation_id = operation_id,
                .request = request,
                .parent = parent.value,
                .work = value,
                .port_reference = value.current_port.?,
                .port = port.value,
                .pending = pending.value,
                .interaction = interaction,
                .encoded = encoded,
            });
        }
        fn workspaceInteractionPort(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            value: workspace.Work,
            interaction: @FieldType(wc.Work, "interact"),
        ) !contracts.Decoded(workspace.Port) {
            const reference = value.current_port orelse return error.NoExposedPort;
            const bytes = try self.store().object(a, reference, null);
            defer a.free(bytes);
            var port = try contracts.decodeOwned(workspace.Port, a, bytes);
            errdefer port.deinit();
            if (!std.meta.eql(port.value.id, try wp.identity(interaction.port, .port)) or
                port.value.generation != interaction.generation or
                !std.meta.eql(port.value.task, task_id) or
                !std.meta.eql(port.value.work, value.id) or
                !std.meta.eql(value.current_occurrence, @as(?state.Digest, port.value.occurrence)))
                return error.StalePort;
            return port;
        }
        fn workspaceInteractionBinding(
            task_id: state.TaskId,
            work_id: state.Digest,
            port: workspace.Port,
        ) occurrence.Binding {
            return .{
                .id = port.occurrence,
                .task = task_id,
                .work = work_id,
                .request = port.request_identity,
            };
        }
        fn workspaceInteractionPending(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            binding: occurrence.Binding,
        ) !contracts.Decoded(occurrence.Occurrence) {
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                binding.id,
                task_id,
            );
            errdefer pending.deinit();
            try occurrence.current(pending.value, binding);
            if (pending.value.state != .ready) return error.PortAlreadyAnswered;
            return pending;
        }
        fn encodeWorkspaceInteraction(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            port: workspace.Port,
            interaction: @FieldType(wc.Work, "interact"),
        ) !EncodedInteraction {
            const argument_schema = try self.store().object(a, port.interface.argument, null);
            defer a.free(argument_schema);
            var input: ?InteractionInput = null;
            errdefer if (input) |owned| a.free(owned.bytes);
            const command_schema = try self.store().object(a, port.interface.command, null);
            defer a.free(command_schema);
            const payload_schema = if (interaction.command == .finish)
                try self.store().object(a, port.interface.payload, null)
            else
                &.{};
            defer a.free(payload_schema);
            const payload = if (interaction.command == .finish)
                try self.store().object(a, port.payload, null)
            else
                &.{};
            defer a.free(payload);
            const protocol: @import("workspace_driver.zig").Protocol = .{
                .class = port.interface.class,
                .command_schema = command_schema,
                .payload_schema = payload_schema,
                .payload = payload,
            };
            const command: @import("workspace_driver.zig").Command = switch (interaction.command) {
                .finish => .finish,
                .resume_value => |supplied| blk: {
                    input = try self.workspaceInteractionInput(
                        a,
                        task_id,
                        port.interface.argument,
                        argument_schema,
                        supplied,
                    );
                    break :blk .{ .resume_value = input.?.bytes };
                },
            };
            return .{ .input = input, .bytes = try protocol.encode(a, command) };
        }
        fn workspaceInteractionInput(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            argument: state.Reference,
            schema: []const u8,
            supplied: wc.ValueInput,
        ) !InteractionInput {
            switch (supplied) {
                .inline_json => |inline_value| {
                    if (!std.meta.eql(
                        try wp.identity(inline_value.schema, .schema),
                        argument.digest,
                    ))
                        return error.SchemaMismatch;
                    const text = inline_value.json_text.bytes;
                    var parsed = try json.parse(a, text, .{
                        .bytes = text.len,
                        .depth = text.len,
                        .tokens = text.len,
                        .members = text.len,
                    });
                    defer parsed.deinit();
                    return .{
                        .bytes = try @import("dynamic_values.zig").encode(a, schema, parsed.value),
                    };
                },
                .reference => |ref| {
                    const selected = try self.workspaceValueReference(a, task_id, ref);
                    if (!std.meta.eql(selected.schema, argument)) return error.SchemaMismatch;
                    return .{
                        .origin = selected.artifact,
                        .bytes = try self.store().object(a, selected.value, null),
                    };
                },
            }
        }
        fn commitWorkspaceInteraction(
            self: *Self,
            a: std.mem.Allocator,
            publication: InteractionPublication,
        ) !Admission {
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = publication.pending.request,
                .value = publication.encoded.bytes,
            });
            defer a.free(bound);
            var attempt: state.Digest = undefined;
            try self.io.randomSecure(&attempt);
            const binding = workspaceInteractionBinding(
                publication.parent.id,
                publication.work.id,
                publication.port,
            );
            const dispatched = try occurrence.dispatch(
                publication.pending,
                binding,
                attempt,
                false,
                false,
            );
            const acquired = try occurrence.acquired(
                dispatched,
                binding,
                attempt,
                storage.digest(bound),
            );
            return self.publishWorkspaceInteraction(a, publication, attempt, acquired, bound);
        }
        fn publishWorkspaceInteraction(
            self: *Self,
            a: std.mem.Allocator,
            publication: InteractionPublication,
            attempt: state.Digest,
            acquired: occurrence.Occurrence,
            bound: []const u8,
        ) !Admission {
            var value = publication.work;
            const task_id = publication.parent.id;
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            try self.store().begin();
            defer self.store().rollback();
            const origin = try self.retainWorkspaceInteractionInput(
                a,
                task_id,
                &value,
                publication.port.interface.argument,
                publication.encoded.input,
            );
            try self.store().createRecord(
                workspace.PortReply,
                "workspace_port_reply",
                attempt,
                task_id,
                .{
                    .id = attempt,
                    .task = task_id,
                    .port = publication.port_reference,
                    .reply = try self.store().putObject(bound),
                    .input = origin,
                    .command = if (publication.interaction.command == .finish)
                        .finish
                    else
                        .resume_value,
                },
            );
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                publication.pending.id,
                task_id,
                acquired,
            );
            value.control_revision = try std.math.add(u64, value.control_revision, 1);
            value.event_watermark = try std.math.add(u64, publication.parent.event_high, 1);
            value.schedule = .queued;
            try self.writeWorkspaceWork(&value, .replace);
            return self.workspaceCommit(
                a,
                publication.parent,
                publication.operation_id,
                publication.request,
                value.id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", value.id, task_id),
                .{ .interact = publication.interaction },
            );
        }
        fn retainWorkspaceInteractionInput(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            value: *workspace.Work,
            argument: state.Reference,
            input: ?InteractionInput,
        ) !?state.Reference {
            const supplied = input orelse return null;
            const origin = supplied.origin orelse try self.workspacePublishValue(
                a,
                task_id,
                argument,
                try self.store().putObject(supplied.bytes),
                .{ .kind = .hypothesis, .sources = .{ .items = &.{} } },
            );
            const inputs = try a.alloc(state.Reference, value.inputs.items.len + 1);
            @memcpy(inputs[0..value.inputs.items.len], value.inputs.items);
            inputs[value.inputs.items.len] = origin;
            value.inputs = .{ .items = inputs };
            return origin;
        }
        fn workspaceSource(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
        ) ![]u8 {
            return self.workspaceBuildSource(a, task_id, ref, .source_records);
        }
        fn workspaceBuildSource(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
            kind: wc.SourceKind,
        ) ![]u8 {
            if (ref.kind == .value) {
                const source = try self.workspaceValueReference(a, task_id, ref);
                return self.workspaceSourceByKind(a, source, kind);
            }
            return switch (try self.resolveWorkspaceSource(a, task_id, ref)) {
                .text => |text| text,
                .value => |source| self.workspaceSourceByKind(a, source, kind),
            };
        }
        fn workspaceSourceByKind(
            self: *Self,
            a: std.mem.Allocator,
            source: WorkspaceValueReference,
            kind: wc.SourceKind,
        ) ![]u8 {
            const records = @import("source_records.zig");
            return switch (kind) {
                .source_records => self.workspaceSourceValue(records.Document, a, source),
                .source_derivation => self.workspaceSourceValue(
                    records.DerivationDocument,
                    a,
                    source,
                ),
                .component_recipe => error.SchemaMismatch,
            };
        }
        fn workspaceSourceValue(
            self: *Self,
            comptime Document: type,
            a: std.mem.Allocator,
            source: WorkspaceValueReference,
        ) ![]u8 {
            const records = @import("source_records.zig");
            const schema = try values.schemaBytes(Document, a);
            defer a.free(schema);
            if (!std.meta.eql(source.schema, state.Reference{
                .digest = storage.digest(schema),
                .bytes = schema.len,
            })) return error.SchemaMismatch;
            const bytes = try self.store().object(a, source.value, null);
            defer a.free(bytes);
            var document = try contracts.decodeOwned(Document, a, bytes);
            defer document.deinit();
            if (document.value.version != 1) return error.UnsupportedVersion;
            return records.encodeRecord(Document, a, document.value);
        }
        fn workspaceSourcePage(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
            requested: wc.Page,
        ) !json.Value {
            return switch (try self.resolveWorkspaceSource(a, task_id, ref)) {
                .text => |text| blk: {
                    defer a.free(text);
                    break :blk try wp.page(a, text, requested);
                },
                .value => |value| try self.workspacePayloadPage(
                    a,
                    value.schema,
                    value.value,
                    requested,
                ),
            };
        }
        fn resolveWorkspaceSource(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
        ) !WorkspaceSource {
            // Resolve and authorize before choosing complete text or a bounded
            // projection. Frozen typed inputs keep their compact representation.
            const id = try wp.identity(ref, .source);
            if (try self.resolveAcquiredSource(a, task_id, id)) |source| return source;
            if (try self.resolveProgramSource(a, task_id, id)) |source| return source;
            if (try self.resolveCandidateSource(a, task_id, id)) |source| return source;
            return error.ArtifactUnavailable;
        }
        fn resolveAcquiredSource(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !?WorkspaceSource {
            var acquired = try self.store().database.prepare(
                "SELECT id FROM records WHERE task=? AND kind='workspace_value' ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer acquired.deinit();
            while (try acquired.step() == .row) {
                const key = try acquired.bytes(0);
                if (key.len != 32) return error.CorruptState;
                var record_value = try self.record(
                    workspace.Value,
                    a,
                    "workspace_value",
                    key[0..32].*,
                    task_id,
                );
                defer record_value.deinit();
                if (!std.meta.eql(record_value.value.description.provenance.digest, id)) continue;
                const checked = try self.workspaceValueReference(
                    a,
                    task_id,
                    try wp.reference(a, .value, record_value.value.artifact.digest),
                );
                if (record_value.value.derivation.frozen_input != null or
                    record_value.value.derivation.semantic_source != null)
                {
                    return .{ .value = checked };
                }
                const origin = record_value.value.derivation.acquisition orelse continue;
                const bytes = try self.store().object(a, origin.snapshot, null);
                defer a.free(bytes);
                var source = try @import("repository.zig").Snapshot.openBorrowed(a, bytes);
                defer source.deinit();
                const file = source.get(origin.path.bytes) orelse return error.CorruptState;
                if (!std.unicode.utf8ValidateSlice(file.contents.bytes)) return .{
                    .text = try json.canonical(
                        a,
                        try values.toJson(contracts.Bytes(null), a, file.contents),
                    ),
                };
                return .{ .text = try a.dupe(u8, file.contents.bytes) };
            }
            return null;
        }
        fn resolveProgramSource(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !?WorkspaceSource {
            var query = try self.store().database.prepare(
                "SELECT id FROM records WHERE task=? AND kind='workspace_program' ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            while (try query.step() == .row) {
                const key = try query.bytes(0);
                if (key.len != 32) return error.CorruptState;
                var program = try self.record(
                    workspace.Program,
                    a,
                    "workspace_program",
                    key[0..32].*,
                    task_id,
                );
                defer program.deinit();
                if (std.meta.eql(program.value.description.source.digest, id)) return .{
                    .text = try self.store().object(a, program.value.description.source, null),
                };
            }
            return null;
        }
        fn resolveCandidateSource(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !?WorkspaceSource {
            var candidates = try self.store().database.prepare(
                "SELECT id FROM records WHERE task=? AND kind='workspace_candidate' ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer candidates.deinit();
            while (try candidates.step() == .row) {
                const key = try candidates.bytes(0);
                if (key.len != 32) return error.CorruptState;
                var saved = try self.record(
                    workspace.Candidate,
                    a,
                    "workspace_candidate",
                    key[0..32].*,
                    task_id,
                );
                defer saved.deinit();
                if (!std.meta.eql(saved.value.description.proposal.digest, id)) continue;
                var candidate = try self.workspaceCandidate(
                    a,
                    task_id,
                    saved.value.artifact.digest,
                );
                defer candidate.deinit();
                return .{ .text = try self.store().object(
                    a,
                    candidate.value.description.proposal,
                    null,
                ) };
            }
            return null;
        }
        fn workspaceOwnedDescriptor(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
        ) !state.Reference {
            if (ref.kind != .schema and ref.kind != .provenance) return error.InvalidReference;
            const id = try wp.identity(ref, ref.kind);
            var query = try self.store().database.prepare(
                "SELECT id,kind FROM records WHERE task=? AND kind IN ('workspace" ++
                    "_program','workspace_value') ORDER BY id",
                &.{.{ .blob = &task_id }},
            );
            defer query.deinit();
            while (try query.step() == .row) {
                const key = try query.bytes(0);
                if (key.len != 32) return error.CorruptState;
                if (same(try query.bytes(1), "workspace_value")) {
                    var value = try self.record(
                        workspace.Value,
                        a,
                        "workspace_value",
                        key[0..32].*,
                        task_id,
                    );
                    defer value.deinit();
                    const declared =
                        if (ref.kind ==
                        .schema)
                            value.value.description.schema
                        else
                            value.value.description.provenance;
                    if (!std.meta.eql(declared.digest, id)) continue;
                    const checked = try self.workspaceValueReference(
                        a,
                        task_id,
                        try wp.reference(a, .value, value.value.artifact.digest),
                    );
                    const candidate =
                        if (ref.kind ==
                        .schema) checked.schema else checked.provenance;
                    if (std.meta.eql(candidate.digest, id)) return candidate;
                } else if (ref.kind == .schema) {
                    var saved = try self.record(
                        workspace.Program,
                        a,
                        "workspace_program",
                        key[0..32].*,
                        task_id,
                    );
                    defer saved.deinit();
                    if (workspaceProgramDescriptor(saved.value.description, id) == null) continue;
                    var program = try self.workspaceProgram(
                        a,
                        task_id,
                        saved.value.artifact.digest,
                    );
                    defer program.deinit();
                    if (workspaceProgramDescriptor(
                        program.value.description,
                        id,
                    )) |candidate| return candidate;
                }
            }
            return error.ArtifactUnavailable;
        }
        fn workspaceProgramDescriptor(
            program: workspace.ProgramArtifact,
            id: state.Digest,
        ) ?state.Reference {
            inline for (.{ "input_schema", "result_schema", "failure_schema" }) |field| {
                const candidate = @field(program, field);
                if (std.meta.eql(candidate.digest, id)) return candidate;
            }
            for (program.controller_schemas.items) |candidate| if (std.meta.eql(
                candidate.digest,
                id,
            )) return candidate;
            for (program.ports.items) |port| inline for (.{
                "argument",
                "observation",
                "payload",
                "command",
            }) |field| {
                const candidate = @field(port, field);
                if (std.meta.eql(candidate.digest, id)) return candidate;
            };
            return null;
        }
        fn workspaceDerivationObservation(
            self: *Self,
            a: std.mem.Allocator,
            derivation: workspace.Derivation,
        ) !json.Value {
            _ = self;
            var result = json.object();
            try json.put(a, &result, "kind", json.string(@tagName(derivation.kind)));
            if (derivation.kind == .computation or derivation.kind == .trial or
                derivation.kind == .judgment or derivation.kind == .hypothesis)
            {
                try json.put(a, &result, "evidence_class", json.string("experimental"));
                try json.put(a, &result, "analysis_checker", .null);
            }
            var sources: json.Value = .{ .array = .init(a) };
            for (derivation.sources.items) |ref| try sources.array.append(
                try values.toJson(wc.Ref, a, try wp.reference(a, .value, ref.digest)),
            );
            try json.put(a, &result, "sources", sources);
            try json.put(
                a,
                &result,
                "coverage",
                json.string("No source-universe completeness is asserted by this derivation."),
            );
            if (derivation.program) |ref| try json.put(
                a,
                &result,
                "program",
                try values.toJson(wc.Ref, a, try wp.reference(a, .program, ref.digest)),
            );
            if (derivation.work) |id| try json.put(
                a,
                &result,
                "work",
                try values.toJson(wc.Ref, a, try wp.reference(a, .work, id)),
            );
            try appendDerivationAcquisition(a, &result, derivation);
            try appendDerivationInspection(a, &result, derivation);
            return result;
        }
        fn appendDerivationAcquisition(
            a: std.mem.Allocator,
            result: *json.Value,
            derivation: workspace.Derivation,
        ) !void {
            if (derivation.acquisition) |origin| {
                var projected = origin;
                projected.path.bytes = try a.dupe(u8, origin.path.bytes);
                try json.put(
                    a,
                    result,
                    "acquisition",
                    try values.toJson(workspace.SnapshotRange, a, projected),
                );
                try json.put(a, result, "complete_file", .{
                    .bool = origin.start == 0 and origin.end == origin.file_bytes,
                });
            }
            if (derivation.frozen_input) |ref| try json.put(
                a,
                result,
                "frozen_input",
                try values.toJson(state.Reference, a, ref),
            );
        }
        fn appendDerivationInspection(
            a: std.mem.Allocator,
            result: *json.Value,
            derivation: workspace.Derivation,
        ) !void {
            if (derivation.inspection) |origin| {
                try json.put(
                    a,
                    result,
                    "inspection",
                    try values.toJson(wc.GuestViewSelection, a, .{
                        .level = origin.level,
                        .expected = .{
                            .work = try wp.reference(a, .work, origin.observation.work.id),
                            .execution_revision = origin.observation.work.execution_revision,
                            .control_revision = origin.observation.work.control_revision,
                        },
                        .realization_revision = origin.observation.work.realization_revision,
                        .nodes = origin.nodes,
                        .disclosure = origin.disclosure,
                    }),
                );
                try json.put(
                    a,
                    result,
                    "checkpoint",
                    try values.toJson(state.Reference, a, origin.observation.work.checkpoint),
                );
            }
            if (derivation.semantic_source) |origin| {
                try json.put(a, result, "semantic_source", try values.toJson(
                    @TypeOf(origin.selection),
                    a,
                    origin.selection,
                ));
                try json.put(a, result, "semantic_runtime", try values.toJson(
                    state.Reference,
                    a,
                    origin.runtime,
                ));
                try json.put(a, result, "guest_image", try values.toJson(
                    state.Reference,
                    a,
                    origin.guest,
                ));
            }
        }
        fn workspaceDerivationPage(
            self: *Self,
            a: std.mem.Allocator,
            derivation: workspace.Derivation,
            page: wc.Page,
        ) !json.Value {
            // Reuse the ordinary projection's fields, but fold its growing
            // source vector directly into the requested canonical byte range.
            var metadata = derivation;
            metadata.sources.items = &.{};
            const fields = try self.workspaceDerivationObservation(a, metadata);
            const keys = try a.dupe([]const u8, fields.object.keys());
            defer a.free(keys);
            std.mem.sort([]const u8, keys, {}, struct {
                fn less(_: void, left: []const u8, right: []const u8) bool {
                    return std.mem.lessThan(u8, left, right);
                }
            }.less);
            var output = try wp.Range.init(a, page);
            defer output.deinit(a);
            var element = std.heap.ArenaAllocator.init(a);
            defer element.deinit();
            try output.append("{");
            for (keys, 0..) |key, index| {
                if (index != 0) try output.append(",");
                try output.append(try json.canonical(a, json.string(key)));
                try output.append(":");
                if (!same(key, "sources")) {
                    try output.append(try json.canonical(a, fields.object.get(key).?));
                    continue;
                }
                try output.append("[");
                for (derivation.sources.items, 0..) |ref, i| {
                    _ = element.reset(.retain_capacity);
                    const scratch = element.allocator();
                    if (i != 0) try output.append(",");
                    try output.append(
                        try json.canonical(
                            scratch,
                            try values.toJson(
                                wc.Ref,
                                scratch,
                                try wp.reference(scratch, .value, ref.digest),
                            ),
                        ),
                    );
                }
                try output.append("]");
            }
            try output.append("}");
            return output.finish(a);
        }
        fn workspaceValueObservation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
        ) !json.Value {
            const ref = try wp.reference(a, .value, id);
            const value = try self.workspaceValueReference(a, task_id, ref);
            const schema = try self.store().object(a, value.schema, null);
            defer a.free(schema);
            const bytes = try self.store().object(a, value.value, null);
            defer a.free(bytes);
            var result = json.object();
            try json.put(a, &result, "value", try values.toJson(wc.Ref, a, ref));
            try json.put(
                a,
                &result,
                "schema",
                try values.toJson(wc.Ref, a, try wp.reference(a, .schema, value.schema.digest)),
            );
            try json.put(
                a,
                &result,
                "provenance",
                try values.toJson(
                    wc.Ref,
                    a,
                    try wp.reference(a, .provenance, value.provenance.digest),
                ),
            );
            try json.put(
                a,
                &result,
                "preview",
                try @import("dynamic_values.zig").preview(a, schema, bytes),
            );
            const provenance = try self.store().object(a, value.provenance, null);
            defer a.free(provenance);
            var derivation = try contracts.decodeOwned(workspace.Derivation, a, provenance);
            defer derivation.deinit();
            try json.put(
                a,
                &result,
                "derivation",
                try self.workspaceDerivationObservation(a, derivation.value),
            );
            if (derivation.value.acquisition != null or derivation.value.frozen_input != null or
                derivation.value.semantic_source != null)
            {
                try json.put(a, &result, "source", try values.toJson(
                    wc.Ref,
                    a,
                    try wp.reference(a, .source, value.provenance.digest),
                ));
            }
            return result;
        }
        fn workspaceViewObservation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
            page: wc.Page,
        ) !json.Value {
            const key = try workspaceContentCustody(a, task_id, id);
            var saved = try self.record(workspace.View, a, "workspace_view", key, task_id);
            defer saved.deinit();
            const bytes = try contracts.encodeOwned(
                workspace.ViewArtifact,
                a,
                saved.value.description,
            );
            defer a.free(bytes);
            if (saved.value.description.version != 1 or !std.meta.eql(
                saved.value.task,
                task_id,
            ) or
                !std.meta.eql(saved.value.id, key) or
                !std.meta.eql(saved.value.artifact.digest, id) or
                !std.meta.eql(
                    storage.digest(bytes),
                    id,
                ) or bytes.len != saved.value.artifact.bytes) return error.CorruptState;
            var result = json.object();
            try json.put(
                a,
                &result,
                "view",
                try values.toJson(wc.Ref, a, try wp.reference(a, .view, id)),
            );
            try json.put(a, &result, "coverage", json.string("selected_values_only"));
            var selection = try wp.Range.init(a, page);
            defer selection.deinit(a);
            try selection.append("[");
            var element = std.heap.ArenaAllocator.init(a);
            defer element.deinit();
            for (saved.value.description.values.items, 0..) |ref, i| {
                // Each element is independently projected and released. A
                // bounded page never retains N complete value previews.
                _ = element.reset(.retain_capacity);
                const scratch = element.allocator();
                const value = try self.workspaceValueReference(
                    scratch,
                    task_id,
                    try wp.reference(scratch, .value, ref.digest),
                );
                if (!std.meta.eql(value.artifact, ref)) return error.CorruptState;
                if (i != 0) try selection.append(",");
                try selection.append(
                    try json.canonical(
                        scratch,
                        try self.workspaceValueObservation(scratch, task_id, ref.digest),
                    ),
                );
            }
            try selection.append("]");
            try json.put(a, &result, "selection", try selection.finish(a));
            try json.put(
                a,
                &result,
                "value_count",
                try json.number(a, saved.value.description.values.items.len),
            );
            return result;
        }
        fn workspaceContextMutation(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            command: wc.Context,
            snapshot: ?state.Reference,
            input: ?state.Reference,
        ) !Admission {
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            const Request = workspace.ContextRequest;
            const request = try operation(Request, a, .{
                .task = task_id,
                .command = command,
                .snapshot = snapshot,
                .input = input,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            var compiler_facts: CompilerFacts = .{ .allocator = self.allocator };
            defer compiler_facts.deinit();
            const prior_compiler_facts = self.compiler_facts;
            if (self.compiler_facts == null) self.compiler_facts = &compiler_facts;
            defer self.compiler_facts = prior_compiler_facts;
            try self.prepareWorkspaceContext(a, task_id, command);
            var semantic = try self.prepareContextSemanticValue(a, parent.value, command);
            defer if (semantic) |*prepared| prepared.deinit(a);
            try self.store().begin();
            defer self.store().rollback();
            const artifact: state.Reference, const kind: @FieldType(
                wc.Ref,
                "kind",
            ) = switch (command) {
                .materialize => |materialize| .{
                    try self.materializeWorkspaceContext(
                        a,
                        task_id,
                        parent.value,
                        materialize,
                        snapshot,
                        input,
                        semantic,
                    ),
                    .value,
                },
                .select => |selection| .{
                    try self.selectWorkspaceContext(a, task_id, selection),
                    .view,
                },
                else => return error.InvalidState,
            };
            return self.workspaceCommit(
                a,
                parent.value,
                operation_id,
                request,
                artifact.digest,
                kind,
                artifact,
                .{ .context = .{ .command = command, .snapshot = snapshot, .input = input } },
            );
        }
        fn prepareContextSemanticValue(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            command: wc.Context,
        ) !?PreparedSemanticValue {
            return if (command == .materialize and
                command.materialize.input == .semantic_source)
                try self.prepareSemanticValue(
                    a,
                    parent,
                    command.materialize.input.semantic_source,
                )
            else
                null;
        }
        fn materializeWorkspaceContext(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            parent: state.Task,
            materialize: @FieldType(wc.Context, "materialize"),
            snapshot: ?state.Reference,
            input: ?state.Reference,
            semantic: ?PreparedSemanticValue,
        ) !state.Reference {
            if (semantic) |prepared| return self.materializeSemanticContext(
                a,
                task_id,
                materialize,
                prepared,
            );
            if (materialize.input == .guest_view) return self.materializeGuestContext(
                a,
                task_id,
                materialize,
            );
            if (materialize.input == .authorized_input) return self.materializeAuthorizedContext(
                a,
                task_id,
                materialize,
                parent,
                input,
            );
            if (materialize.input == .snapshot) {
                const selection = materialize.input.snapshot;
                if (materialize.sources.items.len != 0) return error.InvalidMaterialization;
                const source = snapshot orelse return error.Denied;
                const result = try self.workspaceMaterializeSnapshot(
                    a,
                    parent,
                    source,
                    selection,
                );
                return result;
            }
            return self.materializeDerivedContext(a, task_id, materialize);
        }
        fn selectWorkspaceContext(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            selection: @FieldType(wc.Context, "select"),
        ) !state.Reference {
            const references = try a.alloc(state.Reference, selection.values.items.len);
            defer a.free(references);
            for (selection.values.items, references) |ref, *out|
                out.* =
                    (try self.workspaceValueReference(a, task_id, ref)).artifact;
            const view: workspace.ViewArtifact = .{ .values = .{ .items = references } };
            const bytes = try contracts.encodeOwned(workspace.ViewArtifact, a, view);
            defer a.free(bytes);
            const ref = try self.store().putObject(bytes);
            const key = try workspaceContentCustody(a, task_id, ref.digest);
            if (try self.store().recordBytes(a, "workspace_view", key, task_id)) |prior| {
                defer a.free(prior);
                const expected = try contracts.encodeOwned(workspace.View, a, .{
                    .id = key,
                    .task = task_id,
                    .artifact = ref,
                    .description = view,
                });
                defer a.free(expected);
                if (!same(prior, expected)) return error.CorruptState;
            } else try self.store().createRecord(
                workspace.View,
                "workspace_view",
                key,
                task_id,
                .{ .id = key, .task = task_id, .artifact = ref, .description = view },
            );
            return ref;
        }
        fn materializeSemanticContext(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            materialize: @FieldType(wc.Context, "materialize"),
            prepared: PreparedSemanticValue,
        ) !state.Reference {
            if (materialize.sources.items.len != 0) return error.InvalidMaterialization;
            _ = try self.store().putObject(prepared.runtime);
            const result = try self.workspacePublishValue(
                a,
                task_id,
                try self.store().putObject(prepared.schema),
                try self.store().putObject(prepared.value),
                .{
                    .kind = .inspection,
                    .sources = .{ .items = &.{} },
                    .semantic_source = prepared.origin,
                },
            );
            return result;
        }
        fn materializeGuestContext(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            materialize: @FieldType(wc.Context, "materialize"),
        ) !state.Reference {
            if (materialize.sources.items.len != 0) return error.InvalidMaterialization;
            const selection = materialize.input.guest_view;
            const observed = try self.freezeWorkspaceWork(
                a,
                task_id,
                selection.expected.work,
                false,
            );
            try inspectionSelection(observed.work, selection);
            // The controller can disclose graph metadata of its own
            // work. Node selection narrows that grant; it never
            // exposes payload, source text or another task's work.
            var prepared = try self.inspectionRuntime(a, observed.work);
            defer prepared.deinit();
            const code = try prepared.runtime.encode(a);
            defer a.free(code);
            const origin: workspace.Inspection = .{
                .level = selection.level,
                .observation = observed,
                .nodes = selection.nodes,
                .disclosure = selection.disclosure,
                .runtime_code = try self.store().putObject(code),
            };
            const derived = try self.workspaceInspectionBytes(a, task_id, origin);
            defer a.free(derived.schema);
            defer a.free(derived.value);
            return try self.workspacePublishValue(a, task_id, try self.store().putObject(
                derived.schema,
            ), try self.store().putObject(derived.value), .{
                .kind = .inspection,
                .sources = .{ .items = &.{} },
                .inspection = origin,
            });
        }
        fn materializeAuthorizedContext(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            materialize: @FieldType(wc.Context, "materialize"),
            parent: state.Task,
            input: ?state.Reference,
        ) !state.Reference {
            if (materialize.sources.items.len != 0) return error.InvalidMaterialization;
            const ref = input orelse return error.UnauthorizedInput;
            try workspaceSnapshotAccess(parent, ref);
            const bytes = try self.store().object(a, ref, null);
            defer a.free(bytes);
            var decoded = try contracts.decodeOwned(
                contracts.tool_construction.Input,
                a,
                bytes,
            );
            defer decoded.deinit();
            var descriptor = try data.schema.decode(a, decoded.value.schema.bytes);
            defer descriptor.deinit();
            try data.schema.validateValue(
                a,
                descriptor.descriptor,
                decoded.value.value.bytes,
            );
            const value = try self.workspacePublishValue(
                a,
                task_id,
                try self.store().putObject(decoded.value.schema.bytes),
                try self.store().putObject(decoded.value.value.bytes),
                .{ .kind = .acquisition, .sources = .{ .items = &.{} }, .frozen_input = ref },
            );
            return value;
        }
        fn materializeDerivedContext(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            materialize: @FieldType(wc.Context, "materialize"),
        ) !state.Reference {
            var sources: std.ArrayList(state.Reference) = .empty;
            defer sources.deinit(a);
            for (materialize.sources.items) |ref| try sources.append(
                a,
                (try self.workspaceValueReference(a, task_id, ref)).artifact,
            );
            const schema: state.Reference, const payload: state.Reference =
                switch (materialize.input.value) {
                    .reference => |ref| inner: {
                        const origin = try self.workspaceValueReference(a, task_id, ref);
                        if (sources.items.len == 0) return origin.artifact;
                        try sources.append(a, origin.artifact);
                        break :inner .{ origin.schema, origin.value };
                    },
                    .inline_json => |inline_value| inner: {
                        const schema = try self.workspaceOwnedDescriptor(
                            a,
                            task_id,
                            inline_value.schema,
                        );
                        const descriptor = try self.store().object(a, schema, null);
                        defer a.free(descriptor);
                        const text = inline_value.json_text.bytes;
                        var parsed = try json.parse(a, text, .{
                            .bytes = text.len,
                            .depth = text.len,
                            .tokens = text.len,
                            .members = text.len,
                        });
                        defer parsed.deinit();
                        const bytes = try @import("dynamic_values.zig").encode(
                            a,
                            descriptor,
                            parsed.value,
                        );
                        defer a.free(bytes);
                        break :inner .{ schema, try self.store().putObject(bytes) };
                    },
                };
            return try self.workspacePublishValue(
                a,
                task_id,
                schema,
                payload,
                .{
                    .kind = if (sources.items.len == 0) .hypothesis else .judgment,
                    .sources = .{ .items = sources.items },
                },
            );
        }
        fn prepareWorkspaceContext(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            command: wc.Context,
        ) !void {
            switch (command) {
                .materialize => |materialize| switch (materialize.input) {
                    .value => |input| {
                        for (materialize.sources.items) |ref| _ = try self.workspaceValueReference(
                            a,
                            task_id,
                            ref,
                        );
                        switch (input) {
                            .reference => |ref| _ = try self.workspaceValueReference(
                                a,
                                task_id,
                                ref,
                            ),
                            .inline_json => |value| _ = try self.workspaceOwnedDescriptor(
                                a,
                                task_id,
                                value.schema,
                            ),
                        }
                    },
                    .guest_view => |selection| {
                        if (materialize.sources.items.len != 0) return error.InvalidMaterialization;
                        const observed = try self.freezeWorkspaceWork(
                            a,
                            task_id,
                            selection.expected.work,
                            false,
                        );
                        try inspectionSelection(observed.work, selection);
                        var prepared = try self.inspectionRuntime(a, observed.work);
                        prepared.deinit();
                    },
                    .snapshot, .authorized_input, .semantic_source => {},
                },
                .select => |selection| for (selection.values.items) |ref| {
                    _ = try self.workspaceValueReference(a, task_id, ref);
                },
                else => return error.InvalidState,
            }
        }
        fn prepareSemanticValue(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            selection: @FieldType(wc.Materialization, "semantic_source"),
        ) !PreparedSemanticValue {
            const request: wc.Command = .{ .program = .{ .inspect = .{
                .target = .{ .semantic_source = .{
                    .subject = selection.subject,
                    .section = .{ .summary = .{} },
                } },
                .page = .{},
            } } };
            const basis_bytes = try self.workspaceReadBasis(a, parent, request);
            defer a.free(basis_bytes);
            var basis = try contracts.decodeOwned(workspace.ReadObservation, a, basis_bytes);
            errdefer basis.deinit();
            const resolved = try self.semanticRuntime(a, parent.id, selection.subject, basis.value);
            var admitted = resolved.admitted;
            defer admitted.deinit();
            const runtime = try admitted.encode(a);
            errdefer a.free(runtime);
            const derived = try self.renderSemanticValue(
                a,
                &admitted,
                selection.module,
                selection.references,
            );
            return .{
                .schema = derived.schema,
                .value = derived.value,
                .runtime = runtime,
                .basis = basis,
                .origin = .{
                    .selection = selection,
                    .basis = basis.value,
                    .guest = resolved.guest,
                    .runtime = .{ .digest = storage.digest(runtime), .bytes = runtime.len },
                },
            };
        }
        fn semanticValueBytes(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            origin: workspace.SemanticSource,
        ) !construction.SemanticValue {
            var resolved = try self.semanticRuntime(
                a,
                task_id,
                origin.selection.subject,
                origin.basis,
            );
            defer resolved.deinit();
            if (!std.meta.eql(origin.guest, resolved.guest) or
                !std.meta.eql(origin.runtime.digest, resolved.admitted.identity))
            {
                return error.InvalidArchive;
            }
            const bytes = try self.store().object(a, origin.runtime, null);
            defer a.free(bytes);
            var retained = try kosmos.RuntimeArtifact.init(a, bytes, origin.runtime.digest);
            defer retained.deinit();
            return self.renderSemanticValue(
                a,
                &retained,
                origin.selection.module,
                origin.selection.references,
            );
        }
        fn workspaceValueReference(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
        ) !WorkspaceValueReference {
            return self.workspaceValueReferenceIn(a, task_id, ref, null);
        }
        fn workspaceValueReferenceIn(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
            checked: ?*SnapshotValidation,
        ) !WorkspaceValueReference {
            const id = try wp.identity(ref, .value);
            const key = try workspaceContentCustody(a, task_id, id);
            var saved = try self.record(workspace.Value, a, "workspace_value", key, task_id);
            defer saved.deinit();
            try validateWorkspaceValueIdentity(a, task_id, key, id, saved.value);
            if (saved.value.derivation.semantic_source) |origin| {
                try self.validateSemanticValueOrigin(
                    a,
                    task_id,
                    id,
                    saved.value,
                    checked,
                    origin,
                );
            } else if (saved.value.derivation.inspection) |origin| {
                try self.validateInspectionValueOrigin(a, task_id, saved.value, origin);
            } else if (saved.value.derivation.kind == .inspection) return error.InvalidArchive;
            if (saved.value.derivation.acquisition) |origin| {
                try self.validateAcquiredValueOrigin(a, task_id, saved.value, origin);
            } else if (saved.value.derivation.frozen_input) |frozen_ref| {
                try self.validateFrozenValueOrigin(a, task_id, saved.value, frozen_ref);
            } else if (saved.value.derivation.kind == .acquisition) return error.CorruptState;
            if (saved.value.derivation.delegation != null or
                saved.value.derivation.capture != null) try self.validateDelegatedValue(
                a,
                task_id,
                saved.value,
            );
            const origin = saved.value.derivation;
            if (origin.program == null and
                origin.work == null and
                origin.acquisition == null and
                origin.frozen_input == null and
                origin.delegation == null and
                origin.capture == null and
                origin.inspection == null and
                origin.semantic_source == null)
            {
                const expected: @TypeOf(
                    origin.kind,
                ) = if (origin.sources.items.len == 0) .hypothesis else .judgment;
                if (origin.kind != expected) return error.InvalidArchive;
            }
            return .{
                .artifact = saved.value.artifact,
                .schema = saved.value.description.schema,
                .value = saved.value.description.value,
                .provenance = saved.value.description.provenance,
            };
        }
        fn validateSemanticValueOrigin(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
            saved: workspace.Value,
            checked: ?*SnapshotValidation,
            origin: workspace.SemanticSource,
        ) !void {
            const d = saved.derivation;
            if (d.kind != .inspection or d.sources.items.len != 0 or d.program != null or
                d.work != null or d.acquisition != null or d.frozen_input != null or
                d.delegation != null or d.capture != null or d.inspection != null)
            {
                return error.InvalidArchive;
            }
            const fact: SnapshotValidation.Key = .{
                .kind = .semantic_source,
                .task = task_id,
                .identity = id,
            };
            const facts =
                if (checked) |context|
                    if (context.semantic_sources) context else null
                else
                    null;
            if (facts == null or !facts.?.facts.contains(fact)) {
                const derived = try self.semanticValueBytes(a, task_id, origin);
                defer a.free(derived.schema);
                defer a.free(derived.value);
                if (!std.meta.eql(saved.description.schema, state.Reference{
                    .digest = storage.digest(derived.schema),
                    .bytes = derived.schema.len,
                }) or !std.meta.eql(saved.description.value, state.Reference{
                    .digest = storage.digest(derived.value),
                    .bytes = derived.value.len,
                })) return error.InvalidArchive;
                if (facts) |validated| try validated.facts.put(
                    validated.allocator,
                    fact,
                    .checked,
                );
            }
        }
        fn validateInspectionValueOrigin(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            saved: workspace.Value,
            origin: workspace.Inspection,
        ) !void {
            const d = saved.derivation;
            if (d.kind != .inspection or
                d.sources.items.len != 0 or
                d.program != null or
                d.work != null or
                d.acquisition != null or
                d.frozen_input != null or
                d.delegation != null or
                d.capture != null)
                return error.InvalidArchive;
            const derived = try self.workspaceInspectionBytes(a, task_id, origin);
            defer a.free(derived.schema);
            defer a.free(derived.value);
            if (!std.meta.eql(saved.description.schema, state.Reference{
                .digest = storage.digest(derived.schema),
                .bytes = derived.schema.len,
            }) or
                !std.meta.eql(saved.description.value, state.Reference{
                    .digest = storage.digest(derived.value),
                    .bytes = derived.value.len,
                })) return error.InvalidArchive;
        }
        fn validateAcquiredValueOrigin(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            saved: workspace.Value,
            origin: workspace.SnapshotRange,
        ) !void {
            if (saved.derivation.kind != .acquisition or
                saved.derivation.sources.items.len != 0 or
                saved.derivation.program != null or
                saved.derivation.work != null or
                saved.derivation.frozen_input != null)
                return error.CorruptState;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try workspaceSnapshotAccess(parent.value, origin.snapshot);
            const derived = try self.workspaceSnapshotBytes(a, origin);
            defer a.free(derived.schema);
            defer a.free(derived.value);
            if (!std.meta.eql(saved.description.schema, state.Reference{
                .digest = storage.digest(derived.schema),
                .bytes = derived.schema.len,
            }) or !std.meta.eql(saved.description.value, state.Reference{
                .digest = storage.digest(derived.value),
                .bytes = derived.value.len,
            })) return error.CorruptState;
        }
        fn validateFrozenValueOrigin(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            saved: workspace.Value,
            frozen_ref: state.Reference,
        ) !void {
            if (saved.derivation.kind != .acquisition or
                saved.derivation.sources.items.len != 0 or
                saved.derivation.program != null or
                saved.derivation.work != null)
                return error.CorruptState;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try workspaceSnapshotAccess(parent.value, frozen_ref);
            const bytes = try self.store().object(a, frozen_ref, null);
            defer a.free(bytes);
            var input_value = try contracts.decodeOwned(
                contracts.tool_construction.Input,
                a,
                bytes,
            );
            defer input_value.deinit();
            if (!std.meta.eql(saved.description.schema, state.Reference{
                .digest = storage.digest(input_value.value.schema.bytes),
                .bytes = input_value.value.schema.bytes.len,
            }) or !std.meta.eql(saved.description.value, state.Reference{
                .digest = storage.digest(input_value.value.value.bytes),
                .bytes = input_value.value.value.bytes.len,
            })) return error.CorruptState;
            var descriptor = try data.schema.decode(a, input_value.value.schema.bytes);
            defer descriptor.deinit();
            try data.schema.validateValue(
                a,
                descriptor.descriptor,
                input_value.value.value.bytes,
            );
        }
        fn validateWorkspaceValueIdentity(
            a: std.mem.Allocator,
            task_id: state.TaskId,
            key: state.Digest,
            id: state.Digest,
            saved: workspace.Value,
        ) !void {
            if (!std.meta.eql(saved.task, task_id) or
                !std.meta.eql(saved.id, key) or
                !std.meta.eql(saved.artifact.digest, id))
                return error.CorruptState;
            const encoded = try contracts.encodeOwned(
                workspace.ValueArtifact,
                a,
                saved.description,
            );
            defer a.free(encoded);
            const provenance = try contracts.encodeOwned(
                workspace.Derivation,
                a,
                saved.derivation,
            );
            defer a.free(provenance);
            if (saved.description.version != 1 or !std.meta.eql(
                storage.digest(encoded),
                id,
            ) or encoded.len != saved.artifact.bytes or !std.meta.eql(
                storage.digest(provenance),
                saved.description.provenance.digest,
            )) return error.CorruptState;
        }
        fn inspectionSelection(work: workspace.Work, selected: wc.GuestViewSelection) !void {
            if (!std.meta.eql(work.id, try wp.identity(selected.expected.work, .work)) or
                work.execution_revision != selected.expected.execution_revision or
                work.control_revision != selected.expected.control_revision or
                work.realization_revision != selected.realization_revision)
                return error.StaleRevision;
        }
        fn inspectionRuntime(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
        ) !kosmos.Prepared {
            var program = try self.workspaceProgram(a, work.task, work.program);
            defer program.deinit();
            const image = try self.store().object(a, program.value.description.image, null);
            defer a.free(image);
            if (work.runtime) |ref| {
                var selected = try self.workspaceRuntime(a, work.task, ref.digest, work.program);
                defer selected.deinit();
                return kosmos.Prepared.initWithRuntime(a, image, &selected.admitted);
            }
            return self.program.prepare(a, image);
        }
        fn workspaceInspectionBytes(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            origin: workspace.Inspection,
        ) !InspectionValue {
            const work = origin.observation.work;
            if (!std.meta.eql(work.task, task_id)) return error.Denied;
            try self.validateWorkspacePublication(a, task_id, origin.observation);
            var prepared = try self.inspectionRuntime(a, work);
            defer prepared.deinit();
            const code = try self.store().object(a, origin.runtime_code, null);
            defer a.free(code);
            if (!std.meta.eql(
                prepared.runtime.identity,
                origin.runtime_code.digest,
            )) return error.InvalidRuntime;
            if (origin.level == .outer_execution)
                return self.workspaceOuterInspection(a, &prepared, origin);
            const checkpoint = try self.store().object(a, work.checkpoint, null);
            defer a.free(checkpoint);
            const mask = try inspectionNodeMask(a, checkpoint, origin.nodes);
            defer if (mask) |items| a.free(items);
            const disclosure = try operation(struct {
                task: state.TaskId,
                work: state.Digest,
                checkpoint: state.Reference,
                scope: wc.NodeScope,
                disclosure: ?wc.Disclosure,
            }, a, .{
                .task = task_id,
                .work = work.id,
                .checkpoint = work.checkpoint,
                .scope = origin.nodes,
                .disclosure = origin.disclosure,
            });
            if (origin.disclosure) |selected| return self.workspaceDetailedInspection(
                a,
                &prepared,
                work,
                checkpoint,
                mask,
                selected,
                disclosure,
            );
            var view = try kosmos.RuntimeViews.capture(
                a,
                prepared.guest.core.?.admitted(),
                checkpoint,
                .{
                    .guest = prepared.guest.core.?.admitted().identity(),
                    .core = prepared.runtime.content.value.manifest.source,
                    .realization = prepared.runtime.identity,
                    .checkpoint = work.checkpoint.digest,
                    .execution = work.id,
                    .guest_revision = work.execution_revision,
                    .realization_revision = work.realization_revision,
                    .disclosure = disclosure,
                },
                mask,
            );
            defer view.deinit();
            const schema = try kosmos.RuntimeViews.schemaBytes(a);
            errdefer a.free(schema);
            return .{ .schema = schema, .value = try kosmos.RuntimeViews.encode(a, view.value) };
        }
        fn inspectionNodeMask(
            a: std.mem.Allocator,
            checkpoint: []const u8,
            nodes: wc.NodeScope,
        ) !?[]bool {
            var mask: ?[]bool = null;
            errdefer if (mask) |items| a.free(items);
            if (nodes == .selected) {
                var decoded = try data.state_image.decodeGraphBorrowed(a, checkpoint, .{});
                defer decoded.deinit();
                mask = try a.alloc(bool, decoded.state.nodes.len);
                @memset(mask.?, false);
                for (nodes.selected.items) |node| {
                    if (node >= mask.?.len) return error.InvalidDisclosure;
                    mask.?[@intCast(node)] = true;
                }
            }
            return mask;
        }
        fn workspaceOuterInspection(
            self: *Self,
            a: std.mem.Allocator,
            prepared: *kosmos.Prepared,
            origin: workspace.Inspection,
        ) !InspectionValue {
            if (origin.disclosure) |selected| if (selected.snapshot)
                return error.InvalidDisclosure;
            const work = origin.observation.work;
            const ref =
                if (work.outer_operation) |pending|
                    pending.capsule
                else
                    work.runtime_capsule orelse
                        return error.OuterCutUnavailable;
            const bytes = try self.store().object(a, ref, null);
            defer a.free(bytes);
            var capsule = try kosmos.RuntimeCapsule.read(a, bytes);
            defer capsule.deinit();
            if (capsule.value.record.kind != .outer_execution)
                return error.OuterCutUnavailable;
            var graph = try data.state_image.decodeGraphBorrowed(a, capsule.value.checkpoint, .{});
            defer graph.deinit();
            var mask: ?[]bool = null;
            defer if (mask) |selected| a.free(selected);
            if (origin.nodes == .selected) {
                mask = try a.alloc(bool, graph.state.nodes.len);
                @memset(mask.?, false);
                for (origin.nodes.selected.items) |node| {
                    if (node >= mask.?.len) return error.InvalidDisclosure;
                    mask.?[@intCast(node)] = true;
                }
            }
            const disclosure = try @import(
                "workspace_observers.zig",
            ).disclosure(a, graph.state.nodes.len, mask, origin.disclosure orelse .{});
            defer disclosure.deinit(a);
            const identity = try operation(workspace.Inspection, a, origin);
            var view = try kosmos.RuntimeCapsule.inspectOuter(
                a,
                prepared.guest.core.?.admitted(),
                &prepared.runtime,
                bytes,
                disclosure.value,
                identity,
            );
            defer view.deinit();
            const schema = try kosmos.RuntimeCapsule.outerViewSchemaBytes(a);
            errdefer a.free(schema);
            return .{
                .schema = schema,
                .value = try kosmos.RuntimeCapsule.encodeOuterView(a, view.value),
            };
        }
        fn workspaceDetailedInspection(
            _: *Self,
            a: std.mem.Allocator,
            prepared: *kosmos.Prepared,
            work: workspace.Work,
            checkpoint: []const u8,
            nodes: ?[]const bool,
            selected: wc.Disclosure,
            disclosure: state.Digest,
        ) !InspectionValue {
            var graph = try data.state_image.decodeGraphBorrowed(a, checkpoint, .{});
            defer graph.deinit();
            const scope = try @import("workspace_observers.zig").disclosure(
                a,
                graph.state.nodes.len,
                nodes,
                selected,
            );
            defer scope.deinit(a);
            var view = try kosmos.RuntimeViews.captureDetailed(
                a,
                prepared.guest.core.?.admitted(),
                checkpoint,
                .{
                    .guest = prepared.guest.core.?.admitted().identity(),
                    .core = prepared.runtime.content.value.manifest.source,
                    .realization = prepared.runtime.identity,
                    .checkpoint = work.checkpoint.digest,
                    .execution = work.id,
                    .guest_revision = work.execution_revision,
                    .realization_revision = work.realization_revision,
                    .disclosure = disclosure,
                },
                scope.value,
            );
            defer view.deinit();
            const schema = try kosmos.RuntimeViews.detailedSchemaBytes(a);
            errdefer a.free(schema);
            return .{
                .schema = schema,
                .value = try kosmos.RuntimeViews.encodeDetailed(a, view.value),
            };
        }
        fn validateDelegatedValue(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            value: workspace.Value,
        ) !void {
            const origin = value.derivation;
            if (origin.kind != .judgment or
                origin.program != null or
                origin.acquisition != null or
                origin.frozen_input != null or
                origin.delegation == null or
                origin.capture == null)
                return error.InvalidArchive;
            var work = try self.workspaceWork(
                a,
                task_id,
                origin.work orelse return error.InvalidArchive,
            );
            defer work.deinit();
            if (work.value.outcome_kind != .completed or !std.meta.eql(
                work.value.delegation,
                origin.delegation,
            ) or !std.meta.eql(
                work.value.answer_value,
                value.artifact,
            )) return error.InvalidArchive;
            var delegation = try contracts.decodeOwned(
                workspace.Delegation,
                a,
                try self.store().object(a, origin.delegation.?, null),
            );
            defer delegation.deinit();
            if (delegation.value.selection != .model or !std.meta.eql(
                delegation.value.instrument,
                work.value.id,
            ) or !std.meta.eql(delegation.value.task, task_id) or
                origin.sources.items.len != delegation.value.inputs.items.len)
                return error.InvalidArchive;
            for (origin.sources.items, delegation.value.inputs.items) |left, right|
                if (!std.meta.eql(left, right)) return error.InvalidArchive;
            try self.validateDelegatedAnswer(a, work.value, delegation.value, value);
            try self.validateDelegatedCapture(a, task_id, work.value, origin);
        }
        fn validateDelegatedAnswer(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            delegation: workspace.Delegation,
            value: workspace.Value,
        ) !void {
            var port = try contracts.decodeOwned(
                workspace.Port,
                a,
                try self.store().object(a, delegation.port, null),
            );
            defer port.deinit();
            var result = try contracts.decodeOwned(
                instrument.Output,
                a,
                try self.store().object(
                    a,
                    work.result orelse return error.InvalidArchive,
                    null,
                ),
            );
            defer result.deinit();
            if (result.value != .answer or !std.meta.eql(
                value.description.schema,
                port.value.interface.argument,
            ) or !std.meta.eql(value.description.value, state.Reference{
                .digest = storage.digest(result.value.answer.bytes),
                .bytes = result.value.answer.bytes.len,
            })) return error.InvalidArchive;
        }
        fn validateDelegatedCapture(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work: workspace.Work,
            origin: workspace.Derivation,
        ) !void {
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                work.instrument_occurrence orelse return error.InvalidArchive,
                task_id,
            );
            defer pending.deinit();
            if (pending.value.state != .admitted or
                pending.value.state.admitted != .reply)
                return error.InvalidArchive;
            var capture_value = try self.record(
                state.Capture,
                a,
                "capture",
                pending.value.state.admitted.reply.attempt,
                task_id,
            );
            defer capture_value.deinit();
            if (!std.meta.eql(
                capture_value.value.response,
                origin.capture,
            )) return error.InvalidArchive;
        }
        fn workspaceSnapshotAccess(parent: state.Task, snapshot: state.Reference) !void {
            for (parent.resources.items) |ref| if (std.meta.eql(ref, snapshot)) return;
            return error.Denied;
        }
        fn workspaceSnapshotBytes(
            self: *Self,
            a: std.mem.Allocator,
            origin: workspace.SnapshotRange,
        ) !struct {
            schema: []u8,
            value: []u8,
        } {
            const bytes = try self.store().object(a, origin.snapshot, null);
            defer a.free(bytes);
            var source = try @import("repository.zig").Snapshot.openBorrowed(a, bytes);
            defer source.deinit();
            const file = source.get(origin.path.bytes) orelse return error.CorruptState;
            if (!std.meta.eql(file.sha256, origin.file_digest) or
                origin.start > origin.end or
                origin.end > file.contents.bytes.len or
                origin.file_bytes != file.contents.bytes.len or
                origin.excluded_entries != source.decoded.value.excluded_entries)
                return error.CorruptState;
            const part = file.contents.bytes[@intCast(origin.start)..@intCast(origin.end)];
            if (std.unicode.utf8ValidateSlice(part)) return .{
                .schema = try values.schemaBytes(contracts.Utf8, a),
                .value = try contracts.encodeOwned(contracts.Utf8, a, .{ .bytes = part }),
            };
            return .{
                .schema = try values.schemaBytes(contracts.Bytes(null), a),
                .value = try contracts.encodeOwned(contracts.Bytes(null), a, .{ .bytes = part }),
            };
        }
        fn workspaceSnapshotRange(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            snapshot: state.Reference,
            selection: anytype,
        ) !workspace.SnapshotRange {
            try workspaceSnapshotAccess(parent, snapshot);
            const bytes = try self.store().object(a, snapshot, null);
            defer a.free(bytes);
            var source = try @import("repository.zig").Snapshot.openBorrowed(a, bytes);
            defer source.deinit();
            const file = source.get(selection.path.bytes) orelse return error.SourceMissing;
            if (selection.offset > file.contents.bytes.len) return error.InvalidRange;
            return .{
                .snapshot = snapshot,
                .path = selection.path,
                .file_digest = file.sha256,
                .start = selection.offset,
                .end = selection.offset + @min(
                    selection.maximum,
                    file.contents.bytes.len - selection.offset,
                ),
                .file_bytes = file.contents.bytes.len,
                .excluded_entries = source.decoded.value.excluded_entries,
            };
        }
        fn workspaceMaterializeSnapshot(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            snapshot: state.Reference,
            selection: anytype,
        ) !state.Reference {
            const origin = try self.workspaceSnapshotRange(a, parent, snapshot, selection);
            const derived = try self.workspaceSnapshotBytes(a, origin);
            defer a.free(derived.schema);
            defer a.free(derived.value);
            return self.workspacePublishValue(a, parent.id, try self.store().putObject(
                derived.schema,
            ), try self.store().putObject(derived.value), .{
                .kind = .acquisition,
                .sources = .{ .items = &.{} },
                .acquisition = origin,
            });
        }
        fn workspacePublishValue(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            schema: state.Reference,
            value: state.Reference,
            derivation: workspace.Derivation,
        ) !state.Reference {
            const provenance_bytes = try contracts.encodeOwned(workspace.Derivation, a, derivation);
            defer a.free(provenance_bytes);
            const artifact: workspace.ValueArtifact = .{
                .schema = schema,
                .value = value,
                .provenance = try self.store().putObject(provenance_bytes),
            };
            const bytes = try contracts.encodeOwned(workspace.ValueArtifact, a, artifact);
            defer a.free(bytes);
            const ref = try self.store().putObject(bytes);
            const key = try workspaceContentCustody(a, task_id, ref.digest);
            const record_value: workspace.Value = .{
                .id = key,
                .task = task_id,
                .artifact = ref,
                .description = artifact,
                .derivation = derivation,
            };
            if (try self.store().recordBytes(a, "workspace_value", key, task_id)) |prior| {
                defer a.free(prior);
                const expected = try contracts.encodeOwned(workspace.Value, a, record_value);
                defer a.free(expected);
                if (!same(prior, expected)) return error.CorruptState;
            } else try self.store().createRecord(
                workspace.Value,
                "workspace_value",
                key,
                task_id,
                record_value,
            );
            return ref;
        }
        fn authorizeWorkspace(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            entry: registry.Entry,
            payload: []const u8,
        ) ![]u8 {
            return self.store().project([]u8, a, self.handlers, self.projectionBinding(
                initial,
            ), struct {
                authorize: *const fn (registry.ProjectionContext, []const u8) anyerror![]u8,
                payload: []const u8,
                pub fn run(this: @This(), ctx: registry.ProjectionContext) ![]u8 {
                    return this.authorize(ctx, this.payload);
                }
            }{ .authorize = entry.declaration.workspace.?, .payload = payload });
        }
        fn authorizeWorkspaceOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            entry: registry.Entry,
            payload: []const u8,
        ) ![]u8 {
            const bytes = try self.authorizeWorkspace(a, initial, entry, payload);
            errdefer a.free(bytes);
            var authorized = try contracts.decodeOwned(workspace.Authorized, a, bytes);
            defer authorized.deinit();
            const command = authorized.value.command;
            if (command == .program and
                command.program == .adopt)
                return error.ControllerHandoffRequired;
            if (pending.residual != null and !workspaceIsRead(command)) return error.Denied;
            return bytes;
        }
        fn workspaceIsRead(command: wc.Command) bool {
            return switch (command) {
                .program => |p| p != .build and p != .specialize and p != .adopt and
                    p != .derive and p != .validate,
                .work => |w| w == .inspect or w == .collect or w == .wait,
                .context => |c| c == .inspect or c == .expand,
                .placement => false,
            };
        }
        fn workspaceCompiles(command: wc.Command) bool {
            return command == .program and (command.program == .build or
                command.program == .derive or command.program == .validate);
        }
        fn appendWorkspaceReference(output: *wp.Range, id: state.Digest) !void {
            if (output.total > 1) try output.append(",");
            // Ref's canonical JSON has only a fixed tag and hexadecimal ID.
            try output.append("{\"id\":\"");
            try output.append(&std.fmt.bytesToHex(id, .lower));
            try output.append("\",\"kind\":\"work\"}");
        }
        fn workspaceScopeAt(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            watermark: u64,
        ) ![]state.Digest {
            var ids: std.AutoHashMap(state.Digest, void) = .init(a);
            defer ids.deinit();
            var event_arena = std.heap.ArenaAllocator.init(a);
            defer event_arena.deinit();
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(i64, watermark) orelse return error.InvalidArchive,
                } },
            );
            defer query.deinit();
            while (try query.step() == .row) {
                _ = event_arena.reset(.retain_capacity);
                var event_value = try contracts.decodeOwned(
                    state.Event,
                    event_arena.allocator(),
                    try query.bytes(0),
                );
                defer event_value.deinit();
                // Scope follows the same publication facts as historical work
                // observations; display payloads cannot create or hide work.
                for (event_value.value.workspace_publications.items) |item| try ids.put(
                    item.work,
                    {},
                );
            }
            const result = try a.alloc(state.Digest, ids.count());
            var iterator = ids.keyIterator();
            var i: usize = 0;
            while (iterator.next()) |id| : (i += 1) result[i] = id.*;
            std.mem.sort(state.Digest, result, {}, struct {
                fn less(_: void, left: state.Digest, right: state.Digest) bool {
                    return std.mem.order(u8, &left, &right) == .lt;
                }
            }.less);
            return result;
        }
        fn workspaceParentStopped(self: *const Self, parent: state.Task) bool {
            return parent.terminal() or parent.cancellation != null or
                if (self.remote_stopped_parent) |id| std.meta.eql(id, parent.id) else false;
        }
        fn workspaceInteractionAllowed(parent_stopped: bool, child: workspace.Work) bool {
            return !child.terminal() and
                (child.cancellation == null or
                    child.cancellation_applied) and
                (!parent_stopped or child.cancellation_applied);
        }
        fn workspaceStoppedAt(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            watermark: u64,
        ) !bool {
            if (self.remote_stopped_parent) |id| if (std.meta.eql(id, task_id)) return true;
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(i64, watermark) orelse return error.InvalidArchive,
                } },
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer saved.deinit();
                switch (saved.value.kind) {
                    .cancellation_requested, .completed, .failed, .cancelled => return true,
                    else => {},
                }
            }
            return false;
        }
        fn workspaceInterruptedAt(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            watermark: u64,
        ) !bool {
            var messages: u64 = 0;
            var cancelled = false;
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(i64, watermark) orelse return error.InvalidArchive,
                } },
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer saved.deinit();
                switch (saved.value.kind) {
                    .message_queued => messages = try std.math.add(u64, messages, 1),
                    .message_consumed, .message_not_consumed => messages = std.math.sub(
                        u64,
                        messages,
                        1,
                    ) catch return error.InvalidArchive,
                    .cancellation_requested => cancelled = true,
                    else => {},
                }
            }
            return messages != 0 or cancelled;
        }
        fn freezeWorkspaceWork(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            ref: wc.Ref,
            retained: bool,
        ) !workspace.WorkObservation {
            var saved = if (retained) try self.retainedWorkspaceWork(
                a,
                task_id,
                try wp.identity(ref, .work),
            ) else try self.workspaceWork(a, task_id, try wp.identity(ref, .work));
            defer saved.deinit();
            var work = saved.value;
            if (work.observer) |observer| work.observer =
                try @import("workspace_observers.zig").copyObserver(a, observer);
            errdefer if (work.observer) |observer|
                @import("workspace_observers.zig").freeObserver(a, observer);
            work.inputs.items = try a.dupe(state.Reference, work.inputs.items);
            errdefer a.free(work.inputs.items);
            work.runtime_dependencies.items = try a.dupe(
                state.Reference,
                work.runtime_dependencies.items,
            );
            errdefer a.free(work.runtime_dependencies.items);
            if (work.runtime_trace) |*trace| trace.dependencies.items = try a.dupe(
                state.Reference,
                trace.dependencies.items,
            );
            errdefer if (work.runtime_trace) |trace| a.free(trace.dependencies.items);
            if (work.outer_operation) |*pending| pending.dependencies.items = try a.dupe(
                state.Reference,
                pending.dependencies.items,
            );
            errdefer if (work.outer_operation) |pending| a.free(pending.dependencies.items);
            if (work.cancellation) |reason| work.cancellation = .{
                .bytes = try a.dupe(u8, reason.bytes),
            };
            errdefer if (work.cancellation) |reason| a.free(reason.bytes);
            if (work.guard) |guard| work.guard = try copyWorkspaceGuard(a, guard);
            errdefer if (work.guard) |guard| {
                if (guard.failure) |failure| a.free(failure.bytes);
                if (guard.reference_operation) |reference| a.free(reference.dependencies.items);
            };
            var pending: ?occurrence.Occurrence = null;
            if (work.current_occurrence) |id| {
                var decoded = try self.record(occurrence.Occurrence, a, "occurrence", id, task_id);
                defer decoded.deinit();
                pending = decoded.value;
            }
            return .{ .work = work, .occurrence = pending };
        }
        fn copyWorkspaceGuard(a: std.mem.Allocator, original: workspace.Guard) !workspace.Guard {
            var guard = original;
            if (guard.failure) |failure|
                guard.failure = .{ .bytes = try a.dupe(u8, failure.bytes) };
            errdefer if (guard.failure) |failure| a.free(failure.bytes);
            if (guard.reference_operation) |*pending|
                pending.dependencies.items = try a.dupe(
                    state.Reference,
                    pending.dependencies.items,
                );
            return guard;
        }
        fn workPublication(
            a: std.mem.Allocator,
            observed: workspace.WorkObservation,
        ) !state.WorkPublication {
            const bytes = try contracts.encodeOwned(workspace.WorkObservation, a, observed);
            defer a.free(bytes);
            return .{
                .observer = observed.work.observer,
                .work = observed.work.id,
                .execution_revision = observed.work.execution_revision,
                .control_revision = observed.work.control_revision,
                .runtime = observed.work.runtime,
                .realization_revision = observed.work.realization_revision,
                .runtime_capsule = observed.work.runtime_capsule,
                .runtime_trace = observed.work.runtime_trace != null,
                .outer_cursor = observed.work.outer_cursor,
                .guard = observed.work.guard,
                .guest_work = observed.work.guest_work,
                .outer_operation = if (observed.work.outer_operation) |pending|
                    pending.capsule
                else
                    null,
                .checkpoint = observed.work.checkpoint,
                .observation = storage.digest(bytes),
                .control = workspace.ControlObservation.from(observed),
            };
        }
        fn samePublication(
            a: std.mem.Allocator,
            declared: state.WorkPublication,
            observed: state.WorkPublication,
        ) !bool {
            const left = try contracts.encodeOwned(state.WorkPublication, a, declared);
            defer a.free(left);
            const right = try contracts.encodeOwned(state.WorkPublication, a, observed);
            defer a.free(right);
            return same(left, right);
        }
        fn publicationSchedule(value: workspace.ControlObservation) state.Schedule {
            if (value.outcome == .requested)
                return if ((value.cancellation != null and
                    !value.cancellation_applied) or
                    ((value.instrument or
                        value.trial) and
                        !value.port and
                        value.policy.continuation == .owner_scheduled)) .queued else .parked;
            if (value.outcome == .completed or
                value.outcome == .failed or
                value.outcome == .cancelled)
                return .parked;
            return if (value.cancellation != null or
                (value.policy.continuation == .owner_scheduled and
                    value.policy.stop != .next_slice and
                    (value.outcome != .yielded or
                        value.policy.stop == .terminal))) .queued else .parked;
        }
        fn delegatedControl(
            before: workspace.ControlObservation,
            has_outer: bool,
            guard: ?workspace.Guard,
            policy: workspace.RunPolicy,
        ) workspace.ControlObservation {
            var after = before;
            after.policy = policy;
            if (guard) |binding| if (binding.disposition == .diverged) {
                after.schedule = .parked;
                return after;
            };
            if (!has_outer and
                before.delivery == .not_sent and
                (before.instrument or
                    before.trial)) after.delivery = .ready;
            const cancel_ready = before.cancellation != null and !before.cancellation_applied and
                (after.delivery == .ready or
                    after.delivery == .awaiting or
                    after.delivery == .not_sent);
            const runnable = has_outer or
                after.delivery == null or
                after.delivery == .settled_reply or
                after.delivery == .captured or
                (after.delivery == .ready and (before.instrument or before.trial)) or cancel_ready;
            after.schedule =
                if (policy.continuation ==
                .explicit_only) .parked else if (after.delivery ==
                .dispatching) .active else if (runnable) .queued else .parked;
            return after;
        }
        fn workspaceInteractionReply(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            interaction: @FieldType(wc.Work, "interact"),
        ) !workspace.PortReply {
            var port = try self.record(
                workspace.Port,
                a,
                "workspace_port",
                try wp.identity(interaction.port, .port),
                task_id,
            );
            defer port.deinit();
            if (!std.meta.eql(port.value.task, task_id) or !std.meta.eql(
                port.value.work,
                try wp.identity(interaction.expected.work, .work),
            ) or
                port.value.generation != interaction.generation) return error.InvalidArchive;
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                port.value.occurrence,
                task_id,
            );
            defer pending.deinit();
            const acquired = switch (pending.value.state) {
                .settled_reply => |reply| reply,
                .admitted => |admitted| if (admitted ==
                    .reply) admitted.reply else return error.InvalidArchive,
                else => return error.InvalidArchive,
            };
            var saved = try self.record(
                workspace.PortReply,
                a,
                "workspace_port_reply",
                acquired.attempt,
                task_id,
            );
            defer saved.deinit();
            const reply = saved.value;
            const port_bytes = try contracts.encodeOwned(workspace.Port, a, port.value);
            defer a.free(port_bytes);
            if (!std.meta.eql(reply.task, task_id) or !std.meta.eql(reply.id, acquired.attempt) or
                !std.meta.eql(reply.reply.digest, acquired.reply) or
                !std.meta.eql(reply.port, state.Reference{
                    .digest = storage.digest(port_bytes),
                    .bytes = port_bytes.len,
                })) return error.InvalidArchive;
            try self.validateInteractionReplyCommand(
                a,
                task_id,
                interaction,
                reply,
                port.value.interface.argument,
            );

            return reply;
        }
        fn validateInteractionReplyCommand(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            interaction: @FieldType(wc.Work, "interact"),
            reply: workspace.PortReply,
            argument: state.Reference,
        ) !void {
            switch (interaction.command) {
                .finish => if (reply.command != .finish or
                    reply.input != null)
                    return error.InvalidArchive,
                .resume_value => |supplied| {
                    if (reply.command != .resume_value) return error.InvalidArchive;
                    const input = reply.input orelse return error.InvalidArchive;
                    const actual = try self.workspaceValueReference(
                        a,
                        task_id,
                        try wp.reference(a, .value, input.digest),
                    );
                    if (!std.meta.eql(actual.artifact, input) or !std.meta.eql(
                        actual.schema,
                        argument,
                    )) return error.InvalidArchive;
                    switch (supplied) {
                        .reference => |ref| {
                            const expected = try self.workspaceValueReference(a, task_id, ref);
                            if (!std.meta.eql(
                                expected.artifact,
                                input,
                            )) return error.InvalidArchive;
                        },
                        .inline_json => |inline_value| try self.validateInteractionInlineReply(
                            a,
                            inline_value,
                            actual,
                            argument,
                        ),
                    }
                },
            }
        }
        fn validateInteractionInlineReply(
            self: *Self,
            a: std.mem.Allocator,
            inline_value: @FieldType(wc.ValueInput, "inline_json"),
            actual: WorkspaceValueReference,
            argument: state.Reference,
        ) !void {
            if (!std.meta.eql(
                try wp.identity(inline_value.schema, .schema),
                argument.digest,
            )) return error.InvalidArchive;
            const descriptor = try self.store().object(a, argument, null);
            defer a.free(descriptor);
            const text = inline_value.json_text.bytes;
            var parsed = try json.parse(a, text, .{
                .bytes = text.len,
                .depth = text.len,
                .tokens = text.len,
                .members = text.len,
            });
            defer parsed.deinit();
            const bytes = try @import("dynamic_values.zig").encode(
                a,
                descriptor,
                parsed.value,
            );
            defer a.free(bytes);
            const provenance = try contracts.encodeOwned(
                workspace.Derivation,
                a,
                .{ .kind = .hypothesis, .sources = .{ .items = &.{} } },
            );
            defer a.free(provenance);
            if (!std.meta.eql(actual.value, state.Reference{
                .digest = storage.digest(bytes),
                .bytes = bytes.len,
            }) or
                !std.meta.eql(actual.provenance, state.Reference{
                    .digest = storage.digest(provenance),
                    .bytes = provenance.len,
                })) return error.InvalidArchive;
        }
        fn validateWorkspaceContextOutput(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            context: @FieldType(workspace.PublicationCommand, "context"),
            identity: state.Digest,
            event_seq: u64,
            controller_read: ?state.ControllerReadCut,
        ) !void {
            // Replay proves receipt stability only after admission. At the archive
            // boundary, derive the content relationship from the retained command.
            return (ContextOutputValidation{
                .self = self,
                .a = a,
                .parent = parent,
                .context = context,
                .identity = identity,
                .event_seq = event_seq,
                .controller_read = controller_read,
            }).run();
        }
        const ContextOutputValidation = contextOutputValidationType();
        fn contextOutputValidationType() type {
            return struct {
                self: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                context: @FieldType(workspace.PublicationCommand, "context"),
                identity: state.Digest,
                event_seq: u64,
                controller_read: ?state.ControllerReadCut,
                fn run(ctx: @This()) !void {
                    switch (ctx.context.command) {
                        .select => |selection| try ctx.select(selection),
                        .materialize => |materialize| try ctx.materializedOutput(materialize),
                        else => return error.InvalidArchive,
                    }
                }

                fn select(ctx: @This(), selection: @FieldType(wc.Context, "select")) !void {
                    const refs = try ctx.a.alloc(state.Reference, selection.values.items.len);
                    defer ctx.a.free(refs);
                    for (selection.values.items, refs) |ref, *out|
                        out.* =
                            (try ctx.self.workspaceValueReference(
                                ctx.a,
                                ctx.parent.id,
                                ref,
                            )).artifact;
                    const bytes = try contracts.encodeOwned(
                        workspace.ViewArtifact,
                        ctx.a,
                        .{ .values = .{ .items = refs } },
                    );
                    defer ctx.a.free(bytes);
                    if (!std.meta.eql(
                        storage.digest(bytes),
                        ctx.identity,
                    )) return error.InvalidArchive;
                }

                fn semanticSource(
                    ctx: @This(),
                    materialize: @FieldType(wc.Context, "materialize"),
                    selection: @FieldType(wc.Materialization, "semantic_source"),
                ) !void {
                    if (materialize.sources.items.len != 0) return error.InvalidArchive;
                    var retained = try ctx.self.record(
                        workspace.Value,
                        ctx.a,
                        "workspace_value",
                        try workspaceContentCustody(ctx.a, ctx.parent.id, ctx.identity),
                        ctx.parent.id,
                    );
                    defer retained.deinit();
                    const origin = retained.value.derivation.semantic_source orelse
                        return error.InvalidArchive;
                    const requested = try contracts.encodeOwned(
                        @TypeOf(selection),
                        ctx.a,
                        selection,
                    );
                    defer ctx.a.free(requested);
                    const actual_selection = try contracts.encodeOwned(
                        @TypeOf(selection),
                        ctx.a,
                        origin.selection,
                    );
                    defer ctx.a.free(actual_selection);
                    if (!same(requested, actual_selection)) return error.InvalidArchive;
                    try validateSemanticReadPosition(origin.basis, ctx.event_seq);
                    try validateControllerReadCut(origin.basis, ctx.controller_read);
                    return;
                }

                fn guestView(
                    ctx: @This(),
                    materialize: @FieldType(wc.Context, "materialize"),
                    selection: @FieldType(wc.Materialization, "guest_view"),
                ) !void {
                    if (materialize.sources.items.len != 0) return error.InvalidArchive;
                    var retained = try ctx.self.record(
                        workspace.Value,
                        ctx.a,
                        "workspace_value",
                        try workspaceContentCustody(ctx.a, ctx.parent.id, ctx.identity),
                        ctx.parent.id,
                    );
                    defer retained.deinit();
                    const origin = retained.value.derivation.inspection orelse
                        return error.InvalidArchive;
                    try inspectionSelection(origin.observation.work, selection);
                    if (origin.level != selection.level) return error.InvalidArchive;
                    if (origin.observation.work.event_watermark >= ctx.event_seq)
                        return error.InvalidArchive;
                    const requested_scope = try contracts.encodeOwned(struct {
                        nodes: wc.NodeScope,
                        values: ?wc.Disclosure,
                    }, ctx.a, .{ .nodes = selection.nodes, .values = selection.disclosure });
                    defer ctx.a.free(requested_scope);
                    const retained_scope = try contracts.encodeOwned(struct {
                        nodes: wc.NodeScope,
                        values: ?wc.Disclosure,
                    }, ctx.a, .{ .nodes = origin.nodes, .values = origin.disclosure });
                    defer ctx.a.free(retained_scope);
                    if (!same(requested_scope, retained_scope)) return error.InvalidArchive;
                    // Value access already reconstructs the exact bytes
                    // from the journal-bound observation and scope.
                    return;
                }

                fn inlineValue(
                    ctx: @This(),
                    inline_value: @FieldType(wc.ValueInput, "inline_json"),
                    schema: *state.Reference,
                    payload: *state.Reference,
                ) !void {
                    schema.* = try ctx.self.workspaceOwnedDescriptor(
                        ctx.a,
                        ctx.parent.id,
                        inline_value.schema,
                    );
                    const descriptor = try ctx.self.store().object(ctx.a, schema.*, null);
                    defer ctx.a.free(descriptor);
                    const text = inline_value.json_text.bytes;
                    var parsed = try json.parse(ctx.a, text, .{
                        .bytes = text.len,
                        .depth = text.len,
                        .tokens = text.len,
                        .members = text.len,
                    });
                    defer parsed.deinit();
                    const bytes = try @import("dynamic_values.zig").encode(
                        ctx.a,
                        descriptor,
                        parsed.value,
                    );
                    defer ctx.a.free(bytes);
                    payload.* = .{ .digest = storage.digest(bytes), .bytes = bytes.len };
                }

                fn value(
                    ctx: @This(),
                    materialize: @FieldType(wc.Context, "materialize"),
                    input: wc.ValueInput,
                    actual: WorkspaceValueReference,
                    schema: *state.Reference,
                    payload: *state.Reference,
                    derivation: *workspace.Derivation,
                    sources: *std.ArrayList(state.Reference),
                ) !bool {
                    for (materialize.sources.items) |ref| try sources.append(
                        ctx.a,
                        (try ctx.self.workspaceValueReference(ctx.a, ctx.parent.id, ref)).artifact,
                    );
                    switch (input) {
                        .reference => |ref| {
                            const origin = try ctx.self.workspaceValueReference(
                                ctx.a,
                                ctx.parent.id,
                                ref,
                            );
                            if (sources.items.len == 0) {
                                if (!std.meta.eql(
                                    origin.artifact,
                                    actual.artifact,
                                )) return error.InvalidArchive;
                                return false;
                            }
                            try sources.append(ctx.a, origin.artifact);
                            schema.* = origin.schema;
                            payload.* = origin.value;
                        },
                        .inline_json => |inline_value| try ctx.inlineValue(
                            inline_value,
                            schema,
                            payload,
                        ),
                    }
                    derivation.* = .{
                        .kind = if (sources.items.len == 0) .hypothesis else .judgment,
                        .sources = .{ .items = sources.items },
                    };

                    return true;
                }

                fn materializedOutput(
                    ctx: @This(),
                    materialize: @FieldType(wc.Context, "materialize"),
                ) !void {
                    const actual = try ctx.self.workspaceValueReference(
                        ctx.a,
                        ctx.parent.id,
                        try wp.reference(ctx.a, .value, ctx.identity),
                    );
                    var schema = actual.schema;
                    var payload = actual.value;
                    var derivation: workspace.Derivation = .{
                        .kind = .hypothesis,
                        .sources = .{ .items = &.{} },
                    };
                    var sources: std.ArrayList(state.Reference) = .empty;
                    defer sources.deinit(ctx.a);
                    switch (materialize.input) {
                        .semantic_source => |selection| return ctx.semanticSource(
                            materialize,
                            selection,
                        ),
                        .guest_view => |selection| return ctx.guestView(materialize, selection),
                        .authorized_input => {
                            if (materialize.sources.items.len != 0) return error.InvalidArchive;
                            const ref = ctx.context.input orelse return error.InvalidArchive;
                            try workspaceSnapshotAccess(ctx.parent, ref);
                            derivation = .{
                                .kind = .acquisition,
                                .sources = .{ .items = &.{} },
                                .frozen_input = ref,
                            };
                            // workspaceValueReference checks the actual schema
                            // and payload against this exact frozen input.
                        },
                        .snapshot => |selection| {
                            if (materialize.sources.items.len != 0) return error.InvalidArchive;
                            derivation = .{
                                .kind = .acquisition,
                                .sources = .{ .items = &.{} },
                                .acquisition = try ctx.self.workspaceSnapshotRange(
                                    ctx.a,
                                    ctx.parent,
                                    ctx.context.snapshot orelse return error.InvalidArchive,
                                    selection,
                                ),
                            };
                        },
                        .value => |input| if (!try ctx.value(
                            materialize,
                            input,
                            actual,
                            &schema,
                            &payload,
                            &derivation,
                            &sources,
                        )) return,
                    }
                    try ctx.materializedProvenance(actual, schema, payload, derivation);
                }
                fn materializedProvenance(
                    ctx: @This(),
                    actual: WorkspaceValueReference,
                    schema: state.Reference,
                    payload: state.Reference,
                    derivation: workspace.Derivation,
                ) !void {
                    const provenance = try contracts.encodeOwned(
                        workspace.Derivation,
                        ctx.a,
                        derivation,
                    );
                    defer ctx.a.free(provenance);
                    if (!std.meta.eql(actual.schema, schema) or
                        !std.meta.eql(actual.value, payload) or
                        !std.meta.eql(actual.provenance, state.Reference{
                            .digest = storage.digest(provenance),
                            .bytes = provenance.len,
                        })) return error.InvalidArchive;
                }
            };
        }
        fn validateWorkspaceAdmission(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            event_value: state.Event,
            command: workspace.PublicationCommand,
            admission: WorkspaceAdmission,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            // Validate the receipt's operation before interpreting any declared
            // publication. Neither the receipt kind nor an empty list can bypass it.
            return (PublicationAdmissionValidation{
                .self = self,
                .a = a,
                .parent = parent,
                .event_value = event_value,
                .command = command,
                .admission = admission,
                .records = records,
                .checked = checked,
            }).run();
        }
        const PublicationAdmissionValidation = publicationAdmissionValidationType();
        fn publicationAdmissionValidationType() type {
            return struct {
                self: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                event_value: state.Event,
                command: workspace.PublicationCommand,
                admission: WorkspaceAdmission,
                records: []const state.ArchiveRecord,
                checked: *SnapshotValidation,
                fn run(ctx: @This()) !void {
                    errdefer std.debug.print("workspace admission: {s} at {d}\n", .{
                        @tagName(ctx.command),
                        ctx.event_value.seq,
                    });
                    try ctx.publicationShape();
                    const request = switch (ctx.command) {
                        .realize_controller => |selection| try ctx.requestRealizeController(
                            selection,
                        ),
                        .stop_observing => |selection| try ctx.requestStopObserving(selection),
                        .semantic => |selected| try ctx.requestSemantic(selected),
                        .residual => |selection| try ctx.requestResidual(selection),
                        .specialize => |selection| try ctx.requestSpecialize(selection),
                        .realize => |selection| try ctx.requestRealize(selection),
                        .pump => |selection| try ctx.requestPump(selection),
                        .guard => |selection| try ctx.requestGuard(selection),
                        .unguard => |selection| try ctx.requestUnguard(selection),
                        .request_cut => |selection| try ctx.requestRequestCut(selection),
                        .build => try ctx.requestBuild(),
                        .context => |context| try ctx.requestContext(context),
                        .start => |start| try ctx.requestStart(start),
                        .control => |control| try ctx.requestControl(control),
                        .interact => |interaction| try ctx.requestInteract(interaction),
                        .delegate => |selection| try ctx.requestDelegate(selection),
                    };
                    if (!std.meta.eql(request, ctx.admission.request)) return error.InvalidArchive;
                }

                fn publicationShape(ctx: @This()) !void {
                    const items = ctx.event_value.workspace_publications.items;
                    const kind: @FieldType(wc.Ref, "kind") = switch (ctx.command) {
                        .build => .program,
                        .realize_controller => .controller,
                        .residual => .residual,
                        .specialize => .runtime,
                        .semantic => .candidate,
                        .context => |context| switch (context.command) {
                            .materialize => .value,
                            .select => .view,
                            else => return error.InvalidArchive,
                        },
                        else => .work,
                    };
                    if (ctx.admission.kind != kind) return error.InvalidArchive;
                    const count: usize = switch (ctx.command) {
                        .build,
                        .context,
                        .specialize,
                        .semantic,
                        .residual,
                        .realize_controller,
                        => 0,
                        .delegate => 2,
                        .start => |start| if (start.observer) |observer|
                            if (observer.selection.previous != null) 2 else 1
                        else
                            1,
                        else => 1,
                    };
                    if (items.len != count) return error.InvalidArchive;
                    if (count != 0 and !std.meta.eql(
                        items[0].work,
                        ctx.admission.work,
                    )) return error.InvalidArchive;
                }

                fn requestRealizeController(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "realize_controller"),
                ) !state.Digest {
                    try ctx.self.validateControllerRealization(
                        ctx.a,
                        ctx.parent,
                        ctx.event_value,
                        selection,
                        ctx.admission,
                    );
                    return try operation(workspace.ControllerRealizeRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = selection.command,
                    });
                }

                fn requestStopObserving(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "stop_observing"),
                ) !state.Digest {
                    return try operation(workspace.StopObservingRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .expected = selection,
                    });
                }

                fn requestSemantic(
                    ctx: @This(),
                    selected: @FieldType(workspace.PublicationCommand, "semantic"),
                ) !state.Digest {
                    try ctx.self.validateSemanticPublication(
                        ctx.parent,
                        selected,
                        ctx.admission,
                        ctx.records,
                        ctx.event_value.seq,
                        ctx.event_value.controller_read,
                        ctx.checked,
                    );
                    return try operation(workspace.SemanticRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = selected.command,
                    });
                }

                fn requestResidual(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "residual"),
                ) !state.Digest {
                    return try operation(workspace.ResidualControlRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .residual = ctx.admission.work,
                        .execution = selection.execution,
                        .control = selection.control,
                        .command = selection.command,
                    });
                }

                fn requestSpecialize(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "specialize"),
                ) !state.Digest {
                    var selected = try ctx.self.workspaceRuntime(
                        ctx.a,
                        ctx.parent.id,
                        ctx.admission.work,
                        selection.program,
                    );
                    defer selected.deinit();
                    const hooks = selected.admitted.content.value.hooks;
                    if (hooks.control != selection.hooks.control or
                        hooks.storage != selection.hooks.storage)
                        return error.InvalidArchive;
                    return try operation(workspace.SpecializeRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .program = selection.program,
                        .hooks = selection.hooks,
                    });
                }

                fn requestRealize(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "realize"),
                ) !state.Digest {
                    return try operation(workspace.RealizeRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .work = ctx.admission.work,
                        .execution = selection.execution,
                        .control = selection.control,
                        .realization = selection.realization,
                        .runtime = selection.runtime,
                    });
                }

                fn requestPump(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "pump"),
                ) !state.Digest {
                    if (!std.meta.eql(
                        try wp.identity(selection.expected.work, .work),
                        ctx.admission.work,
                    )) return error.InvalidArchive;
                    return try operation(workspace.PumpRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = selection,
                    });
                }

                fn requestGuard(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "guard"),
                ) !state.Digest {
                    return try operation(workspace.GuardRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = .{ .guard = selection },
                    });
                }

                fn requestUnguard(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "unguard"),
                ) !state.Digest {
                    return try operation(workspace.GuardRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = .{ .unguard = selection },
                    });
                }

                fn requestRequestCut(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "request_cut"),
                ) !state.Digest {
                    if (!std.meta.eql(
                        try wp.identity(selection.expected.work, .work),
                        ctx.admission.work,
                    )) return error.InvalidArchive;
                    return try operation(workspace.CutRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = selection,
                    });
                }

                fn requestBuild(ctx: @This()) !state.Digest {
                    var program = try ctx.self.workspaceProgram(
                        ctx.a,
                        ctx.parent.id,
                        ctx.admission.work,
                    );
                    defer program.deinit();
                    const artifact = program.value.description;
                    if (artifact.source_kind != .source_records and
                        artifact.source_kind != .component_recipe and
                        artifact.source_kind != .source_derivation)
                        return error.InvalidArchive;
                    return try operation(workspace.BuildRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .source = .{
                            .bytes = try ctx.self.store().object(ctx.a, artifact.source, null),
                        },
                        .source_kind = @fromBackingInt(@intCast(@backingInt(artifact.source_kind))),
                        .catalog = artifact.catalog,
                        .exposures = artifact.exposures,
                        .role = if (artifact.controller != null) .controller else .computation,
                    });
                }

                fn requestContext(
                    ctx: @This(),
                    context: @FieldType(workspace.PublicationCommand, "context"),
                ) !state.Digest {
                    try ctx.self.validateWorkspaceContextOutput(
                        ctx.a,
                        ctx.parent,
                        context,
                        ctx.admission.work,
                        ctx.event_value.seq,
                        ctx.event_value.controller_read,
                    );
                    return try operation(workspace.ContextRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = context.command,
                        .snapshot = context.snapshot,
                        .input = context.input,
                    });
                }

                fn requestStart(
                    ctx: @This(),
                    start: @FieldType(workspace.PublicationCommand, "start"),
                ) !state.Digest {
                    if (ctx.event_value.workspace_publications.items.len == 2) {
                        const previous = start.observer.?.selection.previous.?;
                        if (!std.meta.eql(
                            ctx.event_value.workspace_publications.items[1].work,
                            try wp.identity(previous, .work),
                        ) or
                            std.meta.eql(
                                ctx.event_value.workspace_publications.items[0].work,
                                ctx.event_value.workspace_publications.items[1].work,
                            )) return error.InvalidArchive;
                    }
                    var work = try ctx.self.retainedWorkspaceWork(
                        ctx.a,
                        ctx.parent.id,
                        ctx.admission.work,
                    );
                    defer work.deinit();
                    if ((start.trial == .none) != (work.value.trial == null))
                        return error.InvalidArchive;
                    if (work.value.trial) |id| try ctx.validateTrial(start.trial, id);

                    if (!start.origin) try ctx.self.validateWorkspaceInitialInput(
                        ctx.a,
                        work.value,
                        &ctx.checked.observer_successors,
                    );
                    if (start.observer) |observer| return try operation(
                        workspace.ObserveRequest,
                        ctx.a,
                        .{ .task = ctx.parent.id, .selection = observer.selection },
                    );
                    return try operation(workspace.StartRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .program = work.value.program,
                        .input = .{
                            .bytes = try ctx.self.store().object(ctx.a, work.value.input, null),
                        },
                        .policy = start.policy,
                        .origin = if (start.origin) work.value.input_value else null,
                        .runtime = start.runtime,
                        .trial = start.trial,
                    });
                }

                fn validateTrial(ctx: @This(), selection: wc.Trial, id: state.Digest) !void {
                    var trial = try ctx.self.record(
                        workspace.Trial,
                        ctx.a,
                        "workspace_trial",
                        id,
                        ctx.parent.id,
                    );
                    defer trial.deinit();
                    const selected = try contracts.encodeOwned(wc.Trial, ctx.a, selection);
                    defer ctx.a.free(selected);
                    const retained = try contracts.encodeOwned(
                        wc.Trial,
                        ctx.a,
                        trial.value.selection,
                    );
                    defer ctx.a.free(retained);
                    if (!same(selected, retained)) return error.InvalidArchive;
                    var view = try contracts.decodeOwned(
                        contracts.controller.OwnerView,
                        ctx.a,
                        try ctx.self.store().object(ctx.a, trial.value.view, null),
                    );
                    defer view.deinit();
                    if (ctx.event_value.seq == 0 or
                        view.value.event_cut != ctx.event_value.seq - 1)
                        return error.InvalidArchive;
                }
                fn requestControl(
                    ctx: @This(),
                    control: @FieldType(workspace.PublicationCommand, "control"),
                ) !state.Digest {
                    return try operation(workspace.ControlRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .work = ctx.admission.work,
                        .execution = control.execution,
                        .control = control.control,
                        .command = control.command,
                    });
                }

                fn requestInteract(
                    ctx: @This(),
                    interaction: @FieldType(workspace.PublicationCommand, "interact"),
                ) !state.Digest {
                    return try operation(workspace.InteractionRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .interaction = interaction,
                    });
                }

                fn requestDelegate(
                    ctx: @This(),
                    selection: @FieldType(workspace.PublicationCommand, "delegate"),
                ) !state.Digest {
                    const target = try wp.identity(selection.expected.work, .work);
                    if (!std.meta.eql(
                        ctx.event_value.workspace_publications.items[1].work,
                        target,
                    ) or
                        std.meta.eql(ctx.event_value.workspace_publications.items[0].work, target))
                        return error.InvalidArchive;
                    var child = try ctx.self.retainedWorkspaceWork(
                        ctx.a,
                        ctx.parent.id,
                        ctx.admission.work,
                    );
                    defer child.deinit();
                    try ctx.self.validateWorkspaceInitialInput(
                        ctx.a,
                        child.value,
                        &ctx.checked.observer_successors,
                    );
                    return try operation(workspace.DelegationRequest, ctx.a, .{
                        .task = ctx.parent.id,
                        .command = selection,
                    });
                }
            };
        }
        fn validateWorkspaceInitialInput(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            successors: *ObserverSuccessors,
        ) !void {
            // An originless admission derives this identity from the constructor;
            // equal schema/payload bytes do not authorize different ancestry.
            try self.validateObserver(a, work, successors);
            const ref = work.input_value orelse return error.InvalidArchive;
            const input = try self.workspaceValueReference(
                a,
                work.task,
                try wp.reference(a, .value, ref.digest),
            );
            const inputs = if (work.observer) |observer|
                &[_]state.Reference{ observer.source, observer.accumulator }
            else
                &.{};
            const provenance = try contracts.encodeOwned(workspace.Derivation, a, .{
                .kind = if (work.observer != null) .judgment else .hypothesis,
                .sources = .{ .items = inputs },
            });
            defer a.free(provenance);
            if (!std.meta.eql(input.provenance, state.Reference{
                .digest = storage.digest(provenance),
                .bytes = provenance.len,
            })) return error.InvalidArchive;
        }
        fn validateWorkspaceControl(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            event_value: state.Event,
            item: state.WorkPublication,
            prior: ?state.WorkPublication,
            command: ?workspace.PublicationCommand,
            admission: ?WorkspaceAdmission,
            outer_observed: bool,
            prefix: *@import("workspace_observers.zig").PublicationPrefix,
            histories: *ObserverHistories,
        ) !void {
            var validation = WorkspaceControlValidation{
                .self = self,
                .a = a,
                .parent = parent,
                .event_value = event_value,
                .item = item,
                .prior = prior,
                .command = command,
                .admission = admission,
                .outer_observed = outer_observed,
                .prefix = prefix,
                .histories = histories,
                .actual = item.control,
                .expected = item.control,
                .execution_changed = false,
                .guarded_progress = false,
                .observer_progress = false,
            };
            return validation.run();
        }
        const WorkspaceControlValidation = workspaceControlValidationType();
        fn workspaceControlValidationType() type {
            return struct {
                self: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                event_value: state.Event,
                item: state.WorkPublication,
                prior: ?state.WorkPublication,
                command: ?workspace.PublicationCommand,
                admission: ?WorkspaceAdmission,
                outer_observed: bool,
                prefix: *@import("workspace_observers.zig").PublicationPrefix,
                histories: *ObserverHistories,
                actual: workspace.ControlObservation,
                expected: workspace.ControlObservation,
                execution_changed: bool,
                guarded_progress: bool,
                observer_progress: bool,
                fn run(ctx: *@This()) !void {
                    if (try ctx.self.validateObserverSuccessionPublication(
                        ctx.a,
                        ctx.event_value,
                        ctx.item,
                        ctx.prior,
                        ctx.command,
                    )) return;

                    ctx.execution_changed =
                        if (ctx.prior) |before|
                            ctx.item.execution_revision !=
                                before.execution_revision
                        else
                            true;
                    try ctx.runtimeProgress();
                    try ctx.outerProgress();
                    if ((ctx.actual.outcome == .requested) != (ctx.actual.delivery != null) or
                        (ctx.actual.port and
                            ctx.actual.delivery == null))
                        return error.InvalidArchive;

                    try ctx.expectedInitial();
                    try validateGuardProgress(ctx.item, ctx.prior, ctx.command);
                    ctx.guarded_progress = if (ctx.prior) |before|
                        guardProgress(ctx.item, before)
                    else
                        false;
                    try validateObserverPublication(ctx.a, ctx.item, ctx.prior, ctx.command);
                    ctx.observer_progress = try ctx.self.validateObserverPreparationProgress(
                        ctx.a,
                        ctx.parent.id,
                        ctx.event_value.seq,
                        ctx.item,
                        ctx.prior,
                        ctx.command,
                        ctx.histories,
                    );
                    if (ctx.command) |decoded| try ctx.selectedCommand(
                        decoded,
                    ) else try ctx.spontaneous();

                    try ctx.equalObservation();
                    try ctx.self.validateWorkspaceGuestWork(
                        ctx.parent.id,
                        ctx.item,
                        ctx.prior,
                        ctx.command,
                        ctx.prefix,
                    );
                }

                fn runtimeProgress(ctx: *@This()) !void {
                    if (!ctx.execution_changed and ctx.item.guest_work != ctx.prior.?.guest_work)
                        return error.InvalidArchive;
                    if (ctx.execution_changed) {
                        var required = false;
                        if (ctx.item.runtime) |runtime| {
                            var selected = try ctx.self.workspaceRuntime(
                                ctx.a,
                                ctx.parent.id,
                                runtime.digest,
                                null,
                            );
                            defer selected.deinit();
                            required = selected.admitted.content.value.hooks.enabled();
                        }
                        if (ctx.item.runtime_trace != required) return error.InvalidArchive;
                    } else if (ctx.command != null and ctx.command.? == .realize) {
                        if (ctx.item.runtime_trace) return error.InvalidArchive;
                    } else if (ctx.item.runtime_trace != ctx.prior.?.runtime_trace)
                        return error.InvalidArchive;
                }

                fn outerProgress(ctx: *@This()) !void {
                    if (ctx.execution_changed and ctx.item.outer_operation != null)
                        return error.InvalidArchive;
                    if (ctx.item.outer_operation) |current_capsule| {
                        if (ctx.prior) |before| {
                            if (before.outer_operation) |previous_capsule| {
                                if (!std.meta.eql(current_capsule, previous_capsule)) {
                                    const before_bytes = try ctx.self.store().object(
                                        ctx.a,
                                        previous_capsule,
                                        null,
                                    );
                                    defer ctx.a.free(before_bytes);
                                    const after_bytes = try ctx.self.store().object(
                                        ctx.a,
                                        current_capsule,
                                        null,
                                    );
                                    defer ctx.a.free(after_bytes);
                                    var previous = try kosmos.RuntimeCapsule.read(
                                        ctx.a,
                                        before_bytes,
                                    );
                                    defer previous.deinit();
                                    var current = try kosmos.RuntimeCapsule.read(
                                        ctx.a,
                                        after_bytes,
                                    );
                                    defer current.deinit();
                                    if (current.value.record.outer_revision <=
                                        previous.value.record.outer_revision or
                                        current.value.record.guest_revision !=
                                            previous.value.record.guest_revision or
                                        !std.meta.eql(
                                            current.value.record.artifact,
                                            previous.value.record.artifact,
                                        ) or
                                        !same(
                                            current.value.command,
                                            previous.value.command,
                                        )) return error.InvalidArchive;
                                }
                            } else if (ctx.command == null or ctx.command.? != .pump)
                                return error.InvalidArchive;
                        } else return error.InvalidArchive;
                    } else if (!ctx.execution_changed and
                        ctx.prior != null and
                        ctx.prior.?.outer_operation != null)
                        return error.InvalidArchive;
                }

                fn expectedInitial(ctx: *@This()) !void {
                    if (ctx.prior) |before| {
                        if (ctx.command == null or ctx.command.? != .realize) {
                            if (!std.meta.eql(ctx.item.runtime, before.runtime) or
                                ctx.item.realization_revision != before.realization_revision)
                                return error.InvalidArchive;
                        }
                        if (ctx.item.execution_revision == before.execution_revision) {
                            if (!std.meta.eql(
                                ctx.item.checkpoint,
                                before.checkpoint,
                            )) return error.InvalidArchive;
                            const pumping = ctx.item.outer_operation != null and !std.meta.eql(
                                ctx.item.outer_operation,
                                before.outer_operation,
                            );
                            if (!pumping and
                                (ctx.command == null or
                                    (ctx.command.? != .realize and
                                        ctx.command.? != .request_cut)))
                                if (!std.meta.eql(
                                    ctx.item.runtime_capsule,
                                    before.runtime_capsule,
                                )) return error.InvalidArchive;
                        } else if (ctx.item.runtime_capsule != null and
                            !ctx.outer_observed)
                            return error.InvalidArchive;
                        ctx.expected.policy = before.control.policy;
                        ctx.expected.cancellation = before.control.cancellation;
                        ctx.expected.blocker = before.control.blocker;
                        if (ctx.execution_changed and ctx.expected.blocker == .observation_blocked)
                            ctx.expected.blocker = null;
                        ctx.expected.schedule = before.control.schedule;
                        if (ctx.actual.instrument != before.control.instrument or
                            ctx.actual.trial != before.control.trial)
                            return error.InvalidArchive;
                        if (ctx.item.execution_revision == before.execution_revision and
                            (ctx.actual.outcome != before.control.outcome or
                                ctx.actual.port != before.control.port or
                                ctx.actual.cancellation_applied !=
                                    before.control.cancellation_applied))
                            return error.InvalidArchive;
                    } else {
                        if (ctx.item.execution_revision != 1 or
                            ctx.item.control_revision != 1 or
                            ctx.command == null)
                            return error.InvalidArchive;
                        if (ctx.item.realization_revision != 0 or
                            ctx.item.runtime_capsule != null)
                            return error.InvalidArchive;
                        ctx.expected.cancellation = null;
                        ctx.expected.blocker = null;
                        if (ctx.actual.cancellation_applied) return error.InvalidArchive;
                    }
                }

                fn commandDelegate(
                    ctx: *@This(),
                    selection: @FieldType(workspace.PublicationCommand, "delegate"),
                ) !void {
                    if (selection.interpretation == .none) return error.InvalidArchive;
                    const target = try wp.identity(selection.expected.work, .work);
                    if (std.meta.eql(ctx.item.work, target)) {
                        const before = ctx.prior orelse return error.InvalidArchive;
                        if (selection.expected.execution_revision != before.execution_revision or
                            selection.expected.control_revision != before.control_revision or
                            ctx.item.execution_revision != before.execution_revision or
                            ctx.item.control_revision -| before.control_revision != 1 or
                            ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                        ctx.expected.policy = selection.policy;
                        ctx.expected.schedule = .parked;
                    } else {
                        if (ctx.prior != null or !ctx.actual.instrument or !std.meta.eql(
                            (ctx.admission orelse return error.InvalidArchive).work,
                            ctx.item.work,
                        )) return error.InvalidArchive;
                        if (ctx.item.runtime != null) return error.InvalidArchive;
                        ctx.expected.policy = .{
                            .stop = .terminal,
                            .continuation = .owner_scheduled,
                        };
                        ctx.expected.schedule = publicationSchedule(ctx.expected);
                    }
                }

                fn commandInteract(
                    ctx: *@This(),
                    interaction: @FieldType(workspace.PublicationCommand, "interact"),
                ) !void {
                    const before = ctx.prior orelse return error.InvalidArchive;
                    if (!std.meta.eql(
                        try wp.identity(interaction.expected.work, .work),
                        ctx.item.work,
                    ) or
                        interaction.expected.execution_revision != before.execution_revision or
                        interaction.expected.control_revision != before.control_revision or
                        ctx.item.execution_revision != before.execution_revision or
                        ctx.item.control_revision -| before.control_revision != 1 or
                        ctx.actual.delivery != .settled_reply) return error.InvalidArchive;
                    ctx.expected.schedule = .queued;
                }

                fn commandControl(
                    ctx: *@This(),
                    control: @FieldType(workspace.PublicationCommand, "control"),
                ) !void {
                    const before = ctx.prior orelse return error.InvalidArchive;
                    if (control.execution != before.execution_revision or
                        control.control != before.control_revision)
                        return error.InvalidArchive;
                    if (before.control.outcome == .completed or
                        before.control.outcome == .failed or
                        before.control.outcome == .cancelled)
                        return error.InvalidArchive;
                    const advanced = ctx.item.execution_revision > before.execution_revision;
                    if (control.command == .advance) {
                        try ctx.advanceControl(before, advanced);
                    } else {
                        if (ctx.item.control_revision -| before.control_revision != 1)
                            return error.InvalidArchive;
                        try ctx.changeControl(before, advanced, control);
                    }
                }

                fn commandStart(
                    ctx: *@This(),
                    start: @FieldType(workspace.PublicationCommand, "start"),
                ) !void {
                    if (ctx.prior != null or ctx.actual.instrument) return error.InvalidArchive;
                    if (!std.meta.eql(ctx.item.runtime, start.runtime)) return error.InvalidArchive;
                    ctx.expected.policy = start.policy;
                    ctx.expected.schedule = publicationSchedule(ctx.expected);
                }

                fn commandRequestCut(
                    ctx: *@This(),
                    selection: @FieldType(workspace.PublicationCommand, "request_cut"),
                ) !void {
                    const before = ctx.prior orelse return error.InvalidArchive;
                    if (selection.expected.execution_revision != before.execution_revision or
                        selection.expected.control_revision != before.control_revision or
                        !std.meta.eql(
                            try wp.identity(selection.expected.work, .work),
                            ctx.item.work,
                        ) or
                        ctx.item.execution_revision != before.execution_revision or
                        ctx.item.control_revision -| before.control_revision != 1 or
                        ctx.actual.delivery == .dispatching or
                        ctx.actual.delivery == .unknown or
                        ctx.actual.delivery != before.control.delivery or
                        ctx.item.runtime_capsule == null)
                        return error.InvalidArchive;
                    const capsule_bytes = try ctx.self.store().object(
                        ctx.a,
                        ctx.item.runtime_capsule.?,
                        null,
                    );
                    defer ctx.a.free(capsule_bytes);
                    var capsule = try kosmos.RuntimeCapsule.read(ctx.a, capsule_bytes);
                    defer capsule.deinit();
                    if (!same(
                        @tagName(capsule.value.record.kind),
                        @tagName(selection.level),
                    )) return error.InvalidArchive;
                }

                fn commandPump(
                    ctx: *@This(),
                    selection: @FieldType(workspace.PublicationCommand, "pump"),
                ) !void {
                    const before = ctx.prior orelse return error.InvalidArchive;
                    if (selection.expected.execution_revision != before.execution_revision or
                        selection.expected.control_revision != before.control_revision or
                        !std.meta.eql(
                            try wp.identity(selection.expected.work, .work),
                            ctx.item.work,
                        ) or ctx.item.control_revision -| before.control_revision != 1 or
                        selection.base_quantum == 0 or
                        selection.base_quantum > 1048576)
                        return error.InvalidArchive;
                    if (ctx.execution_changed) {
                        ctx.expected.schedule = publicationSchedule(ctx.expected);
                    } else if (ctx.guarded_progress) {
                        if (ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                        ctx.expected.schedule = guardSchedule(
                            ctx.item.guard.?,
                            ctx.expected.policy,
                        );
                    } else if (before.outer_operation == null and trialControlReady(
                        before.control,
                    )) {
                        if (ctx.item.outer_operation != null or
                            ctx.actual.delivery != .ready)
                            return error.InvalidArchive;
                        ctx.expected.delivery = .ready;
                        ctx.expected.schedule = .queued;
                        ctx.expected.blocker = null;
                    } else {
                        if (ctx.item.outer_operation == null or
                            ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                        ctx.expected.schedule = if (ctx.expected.cancellation != null or
                            ctx.expected.policy.continuation == .owner_scheduled)
                            .queued
                        else
                            .parked;
                    }
                }

                fn commandRealize(
                    ctx: *@This(),
                    selection: @FieldType(workspace.PublicationCommand, "realize"),
                ) !void {
                    const before = ctx.prior orelse return error.InvalidArchive;
                    if (before.outer_operation != null or
                        selection.execution != before.execution_revision or
                        selection.control != before.control_revision or
                        selection.realization != before.realization_revision or
                        ctx.item.execution_revision != before.execution_revision or
                        ctx.item.control_revision -| before.control_revision != 1 or
                        ctx.item.realization_revision -| before.realization_revision != 1 or
                        !std.meta.eql(ctx.item.runtime, selection.runtime) or
                        !std.meta.eql(ctx.item.runtime_capsule, selection.target) or
                        ctx.actual.delivery == .dispatching or
                        ctx.actual.delivery == .unknown or
                        ctx.actual.delivery != before.control.delivery)
                        return error.InvalidArchive;
                    try ctx.self.validateRuntimeSwitch(
                        ctx.a,
                        ctx.parent.id,
                        ctx.item,
                        before,
                        selection,
                    );
                }

                fn commandGuard(ctx: *@This(), decoded: workspace.PublicationCommand) !void {
                    const before = ctx.prior orelse return error.InvalidArchive;
                    try validateGuardSelection(ctx.item, before, decoded);
                }

                fn spontaneous(ctx: *@This()) !void {
                    const before = ctx.prior orelse return error.InvalidArchive;
                    if (ctx.item.execution_revision > before.execution_revision) {
                        if (ctx.item.control_revision != before.control_revision)
                            return error.InvalidArchive;
                        ctx.expected.schedule = publicationSchedule(ctx.expected);
                    } else if (ctx.guarded_progress) {
                        if (ctx.item.control_revision != before.control_revision or
                            ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                        ctx.expected.schedule = guardSchedule(
                            ctx.item.guard.?,
                            ctx.expected.policy,
                        );
                    } else if (ctx.item.outer_operation != null and
                        before.outer_operation != null and
                        ctx.item.control_revision == before.control_revision)
                    {
                        if (ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                        ctx.expected.schedule = if (ctx.expected.cancellation != null or
                            ctx.expected.policy.continuation == .owner_scheduled)
                            .queued
                        else
                            .parked;
                    } else if (ctx.observer_progress) {
                        if (ctx.item.control_revision != before.control_revision or
                            ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                    } else if (ctx.item.control_revision > before.control_revision) {
                        if (ctx.item.execution_revision != before.execution_revision or
                            !try ctx.self.workspaceStoppedAt(
                                ctx.a,
                                ctx.parent.id,
                                ctx.event_value.seq - 1,
                            ) or ctx.actual.delivery !=
                            before.control.delivery) return error.InvalidArchive;
                        ctx.expected.schedule = .parked;
                    } else {
                        try ctx.deliveryProgress(before);
                    }
                }

                fn selectedCommand(ctx: *@This(), decoded: workspace.PublicationCommand) !void {
                    switch (decoded) {
                        .stop_observing => {},
                        .build,
                        .context,
                        .specialize,
                        .semantic,
                        .residual,
                        .realize_controller,
                        => return error.InvalidArchive,
                        .guard, .unguard => try ctx.commandGuard(decoded),
                        .realize => |selection| try ctx.commandRealize(selection),
                        .pump => |selection| try ctx.commandPump(selection),
                        .request_cut => |selection| try ctx.commandRequestCut(selection),
                        .start => |start| try ctx.commandStart(start),
                        .control => |control| try ctx.commandControl(control),
                        .interact => |interaction| try ctx.commandInteract(interaction),
                        .delegate => |selection| try ctx.commandDelegate(selection),
                    }
                }

                fn equalObservation(ctx: *@This()) !void {
                    const expected_bytes = try contracts.encodeOwned(
                        workspace.ControlObservation,
                        ctx.a,
                        ctx.expected,
                    );
                    defer ctx.a.free(expected_bytes);
                    const actual_bytes = try contracts.encodeOwned(
                        workspace.ControlObservation,
                        ctx.a,
                        ctx.actual,
                    );
                    defer ctx.a.free(actual_bytes);
                    if (!same(expected_bytes, actual_bytes)) return error.InvalidArchive;
                }
                fn advanceControl(
                    ctx: *@This(),
                    before: state.WorkPublication,
                    advanced: bool,
                ) !void {
                    if (!advanced and ctx.guarded_progress) {
                        if (ctx.item.control_revision != before.control_revision or
                            ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                        ctx.expected.schedule = guardSchedule(
                            ctx.item.guard.?,
                            ctx.expected.policy,
                        );
                    } else if (!advanced and
                        before.outer_operation == null and
                        trialControlReady(before.control))
                    {
                        if (ctx.item.control_revision -| before.control_revision != 1 or
                            ctx.item.outer_operation != null or
                            ctx.actual.delivery != .ready)
                            return error.InvalidArchive;
                        ctx.expected.delivery = .ready;
                        ctx.expected.schedule = .queued;
                        ctx.expected.blocker = null;
                    } else if (advanced) {
                        if (ctx.item.control_revision != before.control_revision)
                            return error.InvalidArchive;
                        ctx.expected.schedule = publicationSchedule(ctx.expected);
                    } else {
                        if (ctx.item.control_revision != before.control_revision or
                            before.outer_operation == null or
                            ctx.item.outer_operation == null or
                            ctx.actual.delivery != before.control.delivery)
                            return error.InvalidArchive;
                        ctx.expected.schedule = if (ctx.expected.cancellation != null or
                            ctx.expected.policy.continuation ==
                                .owner_scheduled) .queued else .parked;
                    }
                }
                fn changeControl(
                    ctx: *@This(),
                    before: state.WorkPublication,
                    advanced: bool,
                    control: @FieldType(workspace.PublicationCommand, "control"),
                ) !void {
                    switch (control.command) {
                        .park => {
                            if (advanced or
                                ctx.actual.delivery != before.control.delivery)
                                return error.InvalidArchive;
                            ctx.expected.schedule = .parked;
                        },
                        .delegate => |policy| {
                            if (advanced) return error.InvalidArchive;
                            const delegated = delegatedControl(
                                before.control,
                                before.outer_operation != null,
                                before.guard,
                                policy,
                            );
                            ctx.expected.policy = delegated.policy;
                            ctx.expected.delivery = delegated.delivery;
                            ctx.expected.schedule = delegated.schedule;
                        },
                        .cancel => |reason| {
                            if (ctx.expected.cancellation == null)
                                ctx.expected.cancellation = reason;
                            if (advanced) {
                                ctx.expected.schedule = publicationSchedule(ctx.expected);
                            } else if (ctx.actual.blocker == .observation_blocked) {
                                if (ctx.actual.delivery != before.control.delivery or
                                    !std.meta.eql(ctx.item.outer_operation, before.outer_operation))
                                    return error.InvalidArchive;
                                if (!try observationBlockedAt(
                                    before,
                                    ctx.prefix,
                                )) return error.InvalidArchive;
                                ctx.expected.schedule = .queued;
                                ctx.expected.blocker = .observation_blocked;
                            } else {
                                if (ctx.actual.delivery != before.control.delivery)
                                    return error.InvalidArchive;
                                ctx.expected.schedule =
                                    if (ctx.item.outer_operation !=
                                    null) .queued else switch (ctx.actual.delivery orelse
                                    return error.InvalidArchive) {
                                        .dispatching => .active,
                                        .captured => .queued,
                                        .unknown => .parked,
                                        else => return error.InvalidArchive,
                                    };
                            }
                        },
                        .advance => unreachable,
                    }
                }
                fn deliveryProgress(ctx: *@This(), before: state.WorkPublication) !void {
                    if (ctx.item.execution_revision != before.execution_revision or
                        ctx.item.control_revision != before.control_revision or
                        ctx.actual.delivery == null)
                        return error.InvalidArchive;
                    if (ctx.actual.delivery == .settled_reply and
                        before.control.delivery == .settled_reply and
                        before.control.trial and
                        before.control.policy.continuation == .explicit_only and
                        before.control.cancellation == null)
                    {
                        ctx.expected.schedule = .parked;
                    } else if (ctx.actual.delivery == before.control.delivery and
                        ctx.actual.blocker != null)
                    {
                        // A dispatch/interpretation rejection records an actual
                        // environmental diagnostic, not an execution result.
                        if (ctx.actual.delivery != .ready and
                            ctx.actual.delivery != .captured and
                            ctx.actual.delivery != .unknown)
                            return error.InvalidArchive;
                        ctx.expected.blocker = ctx.actual.blocker;
                        ctx.expected.schedule = .parked;
                    } else switch (ctx.actual.delivery.?) {
                        .dispatching => {
                            ctx.expected.schedule = .active;
                            ctx.expected.blocker = null;
                        },
                        .captured, .settled_reply => {
                            ctx.expected.schedule =
                                if (before.control.schedule ==
                                .parked) .parked else .queued;
                            ctx.expected.blocker = null;
                        },
                        .unknown => {
                            ctx.expected.schedule = .parked;
                            ctx.expected.blocker = .unavailable_environment;
                        },
                        .not_sent => {
                            const cancelling = ctx.actual.cancellation != null and
                                !ctx.actual.cancellation_applied;
                            ctx.expected.schedule = if (cancelling and
                                before.control.schedule != .parked) .queued else .parked;
                            ctx.expected.blocker =
                                if (cancelling) null else .unavailable_environment;
                        },
                        else => return error.InvalidArchive,
                    }
                }
            };
        }
        fn validateWorkspaceGuestWork(
            self: *Self,
            task_id: state.TaskId,
            item: state.WorkPublication,
            prior: ?state.WorkPublication,
            command: ?workspace.PublicationCommand,
            prefix: *const @import("workspace_observers.zig").PublicationPrefix,
        ) !void {
            var validation = GuestWorkValidation{
                .self = self,
                .task_id = task_id,
                .item = item,
                .prior = prior,
                .command = command,
                .prefix = prefix,
                .a = undefined,
                .work = undefined,
                .control = .none,
                .quantum = 256,
                .frozen_control = null,
                .initial_checkpoint = null,
            };
            return validation.run();
        }
        const GuestWorkValidation = guestWorkValidationType();
        fn guestWorkValidationType() type {
            return struct {
                self: *Self,
                task_id: state.TaskId,
                item: state.WorkPublication,
                prior: ?state.WorkPublication,
                command: ?workspace.PublicationCommand,
                prefix: *const @import("workspace_observers.zig").PublicationPrefix,
                a: std.mem.Allocator,
                work: workspace.Work,
                control: data.invocation.Control,
                quantum: u64,
                frozen_control: ?contracts.Decoded(data.invocation.Control),
                initial_checkpoint: ?[]const u8,
                fn run(ctx: *@This()) !void {
                    const advanced =
                        if (ctx.prior) |before|
                            ctx.item.execution_revision !=
                                before.execution_revision
                        else
                            true;
                    const pending = ctx.item.outer_operation != null or
                        if (ctx.item.guard) |guard| guard.pending_control != null else false;
                    if (!advanced and !pending) return;
                    var arena = std.heap.ArenaAllocator.init(ctx.self.allocator);
                    defer arena.deinit();
                    ctx.a = arena.allocator();
                    var observed = try contracts.decodeOwned(
                        workspace.WorkObservation,
                        ctx.a,
                        try ctx.self.store().acquiredObject(ctx.a, ctx.item.observation, null),
                    );
                    defer observed.deinit();
                    ctx.work = observed.value.work;
                    if (!std.meta.eql(ctx.work.task, ctx.task_id) or
                        !try samePublication(
                            ctx.a,
                            ctx.item,
                            try workPublication(ctx.a, observed.value),
                        ))
                        return error.InvalidArchive;
                    try ctx.identity();
                    defer if (ctx.frozen_control) |*decoded| decoded.deinit();

                    if (ctx.prior) |before| try ctx.initialControl(before);
                    if (ctx.quantum > 256) return error.InvalidArchive;
                    const encoded_control = try contracts.encodeOwned(
                        data.invocation.Control,
                        ctx.a,
                        ctx.control,
                    );
                    if (ctx.work.outer_operation) |operation_value| {
                        const retained = try ctx.self.store().object(
                            ctx.a,
                            operation_value.control,
                            null,
                        );
                        if (operation_value.guest_quantum != ctx.quantum or !same(
                            retained,
                            encoded_control,
                        ))
                            return error.InvalidArchive;
                    }
                    if (ctx.work.guard) |guard| if (guard.pending_control) |ref| {
                        const retained = try ctx.self.store().object(ctx.a, ref, null);
                        if (guard.guest_quantum != ctx.quantum or !same(retained, encoded_control))
                            return error.InvalidArchive;
                    };
                    if (!advanced) return;
                    try ctx.validateExecution(encoded_control);
                }

                fn identity(ctx: *@This()) !void {
                    var current = try ctx.self.workspaceWork(ctx.a, ctx.task_id, ctx.item.work);
                    defer current.deinit();
                    inline for (.{
                        "program",
                        "input",
                        "input_value",
                        "origin_work",
                        "delegation",
                        "trial",
                    }) |field|
                        if (!std.meta.eql(
                            @field(ctx.work, field),
                            @field(current.value, field),
                        )) return error.InvalidArchive;
                }

                fn initialControl(ctx: *@This(), before: state.WorkPublication) !void {
                    ctx.initial_checkpoint = try ctx.self.store().object(
                        ctx.a,
                        before.checkpoint orelse return error.InvalidArchive,
                        null,
                    );
                    ctx.quantum = ctx.prefix.guestQuantum(ctx.item.work);
                    var initial = try contracts.decodeOwned(
                        workspace.WorkObservation,
                        ctx.a,
                        try ctx.self.store().acquiredObject(ctx.a, before.observation, null),
                    );
                    defer initial.deinit();
                    if (!try samePublication(
                        ctx.a,
                        before,
                        try workPublication(ctx.a, initial.value),
                    ))
                        return error.InvalidArchive;
                    const cancellation = ctx.item.control.cancellation;
                    const cancel_requested = if (ctx.command) |selected|
                        selected == .control and selected.control.command == .cancel
                    else
                        false;
                    if (before.control.delivery == .settled_reply) {
                        try ctx.self.validateHistoricalOccurrence(ctx.a, initial.value);
                        const acquired = initial.value.occurrence orelse
                            return error.InvalidArchive;
                        const reply = switch (acquired.state) {
                            .settled_reply => |value| value.reply,
                            .admitted => |value| if (value ==
                                .reply) value.reply.reply else return error.InvalidArchive,
                            else => return error.InvalidArchive,
                        };
                        ctx.control = .{
                            .reply = try ctx.self.store().acquiredObject(ctx.a, reply, null),
                        };
                        if (cancellation != null and !before.control.cancellation_applied) {
                            ctx.quantum = 0;
                        }
                    } else if (cancellation != null and
                        (!before.control.cancellation_applied or cancel_requested))
                    {
                        ctx.control = .{ .cancel = .{ .text = cancellation.?.bytes } };
                    } else if (before.control.outcome == .yielded) ctx.control = .resume_yield;
                    if (initial.value.work.outer_operation) |operation_value| {
                        ctx.quantum = operation_value.guest_quantum;
                        ctx.frozen_control = try contracts.decodeOwned(
                            data.invocation.Control,
                            ctx.a,
                            try ctx.self.store().object(ctx.a, operation_value.control, null),
                        );
                        ctx.control = ctx.frozen_control.?.value;
                    } else if (cancellation ==
                        null)
                        if (before.guard) |guard|
                            if (guard.pending_control) |ref| {
                                ctx.frozen_control = try contracts.decodeOwned(
                                    data.invocation.Control,
                                    ctx.a,
                                    try ctx.self.store().object(ctx.a, ref, null),
                                );
                                ctx.control = ctx.frozen_control.?.value;
                                ctx.quantum = guard.guest_quantum;
                            };
                }

                fn replay(ctx: *@This(), prepared: *kosmos.Prepared, fact_key: state.Digest) !void {
                    var execution = if (ctx.initial_checkpoint) |checkpoint|
                        try kosmos.Session.restore(ctx.self.allocator, prepared, checkpoint)
                    else
                        try kosmos.Session.start(
                            ctx.self.allocator,
                            prepared,
                            try ctx.self.store().object(ctx.a, ctx.work.input, null),
                        );
                    defer execution.deinit();
                    _ = try kosmos.invocation.advance(&execution, ctx.control, ctx.quantum);
                    if (execution.transitions != ctx.item.guest_work) return error.InvalidArchive;
                    var finished = try kosmos.invocation.finishPublication(
                        ctx.a,
                        &execution,
                        .receipt,
                        null,
                    );
                    defer finished.outcome.deinit();
                    defer ctx.self.allocator.free(finished.checkpoint.?);
                    const outcome = try data.invocation.encodeOwned(
                        data.invocation.Outcome,
                        ctx.a,
                        finished.outcome.record,
                    );
                    const expected_checkpoint = ctx.item.checkpoint orelse
                        return error.InvalidArchive;
                    if (!std.meta.eql(
                        storage.digest(finished.checkpoint.?),
                        expected_checkpoint.digest,
                    ) or
                        finished.checkpoint.?.len != expected_checkpoint.bytes or
                        !std.meta.eql(
                            storage.digest(outcome),
                            ctx.work.outcome.digest,
                        ) or outcome.len != ctx.work.outcome.bytes)
                        return error.InvalidArchive;
                    guest_segment_proofs.retain(fact_key);
                }

                fn validateExecution(ctx: *@This(), encoded_control: []const u8) !void {
                    var program = try ctx.self.workspaceProgram(
                        ctx.a,
                        ctx.task_id,
                        ctx.work.program,
                    );
                    defer program.deinit();
                    var packaged = try ctx.self.program.retainRuntime();
                    defer packaged.deinit();
                    const input_reference = if (ctx.prior) |before|
                        before.checkpoint.?
                    else
                        ctx.work.input;
                    const segment_fact = try guestSegmentFact(.{
                        .input = .{
                            .digest = input_reference.digest,
                            .bytes = input_reference.bytes,
                        },
                        .image = .{
                            .digest = program.value.description.image.digest,
                            .bytes = program.value.description.image.bytes,
                        },
                        .runtime = if (ctx.work.runtime) |runtime|
                            runtime.digest
                        else
                            packaged.identity,
                        .initial = ctx.prior == null,
                        .control = storage.digest(encoded_control),
                        .quantum = ctx.quantum,
                    }, ctx.work);
                    var prepared = try ctx.self.inspectionRuntime(ctx.self.allocator, ctx.work);
                    defer prepared.deinit();
                    const fact_key = try guestSegmentKey(segment_fact);
                    if (try ctx.self.validatedGuestSegment(
                        fact_key,
                        segment_fact,
                        ctx.work.outcome,
                    )) return;
                    try ctx.replay(&prepared, fact_key);
                }
            };
        }
        fn guestSegmentFact(
            segment: evaluator.Driver.Segment,
            work: workspace.Work,
        ) !CompilerFact {
            var hash = std.crypto.hash.sha2.Sha256.init(.{});
            var writer: data.wire.Writer = .{ .hasher = &hash };
            try data.record.write(struct {
                execution: evaluator.Driver.Segment,
                guest_work: u64,
                outcome: state.Reference,
            }, .{
                .execution = segment,
                .guest_work = work.guest_work,
                .outcome = work.outcome,
            }, &writer);
            return .{
                .kind = .guest_segment,
                .input = .{ .digest = segment.input.digest, .bytes = segment.input.bytes },
                .output = work.checkpoint,
                .context = hash.finalResult(),
            };
        }
        fn guestSegmentKey(fact: CompilerFact) !state.Digest {
            var hash = std.crypto.hash.sha2.Sha256.init(.{});
            var writer: data.wire.Writer = .{ .hasher = &hash };
            try data.record.write(CompilerFact, fact, &writer);
            return hash.finalResult();
        }
        fn validatedGuestSegment(
            self: *Self,
            key: state.Digest,
            fact: CompilerFact,
            outcome: state.Reference,
        ) !bool {
            if (!guest_segment_proofs.contains(key)) return false;
            try self.store().objectRange(fact.input, 0, &.{});
            try self.store().objectRange(fact.output, 0, &.{});
            try self.store().objectRange(outcome, 0, &.{});
            return true;
        }
        fn workspacePublicationAt(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
            watermark: u64,
        ) !u64 {
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq DESC",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(i64, watermark) orelse return error.InvalidArchive,
                } },
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer saved.deinit();
                for (saved.value.workspace_publications.items) |item| if (std.meta.eql(
                    item.work,
                    id,
                )) return saved.value.seq;
            }
            return error.InvalidArchive;
        }
        fn residualPublicationAt(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            id: state.Digest,
            watermark: u64,
        ) !state.ControllerResidualObservation {
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq DESC",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(i64, watermark) orelse return error.InvalidArchive,
                } },
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer saved.deinit();
                for (saved.value.residual_publications.items) |item| if (std.meta.eql(
                    item.value.id,
                    id,
                )) return item.value;
            }
            return error.InvalidArchive;
        }
        fn residualWaitReadyAt(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            watermark: u64,
        ) !bool {
            var waiting = try self.record(workspace.Wait, a, "workspace_wait", id, parent.id);
            defer waiting.deinit();
            if (try self.workspaceInterruptedAt(a, parent.id, watermark)) return true;
            for (waiting.value.selection.works.items) |ref| {
                const work = try wp.identity(ref, .work);
                const seq = try self.workspacePublicationAt(a, parent.id, work, watermark);
                if (seq > waiting.value.selection.after) return true;
                var query = try self.store().database.prepare(
                    "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                        "ERE e.task=? AND e.seq=?",
                    &.{ .{ .blob = &parent.id }, .{ .integer = @intCast(seq) } },
                );
                defer query.deinit();
                if (try query.step() != .row) return error.InvalidArchive;
                var saved = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer saved.deinit();
                for (saved.value.workspace_publications.items) |item| if (std.meta.eql(
                    item.work,
                    work,
                )) {
                    if (item.control.outcome == .completed or
                        item.control.outcome == .failed or
                        item.control.outcome == .cancelled)
                        return true;
                };
            }
            return false;
        }
        fn residualRecoveryAt(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
            revision: u64,
        ) !bool {
            var query = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='reconciliation'",
                &.{.{ .blob = &parent.id }},
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(state.Reconciliation, a, try query.bytes(0));
                defer saved.deinit();
                if (saved.value.admission_revision == revision and std.meta.eql(
                    saved.value.occurrence,
                    id,
                ) and saved.value.owner_epoch != null) return true;
            }
            return false;
        }
        fn residualRecoveredAt(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            revision: u64,
        ) !bool {
            const attempt = switch (pending.state) {
                .captured, .not_sent => |value| value.id,
                .settled_reply => |value| value.attempt,
                else => return error.InvalidArchive,
            };
            var query = try self.store().database.prepare(
                "SELECT o.body FROM records r JOIN objects o ON o.digest=r.body W" ++
                    "HERE r.task=? AND r.kind='reconciliation'",
                &.{.{ .blob = &parent.id }},
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var saved = try contracts.decodeOwned(state.Reconciliation, a, try query.bytes(0));
                defer saved.deinit();
                const value = saved.value;
                if (!std.meta.eql(value.occurrence, pending.id) or !std.meta.eql(
                    value.attempt,
                    attempt,
                ) or value.admission_revision > revision) continue;
                const matches = switch (pending.state) {
                    .captured => blk: {
                        if (value.outcome == .capture_admitted) break :blk true;
                        if (value.outcome != .reply_settled) break :blk false;
                        const ref = value.previous orelse break :blk false;
                        var previous = try contracts.decodeOwned(
                            state.Reconciliation,
                            a,
                            try self.store().object(a, ref, null),
                        );
                        defer previous.deinit();
                        break :blk std.meta.eql(
                            previous.value.id,
                            value.id,
                        ) and std.meta.eql(previous.value.task, parent.id) and std.meta.eql(
                            previous.value.occurrence,
                            pending.id,
                        ) and std.meta.eql(
                            previous.value.attempt,
                            attempt,
                        ) and previous.value.outcome == .capture_admitted;
                    },
                    .not_sent => value.outcome == .not_sent,
                    .settled_reply => |reply| value.outcome == .reply_settled and std.meta.eql(
                        value.outcome.reply_settled.digest,
                        reply.reply,
                    ),
                    else => unreachable,
                };
                if (matches) return true;
            }
            return false;
        }
        fn validateResidualDelivery(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            before: occurrence.Occurrence,
            after: occurrence.Occurrence,
            revision: u64,
        ) !void {
            var validation = ResidualDeliveryValidation{
                .self = self,
                .a = a,
                .parent = parent,
                .before = before,
                .after = after,
                .revision = revision,
                .binding = undefined,
            };
            return validation.run();
        }
        const ResidualDeliveryValidation = residualDeliveryValidationType();
        fn residualDeliveryValidationType() type {
            return struct {
                self: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                before: occurrence.Occurrence,
                after: occurrence.Occurrence,
                revision: u64,
                binding: occurrence.Binding,
                fn run(ctx: *@This()) !void {
                    if (std.meta.eql(ctx.before, ctx.after)) return;
                    ctx.binding = .{
                        .id = ctx.before.id,
                        .task = ctx.parent.id,
                        .residual = ctx.before.residual,
                        .request = ctx.before.request,
                    };
                    const expected = switch (ctx.after.state) {
                        .dispatching => |attempt| occurrence.dispatch(
                            ctx.before,
                            ctx.binding,
                            attempt.id,
                            false,
                            true,
                        ) catch return error.InvalidArchive,
                        .awaiting => |waiting| occurrence.awaiting(
                            ctx.before,
                            ctx.binding,
                            waiting,
                            false,
                        ) catch return error.InvalidArchive,
                        .unknown => |attempt| occurrence.unknown(
                            ctx.before,
                            ctx.binding,
                            attempt.id,
                        ) catch return error.InvalidArchive,
                        .not_sent => |attempt| try ctx.deliveryNotSent(attempt),
                        .captured => |attempt| try ctx.deliveryCaptured(attempt),
                        .settled_reply => |reply| try ctx.deliverySettledReply(reply),
                        .ready, .admitted => return error.InvalidArchive,
                    };
                    if (!std.meta.eql(expected, ctx.after)) return error.InvalidArchive;
                }

                fn deliveryNotSent(
                    ctx: *@This(),
                    attempt: @FieldType(@FieldType(occurrence.Occurrence, "state"), "not_sent"),
                ) !occurrence.Occurrence {
                    if (ctx.before.state == .unknown) {
                        if (!try ctx.self.residualRecoveredAt(
                            ctx.a,
                            ctx.parent,
                            ctx.after,
                            ctx.revision,
                        )) return error.InvalidArchive;
                        return occurrence.recoveredNotSent(
                            ctx.before,
                            ctx.binding,
                            attempt.id,
                        ) catch return error.InvalidArchive;
                    }
                    return occurrence.notSent(
                        ctx.before,
                        ctx.binding,
                        attempt.id,
                    ) catch return error.InvalidArchive;
                }

                fn deliveryCaptured(
                    ctx: *@This(),
                    attempt: @FieldType(@FieldType(occurrence.Occurrence, "state"), "captured"),
                ) !occurrence.Occurrence {
                    if (ctx.before.state == .unknown) {
                        if (!try ctx.self.residualRecoveredAt(
                            ctx.a,
                            ctx.parent,
                            ctx.after,
                            ctx.revision,
                        )) return error.InvalidArchive;
                        return occurrence.recoveredCapture(
                            ctx.before,
                            ctx.binding,
                            attempt.id,
                        ) catch return error.InvalidArchive;
                    }
                    return occurrence.captured(
                        ctx.before,
                        ctx.binding,
                        attempt.id,
                    ) catch return error.InvalidArchive;
                }

                fn deliverySettledReply(
                    ctx: *@This(),
                    reply: @FieldType(@FieldType(occurrence.Occurrence, "state"), "settled_reply"),
                ) !occurrence.Occurrence {
                    if (reply.answer) |answer| return occurrence.answered(
                        ctx.before,
                        ctx.binding,
                        answer.question,
                        answer.pending_digest,
                        answer.digest,
                        reply.reply,
                        false,
                    ) catch return error.InvalidArchive;
                    var dispatched = ctx.before;
                    if (ctx.before.state == .ready) {
                        const bytes = try ctx.self.store().object(
                            ctx.a,
                            ctx.before.request_object,
                            null,
                        );
                        defer ctx.a.free(bytes);
                        var request = try data.invocation.decode(
                            data.invocation.Request,
                            ctx.a,
                            bytes,
                        );
                        defer request.deinit();
                        const entry = try ctx.self.handlers.resolve(
                            request.value,
                            try ctx.self.occurrenceImage(ctx.a, ctx.parent, ctx.before),
                        );
                        if (entry.declaration.kind != .workspace) return error.InvalidArchive;
                        dispatched = occurrence.dispatch(
                            ctx.before,
                            ctx.binding,
                            reply.attempt,
                            false,
                            true,
                        ) catch return error.InvalidArchive;
                    } else if (ctx.before.state == .unknown and !try ctx.self.residualRecoveredAt(
                        ctx.a,
                        ctx.parent,
                        ctx.after,
                        ctx.revision,
                    )) return error.InvalidArchive;
                    return occurrence.acquired(
                        dispatched,
                        ctx.binding,
                        reply.attempt,
                        reply.reply,
                    ) catch return error.InvalidArchive;
                }
            };
        }
        fn validateResidualPublication(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            event_value: state.Event,
            item: state.ResidualPublication,
            prior: ?state.ResidualPublication,
            command: ?workspace.PublicationCommand,
            admission: ?WorkspaceAdmission,
        ) !void {
            var validation = ResidualPublicationValidation{
                .self = self,
                .a = a,
                .parent = parent,
                .event_value = event_value,
                .item = item,
                .prior = prior,
                .command = command,
                .admission = admission,
                .value = item.value,
                .expected = undefined,
            };
            return validation.run();
        }
        const ResidualPublicationValidation = residualPublicationValidationType();
        fn residualPublicationValidationType() type {
            return struct {
                self: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                event_value: state.Event,
                item: state.ResidualPublication,
                prior: ?state.ResidualPublication,
                command: ?workspace.PublicationCommand,
                admission: ?WorkspaceAdmission,
                value: state.ControllerResidualObservation,
                expected: state.ControllerResidualObservation,
                fn run(ctx: *@This()) !void {
                    if (!std.meta.eql(ctx.value.task, ctx.parent.id)) return error.InvalidArchive;
                    try ctx.occurrenceIdentity();
                    if (ctx.prior) |before| {
                        if (before.value.outcome_kind == .completed or
                            before.value.outcome_kind == .failed or
                            before.value.outcome_kind == .cancelled)
                            return error.InvalidArchive;
                        ctx.expected = before.value;
                        if (ctx.command) |selected| try ctx.selectedCommand(
                            before,
                            selected,
                        ) else try ctx.progress(before);
                    } else {
                        try ctx.initialPublication();
                    }
                }

                fn occurrenceIdentity(ctx: *@This()) !void {
                    if (ctx.item.occurrence) |pending| {
                        if (!std.meta.eql(
                            ctx.value.current_occurrence,
                            pending.id,
                        ) or !std.meta.eql(
                            pending.task,
                            ctx.parent.id,
                        ) or pending.work != null or
                            (ctx.value.cancellation_applied and !std.meta.eql(
                                pending.residual,
                                ctx.value.id,
                            ))) return error.InvalidArchive;
                        var current = try ctx.self.record(
                            occurrence.Occurrence,
                            ctx.a,
                            "occurrence",
                            pending.id,
                            ctx.parent.id,
                        );
                        defer current.deinit();
                        if (!std.meta.eql(pending.request, current.value.request) or !std.meta.eql(
                            pending.request_object,
                            current.value.request_object,
                        )) return error.InvalidArchive;
                        const acquired: ?occurrence.Acquired = switch (pending.state) {
                            .settled_reply => |reply| reply,
                            .admitted => |settled| if (settled == .reply) settled.reply else null,
                            else => null,
                        };
                        if (acquired) |acquired_expected| {
                            const actual = switch (current.value.state) {
                                .settled_reply => |reply| reply,
                                .admitted => |settled| if (settled ==
                                    .reply) settled.reply else return error.InvalidArchive,
                                else => return error.InvalidArchive,
                            };
                            if (!std.meta.eql(
                                acquired_expected,
                                actual,
                            )) return error.InvalidArchive;
                        }
                    } else if (ctx.value.current_occurrence != null) return error.InvalidArchive;
                }

                fn initialPublication(ctx: *@This()) !void {
                    if (ctx.event_value.kind != .controller or
                        ctx.command != null or
                        ctx.value.execution_revision == 0 or
                        ctx.value.control_revision != 1 or
                        ctx.value.cancellation_applied or
                        ctx.value.schedule != .queued or
                        ctx.value.blocker != null)
                        return error.InvalidArchive;
                    var succession = try ctx.self.record(
                        state.ControllerSuccession,
                        ctx.a,
                        "controller_succession",
                        ctx.value.succession,
                        ctx.parent.id,
                    );
                    defer succession.deinit();
                    const original = succession.value;
                    if (original.phase != .activated or
                        original.activation_event != ctx.event_value.seq or
                        !std.meta.eql(
                            original.residual,
                            ctx.value.id,
                        ) or !std.meta.eql(
                        original.predecessor,
                        ctx.value.controller,
                    ) or !std.meta.eql(
                        original.checkpoint,
                        ctx.value.initial_checkpoint,
                    ) or
                        !std.meta.eql(original.checkpoint, ctx.value.checkpoint) or
                        !std.meta.eql(original.outcome, ctx.value.outcome) or
                        !std.meta.eql(
                            ctx.value.current_occurrence,
                            original.handoff,
                        )) return error.InvalidArchive;
                    const publication = ctx.event_value.root_publication orelse
                        return error.InvalidArchive;
                    const boot = original.boot orelse return error.InvalidArchive;
                    if (!std.meta.eql(
                        publication.after.controller,
                        try ctx.self.controllerAt(ctx.a, ctx.parent, ctx.event_value.seq),
                    ) or
                        !std.meta.eql(publication.after.checkpoint, boot.checkpoint.digest))
                        return error.InvalidArchive;
                    try ctx.self.validateResidualObservation(ctx.a, ctx.value);
                }

                fn receiptObservation(ctx: *@This(), admitted: WorkspaceAdmission) !void {
                    var observed = try contracts.decodeOwned(
                        state.ControllerResidual,
                        ctx.a,
                        try ctx.self.store().object(
                            ctx.a,
                            admitted.observation orelse return error.InvalidArchive,
                            null,
                        ),
                    );
                    defer observed.deinit();
                    if (!std.meta.eql(
                        ctx.value,
                        state.ControllerResidualObservation.from(observed.value),
                    )) return error.InvalidArchive;
                }

                fn selectedCommand(
                    ctx: *@This(),
                    before: state.ResidualPublication,
                    selected: workspace.PublicationCommand,
                ) !void {
                    const admitted = ctx.admission orelse return error.InvalidArchive;
                    if (ctx.event_value.kind != .workspace or selected != .residual or
                        !std.meta.eql(
                            admitted.work,
                            ctx.value.id,
                        ) or
                        selected.residual.execution != before.value.execution_revision or
                        selected.residual.control != before.value.control_revision or
                        selected.residual.command == .delegate)
                        return error.InvalidArchive;
                    ctx.expected.control_revision = std.math.add(
                        u64,
                        ctx.expected.control_revision,
                        1,
                    ) catch return error.InvalidArchive;
                    ctx.expected.schedule =
                        if (selected.residual.command ==
                        .park) .parked else .queued;
                    ctx.expected.blocker = null;
                    if (!std.meta.eql(ctx.expected, ctx.value)) return error.InvalidArchive;
                    var pending = before.occurrence;
                    if (pending) |*old| {
                        if (old.state == .unknown or
                            old.state == .dispatching)
                            return error.InvalidArchive;
                        if (old.state == .not_sent and
                            selected.residual.command != .park) old.* = occurrence.rearm(
                            old.*,
                            .{
                                .id = old.id,
                                .task = ctx.parent.id,
                                .residual = old.residual,
                                .request = old.request,
                            },
                        ) catch return error.InvalidArchive;
                    }
                    if (!std.meta.eql(pending, ctx.item.occurrence)) return error.InvalidArchive;
                    try ctx.receiptObservation(admitted);
                }

                fn deliveryProgress(ctx: *@This(), before: state.ResidualPublication) !void {
                    const pending = ctx.item.occurrence orelse return error.InvalidArchive;
                    if (before.occurrence == null or !std.meta.eql(
                        pending.id,
                        before.occurrence.?.id,
                    )) return error.InvalidArchive;
                    try ctx.self.validateResidualDelivery(
                        ctx.a,
                        ctx.parent,
                        before.occurrence.?,
                        pending,
                        ctx.event_value.revision,
                    );
                    if (ctx.value.blocker != null) {
                        if (pending.state != .ready and
                            pending.state != .captured and
                            pending.state != .unknown and
                            pending.state != .not_sent)
                            return error.InvalidArchive;
                        ctx.expected.schedule = .parked;
                        ctx.expected.blocker = ctx.value.blocker;
                        if (ctx.value.blocker == .waiting_workspace and
                            (pending.state != .ready or
                                !ctx.value.cancellation_applied or
                                try ctx.self.residualWaitReadyAt(
                                    ctx.a,
                                    ctx.parent,
                                    pending.id,
                                    ctx.event_value.seq - 1,
                                ))) return error.InvalidArchive;
                    } else {
                        ctx.expected.blocker = null;
                        ctx.expected.schedule = switch (pending.state) {
                            .dispatching => .active,
                            .awaiting => .parked,
                            .captured, .settled_reply => .queued,
                            .ready => blk: {
                                if (before.value.blocker != .waiting_workspace or
                                    before.value.schedule != .parked or
                                    !ctx.value.cancellation_applied or
                                    !try ctx.self.residualWaitReadyAt(
                                        ctx.a,
                                        ctx.parent,
                                        pending.id,
                                        ctx.event_value.seq - 1,
                                    )) return error.InvalidArchive;
                                break :blk .queued;
                            },
                            .unknown => blk: {
                                if (!try ctx.self.residualRecoveryAt(
                                    ctx.a,
                                    ctx.parent,
                                    pending.id,
                                    ctx.event_value.revision,
                                )) return error.InvalidArchive;
                                break :blk .queued;
                            },
                            else => return error.InvalidArchive,
                        };
                    }
                    if (!std.meta.eql(ctx.expected, ctx.value)) return error.InvalidArchive;
                }

                fn progress(ctx: *@This(), before: state.ResidualPublication) !void {
                    if (ctx.event_value.kind != .workspace_progress) return error.InvalidArchive;
                    if (ctx.value.execution_revision != before.value.execution_revision) {
                        ctx.expected.execution_revision = std.math.add(
                            u64,
                            ctx.expected.execution_revision,
                            1,
                        ) catch return error.InvalidArchive;
                        ctx.expected.checkpoint = ctx.value.checkpoint;
                        ctx.expected.outcome = ctx.value.outcome;
                        ctx.expected.outcome_kind = ctx.value.outcome_kind;
                        ctx.expected.current_occurrence = ctx.value.current_occurrence;
                        ctx.expected.cancellation_applied = true;
                        ctx.expected.schedule = if (ctx.value.outcome_kind == .completed or
                            ctx.value.outcome_kind == .failed or
                            ctx.value.outcome_kind == .cancelled) .parked else .queued;
                        if (!std.meta.eql(ctx.expected, ctx.value)) return error.InvalidArchive;
                        if (ctx.item.occurrence) |pending| if (pending.state != .ready)
                            return error.InvalidArchive;
                        try ctx.self.validateResidualObservation(ctx.a, ctx.value);
                    } else {
                        try ctx.deliveryProgress(before);
                    }
                }
            };
        }
        fn capturedControllerReads(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            records: []const state.ArchiveRecord,
            compiler_reads: *std.AutoHashMap(state.Digest, CompilerReadPosition),
        ) ![]state.ControllerReadCut {
            var captured_reads: std.ArrayList(state.ControllerReadCut) = .empty;
            errdefer captured_reads.deinit(a);
            for (records) |row| {
                if (row.kind != .attempt) continue;
                var attempt = try self.record(
                    state.Attempt,
                    self.allocator,
                    "attempt",
                    row.id,
                    task_id,
                );
                defer attempt.deinit();
                if (!std.meta.eql(attempt.value.task, task_id) or
                    !std.meta.eql(attempt.value.id, row.id)) return error.InvalidArchive;
                if (attempt.value.controller_read) |read| try captured_reads.append(a, read);
                try self.captureCompilerRead(task_id, attempt.value, compiler_reads);
            }
            std.mem.sort(state.ControllerReadCut, captured_reads.items, {}, struct {
                fn less(
                    _: void,
                    left: state.ControllerReadCut,
                    right: state.ControllerReadCut,
                ) bool {
                    return left.event_watermark < right.event_watermark;
                }
            }.less);
            return captured_reads.toOwnedSlice(a);
        }
        fn captureCompilerRead(
            self: *Self,
            task_id: state.TaskId,
            attempt: state.Attempt,
            compiler_reads: *std.AutoHashMap(state.Digest, CompilerReadPosition),
        ) !void {
            if (attempt.operation == .workspace_build) {
                const bytes = try self.store().object(
                    self.allocator,
                    attempt.prepared orelse return error.InvalidArchive,
                    null,
                );
                defer self.allocator.free(bytes);
                var input = try contracts.decodeOwned(build_job.Input, self.allocator, bytes);
                defer input.deinit();
                if (input.value == .derive and input.value.derive.basis != .immutable) {
                    try self.captureMutableCompilerRead(
                        task_id,
                        attempt,
                        input.value,
                        compiler_reads,
                    );
                } else if (attempt.dispatch_checkpoint != null)
                    return error.InvalidArchive;
            } else if (attempt.dispatch_checkpoint != null) return error.InvalidArchive;
        }
        fn captureMutableCompilerRead(
            self: *Self,
            task_id: state.TaskId,
            attempt: state.Attempt,
            input: build_job.Input,
            compiler_reads: *std.AutoHashMap(state.Digest, CompilerReadPosition),
        ) !void {
            const at = switch (input.derive.basis) {
                .controller => |read| read.event_watermark,
                .works => |read| read.event_watermark,
                else => return error.InvalidArchive,
            };
            try validateControllerReadCut(input.derive.basis, attempt.controller_read);
            const checkpoint = attempt.dispatch_checkpoint orelse
                return error.InvalidArchive;
            const checkpoint_bytes = try self.store().object(
                self.allocator,
                checkpoint,
                null,
            );
            defer self.allocator.free(checkpoint_bytes);
            const request_bytes = try self.store().object(
                self.allocator,
                attempt.request,
                null,
            );
            defer self.allocator.free(request_bytes);
            var request = try data.invocation.decode(
                data.invocation.Request,
                self.allocator,
                request_bytes,
            );
            defer request.deinit();
            if (!std.meta.eql(
                data.invocation.stateDigest(checkpoint_bytes),
                request.value.binding.pending_state_digest,
            )) return error.InvalidArchive;
            var route = try self.record(
                workspace.ExecutionRoute,
                self.allocator,
                "execution_route",
                attempt.occurrence,
                task_id,
            );
            defer route.deinit();
            if (route.value.work != null or
                route.value.residual != null)
                return error.InvalidArchive;
            const entry = try compiler_reads.getOrPut(attempt.id);
            if (entry.found_existing) return error.InvalidArchive;
            entry.value_ptr.* = .{
                .occurrence = attempt.occurrence,
                .event_watermark = at,
                .controller_read = attempt.controller_read,
                .root = .{
                    .controller = route.value.controller,
                    .checkpoint = checkpoint.digest,
                },
            };
        }
        fn validateWorkspacePublications(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            var root_history: state.RootHistory = .init(parent);
            var compiler_reads: std.AutoHashMap(state.Digest, CompilerReadPosition) = .init(a);
            defer compiler_reads.deinit();
            const captured_reads = try self.capturedControllerReads(
                a,
                parent.id,
                records,
                &compiler_reads,
            );
            defer a.free(captured_reads);
            var prefix: @import("workspace_observers.zig").PublicationPrefix = .init(a);
            defer prefix.deinit();
            var successor_ids: std.AutoHashMap(state.Digest, state.Digest) = .init(a);
            defer successor_ids.deinit();
            var admissions: std.AutoHashMap(u64, WorkspaceAdmission) = .init(a);
            defer admissions.deinit();
            var replies: std.AutoHashMap(state.Digest, void) = .init(a);
            defer replies.deinit();
            var residuals: std.AutoHashMap(state.Digest, state.ResidualPublication) = .init(a);
            defer residuals.deinit();
            var validation: PublicationValidation = .{
                .service = self,
                .a = a,
                .parent = parent,
                .records = records,
                .checked = checked,
                .root_history = &root_history,
                .compiler_reads = &compiler_reads,
                .captured_reads = captured_reads,
                .prefix = &prefix,
                .successor_ids = &successor_ids,
                .admissions = &admissions,
                .replies = &replies,
                .residuals = &residuals,
            };
            try validation.admitReceipts();
            try validation.events();
            try validation.finalRecords();
            try validation.observerHeads();
            try validation.finish();
        }
        const PublicationValidation = publicationValidationType();
        fn publicationValidationType() type {
            return struct {
                service: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                records: []const state.ArchiveRecord,
                checked: *SnapshotValidation,
                root_history: *state.RootHistory,
                compiler_reads: *std.AutoHashMap(state.Digest, CompilerReadPosition),
                captured_reads: []const state.ControllerReadCut,
                captured_read: usize = 0,
                prefix: *@import("workspace_observers.zig").PublicationPrefix,
                successor_ids: *std.AutoHashMap(state.Digest, state.Digest),
                admissions: *std.AutoHashMap(u64, WorkspaceAdmission),
                replies: *std.AutoHashMap(state.Digest, void),
                residuals: *std.AutoHashMap(state.Digest, state.ResidualPublication),
                fn admitReceipts(validation: *@This()) !void {
                    var operations = try validation.service.store().database.prepare(
                        "SELECT o.body FROM operations p JOIN objects o ON o.digest=p.rec" ++
                            "eipt WHERE p.task=?",
                        &.{.{ .blob = &validation.parent.id }},
                    );
                    defer operations.deinit();
                    while (try operations.step() == .row) {
                        var receipt_value = try contracts.decodeOwned(
                            state.Receipt,
                            validation.a,
                            try operations.bytes(0),
                        );
                        defer receipt_value.deinit();
                        const value = receipt_value.value;
                        if (value.method != .workspace) continue;
                        const entry = try validation.admissions.getOrPut(value.revision);
                        if (entry.found_existing) return error.InvalidArchive;
                        entry.value_ptr.* = .{
                            .request = value.request_digest,
                            .work = value.workspace orelse return error.InvalidArchive,
                            .kind = value.workspace_kind orelse return error.InvalidArchive,
                            .observation = value.workspace_observation,
                        };
                    }
                }
                fn events(validation: *@This()) !void {
                    var query = try validation.service.store().database.prepare(
                        "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                            "ERE e.task=? ORDER BY e.seq",
                        &.{.{ .blob = &validation.parent.id }},
                    );
                    defer query.deinit();
                    while (try query.step() == .row) {
                        var saved = try contracts.decodeOwned(
                            state.Event,
                            validation.a,
                            try query.bytes(0),
                        );
                        defer saved.deinit();
                        try validation.event(saved.value);
                    }
                }
                fn validateCommand(
                    validation: *@This(),
                    event_value: state.Event,
                    command: *?contracts.Decoded(workspace.PublicationCommand),
                    admission: anytype,
                ) !void {
                    if (event_value.kind == .workspace) {
                        const ref = event_value.workspace_command orelse
                            return error.InvalidArchive;
                        command.* = try contracts.decodeOwned(
                            workspace.PublicationCommand,
                            validation.a,
                            try validation.service.store().object(validation.a, ref, null),
                        );
                        if ((event_value.controller_read != null) != publicationReadsController(
                            command.*.?.value,
                        )) return error.InvalidArchive;
                        if (command.*.?.value == .realize_controller) {
                            const selected = command.*.?.value.realize_controller;
                            try validation.root_history.observeCut(.{
                                .controller = selected.controller,
                                .checkpoint = selected.checkpoint.digest,
                            });
                        }
                        try validation.service.validateWorkspaceAdmission(
                            validation.a,
                            validation.parent,
                            event_value,
                            command.*.?.value,
                            (admission orelse return error.InvalidArchive).value,
                            validation.records,
                            validation.checked,
                        );
                        if (command.*.?.value == .context) if (event_value.controller_read) |cut|
                            try validation.checked.controller_values.put(
                                validation.checked.allocator,
                                admission.?.value.work,
                                cut,
                            );
                        if (event_value.residual_publications.items.len != @as(
                            usize,
                            if (command.*.?.value == .residual) 1 else 0,
                        )) return error.InvalidArchive;
                        if (command.*.?.value == .interact) {
                            const reply = try validation.service.workspaceInteractionReply(
                                validation.a,
                                validation.parent.id,
                                command.*.?.value.interact,
                            );
                            try requireArchiveRecord(
                                validation.records,
                                .workspace_port_reply,
                                reply.id,
                            );
                            if ((try validation.replies.getOrPut(
                                reply.id,
                            )).found_existing) return error.InvalidArchive;
                        }
                    } else if (event_value.workspace_command != null or
                        (event_value.kind != .workspace_read and
                            event_value.controller_read != null))
                        return error.InvalidArchive;
                }
                fn residualEvents(
                    validation: *@This(),
                    event_value: state.Event,
                    command: ?contracts.Decoded(workspace.PublicationCommand),
                    admission: anytype,
                ) !void {
                    if (event_value.kind == .workspace_progress and
                        event_value.workspace_publications.items.len == 0 and
                        event_value.residual_publications.items.len == 0)
                        return error.InvalidArchive;
                    if (event_value.kind == .controller and
                        event_value.residual_publications.items.len != 1)
                        return error.InvalidArchive;
                    if (event_value.residual_publications.items.len > 1)
                        return error.InvalidArchive;
                    for (event_value.residual_publications.items) |item| {
                        try requireArchiveRecord(
                            validation.records,
                            .controller_residual,
                            item.value.id,
                        );
                        try validation.service.validateResidualPublication(
                            validation.a,
                            validation.parent,
                            event_value,
                            item,
                            validation.residuals.get(item.value.id),
                            if (command) |decoded| decoded.value else null,
                            if (admission) |entry| entry.value else null,
                        );
                        if (event_value.kind != .controller) {
                            var parsed = try json.parseAsset(
                                validation.a,
                                event_value.data.bytes,
                                event_value.data.bytes.len,
                            );
                            defer parsed.deinit();
                            const text = try json.text(
                                parsed.value.object.get(
                                    "workspace_id",
                                ) orelse return error.InvalidArchive,
                            );
                            if (!std.meta.eql(
                                try wp.identity(
                                    .{ .kind = .residual, .id = .{ .bytes = text } },
                                    .residual,
                                ),
                                item.value.id,
                            )) return error.InvalidArchive;
                        }
                        try validation.residuals.put(item.value.id, item);
                    }
                }
                fn readEvent(validation: *@This(), event_value: state.Event) !void {
                    if (event_value.kind == .workspace_read) {
                        var parsed = try json.parseAsset(
                            validation.a,
                            event_value.data.bytes,
                            event_value.data.bytes.len,
                        );
                        defer parsed.deinit();
                        const text = try json.text(
                            parsed.value.object.get(
                                "occurrence_id",
                            ) orelse return error.InvalidArchive,
                        );
                        const id = try wp.identity(
                            .{ .kind = .work, .id = .{ .bytes = text } },
                            .work,
                        );
                        if (parsed.value.object.get("attempt_id")) |attempt_text| {
                            const attempt_id = try wp.identity(
                                .{ .kind = .work, .id = .{ .bytes = try json.text(attempt_text) } },
                                .work,
                            );
                            const read = (validation.compiler_reads.fetchRemove(
                                attempt_id,
                            ) orelse return error.InvalidArchive).value;
                            if (!std.meta.eql(read.occurrence, id) or event_value.seq == 0 or
                                read.event_watermark != event_value.seq - 1 or
                                !std.meta.eql(
                                    read.controller_read,
                                    event_value.controller_read,
                                )) return error.InvalidArchive;
                            try requireArchiveRecord(validation.records, .occurrence, id);
                            try validation.root_history.observeCut(read.root);
                        } else {
                            try requireArchiveRecord(validation.records, .workspace_reply, id);
                            var evidence = try validation.service.record(
                                workspace.ReplyObservation,
                                validation.a,
                                "workspace_reply",
                                id,
                                validation.parent.id,
                            );
                            defer evidence.deinit();
                            if (evidence.value.evidence != .read) return error.InvalidArchive;
                            const at = switch (evidence.value.evidence.read) {
                                .immutable => return error.InvalidArchive,
                                .semantic_policy => |value| value.event_watermark,
                                .scope => |value| value,
                                .controller => |value| value.event_watermark,
                                .residual => |value| value.event_watermark,
                                .works => |value| value.event_watermark,
                                .wait => |value| value.event_watermark,
                            };
                            if (event_value.seq == 0 or
                                at != event_value.seq - 1)
                                return error.InvalidArchive;
                            try validateControllerReadCut(
                                evidence.value.evidence.read,
                                event_value.controller_read,
                            );
                        }
                    }
                }
                fn workEvents(
                    validation: *@This(),
                    event_value: state.Event,
                    command: ?contracts.Decoded(workspace.PublicationCommand),
                    admission: anytype,
                ) !void {
                    if (event_value.workspace_publications.items.len != 0 and
                        event_value.kind != .workspace and
                        event_value.kind != .workspace_progress)
                        return error.InvalidArchive;
                    if (event_value.workspace_publications.items.len != 0) {
                        var parsed = try json.parseAsset(
                            validation.a,
                            event_value.data.bytes,
                            event_value.data.bytes.len,
                        );
                        defer parsed.deinit();
                        const text = try json.text(
                            parsed.value.object.get(
                                "workspace_id",
                            ) orelse return error.InvalidArchive,
                        );
                        const id = try wp.identity(
                            .{ .kind = .work, .id = .{ .bytes = text } },
                            .work,
                        );
                        if (!std.meta.eql(
                            id,
                            event_value.workspace_publications.items[0].work,
                        )) return error.InvalidArchive;
                    }
                    for (event_value.workspace_publications.items) |item|
                        try validation.workEvent(event_value, command, admission, item);
                }
                fn event(validation: *@This(), event_value: state.Event) !void {
                    while (validation.captured_read < validation.captured_reads.len and
                        validation.captured_reads[validation.captured_read].event_watermark <
                            event_value.seq)
                    {
                        try validation.root_history.observeRead(
                            validation.captured_reads[validation.captured_read],
                        );
                        validation.captured_read += 1;
                    }
                    try validation.root_history.observe(event_value);
                    errdefer std.debug.print("workspace publication: {s} at {d}\n", .{
                        @tagName(event_value.kind),
                        event_value.seq,
                    });
                    var command: ?contracts.Decoded(workspace.PublicationCommand) = null;
                    defer if (command) |*decoded| decoded.deinit();
                    const admission = if (event_value.kind == .workspace)
                        validation.admissions.fetchRemove(event_value.revision)
                    else
                        null;
                    try validation.validateCommand(event_value, &command, admission);
                    try validation.residualEvents(event_value, command, admission);
                    try validation.readEvent(event_value);
                    try validation.workEvents(event_value, command, admission);
                }
                fn finalRecords(validation: *@This()) !void {
                    if (validation.admissions.count() != 0 or
                        validation.compiler_reads.count() != 0)
                        return error.InvalidArchive;
                    for (validation.records) |row| {
                        if (row.kind == .workspace_port_reply and !validation.replies.contains(
                            row.id,
                        )) return error.InvalidArchive;
                        if (row.kind == .controller_residual) {
                            var residual = try validation.service.record(
                                state.ControllerResidual,
                                validation.a,
                                "controller_residual",
                                row.id,
                                validation.parent.id,
                            );
                            defer residual.deinit();
                            const last = validation.residuals.get(
                                row.id,
                            ) orelse return error.InvalidArchive;
                            if (!std.meta.eql(
                                last,
                                try validation.service.residualPublication(
                                    validation.a,
                                    residual.value,
                                ),
                            )) return error.InvalidArchive;
                        }
                        if (row.kind != .workspace_work) continue;
                        const current = try validation.service.freezeWorkspaceWork(
                            validation.a,
                            validation.parent.id,
                            try wp.reference(validation.a, .work, row.id),
                            true,
                        );
                        const last = validation.prefix.latest.get(
                            row.id,
                        ) orelse return error.InvalidArchive;
                        if (last.seq != current.work.event_watermark or !try samePublication(
                            validation.a,
                            last.publication,
                            try workPublication(validation.a, current),
                        )) return error.InvalidArchive;
                        if (current.work.observer) |observer|
                            if (!std.meta.eql(
                                observer.successor,
                                validation.successor_ids.get(row.id),
                            )) return error.InvalidArchive;
                    }
                }
                fn observerHeads(validation: *@This()) !void {
                    var active_count: usize = 0;
                    var publications = validation.prefix.latest.iterator();
                    while (publications.next()) |entry| {
                        const observer = entry.value_ptr.publication.observer orelse continue;
                        if (!observer.stopped and !validation.successor_ids.contains(
                            entry.key_ptr.*,
                        )) active_count += 1;
                    }
                    if (active_count != validation.parent.observer_heads.items.len)
                        return error.InvalidArchive;
                    for (validation.parent.observer_heads.items, 0..) |id, index| {
                        if (index != 0 and !observerHeadOrder(
                            {},
                            validation.parent.observer_heads.items[index - 1],
                            id,
                        ))
                            return error.InvalidArchive;
                        const latest = validation.prefix.latest.get(
                            id,
                        ) orelse return error.InvalidArchive;
                        const observer = latest.publication.observer orelse
                            return error.InvalidArchive;
                        if (observer.stopped or validation.successor_ids.contains(
                            id,
                        )) return error.InvalidArchive;
                    }
                }
                fn finish(validation: *@This()) !void {
                    for (validation.captured_reads[validation.captured_read..]) |read|
                        try validation.root_history.observeRead(read);
                    try validation.root_history.finish(validation.parent);
                }
                fn workEvent(
                    validation: *@This(),
                    event_value: state.Event,
                    command: ?contracts.Decoded(workspace.PublicationCommand),
                    admission: anytype,
                    item: state.WorkPublication,
                ) !void {
                    try requireArchiveRecord(validation.records, .workspace_work, item.work);
                    try validation.prefix.validateOuterCursor(item);
                    if (validation.prefix.latest.get(item.work)) |prior| {
                        if (prior.seq >= event_value.seq) return error.InvalidArchive;
                        inline for (.{ "execution_revision", "control_revision" }) |field| {
                            const before = @field(prior.publication, field);
                            const after = @field(item, field);
                            if (after < before or after - before > 1) return error.InvalidArchive;
                        }
                        if (validation.parent.observers_present)
                            try validateObservedAdvance(prior.publication, item, validation.prefix);
                    } else {
                        if (item.execution_revision != 1 or
                            item.control_revision != 1)
                            return error.InvalidArchive;
                        if (item.observer) |observer| if (observer.selection.previous) |previous| {
                            const entry = try validation.successor_ids.getOrPut(
                                try wp.identity(previous, .work),
                            );
                            if (entry.found_existing) return error.InvalidArchive;
                            entry.value_ptr.* = item.work;
                        };
                    }
                    try validation.service.validateWorkspaceControl(
                        validation.a,
                        validation.parent,
                        event_value,
                        item,
                        if (validation.prefix.latest.get(
                            item.work,
                        )) |prior| prior.publication else null,
                        if (command) |decoded| decoded.value else null,
                        if (admission) |entry| entry.value else null,
                        validation.parent.observers_present and validation.prefix.hasOuter(
                            item.work,
                        ),
                        validation.prefix,
                        &validation.checked.observer_successors.histories,
                    );
                    var retained = item;
                    if (item.observer) |observer| retained.observer =
                        try @import("workspace_observers.zig").copyObserver(validation.a, observer);
                    if (item.control.cancellation) |reason| retained.control.cancellation = .{
                        .bytes = try validation.a.dupe(u8, reason.bytes),
                    };
                    if (item.guard) |guard| retained.guard = try copyWorkspaceGuard(
                        validation.a,
                        guard,
                    );
                    try validation.prefix.put(retained, event_value.seq);
                }
            };
        }
        fn workspaceReadBasis(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
            command: wc.Command,
        ) ![]u8 {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var basis: workspace.ReadObservation = .immutable;
            if (command == .work and
                command.work == .inspect and
                command.work.inspect.work.kind == .residual)
            {
                return self.residualReadBasis(a, allocator, parent, command);
            }
            var refs: []const wc.Ref = &.{};
            var one: [1]wc.Ref = undefined;
            var retained = false;
            var collect = false;
            switch (command) {
                .work => |w| switch (w) {
                    .inspect => |r| {
                        one[0] = r.work;
                        refs = &one;
                    },
                    .collect => |r| {
                        refs = r.works.items;
                        collect = true;
                    },
                    .wait => |r| refs = r.works.items,
                    else => return error.InvalidState,
                },
                .context => |c| switch (c) {
                    .inspect => basis = .{ .scope = parent.event_high },
                    .expand => |r| if (r.reference.kind == .work) {
                        one[0] = r.reference;
                        refs = &one;
                        retained = true;
                    },
                    else => return error.InvalidState,
                },
                .program => |p| try self.programReadBasis(a, parent, p, &basis, &refs, &one),
                .placement => return error.InvalidState,
            }
            if (command == .work or refs.len != 0) {
                const observations = try a.alloc(?workspace.WorkObservation, refs.len);
                for (refs, observations) |ref, *out| out.* = self.freezeWorkspaceWork(
                    a,
                    parent.id,
                    ref,
                    retained,
                ) catch |err| blk: {
                    if (!collect or err != error.ArtifactUnavailable) return err;
                    break :blk null;
                };
                basis = if (command == .work and command.work == .wait) .{ .wait = .{
                    .works = .{ .items = observations },
                    .interrupted = parent.messages.items.len != 0 or parent.cancellation != null,
                    .event_watermark = parent.event_high,
                } } else .{ .works = .{
                    .works = .{ .items = observations },
                    .event_watermark = parent.event_high,
                } };
            }
            return contracts.encodeOwned(workspace.ReadObservation, allocator, basis);
        }
        fn residualReadBasis(
            self: *Self,
            a: std.mem.Allocator,
            allocator: std.mem.Allocator,
            parent: state.Task,
            command: wc.Command,
        ) ![]u8 {
            var residual = try self.record(
                state.ControllerResidual,
                a,
                "controller_residual",
                try wp.identity(command.work.inspect.work, .residual),
                parent.id,
            );
            defer residual.deinit();
            return contracts.encodeOwned(workspace.ReadObservation, allocator, .{ .residual = .{
                .value = .from(residual.value),
                .event_watermark = parent.event_high,
            } });
        }
        fn programReadBasis(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            p: wc.Program,
            basis: *workspace.ReadObservation,
            refs: *[]const wc.Ref,
            one: *[1]wc.Ref,
        ) !void {
            if (p == .build or p == .specialize or p == .adopt or
                p == .derive or p == .validate) return error.InvalidState;
            if (p == .describe and p.describe.section == .semantic_candidates)
                basis.* = .{ .semantic_policy = .{
                    .policy = try self.workspaceSemanticPolicy(a),
                    .event_watermark = parent.event_high,
                } };
            const semantic = if (p == .inspect and p.inspect.target == .semantic_source)
                p.inspect.target.semantic_source.subject
            else
                null;
            if (semantic != null and semantic.? == .work) {
                one[0] = semantic.?.work.expected.work;
                refs.* = one;
            }
            if ((p == .describe and p.describe.section == .current_controller) or
                (semantic != null and semantic.? == .controller))
            {
                basis.* = .{ .controller = .{
                    .binding = parent.controller,
                    .epoch = parent.controller_epoch,
                    .execution_revision = parent.execution_revision,
                    .runtime = parent.controller_runtime,
                    .realization_revision = parent.realization_revision,
                    .interaction = parent.controller_interaction,
                    .residuals = .{ .items = try self.controllerResidualIds(a, parent.id) },
                    .event_watermark = parent.event_high,
                } };
            }
        }
        fn rejectWorkspace(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            stage: @FieldType(@FieldType(workspace.ReplyEvidence, "rejected"), "stage"),
            err: anyerror,
        ) !Step {
            if (self.store().fenced or
                err == error.OutOfMemory or
                err == error.StorageUnavailable)
                return err;
            return self.settleWorkspaceReply(a, parent, pending, try workspaceRejection(
                a,
                err,
            ), .{ .rejected = .{ .stage = stage, .code = try name(@errorName(err)) } });
        }
        fn validateHistoricalOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            observed: workspace.WorkObservation,
        ) !void {
            const work = observed.work;
            if (observed.occurrence) |pending| {
                if (!std.meta.eql(work.current_occurrence, pending.id) or
                    !std.meta.eql(pending.task, work.task) or
                    !std.meta.eql(pending.work, work.id))
                    return error.InvalidArchive;
                var current = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    pending.id,
                    work.task,
                );
                defer current.deinit();
                if (!std.meta.eql(current.value.request, pending.request) or !std.meta.eql(
                    current.value.request_object,
                    pending.request_object,
                )) return error.InvalidArchive;
                // A settled observation must name the same acquired evidence;
                // later admission may change only its enclosing state tag.
                const acquired: ?occurrence.Acquired = switch (pending.state) {
                    .settled_reply => |r| r,
                    .admitted => |v| if (v == .reply) v.reply else null,
                    else => null,
                };
                if (acquired) |expected| {
                    const actual = switch (current.value.state) {
                        .settled_reply => |r| r,
                        .admitted => |v| if (v == .reply) v.reply else return error.InvalidArchive,
                        else => return error.InvalidArchive,
                    };
                    if (!std.meta.eql(expected, actual)) return error.InvalidArchive;
                }
            } else if (work.current_occurrence != null) return error.InvalidArchive;
        }
        fn validateControllerReadCut(
            basis: workspace.ReadObservation,
            controller_read: ?state.ControllerReadCut,
        ) !void {
            if (basis == .controller) {
                const cut = controller_read orelse return error.InvalidArchive;
                if (cut.event_watermark != basis.controller.event_watermark or
                    cut.execution_revision != basis.controller.execution_revision)
                    return error.InvalidArchive;
            } else if (controller_read != null) return error.InvalidArchive;
        }
        fn publicationReadsController(command: workspace.PublicationCommand) bool {
            return switch (command) {
                .realize_controller => true,
                .semantic => |selected| selected.command == .derive and
                    selected.command.derive.ancestor == .controller,
                .context => |selected| selected.command == .materialize and
                    selected.command.materialize.input == .semantic_source and
                    selected.command.materialize.input.semantic_source.subject == .controller,
                else => false,
            };
        }
        fn validateWorkspaceReadIn(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            command: wc.Command,
            basis: workspace.ReadObservation,
            records: []const state.ArchiveRecord,
            controller_read: ?state.ControllerReadCut,
            checked: *SnapshotValidation,
        ) !void {
            if (!workspaceIsRead(command)) return error.InvalidArchive;
            try validateControllerReadCut(basis, controller_read);
            if (command == .work and
                command.work == .inspect and
                command.work.inspect.work.kind == .residual)
            {
                try self.validateResidualReadBasis(a, parent, command, basis, records);
                return;
            }
            var refs: []const wc.Ref = &.{};
            var one: [1]wc.Ref = undefined;
            var optional = false;
            var expected: std.meta.Tag(workspace.ReadObservation) = .immutable;
            try workspaceReadSelection(command, &refs, &one, &optional, &expected);
            if (std.meta.activeTag(basis) != expected) return error.InvalidArchive;
            switch (basis) {
                .immutable => {},
                .semantic_policy => |observed| {
                    if (observed.event_watermark > parent.event_high) return error.InvalidArchive;
                },
                .residual => return error.InvalidArchive,
                .controller => |observed| try self.validateControllerReadObservation(
                    a,
                    parent,
                    observed,
                    records,
                ),
                .scope => |watermark| {
                    if (watermark > parent.event_high) return error.InvalidArchive;
                    for (try self.workspaceScopeAt(
                        a,
                        parent.id,
                        watermark,
                    )) |id| try requireArchiveRecord(records, .workspace_work, id);
                },
                .works, .wait => try self.validateWorksReadObservation(
                    a,
                    parent,
                    basis,
                    records,
                    checked,
                    refs,
                    optional,
                ),
            }
        }
        fn validateResidualReadBasis(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            command: wc.Command,
            basis: workspace.ReadObservation,
            records: []const state.ArchiveRecord,
        ) !void {
            if (basis != .residual or
                basis.residual.event_watermark > parent.event_high or
                !std.meta.eql(
                    basis.residual.value.id,
                    try wp.identity(command.work.inspect.work, .residual),
                ) or !std.meta.eql(
                basis.residual.value.task,
                parent.id,
            )) return error.InvalidArchive;
            try requireArchiveRecord(records, .controller_residual, basis.residual.value.id);
            if (!std.meta.eql(
                basis.residual.value,
                try self.residualPublicationAt(
                    a,
                    parent.id,
                    basis.residual.value.id,
                    basis.residual.event_watermark,
                ),
            )) return error.InvalidArchive;
            try self.validateResidualObservation(a, basis.residual.value);
        }
        fn validateControllerReadObservation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            observed: @FieldType(workspace.ReadObservation, "controller"),
            records: []const state.ArchiveRecord,
        ) !void {
            if (!std.meta.eql(
                observed.binding,
                try self.controllerAt(a, parent, observed.event_watermark),
            )) return error.InvalidArchive;
            if (observed.epoch != try self.controllerEpochAt(
                a,
                parent,
                observed.event_watermark,
            )) return error.InvalidArchive;
            const runtime_cut = try self.controllerRuntimeAt(
                a,
                parent,
                observed.event_watermark,
            );
            if (!std.meta.eql(runtime_cut.runtime, observed.runtime) or
                runtime_cut.realization_revision != observed.realization_revision)
                return error.InvalidArchive;
            if (observed.execution_revision > parent.execution_revision) {
                return error.InvalidArchive;
            }
            if (observed.interaction) |id| {
                try requireArchiveRecord(records, .controller_interaction, id);
                var interaction = try self.record(
                    state.ControllerInteraction,
                    a,
                    "controller_interaction",
                    id,
                    parent.id,
                );
                defer interaction.deinit();
                if (!std.meta.eql(
                    observed.binding,
                    @as(?state.Digest, interaction.value.controller),
                ))
                    return error.InvalidArchive;
            }
            if (observed.binding) |id| {
                try requireArchiveRecord(records, .controller_binding, id);
                if (observed.epoch < (try self.controllerBinding(
                    a,
                    parent,
                    id,
                )).epoch) return error.InvalidArchive;
            }
            try self.validateObservedControllerResiduals(a, parent, observed, records);
        }
        fn validateObservedControllerResiduals(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            observed: @FieldType(workspace.ReadObservation, "controller"),
            records: []const state.ArchiveRecord,
        ) !void {
            const all_residuals = try self.controllerResidualIds(a, parent.id);
            defer a.free(all_residuals);
            var count: usize = 0;
            for (all_residuals) |id| {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    parent.id,
                );
                defer residual.deinit();
                var operation_value = try self.record(
                    state.ControllerSuccession,
                    a,
                    "controller_succession",
                    residual.value.succession,
                    parent.id,
                );
                defer operation_value.deinit();
                if ((operation_value.value.activation_event orelse
                    return error.InvalidArchive) > observed.event_watermark)
                    continue;
                if (count >= observed.residuals.items.len or !std.meta.eql(
                    observed.residuals.items[count],
                    id,
                )) return error.InvalidArchive;
                try requireArchiveRecord(records, .controller_residual, id);
                count += 1;
            }
            if (count != observed.residuals.items.len) return error.InvalidArchive;
        }
        fn validateWorksReadObservation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            basis: workspace.ReadObservation,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
            refs: []const wc.Ref,
            optional: bool,
        ) !void {
            const observed =
                if (basis ==
                .works) basis.works.works.items else basis.wait.works.items;
            const watermark =
                if (basis ==
                .works) basis.works.event_watermark else basis.wait.event_watermark;
            if (watermark > parent.event_high) return error.InvalidArchive;
            const visible = if (optional) try self.workspaceScopeAt(
                a,
                parent.id,
                watermark,
            ) else &.{};
            if (observed.len != refs.len) return error.InvalidArchive;
            if (basis == .wait) {
                if (basis.wait.event_watermark > parent.event_high or
                    basis.wait.interrupted != try self.workspaceInterruptedAt(
                        a,
                        parent.id,
                        basis.wait.event_watermark,
                    )) return error.InvalidArchive;
            }
            for (observed, refs) |item, ref| {
                const id = try wp.identity(ref, .work);
                const snapshot = item orelse {
                    if (!optional) return error.InvalidArchive;
                    for (visible) |published| if (std.meta.eql(
                        published,
                        id,
                    )) return error.InvalidArchive;
                    continue;
                };
                if (!std.meta.eql(
                    snapshot.work.id,
                    id,
                ) or snapshot.work.event_watermark > watermark) return error.InvalidArchive;
                try requireArchiveRecord(records, .workspace_work, id);
                try self.validateWorkspaceWorkSnapshotIn(
                    parent,
                    snapshot,
                    records,
                    checked,
                );
                if (snapshot.work.event_watermark != try self.workspacePublicationAt(
                    a,
                    parent.id,
                    id,
                    watermark,
                )) return error.InvalidArchive;
                try self.validateHistoricalOccurrence(a, snapshot);
            }
        }
        fn workspaceReadSelection(
            command: wc.Command,
            refs: *[]const wc.Ref,
            one: *[1]wc.Ref,
            optional: *bool,
            expected: *std.meta.Tag(workspace.ReadObservation),
        ) !void {
            switch (command) {
                .work => |w| switch (w) {
                    .inspect => |r| {
                        one[0] = r.work;
                        refs.* = one;
                        expected.* = .works;
                    },
                    .collect => |r| {
                        refs.* = r.works.items;
                        expected.* = .works;
                        optional.* = true;
                    },
                    .wait => |r| {
                        refs.* = r.works.items;
                        expected.* = .wait;
                    },
                    else => return error.InvalidArchive,
                },
                .context => |c| switch (c) {
                    .inspect => expected.* = .scope,
                    .expand => |r| if (r.reference.kind == .work) {
                        one[0] = r.reference;
                        refs.* = one;
                        expected.* = .works;
                    },
                    else => return error.InvalidArchive,
                },
                .program => |p| {
                    if (p == .describe and p.describe.section == .current_controller) {
                        expected.* = .controller;
                    }
                    if (p == .describe and p.describe.section == .semantic_candidates)
                        expected.* = .semantic_policy;
                    if (p == .inspect and p.inspect.target == .semantic_source) {
                        switch (p.inspect.target.semantic_source.subject) {
                            .runtime => {},
                            .controller => expected.* = .controller,
                            .work => |selected| {
                                one[0] = selected.expected.work;
                                refs.* = one;
                                expected.* = .works;
                            },
                        }
                    }
                },
                .placement => return error.InvalidArchive,
            }
        }
        fn validateWorkspaceReply(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            entry: registry.Entry,
            request: data.invocation.Request,
            saved: workspace.ReplyObservation,
            reply: []const u8,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) anyerror!void {
            try validateWorkspaceReplyIdentity(parent, pending, saved);
            const authorized_bytes = self.authorizeWorkspaceOccurrence(
                a,
                parent,
                pending,
                entry,
                request.binding.payload,
            ) catch |err| {
                try validateWorkspaceAuthorizationFailure(a, saved, reply, err);
                return;
            };
            var authorized = try contracts.decodeOwned(workspace.Authorized, a, authorized_bytes);
            defer authorized.deinit();
            const command = authorized.value.command;
            const operation_id = std.fmt.bytesToHex(pending.id, .lower);
            const expected: wc.Reply = switch (saved.evidence) {
                .placement => |reference| try self.workspaceReplyPlacement(
                    a,
                    parent,
                    reference,
                    command,
                    &operation_id,
                    records,
                ),
                .read => |basis| try self.workspaceReplyRead(
                    a,
                    parent,
                    basis,
                    authorized.value,
                    pending,
                    &operation_id,
                    records,
                    checked,
                ),
                .admitted => |admitted| try self.workspaceReplyAdmitted(
                    a,
                    parent,
                    admitted,
                    authorized.value,
                    &operation_id,
                    records,
                    checked,
                ),
                .rejected => |failure| try self.workspaceReplyRejected(
                    a,
                    failure,
                    command,
                    &operation_id,
                ),
            };
            if (!same(
                reply,
                try contracts.encodeOwned(wc.Reply, a, expected),
            )) return error.InvalidArchive;
        }
        fn validateWorkspaceAuthorizationFailure(
            a: std.mem.Allocator,
            saved: workspace.ReplyObservation,
            reply: []const u8,
            err: anyerror,
        ) !void {
            if (saved.evidence != .rejected or
                saved.evidence.rejected.stage != .authorization or
                !same(
                    saved.evidence.rejected.code.bytes,
                    @errorName(err),
                )) return error.InvalidArchive;
            const expected = try contracts.encodeOwned(
                wc.Reply,
                a,
                try workspaceRejection(a, err),
            );
            if (!same(reply, expected)) return error.InvalidArchive;
        }
        fn validateWorkspaceReplyIdentity(
            parent: state.Task,
            pending: occurrence.Occurrence,
            saved: workspace.ReplyObservation,
        ) !void {
            if (pending.work != null or !std.meta.eql(
                saved.id,
                pending.id,
            ) or !std.meta.eql(saved.task, parent.id) or !std.meta.eql(
                saved.request,
                pending.request_object,
            )) return error.InvalidArchive;
            const acquired = switch (pending.state) {
                .settled_reply => |r| r,
                .admitted => |v| if (v == .reply) v.reply else return error.InvalidArchive,
                else => return error.InvalidArchive,
            };
            if (!std.meta.eql(acquired.attempt, saved.attempt)) return error.InvalidArchive;
        }
        fn workspaceReplyPlacement(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            reference: state.Reference,
            command: wc.Command,
            operation_id: []const u8,
            records: []const state.ArchiveRecord,
        ) !wc.Reply {
            const p = @import("placement.zig");
            if (command != .placement) return error.InvalidArchive;
            const bytes = try self.store().object(a, reference, null);
            defer a.free(bytes);
            var record_value = try contracts.decodeOwned(p.ActionRecord, a, bytes);
            defer record_value.deinit();
            const action = record_value.value.action;
            try p.verify(p.Action, a, action, action.value.owner);
            const id = p.operationId(action.value.owner, parent.id, operation_id, .action);
            if (!std.meta.eql(id, record_value.value.id) or
                !std.meta.eql(id, action.value.id) or
                !std.meta.eql(parent.id, action.value.task) or !same(
                action.value.operation.bytes,
                operation_id,
            )) return error.InvalidArchive;
            try requireArchiveRecord(records, .placement_action, id);
            var indexed = try self.record(
                p.ActionRecord,
                a,
                "placement_action",
                id,
                parent.id,
            );
            defer indexed.deinit();
            if (!std.meta.eql(
                indexed.value.action.signature,
                action.signature,
            )) return error.InvalidArchive;
            const wanted = try contracts.encodeOwned(wc.Placement, a, command.placement);
            defer a.free(wanted);
            const actual = try contracts.encodeOwned(wc.Placement, a, action.value.request);
            defer a.free(actual);
            if (!same(wanted, actual)) return error.InvalidArchive;
            return try placementReplyCopy(a, action.value.reply);
        }
        fn workspaceReplyRead(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            basis: workspace.ReadObservation,
            authorized: workspace.Authorized,
            pending: occurrence.Occurrence,
            operation_id: []const u8,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !wc.Reply {
            const command = authorized.command;

            const controller_read = try self.workspaceReplyReadCut(a, parent, pending, basis);
            try self.validateWorkspaceReadIn(
                a,
                parent,
                command,
                basis,
                records,
                controller_read,
                checked,
            );
            return try self.workspaceCommandFromIn(
                a,
                operation_id,
                parent.id,
                authorized,
                basis,
                .{ .historical = &checked.observer_successors.histories },
            );
        }
        fn workspaceReplyReadCut(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            pending: occurrence.Occurrence,
            basis: workspace.ReadObservation,
        ) !?state.ControllerReadCut {
            var controller_read: ?state.ControllerReadCut = null;
            const watermark: ?u64 = switch (basis) {
                .immutable => null,
                .semantic_policy => |observed| observed.event_watermark,
                .scope => |at| at,
                .controller => |observed| observed.event_watermark,
                .residual => |observed| observed.event_watermark,
                .works => |works| works.event_watermark,
                .wait => |wait| wait.event_watermark,
            };
            if (watermark) |at| {
                // The read's own journal position anchors its prefix;
                // a forged cutoff cannot hide already-published work.
                const sequence = std.math.add(u64, at, 1) catch return error.InvalidArchive;
                var query = try self.store().database.prepare(
                    "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                        "ERE e.task=? AND e.seq=?",
                    &.{ .{ .blob = &parent.id }, .{
                        .integer = std.math.cast(
                            i64,
                            sequence,
                        ) orelse return error.InvalidArchive,
                    } },
                );
                defer query.deinit();
                if (try query.step() != .row) return error.InvalidArchive;
                var event_value = try contracts.decodeOwned(
                    state.Event,
                    a,
                    try query.bytes(0),
                );
                defer event_value.deinit();
                if (event_value.value.kind != .workspace_read) return error.InvalidArchive;
                controller_read = event_value.value.controller_read;
                var event_data = try json.parse(a, event_value.value.data.bytes, .{});
                defer event_data.deinit();
                const id = try json.text(
                    event_data.value.object.get(
                        "occurrence_id",
                    ) orelse return error.InvalidArchive,
                );
                if (!same(
                    id,
                    &std.fmt.bytesToHex(pending.id, .lower),
                )) return error.InvalidArchive;
            }
            return controller_read;
        }
        fn workspaceReplyAdmitted(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            admitted: @FieldType(workspace.ReplyEvidence, "admitted"),
            authorized: workspace.Authorized,
            operation_id: []const u8,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !wc.Reply {
            const command = authorized.command;

            if (workspaceIsRead(command) or
                workspaceCompiles(command))
                return error.InvalidArchive;
            if (self.workspace_replay != null) return error.InvalidArchive;
            self.workspace_replay = .{
                .replayed = admitted.replayed,
                .records = records,
                .checked = checked,
            };
            defer self.workspace_replay = null;
            const result = try self.workspaceCommandFromIn(
                a,
                operation_id,
                parent.id,
                authorized,
                null,
                .{ .historical = &checked.observer_successors.histories },
            );
            if (result.disposition == .rejected) return error.InvalidArchive;
            return result;
        }
        fn workspaceReplyRejected(
            self: *Self,
            a: std.mem.Allocator,
            failure: @FieldType(workspace.ReplyEvidence, "rejected"),
            command: wc.Command,
            operation_id: []const u8,
        ) !wc.Reply {
            if (failure.stage == .authorization or
                failure.code.bytes.len == 0)
                return error.InvalidArchive;
            if (failure.stage == .preparation) {
                if (!workspaceCompiles(command)) return error.InvalidArchive;
            }
            const key = try self.operationKey(a, operation_id);
            if (try self.store().savedReceipt(a, &key)) |committed| {
                a.free(committed);
                return error.InvalidArchive;
            }
            // A captured operation failure is a diagnostic event. It
            // can carry no result, selected view, program or evidence.
            var observation = json.object();
            try json.put(a, &observation, "error", json.string(failure.code.bytes));
            return .{ .disposition = .rejected, .observation_json = .{
                .bytes = try json.canonical(a, observation),
            } };
        }
        fn dispatchWorkspace(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            entry: registry.Entry,
            payload: []const u8,
        ) !Step {
            const authorized = self.authorizeWorkspaceOccurrence(
                a,
                initial,
                pending,
                entry,
                payload,
            ) catch |err| {
                return self.rejectWorkspace(a, initial, pending, .authorization, err);
            };
            defer a.free(authorized);
            var command = try contracts.decodeOwned(workspace.Authorized, a, authorized);
            defer command.deinit();
            if (workspaceCompiles(command.value.command))
                return self.dispatchWorkspaceBuild(a, initial, pending, entry, command.value);
            if (command.value.command == .work and command.value.command.work == .wait) {
                if (try self.dispatchWorkspaceWait(
                    a,
                    initial,
                    pending,
                    command.value.command.work.wait,
                )) |step| return step;
            }
            return self.dispatchWorkspaceObservation(a, initial, pending, command.value);
        }
        fn dispatchWorkspaceBuild(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            entry: registry.Entry,
            command: workspace.Authorized,
        ) !Step {
            if (self.work != null) return .idle;
            const prepared = self.workspacePrepareBuild(a, initial, command) catch |err| {
                return self.rejectWorkspace(a, initial, pending, .preparation, err);
            };
            defer a.free(prepared);
            const request_bytes = try self.store().object(a, pending.request_object, null);
            defer a.free(request_bytes);
            return self.dispatchAcquisition(
                a,
                initial,
                pending,
                entry,
                request_bytes,
                prepared,
                .workspace_build,
                if (command.command.program == .derive and
                    command.command.program.derive.ancestor == .controller) .from(
                    initial,
                ) else null,
            );
        }
        fn dispatchWorkspaceWait(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            selection: @FieldType(wc.Work, "wait"),
        ) !?Step {
            const ready = self.workspaceWaitReady(
                a,
                initial,
                selection,
            ) catch |err| return try self.rejectWorkspace(
                a,
                initial,
                pending,
                .operation,
                err,
            );
            if (!ready) {
                var parked = false;
                if (pending.residual) |id| {
                    var residual = try self.record(
                        state.ControllerResidual,
                        a,
                        "controller_residual",
                        id,
                        initial.id,
                    );
                    defer residual.deinit();
                    parked = residual.value.schedule == .parked and
                        residual.value.blocker == .waiting_workspace;
                }
                var retained = false;
                if (try self.store().recordBytes(
                    a,
                    "workspace_wait",
                    pending.id,
                    initial.id,
                )) |bytes| {
                    defer a.free(bytes);
                    var saved = try contracts.decodeOwned(workspace.Wait, a, bytes);
                    defer saved.deinit();
                    if (!std.meta.eql(
                        saved.value.request,
                        pending.request_object,
                    )) return error.CorruptState;
                    retained = true;
                }
                if (!retained or (pending.residual != null and !parked))
                    try self.parkWorkspaceWait(a, initial, pending, selection, retained);
                self.subjectRemove(.{ .task = initial.id, .residual = pending.residual });
                try self.retire(a);
                return .waiting;
            }
            return null;
        }
        fn parkWorkspaceWait(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            selection: @FieldType(wc.Work, "wait"),
            retained: bool,
        ) !void {
            var value = initial;
            value.revision = try std.math.add(u64, value.revision, 1);
            if (pending.residual == null) value.schedule = .parked;
            try self.store().begin();
            defer self.store().rollback();
            if (!retained) try self.store().createRecord(
                workspace.Wait,
                "workspace_wait",
                pending.id,
                initial.id,
                .{
                    .id = pending.id,
                    .task = initial.id,
                    .request = pending.request_object,
                    .selection = selection,
                },
            );
            try self.effectSchedule(a, &value, pending, .parked, .waiting_workspace);
            try self.persist(a, value, initial.revision, "workspace.wait", .preserve);
        }
        fn dispatchWorkspaceObservation(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            command: workspace.Authorized,
        ) !Step {
            const operation_id = std.fmt.bytesToHex(pending.id, .lower);
            var basis: ?contracts.Decoded(workspace.ReadObservation) = null;
            defer if (basis) |*frozen| frozen.deinit();
            if (workspaceIsRead(command.command)) {
                const bytes = self.workspaceReadBasis(
                    a,
                    initial,
                    command.command,
                ) catch |err| return self.rejectWorkspace(
                    a,
                    initial,
                    pending,
                    .operation,
                    err,
                );
                defer a.free(bytes);
                basis = try contracts.decodeOwned(workspace.ReadObservation, a, bytes);
            }
            const observation = try self.workspaceCommandFrom(
                a,
                &operation_id,
                initial.id,
                command,
                if (basis) |frozen| frozen.value else null,
            );
            var parsed = try json.parseAsset(
                a,
                observation.observation_json.bytes,
                observation.observation_json.bytes.len,
            );
            defer parsed.deinit();
            const placement_evidence = try self.workspacePlacementEvidence(
                a,
                initial.id,
                &operation_id,
                command.command,
            );
            const evidence: workspace.ReplyEvidence = if (placement_evidence) |reference| .{
                .placement = reference,
            } else if (observation.disposition == .rejected)
                .{ .rejected = .{
                    .stage = .operation,
                    .code = try name(
                        try json.text(
                            parsed.value.object.get("error") orelse return error.CorruptState,
                        ),
                    ),
                } }
            else if (basis) |frozen| .{ .read = frozen.value } else .{ .admitted = .{
                .replayed = (parsed.value.object.get(
                    "replayed",
                ) orelse return error.CorruptState).bool,
            } };
            return self.settleWorkspaceReply(a, initial, pending, observation, evidence);
        }
        fn workspacePlacementEvidence(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            operation_id: []const u8,
            command: wc.Command,
        ) !?state.Reference {
            if (command == .placement and self.profile.placement != null) {
                const p = @import("placement.zig");
                const action_id = p.operationId(
                    try self.placementSite(),
                    task_id,
                    operation_id,
                    .action,
                );
                if (try self.store().recordBytes(
                    a,
                    "placement_action",
                    action_id,
                    task_id,
                )) |bytes| {
                    defer a.free(bytes);
                    return .{ .digest = storage.digest(bytes), .bytes = bytes.len };
                }
            }
            return null;
        }
        fn workspacePrepareBuild(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            authorized: workspace.Authorized,
        ) ![]u8 {
            if (authorized.command.program != .build) {
                return self.workspacePrepareSemanticBuild(
                    a,
                    parent,
                    authorized.command.program,
                    null,
                );
            }
            const build = authorized.command.program.build;
            const source = switch (build.source) {
                .json_text => |text| try a.dupe(u8, text.bytes),
                .reference => |ref| try self.workspaceBuildSource(
                    a,
                    parent.id,
                    ref,
                    build.source_kind,
                ),
            };
            defer a.free(source);
            var catalog: ?[]u8 = null;
            defer if (catalog) |bytes| a.free(bytes);
            if (build.source_kind == .component_recipe) {
                const ref = authorized.catalog orelse return error.UnavailableCatalog;
                try workspaceSnapshotAccess(parent, ref);
                catalog = try self.store().object(a, ref, null);
            }
            const contract = if (build.role == .controller) try self.controllerContract(
                a,
            ) else null;
            defer if (contract) |value| {
                a.free(value.result.bytes);
                a.free(value.failure.bytes);
                for (value.imports.items) |item| if (item.native_result != null) a.free(
                    item.result.bytes,
                );
                a.free(value.imports.items);
            };
            return contracts.encodeOwned(build_job.Input, a, .{ .program = .{
                .source = .{ .bytes = source },
                .kind = build.source_kind,
                .catalog = if (catalog) |bytes| .{ .bytes = bytes } else null,
                .exposures = build.exposures,
                .controller = contract,
            } });
        }
        fn workspacePrepareSemanticBuild(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            command: wc.Program,
            frozen: ?workspace.ReadObservation,
        ) ![]u8 {
            switch (command) {
                .derive => |selected| return self.workspacePrepareDerivation(
                    a,
                    parent,
                    selected,
                    frozen,
                ),
                .validate => |selected| {
                    var candidate = try self.workspaceCandidate(
                        a,
                        parent.id,
                        try wp.identity(selected.candidate, .candidate),
                    );
                    defer candidate.deinit();
                    const d = candidate.value.description;
                    try self.requireSemanticPolicy(d.root, d.checker.bytes);
                    const ancestor = try self.store().object(a, d.ancestor, null);
                    defer a.free(ancestor);
                    const code = try self.store().object(a, d.code, null);
                    defer a.free(code);
                    return contracts.encodeOwned(build_job.Input, a, .{ .validate = .{
                        .ancestor = .{ .bytes = ancestor },
                        .candidate = .{ .bytes = code },
                        .candidate_ref = candidate.value.artifact,
                        .program = candidate.value.program,
                        .guest = d.guest,
                        .root = d.root,
                        .checker = d.checker,
                    } });
                },
                else => return error.InvalidState,
            }
        }
        fn workspacePrepareDerivation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            selected: @FieldType(wc.Program, "derive"),
            frozen: ?workspace.ReadObservation,
        ) ![]u8 {
            const inspect: wc.Command = .{ .program = .{ .inspect = .{
                .target = .{ .semantic_source = .{
                    .subject = selected.ancestor,
                    .section = .{ .summary = .{} },
                } },
                .page = .{},
            } } };
            const basis_bytes = if (frozen) |basis|
                try contracts.encodeOwned(workspace.ReadObservation, a, basis)
            else
                try self.workspaceReadBasis(a, parent, inspect);
            defer a.free(basis_bytes);
            var basis = try contracts.decodeOwned(
                workspace.ReadObservation,
                a,
                basis_bytes,
            );
            defer basis.deinit();
            var ancestor = try self.semanticRuntime(
                a,
                parent.id,
                selected.ancestor,
                basis.value,
            );
            defer ancestor.deinit();
            const root = kosmos.RuntimeCompiler.approvedRootIdentity(&ancestor.admitted);
            const checker = kosmos.RuntimeCompiler.checker_identity;
            try self.requireSemanticPolicy(root, checker);
            return self.freezeSemanticDerive(
                a,
                parent.id,
                selected,
                ancestor.admitted,
                root,
                checker,
                basis.value,
            );
        }
        fn freezeSemanticDerive(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            selected: @FieldType(wc.Program, "derive"),
            ancestor: kosmos.RuntimeArtifact,
            root: state.Digest,
            checker: []const u8,
            basis: workspace.ReadObservation,
        ) ![]u8 {
            const program_id = try wp.identity(selected.program, .program);
            var program = try self.workspaceProgram(a, task_id, program_id);
            defer program.deinit();
            const image = try self.store().object(a, program.value.description.image, null);
            defer a.free(image);
            const root_bytes = try ancestor.encode(a);
            defer a.free(root_bytes);
            const proposal = try self.workspaceProposal(a, task_id, selected.proposal);
            defer a.free(proposal);
            const producer = if (selected.proposal == .reference and
                selected.proposal.reference.kind == .value)
                (try self.workspaceValueReference(a, task_id, selected.proposal.reference)).artifact
            else
                null;
            return contracts.encodeOwned(build_job.Input, a, .{ .derive = .{
                .ancestor = .{ .bytes = root_bytes },
                .guest = .{ .bytes = image },
                .program = program_id,
                .proposal = .{ .bytes = proposal },
                .producer = producer,
                .root = root,
                .checker = try name(checker),
                .subject = selected.ancestor,
                .basis = basis,
            } });
        }
        fn workspaceProposal(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            input: wc.SourceInput,
        ) ![]u8 {
            if (input == .json_text) return a.dupe(u8, input.json_text.bytes);
            if (input.reference.kind == .source) return self.workspaceSource(
                a,
                task_id,
                input.reference,
            );
            const source = try self.workspaceValueReference(a, task_id, input.reference);
            const schema = try values.schemaBytes(construction.CandidateDocument, a);
            defer a.free(schema);
            if (!std.meta.eql(source.schema, state.Reference{
                .digest = storage.digest(schema),
                .bytes = schema.len,
            })) return error.SchemaMismatch;
            const bytes = try self.store().object(a, source.value, null);
            defer a.free(bytes);
            var document = try contracts.decodeOwned(construction.CandidateDocument, a, bytes);
            defer document.deinit();
            if (document.value.version != 1) return error.UnsupportedVersion;
            return @import("source_records.zig").encodeRecord(
                construction.CandidateDocument,
                a,
                document.value,
            );
        }
        fn validateSemanticReadPosition(basis: workspace.ReadObservation, event_seq: u64) !void {
            const watermark = switch (basis) {
                .immutable => return,
                .controller => |read| read.event_watermark,
                .works => |read| read.event_watermark,
                else => return error.InvalidArchive,
            };
            if (event_seq == 0 or watermark != event_seq - 1) return error.InvalidArchive;
        }
        fn validateSemanticInput(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            command: wc.Program,
            input: build_job.Input,
            records: []const state.ArchiveRecord,
            controller_read: ?state.ControllerReadCut,
            checked: *SnapshotValidation,
        ) !void {
            if (command == .derive and input == .derive) {
                const inspect: wc.Command = .{ .program = .{ .inspect = .{
                    .target = .{ .semantic_source = .{
                        .subject = command.derive.ancestor,
                        .section = .{ .summary = .{} },
                    } },
                    .page = .{},
                } } };
                try self.validateWorkspaceReadIn(
                    a,
                    parent,
                    inspect,
                    input.derive.basis,
                    records,
                    controller_read,
                    checked,
                );
                return;
            }
            if (command != .validate or
                input != .validate or
                controller_read != null)
                return error.InvalidArchive;
            var candidate = try self.workspaceCandidate(
                a,
                parent.id,
                try wp.identity(command.validate.candidate, .candidate),
            );
            defer candidate.deinit();
            if (!std.meta.eql(candidate.value.artifact, input.validate.candidate_ref))
                return error.InvalidArchive;
            try requireArchiveRecord(records, .workspace_candidate, candidate.value.id);
        }
        fn validateSemanticPublication(
            self: *Self,
            parent: state.Task,
            selected: @FieldType(workspace.PublicationCommand, "semantic"),
            admission: WorkspaceAdmission,
            records: []const state.ArchiveRecord,
            event_seq: u64,
            controller_read: ?state.ControllerReadCut,
            checked: *SnapshotValidation,
        ) !void {
            var arena = std.heap.ArenaAllocator.init(self.allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var phase: []const u8 = "input";
            errdefer std.debug.print("semantic publication: {s}\n", .{phase});
            const input_bytes = try self.store().object(a, selected.input, null);
            defer a.free(input_bytes);
            var input = try contracts.decodeOwned(build_job.Input, a, input_bytes);
            defer input.deinit();
            if (input.value == .derive) try validateSemanticReadPosition(
                input.value.derive.basis,
                event_seq,
            );
            try self.validateSemanticInput(
                a,
                parent,
                selected.command,
                input.value,
                records,
                controller_read,
                checked,
            );
            phase = "frozen input";
            const frozen = try self.workspacePrepareSemanticBuild(
                a,
                parent,
                selected.command,
                if (input.value == .derive) input.value.derive.basis else null,
            );
            defer a.free(frozen);
            if (!same(frozen, input_bytes)) return error.InvalidArchive;
            const output_bytes = try self.store().object(a, selected.output, null);
            defer a.free(output_bytes);
            phase = "compiler output";
            try self.validateCompilerOutput(parent.id, input_bytes, output_bytes);
            phase = "retained observation";
            var output = try contracts.decodeOwned(build_job.Output, a, output_bytes);
            defer output.deinit();
            const observed = try self.retainedSemanticObservation(
                a,
                parent.id,
                input.value,
                output.value,
                selected.output,
            );
            const expected = try contracts.encodeOwned(workspace.SemanticObservation, a, observed);
            defer a.free(expected);
            const reference = admission.observation orelse return error.InvalidArchive;
            if (!std.meta.eql(reference, state.Reference{
                .digest = storage.digest(expected),
                .bytes = expected.len,
            }) or !std.meta.eql(
                admission.work,
                if (observed.candidate) |ref| ref.digest else reference.digest,
            ))
                return error.InvalidArchive;
        }
        fn validateCompilerOutput(
            self: *Self,
            task_id: state.TaskId,
            input: []const u8,
            output: []const u8,
        ) !void {
            const fact: CompilerFact = .{
                .kind = .output,
                .input = compilerReference(input),
                .output = compilerReference(output),
            };
            if (try self.compilerFact(fact)) return;
            const a = self.allocator;
            var frozen = try contracts.decodeOwned(build_job.Input, a, input);
            defer frozen.deinit();
            var actual = try contracts.decodeOwned(build_job.Output, a, output);
            defer actual.deinit();
            if (actual.value == .validation) switch (actual.value.validation.outcome) {
                .resource_exhausted, .interrupted, .unavailable_dependency => {
                    if (frozen.value != .validate or
                        actual.value.validation.code.bytes.len == 0)
                        return error.InvalidArchive;
                    try self.retainCompilerFact(fact);
                    return;
                },
                else => {},
            };
            const task_name = std.fmt.bytesToHex(task_id, .lower);
            const expected_bytes = try build_job.run(.{
                .allocator = a,
                .io = self.io,
                .authority = &self.profile.authority,
                .task_id = &task_name,
                .profile = self.profile.bytes,
                .environment = null,
            }, input);
            defer a.free(expected_bytes);
            var expected = try contracts.decodeOwned(build_job.Output, a, expected_bytes);
            defer expected.deinit();
            switch (expected.value) {
                inline else => |*value| value.compiler_nanoseconds = 0,
            }
            switch (actual.value) {
                inline else => |*value| value.compiler_nanoseconds = 0,
            }
            const expected_value = try contracts.encodeOwned(build_job.Output, a, expected.value);
            defer a.free(expected_value);
            const actual_value = try contracts.encodeOwned(build_job.Output, a, actual.value);
            defer a.free(actual_value);
            if (!same(expected_value, actual_value)) return error.InvalidArchive;
            try self.retainCompilerFact(fact);
            try self.retainCompilerOutputEvidence(a, frozen.value, actual.value);
        }
        fn retainCompilerOutputEvidence(
            self: *Self,
            a: std.mem.Allocator,
            frozen: build_job.Input,
            actual: build_job.Output,
        ) !void {
            if (frozen == .derive and actual == .derived) {
                const description = semanticCandidateDescription(
                    frozen.derive,
                    actual.derived.artifact.bytes,
                );
                const bytes = try contracts.encodeOwned(
                    workspace.CandidateArtifact,
                    a,
                    description,
                );
                defer a.free(bytes);
                try self.retainCompilerFact(.{
                    .kind = .candidate,
                    .input = compilerReference(bytes),
                    .output = description.code,
                });
            } else if (frozen == .validate and
                actual == .validation and
                actual.validation.outcome == .validated)
            {
                const selected = frozen.validate;
                try self.retainCompilerFact(try runtimeCompilerFact(a, compilerReference(
                    selected.candidate.bytes,
                ), .{
                    .candidate = selected.candidate_ref,
                    .ancestor = compilerReference(selected.ancestor.bytes),
                    .guest = selected.guest,
                    .root = selected.root,
                    .checker = selected.checker,
                }));
            }
        }
        fn workspaceSemanticCommand(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            command: wc.Program,
        ) !Admission {
            const request = try operation(workspace.SemanticRequest, a, .{
                .task = task_id,
                .command = command,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            const input_bytes = try self.workspacePrepareSemanticBuild(
                a,
                parent.value,
                command,
                null,
            );
            defer a.free(input_bytes);
            const task_name = std.fmt.bytesToHex(task_id, .lower);
            if (self.store().transaction) return error.CompilerPreparationRequired;
            const output_bytes = try build_job.run(.{
                .allocator = a,
                .io = self.io,
                .authority = &self.profile.authority,
                .task_id = &task_name,
                .profile = self.profile.bytes,
                .environment = null,
            }, input_bytes);
            defer a.free(output_bytes);
            var input = try contracts.decodeOwned(build_job.Input, a, input_bytes);
            defer input.deinit();
            var output = try contracts.decodeOwned(build_job.Output, a, output_bytes);
            defer output.deinit();
            try self.store().begin();
            defer self.store().rollback();
            const observed = try self.workspaceStoreSemantic(
                a,
                task_id,
                input.value,
                output.value,
                output_bytes,
            );
            const observed_bytes = try contracts.encodeOwned(
                workspace.SemanticObservation,
                a,
                observed,
            );
            defer a.free(observed_bytes);
            const observation = try self.store().putObject(observed_bytes);
            return self.workspaceCommit(
                a,
                parent.value,
                operation_id,
                request,
                if (observed.candidate) |ref| ref.digest else observation.digest,
                .candidate,
                observation,
                .{ .semantic = .{
                    .command = command,
                    .input = try self.store().putObject(input_bytes),
                    .output = observed.output,
                } },
            );
        }
        fn workspaceStoreSemantic(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            input: build_job.Input,
            output: build_job.Output,
            output_bytes: []const u8,
        ) !workspace.SemanticObservation {
            const result: workspace.SemanticObservation = .{
                .candidate = null,
                .runtime = null,
                .output = try self.store().putObject(output_bytes),
            };
            switch (output) {
                .rejected => return result,
                .derived => |derived| {
                    if (input != .derive) return error.InvalidCandidate;
                    var observed = result;
                    observed.candidate = try self.workspaceStoreCandidate(
                        a,
                        task_id,
                        input.derive,
                        derived.artifact.bytes,
                    );
                    return observed;
                },
                .validation => |validation| {
                    if (input != .validate) return error.InvalidCandidate;
                    var observed = result;
                    observed.candidate = input.validate.candidate_ref;
                    if (validation.outcome == .validated) {
                        observed.runtime = try self.workspaceStoreValidation(
                            a,
                            task_id,
                            input.validate,
                        );
                    }
                    return observed;
                },
                .compiled, .rejected_contract => return error.InvalidCandidate,
            }
        }
        fn workspaceStoreCandidate(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            input: build_job.DeriveInput,
            code: []const u8,
        ) !state.Reference {
            var admitted = try kosmos.RuntimeArtifact.init(a, code, storage.digest(code));
            defer admitted.deinit();
            const lineage = admitted.content.value.lineage orelse return error.InvalidCandidate;
            if (!std.meta.eql(lineage.parent, storage.digest(input.ancestor.bytes)) or
                !std.meta.eql(lineage.root, input.root) or
                !same(lineage.checker, input.checker.bytes))
                return error.InvalidCandidate;
            _ = try self.store().putObject(input.ancestor.bytes);
            _ = try self.store().putObject(input.guest.bytes);
            _ = try self.store().putObject(input.proposal.bytes);
            _ = try self.store().putObject(code);
            const description = semanticCandidateDescription(input, code);
            const bytes = try contracts.encodeOwned(workspace.CandidateArtifact, a, description);
            defer a.free(bytes);
            const artifact = try self.store().putObject(bytes);
            const id = try workspaceContentCustody(a, task_id, artifact.digest);
            const value: workspace.Candidate = .{
                .id = id,
                .task = task_id,
                .program = input.program,
                .artifact = artifact,
                .description = description,
            };
            if (try self.store().recordBytes(a, "workspace_candidate", id, task_id)) |prior| {
                defer a.free(prior);
                var saved = try contracts.decodeOwned(workspace.Candidate, a, prior);
                defer saved.deinit();
                var canonical = value;
                canonical.program = saved.value.program;
                const expected = try contracts.encodeOwned(workspace.Candidate, a, canonical);
                defer a.free(expected);
                if (!same(prior, expected)) return error.InvalidCandidate;
            } else try self.store().createRecord(
                workspace.Candidate,
                "workspace_candidate",
                id,
                task_id,
                value,
            );
            return artifact;
        }
        fn semanticCandidateDescription(
            input: build_job.DeriveInput,
            code: []const u8,
        ) workspace.CandidateArtifact {
            return .{
                .ancestor = .{
                    .digest = storage.digest(input.ancestor.bytes),
                    .bytes = input.ancestor.bytes.len,
                },
                .guest = .{
                    .digest = storage.digest(input.guest.bytes),
                    .bytes = input.guest.bytes.len,
                },
                .proposal = .{
                    .digest = storage.digest(input.proposal.bytes),
                    .bytes = input.proposal.bytes.len,
                },
                .code = .{ .digest = storage.digest(code), .bytes = code.len },
                .producer = input.producer,
                .root = input.root,
                .checker = input.checker,
            };
        }
        fn retainedSemanticObservation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            input: build_job.Input,
            output: build_job.Output,
            output_ref: state.Reference,
        ) !workspace.SemanticObservation {
            var result: workspace.SemanticObservation = .{
                .candidate = null,
                .runtime = null,
                .output = output_ref,
            };
            switch (output) {
                .rejected => {},
                .derived => |derived| {
                    if (input != .derive) return error.InvalidArchive;
                    const description = semanticCandidateDescription(
                        input.derive,
                        derived.artifact.bytes,
                    );
                    const bytes = try contracts.encodeOwned(
                        workspace.CandidateArtifact,
                        a,
                        description,
                    );
                    defer a.free(bytes);
                    var candidate = try self.workspaceCandidate(a, task_id, storage.digest(bytes));
                    defer candidate.deinit();
                    result.candidate = candidate.value.artifact;
                },
                .validation => |validation| {
                    if (input != .validate) return error.InvalidArchive;
                    var candidate = try self.workspaceCandidate(
                        a,
                        task_id,
                        input.validate.candidate_ref.digest,
                    );
                    defer candidate.deinit();
                    if (!std.meta.eql(candidate.value.artifact, input.validate.candidate_ref))
                        return error.InvalidArchive;
                    result.candidate = candidate.value.artifact;
                    if (validation.outcome == .validated) {
                        var runtime = try self.workspaceRuntime(
                            a,
                            task_id,
                            candidate.value.description.code.digest,
                            candidate.value.program,
                        );
                        defer runtime.deinit();
                        result.runtime = runtime.record.value.artifact;
                    }
                },
                .compiled, .rejected_contract => return error.InvalidArchive,
            }
            return result;
        }
        fn workspaceStoreValidation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            input: build_job.ValidateInput,
        ) !state.Reference {
            var candidate = try self.workspaceCandidate(a, task_id, input.candidate_ref.digest);
            defer candidate.deinit();
            const d = candidate.value.description;
            if (!std.meta.eql(d.root, input.root) or !std.meta.eql(d.guest, input.guest) or
                !std.meta.eql(d.code.digest, storage.digest(input.candidate.bytes)) or
                !std.meta.eql(d.ancestor.digest, storage.digest(input.ancestor.bytes)) or
                !same(d.checker.bytes, input.checker.bytes)) return error.InvalidCandidate;
            const id = try workspaceContentCustody(a, task_id, d.code.digest);
            const value: workspace.Runtime = .{
                .id = id,
                .task = task_id,
                .program = candidate.value.program,
                .artifact = d.code,
                .validation = .{
                    .candidate = candidate.value.artifact,
                    .ancestor = d.ancestor,
                    .guest = d.guest,
                    .root = d.root,
                    .checker = d.checker,
                },
            };
            if (try self.store().recordBytes(a, "workspace_runtime", id, task_id)) |prior| {
                defer a.free(prior);
                var saved = try contracts.decodeOwned(workspace.Runtime, a, prior);
                defer saved.deinit();
                var canonical = value;
                const validation = saved.value.validation orelse return error.InvalidRuntime;
                canonical.program = saved.value.program;
                canonical.validation.?.candidate = validation.candidate;
                const expected = try contracts.encodeOwned(workspace.Runtime, a, canonical);
                defer a.free(expected);
                if (!same(prior, expected)) return error.InvalidRuntime;
            } else try self.store().createRecord(
                workspace.Runtime,
                "workspace_runtime",
                id,
                task_id,
                value,
            );
            return d.code;
        }
        fn workspaceSemanticObservation(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            observed: workspace.SemanticObservation,
        ) !json.Value {
            const output_bytes = try self.store().object(a, observed.output, null);
            defer a.free(output_bytes);
            var decoded = try contracts.decodeOwned(build_job.Output, a, output_bytes);
            defer decoded.deinit();
            const output = decoded.value;
            var result = json.object();
            if (observed.candidate) |ref| {
                var candidate = try self.workspaceCandidate(a, task_id, ref.digest);
                defer candidate.deinit();
                result = try self.workspaceCandidateObservation(a, candidate.value);
            }
            switch (output) {
                .rejected => |failure| {
                    try json.put(
                        a,
                        &result,
                        "error",
                        json.string(try a.dupe(u8, failure.code.bytes)),
                    );
                    try json.put(a, &result, "construction", json.string("rejected"));
                },
                .derived => {},
                .validation => |validation| {
                    try json.put(
                        a,
                        &result,
                        "validation",
                        json.string(@tagName(validation.outcome)),
                    );
                    try json.put(a, &result, "diagnostic", json.string(
                        try a.dupe(u8, validation.code.bytes),
                    ));
                },
                .compiled, .rejected_contract => return error.InvalidCandidate,
            }
            if (observed.runtime) |ref| {
                try json.put(a, &result, "runtime", try values.toJson(
                    wc.Ref,
                    a,
                    try wp.reference(a, .runtime, ref.digest),
                ));
                try json.put(a, &result, "runtime_authority", .{ .bool = true });
            }
            const compiler_nanoseconds = switch (output) {
                inline else => |value| value.compiler_nanoseconds,
            };
            try json.put(
                a,
                &result,
                "compiler_nanoseconds",
                try json.number(a, compiler_nanoseconds),
            );
            return result;
        }
        fn workspaceBuildReply(
            self: *Self,
            a: std.mem.Allocator,
            program: ?state.Reference,
            output: build_job.Output,
        ) !wc.Reply {
            var observation = json.object();
            if (output.rejection()) |failure| {
                try json.put(
                    a,
                    &observation,
                    "compiler_nanoseconds",
                    try json.number(a, failure.compiler_nanoseconds),
                );
                try json.put(
                    a,
                    &observation,
                    "error",
                    json.string(try a.dupe(u8, failure.code.bytes)),
                );
                try json.put(
                    a,
                    &observation,
                    "phase",
                    json.string(try a.dupe(u8, failure.phase.bytes)),
                );
                try json.put(
                    a,
                    &observation,
                    "function",
                    try values.toJson(?u64, a, failure.function),
                );
                try json.put(a, &observation, "term", try values.toJson(?u64, a, failure.term));
                try json.put(a, &observation, "value", try values.toJson(?u64, a, failure.value));
                if (output == .rejected_contract) {
                    try json.put(
                        a,
                        &observation,
                        "continuation_contract",
                        try values.toJson(
                            build_job.ContinuationDiagnostic,
                            a,
                            output.rejected_contract.continuation,
                        ),
                    );
                }
                return .{ .disposition = .rejected, .observation_json = .{
                    .bytes = try json.canonical(a, observation),
                } };
            }
            const saved = program orelse return error.CorruptState;
            var artifact = try contracts.decodeOwned(
                workspace.ProgramArtifact,
                a,
                try self.store().object(a, saved, null),
            );
            defer artifact.deinit();
            observation = try self.workspaceProgramObservation(a, saved.digest, artifact.value);
            try json.put(
                a,
                &observation,
                "compiler_nanoseconds",
                try json.number(a, output.compiled.compiler_nanoseconds),
            );
            return .{ .disposition = .admitted, .program = try wp.reference(
                a,
                .program,
                saved.digest,
            ), .observation_json = .{ .bytes = try json.canonical(a, observation) } };
        }
        fn interpretWorkspaceBuild(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt: state.Attempt,
            raw: state.Capture,
        ) !Step {
            const rendered = try self.store().object(a, raw.request, null);
            defer a.free(rendered);
            var input = try contracts.decodeOwned(build_job.Input, a, rendered);
            defer input.deinit();
            const response = try self.store().object(a, raw.response.?, null);
            defer a.free(response);
            var output = try contracts.decodeOwned(build_job.Output, a, response);
            defer output.deinit();
            if (input.value != .program) return self.interpretWorkspaceSemantic(
                a,
                initial,
                pending,
                attempt,
                raw,
                input.value,
                output.value,
                response,
            );
            return self.interpretWorkspaceProgram(
                a,
                initial,
                pending,
                attempt,
                raw,
                input.value,
                output.value,
            );
        }
        fn interpretWorkspaceProgram(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt: state.Attempt,
            raw: state.Capture,
            input: build_job.Input,
            output: build_job.Output,
        ) !Step {
            var parent = initial;
            parent.revision = try std.math.add(u64, parent.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            const program: ?state.Reference =
                if (output ==
                .compiled) try self.workspaceStoreProgram(
                    a,
                    initial.id,
                    input.program.source.bytes,
                    @fromBackingInt(@intCast(@backingInt(input.program.kind))),
                    if (input.program.catalog) |bytes| .{
                        .digest = storage.digest(bytes.bytes),
                        .bytes = bytes.bytes.len,
                    } else null,
                    input.program.exposures.items,
                    output.compiled,
                ) else null;
            const reply = try self.workspaceBuildReply(a, program, output);
            const payload = try contracts.encodeOwned(wc.Reply, a, reply);
            defer a.free(payload);
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = payload,
            });
            defer a.free(bound);
            const next = try occurrence.acquired(
                pending,
                .{ .id = pending.id, .task = initial.id, .request = pending.request },
                attempt.id,
                storage.digest(bound),
            );
            var projected = raw;
            projected.projection = .{
                .reply = try self.store().putObject(bound),
                .objects = .{ .items = &.{} },
                .output_tokens = null,
            };
            try self.store().putRecord(state.Capture, "capture", attempt.id, initial.id, projected);
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                initial.id,
                next,
            );
            // The retained capture/reply owns the program observation. A
            // second journal projection has no independent publication fact.
            try self.persist(a, parent, initial.revision, "workspace.build", .preserve);
            if (program) |saved| try self.checked_workspace_programs.put(
                self.allocator,
                saved.digest,
                self.store().integrity_epoch,
            );
            return .progressed;
        }
        fn interpretWorkspaceSemantic(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt: state.Attempt,
            raw: state.Capture,
            input: build_job.Input,
            output: build_job.Output,
            response: []const u8,
        ) !Step {
            switch (output) {
                .derived => {
                    if (input != .derive) return error.InvalidCandidate;
                    var guest = try self.workspaceProgram(a, initial.id, input.derive.program);
                    guest.deinit();
                },
                .validation => {
                    if (input != .validate) return error.InvalidCandidate;
                    var candidate = try self.workspaceCandidate(
                        a,
                        initial.id,
                        input.validate.candidate_ref.digest,
                    );
                    candidate.deinit();
                },
                .rejected => {},
                .compiled, .rejected_contract => return error.InvalidCandidate,
            }
            var parent = initial;
            parent.revision = try std.math.add(u64, parent.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            const observed = try self.workspaceStoreSemantic(
                a,
                initial.id,
                input,
                output,
                response,
            );
            const reply = try self.workspaceSemanticReply(a, initial.id, observed);
            const payload = try contracts.encodeOwned(wc.Reply, a, reply);
            defer a.free(payload);
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = payload,
            });
            defer a.free(bound);
            const next = try occurrence.acquired(pending, .{
                .id = pending.id,
                .task = initial.id,
                .request = pending.request,
            }, attempt.id, storage.digest(bound));
            var projected = raw;
            projected.projection = .{
                .reply = try self.store().putObject(bound),
                .objects = .{ .items = &.{} },
                .output_tokens = null,
            };
            try self.store().putRecord(state.Capture, "capture", attempt.id, initial.id, projected);
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                initial.id,
                next,
            );
            try self.persist(a, parent, initial.revision, "workspace.semantic", .preserve);
            return .progressed;
        }
        fn workspaceSemanticReply(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            observed: workspace.SemanticObservation,
        ) !wc.Reply {
            const observation = try self.workspaceSemanticObservation(a, task_id, observed);
            return .{
                .disposition = if (observation.object.contains("error")) .rejected else .admitted,
                .observation_json = .{ .bytes = try json.canonical(a, observation) },
                .evidence = if (observation.object.get("runtime") orelse
                    observation.object.get("candidate")) |ref|
                    try values.fromJson(wc.Ref, a, ref)
                else
                    null,
            };
        }
        fn workspaceWaitReady(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            selection: @FieldType(wc.Work, "wait"),
        ) !bool {
            var ready = parent.messages.items.len != 0 or parent.cancellation != null;
            for (selection.works.items) |ref| {
                var work = try self.workspaceWork(a, parent.id, try wp.identity(ref, .work));
                defer work.deinit();
                ready = ready or
                    work.value.event_watermark > selection.after or
                    work.value.terminal();
            }
            return ready;
        }
        fn workspaceWaitWakeups(
            self: *Self,
            a: std.mem.Allocator,
            parent: *state.Task,
            ownership: Ownership,
            wake: *std.ArrayList(workspace.Subject),
        ) !void {
            if (!try self.hasLocalCustody(a, parent.id, null)) return;
            var owned = ownership == .acquire;
            for (self.owned.items) |id| owned = owned or std.meta.eql(id, parent.id);
            if (!owned) return;
            // Custody can retain cancellation while this launch cannot execute
            // the task. Journal writes must not turn that ownership into a wake.
            self.compatible(parent.*) catch |err| switch (err) {
                error.IncompatibleProfile => return,
            };
            if (!parent.terminal()) if (parent.current_occurrence) |id| {
                if (try self.workspaceWaitReadyAt(a, parent.*, id))
                    try wake.append(a, .{ .task = parent.id });
            };
            const ids = try self.controllerResidualIds(a, parent.id);
            defer a.free(ids);
            for (ids) |id| {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    id,
                    parent.id,
                );
                defer residual.deinit();
                if (residual.value.schedule != .parked or
                    residual.value.blocker != .waiting_workspace or
                    !residual.value.cancellation_applied)
                    continue;
                const current = residual.value.current_occurrence orelse continue;
                if (!try self.workspaceWaitReadyAt(a, parent.*, current)) continue;
                residual.value.schedule = .queued;
                residual.value.blocker = null;
                try self.store().putRecord(
                    state.ControllerResidual,
                    "controller_residual",
                    id,
                    parent.id,
                    residual.value,
                );
                try self.residualProgressEvent(a, parent, residual.value);
                try wake.append(a, .{ .task = parent.id, .residual = id });
            }
        }
        fn workspaceWaitReadyAt(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            id: state.Digest,
        ) !bool {
            const bytes = (try self.store().recordBytes(
                a,
                "workspace_wait",
                id,
                parent.id,
            )) orelse return false;
            defer a.free(bytes);
            var waiting = try contracts.decodeOwned(workspace.Wait, a, bytes);
            defer waiting.deinit();
            var pending = try self.record(occurrence.Occurrence, a, "occurrence", id, parent.id);
            defer pending.deinit();
            if (pending.value.state != .ready) return false;
            return self.workspaceWaitReady(a, parent, waiting.value.selection);
        }
        fn settleWorkspaceReply(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            pending: occurrence.Occurrence,
            observation: wc.Reply,
            evidence: workspace.ReplyEvidence,
        ) !Step {
            const reply = try contracts.encodeOwned(wc.Reply, a, observation);
            defer a.free(reply);
            const bound = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = reply,
            });
            defer a.free(bound);
            // Workspace mutation may have advanced only the parent's control
            // journal. Its root occurrence and checkpoint remain unchanged.
            var fresh = try self.task(a, initial.id);
            defer fresh.deinit();
            var parent = fresh.value;
            if (!std.meta.eql(
                parent.current_occurrence,
                initial.current_occurrence,
            )) return error.StaleOccurrence;
            const attempt = switch (pending.state) {
                .dispatching => |dispatching| dispatching.id,
                else => return error.UnsettledOccurrence,
            };
            const binding: occurrence.Binding = .{
                .id = pending.id,
                .task = initial.id,
                .work = pending.work,
                .residual = pending.residual,
                .request = pending.request,
            };
            const acquired = try occurrence.acquired(
                pending,
                binding,
                attempt,
                storage.digest(bound),
            );
            parent.revision = try std.math.add(u64, parent.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.storeWorkspaceReply(initial, pending, attempt, evidence, acquired, bound);
            try self.publishWorkspaceRead(a, &parent, fresh.value, pending, evidence);
            try self.effectSchedule(a, &parent, pending, .queued, null);
            try self.persistOccurrence(
                a,
                parent,
                fresh.value.revision,
                "workspace.reply",
                pending,
                true,
            );
            return .progressed;
        }
        fn storeWorkspaceReply(
            self: *Self,
            initial: state.Task,
            pending: occurrence.Occurrence,
            attempt: @FieldType(state.Attempt, "id"),
            evidence: workspace.ReplyEvidence,
            acquired: occurrence.Occurrence,
            bound: []const u8,
        ) !void {
            _ = try self.store().putObject(bound);
            try self.store().createRecord(
                workspace.ReplyObservation,
                "workspace_reply",
                pending.id,
                initial.id,
                .{
                    .id = pending.id,
                    .task = initial.id,
                    .attempt = attempt,
                    .request = pending.request_object,
                    .evidence = evidence,
                },
            );
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                initial.id,
                acquired,
            );
        }
        fn publishWorkspaceRead(
            self: *Self,
            a: std.mem.Allocator,
            parent: *state.Task,
            fresh: state.Task,
            pending: occurrence.Occurrence,
            evidence: workspace.ReplyEvidence,
        ) !void {
            if (evidence == .read and evidence.read != .immutable) {
                var event_data = json.object();
                try json.put(
                    a,
                    &event_data,
                    "occurrence_id",
                    json.string(try a.dupe(u8, &std.fmt.bytesToHex(pending.id, .lower))),
                );
                const cut: ?state.ControllerReadCut = if (evidence.read == .controller) .from(
                    fresh,
                ) else null;
                try validateControllerReadCut(evidence.read, cut);
                try self.subjectPublicationEvent(
                    parent,
                    .workspace_read,
                    try json.canonical(a, event_data),
                    &.{},
                    &.{},
                    null,
                    cut,
                    null,
                );
            }
        }
        fn retainValidatedRuntime(
            self: *Self,
            admitted: *const kosmos.RuntimeArtifact,
            fact: CompilerFact,
        ) !void {
            var retained = try admitted.clone();
            errdefer retained.deinit();
            try self.checked_workspace_runtimes.put(
                self.allocator,
                fact,
                self.store().integrity_epoch,
            );
            const compiled = if (self.runtime_cache) |cached|
                cached.compiled and cached.epoch == self.store().integrity_epoch and
                    std.meta.eql(cached.artifact.identity, admitted.identity)
            else
                false;
            if (self.runtime_cache) |*cached| cached.artifact.deinit();
            self.runtime_cache = .{
                .epoch = self.store().integrity_epoch,
                .artifact = retained,
                .compiled = compiled,
            };
        }
        fn compileWorkspaceRuntime(
            self: *Self,
            guest: *const data.program_image.Admitted,
            hooks: wc.RuntimeHooks,
        ) ![]u8 {
            const instrumentation: kosmos.RuntimeInstrumentation.Hooks = .{
                .control = hooks.control,
                .storage = hooks.storage,
            };
            if (self.runtime_cache) |*cached| {
                const bundle = cached.artifact.content.value;
                if (cached.compiled and cached.epoch == self.store().integrity_epoch and
                    bundle.guest != null and std.meta.eql(bundle.guest.?, guest.identity()) and
                    std.meta.eql(bundle.hooks, instrumentation))
                    return cached.artifact.encode(self.allocator);
            }
            return kosmos.RuntimeCompiler.compile(self.allocator, .{
                .guest = guest,
                .horos_package = @import("native_options").horos_identity,
                .hooks = instrumentation,
            });
        }
        fn runtimeCompilerFact(
            a: std.mem.Allocator,
            reference: state.Reference,
            validation: ?workspace.ValidationFact,
        ) !CompilerFact {
            const bytes = try contracts.encodeOwned(?workspace.ValidationFact, a, validation);
            defer a.free(bytes);
            return .{
                .kind = .runtime,
                .input = reference,
                .output = if (validation) |fact| fact.ancestor else .{
                    .digest = @splat(0),
                    .bytes = 0,
                },
                .context = storage.digest(bytes),
            };
        }
        fn validateRuntimeCompiler(
            self: *Self,
            a: std.mem.Allocator,
            reference: state.Reference,
            validation: ?workspace.ValidationFact,
            admitted: *const kosmos.RuntimeArtifact,
            source: anytype,
        ) !void {
            const fact = try runtimeCompilerFact(a, reference, validation);
            if (try self.compilerFact(fact)) return;
            if (admitted.content.value.lineage != null) {
                const declared = validation orelse return error.InvalidRuntime;
                const bytes = try source.object(a, declared.ancestor, null);
                defer a.free(bytes);
                var ancestor = try kosmos.RuntimeArtifact.init(a, bytes, declared.ancestor.digest);
                defer ancestor.deinit();
                try kosmos.RuntimeCompiler.validateAgainst(a, admitted, &ancestor);
            } else {
                if (validation != null) return error.InvalidRuntime;
                try kosmos.RuntimeCompiler.validate(a, admitted);
            }
            try self.retainCompilerFact(fact);
        }
        fn workspaceRuntime(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            digest: state.Digest,
            program_id: ?state.Digest,
        ) !SelectedRuntime {
            const id = try workspaceContentCustody(a, task_id, digest);
            var saved = try self.record(workspace.Runtime, a, "workspace_runtime", id, task_id);
            errdefer saved.deinit();
            if (!std.meta.eql(saved.value.id, id) or
                !std.meta.eql(saved.value.task, task_id) or
                !std.meta.eql(
                    saved.value.artifact.digest,
                    digest,
                )) return error.InvalidRuntime;
            var program = try self.workspaceProgram(a, task_id, saved.value.program);
            defer program.deinit();
            if (program_id) |required| if (!std.meta.eql(required, saved.value.program)) {
                var requested = try self.workspaceProgram(a, task_id, required);
                defer requested.deinit();
                if (!std.meta.eql(
                    requested.value.description.image,
                    program.value.description.image,
                )) return error.InvalidRuntime;
            };
            const image = try self.store().object(a, program.value.description.image, null);
            defer a.free(image);
            const guest = try data.program_image.Admitted.decode(a, image);
            defer guest.deinit();
            var admitted = cached: {
                if (self.runtime_cache) |*cached| {
                    if (cached.epoch == self.store().integrity_epoch and std.meta.eql(
                        cached.artifact.identity,
                        digest,
                    )) break :cached try cached.artifact.clone();
                }
                const bytes = try self.store().object(a, saved.value.artifact, null);
                defer a.free(bytes);
                break :cached try kosmos.RuntimeArtifact.init(self.allocator, bytes, digest);
            };
            errdefer admitted.deinit();
            const bound = admitted.content.value.guest orelse return error.InvalidRuntime;
            if (!std.mem.eql(u8, &bound, &guest.identity()) or !same(
                admitted.content.value.manifest.compiler.horos_package,
                @import("native_options").horos_identity,
            )) return error.InvalidRuntime;
            const fact = try runtimeCompilerFact(a, saved.value.artifact, saved.value.validation);
            if (admitted.content.value.lineage != null) {
                try self.validateDerivedRuntime(a, saved.value, &admitted);
            } else if (saved.value.validation != null) return error.InvalidRuntime;
            if (self.checked_workspace_runtimes.get(fact) != self.store().integrity_epoch) {
                try self.validateRuntimeCompiler(
                    self.allocator,
                    saved.value.artifact,
                    saved.value.validation,
                    &admitted,
                    self.store(),
                );
            }
            try self.retainValidatedRuntime(&admitted, fact);
            return .{ .record = saved, .admitted = admitted };
        }
        fn validateDerivedRuntime(
            self: *Self,
            a: std.mem.Allocator,
            value: workspace.Runtime,
            admitted: *const kosmos.RuntimeArtifact,
        ) !void {
            const fact = value.validation orelse return error.InvalidRuntime;
            if (fact.version != 1) return error.InvalidRuntime;
            var candidate = try self.workspaceCandidate(a, value.task, fact.candidate.digest);
            defer candidate.deinit();
            const d = candidate.value.description;
            if (!std.meta.eql(candidate.value.artifact, fact.candidate) or
                !std.meta.eql(d.code, value.artifact) or
                !std.meta.eql(d.ancestor, fact.ancestor) or !std.meta.eql(d.root, fact.root) or
                !std.meta.eql(d.guest, fact.guest) or !same(d.checker.bytes, fact.checker.bytes))
                return error.InvalidRuntime;
            if (!std.meta.eql(
                admitted.identity,
                value.artifact.digest,
            )) return error.InvalidRuntime;
        }
        fn workspaceRuntimeObservation(
            self: *Self,
            a: std.mem.Allocator,
            saved: workspace.Runtime,
        ) !json.Value {
            var selected = try self.workspaceRuntime(
                a,
                saved.task,
                saved.artifact.digest,
                saved.program,
            );
            defer selected.deinit();
            if (!data.record.equal(workspace.Runtime, saved, selected.record.value))
                return error.InvalidRuntime;
            const bundle = selected.admitted.content.value;
            var result = json.object();
            try json.put(
                a,
                &result,
                "runtime",
                try values.toJson(wc.Ref, a, try wp.reference(a, .runtime, saved.artifact.digest)),
            );
            try json.put(
                a,
                &result,
                "origin_program",
                try values.toJson(wc.Ref, a, try wp.reference(a, .program, saved.program)),
            );
            try workspaceRuntimeDetails(a, &result, saved, bundle);
            return result;
        }
        fn workspaceRuntimeDetails(
            a: std.mem.Allocator,
            result: *json.Value,
            saved: workspace.Runtime,
            bundle: @FieldType(@FieldType(kosmos.RuntimeArtifact, "content"), "value"),
        ) !void {
            try json.put(
                a,
                result,
                "guest",
                json.string(try a.dupe(u8, &std.fmt.bytesToHex(bundle.guest.?, .lower))),
            );
            try json.put(
                a,
                result,
                "source",
                json.string(try a.dupe(u8, &std.fmt.bytesToHex(bundle.manifest.source, .lower))),
            );
            try json.put(
                a,
                result,
                "base",
                json.string(try a.dupe(u8, bundle.manifest.requirements.base)),
            );
            try json.put(
                a,
                result,
                "admission",
                json.string(try a.dupe(u8, bundle.manifest.requirements.admission)),
            );
            try json.put(
                a,
                result,
                "bridge",
                json.string(try a.dupe(u8, bundle.manifest.requirements.bridge)),
            );
            try json.put(a, result, "artifact_bytes", try json.number(a, saved.artifact.bytes));
            try json.put(a, result, "code_bytes", try json.number(a, bundle.image.len));
            try json.put(
                a,
                result,
                "approval",
                json.string("exact-source-and-independent-derivation"),
            );
            try json.put(a, result, "hydration", json.string("canonical-guest-cut"));
            try json.put(
                a,
                result,
                "hooks",
                try values.toJson(kosmos.RuntimeInstrumentation.Hooks, a, bundle.hooks),
            );
            try json.put(
                a,
                result,
                "trace_failure_policy",
                json.string("publication-fences-owner-and-retains-prior-durable-cut"),
            );
        }
        pub fn workspaceSpecialize(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            program_id: state.Digest,
        ) !Admission {
            return self.workspaceSpecializeWithHooks(a, operation_id, task_id, program_id, .{});
        }
        pub fn workspaceSpecializeWithHooks(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            program_id: state.Digest,
            hooks: wc.RuntimeHooks,
        ) !Admission {
            const request = try operation(workspace.SpecializeRequest, a, .{
                .task = task_id,
                .program = program_id,
                .hooks = hooks,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            var program = try self.workspaceProgram(a, task_id, program_id);
            defer program.deinit();
            const image = try self.store().object(a, program.value.description.image, null);
            defer a.free(image);
            const guest = try data.program_image.Admitted.decode(a, image);
            defer guest.deinit();
            // Compiler and proof scratch ends before the next phase. Keeping it
            // in the caller's response arena retains completed work, including
            // independently decoded proofs, until that entire request ends.
            if (self.store().transaction) return error.CompilerPreparationRequired;
            const bytes = try self.compileWorkspaceRuntime(guest, hooks);
            defer self.allocator.free(bytes);
            var admitted = try kosmos.RuntimeArtifact.init(
                self.allocator,
                bytes,
                storage.digest(bytes),
            );
            defer admitted.deinit();
            try self.validateRuntimeCompiler(
                self.allocator,
                compilerReference(bytes),
                null,
                &admitted,
                self.store(),
            );
            try self.retainValidatedRuntime(
                &admitted,
                try runtimeCompilerFact(a, compilerReference(bytes), null),
            );
            self.runtime_cache.?.compiled = true;
            try self.store().begin();
            defer self.store().rollback();
            const artifact = try self.store().putObject(bytes);
            const saved = try self.storeSpecializedRuntime(a, task_id, program_id, artifact);
            const record_bytes = try contracts.encodeOwned(workspace.Runtime, a, saved);
            defer a.free(record_bytes);
            const observation = try self.store().putObject(record_bytes);
            return self.workspaceCommit(
                a,
                parent.value,
                operation_id,
                request,
                artifact.digest,
                .runtime,
                observation,
                .{ .specialize = .{ .program = program_id, .hooks = hooks } },
            );
        }
        fn storeSpecializedRuntime(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            program_id: state.Digest,
            artifact: state.Reference,
        ) !workspace.Runtime {
            const id = try workspaceContentCustody(a, task_id, artifact.digest);
            var saved: workspace.Runtime = .{
                .id = id,
                .task = task_id,
                .program = program_id,
                .artifact = artifact,
            };
            if (try self.store().recordBytes(a, "workspace_runtime", id, task_id)) |prior| {
                defer a.free(prior);
                var existing = try self.workspaceRuntime(a, task_id, artifact.digest, program_id);
                defer existing.deinit();
                saved = existing.record.value;
            } else try self.store().createRecord(
                workspace.Runtime,
                "workspace_runtime",
                id,
                task_id,
                saved,
            );
            return saved;
        }
        fn runtimeWork(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            expected: wc.Expected,
        ) !contracts.Decoded(workspace.Work) {
            try self.requireCustody(a, task_id, try wp.identity(expected.work, .work));
            var work = try self.workspaceWork(a, task_id, try wp.identity(expected.work, .work));
            errdefer work.deinit();
            if (work.value.execution_revision != expected.execution_revision or
                work.value.control_revision != expected.control_revision)
                return error.StaleRevision;
            if (work.value.current_occurrence) |id| {
                var pending = try self.record(occurrence.Occurrence, a, "occurrence", id, task_id);
                defer pending.deinit();
                if (pending.value.state == .dispatching or
                    pending.value.state == .unknown)
                    return error.UnresolvedDelivery;
            }
            return work;
        }
        pub fn workspaceGuard(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            command: @FieldType(workspace.GuardRequest, "command"),
        ) !Admission {
            const request = try operation(workspace.GuardRequest, a, .{
                .task = task_id,
                .command = command,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if (command == .guard and self.workspaceParentStopped(parent.value))
                return error.InvalidState;
            const expected = switch (command) {
                inline else => |selection| selection.expected,
            };
            var work = try self.guardWork(a, task_id, expected, command == .guard);
            defer work.deinit();
            if (command == .guard and
                (work.value.terminal() or work.value.outer_operation != null))
                return error.GuestCutUnavailable;
            switch (command) {
                .guard => |selection| {
                    if (work.value.cancellation != null) return error.InvalidState;
                    if (work.value.guard != null) return error.GuardAlreadyActive;
                    if (selection.realization_revision != work.value.realization_revision)
                        return error.StaleRevision;
                    work.value.guard = try self.workspaceGuardBinding(
                        a,
                        work.value,
                        selection.candidate,
                    );
                },
                .unguard => |selection| {
                    const guard = work.value.guard orelse return error.GuardUnavailable;
                    if (selection.guard_revision != guard.revision) return error.StaleRevision;
                    work.value.guard = null;
                },
            }
            work.value.control_revision = try std.math.add(u64, work.value.control_revision, 1);
            work.value.event_watermark = try std.math.add(u64, parent.value.event_high, 1);
            try self.store().begin();
            defer self.store().rollback();
            const id = work.value.id;
            try self.writeWorkspaceWork(&work.value, .replace);
            const publication: workspace.PublicationCommand = switch (command) {
                .guard => |selection| .{ .guard = selection },
                .unguard => |selection| .{ .unguard = selection },
            };
            const snapshot = try self.snapshotRecord(
                workspace.Work,
                a,
                "workspace_work",
                id,
                task_id,
            );
            return self.workspaceCommit(
                a,
                parent.value,
                operation_id,
                request,
                work.value.id,
                .work,
                snapshot,
                publication,
            );
        }
        fn guardWork(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            expected: wc.Expected,
            enabling: bool,
        ) !contracts.Decoded(workspace.Work) {
            if (enabling) return self.runtimeWork(a, task_id, expected);
            const id = try wp.identity(expected.work, .work);
            try self.requireCustody(a, task_id, id);
            var work = try self.workspaceWork(a, task_id, id);
            errdefer work.deinit();
            if (work.value.execution_revision != expected.execution_revision or
                work.value.control_revision != expected.control_revision)
                return error.StaleRevision;
            return work;
        }
        fn workspaceGuardBinding(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            candidate_ref: wc.Ref,
        ) !workspace.Guard {
            const policy = self.profile.semantic_construction orelse
                return error.SemanticPolicyDenied;
            if (!policy.guard) return error.GuardPolicyDenied;
            var candidate = try self.workspaceCandidate(
                a,
                work.task,
                try wp.identity(candidate_ref, .candidate),
            );
            defer candidate.deinit();
            const description = candidate.value.description;
            try self.requireSemanticPolicy(description.root, description.checker.bytes);
            var program = try self.workspaceProgram(a, work.task, work.program);
            defer program.deinit();
            if (!std.meta.eql(program.value.description.image, description.guest))
                return error.GuestIdentityMismatch;
            return initialGuard(candidate.value.artifact, description.code);
        }
        fn initialGuard(candidate: state.Reference, code: state.Reference) workspace.Guard {
            return .{ .candidate = candidate, .code = code, .revision = 0 };
        }
        fn runtimeProvenance(work: workspace.Work) kosmos.RuntimeCapsule.Provenance {
            return .{ .execution = work.id, .custody = storage.digest(
                &work.task,
            ), .publication = .{
                .digest = work.checkpoint.digest,
                .bytes = work.checkpoint.bytes,
            } };
        }
        fn validateGuardSelection(
            item: state.WorkPublication,
            prior: state.WorkPublication,
            command: workspace.PublicationCommand,
        ) !void {
            const expected = switch (command) {
                .guard => |selection| selection.expected,
                .unguard => |selection| selection.expected,
                else => return error.InvalidArchive,
            };
            if (!std.meta.eql(try wp.identity(expected.work, .work), item.work) or
                expected.execution_revision != prior.execution_revision or
                expected.control_revision != prior.control_revision or
                item.execution_revision != prior.execution_revision or
                item.control_revision -| prior.control_revision != 1 or
                item.control.delivery != prior.control.delivery)
                return error.InvalidArchive;
            switch (command) {
                .guard => |selection| {
                    const guard = item.guard orelse return error.InvalidArchive;
                    if (item.control.delivery == .dispatching or item.control.delivery == .unknown)
                        return error.InvalidArchive;
                    if (prior.guard != null or
                        !equalGuards(guard, initialGuard(guard.candidate, guard.code)) or
                        selection.realization_revision != prior.realization_revision or
                        !std.meta.eql(
                            try wp.identity(selection.candidate, .candidate),
                            guard.candidate.digest,
                        )) return error.InvalidArchive;
                },
                .unguard => |selection| {
                    const guard = prior.guard orelse return error.InvalidArchive;
                    if (item.guard != null or selection.guard_revision != guard.revision)
                        return error.InvalidArchive;
                },
                else => unreachable,
            }
        }
        fn guardProgress(item: state.WorkPublication, prior: state.WorkPublication) bool {
            const next = item.guard orelse return false;
            const before = prior.guard orelse return false;
            return next.revision > before.revision and
                item.execution_revision == prior.execution_revision;
        }
        fn guardSchedule(guard: workspace.Guard, policy: workspace.RunPolicy) state.Schedule {
            return if (guard.disposition == .diverged or guard.failure != null or
                policy.continuation == .explicit_only) .parked else .queued;
        }
        fn validateGuardProgress(
            item: state.WorkPublication,
            prior: ?state.WorkPublication,
            command: ?workspace.PublicationCommand,
        ) !void {
            if (command) |selected| if (selected == .guard or selected == .unguard) return;
            const before = prior orelse {
                if (item.guard != null) return error.InvalidArchive;
                return;
            };
            if (equalGuards(item.guard, before.guard)) {
                if (item.guard != null and item.execution_revision != before.execution_revision)
                    return error.InvalidArchive;
                return;
            }
            if (item.control.cancellation != null and item.guard == null) return;
            const old = before.guard orelse return error.InvalidArchive;
            const next = item.guard orelse return error.InvalidArchive;
            if (next.revision -| old.revision != 1 or
                !std.meta.eql(next.candidate, old.candidate) or
                !std.meta.eql(next.code, old.code) or
                next.reference_nanoseconds < old.reference_nanoseconds or
                next.candidate_nanoseconds < old.candidate_nanoseconds)
                return error.InvalidArchive;
            if (item.execution_revision != before.execution_revision) {
                if (next.disposition != .agreed or next.pending_control != null or
                    next.reference_operation != null or next.candidate_segment != null or
                    next.agreed_segments -| old.agreed_segments != 1 or !next.initialized)
                    return error.InvalidArchive;
            } else {
                if ((next.disposition != .incomplete and next.disposition != .diverged) or
                    next.pending_control == null or next.agreed_segments != old.agreed_segments)
                    return error.InvalidArchive;
                if (old.pending_control) |ref|
                    if (!std.meta.eql(ref, next.pending_control.?)) return error.InvalidArchive;
            }
        }
        fn equalGuards(left: ?workspace.Guard, right: ?workspace.Guard) bool {
            var lhs = left orelse return right == null;
            var rhs = right orelse return false;
            if ((lhs.failure == null) != (rhs.failure == null)) return false;
            if (lhs.failure) |failure| if (!same(failure.bytes, rhs.failure.?.bytes)) return false;
            if ((lhs.reference_operation == null) != (rhs.reference_operation == null))
                return false;
            if (lhs.reference_operation) |*pending| {
                const other = &rhs.reference_operation.?;
                if (!std.meta.eql(pending.capsule, other.capsule) or
                    !std.meta.eql(pending.control, other.control) or
                    pending.guest_quantum != other.guest_quantum or
                    pending.dependencies.items.len != other.dependencies.items.len) return false;
                for (pending.dependencies.items, other.dependencies.items) |left_ref, right_ref|
                    if (!std.meta.eql(left_ref, right_ref)) return false;
                lhs.reference_operation = null;
                rhs.reference_operation = null;
            }
            lhs.failure = null;
            rhs.failure = null;
            return std.meta.eql(lhs, rhs);
        }
        fn validateGuardSnapshot(
            self: *Self,
            a: std.mem.Allocator,
            snapshot: workspace.WorkObservation,
            records: []const state.ArchiveRecord,
        ) !void {
            var phase: []const u8 = "candidate";
            errdefer std.debug.print("guard snapshot: {s}\n", .{phase});
            const work = snapshot.work;
            const guard = work.guard orelse return error.InvalidArchive;
            if (work.outer_operation != null or work.cancellation != null)
                return error.InvalidArchive;
            var candidate = try self.workspaceCandidate(a, work.task, guard.candidate.digest);
            defer candidate.deinit();
            if (!std.meta.eql(candidate.value.artifact, guard.candidate) or
                !std.meta.eql(candidate.value.description.code, guard.code))
                return error.InvalidArchive;
            var current = try self.workspaceWork(a, work.task, work.id);
            defer current.deinit();
            if (current.value.guard) |active|
                if (std.meta.eql(active.candidate, guard.candidate))
                    try self.requireGuardPolicy(a, current.value);
            try requireArchiveRecord(records, .workspace_candidate, candidate.value.id);
            var program = try self.workspaceProgram(a, work.task, work.program);
            defer program.deinit();
            if (!std.meta.eql(
                candidate.value.description.guest,
                program.value.description.image,
            )) return error.InvalidArchive;
            if (guard.initialized and guard.continuation == null) return error.InvalidArchive;
            if (guard.continuation != null and guard.disposition != .agreed) {
                phase = "candidate continuation";
                var candidate_execution = try self.workspaceGuardExperiment(a, work);
                defer candidate_execution.deinit();
                if (guard.initialized != (candidate_execution.stage == .advanced))
                    return error.InvalidArchive;
            }
            phase = "reference";
            try self.validateGuardReference(a, work);
            phase = "pending control";
            if (guard.pending_control) |ref| {
                const bytes = try self.store().object(a, ref, null);
                defer a.free(bytes);
                var control = try contracts.decodeOwned(data.invocation.Control, a, bytes);
                defer control.deinit();
                try validateGuardControl(snapshot, control.value);
                if (guard.guest_quantum != 1 and guard.guest_quantum != 256)
                    return error.InvalidArchive;
            } else if (guard.disposition == .incomplete or guard.disposition == .diverged)
                return error.InvalidArchive;
        }
        fn validateGuardAgreement(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            reference: *kosmos.Session,
        ) !void {
            const guard = work.guard orelse return;
            if (guard.disposition != .agreed) return;
            if (!guard.initialized or guard.continuation == null) return error.InvalidArchive;
            var candidate = try self.workspaceGuardExperiment(a, work);
            defer candidate.deinit();
            if (candidate.stage != .advanced or candidate.phase != .ready)
                return error.InvalidArchive;
            var completed = try candidate.completedSegment(a);
            defer completed.deinit();
            const observation =
                if (reference.view) |view|
                    view.event.value.observation
                else
                    .progressed;
            const expected = try contracts.encodeOwned(@TypeOf(observation), a, observation);
            defer a.free(expected);
            if (!std.meta.eql(storage.digest(completed.checkpoint), work.checkpoint.digest) or
                completed.checkpoint.len != work.checkpoint.bytes or
                completed.guest_work != work.guest_work or !same(completed.observation, expected))
                return error.InvalidArchive;
        }
        fn validateGuardReference(self: *Self, a: std.mem.Allocator, work: workspace.Work) !void {
            const guard = work.guard.?;
            if (guard.candidate_segment) |segment| {
                if (!guard.initialized or
                    guard.pending_control == null or
                    guard.continuation == null or
                    (guard.disposition != .incomplete and
                        guard.disposition != .diverged))
                    return error.InvalidArchive;
                var candidate = try self.workspaceGuardExperiment(a, work);
                defer candidate.deinit();
                if (candidate.phase != .ready or candidate.stage != .advanced or
                    candidate.guest_work != segment.guest_work) return error.InvalidArchive;
                const checkpoint = try self.store().object(a, segment.checkpoint, null);
                defer a.free(checkpoint);
                const observation = try self.store().object(a, segment.observation, null);
                defer a.free(observation);
                var completed = try candidate.completedSegment(a);
                defer completed.deinit();
                if (!same(checkpoint, completed.checkpoint) or
                    !same(observation, completed.observation) or
                    segment.guest_work != completed.guest_work) return error.InvalidArchive;
            }
            if (guard.reference_operation) |pending| {
                if (guard.candidate_segment == null or guard.pending_control == null or
                    !std.meta.eql(pending.control, guard.pending_control.?) or
                    pending.guest_quantum != guard.guest_quantum) return error.InvalidArchive;
                const bytes = try self.store().object(a, pending.capsule, null);
                defer a.free(bytes);
                const dependencies = try capsuleDependencies(a, bytes);
                defer a.free(dependencies);
                if (dependencies.len != pending.dependencies.items.len) return error.InvalidArchive;
                for (dependencies, pending.dependencies.items) |wanted, actual|
                    if (!std.meta.eql(wanted, actual)) return error.InvalidArchive;
                try self.validatePublishedCapsuleTrace(
                    a,
                    work,
                    pending.capsule,
                    work.runtime,
                    null,
                    pending,
                );
            }
        }
        fn validateGuardControl(
            snapshot: workspace.WorkObservation,
            control: data.invocation.Control,
        ) !void {
            switch (control) {
                .reply => |reply| {
                    const pending = snapshot.occurrence orelse return error.InvalidArchive;
                    if (pending.state != .settled_reply) return error.InvalidArchive;
                    const expected = pending.state.settled_reply.reply;
                    if (!std.meta.eql(expected, storage.digest(reply))) return error.InvalidArchive;
                },
                .resume_yield => if (snapshot.work.outcome_kind != .yielded)
                    return error.InvalidArchive,
                .none => if (snapshot.work.current_occurrence != null or
                    snapshot.work.outcome_kind == .yielded) return error.InvalidArchive,
                .cancel => return error.InvalidArchive,
            }
        }
        fn requireGuardPolicy(self: *Self, a: std.mem.Allocator, work: workspace.Work) !void {
            const guard = work.guard orelse return error.GuardUnavailable;
            const policy = self.profile.semantic_construction orelse return error.GuardPolicyDenied;
            if (!policy.guard) return error.GuardPolicyDenied;
            var candidate = try self.workspaceCandidate(a, work.task, guard.candidate.digest);
            defer candidate.deinit();
            try self.requireSemanticPolicy(
                candidate.value.description.root,
                candidate.value.description.checker.bytes,
            );
        }
        pub fn workspaceRequestCut(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            command: @FieldType(wc.Work, "request_cut"),
        ) !Admission {
            const request = try operation(workspace.CutRequest, a, .{
                .task = task_id,
                .command = command,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            var work = try self.runtimeWork(a, task_id, command.expected);
            defer work.deinit();
            const driver = try self.workspaceResident(a, work.value);
            const capsule_receipt = try driver.publishCapsule(a, switch (command.level) {
                .guest_cut => .guest_cut,
                .outer_execution => .outer_execution,
            }, runtimeProvenance(work.value));
            defer capsule_receipt.deinit();
            if (parent.value.observers_present) {
                var published = work.value;
                published.runtime_capsule = .{
                    .digest = storage.digest(capsule_receipt.bytes()),
                    .bytes = capsule_receipt.bytes().len,
                };
                if (try self.observerSourceRevision(a, published, .outer_execution) !=
                    try self.observerSourceRevision(a, work.value, .outer_execution))
                    try self.observerAdvanceAllowedFor(a, work.value, .outer_execution);
            }
            const code = try driver.runtimeBytes(a);
            defer a.free(code);
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(code);
            work.value.runtime_capsule = try self.store().putObject(capsule_receipt.bytes());
            work.value.runtime_dependencies = .{
                .items = try capsuleDependencies(a, capsule_receipt.bytes()),
            };
            defer a.free(work.value.runtime_dependencies.items);
            work.value.control_revision = try std.math.add(u64, work.value.control_revision, 1);
            work.value.event_watermark = parent.value.event_high + 1;
            try self.writeWorkspaceWork(&work.value, .replace);
            return self.workspaceCommit(
                a,
                parent.value,
                operation_id,
                request,
                work.value.id,
                .work,
                try self.snapshotRecord(
                    workspace.Work,
                    a,
                    "workspace_work",
                    work.value.id,
                    task_id,
                ),
                .{ .request_cut = command },
            );
        }
        fn controllerRuntimeAt(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            watermark: u64,
        ) !ControllerRuntimeCut {
            var result: ControllerRuntimeCut = .{};
            var rows = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq",
                &.{ .{ .blob = &parent.id }, .{
                    .integer = std.math.cast(i64, watermark) orelse return error.InvalidArchive,
                } },
            );
            defer rows.deinit();
            while (try rows.step() == .row) {
                var event_value = try contracts.decodeOwned(state.Event, a, try rows.bytes(0));
                defer event_value.deinit();
                if (event_value.value.kind == .controller) {
                    result = .{};
                    continue;
                }
                const reference = event_value.value.workspace_command orelse continue;
                const bytes = try self.store().object(a, reference, null);
                defer a.free(bytes);
                var command = try contracts.decodeOwned(workspace.PublicationCommand, a, bytes);
                defer command.deinit();
                if (command.value != .realize_controller) continue;
                const selected = command.value.realize_controller;
                if (selected.cut.realization_revision != result.realization_revision)
                    return error.InvalidArchive;
                result = .{
                    .runtime = selected.runtime,
                    .realization_revision = try std.math.add(u64, result.realization_revision, 1),
                };
            }
            return result;
        }
        fn validateControllerRealization(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            event_value: state.Event,
            selected: workspace.ControllerRealization,
            admission: WorkspaceAdmission,
        ) !void {
            if (!std.meta.eql(admission.work, rootIdentity(parent.id)) or event_value.seq == 0)
                return error.InvalidArchive;
            const cut = event_value.controller_read orelse return error.InvalidArchive;
            if (cut.event_watermark != event_value.seq - 1 or
                cut.execution_revision != selected.cut.execution_revision)
                return error.InvalidArchive;
            const receipt_body = try contracts.encodeOwned(
                workspace.ControllerRealization,
                a,
                selected,
            );
            defer a.free(receipt_body);
            if (!std.meta.eql(
                admission.observation,
                @as(?state.Reference, .{
                    .digest = storage.digest(receipt_body),
                    .bytes = receipt_body.len,
                }),
            ))
                return error.InvalidArchive;
            const prior = try self.controllerRuntimeAt(a, parent, event_value.seq - 1);
            if (selected.cut.realization_revision != prior.realization_revision or
                selected.cut.epoch != try self.controllerEpochAt(a, parent, event_value.seq - 1) or
                !std.meta.eql(
                    selected.controller,
                    try self.controllerAt(a, parent, event_value.seq - 1),
                ) or
                selected.cut.execution_revision > parent.execution_revision)
                return error.InvalidArchive;
            try self.validateControllerRealizationExpectation(a, parent, selected, prior);
            if (selected.command.runtime == .selected) {
                if (selected.runtime == null or !std.meta.eql(
                    selected.runtime.?.digest,
                    try wp.identity(selected.command.runtime.selected, .runtime),
                )) return error.InvalidArchive;
            } else if (selected.runtime != null) return error.InvalidArchive;
            const guest = if (selected.controller) |id|
                (try self.controllerBinding(a, parent, id)).image
            else
                parent.image;
            if (selected.dependencies.items.len != 3 or
                !std.meta.eql(selected.dependencies.items[2], guest)) return error.InvalidArchive;
            try self.validateControllerRealizationCapsules(a, parent, selected, prior, guest);
        }
        fn validateControllerRealizationCapsules(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            selected: workspace.ControllerRealization,
            prior: ControllerRuntimeCut,
            guest: state.Reference,
        ) !void {
            const bytes = try self.store().object(a, guest, null);
            defer a.free(bytes);
            const refs = [_]?state.Reference{ prior.runtime, selected.runtime };
            const capsules = [_]state.Reference{ selected.source, selected.target };
            for (refs, capsules, selected.dependencies.items[0..2]) |ref, capsule_ref, code_ref| {
                var runtime = try self.controllerRuntime(a, parent.id, guest, ref);
                defer runtime.deinit();
                if (!std.meta.eql(runtime.identity, code_ref.digest)) return error.InvalidArchive;
                var prepared = try kosmos.Prepared.initWithRuntime(a, bytes, &runtime);
                defer prepared.deinit();
                const capsule = try self.store().object(a, capsule_ref, null);
                defer a.free(capsule);
                var envelope = try kosmos.RuntimeCapsule.read(a, capsule);
                defer envelope.deinit();
                const record_value = envelope.value.record;
                try validateControllerRealizationProvenance(
                    parent,
                    selected,
                    record_value,
                    code_ref,
                );
                const Check = struct {
                    fn claim(
                        _: *anyopaque,
                        _: kosmos.RuntimeCapsule.Reference,
                        _: kosmos.RuntimeCapsule.Record,
                        _: kosmos.RuntimeCapsule.Reference,
                    ) !void {}
                };
                var context: u8 = 0;
                var candidate = try kosmos.RuntimeCapsule.restore(
                    a,
                    &prepared.guest,
                    &runtime,
                    capsule,
                    .{ .context = &context, .claim = Check.claim },
                );
                defer candidate.deinit();
                const checkpoint = try candidate.checkpoint(a);
                defer a.free(checkpoint);
                if (!std.meta.eql(storage.digest(checkpoint), selected.checkpoint.digest) or
                    checkpoint.len != selected.checkpoint.bytes) return error.InvalidArchive;
            }
        }
        fn validateControllerRealizationProvenance(
            parent: state.Task,
            selected: workspace.ControllerRealization,
            record_value: kosmos.RuntimeCapsule.Record,
            code_ref: state.Reference,
        ) !void {
            if (record_value.operation != null or
                !std.meta.eql(record_value.provenance.execution, rootIdentity(parent.id)) or
                !std.meta.eql(record_value.provenance.custody, storage.digest(&parent.id)) or
                record_value.provenance.publication == null or
                !std.meta.eql(
                    record_value.provenance.publication.?.digest,
                    selected.checkpoint.digest,
                ) or
                record_value.provenance.publication.?.bytes != selected.checkpoint.bytes or
                !std.meta.eql(record_value.artifact.digest, code_ref.digest) or
                record_value.artifact.bytes != code_ref.bytes) return error.InvalidArchive;
        }
        fn validateControllerRealizationExpectation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            selected: workspace.ControllerRealization,
            prior: ControllerRuntimeCut,
        ) !void {
            switch (selected.command.expected) {
                .cut => |expected| if (!std.meta.eql(
                    expected,
                    selected.cut,
                )) return error.InvalidArchive,
                .action => |expected| {
                    if (expected.epoch != selected.cut.epoch or
                        expected.realization_revision != selected.cut.realization_revision)
                        return error.InvalidArchive;
                    var historical = parent;
                    historical.controller = selected.controller;
                    historical.controller_epoch = selected.cut.epoch;
                    historical.execution_revision = selected.cut.execution_revision;
                    historical.realization_revision = selected.cut.realization_revision;
                    historical.controller_runtime = prior.runtime;
                    historical.checkpoint = selected.checkpoint;
                    historical.current_occurrence = selected.occurrence;
                    historical.controller_interaction = try wp.identity(
                        .{ .kind = .controller, .id = expected.interaction },
                        .controller,
                    );
                    var current = try self.record(
                        occurrence.Occurrence,
                        a,
                        "occurrence",
                        selected.occurrence orelse return error.InvalidArchive,
                        parent.id,
                    );
                    defer current.deinit();
                    if (current.value.work != null or current.value.residual != null)
                        return error.InvalidArchive;
                    try self.validateControllerAction(
                        a,
                        historical,
                        current.value,
                        selected.command,
                    );
                },
            }
        }
        fn controllerRealizationCut(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            parent: state.Task,
            command: @FieldType(wc.Work, "realize_controller"),
        ) !wc.ControllerCut {
            if (command.expected == .cut) return command.expected.cut;
            const expected = command.expected.action;
            const interaction_id = try wp.identity(
                .{ .kind = .controller, .id = expected.interaction },
                .controller,
            );
            if (parent.controller_interaction == null or
                !std.meta.eql(parent.controller_interaction.?, interaction_id) or
                parent.controller_epoch != expected.epoch or
                parent.realization_revision != expected.realization_revision)
                return error.StaleController;
            const id = parent.current_occurrence orelse return error.ControllerActionRequired;
            if (!same(operation_id, &std.fmt.bytesToHex(id, .lower)))
                return error.ControllerActionRequired;
            var current = try self.record(occurrence.Occurrence, a, "occurrence", id, parent.id);
            defer current.deinit();
            if ((current.value.state != .ready and
                current.value.state != .dispatching) or
                current.value.work != null or
                current.value.residual != null) return error.ControllerActionRequired;
            try self.validateControllerAction(a, parent, current.value, command);
            return .{
                .epoch = parent.controller_epoch,
                .execution_revision = parent.execution_revision,
                .realization_revision = parent.realization_revision,
            };
        }
        fn validateControllerAction(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            current: occurrence.Occurrence,
            command: @FieldType(wc.Work, "realize_controller"),
        ) !void {
            if (command.expected != .action) return error.ControllerActionRequired;
            const id = try wp.identity(
                .{ .kind = .controller, .id = command.expected.action.interaction },
                .controller,
            );
            var interaction = try self.record(
                state.ControllerInteraction,
                a,
                "controller_interaction",
                id,
                parent.id,
            );
            defer interaction.deinit();
            if (!std.meta.eql(
                parent.controller,
                @as(?state.Digest, interaction.value.controller),
            ) or
                interaction.value.epoch != command.expected.action.epoch or
                interaction.value.model == null) return error.StaleController;
            const bytes = try self.store().object(a, current.request_object, null);
            defer a.free(bytes);
            var request_value = try data.invocation.decode(data.invocation.Request, a, bytes);
            defer request_value.deinit();
            const entry = try self.handlers.resolve(
                request_value.value,
                try self.occurrenceImage(a, parent, current),
            );
            if (entry.declaration.kind != .workspace) return error.ControllerActionRequired;
            const admitted = try self.authorizeWorkspaceOccurrence(
                a,
                parent,
                current,
                entry,
                request_value.value.binding.payload,
            );
            defer a.free(admitted);
            var authorized = try contracts.decodeOwned(workspace.Authorized, a, admitted);
            defer authorized.deinit();
            if (authorized.value.command != .work or
                authorized.value.command.work != .realize_controller)
                return error.ControllerActionRequired;
            const actual = try contracts.encodeOwned(
                @TypeOf(command),
                a,
                authorized.value.command.work.realize_controller,
            );
            defer a.free(actual);
            const expected = try contracts.encodeOwned(@TypeOf(command), a, command);
            defer a.free(expected);
            if (!same(actual, expected)) return error.ControllerActionRequired;
        }
        pub fn workspaceRealizeController(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            command: @FieldType(wc.Work, "realize_controller"),
        ) !Admission {
            const request = try operation(workspace.ControllerRealizeRequest, a, .{
                .task = task_id,
                .command = command,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            var saved = try self.task(a, task_id);
            defer saved.deinit();
            const parent = saved.value;
            if (self.workspaceParentStopped(parent)) return error.InvalidState;
            if (parent.controller_succession != null) return error.ControllerHandoffPending;
            const cut = try self.controllerRealizationCut(a, operation_id, parent, command);
            if (cut.epoch != parent.controller_epoch or
                cut.execution_revision != parent.execution_revision or
                cut.realization_revision != parent.realization_revision)
                return error.StaleRevision;
            var pending = try self.rootOperation(a, parent);
            defer if (pending) |*value| value.deinit();
            if (pending != null and
                pending.?.value.pending != null)
                return error.GuestCutUnavailable;
            if (self.active) |active| if (active.subject == .root and
                std.meta.eql(active.task, task_id) and active.root_control != null)
                return error.GuestCutUnavailable;
            try self.requireControllerRealizationOccurrence(a, parent, operation_id);
            const image = try self.rootImage(a, parent);
            var selected: ?SelectedRuntime = if (command.runtime == .selected)
                try self.workspaceRuntime(
                    a,
                    task_id,
                    try wp.identity(command.runtime.selected, .runtime),
                    null,
                )
            else
                null;
            defer if (selected) |*value| value.deinit();
            const target = if (selected) |value| value.record.value.artifact else null;
            var runtime = try self.controllerRuntime(a, task_id, image, target);
            defer runtime.deinit();
            if (target != null) try self.requireSemanticPolicy(
                kosmos.RuntimeCompiler.approvedRootIdentity(&runtime),
                kosmos.RuntimeCompiler.checker_identity,
            );
            return self.publishControllerRealization(
                a,
                parent,
                command,
                cut,
                operation_id,
                request,
                target,
                &runtime,
            );
        }
        fn publishControllerRealization(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            command: @FieldType(wc.Work, "realize_controller"),
            cut: wc.ControllerCut,
            operation_id: []const u8,
            request: state.Digest,
            target: ?state.Reference,
            runtime: *kosmos.RuntimeArtifact,
        ) !Admission {
            const driver = try self.resident(a, parent);
            const source_code = try driver.runtimeBytes(a);
            defer a.free(source_code);
            const target_code = try runtime.encode(a);
            defer a.free(target_code);
            var publisher: ControllerRealizationPublisher = .{
                .host = self,
                .a = a,
                .parent = parent,
                .command = command,
                .cut = cut,
                .operation_id = operation_id,
                .request = request,
                .runtime = target,
                .source_code = source_code,
                .target_code = target_code,
            };
            const decision = try driver.realize(
                try driver.runtimeBinding(),
                runtime,
                rootProvenance(parent),
                .{ .context = &publisher, .publish = ControllerRealizationPublisher.publish },
            );
            if (publisher.failure) |err| return err;
            if (decision != .committed) return error.PublicationUncertain;
            self.active.?.realization_revision = cut.realization_revision + 1;
            return publisher.result orelse return error.CorruptState;
        }
        fn requireControllerRealizationOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            operation_id: []const u8,
        ) !void {
            if (parent.current_occurrence) |id| {
                var current = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    id,
                    parent.id,
                );
                defer current.deinit();
                if (current.value.state == .unknown) return error.UnresolvedDelivery;
                if (current.value.state == .dispatching) {
                    if (!same(operation_id, &std.fmt.bytesToHex(id, .lower)))
                        return error.UnresolvedDelivery;
                    const bytes = try self.store().object(a, current.value.request_object, null);
                    defer a.free(bytes);
                    var request_value = try data.invocation.decode(
                        data.invocation.Request,
                        a,
                        bytes,
                    );
                    defer request_value.deinit();
                    const entry = try self.handlers.resolve(
                        request_value.value,
                        try self.occurrenceImage(a, parent, current.value),
                    );
                    if (entry.declaration.kind != .workspace) return error.UnresolvedDelivery;
                }
                if (current.value.residual != null or current.value.work != null)
                    return error.InvalidState;
            }
        }
        const ControllerRealizationPublisher = controllerRealizationPublisherType();
        fn controllerRealizationPublisherType() type {
            return struct {
                host: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                command: @FieldType(wc.Work, "realize_controller"),
                cut: wc.ControllerCut,
                operation_id: []const u8,
                request: state.Digest,
                runtime: ?state.Reference,
                source_code: []const u8,
                target_code: []const u8,
                result: ?Admission = null,
                failure: ?anyerror = null,
                fn publish(
                    context: *anyopaque,
                    _: kosmos.RuntimeCapsule.Binding,
                    source_capsule: []const u8,
                    target_capsule: []const u8,
                ) kosmos.RuntimeCapsule.SwitchDecision {
                    const publication: *@This() = @ptrCast(@alignCast(context));
                    publication.result = publication.commit(
                        source_capsule,
                        target_capsule,
                    ) catch |err| {
                        publication.failure = err;
                        return if (publication.host.store().fenced) .uncertain else .rejected;
                    };
                    return .committed;
                }
                fn commit(
                    publication: *@This(),
                    source_capsule: []const u8,
                    target_capsule: []const u8,
                ) !Admission {
                    const host = publication.host;
                    try host.store().begin();
                    defer host.store().rollback();
                    const dependencies = [_]state.Reference{
                        try host.store().putObject(publication.source_code),
                        try host.store().putObject(publication.target_code),
                        try host.rootImage(publication.a, publication.parent),
                    };
                    const fact: workspace.ControllerRealization = .{
                        .command = publication.command,
                        .cut = publication.cut,
                        .occurrence = publication.parent.current_occurrence,
                        .controller = publication.parent.controller,
                        .checkpoint = publication.parent.checkpoint,
                        .runtime = publication.runtime,
                        .source = try host.store().putObject(source_capsule),
                        .target = try host.store().putObject(target_capsule),
                        .dependencies = .{ .items = &dependencies },
                    };
                    const bytes = try contracts.encodeOwned(
                        workspace.ControllerRealization,
                        publication.a,
                        fact,
                    );
                    defer publication.a.free(bytes);
                    const observation = try host.store().putObject(bytes);
                    var next = publication.parent;
                    next.controller_runtime = publication.runtime;
                    next.realization_revision = try std.math.add(u64, next.realization_revision, 1);
                    return host.workspaceCommit(
                        publication.a,
                        next,
                        publication.operation_id,
                        publication.request,
                        rootIdentity(next.id),
                        .controller,
                        observation,
                        .{ .realize_controller = fact },
                    );
                }
            };
        }
        pub fn workspaceRealize(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            command: @FieldType(wc.Work, "realize"),
        ) !Admission {
            var selected: ?SelectedRuntime =
                if (command.runtime ==
                .selected) try self.workspaceRuntime(
                    a,
                    task_id,
                    try wp.identity(command.runtime.selected, .runtime),
                    null,
                ) else null;
            defer if (selected) |*item| item.deinit();
            const target: ?state.Reference =
                if (selected) |item|
                    item.record.value.artifact
                else
                    null;
            const work_id = try wp.identity(command.expected.work, .work);
            const request = try operation(workspace.RealizeRequest, a, .{
                .task = task_id,
                .work = work_id,
                .execution = command.expected.execution_revision,
                .control = command.expected.control_revision,
                .realization = command.realization_revision,
                .runtime = target,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            if (selected) |*item| try self.requireSemanticPolicy(
                kosmos.RuntimeCompiler.approvedRootIdentity(&item.admitted),
                kosmos.RuntimeCompiler.checker_identity,
            );
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            var work = try self.runtimeWork(a, task_id, command.expected);
            defer work.deinit();
            if (work.value.guard != null) return error.GuardActive;
            if (work.value.outer_operation != null) return error.GuestCutUnavailable;
            if (work.value.realization_revision != command.realization_revision)
                return error.StaleRevision;
            try self.observerAdvanceAllowed(a, work.value);
            var program = try self.workspaceProgram(a, task_id, work.value.program);
            defer program.deinit();
            if (selected) |item| if (!std.meta.eql(item.record.value.program, work.value.program)) {
                var origin = try self.workspaceProgram(a, task_id, item.record.value.program);
                defer origin.deinit();
                if (!std.meta.eql(
                    origin.value.description.image,
                    program.value.description.image,
                )) return error.InvalidRuntime;
            };
            return self.realizeWorkspaceRuntime(
                a,
                parent.value,
                work.value,
                program.value,
                &selected,
                target,
                operation_id,
                request,
                command.realization_revision,
            );
        }
        fn realizeWorkspaceRuntime(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work: workspace.Work,
            program: workspace.Program,
            selected: *?SelectedRuntime,
            target: ?state.Reference,
            operation_id: []const u8,
            request: state.Digest,
            realization_revision: u64,
        ) !Admission {
            const image = try self.store().object(a, program.description.image, null);
            defer a.free(image);
            var generic: ?kosmos.Prepared = if (selected.* == null) try self.program.prepare(
                self.allocator,
                image,
            ) else null;
            defer if (generic) |*item| item.deinit();
            const target_artifact = if (selected.*) |*item| &item.admitted else &generic.?.runtime;
            const driver = try self.workspaceResident(a, work);
            const source_code = try driver.runtimeBytes(a);
            defer a.free(source_code);
            const target_code = try target_artifact.encode(a);
            defer a.free(target_code);
            var publisher: WorkRealizationPublisher = .{
                .host = self,
                .a = a,
                .parent = parent,
                .work = work,
                .operation_id = operation_id,
                .request = request,
                .target = target,
                .source_code = source_code,
                .target_code = target_code,
            };
            const decision = try driver.realize(
                try driver.runtimeBinding(),
                target_artifact,
                runtimeProvenance(work),
                .{ .context = &publisher, .publish = WorkRealizationPublisher.publish },
            );
            if (publisher.failure) |err| return err;
            if (decision != .committed) return error.PublicationUncertain;
            self.active.?.realization_revision = realization_revision + 1;
            return publisher.result orelse return error.CorruptState;
        }
        const WorkRealizationPublisher = workRealizationPublisherType();
        fn workRealizationPublisherType() type {
            return struct {
                host: *Self,
                a: std.mem.Allocator,
                parent: state.Task,
                work: workspace.Work,
                operation_id: []const u8,
                request: state.Digest,
                target: ?state.Reference,
                source_code: []const u8,
                target_code: []const u8,
                result: ?Admission = null,
                failure: ?anyerror = null,
                fn publish(
                    context: *anyopaque,
                    _: kosmos.RuntimeCapsule.Binding,
                    source_capsule: []const u8,
                    target_capsule: []const u8,
                ) kosmos.RuntimeCapsule.SwitchDecision {
                    const publication: *@This() = @ptrCast(@alignCast(context));
                    publication.result = publication.commit(
                        source_capsule,
                        target_capsule,
                    ) catch |err| {
                        publication.failure = err;
                        return if (publication.host.store().fenced) .uncertain else .rejected;
                    };
                    return .committed;
                }
                fn commit(
                    publication: *@This(),
                    source_capsule: []const u8,
                    target_capsule: []const u8,
                ) !Admission {
                    const host = publication.host;
                    try host.store().begin();
                    defer host.store().rollback();
                    const source_code_ref = try host.store().putObject(publication.source_code);
                    const target_code_ref = try host.store().putObject(publication.target_code);
                    const before = try host.store().putObject(source_capsule);
                    const after = try host.store().putObject(target_capsule);
                    var next = publication.work;
                    next.runtime = publication.target;
                    next.runtime_capsule = after;
                    next.runtime_trace = null;
                    next.runtime_dependencies = .{
                        .items = try capsuleDependencies(publication.a, target_capsule),
                    };
                    defer publication.a.free(next.runtime_dependencies.items);
                    next.realization_revision = try std.math.add(u64, next.realization_revision, 1);
                    next.control_revision = try std.math.add(u64, next.control_revision, 1);
                    next.event_watermark = publication.parent.event_high + 1;
                    try host.writeWorkspaceWork(&next, .replace);
                    const dependencies = [_]state.Reference{
                        source_code_ref,
                        target_code_ref,
                        next.runtime_dependencies.items[1],
                    };
                    return host.workspaceCommit(
                        publication.a,
                        publication.parent,
                        publication.operation_id,
                        publication.request,
                        next.id,
                        .work,
                        try host.snapshotRecord(
                            workspace.Work,
                            publication.a,
                            "workspace_work",
                            next.id,
                            next.task,
                        ),
                        .{
                            .realize = .{
                                .execution = publication.work.execution_revision,
                                .control = publication.work.control_revision,
                                .realization = publication.work.realization_revision,
                                .runtime = publication.target,
                                .source = before,
                                .target = after,
                                .dependencies = .{ .items = &dependencies },
                            },
                        },
                    );
                }
            };
        }
        fn capsuleDependencies(a: std.mem.Allocator, bytes: []const u8) ![]state.Reference {
            var decoded = try kosmos.RuntimeCapsule.read(a, bytes);
            defer decoded.deinit();
            if (decoded.value.record.dependencies.len != 2) return error.InvalidRuntime;
            const refs = try a.alloc(state.Reference, 2);
            for (refs, decoded.value.record.dependencies) |*out, ref| out.* = .{
                .digest = ref.digest,
                .bytes = ref.bytes,
            };
            return refs;
        }
        fn validatePublishedCapsule(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            ref: state.Reference,
            expected_runtime: ?state.Reference,
        ) !void {
            return self.validatePublishedCapsuleTrace(a, work, ref, expected_runtime, null, null);
        }
        fn validatePublishedCapsuleTrace(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            ref: state.Reference,
            expected_runtime: ?state.Reference,
            trace: ?kosmos.RuntimeInstrumentation.Output,
            pending_operation: ?workspace.OuterOperation,
        ) !void {
            const bytes = try self.store().object(a, ref, null);
            defer a.free(bytes);
            var envelope = try kosmos.RuntimeCapsule.read(a, bytes);
            defer envelope.deinit();
            const record_value = envelope.value.record;
            try validateCapsuleProvenance(work, record_value);
            var program = try self.workspaceProgram(a, work.task, work.program);
            defer program.deinit();
            if (!std.meta.eql(
                record_value.guest.image.digest,
                program.value.description.image.digest,
            ) or
                record_value.guest.image.bytes != program.value.description.image.bytes)
                return error.InvalidArchive;
            const image = try self.store().object(a, program.value.description.image, null);
            defer a.free(image);
            const runtime_ref: state.Reference = .{
                .digest = record_value.artifact.digest,
                .bytes = record_value.artifact.bytes,
            };
            const code = try self.store().object(a, runtime_ref, null);
            defer a.free(code);
            var selected = try self.selectCapsuleRuntime(
                a,
                work,
                runtime_ref,
                expected_runtime,
                image,
            );
            defer selected.deinit();
            var prepared = try kosmos.Prepared.initWithRuntime(a, image, &selected);
            defer prepared.deinit();
            const CheckOnly = struct {
                // Private archive candidate, never installed in Service.active
                // and never given an environmental adapter or execution turn.
                fn inspect(
                    _: *anyopaque,
                    _: kosmos.RuntimeCapsule.Reference,
                    _: kosmos.RuntimeCapsule.Record,
                    _: kosmos.RuntimeCapsule.Reference,
                ) !void {}
            };
            try self.validateCapsuleOperation(
                a,
                work,
                ref,
                trace,
                pending_operation,
                record_value,
                envelope.value.command,
            );
            var context: u8 = 0;
            var candidate = try kosmos.RuntimeCapsule.restore(
                a,
                &prepared.guest,
                &selected,
                bytes,
                .{ .context = &context, .claim = CheckOnly.inspect },
            );
            defer candidate.deinit();
            if (pending_operation != null) return;
            try validateCapsuleCheckpoint(a, work, &candidate, &selected, trace);
        }
        fn validateOuterControl(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            pending: workspace.OuterOperation,
            encoded: []const u8,
        ) !void {
            const bytes = try self.store().object(a, pending.control, null);
            defer a.free(bytes);
            var accepted = try contracts.decodeOwned(data.invocation.Control, a, bytes);
            defer accepted.deinit();
            var issued = try kosmos.RuntimeCapsule.readCommand(a, encoded);
            defer issued.deinit();
            if (issued.value != .advance or issued.value.advance.quantum != pending.guest_quantum or
                (pending.guest_quantum == 0 and
                    accepted.value != .reply))
                return error.InvalidArchive;
            const actual = issued.value.advance.control;
            switch (accepted.value) {
                .none => if (actual != .none or
                    work.outcome_kind != .progressed)
                    return error.InvalidArchive,
                .resume_yield => if (actual != .resume_yield or
                    work.outcome_kind != .yielded)
                    return error.InvalidArchive,
                .cancel => |reason| {
                    const saved = work.cancellation orelse return error.InvalidArchive;
                    if (actual != .cancel or reason != .text or !same(reason.text, saved.bytes) or
                        !data.record.equal(
                            data.invocation.Reason,
                            reason,
                            actual.cancel,
                        )) return error.InvalidArchive;
                },
                .reply => |reply| {
                    if (actual != .answer or
                        work.outcome_kind != .requested)
                        return error.InvalidArchive;
                    var response = try data.invocation.decode(data.invocation.Result, a, reply);
                    defer response.deinit();
                    var occurrence_value = try self.record(
                        occurrence.Occurrence,
                        a,
                        "occurrence",
                        work.current_occurrence orelse return error.InvalidArchive,
                        work.task,
                    );
                    defer occurrence_value.deinit();
                    const value = occurrence_value.value;
                    const acquisition = switch (value.state) {
                        .settled_reply => |acquired| acquired,
                        .admitted => |admitted| if (admitted ==
                            .reply) admitted.reply else return error.InvalidArchive,
                        else => return error.InvalidArchive,
                    };
                    if (!std.meta.eql(value.work, work.id) or
                        !std.meta.eql(value.request, response.value.request_identity) or
                        !std.meta.eql(acquisition.reply, storage.digest(reply)) or !same(
                        actual.answer,
                        response.value.value,
                    )) return error.InvalidArchive;
                },
            }
        }
        fn validateRuntimeSwitch(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            item: state.WorkPublication,
            prior: state.WorkPublication,
            command: @FieldType(workspace.PublicationCommand, "realize"),
        ) !void {
            var current = try self.workspaceWork(a, task_id, item.work);
            defer current.deinit();
            var work = current.value;
            work.checkpoint = prior.checkpoint orelse return error.InvalidArchive;
            try self.validatePublishedCapsule(a, work, command.source, prior.runtime);
            try self.validatePublishedCapsule(a, work, command.target, item.runtime);
            const before_bytes = try self.store().object(a, command.source, null);
            defer a.free(before_bytes);
            const after_bytes = try self.store().object(a, command.target, null);
            defer a.free(after_bytes);
            var before = try kosmos.RuntimeCapsule.read(a, before_bytes);
            defer before.deinit();
            var after = try kosmos.RuntimeCapsule.read(a, after_bytes);
            defer after.deinit();
            const source_record = before.value.record;
            const target_record = after.value.record;
            if (source_record.kind != .guest_cut or target_record.kind != .guest_cut or !same(
                before.value.checkpoint,
                after.value.checkpoint,
            ) or
                !std.meta.eql(
                    source_record.checkpoint.digest,
                    work.checkpoint.digest,
                ) or source_record.checkpoint.bytes != work.checkpoint.bytes or
                source_record.guest_revision != target_record.guest_revision or
                source_record.outer_revision == std.math.maxInt(u64) or
                target_record.outer_revision != source_record.outer_revision + 1)
                return error.InvalidArchive;
            const dependencies = [_]state.Reference{
                .{ .digest = source_record.artifact.digest, .bytes = source_record.artifact.bytes },
                .{ .digest = target_record.artifact.digest, .bytes = target_record.artifact.bytes },
                .{
                    .digest = target_record.guest.image.digest,
                    .bytes = target_record.guest.image.bytes,
                },
            };
            if (command.dependencies.items.len != dependencies.len) return error.InvalidArchive;
            for (dependencies, command.dependencies.items) |wanted, actual| if (!std.meta.eql(
                wanted,
                actual,
            )) return error.InvalidArchive;
        }
        pub fn workspaceProgram(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            program_id: state.Digest,
        ) !contracts.Decoded(workspace.Program) {
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            const custody_id = try workspaceContentCustody(a, task_id, program_id);
            const bytes = (try self.store().recordBytes(
                a,
                "workspace_program",
                custody_id,
                task_id,
            )) orelse return error.ArtifactUnavailable;
            defer a.free(bytes);
            var saved = try contracts.decodeOwned(workspace.Program, a, bytes);
            errdefer saved.deinit();
            if (!std.meta.eql(saved.value.id, custody_id) or
                !std.meta.eql(saved.value.artifact.digest, program_id) or
                !std.meta.eql(saved.value.task, task_id))
                return error.CorruptState;
            const encoded = try contracts.encodeOwned(
                workspace.ProgramArtifact,
                a,
                saved.value.description,
            );
            defer a.free(encoded);
            if (!std.meta.eql(
                storage.digest(encoded),
                saved.value.artifact.digest,
            ) or encoded.len != saved.value.artifact.bytes) return error.CorruptState;
            if (saved.value.description.catalog) |catalog| try workspaceSnapshotAccess(
                parent.value,
                catalog,
            );
            try self.validateWorkspaceProgram(a, saved.value);
            return saved;
        }
        fn workspaceContentCustody(
            a: std.mem.Allocator,
            task_id: state.TaskId,
            program_id: state.Digest,
        ) !state.Digest {
            return workspace.custodyId(a, task_id, program_id);
        }
        fn validateWorkspaceProgram(
            self: *Self,
            a: std.mem.Allocator,
            saved: workspace.Program,
        ) !void {
            if (self.checked_workspace_programs.get(
                saved.artifact.digest,
            )) |epoch| if (epoch == self.store().integrity_epoch) return;
            try self.validateProgramCompiler(a, saved, self.store());
            try self.checked_workspace_programs.put(
                self.allocator,
                saved.artifact.digest,
                self.store().integrity_epoch,
            );
        }
        fn validateProgramCompiler(
            self: *Self,
            a: std.mem.Allocator,
            saved: workspace.Program,
            objects: anytype,
        ) !void {
            const artifact = saved.description;
            try validateCompilerArtifact(a, saved, artifact);
            if (try self.validateSeedProgram(a, artifact)) return;
            const context: state.Digest = if (artifact.controller != null) blk: {
                var arena = std.heap.ArenaAllocator.init(self.allocator);
                defer arena.deinit();
                const scratch = arena.allocator();
                const frozen_contract = try self.controllerContract(scratch);
                break :blk storage.digest(
                    try contracts.encodeOwned(
                        contracts.controller.Contract,
                        scratch,
                        frozen_contract,
                    ),
                );
            } else @splat(0);
            const fact: CompilerFact = .{
                .kind = .program,
                .input = saved.artifact,
                .output = artifact.image,
                .context = context,
            };
            if (try self.compilerFact(fact)) return;
            const source = try objects.object(a, artifact.source, null);
            defer a.free(source);
            var diagnostic: construction.Diagnostic = .{};
            var built = try self.workspaceCompileFrom(
                self.allocator,
                source,
                artifact.source_kind,
                artifact.catalog,
                artifact.exposures.items,
                if (artifact.controller != null) .controller else .computation,
                &diagnostic,
                objects,
            );
            defer built.deinit();
            try validateCompiledArtifact(a, artifact, built);
            try self.retainCompilerFact(fact);
        }
        pub fn workspaceWork(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
        ) !contracts.Decoded(workspace.Work) {
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            return self.retainedWorkspaceWork(a, task_id, work_id);
        }
        fn retainedWorkspaceWork(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
        ) !contracts.Decoded(workspace.Work) {
            const bytes = (try self.store().recordBytes(
                a,
                "workspace_work",
                work_id,
                task_id,
            )) orelse return error.ArtifactUnavailable;
            defer a.free(bytes);
            var saved = try contracts.decodeOwned(workspace.Work, a, bytes);
            errdefer saved.deinit();
            if (saved.value.version != 3 or !std.meta.eql(
                saved.value.id,
                work_id,
            ) or !std.meta.eql(saved.value.task, task_id)) return error.CorruptState;
            return saved;
        }
        pub fn validateWorkspace(
            self: *Self,
            allocator: std.mem.Allocator,
            task_id: state.TaskId,
        ) !void {
            var phase: []const u8 = "task and archive index";
            errdefer std.debug.print("workspace validation: {s}\n", .{phase});
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            const index = try self.store().archiveIndex(a, task_id, .{
                .digest = storage.digest(self.assets.manifest),
                .bytes = self.assets.manifest.len,
            });
            phase = "records";
            try self.validateWorkspaceRecords(a, task_id, index.records.items);
        }
        fn validateDelegation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
            records: []const state.ArchiveRecord,
        ) !void {
            var saved = try self.record(
                workspace.Delegation,
                a,
                "workspace_delegation",
                row.id,
                parent.id,
            );
            defer saved.deinit();
            const value = saved.value;
            if (!std.meta.eql(value.id, row.id) or
                !std.meta.eql(value.task, parent.id))
                return error.InvalidArchive;
            try requireArchiveRecord(records, .occurrence, value.parent_occurrence);
            try requireArchiveRecord(records, .workspace_work, value.instrument);
            try requireArchiveRecord(records, .workspace_work, value.work);
            var original = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                value.parent_occurrence,
                parent.id,
            );
            defer original.deinit();
            if (original.value.work != null or !std.meta.eql(
                original.value.request_object,
                value.parent_request,
            )) return error.InvalidArchive;
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                try self.store().object(a, value.parent_request, null),
            );
            defer request.deinit();
            const entry = try self.handlers.resolve(
                request.value,
                try self.occurrenceImage(a, parent, original.value),
            );
            if (entry.declaration.kind != .workspace) return error.InvalidArchive;
            var authorized = try contracts.decodeOwned(
                workspace.Authorized,
                a,
                try self.authorizeWorkspace(a, parent, entry, request.value.binding.payload),
            );
            defer authorized.deinit();
            if (authorized.value.command != .work or
                authorized.value.command.work != .delegate)
                return error.InvalidArchive;
            try validateDelegationSelection(a, value, authorized.value);
            const selection = authorized.value.command.work.delegate;
            try self.validateDelegatedPort(a, parent, value, selection);
            try self.validateDelegatedChild(a, parent, row, value, selection);
        }
        pub fn prepareWorkspaceValidation(self: *Self, task_id: state.TaskId) !CompilerFacts {
            if (self.store().transaction) return error.InvalidState;
            var facts: CompilerFacts = .{ .allocator = self.allocator };
            errdefer facts.deinit();
            const prior = self.compiler_facts;
            self.compiler_facts = &facts;
            defer self.compiler_facts = prior;
            var arena = std.heap.ArenaAllocator.init(self.allocator);
            defer arena.deinit();
            const manifest = try self.store().archiveIndex(
                arena.allocator(),
                task_id,
                compilerReference(self.assets.manifest),
            );
            try self.prepareCompilerFacts(manifest, self.store());
            return facts;
        }
        pub fn validateWorkspaceRecordsPrepared(
            self: *Self,
            allocator: std.mem.Allocator,
            task_id: state.TaskId,
            records: []const state.ArchiveRecord,
            facts: *CompilerFacts,
        ) !void {
            const prior = self.compiler_facts;
            self.compiler_facts = facts;
            defer self.compiler_facts = prior;
            try self.validateWorkspaceRecords(allocator, task_id, records);
        }
        pub fn validateWorkspaceRecords(
            self: *Self,
            allocator: std.mem.Allocator,
            task_id: state.TaskId,
            records: []const state.ArchiveRecord,
        ) !void {
            var phase: []const u8 = "task";
            errdefer std.debug.print("workspace records: {s}\n", .{phase});
            var compiler_facts: CompilerFacts = .{ .allocator = self.allocator };
            defer compiler_facts.deinit();
            const prior_compiler_facts = self.compiler_facts;
            if (self.compiler_facts == null) self.compiler_facts = &compiler_facts;
            defer self.compiler_facts = prior_compiler_facts;
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            phase = "archive records";
            try self.validateWorkspaceArchive(a, parent.value, records, .records);
        }
        fn validateWorkspaceArchive(
            self: *Self,
            allocator: std.mem.Allocator,
            parent: state.Task,
            records: []const state.ArchiveRecord,
            mode: enum {
                records,
                inspect,
                retain,
            },
        ) !void {
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var checked: SnapshotValidation = .{
                .allocator = a,
                .observer_successors = .init(self.allocator, parent.id),
                .semantic_sources = true,
            };
            defer checked.deinit();
            try self.validateOccurrenceProvenance(a, parent, records, &checked);
            if (mode != .records)
                try self.validateCapturedProjections(
                    parent,
                    records,
                    if (mode == .inspect) .inspect else .retain,
                    &checked,
                );
            try self.validateWorkspaceRecordBodies(a, parent.id, records, &checked);
        }
        fn validateWorkspaceRecordBodies(
            self: *Self,
            allocator: std.mem.Allocator,
            task_id: state.TaskId,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            var phase: []const u8 = "task and controller";
            errdefer std.debug.print("workspace record bodies: {s}\n", .{phase});
            var arena = std.heap.ArenaAllocator.init(allocator);
            defer arena.deinit();
            const a = arena.allocator();
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatibleApplication(parent.value);
            const runtime_cut = try self.controllerRuntimeAt(
                a,
                parent.value,
                parent.value.event_high,
            );
            if (!std.meta.eql(runtime_cut.runtime, parent.value.controller_runtime) or
                runtime_cut.realization_revision != parent.value.realization_revision)
                return error.InvalidArchive;
            phase = "publications";
            try self.validateWorkspacePublications(a, parent.value, records, checked);
            phase = "receipts";
            try self.validateWorkspaceReceipts(a, parent.value, records, checked);
            phase = "controller bindings";
            try self.validateWorkspaceControllerBindings(a, parent.value, records);
            const Generation = struct { work: state.Digest, generation: u64 };
            var generations: std.AutoHashMap(Generation, void) = .init(a);
            for (records) |row| {
                var record_arena = std.heap.ArenaAllocator.init(self.allocator);
                defer record_arena.deinit();
                const frame = record_arena.allocator();
                phase = @tagName(row.kind);
                try self.validateWorkspaceRecordBody(
                    frame,
                    parent.value,
                    row,
                    records,
                    checked,
                    &generations,
                );
            }
            try self.validateWorkspaceGenerations(parent.value, records, checked, &generations);
        }
        fn validateWorkspaceInputs(self: *Self, a: std.mem.Allocator, value: workspace.Work) !void {
            var count: usize = 0;
            if (value.observer) |observer| {
                if (value.inputs.items.len < 2 or
                    !std.meta.eql(value.inputs.items[0], observer.source) or
                    !std.meta.eql(value.inputs.items[1], observer.accumulator))
                    return error.InvalidArchive;
                count = 2;
            }
            if (value.trial) |id| {
                var trial = try self.record(workspace.Trial, a, "workspace_trial", id, value.task);
                defer trial.deinit();
                for (trial.value.responses.items) |response| {
                    if (value.inputs.items.len -| count < 2 or !std.meta.eql(
                        value.inputs.items[count],
                        response.payload,
                    ) or !std.meta.eql(
                        value.inputs.items[count + 1],
                        response.response,
                    )) return error.InvalidArchive;
                    count += 2;
                }
            }
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq<=? ORDER BY e.seq",
                &.{ .{ .blob = &value.task }, .{
                    .integer = std.math.cast(
                        i64,
                        value.event_watermark,
                    ) orelse return error.InvalidArchive,
                } },
            );
            defer query.deinit();
            while (try query.step() == .row) {
                var event_value = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
                defer event_value.deinit();
                const ref = event_value.value.workspace_command orelse continue;
                var command = try contracts.decodeOwned(
                    workspace.PublicationCommand,
                    a,
                    try self.store().object(a, ref, null),
                );
                defer command.deinit();
                if (command.value != .interact or !std.meta.eql(
                    try wp.identity(command.value.interact.expected.work, .work),
                    value.id,
                )) continue;
                const reply = try self.workspaceInteractionReply(
                    a,
                    value.task,
                    command.value.interact,
                );
                if (reply.input) |input| {
                    if (count >= value.inputs.items.len or !std.meta.eql(
                        value.inputs.items[count],
                        input,
                    )) return error.InvalidArchive;
                    count += 1;
                }
            }
            if (value.answer_value) |answer| {
                if (count >= value.inputs.items.len or !std.meta.eql(
                    value.inputs.items[count],
                    answer,
                )) return error.InvalidArchive;
                count += 1;
            }
            if (count != value.inputs.items.len) return error.InvalidArchive;
        }
        fn validateWorkspacePublication(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            snapshot: workspace.WorkObservation,
        ) !void {
            const value = snapshot.work;
            if (!std.meta.eql(value.task, task_id)) return error.InvalidArchive;
            const publication_binding = try workPublication(a, snapshot);
            var event_query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body WH" ++
                    "ERE e.task=? AND e.seq=?",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(
                        i64,
                        value.event_watermark,
                    ) orelse return error.InvalidArchive,
                } },
            );
            defer event_query.deinit();
            if (try event_query.step() != .row) return error.InvalidArchive;
            var published = try contracts.decodeOwned(state.Event, a, try event_query.bytes(0));
            defer published.deinit();
            var matches: usize = 0;
            for (published.value.workspace_publications.items) |item| if (try samePublication(
                a,
                item,
                publication_binding,
            )) {
                matches += 1;
            };
            if (matches != 1) return error.InvalidArchive;
        }
        const SnapshotValidation = snapshotValidationType();
        fn snapshotValidationType() type {
            return struct {
                const Key = struct {
                    kind: enum { snapshot, semantic_source },
                    task: state.TaskId,
                    identity: state.Digest,
                };
                allocator: std.mem.Allocator,
                facts: std.AutoHashMapUnmanaged(Key, enum { visiting, checked }) = .empty,
                observer_successors: ObserverSuccessors,
                semantic_sources: bool = false,
                controller_values: std.AutoHashMapUnmanaged(
                    state.Digest,
                    state.ControllerReadCut,
                ) = .empty,

                fn deinit(self: *SnapshotValidation) void {
                    self.facts.deinit(self.allocator);
                    self.controller_values.deinit(self.allocator);
                    self.observer_successors.deinit();
                }
            };
        }
        fn validateWorkspaceWorkSnapshotIn(
            self: *Self,
            parent: state.Task,
            snapshot: workspace.WorkObservation,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) anyerror!void {
            var arena = std.heap.ArenaAllocator.init(self.allocator);
            defer arena.deinit();
            const a = arena.allocator();
            const bytes = try contracts.encodeOwned(workspace.WorkObservation, a, snapshot);
            defer a.free(bytes);
            const key: SnapshotValidation.Key = .{
                .kind = .snapshot,
                .task = parent.id,
                .identity = storage.digest(bytes),
            };
            if (checked.facts.get(
                key,
            )) |prior| return if (prior == .checked) {} else error.InvalidArchive;
            try checked.facts.put(checked.allocator, key, .visiting);
            errdefer _ = checked.facts.remove(key);
            try self.validateWorkspaceWorkSnapshotBody(a, parent, snapshot, records, checked);
            checked.facts.getPtr(key).?.* = .checked;
        }
        fn validateWorkspaceWorkSnapshotBody(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            snapshot: workspace.WorkObservation,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) anyerror!void {
            var phase: []const u8 = "publication";
            errdefer std.debug.print("work snapshot: {s}\n", .{phase});
            const value = snapshot.work;
            try self.validateWorkspacePublication(a, parent.id, snapshot);
            phase = "guard";
            if (value.guard != null) try self.validateGuardSnapshot(a, snapshot, records);
            phase = "current work and observer";
            // A checkpoint certifies execution, not native custody facts. Those
            // facts either remain immutable or grow monotonically in the owner.
            var current = try self.workspaceWork(a, parent.id, value.id);
            defer current.deinit();
            try self.validateSnapshotCurrent(a, parent, value, current.value, checked);
            try self.validateSnapshotRuntime(a, parent, value, records, &phase);
            phase = "inputs";
            try self.validateWorkspaceInputs(a, value);
            try validateSnapshotProgress(parent, value, current.value);
            var program = try self.workspaceProgram(a, parent.id, value.program);
            defer program.deinit();
            try self.validateSnapshotTrial(
                a,
                parent,
                value,
                current.value,
                program.value,
                records,
                checked,
            );
            const native_program = program.value.description.source_kind == .instrument_model or
                program.value.description.source_kind == .instrument_snapshot;
            try self.validateSnapshotDelegationInputs(
                a,
                parent,
                value,
                program.value,
                native_program,
                records,
                checked,
            );
            try self.validateSnapshotExecution(
                a,
                parent,
                value,
                program.value,
                native_program,
                checked,
            );
        }
        fn validateWorkspaceInstrumentAnswer(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            child: workspace.Work,
        ) !void {
            if (child.outcome_kind != .completed) {
                if (child.answer_value != null) return error.InvalidArchive;
                return;
            }
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                child.instrument_occurrence orelse return error.InvalidArchive,
                parent.id,
            );
            defer pending.deinit();
            if (!std.meta.eql(pending.value.work, child.id) or
                pending.value.state != .admitted or
                pending.value.state.admitted != .reply)
                return error.InvalidArchive;
            const admitted = pending.value.state.admitted.reply;
            var reply = try data.invocation.decode(
                data.invocation.Result,
                a,
                try self.store().acquiredObject(a, admitted.reply, null),
            );
            defer reply.deinit();
            if (!std.meta.eql(reply.value.request_identity, pending.value.request) or
                !std.meta.eql(
                    child.result,
                    @as(?state.Reference, .{
                        .digest = storage.digest(reply.value.value),
                        .bytes = reply.value.value.len,
                    }),
                )) return error.InvalidArchive;
            var output = try contracts.decodeOwned(instrument.Output, a, reply.value.value);
            defer output.deinit();
            if (output.value == .unavailable) {
                if (child.answer_value != null) return error.InvalidArchive;
                return;
            }
            try self.validateInstrumentAnswerValue(a, parent, child, output.value, admitted);
        }
        pub fn workspaceBuild(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            source: []const u8,
            diagnostic: *construction.Diagnostic,
        ) !Admission {
            // The compilation result stays local until the same transaction admits
            // its complete dependency closure, custody and acknowledgment.
            return self.workspaceBuildKind(
                a,
                operation_id,
                task_id,
                source,
                .source_records,
                null,
                &.{},
                .computation,
                diagnostic,
            );
        }
        pub fn controllerContract(
            self: *Self,
            a: std.mem.Allocator,
        ) !contracts.controller.Contract {
            var imports: std.ArrayList(contracts.controller.Signature) = .empty;
            defer imports.deinit(a);
            errdefer for (imports.items) |item| if (item.native_result != null) a.free(
                item.result.bytes,
            );
            for (self.handlers.entries) |entry|
                if (entry.declaration.controller_import) |imported| {
                    try imports.ensureUnusedCapacity(a, 1);
                    imports.appendAssumeCapacity(.{
                        .import = imported,
                        .payload = .{ .bytes = entry.payload_schema },
                        .result = .{
                            .bytes = if (imported ==
                                .deliberate) try construction.controller.replySchema(
                                a,
                                entry.resume_schema,
                            ) else entry.resume_schema,
                        },
                        .native_result = if (imported == .deliberate) .{
                            .bytes = entry.resume_schema,
                        } else null,
                    });
                };
            const result = try values.schemaBytes(Types.Output, a);
            errdefer a.free(result);
            const failure = try values.schemaBytes(Types.Failure, a);
            errdefer a.free(failure);
            return .{
                .result = .{ .bytes = result },
                .failure = .{ .bytes = failure },
                .imports = .{ .items = try imports.toOwnedSlice(a) },
            };
        }
        fn workspaceCompile(
            self: *Self,
            a: std.mem.Allocator,
            source: []const u8,
            kind: @FieldType(workspace.ProgramArtifact, "source_kind"),
            catalog: ?state.Reference,
            exposures: []const wc.Exposure,
            role: wc.ProgramRole,
            diagnostic: *construction.Diagnostic,
        ) !construction.Built {
            if (self.store().transaction) return error.CompilerPreparationRequired;
            return self.workspaceCompileFrom(
                a,
                source,
                kind,
                catalog,
                exposures,
                role,
                diagnostic,
                self.store(),
            );
        }
        fn workspaceCompileFrom(
            self: *Self,
            a: std.mem.Allocator,
            source: []const u8,
            kind: @FieldType(workspace.ProgramArtifact, "source_kind"),
            catalog: ?state.Reference,
            exposures: []const wc.Exposure,
            role: wc.ProgramRole,
            diagnostic: *construction.Diagnostic,
            objects: anytype,
        ) !construction.Built {
            if (self.store().transaction) return error.CompilerPreparationRequired;
            if (role == .controller) {
                if (kind != .source_records or
                    catalog != null or
                    exposures.len != 0)
                    return error.InvalidConstruction;
                const contract = try self.controllerContract(a);
                defer {
                    a.free(contract.result.bytes);
                    a.free(contract.failure.bytes);
                    for (contract.imports.items) |item| if (item.native_result != null) a.free(
                        item.result.bytes,
                    );
                    a.free(contract.imports.items);
                }
                return construction.buildController(a, source, contract, null, diagnostic);
            }
            if (kind == .instrument_model or kind == .instrument_snapshot) {
                if (!same(
                    source,
                    instrument.identity,
                ) or catalog != null or exposures.len != 0) return error.InvalidConstruction;
                return instrument.build(a, if (kind == .instrument_model) .model else .snapshot);
            }
            if (kind == .source_records) {
                if (catalog != null) return error.InvalidConstruction;
                return construction.buildExposed(a, source, exposures, null, diagnostic);
            }
            if (kind == .source_derivation) {
                if (catalog != null) return error.InvalidConstruction;
                return construction.buildDerived(a, source, exposures, null, diagnostic);
            }
            if (exposures.len != 0) return error.InvalidExposure;
            diagnostic.phase = .authority;
            const ref = catalog orelse return error.UnavailableCatalog;
            const bytes = try objects.object(a, ref, null);
            defer a.free(bytes);
            diagnostic.phase = .compilation;
            const built = try construction.buildComponent(a, bytes, source);
            diagnostic.phase = .complete;
            return built;
        }
        fn workspaceBuildKind(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            source: []const u8,
            source_kind: wc.SourceKind,
            catalog: ?state.Reference,
            exposures: []const wc.Exposure,
            role: wc.ProgramRole,
            diagnostic: *construction.Diagnostic,
        ) !Admission {
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            const Request = workspace.BuildRequest;
            const request = try operation(Request, a, .{
                .task = task_id,
                .source = .{ .bytes = source },
                .source_kind = source_kind,
                .catalog = catalog,
                .exposures = .{ .items = exposures },
                .role = role,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, null);
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            if (catalog) |ref| try workspaceSnapshotAccess(parent.value, ref);
            var built = try self.workspaceCompile(
                a,
                source,
                @fromBackingInt(@intCast(@backingInt(source_kind))),
                catalog,
                exposures,
                role,
                diagnostic,
            );
            defer built.deinit();
            try self.store().begin();
            defer self.store().rollback();
            const saved = try self.workspaceStoreProgram(a, task_id, source, @fromBackingInt(
                @intCast(@backingInt(source_kind)),
            ), catalog, exposures, .{
                .image = .{ .bytes = built.image },
                .interface = built.interface,
                .ports = .{ .items = built.ports },
                .controller = built.controller,
            });
            const admitted = try self.workspaceCommit(
                a,
                parent.value,
                operation_id,
                request,
                saved.digest,
                .program,
                saved,
                .build,
            );
            try self.checked_workspace_programs.put(
                self.allocator,
                saved.digest,
                self.store().integrity_epoch,
            );
            return admitted;
        }
        fn workspaceStoreProgram(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            source: []const u8,
            source_kind: @FieldType(workspace.ProgramArtifact, "source_kind"),
            catalog: ?state.Reference,
            exposures: []const wc.Exposure,
            built: build_job.Compiled,
        ) !state.Reference {
            const ports = try a.alloc(workspace.PortInterface, built.ports.items.len);
            defer a.free(ports);
            var controller_schemas: std.ArrayList(state.Reference) = .empty;
            defer controller_schemas.deinit(a);
            if (built.controller) |descriptor| {
                const schemas = try @import("controller_construction.zig").schemas(a, descriptor);
                defer a.free(schemas);
                for (schemas) |schema| try controller_schemas.append(
                    a,
                    try self.store().putObject(schema),
                );
            }
            for (built.ports.items, ports) |port, *out| out.* = .{
                .identity = port.identity,
                .class = port.class,
                .argument = try self.store().putObject(port.argument.bytes),
                .observation = try self.store().putObject(port.observation.bytes),
                .payload = try self.store().putObject(port.payload.bytes),
                .command = try self.store().putObject(port.command.bytes),
            };
            const artifact: workspace.ProgramArtifact = .{
                .source = try self.store().putObject(source),
                .source_kind = source_kind,
                .construction_contract = try name(
                    if (built.controller !=
                        null) contracts.controller.identity else switch (source_kind) {
                        .source_records => @import("source_records.zig").identity,
                        .source_derivation => @import("source_records.zig").derivation_identity,
                        .component_recipe => construction.component_identity,
                        .instrument_model, .instrument_snapshot => instrument.identity,
                    },
                ),
                .authoring_identity = storage.digest(@import("native_options").horos_identity),
                .image = try self.store().putObject(built.image.bytes),
                .input_schema = try self.store().putObject(built.interface.input.bytes),
                .result_schema = try self.store().putObject(built.interface.output.bytes),
                .failure_schema = try self.store().putObject(built.interface.failure.bytes),
                .catalog = catalog,
                .exposures = .{ .items = exposures },
                .ports = .{ .items = ports },
                .controller = built.controller,
                .controller_schemas = .{ .items = controller_schemas.items },
            };
            return self.storeProgramCustody(a, task_id, artifact);
        }
        fn workspaceCommit(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            operation_id: ?[]const u8,
            request: state.Digest,
            identity: state.Digest,
            kind: @FieldType(contracts.workspace.Ref, "kind"),
            observation: state.Reference,
            command: ?workspace.PublicationCommand,
        ) !Admission {
            return self.workspaceCommitRelated(
                a,
                initial,
                operation_id,
                request,
                identity,
                kind,
                observation,
                null,
                command,
            );
        }
        fn workspaceCommitRelated(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            operation_id: ?[]const u8,
            request: state.Digest,
            identity: state.Digest,
            kind: @FieldType(contracts.workspace.Ref, "kind"),
            observation: state.Reference,
            related: ?state.Digest,
            command: ?workspace.PublicationCommand,
        ) !Admission {
            var parent = initial;
            parent.revision = try std.math.add(u64, parent.revision, 1);
            const event_data = try std.fmt.allocPrint(a, "{{\"workspace_id\":\"{s}\"}}", .{
                std.fmt.bytesToHex(identity, .lower),
            });
            defer a.free(event_data);
            var publication: WorkspaceCommitPublication = .{ .frozen = observation };
            defer if (publication.decoded_work) |*work| work.deinit();
            var receipt_id: state.Digest = undefined;
            try self.io.randomSecure(&receipt_id);
            try self.prepareWorkspaceCommitPublication(
                a,
                parent.id,
                identity,
                kind,
                observation,
                related,
                &publication,
            );
            try self.publishWorkspaceCommitEvent(
                a,
                initial,
                &parent,
                operation_id,
                event_data,
                command,
                &publication,
            );
            const saved: state.Receipt = .{
                .id = receipt_id,
                .client_operation_id = try name(operation_id orelse "workspace.progress"),
                .method = .workspace,
                .request_digest = request,
                .task = parent.id,
                .revision = parent.revision,
                .disposition = .accepted,
                .workspace = identity,
                .workspace_kind = kind,
                .workspace_observation = publication.frozen,
            };
            if (operation_id) |op| {
                const bytes = try contracts.encodeOwned(state.Receipt, a, saved);
                defer a.free(bytes);
                const key = try self.operationKey(a, op);
                try self.store().putReceipt(&key, request, bytes);
            }
            try self.scheduleWorkspaceCommit(
                a,
                parent,
                initial.revision,
                identity,
                kind,
                publication.decoded_work,
            );
            return .{ .receipt = saved, .replayed = false };
        }
        fn workspaceDelegate(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            authorized: workspace.Authorized,
        ) !Admission {
            const selection = authorized.command.work.delegate;
            const Request = workspace.DelegationRequest;
            const request = try operation(Request, a, .{ .task = task_id, .command = selection });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            const parent_occurrence = parent.value.current_occurrence orelse
                return error.InvalidDelegation;
            const operation_name = std.fmt.bytesToHex(parent_occurrence, .lower);
            if (!same(operation_id, &operation_name)) return error.InvalidDelegation;
            var original = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                parent_occurrence,
                task_id,
            );
            defer original.deinit();
            if (original.value.work != null or
                original.value.state != .ready)
                return error.InvalidDelegation;
            const target_id = try wp.identity(selection.expected.work, .work);
            try self.requireCustody(a, task_id, target_id);
            var target = try self.workspaceWork(a, task_id, target_id);
            defer target.deinit();
            if (target.value.execution_revision != selection.expected.execution_revision or
                target.value.control_revision != selection.expected.control_revision)
                return error.StaleRevision;
            if (target.value.terminal() or
                target.value.cancellation != null)
                return error.InvalidState;
            const port_ref = target.value.current_port orelse return error.NoExposedPort;
            var port = try contracts.decodeOwned(
                workspace.Port,
                a,
                try self.store().object(a, port_ref, null),
            );
            defer port.deinit();
            try self.validateDelegatePort(a, task_id, selection, port.value);
            return self.publishWorkspaceDelegation(
                a,
                operation_id,
                task_id,
                authorized,
                parent.value,
                original.value,
                target.value,
                port.value,
                port_ref,
                request,
            );
        }
        pub fn workspaceStopObserving(
            self: *Self,
            a: std.mem.Allocator,
            id: []const u8,
            task_id: state.TaskId,
            expected: wc.Expected,
        ) !Admission {
            const request = try operation(workspace.StopObservingRequest, a, .{
                .task = task_id,
                .expected = expected,
            });
            if (try self.replay(a, id, request)) |prior| return prior;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            const work_id = try wp.identity(expected.work, .work);
            try self.requireCustody(a, task_id, work_id);
            var saved = try self.workspaceWork(a, task_id, work_id);
            defer saved.deinit();
            if (saved.value.execution_revision != expected.execution_revision or
                saved.value.control_revision != expected.control_revision)
                return error.StaleRevision;
            var value = saved.value;
            if (value.observer == null or
                value.observer.?.successor != null)
                return error.InvalidObserverInput;
            if (!value.observer.?.stopped and
                observerHeadIndex(parent.value, value.id) == null) return error.CorruptState;
            const heads = try observerHeadsAfter(a, parent.value, value.id, null);
            defer a.free(heads);
            parent.value.observer_heads.items = heads;
            value.observer.?.stopped = true;
            value.control_revision = try std.math.add(u64, value.control_revision, 1);
            value.event_watermark = try std.math.add(u64, parent.value.event_high, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.writeWorkspaceWork(&value, .replace);
            const frozen = try self.snapshotRecord(
                workspace.Work,
                a,
                "workspace_work",
                value.id,
                task_id,
            );
            return self.workspaceCommit(
                a,
                parent.value,
                id,
                request,
                value.id,
                .work,
                frozen,
                .{ .stop_observing = expected },
            );
        }
        fn validateObserverSuccessionPublication(
            self: *Self,
            a: std.mem.Allocator,
            event_value: state.Event,
            item: state.WorkPublication,
            prior: ?state.WorkPublication,
            command: ?workspace.PublicationCommand,
        ) !bool {
            const before = prior orelse return false;
            const selected = command orelse return false;
            if (selected != .start) return false;
            const observer = selected.start.observer orelse return error.InvalidArchive;
            const previous = observer.selection.previous orelse return error.InvalidArchive;
            const publications = event_value.workspace_publications.items;
            if (publications.len != 2 or !std.meta.eql(publications[1].work, item.work) or
                !std.meta.eql(
                    try wp.identity(previous, .work),
                    item.work,
                )) return error.InvalidArchive;
            const reference = observer.previous orelse return error.InvalidArchive;
            const bytes = try self.store().object(a, reference, null);
            defer a.free(bytes);
            var retained = try contracts.decodeOwned(workspace.Work, a, bytes);
            defer retained.deinit();
            const predecessor = retained.value;
            var snapshot: workspace.WorkObservation = .{ .work = predecessor, .occurrence = null };
            if (!try samePublication(a, before, try workPublication(a, snapshot)))
                return error.InvalidArchive;
            if (predecessor.observer == null or predecessor.observer.?.successor != null or
                predecessor.outcome_kind != .completed or predecessor.cancellation != null)
                return error.InvalidArchive;
            const previous_bytes = try contracts.encodeOwned(workspace.Work, a, predecessor);
            defer a.free(previous_bytes);
            const previous_reference: state.Reference = .{
                .digest = storage.digest(previous_bytes),
                .bytes = previous_bytes.len,
            };
            if (!std.meta.eql(observer.previous, @as(?state.Reference, previous_reference)))
                return error.InvalidArchive;
            snapshot.work.observer.?.successor = publications[0].work;
            snapshot.work.control_revision = try std.math.add(u64, predecessor.control_revision, 1);
            snapshot.work.event_watermark = event_value.seq;
            if (!try samePublication(a, item, try workPublication(a, snapshot)))
                return error.InvalidArchive;
            return true;
        }
        fn validateObserverPublication(
            a: std.mem.Allocator,
            item: state.WorkPublication,
            prior: ?state.WorkPublication,
            command: ?workspace.PublicationCommand,
        ) !void {
            const observer = item.observer orelse {
                if (prior != null and prior.?.observer != null) return error.InvalidArchive;
                if (command) |selected| switch (selected) {
                    .start => |start| if (start.observer != null) return error.InvalidArchive,
                    .stop_observing => return error.InvalidArchive,
                    else => {},
                };
                return;
            };
            const completed = item.control.outcome == .completed;
            if (observer.consumed_revision != @as(?u64, if (completed)
                observer.source_revision
            else
                null)) return error.InvalidArchive;
            if (prior) |before| {
                var expected = before.observer orelse return error.InvalidArchive;
                expected.consumed_revision = observer.consumed_revision;
                if (!std.meta.eql(expected.incomplete, observer.incomplete)) {
                    if (command != null or expected.stopped or !completed or
                        before.control.outcome != .completed or observer.incomplete == null or
                        expected.selection.policy.continuation != .owner_scheduled)
                        return error.InvalidArchive;
                    expected.incomplete = observer.incomplete;
                }
                if (command != null and command.? == .stop_observing) {
                    const selected = command.?.stop_observing;
                    if (!std.meta.eql(try wp.identity(selected.work, .work), item.work) or
                        selected.execution_revision != before.execution_revision or
                        selected.control_revision != before.control_revision or
                        item.control_revision -| before.control_revision != 1 or
                        item.execution_revision != before.execution_revision)
                        return error.InvalidArchive;
                    expected.stopped = true;
                }
                const bytes = try contracts.encodeOwned(workspace.Observer, a, expected);
                defer a.free(bytes);
                const actual = try contracts.encodeOwned(workspace.Observer, a, observer);
                defer a.free(actual);
                if (!same(bytes, actual)) return error.InvalidArchive;
            } else {
                if (observer.stopped or observer.successor != null or observer.incomplete != null or
                    command == null or command.? != .start)
                    return error.InvalidArchive;
                var expected = command.?.start.observer orelse return error.InvalidArchive;
                expected.consumed_revision = observer.consumed_revision;
                const requested = try contracts.encodeOwned(workspace.Observer, a, expected);
                defer a.free(requested);
                const actual = try contracts.encodeOwned(workspace.Observer, a, observer);
                defer a.free(actual);
                if (!same(requested, actual)) return error.InvalidArchive;
            }
        }
        const ObserverSuccessors = observerSuccessorsType();
        fn observerSuccessorsType() type {
            return struct {
                const Entry = struct { id: state.Digest, duplicate: bool };
                allocator: std.mem.Allocator,
                task: state.TaskId,
                entries: std.AutoHashMapUnmanaged(state.Digest, Entry) = .empty,
                loaded: bool = false,
                histories: ObserverHistories,

                fn init(a: std.mem.Allocator, task_id: state.TaskId) ObserverSuccessors {
                    return .{ .allocator = a, .task = task_id, .histories = .{ .allocator = a } };
                }

                fn deinit(self: *ObserverSuccessors) void {
                    self.entries.deinit(self.allocator);
                    self.histories.deinit();
                }

                fn next(
                    self: *ObserverSuccessors,
                    service: *Self,
                    id: state.Digest,
                ) !?state.Digest {
                    if (!self.loaded) try self.load(service);
                    const entry = self.entries.get(id) orelse return null;
                    if (entry.duplicate) return error.InvalidArchive;
                    return entry.id;
                }

                fn load(self: *ObserverSuccessors, service: *Self) !void {
                    var entries: std.AutoHashMapUnmanaged(state.Digest, Entry) = .empty;
                    errdefer entries.deinit(self.allocator);
                    const ids = try service.workspaceIds(self.allocator, self.task);
                    defer self.allocator.free(ids);
                    var arena = std.heap.ArenaAllocator.init(self.allocator);
                    defer arena.deinit();
                    for (ids) |id| {
                        _ = arena.reset(.retain_capacity);
                        var other = try service.retainedWorkspaceWork(
                            arena.allocator(),
                            self.task,
                            id,
                        );
                        defer other.deinit();
                        const observer = other.value.observer orelse continue;
                        const prior = observer.selection.previous orelse continue;
                        const entry = try entries.getOrPut(
                            self.allocator,
                            try wp.identity(prior, .work),
                        );
                        if (entry.found_existing) entry.value_ptr.duplicate =
                            true else entry.value_ptr.* =
                            .{ .id = other.value.id, .duplicate = false };
                    }
                    self.entries = entries;
                    self.loaded = true;
                }
            };
        }
        fn validateObservedAdvance(
            before: state.WorkPublication,
            after: state.WorkPublication,
            prefix: *@import("workspace_observers.zig").PublicationPrefix,
        ) !void {
            if (before.execution_revision == after.execution_revision and
                std.meta.eql(
                    before.outer_operation orelse before.runtime_capsule,
                    after.outer_operation orelse after.runtime_capsule,
                )) return;
            const active = prefix.lossless(before.work) orelse return;
            var outer: ?struct { before: u64, after: u64 } = null;
            for (active.keys()) |id| {
                const observer = prefix.latest.get(id).?.publication.observer.?;
                if (observer.selection.source.level == .guest_cut and
                    before.execution_revision == after.execution_revision) continue;
                var cursor = before.execution_revision;
                if (observer.selection.source.level == .outer_execution) {
                    if (outer == null) outer = .{
                        .before = try prefix.outerRevision(
                            before.work,
                            std.math.maxInt(u64),
                            before.outer_operation orelse before.runtime_capsule,
                        ),
                        .after = try prefix.outerRevision(
                            after.work,
                            std.math.maxInt(u64),
                            after.outer_operation orelse after.runtime_capsule,
                        ),
                    };
                    cursor = outer.?.before;
                    if (cursor == outer.?.after) continue;
                }
                if (observer.consumed_revision == null or observer.consumed_revision.? != cursor)
                    return error.InvalidArchive;
            }
        }
        fn pumpObserver(self: *Self, a: std.mem.Allocator, work: workspace.Work) !Step {
            const observer = work.observer.?;
            const subject: workspace.Subject = .{ .task = work.task, .work = work.id };
            var parent = try self.task(a, work.task);
            defer parent.deinit();
            if (self.workspaceParentStopped(parent.value) or observer.stopped or
                observer.selection.policy.continuation != .owner_scheduled or
                observer.successor != null)
            {
                self.subjectRemove(subject);
                return .progressed;
            }
            var source = try self.workspaceWork(a, work.task, observer.source_work);
            defer source.deinit();
            const consumed = observer.consumed_revision orelse return error.InvalidObserverInput;
            const revision = try self.observerSourceRevision(
                a,
                source.value,
                observer.selection.source.level,
            );
            if (revision -| consumed < observer.selection.policy.cadence)
                return .idle;
            if (observer.incomplete) |incomplete| if (incomplete.revision == revision)
                return .idle;
            var selection = observer.selection;
            selection.source.expected.execution_revision = source.value.execution_revision;
            selection.source.expected.control_revision = source.value.control_revision;
            selection.source.realization_revision = source.value.realization_revision;
            selection.previous = try wp.reference(a, .work, work.id);
            const identity = try operation(struct {
                revision: u64,
                request: workspace.ObserveRequest,
            }, a, .{
                .revision = revision,
                .request = .{ .task = work.task, .selection = selection },
            });
            const operation_id = try std.fmt.allocPrint(a, "observe-{s}", .{
                std.fmt.bytesToHex(identity, .lower),
            });
            defer a.free(operation_id);
            _ = self.workspaceObserve(a, operation_id, work.task, selection) catch |err| {
                const diagnostic: @FieldType(workspace.Observer.Incomplete, "diagnostic") =
                    switch (err) {
                        error.InvalidDisclosure => .invalid_disclosure,
                        error.OuterCutUnavailable => .outer_cut_unavailable,
                        else => return err,
                    };
                return self.recordObserverIncomplete(
                    a,
                    parent.value,
                    work,
                    source.value,
                    revision,
                    diagnostic,
                );
            };
            self.subjectRemove(subject);
            return .progressed;
        }
        fn recordObserverIncomplete(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work: workspace.Work,
            source: workspace.Work,
            revision: u64,
            diagnostic: @FieldType(workspace.Observer.Incomplete, "diagnostic"),
        ) !Step {
            var prepared = try self.inspectionRuntime(a, source);
            defer prepared.deinit();
            const code = try prepared.runtime.encode(a);
            defer a.free(code);
            var pending: ?contracts.Decoded(occurrence.Occurrence) = null;
            defer if (pending) |*value| value.deinit();
            if (source.current_occurrence) |id|
                pending = try self.record(occurrence.Occurrence, a, "occurrence", id, source.task);
            const snapshot = try contracts.encodeOwned(workspace.WorkObservation, a, .{
                .work = source,
                .occurrence = if (pending) |value| value.value else null,
            });
            defer a.free(snapshot);
            try self.store().begin();
            defer self.store().rollback();
            var value = work;
            value.observer.?.incomplete = .{
                .publication = source.event_watermark,
                .revision = revision,
                .source = try self.store().putObject(snapshot),
                .runtime_code = try self.store().putObject(code),
                .diagnostic = diagnostic,
            };
            value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            try self.writeWorkspaceWork(&value, .replace);
            _ = try self.workspaceCommit(
                a,
                parent,
                null,
                @splat(0),
                value.id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", value.id, value.task),
                null,
            );
            return .progressed;
        }
        fn validateObserverPreparationProgress(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            watermark: u64,
            item: state.WorkPublication,
            prior: ?state.WorkPublication,
            command: ?workspace.PublicationCommand,
            histories: *ObserverHistories,
        ) !bool {
            const observer = item.observer orelse return false;
            const before = prior orelse return false;
            const previous = before.observer orelse return error.InvalidArchive;
            if (std.meta.eql(previous.incomplete, observer.incomplete)) return false;
            const incomplete = observer.incomplete orelse return error.InvalidArchive;
            if (previous.incomplete) |failed| if (failed.revision >= incomplete.revision)
                return error.InvalidArchive;
            if (command != null or item.execution_revision != before.execution_revision or
                item.control_revision != before.control_revision or
                incomplete.publication != try self.workspacePublicationAt(
                    a,
                    task_id,
                    observer.source_work,
                    watermark -| 1,
                )) return error.InvalidArchive;
            var expected = before;
            expected.observer.?.incomplete = incomplete;
            expected.observation = item.observation;
            if (!try samePublication(a, expected, item)) return error.InvalidArchive;
            try self.validateObserverIncompleteAt(
                a,
                task_id,
                item.control.outcome,
                watermark,
                observer,
                histories,
            );
            return true;
        }
        fn validateObserverIncomplete(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            histories: *ObserverHistories,
        ) !void {
            const observer = work.observer orelse return;
            return self.validateObserverIncompleteAt(
                a,
                work.task,
                work.outcome_kind,
                work.event_watermark,
                observer,
                histories,
            );
        }
        fn validateObserverIncompleteAt(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            outcome: state.Outcome,
            watermark: u64,
            observer: workspace.Observer,
            histories: *ObserverHistories,
        ) !void {
            const incomplete = observer.incomplete orelse return;
            const consumed = observer.consumed_revision orelse return error.InvalidArchive;
            if (outcome != .completed or incomplete.publication >= watermark or
                incomplete.revision -| consumed < observer.selection.policy.cadence or
                observer.selection.policy.continuation != .owner_scheduled)
                return error.InvalidArchive;
            var query = try self.store().database.prepare(
                "SELECT o.body FROM events e JOIN objects o ON o.digest=e.body " ++
                    "WHERE e.task=? AND e.seq=?",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(i64, incomplete.publication) orelse
                        return error.InvalidArchive,
                } },
            );
            defer query.deinit();
            if (try query.step() != .row) return error.InvalidArchive;
            var event_value = try contracts.decodeOwned(state.Event, a, try query.bytes(0));
            defer event_value.deinit();
            for (event_value.value.workspace_publications.items) |publication| {
                if (!std.meta.eql(publication.work, observer.source_work)) continue;
                if (!std.meta.eql(publication.observation, incomplete.source.digest))
                    return error.InvalidArchive;
                const bytes = try self.store().object(a, incomplete.source, null);
                defer a.free(bytes);
                var source = try contracts.decodeOwned(workspace.WorkObservation, a, bytes);
                defer source.deinit();
                if (!std.meta.eql(source.value.work.id, observer.source_work) or
                    source.value.work.event_watermark != incomplete.publication)
                    return error.InvalidArchive;
                try self.validateWorkspacePublication(a, task_id, source.value);
                try histories.validateCursor(self, a, source.value.work);
                if (incomplete.revision != try self.observerSourceRevision(
                    a,
                    source.value.work,
                    observer.selection.source.level,
                )) return error.InvalidArchive;
                return self.validateObserverPreparationCut(a, observer, source.value);
            }
            return error.InvalidArchive;
        }
        fn validateObserverPreparationCut(
            self: *Self,
            a: std.mem.Allocator,
            observer: workspace.Observer,
            source: workspace.WorkObservation,
        ) !void {
            const incomplete = observer.incomplete.?;
            var prepared = try self.inspectionRuntime(a, source.work);
            defer prepared.deinit();
            const code = try self.store().object(a, incomplete.runtime_code, null);
            defer a.free(code);
            if (!std.meta.eql(prepared.runtime.identity, incomplete.runtime_code.digest))
                return error.InvalidArchive;
            if (incomplete.diagnostic == .outer_cut_unavailable) {
                if (observer.selection.source.level != .outer_execution or
                    source.work.outer_operation != null)
                    return error.InvalidArchive;
                if (source.work.runtime_capsule) |ref| {
                    const bytes = try self.store().object(a, ref, null);
                    defer a.free(bytes);
                    var capsule = try kosmos.RuntimeCapsule.read(a, bytes);
                    defer capsule.deinit();
                    if (capsule.value.record.kind != .guest_cut) return error.InvalidArchive;
                }
                return;
            }
            const disclosed = self.workspaceInspectionBytes(a, source.work.task, .{
                .level = observer.selection.source.level,
                .observation = source,
                .nodes = observer.selection.source.nodes,
                .disclosure = observer.selection.source.disclosure,
                .runtime_code = incomplete.runtime_code,
            }) catch |err| switch (err) {
                error.InvalidDisclosure => return,
                else => return err,
            };
            a.free(disclosed.schema);
            a.free(disclosed.value);
            return error.InvalidArchive;
        }
        fn observerAdvanceAllowed(self: *Self, a: std.mem.Allocator, source: workspace.Work) !void {
            return self.observerAdvanceAllowedFor(a, source, null);
        }
        fn observerAdvanceAllowedFor(
            self: *Self,
            a: std.mem.Allocator,
            source: workspace.Work,
            level: ?@FieldType(wc.GuestViewSelection, "level"),
        ) !void {
            var parent = try self.task(a, source.task);
            defer parent.deinit();
            if (parent.value.observer_heads.items.len != 0) try self.compatible(parent.value);
            for (parent.value.observer_heads.items) |id| {
                var saved = try self.retainedWorkspaceWork(a, source.task, id);
                defer saved.deinit();
                const observer = saved.value.observer orelse return error.CorruptState;
                if (!self.activeObserver(saved.value)) return error.CorruptState;
                if (observer.selection.policy.delivery != .lossless or
                    (level != null and observer.selection.source.level != level.?) or
                    !std.meta.eql(observer.source_work, source.id)) continue;
                if (observer.consumed_revision == null or
                    observer.consumed_revision.? !=
                        try self.observerSourceRevision(a, source, observer.selection.source.level))
                    return error.ObservationBlocked;
            }
        }
        fn observationBlockedAt(
            source: state.WorkPublication,
            prefix: *@import("workspace_observers.zig").PublicationPrefix,
        ) !bool {
            return prefix.blocked(
                source.work,
                source.execution_revision,
                std.math.maxInt(u64),
                source.outer_operation orelse source.runtime_capsule,
            );
        }
        const ObserverScope = observerScopeType();
        fn observerScopeType() type {
            return union(enum) {
                current: *CurrentObservers,
                historical: *ObserverHistories,

                fn at(scope: ObserverScope, task_id: state.TaskId, watermark: u64) !WorkObservers {
                    return switch (scope) {
                        .current => |index| if (std.meta.eql(
                            index.task,
                            task_id,
                        ) and index.watermark == watermark)
                            .{ .current = index }
                        else
                            error.InvalidArchive,
                        .historical => |histories| .{
                            .historical = try histories.get(task_id, watermark),
                        },
                    };
                }
            };
        }
        const WorkObservers = workObserversType();
        fn workObserversType() type {
            return union(enum) {
                current: *CurrentObservers,
                historical: HistoricalRead,

                fn blocked(
                    observers: WorkObservers,
                    service: *Self,
                    source: workspace.Work,
                    observed_at: u64,
                ) !bool {
                    switch (observers) {
                        inline .current, .historical => |index| {
                            if (observed_at != index.watermark) return error.InvalidArchive;
                            return index.blocked(service, source);
                        },
                    }
                }
            };
        }
        const CurrentObservers = currentObserversType();
        fn currentObserversType() type {
            return struct {
                const Key = struct {
                    source: state.Digest,
                    level: @FieldType(wc.GuestViewSelection, "level"),
                };
                allocator: std.mem.Allocator,
                task: state.TaskId,
                watermark: u64,
                loaded: bool = false,
                revisions: std.AutoHashMapUnmanaged(Key, ?u64) = .empty,

                fn init(
                    a: std.mem.Allocator,
                    task_id: state.TaskId,
                    watermark: u64,
                ) CurrentObservers {
                    return .{ .allocator = a, .task = task_id, .watermark = watermark };
                }

                fn deinit(index: *CurrentObservers) void {
                    index.revisions.deinit(index.allocator);
                }

                fn load(index: *CurrentObservers, service: *Self) !void {
                    const a = index.allocator;
                    var parent = try service.task(a, index.task);
                    defer parent.deinit();
                    if (index.watermark != parent.value.event_high) return error.InvalidArchive;
                    for (parent.value.observer_heads.items) |id| {
                        var saved = try service.retainedWorkspaceWork(a, index.task, id);
                        defer saved.deinit();
                        const observer = saved.value.observer orelse return error.CorruptState;
                        if (!service.activeObserver(saved.value)) return error.CorruptState;
                        if (observer.selection.policy.delivery != .lossless) continue;
                        const entry = try index.revisions.getOrPut(a, .{
                            .source = observer.source_work,
                            .level = observer.selection.source.level,
                        });
                        if (!entry.found_existing) {
                            entry.value_ptr.* = observer.consumed_revision;
                        } else if (!std.meta.eql(entry.value_ptr.*, observer.consumed_revision)) {
                            entry.value_ptr.* = null;
                        }
                    }
                    index.loaded = true;
                }

                fn blocked(index: *CurrentObservers, service: *Self, source: workspace.Work) !bool {
                    if (!std.meta.eql(
                        source.task,
                        index.task,
                    ) or source.event_watermark > index.watermark)
                        return error.InvalidArchive;
                    if (!index.loaded) try index.load(service);
                    const levels = [_]@FieldType(wc.GuestViewSelection, "level"){
                        .guest_cut,
                        .outer_execution,
                    };
                    for (levels) |level| {
                        const consumed = index.revisions.get(.{
                            .source = source.id,
                            .level = level,
                        }) orelse continue;
                        if (consumed == null or consumed.? != try service.observerSourceRevision(
                            index.allocator,
                            source,
                            level,
                        ))
                            return true;
                    }
                    return false;
                }
            };
        }
        const ObserverHistories = observerHistoriesType();
        fn observerHistoriesType() type {
            return struct {
                allocator: std.mem.Allocator,
                entries: std.AutoHashMapUnmanaged(state.TaskId, *HistoricalObservers) = .empty,

                fn deinit(histories: *ObserverHistories) void {
                    const a = histories.allocator;
                    var iterator = histories.entries.valueIterator();
                    while (iterator.next()) |index| {
                        index.*.deinit();
                        a.destroy(index.*);
                    }
                    histories.entries.deinit(a);
                }

                fn validateCursor(
                    histories: *ObserverHistories,
                    service: *Self,
                    a: std.mem.Allocator,
                    work: workspace.Work,
                ) !void {
                    var parent = try service.task(a, work.task);
                    defer parent.deinit();
                    const read = try histories.get(work.task, parent.value.event_high);
                    const index = read.index;
                    try index.load(service);
                    if (work.event_watermark > index.watermark) return error.InvalidArchive;
                    const cursor = index.history.outerCursorAt(work.id, work.event_watermark);
                    if (!std.meta.eql(work.outer_cursor, cursor))
                        return error.InvalidArchive;
                }

                fn get(
                    histories: *ObserverHistories,
                    task_id: state.TaskId,
                    watermark: u64,
                ) !HistoricalRead {
                    const a = histories.allocator;
                    if (histories.entries.get(task_id)) |index|
                        return .{ .index = index, .watermark = watermark };
                    const index = try a.create(HistoricalObservers);
                    errdefer a.destroy(index);
                    index.* = .init(a, task_id, std.math.maxInt(u64));
                    try histories.entries.put(a, task_id, index);
                    return .{ .index = index, .watermark = watermark };
                }
            };
        }
        const HistoricalRead = historicalReadType();
        fn historicalReadType() type {
            return struct {
                index: *HistoricalObservers,
                watermark: u64,

                fn blocked(read: HistoricalRead, service: *Self, source: workspace.Work) !bool {
                    const index = read.index;
                    if (!std.meta.eql(source.task, index.task) or
                        source.event_watermark > read.watermark)
                        return error.InvalidArchive;
                    try index.prepare(service);
                    if (read.watermark > index.watermark) return error.InvalidArchive;
                    if (!index.observers_present.?) return false;
                    try index.load(service);
                    return index.history.blocked(
                        source.id,
                        source.execution_revision,
                        source.event_watermark,
                        read.watermark,
                        if (source.outer_operation) |pending|
                            pending.capsule
                        else
                            source.runtime_capsule,
                    );
                }
            };
        }
        const HistoricalObservers = historicalObserversType();
        fn historicalObserversType() type {
            return struct {
                const History = @import("workspace_observers.zig").PublicationHistory;
                allocator: std.mem.Allocator,
                task: state.TaskId,
                watermark: u64,
                loaded: bool = false,
                observers_present: ?bool = null,
                history: History,

                fn init(
                    a: std.mem.Allocator,
                    task_id: state.TaskId,
                    watermark: u64,
                ) HistoricalObservers {
                    return .{
                        .allocator = a,
                        .task = task_id,
                        .watermark = watermark,
                        .history = .init(a),
                    };
                }

                fn deinit(index: *HistoricalObservers) void {
                    index.history.deinit();
                }

                fn prepare(index: *HistoricalObservers, service: *Self) !void {
                    if (index.observers_present != null) return;
                    var parent = try service.task(index.allocator, index.task);
                    defer parent.deinit();
                    index.watermark = @min(index.watermark, parent.value.event_high);
                    index.observers_present = parent.value.observers_present;
                }

                fn load(index: *HistoricalObservers, service: *Self) !void {
                    if (index.loaded) return;
                    try index.prepare(service);
                    var history = History.init(index.allocator);
                    errdefer history.deinit();
                    var builder = History.Builder.init(service.allocator, &history);
                    defer builder.deinit();
                    var rows = try service.store().database.prepare(
                        "SELECT e.seq, o.body FROM events e JOIN objects o ON o.digest=e.body " ++
                            "WHERE e.task=? AND e.seq<=? ORDER BY e.seq",
                        &.{ .{ .blob = &index.task }, .{
                            .integer = std.math.cast(
                                i64,
                                index.watermark,
                            ) orelse return error.InvalidArchive,
                        } },
                    );
                    defer rows.deinit();
                    while (try rows.step() == .row) {
                        var event_value = try contracts.decodeOwned(
                            state.Event,
                            service.allocator,
                            try rows.bytes(1),
                        );
                        defer event_value.deinit();
                        if (event_value.value.seq != try rows.integer(
                            0,
                        )) return error.InvalidArchive;
                        for (event_value.value.workspace_publications.items) |item|
                            try builder.put(item, event_value.value.seq);
                    }
                    index.history.deinit();
                    index.history = history;
                    index.loaded = true;
                }
            };
        }
        fn observerSourceRevision(
            _: *Self,
            _: std.mem.Allocator,
            work: workspace.Work,
            level: @FieldType(wc.GuestViewSelection, "level"),
        ) !u64 {
            if (level == .guest_cut) return work.execution_revision;
            return (try workspaceOuterCursor(work)).revision;
        }
        fn workspaceOuterCursor(work: workspace.Work) !workspace.OuterCursor {
            var cursor = work.outer_cursor;
            const capsule =
                (if (work.outer_operation) |pending|
                    pending.capsule
                else
                    work.runtime_capsule) orelse
                return cursor;
            if (cursor.last) |previous| {
                if (!std.meta.eql(previous, capsule.digest))
                    cursor.revision = try std.math.add(u64, cursor.revision, 1);
            }
            cursor.last = capsule.digest;
            return cursor;
        }
        fn writeWorkspaceWork(self: *Self, work: *workspace.Work, mode: enum {
            create,
            replace,
        }) !void {
            work.outer_cursor = try workspaceOuterCursor(work.*);
            switch (mode) {
                .create => try self.store().createRecord(
                    workspace.Work,
                    "workspace_work",
                    work.id,
                    work.task,
                    work.*,
                ),
                .replace => try self.store().putRecord(
                    workspace.Work,
                    "workspace_work",
                    work.id,
                    work.task,
                    work.*,
                ),
            }
        }
        fn observerGuestQuantum(self: *Self, a: std.mem.Allocator, source: workspace.Work) !u64 {
            var parent = try self.task(a, source.task);
            defer parent.deinit();
            if (parent.value.observer_heads.items.len != 0) try self.compatible(parent.value);
            for (parent.value.observer_heads.items) |id| {
                var saved = try self.retainedWorkspaceWork(a, source.task, id);
                defer saved.deinit();
                const observer = saved.value.observer orelse return error.CorruptState;
                if (!self.activeObserver(saved.value)) return error.CorruptState;
                if (observer.selection.policy.granularity == .one_guest_step and
                    std.meta.eql(observer.source_work, source.id)) return 1;
            }
            return 256;
        }
        fn retainObservedOuter(self: *Self, a: std.mem.Allocator, value: *workspace.Work) !void {
            var parent = try self.task(a, value.task);
            defer parent.deinit();
            if (parent.value.observer_heads.items.len != 0) try self.compatible(parent.value);
            for (parent.value.observer_heads.items) |id| {
                var work = try self.retainedWorkspaceWork(a, value.task, id);
                defer work.deinit();
                const observer = work.value.observer orelse return error.CorruptState;
                if (!self.activeObserver(work.value)) return error.CorruptState;
                if (observer.selection.source.level != .outer_execution or
                    !std.meta.eql(observer.source_work, value.id)) continue;
                const driver = self.active.?.driver;
                const capsule = try driver.retainCapsule(runtimeProvenance(value.*));
                const code = try driver.runtimeBytes(a);
                defer a.free(code);
                _ = try self.store().putObject(code);
                value.runtime_capsule = try self.store().putObject(capsule);
                value.runtime_dependencies = .{ .items = try capsuleDependencies(a, capsule) };
                return;
            }
        }
        fn validateCapsuleProvenance(
            work: workspace.Work,
            record_value: kosmos.RuntimeCapsule.Record,
        ) !void {
            if (!std.meta.eql(record_value.provenance.execution, work.id) or !std.meta.eql(
                record_value.provenance.custody,
                storage.digest(&work.task),
            ) or
                record_value.provenance.publication == null or !std.meta.eql(
                record_value.provenance.publication.?.digest,
                work.checkpoint.digest,
            ) or
                record_value.provenance.publication.?.bytes != work.checkpoint.bytes)
                return error.InvalidArchive;
        }
        fn validateCapsuleObservation(
            candidate: anytype,
            selected: anytype,
            expected: kosmos.RuntimeInstrumentation.Output,
        ) !void {
            // Re-run only the source observer on a private candidate. A
            // zero-quantum advance does not perform a guest transition.
            if (!std.meta.eql(expected.source, selected.content.value.manifest.source) or
                !std.meta.eql(expected.realization, selected.identity) or
                !std.meta.eql(expected.guest, candidate.guest.admitted().identity()) or
                expected.guest_revision != candidate.guest_revision)
                return error.InvalidArchive;
            var observation = try candidate.exchange(.{ .advance = .{
                .control = .none,
                .quantum = 0,
            } });
            defer observation.deinit();
            if (observation.value != .cut or
                observation.value.cut.guest_work != 0 or
                !std.meta.eql(
                    observation.value.cut.trace,
                    @as(?kosmos.RuntimeInstrumentation.Trace, expected.trace),
                )) return error.InvalidArchive;
        }
        fn validateCompilerArtifact(
            a: std.mem.Allocator,
            saved: workspace.Program,
            artifact: workspace.ProgramArtifact,
        ) !void {
            const artifact_bytes = try contracts.encodeOwned(
                workspace.ProgramArtifact,
                a,
                artifact,
            );
            defer a.free(artifact_bytes);
            if (!std.meta.eql(
                saved.artifact,
                compilerReference(artifact_bytes),
            )) return error.InvalidArchive;
            const contract =
                if (artifact.controller !=
                null) contracts.controller.identity else switch (artifact.source_kind) {
                    .source_records => @import("source_records.zig").identity,
                    .source_derivation => @import("source_records.zig").derivation_identity,
                    .component_recipe => construction.component_identity,
                    .instrument_model, .instrument_snapshot => instrument.identity,
                };
            if (artifact.version != 2 or !same(artifact.construction_contract.bytes, contract) or
                !std.meta.eql(
                    artifact.authoring_identity,
                    storage.digest(@import("native_options").horos_identity),
                )) return error.IncompatibleProfile;
            if (artifact.controller) |descriptor| {
                const schemas = try @import("controller_construction.zig").schemas(a, descriptor);
                defer a.free(schemas);
                if (schemas.len != artifact.controller_schemas.items.len) return error.CorruptState;
                for (schemas, artifact.controller_schemas.items) |schema, ref|
                    if (ref.bytes !=
                        schema.len or
                        !std.meta.eql(
                            ref.digest,
                            storage.digest(schema),
                        )) return error.CorruptState;
            } else if (artifact.controller_schemas.items.len != 0) return error.CorruptState;
        }
        fn validateSeedProgram(
            self: *Self,
            a: std.mem.Allocator,
            artifact: workspace.ProgramArtifact,
        ) !bool {
            if (self.application.controller) |seed| {
                if (std.meta.eql(
                    artifact.source.digest,
                    storage.digest(seed.source),
                ) and artifact.source.bytes == seed.source.len and std.meta.eql(
                    artifact.image.digest,
                    storage.digest(self.assets.image),
                ) and artifact.image.bytes == self.assets.image.len) {
                    if (artifact.source_kind != .source_records or
                        artifact.catalog != null or
                        artifact.exposures.items.len != 0 or
                        artifact.ports.items.len != 0 or
                        artifact.controller == null)
                        return error.CorruptState;
                    const descriptor = try contracts.encodeOwned(
                        contracts.controller.Descriptor,
                        a,
                        artifact.controller.?,
                    );
                    defer a.free(descriptor);
                    if (!same(descriptor, seed.descriptor)) return error.CorruptState;
                    if (comptime @hasDecl(Types, "ControllerInput")) {
                        inline for (.{
                            .{ artifact.input_schema, Types.ControllerInput },
                            .{ artifact.result_schema, Types.Output },
                            .{ artifact.failure_schema, Types.Failure },
                        }) |pair| {
                            const schema = try values.schemaBytes(pair[1], a);
                            defer a.free(schema);
                            if (pair[0].bytes != schema.len or !std.meta.eql(
                                pair[0].digest,
                                storage.digest(schema),
                            )) return error.CorruptState;
                        }
                    } else return error.CorruptState;
                    return true;
                }
            }

            return false;
        }
        fn validateCompiledArtifact(
            a: std.mem.Allocator,
            artifact: workspace.ProgramArtifact,
            built: anytype,
        ) !void {
            inline for (.{
                .{ artifact.image, built.image },
                .{ artifact.input_schema, built.interface.input.bytes },
                .{ artifact.result_schema, built.interface.output.bytes },
                .{ artifact.failure_schema, built.interface.failure.bytes },
            }) |pair| {
                if (pair[0].bytes != pair[1].len or !std.meta.eql(
                    pair[0].digest,
                    storage.digest(pair[1]),
                )) return error.CorruptState;
            }
            if (built.ports.len != artifact.ports.items.len) return error.CorruptState;
            for (built.ports, artifact.ports.items) |actual, declared| {
                if (!same(
                    actual.identity.bytes,
                    declared.identity.bytes,
                ) or actual.class != declared.class) return error.CorruptState;
                inline for (.{ "argument", "observation", "payload", "command" }) |field| {
                    const bytes = @field(actual, field).bytes;
                    const ref = @field(declared, field);
                    if (ref.bytes != bytes.len or !std.meta.eql(
                        ref.digest,
                        storage.digest(bytes),
                    )) return error.CorruptState;
                }
            }
            const actual_controller = try contracts.encodeOwned(
                ?contracts.controller.Descriptor,
                a,
                built.controller,
            );
            defer a.free(actual_controller);
            const declared_controller = try contracts.encodeOwned(
                ?contracts.controller.Descriptor,
                a,
                artifact.controller,
            );
            defer a.free(declared_controller);
            if (!same(actual_controller, declared_controller)) return error.CorruptState;
        }
        fn validateDelegationSelection(
            a: std.mem.Allocator,
            value: workspace.Delegation,
            authorized: workspace.Authorized,
