            const selection = authorized.command.work.delegate;
            if (selection.interpretation == .none or !same(
                try contracts.encodeOwned(wc.Interpretation, a, selection.interpretation),
                try contracts.encodeOwned(wc.Interpretation, a, value.selection),
            ) or
                !std.meta.eql(try wp.identity(selection.expected.work, .work), value.work) or
                (std.math.add(
                    u64,
                    selection.expected.control_revision,
                    1,
                ) catch return error.InvalidArchive) != value.control_revision)
                return error.InvalidArchive;
            if (!same(
                try contracts.encodeOwned(?workspace.ModelBinding, a, authorized.model),
                try contracts.encodeOwned(?workspace.ModelBinding, a, value.model),
            )) return error.InvalidArchive;
            if (!std.meta.eql(
                if (value.selection == .snapshot) authorized.snapshot else null,
                value.snapshot,
            )) return error.InvalidArchive;
        }
        fn validateDelegatedPort(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Delegation,
            selection: anytype,
        ) !void {
            var port = try contracts.decodeOwned(
                workspace.Port,
                a,
                try self.store().object(a, value.port, null),
            );
            defer port.deinit();
            const selected_port = switch (selection.interpretation) {
                .model => |v| v.port,
                .snapshot => |v| v.port,
                .none => unreachable,
            };
            const generation = switch (selection.interpretation) {
                .model => |v| v.generation,
                .snapshot => |v| v.generation,
                .none => unreachable,
            };
            if (!std.meta.eql(port.value.task, parent.id) or
                !std.meta.eql(port.value.work, value.work) or
                !std.meta.eql(port.value.program, value.program) or
                !std.meta.eql(
                    port.value.id,
                    try wp.identity(selected_port, .port),
                ) or port.value.generation != generation) return error.InvalidArchive;
        }
        fn validateDelegatedChild(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
            value: workspace.Delegation,
            selection: anytype,
        ) !void {
            var child = try self.workspaceWork(a, parent.id, value.instrument);
            defer child.deinit();
            if (!std.meta.eql(child.value.delegation, row.body) or !std.meta.eql(
                child.value.origin_work,
                value.work,
            )) return error.InvalidArchive;
            var program = try self.workspaceProgram(a, parent.id, child.value.program);
            defer program.deinit();
            if (program.value.description.source_kind != @as(
                @TypeOf(program.value.description.source_kind),
                if (value.selection == .model) .instrument_model else .instrument_snapshot,
            )) return error.InvalidArchive;
            var input = try contracts.decodeOwned(
                instrument.Input,
                a,
                try self.store().object(a, child.value.input, null),
            );
            defer input.deinit();
            if (!std.meta.eql(input.value.delegation, row.body)) return error.InvalidArchive;
            if (selection.interpretation == .model) {
                if (value.model == null or
                    selection.interpretation.model.inputs.items.len != value.inputs.items.len)
                    return error.InvalidArchive;
                const requested_inputs = selection.interpretation.model.inputs.items;
                for (requested_inputs, value.inputs.items) |ref, expected| {
                    const source = try self.workspaceValueReference(a, parent.id, ref);
                    if (!std.meta.eql(source.artifact, expected)) return error.InvalidArchive;
                }
            } else if (value.model != null or
                value.inputs.items.len != 0 or
                value.snapshot == null)
                return error.InvalidArchive;
        }
        fn storeProgramCustody(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            artifact: workspace.ProgramArtifact,
        ) !state.Reference {
            const bytes = try contracts.encodeOwned(workspace.ProgramArtifact, a, artifact);
            defer a.free(bytes);
            const reference = try self.store().putObject(bytes);
            const id = try workspaceContentCustody(a, task_id, reference.digest);
            const saved: workspace.Program = .{
                .id = id,
                .task = task_id,
                .artifact = reference,
                .description = artifact,
            };
            if (try self.store().recordBytes(a, "workspace_program", id, task_id)) |prior| {
                defer a.free(prior);
                const expected = try contracts.encodeOwned(workspace.Program, a, saved);
                defer a.free(expected);
                if (!same(prior, expected)) return error.CorruptState;
            } else try self.store().createRecord(
                workspace.Program,
                "workspace_program",
                id,
                task_id,
                saved,
            );
            return reference;
        }
        fn validateCapsuleOperation(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            ref: state.Reference,
            trace: ?kosmos.RuntimeInstrumentation.Output,
            pending_operation: ?workspace.OuterOperation,
            record_value: kosmos.RuntimeCapsule.Record,
            command: anytype,
        ) !void {
            if (pending_operation) |pending| {
                if (trace != null or
                    record_value.operation != .advance or
                    record_value.kind != .outer_execution or
                    !std.meta.eql(
                        ref,
                        pending.capsule,
                    ) or pending.guest_quantum > 256) return error.InvalidArchive;
                try self.validateOuterControl(a, work, pending, command);
            } else if (record_value.operation != null) return error.InvalidArchive;
        }
        fn validateInstrumentAnswerValue(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            child: workspace.Work,
            output: instrument.Output,
            admitted: anytype,
        ) !void {
            const answer_ref = child.answer_value orelse return error.InvalidArchive;
            const answer = try self.workspaceValueReference(
                a,
                parent.id,
                try wp.reference(a, .value, answer_ref.digest),
            );
            const delegation_ref = child.delegation orelse return error.InvalidArchive;
            var delegation = try contracts.decodeOwned(
                workspace.Delegation,
                a,
                try self.store().object(a, delegation_ref, null),
            );
            defer delegation.deinit();
            var port = try contracts.decodeOwned(
                workspace.Port,
                a,
                try self.store().object(a, delegation.value.port, null),
            );
            defer port.deinit();
            if (!std.meta.eql(answer.artifact, answer_ref) or
                !std.meta.eql(answer.schema, port.value.interface.argument) or
                !std.meta.eql(answer.value, state.Reference{
                    .digest = storage.digest(output.answer.bytes),
                    .bytes = output.answer.bytes.len,
                })) return error.InvalidArchive;
            const expected: workspace.Derivation = switch (delegation.value.selection) {
                .snapshot => |selected| .{
                    .kind = .acquisition,
                    .sources = .{ .items = &.{} },
                    .acquisition = try self.workspaceSnapshotRange(
                        a,
                        parent,
                        delegation.value.snapshot orelse return error.InvalidArchive,
                        selected,
                    ),
                },
                .model => blk: {
                    var capture_value = try self.record(
                        state.Capture,
                        a,
                        "capture",
                        admitted.attempt,
                        parent.id,
                    );
                    defer capture_value.deinit();
                    break :blk .{
                        .kind = .judgment,
                        .sources = delegation.value.inputs,
                        .work = child.id,
                        .delegation = delegation_ref,
                        .capture = capture_value.value.response orelse return error.InvalidArchive,
                    };
                },
                else => return error.InvalidArchive,
            };
            const provenance = try contracts.encodeOwned(workspace.Derivation, a, expected);
            if (!std.meta.eql(answer.provenance, state.Reference{
                .digest = storage.digest(provenance),
                .bytes = provenance.len,
            })) return error.InvalidArchive;
        }
        fn validateWorkspaceReceipts(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const task_id = parent.id;
            if (parent.controller_epoch != try self.controllerEpochAt(
                a,
                parent,
                parent.event_high,
            )) return error.InvalidArchive;
            var receipts = try self.store().database.prepare(
                "SELECT o.body FROM operations p JOIN objects o ON o.digest=p.rec" ++
                    "eipt WHERE p.task=?",
                &.{.{ .blob = &task_id }},
            );
            defer receipts.deinit();
            while (try receipts.step() == .row) {
                var receipt_arena = std.heap.ArenaAllocator.init(self.allocator);
                defer receipt_arena.deinit();
                const frame = receipt_arena.allocator();
                var receipt_value = try contracts.decodeOwned(
                    state.Receipt,
                    frame,
                    try receipts.bytes(0),
                );
                defer receipt_value.deinit();
                try self.validateWorkspaceReceipt(
                    frame,
                    parent,
                    receipt_value.value,
                    records,
                    checked,
                );
            }
        }
        fn validateWorkspaceControllerBindings(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            records: []const state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;
            var controller_ids: std.AutoHashMap(state.Digest, void) = .init(a);
            var controller_cursor = parent.controller;
            var controller_epoch: ?u64 = null;
            var controller_activation: ?u64 = null;
            while (controller_cursor) |id| {
                var binding_arena = std.heap.ArenaAllocator.init(self.allocator);
                defer binding_arena.deinit();
                const frame = binding_arena.allocator();
                try requireArchiveRecord(records, .controller_binding, id);
                const binding = try self.controllerBinding(frame, parent, id);
                if (controller_epoch) |epoch| if (binding.epoch >= epoch)
                    return error.InvalidArchive;
                if (binding.activated_at == 0 or
                    binding.activated_at > parent.event_high)
                    return error.InvalidArchive;
                if (controller_activation) |at| if (binding.activated_at >= at)
                    return error.InvalidArchive;
                if (binding.predecessor == null and binding.epoch != 0) return error.InvalidArchive;
                if (binding.epoch > parent.controller_epoch) return error.InvalidArchive;
                if (binding.predecessor != null)
                    try self.validateBindingSuccession(frame, task_id, records, binding);

                var image = try data.program_image.decode(
                    self.allocator,
                    try self.store().object(frame, binding.image, null),
                );
                defer image.deinit();
                if (!std.meta.eql(
                    image.identity,
                    binding.program_identity,
                )) return error.InvalidArchive;
                try controller_ids.put(id, {});
                controller_epoch = binding.epoch;
                controller_activation = binding.activated_at;
                controller_cursor = binding.predecessor;
            }
            for (records) |row| if (row.kind == .controller_binding and !controller_ids.contains(
                row.id,
            )) return error.InvalidArchive;
            if (parent.controller_interaction) |id| {
                try requireArchiveRecord(records, .controller_interaction, id);
                var interaction = try self.record(
                    state.ControllerInteraction,
                    a,
                    "controller_interaction",
                    id,
                    task_id,
                );
                defer interaction.deinit();
                if (!std.meta.eql(
                    @as(?state.Digest, interaction.value.controller),
                    parent.controller,
                )) return error.InvalidArchive;
            }
        }
        fn validateWorkspaceGenerations(
            self: *Self,
            parent: state.Task,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
            generations: anytype,
        ) !void {
            const task_id = parent.id;
            for (records) |row| {
                if (row.kind != .workspace_work) continue;
                var work_arena = std.heap.ArenaAllocator.init(self.allocator);
                defer work_arena.deinit();
                const frame = work_arena.allocator();
                var saved = try self.workspaceWork(frame, task_id, row.id);
                defer saved.deinit();
                const value = saved.value;
                for (0..std.math.cast(
                    usize,
                    value.port_generation,
                ) orelse return error.InvalidArchive) |i| if (!generations.contains(.{
                    .work = value.id,
                    .generation = i + 1,
                })) return error.InvalidArchive;
                try self.validateWorkspaceWorkSnapshotIn(
                    parent,
                    try self.freezeWorkspaceWork(
                        frame,
                        task_id,
                        try wp.reference(frame, .work, value.id),
                        true,
                    ),
                    records,
                    checked,
                );
            }
        }
        fn validateWorkspaceRecordBody(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
            generations: anytype,
        ) !void {
            switch (row.kind) {
                .controller_succession,
                .controller_residual,
                .controller_interaction,
                => try self.validateArchiveControllerRecord(
                    parent,
                    row,
                    records,
                    checked,
                ),
                .workspace_trial => try self.validateArchiveWorkspaceTrial(frame, parent, row),
                .root_operation => try self.validateArchiveRootOperation(frame, parent, row),
                .workspace_runtime => try self.validateArchiveWorkspaceRuntime(frame, parent, row),
                .workspace_candidate => try self.validateArchiveWorkspaceCandidate(
                    frame,
                    parent,
                    row,
                ),
                .workspace_program => try self.validateArchiveWorkspaceProgram(frame, parent, row),
                .workspace_value => try self.validateArchiveWorkspaceValue(
                    frame,
                    parent,
                    row,
                    records,
                    checked,
                ),
                .workspace_view => try self.validateArchiveWorkspaceView(frame, parent, row),
                .workspace_port => try self.validateArchiveWorkspacePort(
                    frame,
                    parent,
                    row,
                    records,
                    generations,
                ),
                .workspace_port_reply => try self.validateArchiveWorkspacePortReply(
                    frame,
                    parent,
                    row,
                ),
                .execution_route => try requireArchiveRecord(records, .occurrence, row.id),
                .workspace_reply => try self.validateArchiveWorkspaceReply(
                    frame,
                    parent,
                    row,
                    records,
                ),
                .workspace_delegation => try self.validateDelegation(
                    frame,
                    parent,
                    row,
                    records,
                ),
                .workspace_wait => try self.validateArchiveWorkspaceWait(
                    frame,
                    parent,
                    row,
                    records,
                ),
                else => {},
            }
        }
        fn validateArchiveWorkspaceTrial(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var work = try self.workspaceWork(frame, task_id, row.id);
            defer work.deinit();
            if (!std.meta.eql(work.value.trial, row.id)) return error.InvalidArchive;
        }
        fn validateArchiveRootOperation(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var saved = try self.record(
                state.RootOperation,
                frame,
                "root_operation",
                row.id,
                task_id,
            );
            defer saved.deinit();
            _ = try self.validateRootOperation(frame, parent, saved.value);
        }
        fn validateArchiveWorkspaceRuntime(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var record_value = try self.record(
                workspace.Runtime,
                frame,
                "workspace_runtime",
                row.id,
                task_id,
            );
            defer record_value.deinit();
            var admitted = try self.workspaceRuntime(
                frame,
