        }
        fn validateArchiveWorkspaceCandidate(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var saved = try self.record(
                workspace.Candidate,
                frame,
                "workspace_candidate",
                row.id,
                task_id,
            );
