        }
        fn validateArchiveWorkspaceProgram(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var record_value = try self.record(
                workspace.Program,
                frame,
                "workspace_program",
                row.id,
                task_id,
            );
            defer record_value.deinit();
            var admitted = try self.workspaceProgram(
                frame,
                task_id,
                record_value.value.artifact.digest,
            );
            defer admitted.deinit();
        }
        fn validateArchiveWorkspaceValue(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const task_id = parent.id;

            var record_value = try self.record(
                workspace.Value,
                frame,
                "workspace_value",
                row.id,
                task_id,
            );
            defer record_value.deinit();
            const admitted = try self.workspaceValueReferenceIn(
                frame,
                task_id,
                try wp.reference(frame, .value, record_value.value.artifact.digest),
                checked,
            );
            const descriptor_bytes = try self.store().object(frame, admitted.schema, null);
            var descriptor = try data.schema.decode(frame, descriptor_bytes);
            defer descriptor.deinit();
            try data.schema.validateValue(
                frame,
                descriptor.descriptor,
                try self.store().object(frame, admitted.value, null),
            );
            for (record_value.value.derivation.sources.items) |ref| {
                const source = try self.workspaceValueReferenceIn(
                    frame,
                    task_id,
                    try wp.reference(frame, .value, ref.digest),
                    checked,
                );
                if (!std.meta.eql(source.artifact, ref)) return error.InvalidArchive;
            }
            try self.validateArchiveValueDerivation(
                frame,
                parent,
                record_value.value,
                admitted,
                records,
                checked,
            );
        }
        fn validateArchiveWorkspaceView(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var record_value = try self.record(
                workspace.View,
                frame,
                "workspace_view",
                row.id,
                task_id,
            );
            defer record_value.deinit();
            _ = try self.workspaceViewObservation(
                frame,
                task_id,
                record_value.value.artifact.digest,
                .{ .maximum = 1 },
            );
        }
        fn validateArchiveWorkspacePort(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
            records: []const state.ArchiveRecord,
            generations: anytype,
        ) !void {
            const task_id = parent.id;

            var port = try self.record(
                workspace.Port,
                frame,
                "workspace_port",
                row.id,
                task_id,
            );
            defer port.deinit();
            try requireArchiveRecord(records, .occurrence, port.value.occurrence);
            var route = try self.record(
                workspace.ExecutionRoute,
                frame,
                "execution_route",
                port.value.occurrence,
                task_id,
            );
            defer route.deinit();
            if (route.value.port == null or !std.meta.eql(
                route.value.port.?,
                row.body,
            )) return error.InvalidArchive;
            const entry = try generations.getOrPut(.{
                .work = port.value.work,
                .generation = port.value.generation,
            });
            if (entry.found_existing) return error.InvalidArchive;
        }
        fn validateArchiveWorkspacePortReply(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var answer = try self.record(
                workspace.PortReply,
                frame,
                "workspace_port_reply",
                row.id,
                task_id,
            );
            defer answer.deinit();
            var port = try contracts.decodeOwned(
                workspace.Port,
                frame,
                try self.store().object(frame, answer.value.port, null),
            );
            defer port.deinit();
            var pending = try self.record(
                occurrence.Occurrence,
                frame,
                "occurrence",
                port.value.occurrence,
                task_id,
            );
            defer pending.deinit();
            const acquired = switch (pending.value.state) {
                .settled_reply => |reply| reply,
                .admitted => |admitted| if (admitted ==
                    .reply) admitted.reply else return error.InvalidArchive,
                else => return error.InvalidArchive,
            };
            if (!std.meta.eql(acquired.attempt, row.id) or !std.meta.eql(
                acquired.reply,
                answer.value.reply.digest,
            )) return error.InvalidArchive;
        }
        fn validateArchiveWorkspaceReply(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
            records: []const state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            try requireArchiveRecord(records, .occurrence, row.id);
            var pending = try self.record(
                occurrence.Occurrence,
                frame,
                "occurrence",
                row.id,
                task_id,
            );
            defer pending.deinit();
            if (pending.value.work != null or
                !(pending.value.state == .settled_reply or
                    (pending.value.state == .admitted and
                        pending.value.state.admitted == .reply)))
                return error.InvalidArchive;
        }
        fn validateArchiveWorkspaceWait(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            row: state.ArchiveRecord,
            records: []const state.ArchiveRecord,
        ) !void {
            const task_id = parent.id;

            var wait = try self.record(
                workspace.Wait,
                frame,
                "workspace_wait",
                row.id,
                task_id,
            );
            defer wait.deinit();
            try requireArchiveRecord(records, .occurrence, wait.value.id);
            var pending = try self.record(
                occurrence.Occurrence,
                frame,
                "occurrence",
                wait.value.id,
                task_id,
            );
            defer pending.deinit();
            if (pending.value.work != null or !std.meta.eql(
                wait.value.request,
                pending.value.request_object,
            )) return error.InvalidArchive;
            var request = try data.invocation.decode(
                data.invocation.Request,
                frame,
                try self.store().object(frame, wait.value.request, null),
            );
            defer request.deinit();
            const entry = try self.handlers.resolve(
                request.value,
                try self.occurrenceImage(frame, parent, pending.value),
            );
            if (entry.declaration.kind != .workspace) return error.InvalidArchive;
            var authorized = try contracts.decodeOwned(
                workspace.Authorized,
                frame,
                try self.authorizeWorkspaceOccurrence(
                    frame,
                    parent,
                    pending.value,
                    entry,
                    request.value.binding.payload,
                ),
            );
            defer authorized.deinit();
            try self.validateWaitSelection(frame, task_id, wait.value, authorized.value);
        }
        fn validateWorkspaceReceipt(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            receipt_value: state.Receipt,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const task_id = parent.id;
            if (receipt_value.method == .workspace and
                receipt_value.workspace_kind == .residual)
            {
                try self.validateResidualReceipt(frame, parent, receipt_value);
                return;
            }
            if (receipt_value.method != .workspace or
                receipt_value.workspace_kind != .work)
                return;
            var observed = try contracts.decodeOwned(
                workspace.WorkObservation,
                frame,
                try self.store().object(
                    frame,
                    receipt_value.workspace_observation orelse
                        return error.InvalidArchive,
                    null,
                ),
            );
            defer observed.deinit();
            if (!std.meta.eql(receipt_value.task, task_id) or !std.meta.eql(
                receipt_value.workspace orelse return error.InvalidArchive,
                observed.value.work.id,
            )) return error.InvalidArchive;
            var publication = try self.store().database.prepare(
                "SELECT revision FROM events WHERE task=? AND seq=?",
                &.{ .{ .blob = &task_id }, .{
                    .integer = std.math.cast(
                        i64,
                        observed.value.work.event_watermark,
                    ) orelse return error.InvalidArchive,
                } },
            );
            defer publication.deinit();
            if (try publication.step() != .row or try publication.integer(
                0,
            ) != std.math.cast(
                i64,
                receipt_value.revision,
            ) orelse return error.InvalidArchive) return error.InvalidArchive;
            try self.validateWorkspaceWorkSnapshotIn(
                parent,
                observed.value,
                records,
                checked,
            );
            try self.validateHistoricalOccurrence(frame, observed.value);
        }
        fn validateResidualReceipt(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            receipt_value: state.Receipt,
        ) !void {
            const task_id = parent.id;
            var residual = try contracts.decodeOwned(
                state.ControllerResidual,
                frame,
                try self.store().object(
                    frame,
                    receipt_value.workspace_observation orelse
                        return error.InvalidArchive,
                    null,
                ),
            );
            defer residual.deinit();
            if (!std.meta.eql(receipt_value.workspace, residual.value.id) or
                !std.meta.eql(residual.value.task, task_id)) return error.InvalidArchive;
            try self.validateResidualObservation(frame, .from(residual.value));
            if (residual.value.outer_operation) |pending|
                _ =
                    try self.validateControllerOperation(
                        frame,
                        parent,
                        pending,
                        residual.value,
                        true,
                    );
        }
        fn validateBindingSuccession(
            self: *Self,
            frame: std.mem.Allocator,
            task_id: state.TaskId,
            records: []const state.ArchiveRecord,
            binding: anytype,
        ) !void {
            var matching: usize = 0;
            for (records) |row| if (row.kind == .controller_succession) {
                var operation_value = try self.record(
                    state.ControllerSuccession,
                    frame,
                    "controller_succession",
                    row.id,
                    task_id,
                );
                defer operation_value.deinit();
                if (operation_value.value.phase == .activated and
                    operation_value.value.activation_event == binding.activated_at and
                    operation_value.value.activated_epoch == binding.epoch and
                    std.meta.eql(
                        operation_value.value.predecessor,
                        binding.predecessor.?,
                    ) and std.meta.eql(
                    operation_value.value.successor,
                    binding.program,
                )) matching += 1;
            };
            if (matching != 1) return error.InvalidArchive;
        }
        fn selectCapsuleRuntime(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            runtime_ref: state.Reference,
            expected_runtime: ?state.Reference,
            image: []const u8,
        ) !kosmos.RuntimeArtifact {
            return if (expected_runtime) |expected| chosen: {
                if (!std.meta.eql(runtime_ref, expected)) return error.InvalidArchive;
                var owned = try self.workspaceRuntime(a, work.task, expected.digest, work.program);
                defer owned.deinit();
                if (!std.meta.eql(
                    owned.record.value.artifact,
                    expected,
                )) return error.InvalidArchive;
                break :chosen try owned.admitted.clone();
            } else chosen: {
                var packaged = try self.program.prepare(a, image);
                defer packaged.deinit();
                if (!std.meta.eql(runtime_ref.digest, packaged.runtime.identity) or
                    runtime_ref.bytes != packaged.runtime.core.?.encoded_length)
                    return error.InvalidArchive;
                break :chosen try packaged.runtime.clone();
            };
        }
        fn validateSnapshotCurrent(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            current: workspace.Work,
            checked: *SnapshotValidation,
        ) !void {
            try self.validateObserver(a, value, &checked.observer_successors);
            if (value.observer != null and !parent.observers_present) return error.InvalidArchive;
            inline for (.{
                "version",
                "program",
                "input",
                "input_value",
                "origin_work",
                "delegation",
                "trial",
            }) |field|
                if (!std.meta.eql(
                    @field(value, field),
                    @field(current, field),
                )) return error.InvalidArchive;
            inline for (.{
                "execution_revision",
                "control_revision",
                "realization_revision",
                "port_generation",
                "event_watermark",
            }) |field|
                if (@field(value, field) > @field(current, field))
                    return error.InvalidArchive;
            if (value.realization_revision == current.realization_revision and !std.meta.eql(
                value.runtime,
                current.runtime,
            )) return error.InvalidArchive;
        }
        fn validateSnapshotRuntime(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            records: []const state.ArchiveRecord,
            phase: *[]const u8,
        ) !void {
            if (value.runtime) |ref| {
                phase.* = "selected runtime";
                var selected = try self.workspaceRuntime(a, parent.id, ref.digest, value.program);
                defer selected.deinit();
                if (!std.meta.eql(ref, selected.record.value.artifact)) return error.InvalidArchive;
                try requireArchiveRecord(records, .workspace_runtime, selected.record.value.id);
            }
            if (value.outer_operation) |pending| {
                phase.* = "outer operation";
                try self.validatePublishedCapsuleTrace(
                    a,
                    value,
                    pending.capsule,
                    value.runtime,
                    null,
                    pending,
                );
                const capsule_bytes = try self.store().object(a, pending.capsule, null);
                defer a.free(capsule_bytes);
                const dependencies = try capsuleDependencies(a, capsule_bytes);
                defer a.free(dependencies);
                if (dependencies.len != pending.dependencies.items.len) return error.InvalidArchive;
                for (dependencies, pending.dependencies.items) |wanted, actual| if (!std.meta.eql(
                    wanted,
                    actual,
                )) return error.InvalidArchive;
            }
            if (value.runtime_capsule) |ref| {
                phase.* = "runtime capsule";
                if (value.outer_operation) |pending| {
                    if (!std.meta.eql(ref, pending.capsule)) return error.InvalidArchive;
                } else try self.validatePublishedCapsule(a, value, ref, value.runtime);
                const capsule_bytes = try self.store().object(a, ref, null);
                defer a.free(capsule_bytes);
                const dependencies = try capsuleDependencies(a, capsule_bytes);
                defer a.free(dependencies);
                if (dependencies.len != value.runtime_dependencies.items.len)
                    return error.InvalidArchive;
                for (dependencies, value.runtime_dependencies.items) |wanted, actual|
                    if (!std.meta.eql(wanted, actual)) return error.InvalidArchive;
            } else if (value.runtime_dependencies.items.len != 0) return error.InvalidArchive;
            if (value.runtime_trace) |trace| {
                phase.* = "runtime trace";
                try self.validatePublishedCapsuleTrace(
                    a,
                    value,
                    trace.capsule,
                    value.runtime,
                    trace.output,
                    null,
                );
                const bytes = try self.store().object(a, trace.capsule, null);
                defer a.free(bytes);
                const dependencies = try capsuleDependencies(a, bytes);
                defer a.free(dependencies);
                if (dependencies.len != trace.dependencies.items.len) return error.InvalidArchive;
                for (dependencies, trace.dependencies.items) |wanted, actual| if (!std.meta.eql(
                    wanted,
                    actual,
                )) return error.InvalidArchive;
            }
        }
        fn validateSnapshotProgress(
            parent: state.Task,
            value: workspace.Work,
            current: workspace.Work,
        ) !void {
            inline for (.{
                "result",
                "result_value",
                "answer_value",
                "instrument_occurrence",
            }) |field| {
                if (@field(value, field) != null and !std.meta.eql(
                    @field(value, field),
                    @field(current, field),
                )) return error.InvalidArchive;
            }
            if (value.cancellation) |reason| {
                const actual = current.cancellation orelse return error.InvalidArchive;
                if (!same(reason.bytes, actual.bytes)) return error.InvalidArchive;
            }
            if (value.cancellation_applied and
                !current.cancellation_applied)
                return error.InvalidArchive;
            if (value.terminal() and
                value.execution_revision != current.execution_revision)
                return error.InvalidArchive;
            if (value.execution_revision == current.execution_revision) {
                inline for (.{
                    "checkpoint",
                    "outcome",
                    "outcome_kind",
                    "current_occurrence",
                    "current_port",
                    "port_generation",
                    "result",
                    "result_value",
                    "answer_value",
                    "guest_work",
                }) |field|
                    if (!std.meta.eql(
                        @field(value, field),
                        @field(current, field),
                    )) return error.InvalidArchive;
            }
            if (value.execution_revision == 0 or
                value.control_revision == 0 or
                value.event_watermark > parent.event_high or
                (value.cancellation_applied and
                    value.cancellation == null))
                return error.InvalidArchive;
        }
        fn validateSnapshotTrial(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            current: workspace.Work,
            program: workspace.Program,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            if ((program.description.controller != null) != (value.trial != null))
                return error.InvalidArchive;
            if (value.trial) |id| {
                if (!std.meta.eql(id, value.id) or !std.meta.eql(
                    value.trial,
                    current.trial,
                )) return error.InvalidArchive;
                try requireArchiveRecord(records, .workspace_trial, id);
                var trial = try self.record(workspace.Trial, a, "workspace_trial", id, parent.id);
                defer trial.deinit();
                if (trial.value.selection != .synthetic or
                    trial.value.responses.items.len !=
                        trial.value.selection.synthetic.responses.items.len or
                    value.inputs.items.len != trial.value.responses.items.len * 2 or
                    !std.meta.eql(
                        trial.value.policy,
                        parent.profile,
                    )) return error.InvalidArchive;
                var view = try contracts.decodeOwned(
                    contracts.controller.OwnerView,
                    a,
                    try self.store().object(a, trial.value.view, null),
                );
                defer view.deinit();
                if (!std.meta.eql(
                    view.value.task,
                    parent.id,
                ) or view.value.event_cut >= value.event_watermark or !std.meta.eql(
                    view.value.policy,
                    parent.profile.digest,
                )) return error.InvalidArchive;
                try self.validateControllerViewIn(
                    a,
                    parent,
                    view.value,
                    trial.value.view_works.items,
                    records,
                    checked,
                );
                try self.validateTrialResponses(a, parent, value, trial.value, checked);
            }
        }
        fn validateSnapshotDelegationInputs(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            program: workspace.Program,
            native_program: bool,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            if (native_program != (value.delegation != null) or
                (value.delegation == null and
                    (value.answer_value != null or
                        value.instrument_occurrence != null)))
                return error.InvalidArchive;
            if (value.delegation) |ref| {
                var delegation = try contracts.decodeOwned(
                    workspace.Delegation,
                    a,
                    try self.store().object(a, ref, null),
                );
                defer delegation.deinit();
                try requireArchiveRecord(records, .workspace_delegation, delegation.value.id);
                if (!std.meta.eql(
                    delegation.value.instrument,
                    value.id,
                )) return error.InvalidArchive;
                if (value.instrument_occurrence) |id| try requireArchiveRecord(
                    records,
                    .occurrence,
                    id,
                );
            }
            const input = try self.workspaceValueReferenceIn(
                a,
                parent.id,
                try wp.reference(
                    a,
                    .value,
                    (value.input_value orelse return error.InvalidArchive).digest,
                ),
                checked,
            );
            if (!std.meta.eql(input.value, value.input) or !std.meta.eql(
                input.schema,
                program.description.input_schema,
            )) return error.InvalidArchive;
            for (value.inputs.items) |ref| _ = try self.workspaceValueReferenceIn(
                a,
                parent.id,
                try wp.reference(a, .value, ref.digest),
                checked,
            );
        }
        fn validateSnapshotExecution(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            program: workspace.Program,
            native_program: bool,
            checked: *SnapshotValidation,
        ) !void {
            var prepared = try self.inspectionRuntime(self.allocator, value);
            defer prepared.deinit();
            const checkpoint = try self.store().object(a, value.checkpoint, null);
            defer a.free(checkpoint);
            var candidate = try kosmos.Session.restore(self.allocator, &prepared, checkpoint);
            defer candidate.deinit();
            var finished = try kosmos.invocation.finishPublication(a, &candidate, .receipt, null);
            defer finished.outcome.deinit();
            defer self.allocator.free(finished.checkpoint.?);
            try self.validateGuardAgreement(a, value, &candidate);
            const publication = .{
                .outcome = try data.invocation.encodeOwned(
                    data.invocation.Outcome,
                    a,
                    finished.outcome.record,
                ),
                .checkpoint = finished.checkpoint.?,
            };
            defer a.free(publication.outcome);
            if (!std.meta.eql(
                storage.digest(publication.outcome),
                value.outcome.digest,
            ) or publication.outcome.len != value.outcome.bytes or
                !std.meta.eql(
                    storage.digest(publication.checkpoint),
                    value.checkpoint.digest,
                ) or
                publication.checkpoint.len != value.checkpoint.bytes)
                return error.InvalidArchive;
            var observed = try data.invocation.decode(
                data.invocation.Outcome,
                a,
                publication.outcome,
            );
            defer observed.deinit();
            if (!same(
                @tagName(observed.value),
                @tagName(value.outcome_kind),
            )) return error.InvalidArchive;
            try validateCancellation(a, value, observed.value, publication.checkpoint);
            try self.validateSnapshotOutcome(a, parent, value, program, observed.value, checked);

            if (observed.value != .requested and
                (value.current_occurrence != null or
                    value.current_port != null))
                return error.InvalidArchive;
            if (native_program) try self.validateWorkspaceInstrumentAnswer(a, parent, value);
        }
        fn validateSnapshotOutcome(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            program: workspace.Program,
            observed: data.invocation.Outcome,
            checked: *SnapshotValidation,
        ) !void {
            switch (observed) {
                .requested => |pending| {
                    const id = value.current_occurrence orelse return error.InvalidArchive;
                    var occurrence_value = try self.record(
                        occurrence.Occurrence,
                        a,
                        "occurrence",
                        id,
                        parent.id,
                    );
                    defer occurrence_value.deinit();
                    if (!std.meta.eql(occurrence_value.value.request_object, state.Reference{
                        .digest = storage.digest(pending.request),
                        .bytes = pending.request.len,
                    })) return error.InvalidArchive;
                    var route = try self.record(
                        workspace.ExecutionRoute,
                        a,
                        "execution_route",
                        id,
                        parent.id,
                    );
                    defer route.deinit();
                    if (!std.meta.eql(
                        value.current_port,
                        route.value.port,
                    )) return error.InvalidArchive;
                },
                .completed => |bytes| try self.validateSnapshotResult(
                    a,
                    parent,
                    value,
                    program,
                    bytes,
                    checked,
                ),
                else => if (value.result != null or
                    value.result_value != null)
                    return error.InvalidArchive,
            }
        }
        fn validateTrialResponses(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            trial: workspace.Trial,
            checked: *SnapshotValidation,
        ) !void {
            const selected_responses = trial.selection.synthetic.responses.items;
            for (selected_responses, trial.responses.items, 0..) |selection, response, i| {
                if (!same(
                    selection.identity.bytes,
                    response.identity.bytes,
                ) or !std.meta.eql(
                    (try self.workspaceValueReferenceIn(
                        a,
                        parent.id,
                        selection.payload,
                        checked,
                    )).artifact,
                    response.payload,
                ) or !std.meta.eql(
                    (try self.workspaceValueReferenceIn(
                        a,
                        parent.id,
                        selection.response,
                        checked,
                    )).artifact,
                    response.response,
                ) or !std.meta.eql(
                    value.inputs.items[i * 2],
                    response.payload,
                ) or !std.meta.eql(
                    value.inputs.items[i * 2 + 1],
                    response.response,
                )) return error.InvalidArchive;
                const payload = try self.workspaceValueReferenceIn(
                    a,
                    parent.id,
                    selection.payload,
                    checked,
                );
                for (trial.selection.synthetic.responses.items[0..i]) |prior| {
                    if (!same(selection.identity.bytes, prior.identity.bytes)) continue;
                    const previous = try self.workspaceValueReferenceIn(
                        a,
                        parent.id,
                        prior.payload,
                        checked,
                    );
                    if (std.meta.eql(payload.schema, previous.schema) and std.meta.eql(
                        payload.value,
                        previous.value,
                    )) return error.InvalidArchive;
                }
            }
        }
        fn validateArchiveValueDerivation(
            self: *Self,
            frame: std.mem.Allocator,
            parent: state.Task,
            record_value: workspace.Value,
            admitted: anytype,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            const task_id = parent.id;
            const derivation = record_value.derivation;
            if (derivation.inspection) |origin|
                try self.validateWorkspaceWorkSnapshotIn(
                    parent,
                    origin.observation,
                    records,
                    checked,
                );
            if (derivation.semantic_source) |origin| {
                const request: wc.Command = .{ .program = .{ .inspect = .{
                    .target = .{ .semantic_source = .{
                        .subject = origin.selection.subject,
                        .section = .{ .summary = .{} },
                    } },
                    .page = .{},
                } } };
                try self.validateWorkspaceReadIn(
                    frame,
                    parent,
                    request,
                    origin.basis,
                    records,
                    checked.controller_values.get(record_value.artifact.digest),
                    checked,
                );
            }
            if (derivation.kind == .computation or derivation.kind == .trial) {
                try self.validateComputedValueDerivation(frame, task_id, derivation, admitted);
            } else if (derivation.delegation != null) {
                try self.validateDelegatedValue(frame, task_id, record_value);
            } else if (derivation.program != null or
                derivation.work != null or
                derivation.capture != null)
                return error.InvalidArchive;
        }
        fn validateCapsuleCheckpoint(
            a: std.mem.Allocator,
            work: workspace.Work,
            candidate: anytype,
            selected: anytype,
            trace: ?kosmos.RuntimeInstrumentation.Output,
        ) !void {
            const checkpoint = try candidate.checkpoint(a);
            defer a.free(checkpoint);
            if (!std.meta.eql(
                storage.digest(checkpoint),
                work.checkpoint.digest,
            ) or checkpoint.len != work.checkpoint.bytes) return error.InvalidArchive;
            if (trace) |expected| try validateCapsuleObservation(candidate, selected, expected);
        }
        fn validateWaitSelection(
            self: *Self,
            frame: std.mem.Allocator,
            task_id: state.TaskId,
            wait: workspace.Wait,
            authorized: workspace.Authorized,
        ) !void {
            if (authorized.command != .work or
                authorized.command.work != .wait)
                return error.InvalidArchive;
            const expected = try contracts.encodeOwned(
                @TypeOf(wait.selection),
                frame,
                authorized.command.work.wait,
            );
            const actual = try contracts.encodeOwned(
                @TypeOf(wait.selection),
                frame,
                wait.selection,
            );
            if (!same(actual, expected)) return error.InvalidArchive;
            for (wait.selection.works.items) |ref| {
                var work = try self.workspaceWork(
                    frame,
                    task_id,
                    try wp.identity(ref, .work),
                );
                work.deinit();
            }
        }
        fn validateSnapshotResult(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            program: workspace.Program,
            bytes: []const u8,
            checked: *SnapshotValidation,
        ) !void {
            if (value.result == null or value.result_value == null or !std.meta.eql(
                value.result.?,
                state.Reference{ .digest = storage.digest(bytes), .bytes = bytes.len },
            )) return error.InvalidArchive;
            const result = try self.workspaceValueReferenceIn(
                a,
                parent.id,
                try wp.reference(a, .value, value.result_value.?.digest),
                checked,
            );
            if (!std.meta.eql(
                result.artifact,
                value.result_value.?,
            ) or !std.meta.eql(result.value, value.result.?) or !std.meta.eql(
                result.schema,
                program.description.result_schema,
            )) return error.InvalidArchive;
            var retained = try self.record(
                workspace.Value,
                a,
                "workspace_value",
                try workspaceContentCustody(a, parent.id, result.artifact.digest),
                parent.id,
            );
            defer retained.deinit();
            const expected = try self.workspaceResultDerivation(a, value, program);
            if (!same(
                try contracts.encodeOwned(workspace.Derivation, a, expected),
                try contracts.encodeOwned(
                    workspace.Derivation,
                    a,
                    retained.value.derivation,
                ),
            )) return error.InvalidArchive;
        }
        fn validateComputedValueDerivation(
            self: *Self,
            frame: std.mem.Allocator,
            task_id: state.TaskId,
            derivation: workspace.Derivation,
            admitted: anytype,
        ) !void {
            var work = try self.workspaceWork(
                frame,
                task_id,
                derivation.work orelse return error.InvalidArchive,
            );
            defer work.deinit();
            var program = try self.workspaceProgram(frame, task_id, work.value.program);
            defer program.deinit();
            if ((derivation.kind == .trial) != (work.value.trial != null))
                return error.InvalidArchive;
            if (work.value.result_value == null or !std.meta.eql(
                work.value.result_value.?,
                admitted.artifact,
            ) or
                work.value.result == null or !std.meta.eql(
                work.value.result.?,
                admitted.value,
            ) or
                derivation.program == null or !std.meta.eql(
                derivation.program.?,
                program.value.artifact,
            ) or
                !std.meta.eql(admitted.schema, program.value.description.result_schema) or
                derivation.sources.items.len != work.value.inputs.items.len + 1 or
                work.value.input_value == null or
                !std.meta.eql(
                    derivation.sources.items[0],
                    work.value.input_value.?,
                )) return error.InvalidArchive;
            const derived_inputs = derivation.sources.items[1..];
            for (derived_inputs, work.value.inputs.items) |left, right|
                if (!std.meta.eql(left, right)) return error.InvalidArchive;
        }
        fn prepareWorkspaceCommitPublication(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            identity: state.Digest,
            kind: @FieldType(contracts.workspace.Ref, "kind"),
            observation: state.Reference,
            related: ?state.Digest,
            publication: *WorkspaceCommitPublication,
        ) !void {
            if (kind == .work) {
                const bytes = try self.store().object(a, observation, null);
                defer a.free(bytes);
                publication.decoded_work = try contracts.decodeOwned(workspace.Work, a, bytes);
                const work = publication.decoded_work.?;
                var pending: ?contracts.Decoded(occurrence.Occurrence) = null;
                defer if (pending) |*value| value.deinit();
                if (work.value.current_occurrence) |id| pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    id,
                    task_id,
                );
                const observed: workspace.WorkObservation = .{
                    .work = work.value,
                    .occurrence = if (pending) |value| value.value else null,
                };
                publication.publications[publication.publication_count] = try workPublication(
                    a,
                    observed,
                );
                publication.publication_count += 1;
                const snapshot = try contracts.encodeOwned(workspace.WorkObservation, a, observed);
                defer a.free(snapshot);
                publication.frozen = try self.store().putObject(snapshot);
            }
            if (kind == .residual) {
                var saved_residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    identity,
                    task_id,
                );
                defer saved_residual.deinit();
                publication.residuals[0] = try self.residualPublication(a, saved_residual.value);
                publication.residual_count = 1;
            }
            if (related) |id| {
                const observed = try self.freezeWorkspaceWork(
                    a,
                    task_id,
                    try wp.reference(a, .work, id),
                    true,
                );
                const snapshot = try contracts.encodeOwned(workspace.WorkObservation, a, observed);
                defer a.free(snapshot);
                _ = try self.store().putObject(snapshot);
                publication.publications[publication.publication_count] = try workPublication(
                    a,
                    observed,
                );
                publication.publication_count += 1;
            }
        }
        const WorkspaceCommitPublication = workspaceCommitPublicationType();
        fn workspaceCommitPublicationType() type {
            return struct {
                publications: [2]state.WorkPublication = undefined,
                publication_count: usize = 0,
                residuals: [1]state.ResidualPublication = undefined,
                residual_count: usize = 0,
                frozen: state.Reference,
                decoded_work: ?contracts.Decoded(workspace.Work) = null,
            };
        }
        fn scheduleWorkspaceCommit(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial_revision: u64,
            identity: state.Digest,
            kind: @FieldType(contracts.workspace.Ref, "kind"),
            decoded_work: ?contracts.Decoded(workspace.Work),
        ) !void {
            var scheduled: [1]workspace.Subject = undefined;
            var scheduled_count: usize = 0;
            var stopped: ?workspace.Subject = null;
            if (decoded_work) |work| {
                const subject: workspace.Subject = .{ .task = parent.id, .work = work.value.id };
                if (try self.workspaceRunnable(a, parent, work.value)) {
                    scheduled[scheduled_count] = subject;
                    scheduled_count += 1;
                } else stopped = subject;
            } else if (kind == .residual) {
                var residual = try self.record(
                    state.ControllerResidual,
                    a,
                    "controller_residual",
                    identity,
                    parent.id,
                );
                defer residual.deinit();
                const subject: workspace.Subject = .{ .task = parent.id, .residual = identity };
                if (residual.value.schedule == .queued) {
                    scheduled[scheduled_count] = subject;
                    scheduled_count += 1;
                } else stopped = subject;
            }
            const disposed = if (try self.hasLocalCustody(
                a,
                parent.id,
                null,
            ) or try self.hasFrozenCustody(a, parent.id, null))
                parent.terminal() and try self.taskCleanupComplete(a, parent)
            else
                try self.workspaceSettled(a, parent.id, true, false, false);
            try self.persistScheduled(
                a,
                parent,
                initial_revision,
                "workspace.publish",
                .acquire,
                scheduled[0..scheduled_count],
            );
            if (stopped) |subject| self.subjectRemove(subject);
            if (disposed) self.unclaim(parent.id);
        }
        fn validateDelegatePort(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            selection: anytype,
            port: workspace.Port,
        ) !void {
            const selected_port = switch (selection.interpretation) {
                .model => |v| v.port,
                .snapshot => |v| v.port,
                .none => return error.InvalidDelegation,
            };
            const generation = switch (selection.interpretation) {
                .model => |v| v.generation,
                .snapshot => |v| v.generation,
                .none => unreachable,
            };
            if (!std.meta.eql(try wp.identity(selected_port, .port), port.id) or
                generation != port.generation or
                port.interface.class == .observation)
                return error.StaleOccurrence;
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                port.occurrence,
                task_id,
            );
            defer pending.deinit();
            if (pending.value.state != .ready) return error.UnsettledOccurrence;
        }
        fn publishWorkspaceDelegation(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            authorized: workspace.Authorized,
            parent: state.Task,
            original: occurrence.Occurrence,
            target: workspace.Work,
            port: workspace.Port,
            port_ref: state.Reference,
            request: state.Digest,
        ) !Admission {
            const selection = authorized.command.work.delegate;
            const parent_occurrence = parent.current_occurrence.?;
            const target_id = target.id;
            const kind: instrument.Kind =
                if (selection.interpretation ==
                .model) .model else .snapshot;
            if (kind == .model and
                (authorized.model == null or
                    !self.profile.authority.inference))
                return error.Denied;
            if (kind == .snapshot) try workspaceSnapshotAccess(
                parent,
                authorized.snapshot orelse return error.Denied,
            );
            var inputs: std.ArrayList(state.Reference) = .empty;
            defer inputs.deinit(a);
            if (selection.interpretation ==
                .model) for (selection.interpretation.model.inputs.items) |ref|
            {
                const value = try self.workspaceValueReference(a, task_id, ref);
                try inputs.append(a, value.artifact);
            };
            var built = try instrument.build(a, kind);
            defer built.deinit();
            try self.store().begin();
            defer self.store().rollback();
            const program = try self.publishDelegationProgram(a, task_id, parent, kind, built);
            var id: state.Digest = undefined;
            var instrument_id: state.Digest = undefined;
            try self.io.randomSecure(&id);
            try self.io.randomSecure(&instrument_id);
            const record_value: workspace.Delegation = .{
                .id = id,
                .task = task_id,
                .parent_occurrence = parent_occurrence,
                .parent_request = original.request_object,
                .work = target_id,
                .instrument = instrument_id,
                .program = port.program,
                .port = port_ref,
                .control_revision = try std.math.add(u64, target.control_revision, 1),
                .selection = selection.interpretation,
                .model = authorized.model,
                .snapshot = if (kind == .snapshot) authorized.snapshot else null,
                .inputs = .{ .items = inputs.items },
            };
            return self.startDelegatedInstrument(
                a,
                operation_id,
                task_id,
                program,
                record_value,
                request,
                selection,
            );
        }
        fn publishWorkspaceCommitEvent(
            self: *Self,
            a: std.mem.Allocator,
            initial: state.Task,
            parent: *state.Task,
            operation_id: ?[]const u8,
            event_data: []const u8,
            command: ?workspace.PublicationCommand,
            publication: *const WorkspaceCommitPublication,
        ) !void {
            const command_ref: ?state.Reference = if (command) |value| blk: {
                const bytes = try contracts.encodeOwned(workspace.PublicationCommand, a, value);
                defer a.free(bytes);
                break :blk try self.store().putObject(bytes);
            } else null;
            // Internal program publication is observed through the subsequent
            // work/delegation or captured build reply. Only work progress has
            // the retained publication facts needed for a journal projection.
            if (operation_id != null or publication.publication_count != 0 or
                publication.residual_count != 0)
                try self.subjectPublicationEvent(
                    parent,
                    if (operation_id != null) .workspace else .workspace_progress,
                    event_data,
                    publication.publications[0..publication.publication_count],
                    publication.residuals[0..publication.residual_count],
                    command_ref,
                    if (command != null and
                        publicationReadsController(command.?)) .from(initial) else null,
                    null,
                );
        }
        fn publishDelegationProgram(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            parent: state.Task,
            kind: instrument.Kind,
            built: anytype,
        ) !state.Reference {
            const program = try self.workspaceStoreProgram(
                a,
                task_id,
                instrument.identity,
                if (kind == .model) .instrument_model else .instrument_snapshot,
                null,
                &.{},
                .{ .image = .{
                    .bytes = built.image,
                }, .interface = built.interface, .ports = .{ .items = &.{} } },
            );
            // This publication grants reusable immutable code, never execution.
            _ = try self.workspaceCommit(
                a,
                parent,
                null,
                @splat(0),
                program.digest,
                .program,
                program,
                null,
            );
            try self.checked_workspace_programs.put(
                self.allocator,
                program.digest,
                self.store().integrity_epoch,
            );
            return program;
        }
        fn startDelegatedInstrument(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            program: state.Reference,
            record_value: workspace.Delegation,
            request: state.Digest,
            selection: anytype,
        ) !Admission {
            const record_bytes = try contracts.encodeOwned(workspace.Delegation, a, record_value);
            defer a.free(record_bytes);
            const input = try contracts.encodeOwned(instrument.Input, a, .{ .delegation = .{
                .digest = storage.digest(record_bytes),
                .bytes = record_bytes.len,
            } });
            defer a.free(input);
            return self.workspaceStartAdmitted(
                a,
                operation_id,
                task_id,
                program.digest,
                input,
                .{ .stop = .terminal, .continuation = .owner_scheduled },
                null,
                .{
                    .record = record_value,
                    .request = request,
                    .policy = selection.policy,
                    .command = selection,
                },
                null,
                .{ .none = .{} },
                null,
                null,
            );
        }
        fn validateArchiveControllerRecord(
            self: *Self,
            parent: state.Task,
            row: state.ArchiveRecord,
            records: []const state.ArchiveRecord,
            checked: *SnapshotValidation,
        ) !void {
            switch (row.kind) {
                .controller_succession => try self.validateControllerSuccession(
                    self.allocator,
                    parent,
                    row.id,
                    records,
                    checked,
                ),
                .controller_residual => try self.validateControllerResidual(
                    self.allocator,
                    parent,
                    row.id,
                    records,
                ),

                .controller_interaction => try self.validateControllerInteraction(
                    self.allocator,
                    parent,
                    row.id,
                    records,
                ),

                else => unreachable,
            }
        }
        fn workspaceObserverSource(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            selection: wc.Observe,
        ) !workspace.Observer {
            const key = storage.digest(operation_id);
            const view_id = try std.fmt.allocPrint(a, "observe-view-{s}", .{
                std.fmt.bytesToHex(key, .lower),
            });
            defer a.free(view_id);
            const view = try self.workspaceContextMutation(a, view_id, task_id, .{
                .materialize = .{
                    .input = .{ .guest_view = selection.source },
                    .sources = .{ .items = &.{} },
                },
            }, null, null);
            const view_ref = try wp.reference(a, .value, view.receipt.workspace.?);
            const disclosed = try self.workspaceValueReference(a, task_id, view_ref);
            const custody = try workspaceContentCustody(a, task_id, disclosed.artifact.digest);
            var saved = try self.record(workspace.Value, a, "workspace_value", custody, task_id);
            defer saved.deinit();
            const source = saved.value.derivation.inspection orelse
                return error.InvalidObserverInput;
            var current_source = try self.workspaceWork(a, task_id, source.observation.work.id);
            defer current_source.deinit();
            try inspectionSelection(current_source.value, selection.source);
            const source_revision = try self.observerSourceRevision(
                a,
                source.observation.work,
                selection.source.level,
            );
            if (source_revision != try self.observerSourceRevision(
                a,
                current_source.value,
                selection.source.level,
            )) return error.StaleRevision;
            const accumulator = try self.workspaceValueReference(a, task_id, selection.accumulator);
            return .{
                .selection = selection,
                .source = disclosed.artifact,
                .source_work = source.observation.work.id,
                .source_revision = source_revision,
                .accumulator = accumulator.artifact,
            };
        }
        pub fn workspaceObserve(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            selection: wc.Observe,
        ) !Admission {
            const request = try operation(workspace.ObserveRequest, a, .{
                .task = task_id,
                .selection = selection,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            try self.requireCustody(
                a,
                task_id,
                try wp.identity(selection.source.expected.work, .work),
            );
            try @import("workspace_observers.zig").validatePolicy(selection.policy);
            var observer = try self.workspaceObserverSource(a, operation_id, task_id, selection);
            try self.bindObserverPrevious(a, task_id, &observer);
            const input = try self.observerInput(a, task_id, observer);
            defer a.free(input);
            return self.workspaceStartAdmitted(
                a,
                operation_id,
                task_id,
                try wp.identity(selection.program, .program),
                input,
                .{ .stop = .terminal, .continuation = .owner_scheduled },
                null,
                null,
                null,
                .{ .none = .{} },
                null,
                observer,
            );
        }
        fn bindObserverPrevious(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            observer: *workspace.Observer,
        ) !void {
            const ref = observer.selection.previous orelse return;
            var prior = try self.workspaceWork(a, task_id, try wp.identity(ref, .work));
            defer prior.deinit();
            const before = prior.value.observer orelse return error.InvalidObserverInput;
            const program = try wp.identity(observer.selection.program, .program);
            if (prior.value.outcome_kind != .completed or prior.value.cancellation != null or
                !std.meta.eql(prior.value.program, program) or
                !std.meta.eql(before.source_work, observer.source_work))
                return error.InvalidObserverInput;
            try observerScope(a, before.selection.source, observer.selection.source);
            const consumed = before.consumed_revision orelse return error.InvalidObserverInput;
            const next = observer.source_revision;
            if (next <= consumed) return error.DuplicateObservation;
            if (observer.selection.policy.delivery == .lossless and next != consumed + 1)
                return error.ObservationGap;
            const snapshot = try contracts.encodeOwned(workspace.Work, a, prior.value);
            defer a.free(snapshot);
            observer.previous = .{ .digest = storage.digest(snapshot), .bytes = snapshot.len };
            observer.accumulator = prior.value.result_value orelse
                return error.InvalidObserverInput;
            if (next > consumed + 1) {
                observer.gap_first = consumed + 1;
                observer.gap_last = next - 1;
            }
        }
        fn observerInput(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            observer: workspace.Observer,
        ) ![]u8 {
            const helpers = @import("workspace_observers.zig");
            const envelope = try self.observerEnvelope(a, task_id, observer);
            defer a.free(envelope);
            const program_id = try wp.identity(observer.selection.program, .program);
            var program = try self.workspaceProgram(a, task_id, program_id);
            defer program.deinit();
            const view_ref = try wp.reference(a, .value, observer.source.digest);
            const disclosed = try self.workspaceValueReference(a, task_id, view_ref);
            const view = .{
                .schema = try self.store().object(a, disclosed.schema, null),
                .value = try self.store().object(a, disclosed.value, null),
            };
            defer a.free(view.schema);
            defer a.free(view.value);
            const accumulator_ref = try wp.reference(a, .value, observer.accumulator.digest);
            const accumulator = try self.workspaceValueReference(a, task_id, accumulator_ref);
            const schema = try self.store().object(a, accumulator.schema, null);
            defer a.free(schema);
            const bytes = try self.store().object(a, accumulator.value, null);
            defer a.free(bytes);
            const input_schema = try self.store().object(
                a,
                program.value.description.input_schema,
                null,
            );
            defer a.free(input_schema);
            const output_schema = try self.store().object(
                a,
                program.value.description.result_schema,
                null,
            );
            defer a.free(output_schema);
            if (observer.previous == null) return helpers.input(
                a,
                input_schema,
                output_schema,
                view.schema,
                view.value,
                envelope,
                schema,
                bytes,
            );
            const acc_schema = try helpers.fieldSchema(a, schema, 0);
            defer a.free(acc_schema);
            var decoded = try @import("dynamic_values.zig").decode(a, schema, bytes);
            defer decoded.deinit();
            const acc_bytes = try @import("dynamic_values.zig").encode(
                a,
                acc_schema,
                decoded.value.array.items[0],
            );
            defer a.free(acc_bytes);
            return helpers.input(
                a,
                input_schema,
                output_schema,
                view.schema,
                view.value,
                envelope,
                acc_schema,
                acc_bytes,
            );
        }
        fn observerEnvelope(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            observer: workspace.Observer,
        ) ![]u8 {
            const id = try workspaceContentCustody(a, task_id, observer.source.digest);
            var value = try self.record(workspace.Value, a, "workspace_value", id, task_id);
            defer value.deinit();
            const observed = value.value.derivation.inspection.?.observation;
            var prior_cursor: ?u64 = null;
            var granularity: @FieldType(wc.ObserverPolicy, "granularity") = .publication;
            if (observer.previous) |ref| {
                const bytes = try self.store().object(a, ref, null);
                defer a.free(bytes);
                var before = try contracts.decodeOwned(workspace.Work, a, bytes);
                defer before.deinit();
                const previous = before.value.observer orelse return error.InvalidObserverInput;
                prior_cursor = previous.consumed_revision orelse return error.InvalidObserverInput;
                if (previous.selection.policy.granularity == .one_guest_step and
                    observer.selection.source.level == .guest_cut and
                    observed.work.guest_work <= 1 and
                    observer.source_revision -| prior_cursor.? == 1) granularity = .one_guest_step;
            }
            return contracts.encodeOwned(workspace.ObserverEnvelope, a, .{
                .selection = observer.selection.source,
                .publication = observed.work.event_watermark,
                .cursor = observer.source_revision,
                .prior_cursor = prior_cursor,
                .guest_work_delta = if (observer.selection.source.level == .guest_cut)
                    observed.work.guest_work
                else
                    null,
                .gap_first = observer.gap_first,
                .gap_last = observer.gap_last,
                .granularity = granularity,
                .disclosed_value = observer.source,
                .control = workspace.ControlObservation.from(observed),
            });
        }
        fn validateObserverPrevious(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            observer: workspace.Observer,
            successors: *ObserverSuccessors,
        ) !void {
            if (observer.previous) |previous| {
                const bytes = try self.store().object(a, previous, null);
                defer a.free(bytes);
                var prior = try contracts.decodeOwned(workspace.Work, a, bytes);
                defer prior.deinit();
                const previous_id = try wp.identity(observer.selection.previous.?, .work);
                if (!std.meta.eql(
                    try successors.next(self, previous_id),
                    @as(?state.Digest, work.id),
                ))
                    return error.InvalidArchive;
                if (!std.meta.eql(prior.value.task, work.task) or
                    !std.meta.eql(prior.value.id, previous_id) or
                    !std.meta.eql(prior.value.result_value, observer.accumulator) or
                    prior.value.outcome_kind != .completed or prior.value.cancellation != null)
                    return error.InvalidArchive;
                try self.validateWorkspacePublication(a, work.task, .{
                    .work = prior.value,
                    .occurrence = null,
                });
                try successors.histories.validateCursor(self, a, prior.value);
                const before = prior.value.observer orelse return error.InvalidArchive;
                const consumed = before.consumed_revision orelse return error.InvalidArchive;
                if (!std.meta.eql(prior.value.program, work.program) or
                    !std.meta.eql(before.source_work, observer.source_work) or
                    observer.source_revision <= consumed) return error.InvalidArchive;
                try observerScope(a, before.selection.source, observer.selection.source);
                const skipped = observer.source_revision - consumed > 1;
                if (observer.selection.policy.delivery == .lossless and skipped)
                    return error.InvalidArchive;
                if (observer.gap_first != @as(?u64, if (skipped) consumed + 1 else null) or
                    observer.gap_last != @as(?u64, if (skipped)
                        observer.source_revision - 1
                    else
                        null)) return error.InvalidArchive;
            } else {
                const initial = try self.workspaceValueReference(
                    a,
                    work.task,
                    observer.selection.accumulator,
                );
                if (!std.meta.eql(initial.artifact, observer.accumulator) or
                    observer.gap_first != null or observer.gap_last != null)
                    return error.InvalidArchive;
            }
        }
        fn validateObserver(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            successors: *ObserverSuccessors,
        ) !void {
            try successors.histories.validateCursor(self, a, work);
            const observer = work.observer orelse return;
            if (observer.successor != null and
                !std.meta.eql(
                    observer.successor,
                    try successors.next(self, work.id),
                )) return error.InvalidArchive;
            @import("workspace_observers.zig").validatePolicy(observer.selection.policy) catch
                return error.InvalidArchive;
            try self.validateObserverIncomplete(a, work, &successors.histories);
            if ((observer.previous == null) != (observer.selection.previous == null))
                return error.InvalidArchive;
            const custody = try workspaceContentCustody(a, work.task, observer.source.digest);
            var saved = try self.record(workspace.Value, a, "workspace_value", custody, work.task);
            defer saved.deinit();
            const origin = saved.value.derivation.inspection orelse return error.InvalidArchive;
            if (!std.meta.eql(origin.observation.work.task, work.task)) return error.InvalidArchive;
            try successors.histories.validateCursor(self, a, origin.observation.work);
            try inspectionSelection(origin.observation.work, observer.selection.source);
            var selected = observer.selection.source;
            selected.level = origin.level;
            selected.nodes = origin.nodes;
            selected.disclosure = origin.disclosure;
            try observerScope(a, selected, observer.selection.source);
            const source_revision = try self.observerSourceRevision(
                a,
                origin.observation.work,
                observer.selection.source.level,
            );
            if (!std.meta.eql(origin.observation.work.id, observer.source_work) or
                source_revision != observer.source_revision)
                return error.InvalidArchive;
            if (!std.meta.eql(work.program, try wp.identity(observer.selection.program, .program)))
                return error.InvalidArchive;
            if (observer.consumed_revision != @as(?u64, if (work.outcome_kind == .completed)
                observer.source_revision
            else
                null))
                return error.InvalidArchive;
            const expected = try self.observerInput(a, work.task, observer);
            defer a.free(expected);
            if (!std.meta.eql(storage.digest(expected), work.input.digest) or
                expected.len != work.input.bytes) return error.InvalidArchive;
            try self.validateObserverPrevious(a, work, observer, successors);
        }
        fn observerScope(
            a: std.mem.Allocator,
            before: wc.GuestViewSelection,
            after: wc.GuestViewSelection,
        ) !void {
            var expected = before;
            expected.expected = after.expected;
            expected.realization_revision = after.realization_revision;
            const old = try contracts.encodeOwned(wc.GuestViewSelection, a, expected);
            defer a.free(old);
            const new = try contracts.encodeOwned(wc.GuestViewSelection, a, after);
            defer a.free(new);
            if (!same(old, new)) return error.InvalidObserverInput;
        }
        pub fn workspaceStart(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            program_id: state.Digest,
            input: []const u8,
            policy: workspace.RunPolicy,
        ) !Admission {
            return self.workspaceStartValue(
                a,
                operation_id,
                task_id,
                program_id,
                input,
                policy,
                null,
            );
        }
        fn workspaceStartValue(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            program_id: state.Digest,
            input: []const u8,
            policy: workspace.RunPolicy,
            origin: ?state.Reference,
        ) !Admission {
            return self.workspaceStartAdmitted(
                a,
                operation_id,
                task_id,
                program_id,
                input,
                policy,
                origin,
                null,
                null,
                .{ .none = .{} },
                null,
                null,
            );
        }
        const WorkspaceStartAdmission = workspaceStartAdmissionType();
        fn workspaceStartAdmissionType() type {
            return struct {
                operation_id: []const u8,
                task_id: state.TaskId,
                program_id: state.Digest,
                input: []const u8,
                policy: workspace.RunPolicy,
                origin: ?state.Reference,
                delegated: ?StartDelegation,
                runtime: ?state.Reference,
                trial: wc.Trial,
                preparation: ?state.ControllerSuccession,
                observer: ?workspace.Observer,
            };
        }
        fn workspaceStartAdmitted(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            program_id: state.Digest,
            input: []const u8,
            policy: workspace.RunPolicy,
            origin: ?state.Reference,
            delegated: ?StartDelegation,
            runtime: ?state.Reference,
            trial: wc.Trial,
            preparation: ?state.ControllerSuccession,
            observer: ?workspace.Observer,
        ) !Admission {
            return self.workspaceStartPrepared(a, .{
                .operation_id = operation_id,
                .task_id = task_id,
                .program_id = program_id,
                .input = input,
                .policy = policy,
                .origin = origin,
                .delegated = delegated,
                .runtime = runtime,
                .trial = trial,
                .preparation = preparation,
                .observer = observer,
            });
        }
        fn validateWorkspaceStartInput(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            artifact: workspace.Program,
        ) !void {
            const kind = artifact.description.source_kind;
            if ((artifact.description.controller != null) != (start.trial != .none) or
                (start.trial != .none and
                    start.delegated != null))
                return error.ControllerTrialRequired;
            if ((kind == .instrument_model or
                kind == .instrument_snapshot) != (start.delegated != null))
                return error.InvalidDelegation;
            const schema = try self.store().object(
                a,
                artifact.description.input_schema,
                null,
            );
            defer a.free(schema);
            var descriptor = try data.schema.decode(a, schema);
            defer descriptor.deinit();
            try data.schema.validateValue(a, descriptor.descriptor, start.input);
            if (start.trial != .none and (start.input.len < start.task_id.len or !same(
                start.input[0..start.task_id.len],
                &start.task_id,
            ))) return error.InvalidControllerTrial;
        }
        fn workspaceStartResponses(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            responses: []std.meta.Elem(
                @FieldType(@FieldType(workspace.Trial, "responses"), "items"),
            ),
        ) !void {
            const selected_responses = if (start.trial == .synthetic)
                start.trial.synthetic.responses.items
            else
                &.{};
            for (selected_responses, responses, 0..) |item, *out, i| {
                const payload = try self.workspaceValueReference(a, start.task_id, item.payload);
                const response = try self.workspaceValueReference(a, start.task_id, item.response);
                for (responses[0..i]) |prior| {
                    if (!same(item.identity.bytes, prior.identity.bytes)) continue;
                    var prior_payload = try contracts.decodeOwned(
                        workspace.ValueArtifact,
                        a,
                        try self.store().object(a, prior.payload, null),
                    );
                    defer prior_payload.deinit();
                    if (std.meta.eql(
                        payload.schema,
                        prior_payload.value.schema,
                    ) and std.meta.eql(
                        payload.value,
                        prior_payload.value.value,
                    )) return error.AmbiguousTrialResponse;
                }
                out.* = .{
                    .identity = item.identity,
                    .payload = payload.artifact,
                    .response = response.artifact,
                };
            }
        }
        fn workspaceStartDriver(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            id: state.Digest,
            image: []const u8,
        ) !*evaluator.Driver {
            var selected: ?SelectedRuntime = if (start.runtime) |ref| try self.workspaceRuntime(
                a,
                start.task_id,
                ref.digest,
                start.program_id,
            ) else null;
            defer if (selected) |*value| value.deinit();
            if (selected) |value| {
                if (!std.meta.eql(
                    start.runtime.?,
                    value.record.value.artifact,
                )) return error.InvalidRuntime;
                try self.requireSemanticPolicy(
                    kosmos.RuntimeCompiler.approvedRootIdentity(&value.admitted),
                    kosmos.RuntimeCompiler.checker_identity,
                );
            }
            var packaged = try self.program.retainRuntime();
            defer packaged.deinit();
            const driver = try evaluator.Driver.openSelected(
                self.allocator,
                image,
                .{ .initial_args = start.input },
                if (selected) |*value| &value.admitted else &packaged,
            );
            self.active = .{
                .task = start.task_id,
                .subject = .{ .work = id },
                .execution_revision = 0,
                .driver = driver,
            };
            return driver;
        }
        fn workspaceStartDelegation(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            parent: state.Task,
        ) !?state.Reference {
            var delegation_ref: ?state.Reference = null;
            if (start.delegated) |bound| {
                const record_value = bound.record;
                var target = try self.workspaceWork(a, start.task_id, record_value.work);
                defer target.deinit();
                if (target.value.control_revision + 1 != record_value.control_revision or
                    !std.meta.eql(
                        target.value.current_port,
                        record_value.port,
                    ) or target.value.cancellation != null) return error.StaleRevision;
                target.value.control_revision = record_value.control_revision;
                target.value.policy = bound.policy;
                target.value.event_watermark = parent.event_high + 1;
                target.value.schedule = .parked;
                try self.writeWorkspaceWork(&target.value, .replace);
                try self.store().createRecord(
                    workspace.Delegation,
                    "workspace_delegation",
                    record_value.id,
                    start.task_id,
                    record_value,
                );
                delegation_ref = try self.snapshotRecord(
                    workspace.Delegation,
                    a,
                    "workspace_delegation",
                    record_value.id,
                    start.task_id,
                );
            }
            return delegation_ref;
        }
        fn workspaceStartTrial(
            self: *Self,
            start: WorkspaceStartAdmission,
            parent: state.Task,
            id: state.Digest,
            trial_view: anytype,
            responses: anytype,
        ) !?state.Digest {
            return if (trial_view) |view| blk: {
                try self.store().createRecord(
                    workspace.Trial,
                    "workspace_trial",
                    id,
                    start.task_id,
                    .{
                        .id = id,
                        .task = start.task_id,
                        .selection = start.trial,
                        .view = try self.store().putObject(view.bytes),
                        .view_works = .{ .items = view.works },
                        .policy = parent.profile,
                        .responses = .{ .items = responses },
                    },
                );
                break :blk id;
            } else null;
        }
        fn workspaceStartTrialInputs(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            trial_ref: ?state.Digest,
            saved: *workspace.Work,
        ) !void {
            if (trial_ref) |trial_id| {
                var binding = try self.record(
                    workspace.Trial,
                    a,
                    "workspace_trial",
                    trial_id,
                    task_id,
                );
                defer binding.deinit();
                const inputs = try a.alloc(state.Reference, binding.value.responses.items.len * 2);
                for (binding.value.responses.items, 0..) |response, i| {
                    inputs[i * 2] = response.payload;
                    inputs[i * 2 + 1] = response.response;
                }
                saved.inputs.items = inputs;
            }
        }
        fn workspaceStartRelated(
            self: *Self,
            start: WorkspaceStartAdmission,
            parent: state.Task,
            predecessor: ?*workspace.Work,
            id: state.Digest,
        ) !void {
            if (predecessor) |prior| {
                prior.*.observer.?.successor = id;
                prior.*.control_revision = try std.math.add(
                    u64,
                    prior.*.control_revision,
                    1,
                );
                prior.*.event_watermark = try std.math.add(u64, parent.event_high, 1);
                try self.writeWorkspaceWork(&prior.*, .replace);
            }
            if (start.preparation) |initial| {
                var prepared = initial;
                if (!std.meta.eql(parent.controller_succession, prepared.id) or
                    prepared.conversion_work != null or
                    prepared.phase != .preparing)
                    return error.StaleController;
                prepared.conversion_work = id;
                try self.store().putRecord(
                    state.ControllerSuccession,
                    "controller_succession",
                    prepared.id,
                    start.task_id,
                    prepared,
                );
            }
        }
        fn workspaceCommitStartedWork(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            initial_parent: state.Task,
            predecessor: ?*workspace.Work,
            heads: ?[]state.Digest,
            saved: workspace.Work,
            request: state.Digest,
        ) !Admission {
            var parent = initial_parent;
            const id = saved.id;
            if (heads) |items| {
                parent.observers_present = true;
                parent.observer_heads.items = items;
            }
            const admitted = try self.workspaceCommitRelated(
                a,
                parent,
                start.operation_id,
                request,
                id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", id, start.task_id),
                if (start.delegated) |bound|
                    bound.record.work
                else if (predecessor) |prior|
                    prior.*.id
                else
                    null,
                if (start.delegated) |bound| .{ .delegate = bound.command } else .{ .start = .{
                    .policy = start.policy,
                    .origin = start.origin != null,
                    .runtime = start.runtime,
                    .trial = start.trial,
                    .observer = start.observer,
                } },
            );
            if (predecessor) |prior| self.subjectRemove(.{
                .task = start.task_id,
                .work = prior.*.id,
            });
            self.active.?.execution_revision = saved.execution_revision;
            return admitted;
        }
        fn workspaceInitialWork(
            self: *Self,
            start: WorkspaceStartAdmission,
            parent: state.Task,
            id: state.Digest,
            trial_ref: ?state.Digest,
            delegation_ref: ?state.Reference,
            native_ns: u64,
        ) !workspace.Work {
            return .{
                .observer = start.observer,
                .id = id,
                .task = start.task_id,
                .trial = trial_ref,
                .program = start.program_id,
                .runtime = start.runtime,
                .delegation = delegation_ref,
                .origin_work = if (start.delegated) |bound| bound.record.work else null,
                .input = try self.store().putObject(start.input),
                .checkpoint = undefined,
                .outcome = undefined,
                .outcome_kind = .progressed,
                .execution_revision = 1,
                .native_publication_nanoseconds = native_ns,
                .control_revision = 1,
                .schedule = .parked,
                .policy = start.policy,
                .event_watermark = parent.event_high + 1,
            };
        }
        fn workspaceCreateStartedWork(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            initial_parent: state.Task,
            artifact: workspace.Program,
            predecessor: ?*workspace.Work,
            heads: ?[]state.Digest,
            id: state.Digest,
            trial_view: anytype,
            responses: anytype,
            publication: evaluator.Driver.Publication,
            native_ns: u64,
            request: state.Digest,
        ) !Admission {
            const parent = initial_parent;
            try self.store().begin();
            defer self.store().rollback();
            const delegation_ref = try self.workspaceStartDelegation(a, start, parent);
            const trial_ref = try self.workspaceStartTrial(
                start,
                parent,
                id,
                trial_view,
                responses,
            );
            var saved = try self.workspaceInitialWork(
                start,
                parent,
                id,
                trial_ref,
                delegation_ref,
                native_ns,
            );
            try self.workspaceStartTrialInputs(a, start.task_id, trial_ref, &saved);
            defer if (trial_ref != null) a.free(saved.inputs.items);
            const observer_inputs = if (start.observer) |bound|
                &[_]state.Reference{ bound.source, bound.accumulator }
            else
                &.{};
            if (start.observer != null) saved.inputs = .{ .items = observer_inputs };
            saved.input_value = start.origin orelse try self.workspacePublishValue(
                a,
                start.task_id,
                artifact.description.input_schema,
                saved.input,
                .{
                    .kind = if (start.observer != null) .judgment else .hypothesis,
                    .sources = .{ .items = observer_inputs },
                },
            );
            try self.workspacePublication(a, &saved, publication);
            defer if (saved.runtime_trace) |trace| a.free(trace.dependencies.items);
            try self.writeWorkspaceWork(&saved, .create);
            try self.createCustody(a, start.task_id, id);
            try self.workspaceStartRelated(start, parent, predecessor, id);
            return self.workspaceCommitStartedWork(
                a,
                start,
                parent,
                predecessor,
                heads,
                saved,
                request,
            );
        }
        fn workspaceStartRequest(
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
        ) !state.Digest {
            const Request = workspace.StartRequest;
            return if (start.delegated) |bound| bound.request else if (start.observer) |bound|
                try operation(workspace.ObserveRequest, a, .{
                    .task = start.task_id,
                    .selection = bound.selection,
                })
            else
                try operation(Request, a, .{
                    .task = start.task_id,
                    .program = start.program_id,
                    .input = .{ .bytes = start.input },
                    .policy = start.policy,
                    .origin = start.origin,
                    .runtime = start.runtime,
                    .trial = start.trial,
                });
        }
        fn workspaceStartPredecessor(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            parent: state.Task,
        ) !?contracts.Decoded(workspace.Work) {
            var predecessor: ?contracts.Decoded(workspace.Work) = null;
            errdefer if (predecessor) |*prior| prior.deinit();
            if (start.observer) |bound| if (bound.selection.previous) |previous| {
                const previous_id = try wp.identity(previous, .work);
                try self.requireCustody(a, start.task_id, previous_id);
                predecessor = try self.workspaceWork(a, start.task_id, previous_id);
                const prior = predecessor.?.value;
                const prior_observer = prior.observer orelse return error.InvalidObserverInput;
                if (prior_observer.successor != null) return error.DuplicateObservation;
                if (!prior_observer.stopped and observerHeadIndex(parent, prior.id) == null)
                    return error.CorruptState;
            };
            return predecessor;
        }
        fn workspacePublishStartedDriver(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
            parent: state.Task,
            artifact: workspace.Program,
            predecessor: ?*workspace.Work,
            heads: ?[]state.Digest,
            id: state.Digest,
            trial_view: anytype,
            responses: anytype,
            driver: *evaluator.Driver,
            request: state.Digest,
        ) !Admission {
            const native_started = std.Io.Clock.awake.now(self.io);
            const publication = try driver.drive(a, .none, 256);
            const native_ns = std.math.cast(
                u64,
                @max(0, std.Io.Clock.awake.now(self.io).nanoseconds - native_started.nanoseconds),
            ) orelse std.math.maxInt(u64);
            defer a.free(publication.outcome);
            errdefer self.store().fence();
            return self.workspaceCreateStartedWork(
                a,
                start,
                parent,
                artifact,
                predecessor,
                heads,
                id,
                trial_view,
                responses,
                publication,
                native_ns,
                request,
            );
        }
        fn workspaceStartPrepared(
            self: *Self,
            a: std.mem.Allocator,
            start: WorkspaceStartAdmission,
        ) !Admission {
            var parent = try self.task(a, start.task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            const request = try workspaceStartRequest(a, start);
            if (try self.replay(a, start.operation_id, request)) |prior| {
                if (start.preparation != null) return error.OperationConflict;
                return prior;
            }
            try self.requireCustody(a, start.task_id, null);
            var predecessor = try self.workspaceStartPredecessor(a, start, parent.value);
            defer if (predecessor) |*prior| prior.deinit();
            if (self.workspaceParentStopped(parent.value)) return error.InvalidState;
            var artifact = try self.workspaceProgram(a, start.task_id, start.program_id);
            defer artifact.deinit();
            try self.validateWorkspaceStartInput(a, start, artifact.value);
            const responses = try a.alloc(
                std.meta.Elem(@FieldType(@FieldType(workspace.Trial, "responses"), "items")),
                if (start.trial == .synthetic) start.trial.synthetic.responses.items.len else 0,
            );
            defer a.free(responses);
            try self.workspaceStartResponses(a, start, responses);
            const image = try self.store().object(a, artifact.value.description.image, null);
            defer a.free(image);
            const trial_view = if (start.trial != .none) try self.controllerView(
                a,
                parent.value,
            ) else null;
            defer if (trial_view) |view| {
                a.free(view.bytes);
                freeControllerViewWorks(a, view.works);
            };
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            try self.retire(a);
            var id: state.Digest = undefined;
            if (start.delegated) |bound| id = bound.record.instrument else try self.io.randomSecure(
                &id,
            );
            const heads = if (start.observer != null)
                try observerHeadsAfter(
                    a,
                    parent.value,
                    if (predecessor) |prior| prior.value.id else null,
                    id,
                )
            else
                null;
            defer if (heads) |items| a.free(items);
            const driver = try self.workspaceStartDriver(a, start, id, image);
            errdefer if (!self.store().fenced) self.retire(a) catch self.store().fence();
            return self.workspacePublishStartedDriver(
                a,
                start,
                parent.value,
                artifact.value,
                if (predecessor) |*prior| &prior.value else null,
                heads,
                id,
                trial_view,
                responses,
                driver,
                request,
            );
        }
        fn workspaceTracePublication(
            self: *Self,
            a: std.mem.Allocator,
            value: workspace.Work,
            trace: kosmos.RuntimeInstrumentation.Output,
        ) !workspace.RuntimeTrace {
            const driver = self.active.?.driver;
            const capsule = try driver.publishCapsule(
                a,
                .outer_execution,
                runtimeProvenance(value),
            );
            defer capsule.deinit();
            const code = try driver.runtimeBytes(a);
            defer a.free(code);
            _ = try self.store().putObject(code);
            return .{ .output = trace, .capsule = try self.store().putObject(
                capsule.bytes(),
            ), .dependencies = .{ .items = try capsuleDependencies(a, capsule.bytes()) } };
        }
        fn workspacePublishRequestedPort(
            self: *Self,
            a: std.mem.Allocator,
            value: *workspace.Work,
            program: workspace.Program,
            request: data.invocation.Request,
            next: occurrence.Occurrence,
        ) !void {
            for (program.description.ports.items) |port| {
                if (!same(
                    port.identity.bytes,
                    request.binding.semantic_identity,
                )) continue;
                if (!std.meta.eql(
                    storage.digest(request.binding.resume_schema),
                    port.command.digest,
                ) or
                    !std.meta.eql(
                        storage.digest(request.binding.payload_schema),
                        port.payload.digest,
                    )) return error.CorruptState;
                var port_id: state.Digest = undefined;
                try self.io.randomSecure(&port_id);
                value.port_generation = try std.math.add(u64, value.port_generation, 1);
                const exposed: workspace.Port = .{
                    .id = port_id,
                    .task = value.task,
                    .work = value.id,
                    .program = program.artifact,
                    .occurrence = next.id,
                    .request = next.request_object,
                    .request_identity = next.request,
                    .generation = value.port_generation,
                    .interface = port,
                    .payload = try self.store().putObject(request.binding.payload),
                };
                try self.store().createRecord(
                    workspace.Port,
                    "workspace_port",
                    port_id,
                    value.task,
                    exposed,
                );
                value.current_port = try self.snapshotRecord(
                    workspace.Port,
                    a,
                    "workspace_port",
                    port_id,
                    value.task,
                );
                break;
            }
        }
        fn workspaceRequestedPublication(
            self: *Self,
            a: std.mem.Allocator,
            value: *workspace.Work,
            pending: anytype,
        ) !void {
            var request = try data.invocation.decode(
                data.invocation.Request,
                a,
                pending.request,
            );
            defer request.deinit();
            var id: state.Digest = undefined;
            try self.io.randomSecure(&id);
            const next: occurrence.Occurrence = .{
                .id = id,
                .task = value.task,
                .work = value.id,
                .request = request.value.request_identity,
                .request_object = try self.store().putObject(pending.request),
            };
            try self.store().createRecord(
                occurrence.Occurrence,
                "occurrence",
                id,
                value.task,
                next,
            );
            value.current_occurrence = id;
            if (value.delegation != null) {
                if (value.instrument_occurrence != null) return error.CorruptState;
                value.instrument_occurrence = id;
            }
            value.outcome_kind = .requested;
            var program = try self.workspaceProgram(a, value.task, value.program);
            defer program.deinit();
            try self.workspacePublishRequestedPort(a, value, program.value, request.value, next);
            try self.store().createRecord(
                workspace.ExecutionRoute,
                "execution_route",
                id,
                value.task,
                .{
                    .id = id,
                    .task = value.task,
                    .work = value.id,
                    .image = program.value.description.image,
                    .program_identity = request.value.binding.program_identity,
                    .port = value.current_port,
                    .delegation = value.delegation,
                },
            );
        }
        fn workspacePublication(
            self: *Self,
            a: std.mem.Allocator,
            value: *workspace.Work,
            publication: evaluator.Driver.Publication,
        ) !void {
            value.guest_work = publication.guest_work;
            if (value.blocker == .observation_blocked) value.blocker = null;
            value.runtime_capsule = null;
            value.runtime_trace = null;
            value.outer_operation = null;
            value.runtime_dependencies = .{ .items = &.{} };
            var outcome = try data.invocation.decode(
                data.invocation.Outcome,
                a,
                publication.outcome,
            );
            defer outcome.deinit();
            value.checkpoint = try self.store().putObject(publication.checkpoint);
            if (publication.trace) |trace| {
                value.runtime_trace = self.workspaceTracePublication(
                    a,
                    value.*,
                    trace,
                ) catch return error.InstrumentationPublicationBlocked;
            }
            errdefer if (value.runtime_trace) |trace| a.free(trace.dependencies.items);
            value.outcome = try self.store().putObject(publication.outcome);
            value.schedule = .parked;
            switch (outcome.value) {
                .progressed => value.outcome_kind = .progressed,
                .yielded => value.outcome_kind = .yielded,
                .completed => |bytes| {
                    value.outcome_kind = .completed;
                    if (value.observer) |*observer| observer.consumed_revision =
                        observer.source_revision;
                    value.result = try self.store().putObject(bytes);
                    var program = try self.workspaceProgram(a, value.task, value.program);
                    defer program.deinit();
                    if (value.delegation ==
                        null) value.result_value =
                        try self.workspaceResultValue(a, value.*, program.value);
                },
                .failed => {
                    value.outcome_kind = .failed;
                },
                .cancelled => {
                    value.outcome_kind = .cancelled;
                },
                .requested => |pending| {
                    try self.workspaceRequestedPublication(a, value, pending);
                },
                .needs_capacity => return error.Capacity,
            }
            // No unbound external request is dispatched. A run policy grants
            // continued computation, never the authority to invent an answer.
            value.schedule = publicationSchedule(
                workspace.ControlObservation.from(.{ .work = value.*, .occurrence = null }),
            );
            if (publication.segment) |segment|
                guest_segment_proofs.retain(
                    try guestSegmentKey(try guestSegmentFact(segment, value.*)),
                );
        }
        fn workspaceRestoreCapsule(
            self: *Self,
            a: std.mem.Allocator,
            value: workspace.Work,
            pending: anytype,
            image: []const u8,
            runtime: anytype,
        ) !*evaluator.Driver {
            try self.validatePublishedCapsuleTrace(
                a,
                value,
                pending.capsule,
                value.runtime,
                null,
                pending,
            );
            const bytes = try self.store().object(a, pending.capsule, null);
            defer a.free(bytes);
            const Owner = struct {
                work: workspace.Work,
                reference: state.Reference,
                fn claim(
                    context: *anyopaque,
                    ref: kosmos.RuntimeCapsule.Reference,
                    record_value: kosmos.RuntimeCapsule.Record,
                    _: kosmos.RuntimeCapsule.Reference,
                ) !void {
                    const owner: *@This() = @ptrCast(@alignCast(context));
                    if (!std.meta.eql(
                        ref.digest,
                        owner.reference.digest,
                    ) or ref.bytes != owner.reference.bytes or
                        !std.meta.eql(
                            record_value.provenance,
                            runtimeProvenance(owner.work),
                        )) return error.InvalidArchive;
                }
            };
            // The task's immutable publication and current exclusive native
            // namespace ownership authorize this one resident installation.
            var owner: Owner = .{ .work = value, .reference = pending.capsule };
            return evaluator.Driver.openCapsule(
                self.allocator,
                image,
                runtime,
                bytes,
                .{ .context = &owner, .claim = Owner.claim },
            );
        }
        fn workspaceResident(
            self: *Self,
            a: std.mem.Allocator,
            value: workspace.Work,
        ) !*evaluator.Driver {
            if (self.active) |active| {
                if (std.meta.eql(
                    active.task,
                    value.task,
                ) and active.subject == .work and std.meta.eql(
                    active.subject.work,
                    value.id,
                ) and
                    active.execution_revision == value.execution_revision and
                    active.realization_revision == value.realization_revision and
                    std.meta.eql(
                        active.outer_operation,
                        if (value.outer_operation) |pending| @as(
                            ?state.Reference,
                            pending.capsule,
                        ) else null,
                    )) return active.driver;
                try self.retire(a);
            }
            var artifact = try self.workspaceProgram(a, value.task, value.program);
            defer artifact.deinit();
            const image = try self.store().object(a, artifact.value.description.image, null);
            defer a.free(image);
            const checkpoint = try self.store().object(a, value.checkpoint, null);
            defer a.free(checkpoint);
            var selected: ?SelectedRuntime = if (value.runtime) |ref| try self.workspaceRuntime(
                a,
                value.task,
                ref.digest,
                value.program,
            ) else null;
            defer if (selected) |*item| item.deinit();
            if (selected) |item| if (!std.meta.eql(
                value.runtime.?,
                item.record.value.artifact,
            )) return error.InvalidRuntime;
            var packaged = try self.program.retainRuntime();
            defer packaged.deinit();
            const driver = if (value.outer_operation) |pending| restored: {
                break :restored try self.workspaceRestoreCapsule(
                    a,
                    value,
                    pending,
                    image,
                    if (selected) |*item| &item.admitted else &packaged,
                );
            } else try evaluator.Driver.openSelected(
                self.allocator,
                image,
                .{ .state = checkpoint },
                if (selected) |*item| &item.admitted else &packaged,
            );
            self.active = .{
                .task = value.task,
                .subject = .{ .work = value.id },
                .execution_revision = value.execution_revision,
                .realization_revision = value.realization_revision,
                .outer_operation = if (value.outer_operation) |pending| pending.capsule else null,
                .driver = driver,
            };
            return driver;
        }
        fn workspaceResultValue(
            self: *Self,
            a: std.mem.Allocator,
            value: workspace.Work,
            program: workspace.Program,
        ) !state.Reference {
            const derivation = try self.workspaceResultDerivation(a, value, program);
            defer a.free(derivation.sources.items);
            return self.workspacePublishValue(
                a,
                value.task,
                program.description.result_schema,
                value.result.?,
                derivation,
            );
        }
        fn workspaceResultDerivation(
            _: *Self,
            a: std.mem.Allocator,
            value: workspace.Work,
            program: workspace.Program,
        ) !workspace.Derivation {
            const source_value = value.input_value orelse return error.CorruptState;
            const antecedents = try a.alloc(state.Reference, value.inputs.items.len + 1);
            antecedents[0] = source_value;
            @memcpy(antecedents[1..], value.inputs.items);
            return .{
                .kind = if (value.trial != null) .trial else .computation,
                .sources = .{ .items = antecedents },
                .program = program.artifact,
                .work = value.id,
            };
        }
        fn workspaceInstrumentSnapshotAnswer(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            delegation: workspace.Delegation,
            port: workspace.Port,
            answer: []const u8,
        ) !state.Reference {
            const snapshot = delegation.snapshot orelse return error.CorruptState;
            const selected = delegation.selection.snapshot;
            const ref = try self.workspaceMaterializeSnapshot(a, parent, snapshot, .{
                .path = selected.path,
                .offset = selected.offset,
                .maximum = selected.maximum,
            });
            const acquired = try self.workspaceValueReference(
                a,
                parent.id,
                try wp.reference(a, .value, ref.digest),
            );
            if (!std.meta.eql(
                acquired.schema,
                port.interface.argument,
            ) or !std.meta.eql(acquired.value, state.Reference{
                .digest = storage.digest(answer),
                .bytes = answer.len,
            })) return error.CorruptState;
            return ref;
        }
        fn workspaceInstrumentModelAnswer(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            child: workspace.Work,
            delegation: workspace.Delegation,
            delegation_ref: state.Reference,
            port: workspace.Port,
            answer: []const u8,
        ) !state.Reference {
            var pending = try self.record(
                occurrence.Occurrence,
                a,
                "occurrence",
                child.instrument_occurrence orelse return error.CorruptState,
                parent.id,
            );
            defer pending.deinit();
            if (pending.value.state != .admitted or
                pending.value.state.admitted != .reply)
                return error.CorruptState;
            var capture_value = try self.record(
                state.Capture,
                a,
                "capture",
                pending.value.state.admitted.reply.attempt,
                parent.id,
            );
            defer capture_value.deinit();
            return try self.workspacePublishValue(
                a,
                parent.id,
                port.interface.argument,
                try self.store().putObject(answer),
                .{
                    .kind = .judgment,
                    .sources = delegation.inputs,
                    .work = child.id,
                    .delegation = delegation_ref,
                    .capture = capture_value.value.response orelse return error.CorruptState,
                },
            );
        }
        fn workspaceInstrumentAnswer(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            child: workspace.Work,
        ) !?state.Reference {
            var output = try contracts.decodeOwned(
                instrument.Output,
                a,
                try self.store().object(a, child.result orelse return error.CorruptState, null),
            );
            defer output.deinit();
            if (output.value != .answer) return null;
            const delegation_ref = child.delegation orelse return error.CorruptState;
            var admitted = try contracts.decodeOwned(
                workspace.Delegation,
                a,
                try self.store().object(a, delegation_ref, null),
            );
            defer admitted.deinit();
            const delegation = admitted.value;
            if (!std.meta.eql(delegation.instrument, child.id) or
                !std.meta.eql(delegation.task, parent.id))
                return error.CorruptState;
            var port = try contracts.decodeOwned(
                workspace.Port,
                a,
                try self.store().object(a, delegation.port, null),
            );
            defer port.deinit();
            const schema = try self.store().object(a, port.value.interface.argument, null);
            var descriptor = try data.schema.decode(a, schema);
            defer descriptor.deinit();
            try data.schema.validateValue(a, descriptor.descriptor, output.value.answer.bytes);
            if (delegation.selection == .snapshot)
                return try self.workspaceInstrumentSnapshotAnswer(
                    a,
                    parent,
                    delegation,
                    port.value,
                    output.value.answer.bytes,
                );
            if (delegation.selection != .model) return error.CorruptState;
            return try self.workspaceInstrumentModelAnswer(
                a,
                parent,
                child,
                delegation,
                delegation_ref,
                port.value,
                output.value.answer.bytes,
            );
        }
        fn workspaceApplyAnswer(self: *Self, a: std.mem.Allocator, child: workspace.Work) !void {
            var parent = try self.task(a, child.task);
            defer parent.deinit();
            if (!try self.delegationCurrent(a, parent.value, child)) return;
            var admitted = try contracts.decodeOwned(
                workspace.Delegation,
                a,
                try self.store().object(a, child.delegation.?, null),
            );
            defer admitted.deinit();
            var target = try self.workspaceWork(a, child.task, admitted.value.work);
            defer target.deinit();
            var port = try contracts.decodeOwned(
                workspace.Port,
                a,
                try self.store().object(a, admitted.value.port, null),
            );
            defer port.deinit();
            const operation_id = try std.fmt.allocPrint(a, "delegation-{s}", .{
                std.fmt.bytesToHex(admitted.value.id, .lower),
            });
            defer a.free(operation_id);
            _ = try self.workspaceInteract(a, operation_id, child.task, .{ .expected = .{
                .work = try wp.reference(a, .work, target.value.id),
                .execution_revision = target.value.execution_revision,
                .control_revision = target.value.control_revision,
            }, .port = try wp.reference(
                a,
                .port,
                port.value.id,
            ), .generation = port.value.generation, .command = .{ .resume_value = .{
                .reference = try wp.reference(a, .value, child.answer_value.?.digest),
            } } });
        }
        fn delegationCurrent(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            child: workspace.Work,
        ) !bool {
            if (parent.terminal() or parent.cancellation != null) return false;
            const ref = child.delegation orelse return false;
            var delegation = try contracts.decodeOwned(
                workspace.Delegation,
                a,
                try self.store().object(a, ref, null),
            );
            defer delegation.deinit();
            const admitted = delegation.value;
            if (!std.meta.eql(admitted.task, parent.id) or
                !std.meta.eql(admitted.instrument, child.id))
                return error.CorruptState;
            if (!try self.hasLocalCustody(a, parent.id, admitted.work)) return false;
            var target = try self.workspaceWork(a, parent.id, admitted.work);
            defer target.deinit();
            return target.value.cancellation == null and
                !target.value.terminal() and
                target.value.control_revision == admitted.control_revision and
                std.meta.eql(target.value.current_port, admitted.port);
        }
        fn controllerTrialResponse(
            self: *Self,
            a: std.mem.Allocator,
            trial: workspace.Trial,
            request: data.invocation.Request,
        ) ![]u8 {
            for (trial.responses.items) |item| {
                if (!same(item.identity.bytes, request.binding.semantic_identity)) continue;
                var payload = try contracts.decodeOwned(
                    workspace.ValueArtifact,
                    a,
                    try self.store().object(a, item.payload, null),
                );
                defer payload.deinit();
                if (!std.meta.eql(
                    payload.value.schema.digest,
                    storage.digest(request.binding.payload_schema),
                ) or !std.meta.eql(
                    payload.value.value.digest,
                    storage.digest(request.binding.payload),
                )) continue;
                var response = try contracts.decodeOwned(
                    workspace.ValueArtifact,
                    a,
                    try self.store().object(a, item.response, null),
                );
                defer response.deinit();
                if (!std.meta.eql(
                    response.value.schema.digest,
                    storage.digest(request.binding.resume_schema),
                )) return error.SchemaMismatch;
                return self.store().object(a, response.value.value, null);
            }
            return error.ObservationUnavailable;
        }
        fn controllerTrialReply(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            request: data.invocation.Request,
        ) ![]u8 {
            var trial = try self.record(
                workspace.Trial,
                a,
                "workspace_trial",
                work.trial orelse return error.InvalidControllerTrial,
                work.task,
            );
            defer trial.deinit();
            var program = try self.workspaceProgram(a, work.task, work.program);
            defer program.deinit();
            const descriptor = program.value.description.controller orelse
                return error.InvalidControllerTrial;
            const c = contracts.controller;
            if (same(request.binding.semantic_identity, c.boot_identity)) {
                const input = try self.store().object(a, work.input, null);
                defer a.free(input);
                if (!same(input, request.binding.payload)) return error.InvalidControllerTrial;
                return a.dupe(u8, &.{});
            }
            if (same(request.binding.semantic_identity, c.offer_identity)) {
                var parent = try self.task(a, work.task);
                defer parent.deinit();
                var binding = self.projectionBinding(parent.value);
                binding.execution = request.binding.program_identity;
                binding.trial = .{ .work = work.id, .view = trial.value.view };
                return self.controllerOffer(a, binding, request.binding.payload);
            }
            if (same(request.binding.semantic_identity, c.handoff_identity)) {
                const model = for (descriptor.imports.items) |item| {
                    if (item.import == .deliberate) break item;
                } else return error.InvalidControllerTrial;
                var schema = try data.schema.decode(a, model.payload.bytes);
                defer schema.deinit();
                var arena = std.heap.ArenaAllocator.init(a);
                defer arena.deinit();
                const facts = try data.admission.schemas(
                    arena.allocator(),
                    schema.descriptor.types,
                );
                var reader: data.wire.Reader = .{ .input = request.binding.payload };
                _ = try data.admission.readValue(
                    arena.allocator(),
                    schema.descriptor.types,
                    facts,
                    schema.descriptor.root,
                    &reader,
                );
                return std.mem.concat(a, u8, &.{ request.binding.payload[reader.position..], &.{
                    0,
                } });
            }
            return self.controllerTrialResponse(a, trial.value, request);
        }
        fn controllerTrialAllowsLive(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            request: data.invocation.Request,
        ) !bool {
            if (!same(
                request.binding.semantic_identity,
                contracts.controller.effect_prefix ++ "deliberate",
            )) return false;
            const entry = for (self.handlers.entries) |item| {
                if (item.declaration.controller_import == .deliberate) break item;
            } else return false;
            if (entry.declaration.kind != .leaf or !entry.declaration.inference) return false;
            var trial = try self.record(
                workspace.Trial,
                a,
                "workspace_trial",
                work.trial orelse return error.InvalidControllerTrial,
                work.task,
            );
            defer trial.deinit();
            return trial.value.selection == .synthetic and
                trial.value.selection.synthetic.live_inference;
        }
        fn settleControllerTrial(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work: workspace.Work,
            pending: occurrence.Occurrence,
        ) !Step {
            const request_bytes = try self.store().object(a, pending.request_object, null);
            defer a.free(request_bytes);
            var request = try data.invocation.decode(data.invocation.Request, a, request_bytes);
            defer request.deinit();
            const payload = self.controllerTrialReply(a, work, request.value) catch |err| {
                if (err == error.ObservationUnavailable) {
                    if (try self.controllerTrialAllowsLive(
                        a,
                        work,
                        request.value,
                    )) return self.dispatch(a, parent, pending);
                    return self.blockedOccurrence(a, parent, pending, .unavailable_environment);
                }
                return self.blockControllerRequest(a, parent, pending, err);
            };
            defer a.free(payload);
            var schema = try data.schema.decode(a, request.value.binding.resume_schema);
            defer schema.deinit();
            data.schema.validateValue(
                a,
                schema.descriptor,
                payload,
            ) catch |err| return self.blockControllerRequest(a, parent, pending, err);
            const reply = try data.invocation.encodeOwned(data.invocation.Result, a, .{
                .request_identity = pending.request,
                .value = payload,
            });
            defer a.free(reply);
            const binding: occurrence.Binding = .{
                .id = pending.id,
                .task = parent.id,
                .work = work.id,
                .request = pending.request,
            };
            const dispatched = try occurrence.dispatch(pending, binding, pending.id, false, false);
            const acquired = try occurrence.acquired(
                dispatched,
                binding,
                pending.id,
                storage.digest(reply),
            );
            var value = parent;
            value.revision = try std.math.add(u64, value.revision, 1);
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(reply);
            try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                parent.id,
                acquired,
            );
            try self.effectSchedule(a, &value, acquired, .queued, null);
            try self.persist(a, value, parent.revision, "controller.trial-reply", .preserve);
            return .progressed;
        }
        fn parkControllerTrialReply(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
        ) !Step {
            var value = initial;
            value.schedule = .parked;
            value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.writeWorkspaceWork(&value, .replace);
            _ = try self.workspaceCommit(
                a,
                parent,
                null,
                @splat(0),
                value.id,
                .work,
                try self.snapshotRecord(
                    workspace.Work,
                    a,
                    "workspace_work",
                    value.id,
                    value.task,
                ),
                null,
            );
            return .progressed;
        }
        fn pumpWorkspaceDelivery(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            pending: occurrence.Occurrence,
        ) !?Step {
            if (pending.state == .captured) return try self.interpretCapture(
                a,
                parent,
                pending,
            );
            if (pending.state == .ready and
                value.trial != null)
                return try self.settleControllerTrial(
                    a,
                    parent,
                    value,
                    pending,
                );
            if (pending.state == .ready and value.delegation != null) {
                if (!try self.delegationCurrent(
                    a,
                    parent,
                    value,
                )) return try self.blockedOccurrence(
                    a,
                    parent,
                    pending,
                    .denied,
                );
                return try self.dispatch(a, parent, pending);
            }
            if (pending.state == .unknown or
                pending.state == .not_sent)
                return try self.blockedOccurrence(
                    a,
                    parent,
                    pending,
                    .unavailable_environment,
                );
            return null;
        }
        fn pumpWorkspaceOccurrence(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            id: state.Digest,
        ) !Step {
            var pending = try self.record(occurrence.Occurrence, a, "occurrence", id, value.task);
            defer pending.deinit();
            if (value.cancellation != null and !value.cancellation_applied and
                (pending.value.state == .ready or
                    pending.value.state == .awaiting or
                    pending.value.state == .not_sent))
            {
                _ = try self.workspaceAdvance(
                    a,
                    parent,
                    value,
                    .{ .cancel = .{ .text = value.cancellation.?.bytes } },
                    null,
                    @splat(0),
                    null,
                );
                return .progressed;
            }
            if (try self.pumpWorkspaceDelivery(a, parent, value, pending.value)) |step| return step;
            if (pending.value.state != .settled_reply) return .idle;
            if (value.trial != null and
                value.policy.continuation == .explicit_only and value.cancellation == null)
                return self.parkControllerTrialReply(a, parent, value);
            const reply = try self.store().acquiredObject(
                a,
                pending.value.state.settled_reply.reply,
                null,
            );
            defer a.free(reply);
            _ = try self.workspaceAdvance(
                a,
                parent,
                value,
                .{ .reply = reply },
                null,
                @splat(0),
                null,
            );
            return .progressed;
        }
        fn pumpWorkspace(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
        ) !Step {
            self.requireCustody(a, task_id, work_id) catch |err| {
                if (err != error.CustodyNotLocal) return err;
                self.subjectRemove(.{ .task = task_id, .work = work_id });
                return .idle;
            };
            var saved = try self.workspaceWork(a, task_id, work_id);
            defer saved.deinit();
            const subject: workspace.Subject = .{ .task = task_id, .work = work_id };
            if (saved.value.outcome_kind == .completed and saved.value.observer != null)
                return self.pumpObserver(a, saved.value);
            if (saved.value.terminal() and saved.value.answer_value != null) {
                // Completion and delivery are distinct durable transitions.
                // The retained answer plus its current delegation is the
                // pending transfer, including after explicit task resume.
                try self.workspaceApplyAnswer(a, saved.value);
                self.subjectRemove(subject);
                return .progressed;
            }
            if (saved.value.terminal() or saved.value.schedule == .parked) {
                self.subjectRemove(subject);
                return .progressed;
            }
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            if ((parent.value.cancellation != null or
                parent.value.terminal()) and
                saved.value.cancellation == null)
            {
                try self.parkWorkspaceOnClose(a, task_id, work_id);
                self.subjectRemove(subject);
                return .progressed;
            }
            if (saved.value.outer_operation != null) {
                _ = try self.workspacePumpWork(
                    a,
                    parent.value,
                    saved.value,
                    65536,
                    null,
                    @splat(0),
                    null,
                );
                return .progressed;
            }
            if (saved.value.current_occurrence) |id| {
                return self.pumpWorkspaceOccurrence(a, parent.value, saved.value, id);
            }
            _ = try self.workspaceAdvance(
                a,
                parent.value,
                saved.value,
                workspaceContinuation(saved.value),
                null,
                @splat(0),
                null,
            );
