            }
            return child.answer_value != null and try self.delegationCurrent(a, parent, child);
        }
        pub fn workspacePump(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            command: @FieldType(wc.Work, "pump"),
        ) !Admission {
            if (command.base_quantum == 0 or
                command.base_quantum > 1048576)
                return error.InvalidParams;
            const request = try operation(workspace.PumpRequest, a, .{
                .task = task_id,
                .command = command,
            });
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            var work = try self.runtimeWork(a, task_id, command.expected);
            defer work.deinit();
            if (work.value.terminal()) return error.InvalidState;
            if (self.workspaceParentStopped(
                parent.value,
            ) and work.value.cancellation == null) return error.InvalidState;
            if (try self.queueControllerTrial(a, parent.value, work.value, operation_id, request, .{
                .pump = command,
            })) |admitted| return admitted;
            work.value.control_revision = try std.math.add(u64, work.value.control_revision, 1);
            return self.workspacePumpWork(
                a,
                parent.value,
                work.value,
                command.base_quantum,
                operation_id,
                request,
                .{ .pump = command },
            );
        }
        fn trialControlReady(value: workspace.ControlObservation) bool {
            return value.trial and
                !value.port and
                (value.cancellation == null or
                    value.cancellation_applied) and
                (value.delivery == .ready or
                    value.delivery == .not_sent);
        }
        fn queueControllerTrial(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            operation_id: []const u8,
            request: state.Digest,
            command: workspace.PublicationCommand,
        ) !?Admission {
            if (initial.trial == null or initial.outer_operation != null) return null;
            const id = initial.current_occurrence orelse return null;
            var pending = try self.record(occurrence.Occurrence, a, "occurrence", id, parent.id);
            defer pending.deinit();
            if (!trialControlReady(
                workspace.ControlObservation.from(.{
                    .work = initial,
                    .occurrence = pending.value,
                }),
            )) return null;
            try self.requireCustody(a, parent.id, initial.id);
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            var value = initial;
            value.control_revision = try std.math.add(u64, value.control_revision, 1);
            value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            value.schedule = .queued;
            value.blocker = null;
            try self.store().begin();
            defer self.store().rollback();
            if (pending.value.state == .not_sent) try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                id,
                parent.id,
                try occurrence.rearm(pending.value, .{
                    .id = id,
                    .task = parent.id,
                    .work = value.id,
                    .request = pending.value.request,
                }),
            );
            try self.writeWorkspaceWork(&value, .replace);
            const admitted = try self.workspaceCommit(
                a,
                parent,
                operation_id,
                request,
                value.id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", value.id, parent.id),
                command,
            );
            return admitted;
        }
        fn workspacePumpQuantum(
            self: *Self,
            a: std.mem.Allocator,
            initial: workspace.Work,
            control: *data.invocation.Control,
            reply_bytes: *?[]u8,
        ) !u64 {
            return if (initial.outer_operation) |pending|
                pending.guest_quantum
            else blk: {
                if (initial.current_occurrence) |id| {
                    var occurrence_value = try self.record(
                        occurrence.Occurrence,
                        a,
                        "occurrence",
                        id,
                        initial.task,
                    );
                    defer occurrence_value.deinit();
                    if (occurrence_value.value.state == .settled_reply) {
                        reply_bytes.* = try self.store().acquiredObject(
                            a,
                            occurrence_value.value.state.settled_reply.reply,
                            null,
                        );
                        control.* = .{ .reply = reply_bytes.*.? };
                    } else if (control.* != .cancel or
                        (occurrence_value.value.state != .ready and
                            occurrence_value.value.state != .awaiting and
                            occurrence_value.value.state != .not_sent))
                        return error.WaitingInput;
                }
                break :blk @as(
                    u64,
                    if (control.* == .reply and
                        initial.cancellation != null and
                        !initial.cancellation_applied) 0 else try self.observerGuestQuantum(
                        a,
                        initial,
                    ),
                );
            };
        }
        fn workspaceSuspendPump(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            driver: *evaluator.Driver,
            control_bytes: ?[]const u8,
            guest_quantum: u64,
            elapsed: u64,
            operation_id: ?[]const u8,
            request: state.Digest,
            command: ?workspace.PublicationCommand,
        ) !Admission {
            const capsule = try driver.retainCapsule(runtimeProvenance(initial));
            const code = try driver.runtimeBytes(a);
            defer a.free(code);
            try self.store().begin();
            defer self.store().rollback();
            _ = try self.store().putObject(code);
            var value = initial;
            value.outer_operation = .{
                .capsule = try self.store().putObject(capsule),
                .dependencies = .{ .items = try capsuleDependencies(a, capsule) },
                .control = if (initial.outer_operation) |pending|
                    pending.control
                else
                    try self.store().putObject(control_bytes.?),
                .guest_quantum = guest_quantum,
            };
            defer a.free(value.outer_operation.?.dependencies.items);
            value.runtime_capsule = null;
            value.runtime_dependencies = .{ .items = &.{} };
            value.native_publication_nanoseconds +|= elapsed;
            value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            value.schedule = if (value.cancellation != null or
                value.policy.continuation == .owner_scheduled) .queued else .parked;
            try self.writeWorkspaceWork(&value, .replace);
            const admitted = try self.workspaceCommit(
                a,
                parent,
                operation_id,
                request,
                value.id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", value.id, value.task),
                command,
            );
            self.active.?.outer_operation = value.outer_operation.?.capsule;
            return admitted;
        }
        fn workspacePumpDriver(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            driver: *evaluator.Driver,
            control: data.invocation.Control,
            control_bytes: ?[]const u8,
            guest_quantum: u64,
            base_quantum: u64,
            native_started: anytype,
            operation_value: GuardOperation,
        ) !Admission {
            errdefer self.store().fence();
            var progress = try driver.pump(base_quantum);
            defer progress.deinit();
            const elapsed = std.math.cast(
                u64,
                @max(0, std.Io.Clock.awake.now(self.io).nanoseconds - native_started.nanoseconds),
            ) orelse std.math.maxInt(u64);
            if (progress == .event and progress.event.value == .cut) {
                // The operation already applied its control. Publish the cut
                // with a read-only zero-quantum observation, never another reply.
                var publication = try driver.drive(a, .none, 0);
                defer a.free(publication.outcome);
                publication.guest_work = progress.event.value.cut.guest_work;
                return self.workspaceFinish(
                    a,
                    parent,
                    initial,
                    control,
                    publication,
                    elapsed,
                    operation_value.operation_id,
                    operation_value.request,
                    operation_value.command,
                );
            }
            if (progress != .suspended) return error.InvalidRuntimeProgress;
            return self.workspaceSuspendPump(
                a,
                parent,
                initial,
                driver,
                control_bytes,
                guest_quantum,
                elapsed,
                operation_value.operation_id,
                operation_value.request,
                operation_value.command,
            );
        }
        fn workspacePumpWork(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            base_quantum: u64,
            operation_id: ?[]const u8,
            request: state.Digest,
            command: ?workspace.PublicationCommand,
        ) !Admission {
            if (initial.cancellation == null) try self.requireRuntimePolicy(
                a,
                initial.task,
                initial.runtime,
            );
            try self.requireCustody(a, initial.task, initial.id);
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            var control = workspaceContinuation(initial);
            var decoded: ?contracts.Decoded(data.invocation.Control) = null;
            defer if (decoded) |*value| value.deinit();
            var control_bytes: ?[]u8 = null;
            defer if (control_bytes) |bytes| a.free(bytes);
            var reply_bytes: ?[]u8 = null;
            defer if (reply_bytes) |bytes| a.free(bytes);
            const native_started = std.Io.Clock.awake.now(self.io);
            const guest_quantum = try self.workspacePumpQuantum(a, initial, &control, &reply_bytes);
            try self.observerAdvanceAllowed(a, initial);
            if (initial.guard != null and initial.cancellation == null)
                return self.workspaceGuardAdvance(
                    a,
                    parent,
                    initial,
                    control,
                    try self.observerGuestQuantum(a, initial),
                    base_quantum,
                    operation_id,
                    request,
                    command,
                );
            const driver = try self.workspaceResident(a, initial);
            if (initial.outer_operation) |pending| {
                const bytes = try self.store().object(a, pending.control, null);
                defer a.free(bytes);
                decoded = try contracts.decodeOwned(data.invocation.Control, a, bytes);
                control = decoded.?.value;
            } else {
                control_bytes = try contracts.encodeOwned(data.invocation.Control, a, control);
                _ = try self.workspaceConsumed(a, initial, control);
                try driver.beginAdvance(control, guest_quantum);
            }
            return self.workspacePumpDriver(
                a,
                parent,
                initial,
                driver,
                control,
                control_bytes,
                guest_quantum,
                base_quantum,
                native_started,
                .{
                    .operation_id = operation_id,
                    .request = request,
                    .command = command,
                },
            );
        }
        fn workspaceConsumed(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            control: data.invocation.Control,
        ) !?occurrence.Occurrence {
            if (control == .cancel or control == .reply) if (work.current_occurrence) |id| {
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    id,
                    work.task,
                );
                defer pending.deinit();
                return try occurrence.consumed(
                    pending.value,
                    .{
                        .id = id,
                        .task = work.task,
                        .work = work.id,
                        .request = pending.value.request,
                    },
                    if (control == .cancel) .cancel else .{
                        .reply = storage.digest(control.reply),
                    },
                    work.cancellation != null,
                );
            };
            return null;
        }
        fn workspaceGuardExperiment(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
        ) !kosmos.RuntimeExperiment.Experiment {
            var phase: []const u8 = "program";
            errdefer std.debug.print("guard experiment: {s}\n", .{phase});
            const guard = work.guard orelse return error.GuardUnavailable;
            var program = try self.workspaceProgram(a, work.task, work.program);
            defer program.deinit();
            const image = try self.store().object(a, program.value.description.image, null);
            defer a.free(image);
            const code = try self.store().object(a, guard.code, null);
            defer a.free(code);
            phase = "candidate artifact admission";
            var candidate = try kosmos.RuntimeArtifact.init(a, code, guard.code.digest);
            defer candidate.deinit();
            phase = "continuation bytes";
            const ref = guard.continuation orelse work.checkpoint;
            const bytes = try self.store().object(a, ref, null);
            defer a.free(bytes);
            phase = "continuation restore";
            if (guard.continuation != null)
                return kosmos.RuntimeExperiment.Experiment.restore(a, image, &candidate, bytes);
            phase = "initial experiment";
            return kosmos.RuntimeExperiment.Experiment.init(a, image, &candidate, bytes);
        }
        fn workspaceGuardCandidateAdvance(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            control: data.invocation.Control,
            bytes: []const u8,
            base_quantum: u64,
            operation_value: GuardOperation,
        ) !Admission {
            var work = initial;
            const guard = &work.guard.?;
            var candidate = self.workspaceGuardExperiment(a, work) catch |err|
                return self.workspaceGuardFailure(a, parent, work, bytes, err, operation_value);
            defer candidate.deinit();
            if (guard.initialized and candidate.phase == .ready)
                try beginGuardCandidate(a, &candidate, control, guard.guest_quantum);
            const started = std.Io.Clock.awake.now(self.io);
            var progress = candidate.pump(base_quantum) catch |err|
                return self.workspaceGuardFailure(a, parent, work, bytes, err, operation_value);
            defer if (progress == .complete) progress.complete.deinit();
            guard.candidate_nanoseconds +|= std.math.cast(u64, @max(
                0,
                std.Io.Clock.awake.now(self.io).nanoseconds - started.nanoseconds,
            )) orelse std.math.maxInt(u64);
            guard.failure = null;
            if (progress == .complete and progress.complete.stage == .initialized) {
                if (!try self.guardInitialMatches(a, work, progress.complete))
                    return self.workspaceGuardDiverged(
                        a,
                        parent,
                        work,
                        bytes,
                        &candidate,
                        operation_value,
                    );
                guard.initialized = true;
                try beginGuardCandidate(a, &candidate, control, guard.guest_quantum);
            } else if (progress == .complete) {
                const capsule = try candidate.checkpointOuter(a);
                defer a.free(capsule);
                guard.disposition = .incomplete;
                return self.workspaceGuardRetain(a, parent, work, bytes, .{
                    .candidate = capsule,
                    .segment = progress.complete,
                }, operation_value);
            }
            const capsule = try candidate.checkpointOuter(a);
            defer a.free(capsule);
            guard.disposition = .incomplete;
            return self.workspaceGuardRetain(
                a,
                parent,
                work,
                bytes,
                .{ .candidate = capsule },
                operation_value,
            );
        }
        fn workspaceGuardAdvance(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            control: data.invocation.Control,
            quantum: u64,
            base_quantum: u64,
            operation_id: ?[]const u8,
            request: state.Digest,
            command: ?workspace.PublicationCommand,
        ) !Admission {
            const operation_value: GuardOperation = .{
                .operation_id = operation_id,
                .request = request,
                .command = command,
            };
            var work = initial;
            const guard = &work.guard.?;
            try self.requireGuardPolicy(a, work);
            if (guard.disposition == .diverged) return error.GuardDiverged;
            const bytes = try contracts.encodeOwned(data.invocation.Control, a, control);
            defer a.free(bytes);
            if (guard.pending_control) |owned| {
                if (!std.meta.eql(owned.digest, storage.digest(bytes)) or owned.bytes != bytes.len)
                    return error.GuardControlMismatch;
            } else guard.guest_quantum = quantum;
            _ = try self.workspaceConsumed(a, initial, control);
            if (guard.candidate_segment != null)
                return self.workspaceGuardReference(
                    a,
                    parent,
                    work,
                    control,
                    bytes,
                    base_quantum,
                    operation_value,
                );
            return self.workspaceGuardCandidateAdvance(
                a,
                parent,
                work,
                control,
                bytes,
                base_quantum,
                operation_value,
            );
        }
        fn guardInitialMatches(
            self: *Self,
            a: std.mem.Allocator,
            work: workspace.Work,
            segment: kosmos.RuntimeExperiment.Segment,
        ) !bool {
            const checkpoint = try self.store().object(a, work.checkpoint, null);
            defer a.free(checkpoint);
            return same(checkpoint, segment.checkpoint) and segment.guest_work == 0;
        }
        fn beginGuardCandidate(
            a: std.mem.Allocator,
            candidate: *kosmos.RuntimeExperiment.Experiment,
            control: data.invocation.Control,
            quantum: u64,
        ) !void {
            if (control == .reply) {
                var reply = try data.invocation.decode(data.invocation.Result, a, control.reply);
                defer reply.deinit();
                return candidate.begin(.{ .answer = reply.value.value }, quantum);
            }
            return candidate.begin(switch (control) {
                .none => .none,
                .resume_yield => .resume_yield,
                .cancel => |reason| .{ .cancel = reason },
                .reply => unreachable,
            }, quantum);
        }
        fn workspaceGuardFailure(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work: workspace.Work,
            control: []const u8,
            failure: anyerror,
            operation_value: GuardOperation,
        ) !Admission {
            var next = work;
            next.guard.?.disposition = .incomplete;
            next.guard.?.failure = try name(@errorName(failure));
            return self.workspaceGuardRetain(a, parent, next, control, .{}, operation_value);
        }
        fn workspaceGuardDiverged(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            work: workspace.Work,
            control: []const u8,
            candidate: *kosmos.RuntimeExperiment.Experiment,
            operation_value: GuardOperation,
        ) !Admission {
            var next = work;
            next.guard.?.disposition = .diverged;
            const capsule = try candidate.checkpointOuter(a);
            defer a.free(capsule);
            return self.workspaceGuardRetain(
                a,
                parent,
                next,
                control,
                .{ .candidate = capsule },
                operation_value,
            );
        }
        fn workspaceGuardRetain(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            control: []const u8,
            retained: GuardRetention,
            operation_value: GuardOperation,
        ) !Admission {
            var work = initial;
            const guard = &work.guard.?;
            guard.revision = try std.math.add(u64, guard.revision, 1);
            work.event_watermark = try std.math.add(u64, parent.event_high, 1);
            work.schedule = if (guard.disposition == .diverged or guard.failure != null or
                work.policy.continuation == .explicit_only) .parked else .queued;
            try self.store().begin();
            defer self.store().rollback();
            if (retained.candidate) |bytes| guard.continuation = try self.store().putObject(bytes);
            guard.pending_control = try self.store().putObject(control);
            if (retained.segment) |segment| guard.candidate_segment = .{
                .checkpoint = try self.store().putObject(segment.checkpoint),
                .observation = try self.store().putObject(segment.observation),
                .guest_work = segment.guest_work,
            };
            if (retained.code) |bytes| _ = try self.store().putObject(bytes);
            if (retained.reference) |bytes| guard.reference_operation = .{
                .capsule = try self.store().putObject(bytes),
                .dependencies = .{ .items = try capsuleDependencies(a, bytes) },
                .control = guard.pending_control.?,
                .guest_quantum = guard.guest_quantum,
            };
            defer if (retained.reference != null) a.free(
                guard.reference_operation.?.dependencies.items,
            );
            try self.store().putRecord(
                workspace.Work,
                "workspace_work",
                work.id,
                work.task,
                work,
            );
            return self.workspaceCommit(
                a,
                parent,
                operation_value.operation_id,
                operation_value.request,
                work.id,
                .work,
                try self.snapshotRecord(
                    workspace.Work,
                    a,
                    "workspace_work",
                    work.id,
                    work.task,
                ),
                operation_value.command,
            );
        }
        fn workspaceGuardReference(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            control: data.invocation.Control,
            encoded: []const u8,
            base_quantum: u64,
            operation_value: GuardOperation,
        ) !Admission {
            var work = initial;
            const guard = &work.guard.?;
            var provisional = work;
            provisional.outer_operation = guard.reference_operation;
            const driver = try self.workspaceResident(a, provisional);
            errdefer self.retire(a) catch self.store().fence();
            const started = std.Io.Clock.awake.now(self.io);
            if (guard.reference_operation == null) try driver.beginAdvance(
                control,
                guard.guest_quantum,
            );
            var progress = try driver.pump(base_quantum);
            defer progress.deinit();
            const elapsed = std.math.cast(u64, @max(
                0,
                std.Io.Clock.awake.now(self.io).nanoseconds - started.nanoseconds,
            )) orelse std.math.maxInt(u64);
            guard.reference_nanoseconds +|= elapsed;
            if (progress == .event and progress.event.value == .cut)
                return self.workspaceGuardCompare(
                    a,
                    parent,
                    work,
                    control,
                    encoded,
                    driver,
                    elapsed,
                    operation_value,
                );
            if (progress != .suspended) return error.InvalidRuntimeProgress;
            const capsule = try driver.retainCapsule(runtimeProvenance(work));
            const code = try driver.runtimeBytes(a);
            defer a.free(code);
            const admitted = try self.workspaceGuardRetain(
                a,
                parent,
                work,
                encoded,
                .{ .reference = capsule, .code = code },
                operation_value,
            );
            self.active.?.outer_operation = .{
                .digest = storage.digest(capsule),
                .bytes = capsule.len,
            };
            return admitted;
        }
        fn workspaceGuardCompare(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            control: data.invocation.Control,
            encoded: []const u8,
            driver: *evaluator.Driver,
            elapsed: u64,
            operation_value: GuardOperation,
        ) !Admission {
            var work = initial;
            const guard = &work.guard.?;
            const started = std.Io.Clock.awake.now(self.io);
            var observed = try driver.runtimeObservation(a);
            defer observed.deinit();
            const segment = guard.candidate_segment.?;
            var publication = try driver.drive(a, .none, 0);
            publication.guest_work = observed.guest_work;
            defer a.free(publication.outcome);
            const preparation_elapsed = std.math.cast(u64, @max(
                0,
                std.Io.Clock.awake.now(self.io).nanoseconds - started.nanoseconds,
            )) orelse std.math.maxInt(u64);
            guard.reference_nanoseconds +|= preparation_elapsed;
            const agrees = std.meta.eql(
                storage.digest(publication.checkpoint),
                segment.checkpoint.digest,
            ) and
                publication.checkpoint.len == segment.checkpoint.bytes and
                std.meta.eql(storage.digest(observed.observation), segment.observation.digest) and
                observed.observation.len == segment.observation.bytes and
                observed.guest_work == segment.guest_work;
            if (!agrees) {
                try self.retire(a);
                guard.disposition = .diverged;
                return self.workspaceGuardRetain(a, parent, work, encoded, .{}, operation_value);
            }
            guard.pending_control = null;
            guard.reference_operation = null;
            guard.candidate_segment = null;
            guard.disposition = .agreed;
            guard.revision = try std.math.add(u64, guard.revision, 1);
            guard.agreed_segments = try std.math.add(u64, guard.agreed_segments, 1);
            errdefer self.store().fence();
            return self.workspaceFinish(
                a,
                parent,
                work,
                control,
                publication,
                elapsed +| preparation_elapsed,
                operation_value.operation_id,
                operation_value.request,
                operation_value.command,
            );
        }
        fn workspaceAdvance(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            control: data.invocation.Control,
            operation_id: ?[]const u8,
            request: state.Digest,
            command: ?workspace.PublicationCommand,
        ) !Admission {
            if (initial.cancellation == null) try self.requireRuntimePolicy(
                a,
                initial.task,
                initial.runtime,
            );
            try self.requireCustody(a, initial.task, initial.id);
            try self.observerAdvanceAllowed(a, initial);
            if (initial.guard != null and initial.cancellation == null)
                return self.workspaceGuardAdvance(
                    a,
                    parent,
                    initial,
                    control,
                    try self.observerGuestQuantum(a, initial),
                    65536,
                    operation_id,
                    request,
                    command,
                );
            if (initial.outer_operation != null) return self.workspacePumpWork(
                a,
                parent,
                initial,
                65536,
                operation_id,
                request,
                command,
            );
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            const driver = try self.workspaceResident(a, initial);
            _ = try self.workspaceConsumed(a, initial, control);
            const native_started = std.Io.Clock.awake.now(self.io);
            const publication = try driver.drive(
                a,
                control,
                if (control == .reply and
                    initial.cancellation != null and
                    !initial.cancellation_applied) 0 else try self.observerGuestQuantum(
                    a,
                    initial,
                ),
            );
            defer a.free(publication.outcome);
            errdefer self.store().fence();
            const elapsed = std.math.cast(
                u64,
                @max(0, std.Io.Clock.awake.now(self.io).nanoseconds - native_started.nanoseconds),
            ) orelse std.math.maxInt(u64);
            return self.workspaceFinish(
                a,
                parent,
                initial,
                control,
                publication,
                elapsed,
                operation_id,
                request,
                command,
            );
        }
        fn workspaceFinish(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            control: data.invocation.Control,
            publication: evaluator.Driver.Publication,
            elapsed: u64,
            operation_id: ?[]const u8,
            request: state.Digest,
            command: ?workspace.PublicationCommand,
        ) !Admission {
            const consumed = try self.workspaceConsumed(a, initial, control);
            var value = initial;
            if (value.cancellation != null) value.guard = null;
            value.native_publication_nanoseconds +|= elapsed;
            if (control == .cancel) value.cancellation_applied = true;
            if (consumed != null) {
                value.current_occurrence = null;
                value.current_port = null;
            }
            value.execution_revision = try std.math.add(u64, value.execution_revision, 1);
            value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            try self.store().begin();
            defer self.store().rollback();
            if (consumed) |prior| try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                prior.id,
                value.task,
                prior,
            );
            try self.workspacePublication(a, &value, publication);
            defer if (value.runtime_trace) |trace| a.free(trace.dependencies.items);
            if (parent.observers_present) try self.retainObservedOuter(a, &value);
            defer if (value.runtime_capsule != null) a.free(value.runtime_dependencies.items);
            if (value.outcome_kind == .completed and value.delegation != null) {
                value.answer_value = try self.workspaceInstrumentAnswer(a, parent, value);
                if (value.answer_value) |answer| {
                    const sources = try a.alloc(state.Reference, value.inputs.items.len + 1);
                    @memcpy(sources[0..value.inputs.items.len], value.inputs.items);
                    sources[value.inputs.items.len] = answer;
                    value.inputs = .{ .items = sources };
                }
                var program = try self.workspaceProgram(a, value.task, value.program);
                defer program.deinit();
                value.result_value = try self.workspaceResultValue(a, value, program.value);
            }
            try self.writeWorkspaceWork(&value, .replace);
            const admitted = try self.workspaceCommit(
                a,
                parent,
                operation_id,
                request,
                value.id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", value.id, value.task),
                command,
            );
            self.active.?.execution_revision = value.execution_revision;
            self.active.?.outer_operation = null;
            return admitted;
        }
        fn workspaceObservationCancellation(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            reason: state.Reason,
            operation_id: []const u8,
            request: state.Digest,
            command: workspace.PublicationCommand,
        ) !?Admission {
            if (reason.bytes.len > 256 or !std.unicode.utf8ValidateSlice(reason.bytes))
                return error.InvalidParams;
            const observation_waiting = waiting: {
                self.observerAdvanceAllowed(a, initial) catch |err| switch (err) {
                    error.ObservationBlocked => break :waiting true,
                    else => return err,
                };
                break :waiting false;
            };
            if (!observation_waiting) return null;
            var value = initial;
            if (value.cancellation == null) value.cancellation = reason;
            value.guard = null;
            value.schedule = .queued;
            value.blocker = .observation_blocked;
            value.control_revision = try std.math.add(u64, value.control_revision, 1);
            value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.writeWorkspaceWork(&value, .replace);
            const admitted = try self.workspaceCommit(
                a,
                parent,
                operation_id,
                request,
                value.id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", value.id, value.task),
                command,
            );
            if (self.work) |*active| if (std.meta.eql(active.subject_work, value.id) and
                std.meta.eql(active.task, value.task))
            {
                active.cancel_requested = true;
            };
            return admitted;
        }
        fn workspaceCancelPending(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            pending: occurrence.Occurrence,
            operation_id: []const u8,
            request: state.Digest,
            publication_command: workspace.PublicationCommand,
        ) !?Admission {
            var value = initial;
            if (pending.state == .dispatching or
                pending.state == .unknown or
                pending.state == .captured)
            {
                value.schedule = switch (pending.state) {
                    .captured => .queued,
                    .dispatching => .active,
                    else => .parked,
                };
                value.event_watermark = parent.event_high + 1;
                try self.runnable.ensureUnusedCapacity(self.allocator, 2);
                try self.store().begin();
                defer self.store().rollback();
                try self.writeWorkspaceWork(&value, .replace);
                const admitted = try self.workspaceCommit(
                    a,
                    parent,
                    operation_id,
                    request,
                    value.id,
                    .work,
                    try self.snapshotRecord(
                        workspace.Work,
                        a,
                        "workspace_work",
                        value.id,
                        value.task,
                    ),
                    publication_command,
                );
                if (self.work) |*active| if (std.meta.eql(
                    active.subject_work,
                    value.id,
                ) and std.meta.eql(active.task, value.task)) {
                    active.cancel_requested = true;
                };
                return admitted;
            }
            return null;
        }
        fn workspaceCancelControl(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            reason: state.Reason,
            operation_id: []const u8,
            request: state.Digest,
            publication_command: workspace.PublicationCommand,
        ) !Admission {
            var value = initial;
            value.guard = null;
            if (reason.bytes.len > 256 or !std.unicode.utf8ValidateSlice(
                reason.bytes,
            )) return error.InvalidParams;
            if (value.cancellation == null) value.cancellation = reason;
            value.control_revision = try std.math.add(u64, value.control_revision, 1);
            if (value.current_occurrence) |id| {
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    id,
                    value.task,
                );
                defer pending.deinit();
                if (try self.workspaceCancelPending(
                    a,
                    parent,
                    value,
                    pending.value,
                    operation_id,
                    request,
                    publication_command,
                )) |admitted| return admitted;
                if (pending.value.state == .settled_reply) {
                    const reply = try self.store().acquiredObject(
                        a,
                        pending.value.state.settled_reply.reply,
                        null,
                    );
                    defer a.free(reply);
                    return self.workspaceAdvance(
                        a,
                        parent,
                        value,
                        .{ .reply = reply },
                        operation_id,
                        request,
                        publication_command,
                    );
                }
            }
            return self.workspaceAdvance(
                a,
                parent,
                value,
                .{ .cancel = .{ .text = value.cancellation.?.bytes } },
                operation_id,
                request,
                publication_command,
            );
        }
        fn workspaceAdvanceControl(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            value: workspace.Work,
            operation_id: []const u8,
            request: state.Digest,
            publication_command: workspace.PublicationCommand,
        ) !Admission {
            if (try self.queueControllerTrial(
                a,
                parent,
                value,
                operation_id,
                request,
                publication_command,
            )) |admitted| return admitted;
            if (value.current_occurrence) |id| {
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    id,
                    value.task,
                );
                defer pending.deinit();
                if (pending.value.state != .settled_reply) return error.WaitingInput;
                const reply = try self.store().acquiredObject(
                    a,
                    pending.value.state.settled_reply.reply,
                    null,
                );
                defer a.free(reply);
                return self.workspaceAdvance(
                    a,
                    parent,
                    value,
                    .{ .reply = reply },
                    operation_id,
                    request,
                    publication_command,
                );
            }
            return self.workspaceAdvance(
                a,
                parent,
                value,
                workspaceContinuation(value),
                operation_id,
                request,
                publication_command,
            );
        }
        fn workspaceDelegateControl(
            self: *Self,
            a: std.mem.Allocator,
            value: *workspace.Work,
            policy: workspace.RunPolicy,
        ) !?occurrence.Occurrence {
            var rearmed: ?occurrence.Occurrence = null;
            var before = workspace.ControlObservation.from(.{
                .work = value.*,
                .occurrence = null,
            });
            if (value.current_occurrence) |id| {
                var pending = try self.record(
                    occurrence.Occurrence,
                    a,
                    "occurrence",
                    id,
                    value.task,
                );
                defer pending.deinit();
                before.delivery = std.meta.activeTag(pending.value.state);
                const delegated = delegatedControl(
                    before,
                    value.outer_operation != null,
                    value.guard,
                    policy,
                );
                if (delegated.delivery != before.delivery) {
                    rearmed = try occurrence.rearm(pending.value, .{
                        .id = id,
                        .task = value.task,
                        .work = value.id,
                        .request = pending.value.request,
                    });
                }
            }
            const delegated = delegatedControl(
                before,
                value.outer_operation != null,
                value.guard,
                policy,
            );
            value.policy = delegated.policy;
            value.schedule = delegated.schedule;
            return rearmed;
        }
        fn workspaceScheduleControl(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            command: workspace.Command,
            operation_id: []const u8,
            request: state.Digest,
            publication_command: workspace.PublicationCommand,
        ) !Admission {
            var value = initial;
            try self.runnable.ensureUnusedCapacity(self.allocator, 1);
            value.control_revision = try std.math.add(u64, value.control_revision, 1);
            value.event_watermark = try std.math.add(u64, parent.event_high, 1);
            var rearmed: ?occurrence.Occurrence = null;
            switch (command) {
                .park => value.schedule = .parked,
                .delegate => |policy| {
                    rearmed = try self.workspaceDelegateControl(a, &value, policy);
                },
                .advance, .cancel => unreachable,
            }
            try self.store().begin();
            defer self.store().rollback();
            if (rearmed) |pending| try self.store().putRecord(
                occurrence.Occurrence,
                "occurrence",
                pending.id,
                value.task,
                pending,
            );
            try self.writeWorkspaceWork(&value, .replace);
            const admitted = try self.workspaceCommit(
                a,
                parent,
                operation_id,
                request,
                value.id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", value.id, value.task),
                publication_command,
            );
            return admitted;
        }
        fn workspaceControlAdmitted(
            self: *Self,
            a: std.mem.Allocator,
            parent: state.Task,
            initial: workspace.Work,
            command: workspace.Command,
            operation_id: []const u8,
            request: state.Digest,
            publication_command: workspace.PublicationCommand,
        ) !Admission {
            var value = initial;
            if (command == .cancel) if (try self.workspaceObservationCancellation(
                a,
                parent,
                value,
                command.cancel,
                operation_id,
                request,
                publication_command,
            )) |admitted| return admitted;
            if (value.outer_operation != null and (command == .advance or command == .cancel)) {
                if (command == .cancel) {
                    if (command.cancel.bytes.len > 256 or !std.unicode.utf8ValidateSlice(
                        command.cancel.bytes,
                    )) return error.InvalidParams;
                    if (value.cancellation == null) value.cancellation = command.cancel;
                    value.control_revision = try std.math.add(u64, value.control_revision, 1);
                }
                return self.workspacePumpWork(
                    a,
                    parent,
                    value,
                    65536,
                    operation_id,
                    request,
                    publication_command,
                );
            }
            if (command == .cancel) return self.workspaceCancelControl(
                a,
                parent,
                value,
                command.cancel,
                operation_id,
                request,
                publication_command,
            );
            if (command == .advance) return self.workspaceAdvanceControl(
                a,
                parent,
                value,
                operation_id,
                request,
                publication_command,
            );
            return self.workspaceScheduleControl(
                a,
                parent,
                value,
                command,
                operation_id,
                request,
                publication_command,
            );
        }
        pub fn workspaceControl(
            self: *Self,
            a: std.mem.Allocator,
            operation_id: []const u8,
            task_id: state.TaskId,
            work_id: state.Digest,
            expected_execution: u64,
            expected_control: u64,
            command: workspace.Command,
        ) !Admission {
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            try self.compatible(parent.value);
            const Request = workspace.ControlRequest;
            const request = try operation(Request, a, .{
                .task = task_id,
                .work = work_id,
                .execution = expected_execution,
                .control = expected_control,
                .command = command,
            });
            const publication_command: workspace.PublicationCommand = .{ .control = .{
                .execution = expected_execution,
                .control = expected_control,
                .command = command,
            } };
            if (try self.replay(a, operation_id, request)) |prior| return prior;
            try self.requireCustody(a, task_id, work_id);
            var saved = try self.workspaceWork(a, task_id, work_id);
            defer saved.deinit();
            const value = saved.value;
            if (value.execution_revision != expected_execution or
                value.control_revision != expected_control)
                return error.StaleRevision;
            if (value.terminal()) return error.InvalidState;
            if (command != .park and command != .cancel and self.workspaceParentStopped(
                parent.value,
            )) return error.InvalidState;
            return self.workspaceControlAdmitted(
                a,
                parent.value,
                value,
                command,
                operation_id,
                request,
                publication_command,
            );
        }
        fn parkWorkspaceOnClose(
            self: *Self,
            a: std.mem.Allocator,
            task_id: state.TaskId,
            work_id: state.Digest,
        ) !void {
            try self.requireCustody(a, task_id, work_id);
            var parent = try self.task(a, task_id);
            defer parent.deinit();
            var saved = try self.workspaceWork(a, task_id, work_id);
            defer saved.deinit();
            if (saved.value.schedule == .parked) return;
            saved.value.schedule = .parked;
            saved.value.control_revision = try std.math.add(u64, saved.value.control_revision, 1);
            saved.value.event_watermark = try std.math.add(u64, parent.value.event_high, 1);
            try self.store().begin();
            defer self.store().rollback();
            try self.writeWorkspaceWork(&saved.value, .replace);
            _ = try self.workspaceCommit(
                a,
                parent.value,
                null,
                @splat(0),
                work_id,
                .work,
                try self.snapshotRecord(workspace.Work, a, "workspace_work", work_id, task_id),
                null,
            );
        }
        pub fn close(self: *Self, a: std.mem.Allocator) !void {
            if (self.work != null) return error.Busy;
            if (self.placement_job) |job| {
                job.job.deinit();
                self.placement_job = null;
            }
            try self.retire(a);
            try self.program.close();
            self.runnable.deinit(self.allocator);
            self.placement_pending.deinit(self.allocator);
            self.owned.deinit(self.allocator);
            self.checked_workspace_programs.deinit(self.allocator);
            self.checked_workspace_runtimes.deinit(self.allocator);
            if (self.runtime_cache) |*cached| cached.artifact.deinit();
            self.* = undefined;
        }
        pub fn park(self: *Self, a: std.mem.Allocator) !void {
            if (self.work != null) return error.Busy;
            if (self.placement_job) |job| {
                job.job.deinit();
                self.placement_job = null;
            }
            self.placement_pending.clearRetainingCapacity();
            for (self.owned.items) |id| {
                // Host suspension drops volatile ownership, not the child's
                // admitted scheduling intent. Explicit task resume restores
                // eligible children; a controller work.park remains durable.
                if (!try self.hasLocalCustody(a, id, null) and
                    !try self.hasFrozenCustody(a, id, null))
                    continue;
                var decoded = try self.task(a, id);
                defer decoded.deinit();
                var value = decoded.value;
                if (value.terminal() or value.schedule == .parked) continue;
                const previous = value.revision;
                value.revision = try std.math.add(u64, previous, 1);
                value.schedule = .parked;
                try self.store().begin();
                defer self.store().rollback();
                try self.event(&value, .parked, "{}");
                try self.persist(a, value, previous, "task.park", .preserve);
            }
            self.runnable.clearRetainingCapacity();
            self.runnable_cursor = 0;
            try self.retire(a);
        }
    };
}
